/* ========================================================================
   PostFlowX — UI Styles
   Ver Version: v2026.02.01-softglow+roundedQS+inlineTabs (+VFXMappingFullHeight)
   - Quick Settings: rounded + vertical glow bar inside button
   - Inner tabs (Input/Inspector): inline (same row) + equal width
   - VFX Mapping: full-height shot table + inner scroll (fit screen)
   ======================================================================== */

/* ========================================================================
   Netflix Sans Font Family — used globally across PostFlowX UI
   ======================================================================== */
@font-face {
  font-family: 'NetflixSans';
  src: url('../assets/fonts/NetflixSans-Light.otf') format('opentype');
  font-weight: 300;
  font-style: normal;
}

/* ==========================================================================
   PULL PREP — SMART VFX EDITOR 2026.08
   A compact editorial control plane for shot/version/QC/handoff ownership.
   ========================================================================== */
#main-prepmark .pm-ve-ribbon {
  min-height: 52px;
  display: grid;
  grid-template-columns: minmax(230px, .9fr) auto minmax(270px, 1.25fr);
  align-items: stretch;
  gap: 8px;
  margin: 0 8px 6px;
  padding: 6px;
  border: 1px solid #2c2c2c;
  border-left: 3px solid #4a4a4a;
  border-radius: 6px;
  background: linear-gradient(90deg, #111, #171717 48%, #101010);
  box-shadow: 0 7px 20px rgba(0,0,0,.24);
}
#main-prepmark .pm-ve-ribbon[data-tone="warn"] { border-left-color: #e2b656; }
#main-prepmark .pm-ve-ribbon[data-tone="danger"] { border-left-color: #e50914; }
#main-prepmark .pm-ve-ribbon[data-tone="good"] { border-left-color: #46d38f; }
#main-prepmark .pm-ve-identity,
#main-prepmark .pm-ve-priority {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 5px 9px;
}
#main-prepmark .pm-ve-mark {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  display: grid;
  place-items: center;
  border-radius: 5px;
  color: #fff;
  background: linear-gradient(145deg, #f11722, #b80710);
  box-shadow: 0 4px 14px rgba(229,9,20,.26);
  font: 900 10px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: .06em;
}
#main-prepmark .pm-ve-identity div,
#main-prepmark .pm-ve-priority { min-width: 0; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 2px; }
#main-prepmark .pm-ve-identity b { color: #f5f5f1; font-size: 10px; letter-spacing: .12em; }
#main-prepmark .pm-ve-identity small,
#main-prepmark .pm-ve-priority small { color: #737373; font-size: 7px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
#main-prepmark .pm-ve-metrics { display: flex; gap: 4px; align-items: stretch; }
#main-prepmark .pm-ve-metrics button {
  min-width: 59px;
  padding: 4px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  border: 1px solid #303030;
  border-radius: 5px;
  background: #1b1b1b;
  color: #b3b3b3;
  cursor: pointer;
}
#main-prepmark .pm-ve-metrics button:hover { border-color: #e50914; background: #231416; }
#main-prepmark .pm-ve-metrics span { color: #f5f5f1; font-size: 13px; font-weight: 850; line-height: 1; }
#main-prepmark .pm-ve-metrics small { color: #737373; font-size: 7px; font-weight: 750; text-transform: uppercase; }
#main-prepmark .pm-ve-priority {
  border-left: 1px solid #2d2d2d;
  padding-left: 14px;
}
#main-prepmark .pm-ve-priority b {
  max-width: 100%;
  color: #e7e7e4;
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#main-prepmark .pm-ve-shot-control {
  flex: 0 0 auto;
  max-height: 176px;
  overflow: auto;
  border-top: 1px solid #2d2d2d;
  border-bottom: 1px solid #2d2d2d;
  background: #101010;
  color: #d5d5d2;
  scrollbar-width: thin;
}
#main-prepmark .pm-ve-empty {
  min-height: 44px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
  padding: 7px 11px;
  color: #737373;
}
#main-prepmark .pm-ve-empty b { color: #b3b3b3; font-size: 10px; }
#main-prepmark .pm-ve-empty span { font-size: 8px; }
#main-prepmark .pm-ve-empty-action { flex-direction: row; align-items: center; justify-content: space-between; }
#main-prepmark .pm-ve-empty-action div { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
#main-prepmark .pm-ve-empty-action button {
  min-height: 28px;
  padding: 5px 10px;
  border: 1px solid rgba(229,9,20,.62);
  border-radius: 5px;
  background: #e50914;
  color: white;
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}
#main-prepmark .pm-ve-shot-head {
  min-height: 34px;
  display: grid;
  grid-template-columns: minmax(160px, auto) auto minmax(150px, 1fr);
  align-items: center;
  gap: 8px;
  padding: 5px 9px;
  border-bottom: 1px solid #292929;
  background: #151515;
}
#main-prepmark .pm-ve-shot-head > div { min-width: 0; display: flex; flex-direction: column; gap: 1px; }
#main-prepmark .pm-ve-shot-head small { color: #737373; font-size: 7px; font-weight: 800; letter-spacing: .09em; }
#main-prepmark .pm-ve-shot-head b { color: #f5f5f1; font-size: 10px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#main-prepmark .pm-ve-readiness {
  padding: 3px 7px;
  border: 1px solid rgba(70,211,143,.44);
  border-radius: 999px;
  color: #46d38f;
  background: rgba(70,211,143,.08);
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .07em;
  white-space: nowrap;
}
#main-prepmark .pm-ve-readiness.needs-attention { color: #ff747b; border-color: rgba(229,9,20,.52); background: rgba(229,9,20,.1); }
#main-prepmark .pm-ve-issue { min-width: 0; color: #b3b3b3; font-size: 8px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#main-prepmark .pm-ve-fields {
  display: grid;
  grid-template-columns: 1.05fr .66fr .92fr 1fr 1fr;
  gap: 5px;
  padding: 6px 9px 4px;
}
#main-prepmark .pm-ve-fields label,
#main-prepmark .pm-ve-note { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
#main-prepmark .pm-ve-fields label > span,
#main-prepmark .pm-ve-note > span { color: #737373; font-size: 7px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
#main-prepmark .pm-ve-fields input,
#main-prepmark .pm-ve-fields select,
#main-prepmark .pm-ve-note input {
  width: 100%;
  min-width: 0;
  height: 25px;
  padding: 3px 6px;
  border: 1px solid #353535;
  border-radius: 4px;
  background: #1b1b1b;
  color: #e7e7e4;
  font-size: 8px;
  outline: none;
}
#main-prepmark .pm-ve-fields input:focus,
#main-prepmark .pm-ve-fields select:focus,
#main-prepmark .pm-ve-note input:focus { border-color: #e50914; box-shadow: 0 0 0 2px rgba(229,9,20,.13); }
#main-prepmark .pm-ve-check-row {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  align-items: center;
  gap: 5px;
  padding: 2px 9px;
}
#main-prepmark .pm-ve-check-row > span { color: #737373; font-size: 7px; font-weight: 850; letter-spacing: .09em; }
#main-prepmark .pm-ve-check-row > div { display: flex; gap: 4px; min-width: 0; flex-wrap: wrap; }
#main-prepmark .pm-ve-qc,
#main-prepmark .pm-ve-handoff {
  min-height: 20px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border: 1px solid #333;
  border-radius: 4px;
  background: #191919;
  color: #8d8d8d;
  font-size: 7px;
  text-transform: uppercase;
  cursor: pointer;
}
#main-prepmark .pm-ve-qc span,
#main-prepmark .pm-ve-handoff span { width: 10px; text-align: center; font-weight: 900; }
#main-prepmark .pm-ve-qc.is-pass,
#main-prepmark .pm-ve-handoff.is-done { color: #46d38f; border-color: rgba(70,211,143,.38); background: rgba(70,211,143,.07); }
#main-prepmark .pm-ve-qc.is-fail { color: #ff747b; border-color: rgba(229,9,20,.46); background: rgba(229,9,20,.09); }
#main-prepmark .pm-ve-note { padding: 3px 9px 7px; }

#main-prepmark .pm-ve-row {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  margin: 2px 2px 0 0;
  padding: 2px 4px;
  border: 1px solid #383838;
  border-radius: 3px;
  background: #181818;
  color: #b3b3b3;
  font-size: 6px;
  line-height: 1;
  vertical-align: middle;
}
#main-prepmark .pm-ve-row b { color: #f5f5f1; font-size: 7px; }
#main-prepmark .pm-ve-row i { width: 10px; height: 10px; display: grid; place-items: center; border-radius: 50%; background: #e50914; color: #fff; font-style: normal; font-weight: 900; }
#main-prepmark .pm-ve-row-approved,
#main-prepmark .pm-ve-row-final { border-color: rgba(70,211,143,.38); color: #46d38f; }
#main-prepmark .pm-ve-row.needs-attention { border-color: rgba(229,9,20,.42); }

@media (max-width: 1450px) {
  #main-prepmark .pm-ve-ribbon { grid-template-columns: 220px auto minmax(200px, 1fr); }
  #main-prepmark .pm-ve-identity small { display: none; }
  #main-prepmark .pm-ve-fields { grid-template-columns: 1fr .6fr .9fr 1fr; }
  #main-prepmark .pm-ve-fields label:last-child { display: none; }
}
