/* Apply Netflix Sans to all UI text */
html, body, button, input, textarea, select,
.tab, .inner-tab, .btn, .qs-btn,
.kpis, .card, .card-title,
#eventTable, #inspector, #dropZone {
  font-family: 'NetflixSans', -apple-system, BlinkMacSystemFont,
               "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-weight: 400;
}

/* fine-tune weights for sections */
header .t, .card-title, .version-btn { font-weight: 700; }     /* Bold */
.qs-btn, .btn { font-weight: 500; }                           /* Medium */
#eventTable td, #eventTable th { font-weight: 400; }          /* Regular */
.muted, small, .ins-table td { font-weight: 300; }            /* Light */

:root{
  /* ======================================================================
     HAWKINS PROFESSIONAL — token foundation  (@hawkins/variables, Dark theme)
     Authoritative values from NECP: Surface rgb(22,22,22), Foreground
     rgba(255,255,255,.9), Blue500 rgb(33,114,227), radius 4/6/100,
     border-width 1/2/4, DarkShadow flat/low/mid/high. The legacy
     --bg-*/--card/--line*/--txt/--muted/--accent/--radius* tokens are
     REMAPPED onto these, so the whole app shifts to Hawkins through the
     thousands of existing var() references — no per-rule edits needed.
     Per-component flattening lives in the EOF "HAWKINS — OVERRIDE LAYER".
     ====================================================================== */

  /* ---- Hawkins core surfaces / text / borders ---- */
  --hwk-surface:   #161616;              /* Theme.Dark.Surface  rgb(22,22,22) */
  --hwk-surface-2: #1f1f1f;              /* elevated surface */
  --hwk-canvas:    #0e0e0e;              /* app background, below surface */
  --hwk-fg:        rgba(255,255,255,.9); /* Theme.Dark.Foreground */
  --hwk-fg-muted:  rgba(255,255,255,.6);
  --hwk-fg-subtle: rgba(255,255,255,.4);
  --hwk-border:    rgba(255,255,255,.12);
  --hwk-border-2:  rgba(255,255,255,.18);
  --hwk-border-3:  rgba(255,255,255,.28);

  /* ---- Hawkins accent (Blue500) + states ---- */
  --hwk-blue500:   #2172E3;              /* rgb(33,114,227) — single brand accent */
  --hwk-blue400:   #4a8ce8;
  --hwk-blue600:   #1b5fbf;
  --hwk-on-accent: #ffffff;

  /* ---- Hawkins semantic ---- */
  --hwk-green:     #0AA356;              /* positive / success */
  --hwk-red:       #E5484D;              /* negative / error  (Red300) */
  --hwk-yellow:    #E0B341;              /* warning */

  /* ---- Hawkins radius / border-width scale ---- */
  --hwk-radius-0:  4px;                  /* BorderRadius0 */
  --hwk-radius-1:  6px;                  /* BorderRadius1 */
  --hwk-radius-pill: 100px;              /* BorderRadius2 */
  --hwk-bw-0:      1px;
  --hwk-bw-1:      2px;
  --hwk-bw-2:      4px;

  /* ---- Hawkins spacing scale (Dimensions.SpaceX subset) ---- */
  --hwk-space-1:   4px;
  --hwk-space-2:   8px;
  --hwk-space-3:   12px;
  --hwk-space-4:   16px;
  --hwk-space-6:   24px;
  --hwk-space-8:   32px;

  /* ---- Hawkins elevation (DarkShadow flat / low / mid / high) ---- */
  --hwk-shadow-flat: none;
  --hwk-shadow-low:  0 1px 2px rgba(0,0,0,.40);
  --hwk-shadow-mid:  0 4px 12px rgba(0,0,0,.45);
  --hwk-shadow-high: 0 12px 32px rgba(0,0,0,.55);

  /* ---- Hawkins type scale (FontSize0..) / weights (400 / 600) ---- */
  --hwk-fs-0: 10px; --hwk-fs-1: 12px; --hwk-fs-2: 14px;
  --hwk-fs-3: 16px; --hwk-fs-4: 20px;
  --hwk-fw-regular: 400;
  --hwk-fw-bold:    600;
  --hwk-focus-ring: 0 0 0 2px rgba(33,114,227,.55);

  /* ====== Legacy tokens REMAPPED onto Hawkins ====== */
  --bg-0: var(--hwk-canvas);
  --bg-1: var(--hwk-surface);
  --bg-2: var(--hwk-surface-2);
  --card: var(--hwk-surface);
  --line:   var(--hwk-border);
  --line-2: var(--hwk-border-2);
  --line-3: var(--hwk-border-3);
  --txt:   var(--hwk-fg);
  --muted: var(--hwk-fg-muted);
  --accent: var(--hwk-blue500);

  /* Hawkins is flat — NO neon glow. Many legacy glow box-shadows read these
     two vars, so zeroing them collapses the glow automatically. */
  --glow-blur: 0px;
  --glow-strong: 0px;

  /* Hawkins radius mapped onto legacy radius vars (was 14/12/18 rounded) */
  --radius:    var(--hwk-radius-1);   /* 6px */
  --radius-sm: var(--hwk-radius-0);   /* 4px */
  --radius-lg: 8px;

  --font: 'NetflixSans', ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;

  /* QS vertical bar — single Hawkins accent, no glow */
  --qs-bar-w: 3px;
  --qs-bar-gap: 8px;
  --qs-bar-h: 64%;
  --c-bar: var(--hwk-blue500);

  /* header/viewport helpers */
  --header-h: 56px;
  --page-h-gap: 18px;

  /* layout helper (tabs + top padding) — tweak if needed */
  --top-ui-h: 86px;

  /* ==========================================================
     Global DIFF colors — Hawkins semantic ramp
     NEW / EXTENDED / CHANGED / REMOVED
     ========================================================== */
  --diff-new:      var(--hwk-green);
  --diff-extended: var(--hwk-blue400);
  --diff-changed:  var(--hwk-yellow);
  --diff-removed:  var(--hwk-red);
}

