*{ box-sizing:border-box; }

/* ===== Warm black→orange background ===== */
html,body{
  height:100%;
  margin:0;
  font:13px/1.35 var(--font);
  color:var(--txt);
  background:
    radial-gradient(1200px 900px at 115% 110%, #a2471f 0%, #7a3116 28%, #2b1a12 60%, #0b0908 100%) fixed,
    var(--bg-0);
  padding-left:20px;
  padding-right:20px;
}

/* texture overlay — removed broken developer-machine path (/mnt/data/…) */

/* Header */
header{
  display:flex; align-items:center; justify-content:space-between;
  padding:10px 14px;
  background:linear-gradient(to bottom,#14141a,#101014);
  border-bottom:1px solid var(--line-2);
  position:sticky; top:0; z-index:100;
}
.brand{ display:flex; align-items:center; gap:6px; }
.brand img{ width:22px; height:22px; }
.brand .t{ font-weight:700; }
.brand .x{ color:#2172E3; }

/* Bigger brand (About header) */
.brand.brand-lg{ gap:12px; }
.brand.brand-lg img{
  /* User request: make PostFlowX logo fill the highlighted (red) box */
  width:64px;
  height:64px;
  object-fit:contain;
}
.brand.brand-lg .t{ font-size:20px; line-height:1.05; letter-spacing:.2px; }
.brand.brand-lg .alpha-badge{ font-size:12px; padding:3px 10px; margin-left:10px; }

/* ABOUT badge (Alpha) */
.alpha-badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  margin-left:10px;
  padding:4px 12px;
  background: rgba(80, 150, 255, 0.95);
  color:#fff;
  font-weight:900;
  font-size:20px;
  line-height:1;
  letter-spacing:.2px;
  border-radius:2px;
  box-shadow: 0 0 0 1px rgba(255,255,255,.10), 0 6px 18px rgba(0,0,0,.25);
}
header .right{ display:flex; gap:8px; align-items:center; }

.card{
  background: color-mix(in srgb, var(--card) 94%, transparent);
  backdrop-filter: blur(16px);
  border:1px solid var(--line);
  border-radius:var(--radius);
  padding:10px;
  box-shadow:0 3px 14px rgba(0,0,0,.20);
}
.row{ display:grid; gap:6px; }
.r3{ grid-template-columns:minmax(340px,1fr) minmax(380px,1fr); }

/* Tabs (main + inner)
   UX: reduce vertical height to save space (top nav bar)
*/
.tabs{ display:flex; gap:4px; padding:6px 12px 0; }
.tabs-right{ margin-left:auto; display:flex; align-items:center; gap:8px; min-width:0; }

/* ── Resolve connection status pill (top bar) ─────────────────────────────── */
.pfx-resolve-pill {
  display: inline-flex; align-items: center; gap: 6px;
  height: 24px; padding: 0 10px;
  font-size: 11px; font-weight: 600; letter-spacing: .01em;
  white-space: nowrap;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 12px;
  color: rgba(232,232,242,.78);
  cursor: pointer; flex-shrink: 0;
  transition: background .15s, border-color .15s, color .15s;
  font-family: inherit;
}
.pfx-resolve-pill:hover {
  background: rgba(255,255,255,.07);
  border-color: rgba(255,255,255,.22);
  color: #fff;
}
.pfx-resolve-pill:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px rgba(214,163,58,.4);
}
.pfx-resolve-pill-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: rgba(255,255,255,.35);
  box-shadow: 0 0 0 2px rgba(255,255,255,.05);
  transition: background .25s, box-shadow .25s;
  flex-shrink: 0;
}
.pfx-resolve-pill-text {
  min-width: 0; max-width: 220px;
  overflow: hidden; text-overflow: ellipsis;
}

.pfx-resolve-pill--idle .pfx-resolve-pill-dot      { background: rgba(255,255,255,.35); }
.pfx-resolve-pill--checking {
  border-color: rgba(214,163,58,.40);
  color: #2172E3;
}
.pfx-resolve-pill--checking .pfx-resolve-pill-dot  {
  background: #2172E3;
  box-shadow: 0 0 0 2px rgba(214,163,58,.20);
  animation: pfxResolvePillPulse .9s ease-in-out infinite alternate;
}
.pfx-resolve-pill--connected {
  border-color: rgba(10,163,86,.42);
  color: #7be095;
  background: rgba(10,163,86,.08);
}
.pfx-resolve-pill--connected .pfx-resolve-pill-dot {
  background: #4caf50;
  box-shadow: 0 0 0 2px rgba(10,163,86,.22);
}
.pfx-resolve-pill--error {
  border-color: rgba(224,85,85,.45);
  color: #ef8b8b;
  background: rgba(224,85,85,.08);
}
.pfx-resolve-pill--error .pfx-resolve-pill-dot     {
  background: #e05555;
  box-shadow: 0 0 0 2px rgba(224,85,85,.22);
}
@keyframes pfxResolvePillPulse { from { opacity: .55; } to { opacity: 1; } }
.top-pinned-tools{
  display:flex;
  align-items:center;
  gap:6px;
  min-width:0;
  max-width:min(42vw, 560px);
  overflow-x:auto;
  scrollbar-width:none;
  -ms-overflow-style:none;
}
.top-pinned-tools[hidden],
.top-pinned-tools:empty{ display:none !important; }
.top-pinned-tools::-webkit-scrollbar{ display:none; }
.pfx-tool-shortcut{
  position:relative;
  height:28px;
  padding:0 10px;
  border:1px solid rgba(255,255,255,0.14);
  border-radius:12px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0.03)),
    rgba(14,18,30,0.22);
  color:rgba(255,255,255,0.9);
  font-size:11px;
  font-weight:780;
  letter-spacing:.02em;
  display:inline-flex;
  align-items:center;
  gap:7px;
  white-space:nowrap;
  cursor:pointer;
  box-shadow:
    0 10px 18px rgba(0,0,0,0.14),
    0 1px 0 rgba(255,255,255,0.10) inset,
    0 -1px 0 rgba(0,0,0,0.16) inset;
  flex:0 0 auto;
}
.pfx-tool-shortcut:hover{
  border-color:color-mix(in srgb, var(--pfx-tool-shortcut-glow, #90d8ff) 34%, rgba(255,255,255,0.14));
  background:
    linear-gradient(180deg, rgba(255,255,255,0.16), rgba(255,255,255,0.05)),
    rgba(18,24,38,0.28);
}
.pfx-tool-shortcut .bar{
  width:3px;
  height:14px;
  border-radius:999px;
  background:var(--pfx-tool-shortcut-glow, #90d8ff);
  opacity:.32;
  box-shadow:
    0 0 10px color-mix(in srgb, var(--pfx-tool-shortcut-glow, #90d8ff) 52%, transparent),
    0 0 16px color-mix(in srgb, var(--pfx-tool-shortcut-glow, #90d8ff) 18%, transparent);
}
.pfx-tool-shortcut-logo{
  width:14px;
  height:14px;
  min-width:14px;
  min-height:14px;
  object-fit:contain;
  filter: drop-shadow(0 1px 3px rgba(0,0,0,0.24));
}
.pfx-tool-shortcut-label{
  overflow:hidden;
  text-overflow:ellipsis;
}

/* ------------------------------------------------------------
   Top right utility tabs (Tool Box / Fun box)
------------------------------------------------------------- */
.top-aux{ position: relative; display:flex; align-items:center; }
.top-aux-tabs{
  display:flex;
  align-items:center;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.16);
  background: rgba(0,0,0,0.18);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.22);
}
.top-aux-tab{
  height: 28px;
  padding: 0 12px;
  border: 0;
  background: transparent;
  color: rgba(255,255,255,0.88);
  font-size: 12px;
  font-weight: 780;
  letter-spacing: 0.2px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.top-aux-tab + .top-aux-tab{ border-left: 1px solid rgba(255,255,255,0.10); }

.top-aux-tab{
  gap: 7px;
}
.top-aux-tab::before{
  content:"";
  width: 14px;
  height: 14px;
  display:inline-block;
  flex: 0 0 14px;
  background-repeat:no-repeat;
  background-position:center;
  background-size:contain;
  filter: drop-shadow(0 1px 3px rgba(0,0,0,0.28));
  opacity: .96;
}
.top-aux-tab-toolbox::before{ background-image: url("../assets/icon_tool_box_tab.svg"); }
.top-aux-tab-funbox::before{ background-image: url("../assets/icon_fun_box_tab.svg"); }
.top-aux-tab:hover::before,
.top-aux-tab.active::before{ opacity: 1; }
.top-aux-tab:hover{ background: rgba(255,255,255,0.06); }
.top-aux-tab:active{ transform: translateY(1px); }
.top-aux-tab.active{
  background: rgba(130, 210, 255, 0.14);
  color: rgba(255,255,255,0.98);
}

.top-aux-panel{
  position: fixed;
  top: 62px;
  right: 10px;
  width: 260px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.16);
  background: #0e0f13;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: 0 18px 40px rgba(0,0,0,0.38), inset 0 0 0 1px rgba(0,0,0,0.22);
  padding: 10px;
  z-index: 9999;
}
.top-aux.funbox-open .top-aux-panel,
.top-aux-panel.pfx-aux-panel-funbox{ width: min(460px, calc(100vw - 40px)); }
.top-aux-pane{ display:block; }
/* IMPORTANT: allow the HTML `hidden` attribute to actually hide panes.
   (Without this, author styles override the UA default `*[hidden]{display:none}`.) */
.top-aux-pane[hidden]{ display:none !important; }
.top-aux-pane-title{
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.3px;
  opacity: 0.9;
