/* ------------------------------------------------------------
   Sprint A.2: Global Project Bar
   Hidden on tabs that manage their own data independently.
------------------------------------------------------------- */


.project-bar{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:6px;
  padding:8px 10px;
  margin:8px 10px 0 10px;
  border-radius:12px;
  background:rgba(255,255,255,0.05);
  border:1px solid rgba(255,255,255,0.08);
  backdrop-filter: blur(6px);
}
.project-left{
  display:flex;
  align-items:center;
  gap:8px;
  min-width: 360px;
  flex: 1;
}
.project-label{
  font-size:12px;
  opacity:.75;
}
.project-select{
  height:34px;
  padding:0 10px;
  border-radius:10px;
  background:rgba(0,0,0,.25);
  border:1px solid rgba(255,255,255,.12);
  color:inherit;
  outline:none;
  max-width: 220px;
}
.project-name{
  height:34px;
  padding:0 12px;
  border-radius:10px;
  width:100%;
  background:rgba(0,0,0,.18);
  border:1px solid rgba(255,255,255,.12);
  color:inherit;
  outline:none;
}
.project-actions{
  display:flex;
  align-items:center;
  gap:8px;
}
.project-dirty{
  width:10px;
  height:10px;
  border-radius:50%;
  background:rgba(255,255,255,.18);
  box-shadow:0 0 0 2px rgba(0,0,0,.25) inset;
  opacity:0;
}
.project-dirty.on{ opacity:1; }

/* ------------------------------------------------------------
   Sprint F (Offline Enterprise): Lock pill + Read-only banner
------------------------------------------------------------- */
.mps-ent-pill{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:6px 10px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,0.16);
  background:rgba(255,255,255,0.06);
  color:rgba(255,255,255,0.92);
  font-size:12px;
  line-height:1;
  white-space:nowrap;
  user-select:none;
}
.mps-ent-pill.is-write{ border-color: rgba(0,255,153,0.35); background: rgba(0,255,153,0.10); }
.mps-ent-pill.is-readonly{ border-color: rgba(255,77,77,0.35); background: rgba(255,77,77,0.10); }
.mps-ent-pill.is-off{ opacity:0.65; }

.mps-ent-ttl{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  padding:2px 7px;
  border-radius:999px;
  font-size:11px;
  border:1px solid rgba(255,255,255,0.16);
  background:rgba(0,0,0,0.18);
  color:rgba(255,255,255,0.88);
}
.mps-ent-pill.is-readonly .mps-ent-ttl{
  border-color: rgba(255,77,77,0.45);
  background: rgba(255,77,77,0.16);
  color: rgba(255,220,220,0.95);
}

/* Soft-disable visuals for write-actions in read-only */
.mps-ro-disabled{
  opacity:0.45 !important;
  filter:saturate(0.55);
}
.mps-ro-disabled .bar{ opacity:0 !important; }
.mps-ro-disabled:active{ transform:none !important; }

/* Lock conflict overlay */
.mps-lock-overlay{
  position:fixed;
  inset:0;
  z-index:10000;
  display:flex;
  align-items:center;
  justify-content:center;
  background:rgba(0,0,0,0.62);
}
.mps-lock-card{
  width: 560px;
  max-width: 92vw;
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(20,20,26,0.96);
  box-shadow: 0 16px 55px rgba(0,0,0,0.45);
  padding: 14px 14px 12px;
  color: rgba(255,255,255,0.92);
}
.mps-lock-title{ font-size: 16px; font-weight: 800; margin-bottom: 6px; }
.mps-lock-sub{ font-size: 12px; opacity: 0.9; margin-bottom: 4px; }
.mps-lock-meta{ font-size: 12px; opacity: 0.75; margin-bottom: 10px; }
.mps-lock-ttl{ font-size: 12px; opacity: 0.85; margin-bottom: 10px; }
.mps-lock-reason{ margin: 8px 0 6px; }
.mps-lock-reason-input{
  width:100%;
  height:34px;
  border-radius:10px;
  border:1px solid rgba(255,255,255,0.16);
  background:rgba(0,0,0,0.25);
  color:inherit;
  padding:0 10px;
}
.mps-lock-warn{ font-size:12px; color: rgba(255,160,160,0.95); min-height: 18px; margin: 4px 0 8px; }
.mps-lock-btnrow{
  display:flex;
  gap:6px;
  justify-content:flex-end;
  margin-top: 6px;
  flex-wrap: wrap;
}

body.mps-readonly .mps-ent-pill{ box-shadow: 0 0 0 1px rgba(255,77,77,0.18) inset; }

/* Read-only badge (doesn't disable UI; JS guards handle enforcement) */
body.mps-readonly::after{
  content: 'READ-ONLY';
  position: fixed;
  top: 10px;
  right: 12px;
  z-index: 9998;
  padding: 6px 10px;
  font-size: 11px;
  letter-spacing: 0.08em;
  border-radius: 999px;
  border: 1px solid rgba(255,120,120,0.55);
  background: rgba(120,30,30,0.35);
  color: rgba(255,210,210,0.95);
  pointer-events: none;
}

/* ------------------------------------------------------------
   Sprint A/B: Use Global Project Bar only (hide legacy per-tab project UI)
------------------------------------------------------------- */
#main-cutdiff .cutdiff-projectbar{ display:none !important; }

/* Shot Marker: hide legacy project controls inside timeline panel (keep sensitivity + cut tools) */
#smTimelineCard .sm-ref2-pro-left,
#smTimelineCard .sm-ref2-pro-mid,
#smTimelineCard .sm-ref2-pro-left2,
#smTimelineCard .sm-ref2-pro-load-left{
  display:none !important;
}

/* When legacy SM project UI is hidden, let remaining controls align nicely */
#smTimelineCard .sm-ref2-pro-row1,
#smTimelineCard .sm-ref2-pro-row2{ justify-content: space-between; }
#smTimelineCard .sm-ref2-pro-load2{ justify-content: flex-end; }
.tab,.inner-tab{
  border:1px solid var(--line-2);
  background:#16171d;
  padding:6px 10px;
  font-size:12px;
  line-height:1.15;
  cursor:pointer;
  user-select:none;
  color:var(--txt);
  position:relative;
  border-radius:4px;
  transition:background .15s,border-color .15s;
}
.tab.active,.inner-tab.active{ background:#1b1c23; border-color:var(--line-3); }

/* underline glow for tabs + buttons */
.tab .bar,.inner-tab .bar,.btn .bar{
  position:absolute; left:0; right:0; bottom:-2px; height:3px;
  border-radius:0;
  background:var(--c-bar, rgba(255,255,255,.45));
  opacity:.25; pointer-events:none;
  box-shadow:0 0 calc(var(--glow-blur)*.75) rgba(255,255,255,.08);
}
.tab.active .bar,.inner-tab.active .bar,.btn.active .bar{
  opacity:1;
  box-shadow:
    0 0 var(--glow-blur) color-mix(in srgb,var(--c-bar,#fff) 85%,transparent),
    0 0 var(--glow-strong) color-mix(in srgb,var(--c-bar,#fff) 70%,transparent);
}

/* -----------------------------
   Buttons (shared)
--------------------------------*/
.btn,.qs-btn{
  display:inline-flex; align-items:center; justify-content:center;
  gap:6px;
  padding:10px 14px;
  border:1px solid var(--line-2);
  background:#16171d;
  color:var(--txt);
  cursor:pointer;
  border-radius:6px;
  line-height:1.2;
  position:relative;
  min-height:36px;
  transition:all .18s ease-in-out;
}

/* Icon-only buttons (used for Project folder picker gear) */
.btn.icon-only{
  width:38px;
  min-width:38px;
  padding:0;
  gap:0;
}
.btn.icon-only .ico{
  width:18px;
  height:18px;
  fill:none;
  stroke:rgba(255,255,255,0.85);
  stroke-width:1.8;
  stroke-linecap:round;
  stroke-linejoin:round;
}

.btn.icon-only .ico-img{
  width:18px;
  height:18px;
  opacity:0.9;
}
.btn.icon-only.needs-setup::after{
  content:"";
  position:absolute;
  top:7px;
  right:7px;
  width:7px;
  height:7px;
  border-radius:50%;
  background:rgba(255,184,74,0.95);
  box-shadow:0 0 0 2px rgba(0,0,0,0.35), 0 0 12px rgba(255,184,74,0.55);
}
.btn:hover,.qs-btn:hover{
  background:#1a1b22;
  border-color:var(--line-3);
  transform:translateY(-1px);
  box-shadow:0 4px 10px rgba(0,0,0,.20);
}
.btn.active,.qs-btn.active{
  background:#1b1c23;
  border-color:var(--line-3);
  box-shadow:0 0 10px color-mix(in srgb,var(--c-bar,#fff) 40%,transparent);
}

/* Drop zone */
#dropZone{
  border:1px dashed var(--line-2);
  border-radius:6px;
  padding:16px;
  text-align:center;
  background:#12131a;
  color:var(--txt);
}
#dropZone.drag{ outline:1px solid color-mix(in srgb,#74b0c9 45%,transparent); }

/* -----------------------------
   Inline inner tabs (Input / Inspector)
--------------------------------*/
.inner-tabs.inline{
  display:flex; flex-direction:row; align-items:center; gap:6px;
  margin-bottom:10px;
}
.inner-tabs.inline .inner-tab{
  flex:1;
  text-align:center;
  border-radius:6px;
  padding:10px 12px;
  margin:0 4px;
}

/* -----------------------------
   Quick Settings
--------------------------------*/
#qsRow{
  display:grid;
  grid-template-columns:repeat(6,minmax(0,1fr));
  gap:4px 4px;
  align-items:stretch;
  margin-top:14px;
}
/* Compact sizing for QS buttons so 7 columns fit cleanly */
#qsRow .qs-btn{
  padding: 7px 8px;
  padding-left: calc(8px + var(--qs-bar-w) + var(--qs-bar-gap));
  min-height: 30px;
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#qsRow .qs-ico{ width: 11px; height: 11px; flex-shrink: 0; }

/* vertical glow bar inside QS button */
.qs-btn{ padding-left:calc(12px + var(--qs-bar-w) + var(--qs-bar-gap)); }
.qs-btn .bar{
  position:absolute; left:8px; top:50%; transform:translateY(-50%);
  pointer-events:none;
  width:var(--qs-bar-w); height:var(--qs-bar-h);
  border-radius:999px;
  background:var(--c-bar,rgba(255,255,255,.45));
  opacity:.25; pointer-events:none;
  box-shadow:0 0 calc(var(--glow-blur)*.6) color-mix(in srgb,var(--c-bar,#fff) 25%,transparent);
}
.qs-btn.active .bar{
  opacity:1;
  box-shadow:
    0 0 var(--glow-blur) color-mix(in srgb,var(--c-bar,#fff) 85%,transparent),
    0 0 var(--glow-strong) color-mix(in srgb,var(--c-bar,#fff) 70%,transparent);
}
.qs-btn:not(.active):hover .bar{
  opacity:.9; animation:qsBarPulseV 1.2s ease-in-out infinite;
}
@keyframes qsBarPulseV{
  0%{opacity:.3;}
  50%{opacity:1; box-shadow:0 0 var(--glow-blur) color-mix(in srgb,var(--c-bar,#fff) 60%,transparent);}
  100%{opacity:.3;}
}

/* wider button for handles */
#qsRow .qs-btn[data-key="extra"]{ grid-column: auto; }

/* qs-btn icon */
.qs-ico {
  display: inline-block;
  width: 13px;
  height: 13px;
  vertical-align: middle;
  margin-right: 4px;
  flex-shrink: 0;
  opacity: 0.75;
  transition: opacity .15s;
}
.qs-btn.active .qs-ico,
.qs-btn:hover .qs-ico { opacity: 1; }
.qs-btn { display: flex; align-items: center; justify-content: center; }

/* KPI label with inline icon */
.edl-kpi-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  justify-content: center;
}
.edl-kpi-label svg { flex-shrink: 0; opacity: 0.85; }

/* Misc */
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;text-align:center;}
@media (max-width: 980px){.kpis{grid-template-columns:repeat(2,1fr);}}
.k .v{font-weight:700;font-size:18px;}

/* Cut Diff summary KPI: prevent overflow on narrower windows */
#cutdiffSummaryKpi.kpis{
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  width:100%;
  max-width:100%;
}

/* Timeline Summary KPI mini-cards (Events / Unique Reels / FPS) */
#timelineCard .kpis .k{
  background:linear-gradient(180deg,rgba(255,255,255,.075),rgba(255,255,255,.035));
  border:1px solid rgba(255,255,255,.16);
  border-radius:14px;
  padding:10px 10px;
  min-height:56px;
  display:flex;
  flex-direction:column;
  align-items:center;
