/* ------------------------------------------------------------------
   ✨ EDL Comments — 2 COLUMN layout
------------------------------------------------------------------- */
.edl-compact{
  display:grid;
  grid-template-columns: 140px 1fr 140px 1fr;   /* (label,value) × 2 columns */
  grid-auto-rows: auto;
  grid-auto-flow: row dense;
  row-gap:6px;
  column-gap:6px;
  padding:10px 12px;
  background: rgba(255,255,255,.04);
  border: 0;
  border-radius: 14px;
  font-size:11px;
}

/* ให้แต่ละ item เป็นกลุ่ม label+value แต่เราจะจัดตำแหน่งด้วย nth-of-type */
.edl-compact .item{ display:contents; }

.edl-compact .lbl{
  display:inline-flex;
  align-items:center;
  gap:6px;
  min-width:0;
  font-weight:600;
  color: var(--pfx-text-primary, rgba(255,255,255,0.88));
  opacity:.9;
  align-self:center;
}
.edl-compact .lbl .lbl-ic{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:13px;
  height:13px;
  flex:0 0 13px;
  opacity:.96;
}
.edl-compact .lbl .lbl-ic svg{
  display:block;
  width:100%;
  height:100%;
  stroke:currentColor;
  fill:none;
  stroke-width:1.75;
  stroke-linecap:round;
  stroke-linejoin:round;
}
.edl-compact .lbl .lbl-txt{
  min-width:0;
}
.edl-compact .lbl-speed .lbl-ic{ color:rgba(255,197,92,.96); }
.edl-compact .lbl-handles .lbl-ic{ color:rgba(255,255,255,.86); }
.edl-compact .lbl-locator .lbl-ic{ color:rgba(111,228,255,.96); }
.edl-compact .lbl-transform .lbl-ic{ color:rgba(193,150,255,.96); }
.edl-compact .val{
  color:var(--txt);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

/* วางคู่ที่ 1,3,5… ไว้ฝั่งซ้าย / 2,4,6… ฝั่งขวา */
.edl-compact .item:nth-of-type(odd) .lbl { grid-column:1; }
.edl-compact .item:nth-of-type(odd) .val { grid-column:2; }

.edl-compact .item:nth-of-type(even) .lbl { grid-column:3; }
.edl-compact .item:nth-of-type(even) .val { grid-column:4; }

/* ตัดเส้น dashed เดิมออก (ไม่จำเป็นแล้ว) */
.edl-compact .lbl::after{ content:none; }

/* Locator field styling */
#edlLocator{
