  border-radius: 8px;
  outline:none;
  border:1px solid transparent;
}
#edlLocator:focus{
  border-color: rgba(255,255,255,.22);
  box-shadow: 0 0 0 4px rgba(255,255,255,.05);
}

/* ------------------------------------------------------------------
   ✨ Event Table — fixed layout with checkbox column
------------------------------------------------------------------- */
#eventTable{
  --row-h: 22px;

  /* column widths (auto-fit will update these variables in real time) */
  --col-check:   32px;  /* checkbox */
  --col-num:     58px;  /* Event # (001) */
  --col-reel:   260px;  /* Reel */
  --col-clip:   320px;  /* Clip Name */
  --col-cam:    130px;  /* Cam */
  --col-storage:156px;  /* Storage (Est.) */
  --col-adv:    150px;  /* Advanced FDL */
  --col-handles:120px;  /* Handles */
  --col-srcin:  132px;  /* Src In */
  --col-srcout: 132px;  /* Src Out */
  --col-recin:  132px;  /* Rec In */
  --col-recout: 132px;  /* Rec Out */
  --col-loc:    260px;  /* LOC */

  border-radius: 0;

  /*
     IMPORTANT (Scroll to last row):
     #eventCard is a flex-column container and #eventTable is its flex child.
     If #eventTable remains a normal block element, its inner scroller
     (#eventScroll) can size-to-content and then get clipped by the card,
     which makes it impossible to reach the last rows.
     Make #eventTable a flex column so .evt-shell/#eventScroll can properly
     stretch and scroll within the available height.
  */
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1 1 auto;
  height: auto;
  min-height: 0;
  overflow: visible; /* allow absolutely-positioned children (e.g. #evtFindBar) to escape */

  /* single outer chrome (avoid double borders when we split header/body tables) */
  background: rgba(0,0,0,.08);
  border: 0;
}

.evt-shell{
  flex:1 1 auto;
  min-height:0;
  width:100%;
  display:flex;
  flex-direction:column;
}

/* Scroll container (body) — Event Table */
#eventScroll{
  /* IMPORTANT: allow the scroller to shrink inside flex layouts */
  flex: 1 1 auto;
  min-height: 0;

  overflow: auto;
  -webkit-overflow-scrolling: touch;

  /* Reserve space so overlay scrollbars never cover content */
  padding-right: 18px;
  padding-bottom: 24px;

  /* Hide native scrollbars (we draw always-visible overlay scrollbars) */
  scrollbar-width: none; /* Firefox */
  scrollbar-gutter: auto;
}
#eventScroll::-webkit-scrollbar{
  width: 0;
  height: 0;
}

/* Event Table overlay scrollbars (EDL Converter)
   JS: scripts/event_table_vertscroll.js + scripts/event_table_topscroll.js
   Want: always visible (vis-timeline style).
*/
#eventTable{ position: relative; }

.mps-et-vscroll,
.mps-et-hscroll{
  display: block;
}

.mps-et-vscroll{
  /* Match CUT DIFF overlay scrollbar look/placement */
  position:absolute;
  top:0;
  right:0;
  width:12px;
  height:100%;
  background: rgba(0,0,0,0.22);
  border-left: 1px solid rgba(255,255,255,0.08);
  border-top-right-radius: 14px;
  border-bottom-right-radius: 14px;
  pointer-events: auto;
  z-index: 5;
}
.mps-et-vscroll-thumb{
  position:absolute;
  left:2px;
  width:8px;
  top:0;
  height:40px;
  border-radius: 8px;
  background: rgba(255,255,255,0.22);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.55);
  cursor: grab;
}
.mps-et-vscroll-thumb:active{
  cursor: grabbing;
  background: rgba(255,255,255,0.30);
}


.mps-et-hscroll{
  position:absolute;
  left:0;
  bottom:0;
  height:12px;
  width:100%;
  background: rgba(0,0,0,0.22);
  border-top: 1px solid rgba(255,255,255,0.08);
  border-bottom-left-radius: 14px;
  border-bottom-right-radius: 14px;
  pointer-events: auto;
  z-index: 5;
}
.mps-et-hscroll-thumb{
  position:absolute;
  top:2px;
  height:8px;
  left:0;
  width:40px;
  border-radius: 8px;
  background: rgba(255,255,255,0.22);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.55);
  cursor: grab;
}
.mps-et-hscroll-thumb:active{
  cursor: grabbing;
  background: rgba(255,255,255,0.30);
}


