/* smaller text in table */
#eventTable table,
#eventTable thead th,
#eventTable tbody td{
  font-size:10px;
  color:#ffffff;
}

/* table skeleton */
#eventTable table{
  width:max-content;
  min-width:100%;
  table-layout:fixed;
  border-collapse:separate;
  border-spacing:0;
  background:transparent;
  border:none;
  border-radius:0;
  overflow:visible;
}

/* header row (sticky) */
#eventTable thead{ display:table-header-group; }
#eventTable thead th{
  position:sticky;
  top:0;
  z-index:10;

  /* Frosted-glass header (Netflix-style) */
  background:
    linear-gradient(180deg, rgba(255,255,255,.10), rgba(255,255,255,.03)),
    rgba(18,18,22,.55);
  backdrop-filter: blur(22px) saturate(170%);
  -webkit-backdrop-filter: blur(22px) saturate(170%);

  border-bottom:1px solid rgba(255,255,255,.16);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.06);

  padding:4px 8px;
  font-weight:700;
  color:#fafafa;
  text-align:left;
  white-space:nowrap;
}

/* subtle column dividers in header */
#eventTable thead th:not(:last-child){
  border-right:1px solid rgba(255,255,255,.06);
}

/* header mini toggles (Only / inv) */
#eventTable thead th .th-main{
  display:flex;
  align-items:center;
  gap:6px;
}
#eventTable thead th .th-only{
  margin-top:2px;
  display:flex;
  align-items:center;
  gap:4px;
  font-size:9px;
  font-weight:600;
  opacity:.85;
}
#eventTable thead th .th-only label{
  display:inline-flex;
  align-items:center;
  gap:6px;
  cursor:pointer;
  user-select:none;
}
#eventTable thead th .th-only input[type="checkbox"]{
  width:12px;
  height:12px;
  cursor:pointer;
  accent-color: rgba(130, 90, 255, 0.95);
}
#eventTable thead th .th-only .inv-toggle span{
  opacity:.80;
}

/* body scroll zone + gap top/bottom */
#eventTable tbody{
  display:table-row-group;
}
#eventTable tbody tr{ display:table-row; }

/* rows */
#eventTable tbody td{
  padding:2px 8px;
  height:var(--row-h);
  line-height:1.25;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  border-bottom:1px solid var(--line);
}

/* === column widths (12 columns) === */

/* 1) checkbox column */
#eventTable thead th:nth-child(1),
#eventTable tbody td:nth-child(1){
  width:var(--col-check);
  text-align:center;
  padding-left:8px;
  padding-right:4px;
}

/* 2) Event # column */
#eventTable thead th:nth-child(2),
#eventTable tbody td:nth-child(2){
  width:var(--col-num);
  text-align:right;
  padding-right:8px;
  font-family:var(--font-mono);
}

/* 3) Reel */
#eventTable thead th:nth-child(3),
#eventTable tbody td:nth-child(3){
  width:var(--col-reel);
}

/* 4) Clip Name */
#eventTable thead th:nth-child(4),
#eventTable tbody td:nth-child(4){
  width:var(--col-clip);
}

/* Reel / Clip Name: allow long names to wrap up to 3 lines */
#eventTable tbody td:nth-child(3),
#eventTable tbody td:nth-child(4){
  white-space:normal;
  vertical-align:top;
}
#eventTable tbody td:nth-child(3) > .evt-wrap3,
#eventTable tbody td:nth-child(4) > .evt-wrap3{
  display:-webkit-box;
  -webkit-box-orient:vertical;
  -webkit-line-clamp:3;
  line-clamp:3;
  overflow:hidden;
  max-width:100%;
  white-space:normal;
  overflow-wrap:anywhere;
  word-break:break-word;
  line-height:1.18;
}

/* 5) Cam */
#eventTable thead th:nth-child(5),
#eventTable tbody td:nth-child(5){
  width:var(--col-cam);
}

/* 6) Storage (Est.) */
#eventTable thead th:nth-child(6),
#eventTable tbody td:nth-child(6){
  width:var(--col-storage);
}

/* 7) Advanced FDL */
#eventTable thead th:nth-child(7),
#eventTable tbody td:nth-child(7){
  width:var(--col-adv);
}

/* 8) Handles */
#eventTable thead th:nth-child(8),
#eventTable tbody td:nth-child(8){
  width:var(--col-handles);
  font-family:var(--font-mono);
}

/* 9–12) timecode columns */
#eventTable thead th:nth-child(9),
#eventTable tbody td:nth-child(9),
#eventTable thead th:nth-child(10),
#eventTable tbody td:nth-child(10),
#eventTable thead th:nth-child(11),
#eventTable tbody td:nth-child(11),
#eventTable thead th:nth-child(12),
#eventTable tbody td:nth-child(12){
  width:var(--col-srcin); /* default; JS auto-fit will override per-var below */
  font-family:var(--font-mono);
  letter-spacing:.2px;
}

/* Map per timecode var */
#eventTable thead th:nth-child(9),
#eventTable tbody td:nth-child(9){ width:var(--col-srcin); }
#eventTable thead th:nth-child(10),
#eventTable tbody td:nth-child(10){ width:var(--col-srcout); }
#eventTable thead th:nth-child(11),
#eventTable tbody td:nth-child(11){ width:var(--col-recin); }
#eventTable thead th:nth-child(12),
#eventTable tbody td:nth-child(12){ width:var(--col-recout); }

/* 13) LOC */
#eventTable thead th:nth-child(13),
#eventTable tbody td:nth-child(13){
  width:var(--col-loc);
  font-family:var(--font-mono);
}


/* ------------------------------------------------------------------
   🧊 Pinned / Frozen left columns (NLE-style)
   Checkbox + Event + Reel + Clip Name + Cam
------------------------------------------------------------------- */

/* left offsets are derived from the same CSS width variables that
   power column auto-fit / manual resizing */
#eventTable{
  --evt-pin-left-1: 0px;
  --evt-pin-left-2: var(--col-check);
  --evt-pin-left-3: calc(var(--col-check) + var(--col-num));
  --evt-pin-left-4: calc(var(--col-check) + var(--col-num) + var(--col-reel));
  --evt-pin-left-5: calc(var(--col-check) + var(--col-num) + var(--col-reel) + var(--col-clip));
}

/* make the first 5 columns sticky on the left */
#eventTable thead th:nth-child(-n+5),
#eventTable tbody td:nth-child(-n+5){
  position: sticky;
}

/* explicit left positions per column */
#eventTable thead th:nth-child(1),
#eventTable tbody td:nth-child(1){ left: var(--evt-pin-left-1); }

#eventTable thead th:nth-child(2),
#eventTable tbody td:nth-child(2){ left: var(--evt-pin-left-2); }

#eventTable thead th:nth-child(3),
#eventTable tbody td:nth-child(3){ left: var(--evt-pin-left-3); }

#eventTable thead th:nth-child(4),
#eventTable tbody td:nth-child(4){ left: var(--evt-pin-left-4); }

#eventTable thead th:nth-child(5),
#eventTable tbody td:nth-child(5){ left: var(--evt-pin-left-5); }

/* stacking order */
#eventTable thead th:nth-child(-n+5){
  z-index: 30; /* above normal header cells (z=10) */
}
#eventTable tbody td:nth-child(-n+5){
  z-index: 6;  /* above scrolled columns */
  backdrop-filter: blur(10px) saturate(160%);
  -webkit-backdrop-filter: blur(10px) saturate(160%);
}

/* Backgrounds for pinned cells so text doesn't overlap with scrolled columns */
#eventTable tbody tr:nth-child(odd)  td:nth-child(-n+5){ background: rgba(0,0,0,.10); }
#eventTable tbody tr:nth-child(even) td:nth-child(-n+5){ background: rgba(255,255,255,.02); }
#eventTable tbody tr:hover           td:nth-child(-n+5){ background: rgba(255,255,255,.05); }
#eventTable tbody tr.sel             td:nth-child(-n+5){
  background:
    linear-gradient(180deg, rgba(120,210,255,0.22), rgba(120,210,255,0.12));
}

/* Visual divider/shadow at the edge of the frozen area */
#eventTable thead th:nth-child(5){
  box-shadow:
    inset -1px 0 0 rgba(255,255,255,.08),
    10px 0 14px rgba(0,0,0,.35);
}
#eventTable tbody td:nth-child(5){
  box-shadow:
    inset -1px 0 0 rgba(255,255,255,.06),
    10px 0 14px rgba(0,0,0,.18);
}


/* first data col (index) color */
#eventTable tbody td:nth-child(2){
  color:#d7d7d7;
  font-family:var(--font-mono);
}

/* zebra + hover + selected */
#eventTable tbody tr:nth-child(even){ background:rgba(255,255,255,.02); }
#eventTable tbody tr:hover{ background:rgba(255,255,255,.05); }
#eventTable tbody tr.sel{
  /* Glasses / focus line (light cyan with darker edge) */
  background:
    linear-gradient(180deg, rgba(120,210,255,0.22), rgba(120,210,255,0.12));
  outline:none;
  border: 1px solid rgba(120,210,255,0.58);
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,0.08),
    0 10px 18px rgba(0,0,0,0.18);
  backdrop-filter: blur(10px) saturate(160%);
  -webkit-backdrop-filter: blur(10px) saturate(160%);
}

#eventScroll:focus{
  outline:1px solid rgba(176,108,255,.45);
  outline-offset:2px;
  box-shadow:0 0 0 2px rgba(176,108,255,.18);
  border-radius:12px;
}
#eventTable tbody tr:focus{
  outline:2px solid rgba(176,108,255,.75);
  outline-offset:-2px;
}
#eventTable tbody tr.sel:focus{
  outline:2px solid rgba(120,210,255,0.95);
}

/* (native scrollbars hidden; overlay scrollbars are styled below) */

/* Column resizer handle
   NOTE: do NOT override sticky header positioning.
   'position: sticky' is still a positioned element, so the handle can be absolutely positioned.
*/
#eventTable thead th.resizable {
  position: sticky;
  top: 0;
}
#eventTable thead th .resize-handle{
  position:absolute;
  top:0;
  right:0;
  width:6px;
  height:100%;
  cursor:col-resize;
  background:transparent;
}
#eventTable thead th .resize-handle::before{
  content:"";
  position:absolute;
  inset:0;
  margin:auto;
  width:2px;
  background:rgba(255,255,255,.18);
  border-radius:2px;
  opacity:.6;
}
#eventTable thead th .resize-handle:hover::before{
  opacity:1;
}

/* ------------------------------------------------------------------
   ปรับปุ่ม Browse / Clear ให้สมดุล
------------------------------------------------------------------- */
#btnBrowseFiles,
#btnClear {
  flex: 1 1 160px;
  min-width: 150px;
  max-width: 180px;
  justify-content: center;
  text-align: center;
}
#btnBrowseFiles::before,
#btnClear::before {
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
}
#dropZone .btn {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: center;
}
#dropZone > div[style*="display:flex"] {
  display: flex;
  justify-content: center;
  gap: 8px;
}

/* ------------------------------------------------------------------
   ⚫ All OFF — fade when off
------------------------------------------------------------------- */
#qsAllOff:not(.active) {
  color: var(--muted) !important;
  opacity: 0.7 !important;
  filter: grayscale(60%) !important;
  background: #1a1a1d;
  box-shadow: none;
  border-color: var(--line-2);
}
#qsAllOff:not(.active)::before {
  background: linear-gradient(180deg, #666, #444);
  box-shadow: 0 0 6px rgba(120,120,120,.3);
  opacity: 0.6;
}

/* ===== margin ล่างของ UI ทั้งหมด ===== */
/* ===== Fixed Top Cluster + Scrollable Event Table ===== */
html, body { height: 100%; }
body{
  overflow:hidden;
  display:flex;
  flex-direction:column;
  padding-bottom: var(--page-h-gap);
}

/* Flex layout: Tabs stay on top; active pane fills remaining height */
.tabs{ flex:0 0 auto; }
.main-pane{ flex:1 1 auto; min-height:0; overflow:hidden; }

/* ABOUT pane: allow vertical scrolling (feedback form is long) */
#main-about.main-pane{ overflow-y:auto; overflow-x:hidden; }
#main-about{
  padding-bottom: 18px;
  /* Force ABOUT content to start under Project bar on the LEFT (not right-floating) */
  display: flex;
  flex-direction: column;
  align-items: stretch;
  /* Always center the shell so left/right margins match on every tab */
  justify-content: center;
}


/* ตัว container หลักของหน้า EDL */
#main-edl{
  display:grid;
  /* rows: top cluster / timeline / divider / event table */
  grid-template-rows: auto auto auto minmax(0, 1fr);
  gap: 14px;
  height: 100%;
  overflow:hidden;
}

/* Keep the top cluster always pinned to grid row 1 (swap only affects the panes below). */
#main-edl > .row.r3{ grid-row: 1; }

/*
  IMPORTANT (Swap stability)
  When swapped, the Event Table must still live in a *flex* (minmax/1fr) track.
  Otherwise it loses a definite height, its internal scroller stops working,
  and the whole page can start scrolling (making the top cards look “gone”).
*/
#main-edl.edl-panes-swapped{
  /* rows: top cluster / event table (flex) / divider / timeline (auto) */
  grid-template-rows: auto minmax(0, 1fr) auto auto;
}

/* EDL Convert — allow swapping Timeline ↕ Event Table (layout order) */
#main-edl.edl-panes-swapped #eventCard{ grid-row: 2; }
#main-edl.edl-panes-swapped #edlPaneDivider{ grid-row: 3; }
#main-edl.edl-panes-swapped #edlTimelineCard{ grid-row: 4; }

/* EDL Convert — lock layout (disable swap / resize / hide) */
#main-edl.edl-layout-locked .edl-pane-divider{
  opacity: .45;
  cursor: default;
  pointer-events: none;
}
#main-edl.edl-layout-locked #edlToggleTimeline,
#main-edl.edl-layout-locked #edlToggleTimeline2,
#main-edl.edl-layout-locked #edlToggleEventTable,
#main-edl.edl-layout-locked #edlToggleEventTable2,
#main-edl.edl-layout-locked #edlSwapPanes,
#main-edl.edl-layout-locked #edlSwapPanes2{
  opacity: .45;
  pointer-events: none;
}

/* EDL Convert — collapsible Timeline / Event Table */
#main-edl.edl-hide-timeline #edlTimelineCard{ display:none !important; }

#main-edl.edl-hide-timeline #edlPaneDivider{ display:none !important; }

#main-edl.edl-hide-event #eventCard{ display:none !important; }

#main-edl.edl-hide-event #edlPaneDivider{ display:none !important; }

/* When Timeline is hidden, let the Event Table take the remaining height */
#main-edl.edl-hide-timeline #eventCard{
  grid-row: 2 / -1;
  height: 100%;
  min-height: 0;
}
/* When Event Table is hidden, let the Timeline take the remaining height */
#main-edl.edl-hide-event #edlTimelineCard{
  grid-row: 2 / -1;
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
#main-edl.edl-hide-event #edlTimeline{ flex: 1 1 auto; min-height: 0; }
#main-edl.edl-hide-event #edlTlViewport{ height: 100% !important; }

/* --- EDL Timeline ↕ Event Table divider (drag to resize) --- */
.edl-pane-divider{
  height: 12px;
  margin: -10px 8px;
  border-radius: 999px;
  cursor: ns-resize;
  position: relative;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.10);
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,0.04),
    0 8px 18px rgba(0,0,0,0.18);
}
.edl-pane-divider:hover{
  background: rgba(255,255,255,0.07);
  border-color: rgba(255,255,255,0.22);
}
.edl-pane-divider.is-active{
  background: rgba(180,120,255,0.14);
  border-color: rgba(180,120,255,0.55);
  box-shadow:
    inset 0 0 0 1px rgba(180,120,255,0.18),
    0 10px 22px rgba(0,0,0,0.22);
}
.edl-pane-divider:focus{
  outline: 2px solid rgba(120,210,255,0.85);
  outline-offset: 3px;
}
.edl-pane-divider__handle{
  position:absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 64px;
  height: 8px;
  border-radius: 999px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.16);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.22);
}
.edl-pane-divider__handle::before{
  content: "";
  position:absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: rgba(255,255,255,0.85);
  box-shadow:
    -12px 0 0 rgba(255,255,255,0.70),
     12px 0 0 rgba(255,255,255,0.70);
  opacity: 0.92;
}

/* subtle purple guide line while dragging */
.edl-pane-divider.is-active::after{
  content:"";
  position:absolute;
  left: 10px;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  height: 2px;
  border-radius: 999px;
  background: rgba(180,120,255,0.35);
  box-shadow: 0 0 18px rgba(180,120,255,0.16);
  pointer-events:none;
}

/* While dragging the divider, keep the resize cursor everywhere */
.edl-split-resizing, .edl-split-resizing *{
  cursor: ns-resize !important;
  user-select: none !important;
}

.edl-tl-right{
  display:flex;
  align-items:center;
  gap:8px;
  margin-left:auto;
}

/* Override old meta alignment when wrapped in .edl-tl-right */
#edlTimelineCard .edl-tl-right .edl-tl-meta{ margin-left: 0; }

/* Small glassy toggle buttons (reuses existing .btn chrome) */
.btn.tiny{
  padding: 6px 10px;
  font-size: 11px;
  border-radius: 12px;
  line-height: 1;
}

/* EDL: make the small Hide Timeline / Hide Table buttons more compact (red box request) */
#main-edl #edlTimelineCard .edl-tl-right .btn.tiny,
#main-edl #eventCard .evt-card-actions .btn.tiny{
  padding: 4px 8px;
  font-size: 10px;
  border-radius: 10px;
}
#main-edl #edlTimelineCard .edl-tl-right .btn.tiny .bar,
#main-edl #eventCard .evt-card-actions .btn.tiny .bar{
  height: 2px;
  bottom: -2px;
}
.btn.ghost{
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: none;
}
.btn.ghost:hover{
  background: rgba(255,255,255,.08);
}

/* Hide/Show state tint — makes the "Show" button obvious when a section is hidden */
.btn.ghost.is-hidden-state{
  background: rgba(194,103,255,0.18);
  border-color: rgba(194,103,255,0.55);
  box-shadow: 0 0 0 1px rgba(194,103,255,0.12) inset;
}
.btn.ghost.is-hidden-state:hover{
  background: rgba(194,103,255,0.24);
  border-color: rgba(194,103,255,0.70);
}

/* Event Table header (keeps controls visible even when table scrolls) */
.evt-card-head{
  flex: 0 0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:6px;
  padding: 7px 10px;
  border-bottom: 1px solid rgba(255,255,255,.08);
  background: color-mix(in srgb, var(--card) 90%, transparent);
  backdrop-filter: blur(18px);
}
.evt-card-title{
  font-size: 12px;
  letter-spacing: .2px;
  opacity: .85;
}
.evt-card-actions{
  display:flex;
  gap:8px;
  align-items:center;
}

/* Event Table: group expand/collapse tools (VFX Rename / VFX Marker) */
.evt-card-tools{
  flex: 1 1 auto;
  display:flex;
  align-items:center;
  justify-content:flex-start;
  gap:8px;
  margin-left: 8px;
}
.evt-group-btn{
  display:inline-flex;
  align-items:center;
  gap:8px;
  padding: 6px 10px;
  font-size: 11px;
  line-height: 1;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.14);
  background: rgba(255,255,255,.05);
  color: rgba(255,255,255,.92);
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}
.evt-group-btn:hover{
  background: rgba(255,255,255,.08);
  border-color: rgba(255,255,255,.20);
}
.evt-group-btn:active{
  transform: translateY(1px);
}
.evt-group-btn svg{
  width: 14px;
  height: 14px;
  opacity: .95;
}

/* Single smart toggle (Expand All / Collapse All) */
.evt-group-toggle .evt-icon-collapse{ display:none; }
.evt-group-toggle.is-collapse .evt-icon-expand{ display:none; }
.evt-group-toggle.is-collapse .evt-icon-collapse{ display:inline-block; }
.evt-group-toggle.is-disabled{
  opacity: .45;
  cursor: default;
  pointer-events: none;
}
/* Event table card fills the remaining viewport height */
#eventCard{
  /* Rounded corners — top + bottom (whole card incl. blank area + footer) */
  --evt-radius: 14px;

  margin-top: 0;
  padding: 0;
  height: 100%;
  min-height: 0;

  border-radius: var(--evt-radius);
  overflow: hidden; /* IMPORTANT: clip inner scroll/footer to rounded corners */

  /* Own chrome so bottom corners always show even if footer is outside #eventTable */
  background: color-mix(in srgb, var(--card) 94%, transparent);
  border: 1px solid var(--line-2);
  box-shadow: 0 3px 14px rgba(0,0,0,.20);

  display: flex;
  flex-direction: column;
  position: relative;
}

/* Make table area flexible so footer is always visible */
#eventTable{
  --row-h: 22px;

  /* column widths (auto-fit will update these variables in real time) */
  --col-check:   32px;  /* checkbox */
  --col-num:     58px;  /* Event # (001) */
  --col-reel:   260px;  /* Reel */
  --col-clip:   320px;  /* Clip Name */
  --col-cam:    130px;  /* Cam */
  --col-storage:156px;  /* Storage (Est.) */
  --col-adv:    150px;  /* Advanced FDL */
  --col-handles:120px;  /* Handles */
  --col-srcin:  132px;  /* Src In */
  --col-srcout: 132px;  /* Src Out */
  --col-recin:  132px;  /* Rec In */
  --col-recout: 132px;  /* Rec Out */
  --col-loc:    260px;  /* LOC */

  border-radius: 0;

  /* IMPORTANT:
     #eventCard is a flex-column container with its own header.
     If this area is forced to height:100%, the header + table area
     exceed the card height, causing the scroller to be clipped and
     preventing the last rows from being reachable.
  */
  flex: 1 1 auto;
  height: auto;
  min-height: 0;
  overflow: hidden;

  /* single outer chrome (avoid double borders when we split header/body tables) */
  background: rgba(0,0,0,.08);
  border: 0;
}

.evt-footer-host{
  flex: 0 0 auto;
}

/* MPS overlay scrollbars (Event Table) */
.mps-sb{
  position:absolute;
  z-index:50;
  background:rgba(255,255,255,.06);
  border:1px solid rgba(255,255,255,.12);
  border-radius:10px;
  backdrop-filter: blur(16px);
  box-shadow: 0 10px 26px rgba(0,0,0,.45);
  pointer-events:auto;
}
.mps-sb.hidden{ display:none; }
.mps-sb.dragging{ cursor:grabbing; }

.mps-sb-x{
  left:12px;
  right:24px;
  bottom: calc(8px + var(--evt-foot-h, 0px));
  height:10px;
}
.mps-sb-y{
  top:calc(12px + var(--evt-head-h, 0px));
  right:8px;
  bottom: calc(24px + var(--evt-foot-h, 0px));
  width:10px;
}
.mps-sb-thumb{
  position:absolute;
  inset:0;
  background:rgba(176,108,255,.55);
  border-radius:999px;
  box-shadow: 0 0 16px rgba(176,108,255,.35);
}

/* กันเกิด scroll ซ้อนเมื่อย่อหน้าจอ */
@media (max-height: 720px){
  #main-edl{
    height: 100%;
  }
}
/* === Remove top blank header space === */
header {
  display: none !important;
}
body {
  margin-top: 0 !important;
  padding-top: 0 !important;
}


/* เพิ่มระยะห่างระหว่าง Project name และ KPI */
#timelineCard .row:first-child {
  margin-bottom: 16px;
}

/* Keep first row from hiding under sticky header */
#eventTable tbody tr{
  scroll-margin-top: 36px;
}

/* Remove focus rings */
#eventTable:focus,
#eventTable table:focus,
#eventTable thead:focus,
#eventTable tbody:focus,
#eventTable tr:focus,
#eventTable td:focus,
#eventTable th:focus,
#eventTable [tabindex]:focus {
  outline: none !important;
  box-shadow: none !important;
}
#eventTable:focus-visible {
  outline: none !important;
}
#eventTable *:focus {
  outline-color: transparent !important;
}
/* Remove the blanket :focus suppression. Use :focus-visible to only suppress the ring for mouse clicks while preserving keyboard focus. */
.tabs .tab:focus:not(:focus-visible),
.inner-tab:focus:not(:focus-visible),
.btn:focus:not(:focus-visible),
.qs-btn:focus:not(:focus-visible) {
  outline: none;
  box-shadow: none;
}

/* --- Fix ABOUT text overlap --- */
#main-about .about-body,
#main-about .about-body p,
