}
#qsCard .card-title,
#qsCard .section-title,
#qsCard .qs-title {
  font-size: 11px;
}
#qsCard .toggle,
#qsCard button.toggle,
#qsCard .qs-btn,
#qsCard button {
  font-size: 11px;
  line-height: 1.1;
  padding: 10px 11px;
}
#qsCard .toggle.long,
#qsCard .qs-btn.long {
