/* ==========================================================
   CUT DiFF — Reduce text clutter (hide long help text)
   ========================================================== */

/* ซ่อนคำอธิบายยาวใต้หัวข้อ CUT DIFF (บรรทัด “Load OLD and NEW cuts…”) */
#cutdiffCard > .muted{
  display:none !important;
}

/* ซ่อนคำอธิบายยาวใต้หัวข้อย่อย (1. OLD Cut / 2. NEW Cut / Options)
   แต่ไม่กระทบ status ที่อยู่ด้านล่างปุ่ม */
#cutdiffCard .card-subtitle + .muted{
  display:none !important;
}

/* ทำหัวข้อ/ตัวอักษรให้กระชับขึ้น */
#cutdiffCard .card-title{
  font-size:14px;
  margin-bottom:8px;
}

#cutdiffCard .cutdiff-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
}
#cutdiffCard .cutdiff-head .card-title{
  margin:0;
}

/* Hawkins: remove redundant CUT DIFF header text (keep Clear button) */
body[data-main="cutdiff"] #cutdiffCard .cutdiff-head .card-title{ display:none !important; }
body[data-main="cutdiff"] #cutdiffCard .cutdiff-head{ justify-content:flex-end; }

/* Hawkins: Summary already shows KPIs + sidebar shows file names; hide the long OLD/NEW compare lock row */
body[data-main="cutdiff"] #cutdiffCompareLock{ display:none !important; }

/* Hawkins: remove extra export buttons (CSV + VFX Pack) from Cut Diff UI */
body[data-main="cutdiff"] #cutdiffExportCsvBtn,
body[data-main="cutdiff"] #cutdiffExportPackBtn{ display:none !important; }
body[data-main="cutdiff"] #cutdiffExportBtn,
body[data-main="cutdiff"] #cutdiffExportPdfBtn{ flex: 1 1 100% !important; }
#cutdiffCard .card-subtitle{
  font-size:12px;
}

/* Summary placeholder ให้สั้น/ไม่กินพื้นที่ */
#cutdiffSummaryKpi .muted{
  font-size:11px;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

/* ==========================================================
   CUT DIFF — Smart Timeline Compare (OLD vs NEW)
   ========================================================== */

.cd-difftl{
  position:relative;
  padding:10px 10px 8px;
  border-bottom:1px solid rgba(255,255,255,.10);
  background:linear-gradient(180deg, rgba(22,22,28,.92), rgba(16,16,20,.86));

  /* User-resizable (vertical) to give more space to timeline */
  display:flex;
  flex-direction:column;
  resize: vertical;
  overflow:hidden; /* required for CSS resize handle */
  min-height: 150px;
  max-height: 70vh;
}
.cd-difftl.is-collapsed{
  padding-bottom:10px;
}
.cd-difftl-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:6px;
  margin-bottom:8px;
}
.cd-difftl-title{
  font-weight:800;
  font-size:12px;
  letter-spacing:.2px;
  opacity:.92;
  white-space:nowrap;
}

/* Mode switcher (Compare / NEW / OLD) */
.cd-difftl-mode{
  display:flex;
  align-items:center;
  gap:4px;
  padding:2px;
  border-radius:999px;
  background:rgba(255,255,255,.06);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.08);
  white-space:nowrap;
}
.cd-modebtn{
  appearance:none;
  border:none;
  background:transparent;
  color:rgba(235,240,255,.75);
  font-size:11px;
  font-weight:900;
  letter-spacing:.2px;
  padding:4px 10px;
  border-radius:999px;
  cursor:pointer;
}
.cd-modebtn:hover{ color:rgba(245,247,255,.90); }
.cd-modebtn.is-active{
  background:rgba(176,108,255,.26);
  color:rgba(245,247,255,.95);
  box-shadow: inset 0 0 0 1px rgba(176,108,255,.35);
}
/* Transcode badge on mode button */
.cd-xcode-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  margin-left: 5px;
  border-radius: 8px;
  font-size: 10px;
  font-weight: 600;
  background: rgba(255,170,50,.3);
  color: rgb(255,185,70);
}
/* CUT DIFF transcode pane */
.cd-xcode-pane {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}
.cd-xcode-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  border-bottom: 1px solid rgba(255,255,255,.07);
  flex-shrink: 0;
}
.cd-xcode-title {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255,255,255,.4);
  text-transform: uppercase;
  letter-spacing: .05em;
}
.cd-xcode-clear-btn {
  font-size: 10px;
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,.12);
  background: transparent;
  color: rgba(255,255,255,.4);
  cursor: pointer;
}
.cd-xcode-clear-btn:hover { color: rgba(255,255,255,.8); border-color: rgba(255,255,255,.3); }
.cd-xcode-list {
  flex: 1 1 0;
  overflow-y: auto;
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.cd-xcode-empty {
  color: rgba(255,255,255,.25);
  font-size: 11px;
  text-align: center;
  padding: 20px 0;
}
.cd-xcode-row {
  display: grid;
  grid-template-columns: 1fr 80px 48px;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-radius: 4px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.07);
}
.cd-xcode-row.cd-xcode-active { border-color: rgba(255,170,50,.3); }
.cd-xcode-row.cd-xcode-done   { border-color: rgba(43,230,167,.2); }
.cd-xcode-row.cd-xcode-error  { border-color: rgba(255,80,80,.25); }
.cd-xcode-name {
  font-size: 11px;
  color: rgba(255,255,255,.7);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cd-xcode-bar-wrap {
  height: 3px;
  background: rgba(255,255,255,.1);
  border-radius: 2px;
  overflow: hidden;
}
.cd-xcode-bar {
  height: 100%;
  border-radius: 2px;
  background: rgb(255,170,50);
  transition: width .3s;
}
.cd-xcode-done  .cd-xcode-bar  { background: rgb(43,230,167); }
.cd-xcode-error .cd-xcode-bar  { background: rgb(255,80,80); }
.cd-xcode-stat {
  font-size: 10px;
  color: rgba(255,255,255,.4);
  text-align: right;
  white-space: nowrap;
}
.cd-xcode-done  .cd-xcode-stat { color: rgb(43,230,167); }
.cd-xcode-error .cd-xcode-stat { color: rgb(255,100,100); }
.cd-difftl-legend{
  display:flex;
  align-items:center;
  gap:6px;
  flex:1;
  justify-content:flex-start;
  padding-left:10px;
  opacity:.86;
  font-size:11px;
  white-space:nowrap;
}
.cd-legend-item{
  display:inline-flex;
  align-items:center;
  gap:6px;
  appearance:none;
  border:none;
  background:transparent;
  color:rgba(255,255,255,.90);
  font:inherit;
  padding:3px 8px;
  border-radius:999px;
  cursor:pointer;
  user-select:none;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.12);
  background:rgba(255,255,255,.05);
 }
.cd-legend-item:hover{ background:rgba(255,255,255,.08); }
.cd-legend-item.is-off{
  opacity:.35;
  filter:saturate(.35);
 }
.cd-legend-dot{
  width:10px;
  height:10px;
  border-radius:999px;
  display:inline-block;
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.55);
}
.cd-dot-new{ background: color-mix(in srgb, var(--diff-new) 85%, transparent); }
.cd-dot-extended{ background: color-mix(in srgb, var(--diff-extended) 85%, transparent); }
.cd-dot-changed{ background: color-mix(in srgb, var(--diff-changed) 85%, transparent); }
.cd-dot-removed{ background: color-mix(in srgb, var(--diff-removed) 85%, transparent); }

.cd-difftl-actions{ display:flex; align-items:center; gap:8px; }

/* Overview mini-map (compare mode) */
.cd-difftl-overview{
  position:relative;
  height:22px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,.10);
  background:rgba(0,0,0,.18);
  margin-bottom:8px;
  overflow:hidden;
}
.cd-difftl-overview::before{
  content:"CHANGE MAP";
  position:absolute;
  left:10px;
  top:50%;
  transform:translateY(-50%);
  font-size:9px;
  font-weight:900;
  letter-spacing:.9px;
  color:rgba(255,255,255,.55);
  opacity:.85;
  pointer-events:none;
  text-transform:uppercase;
}
.cd-difftl-overview::after{
  content:"click \u2022 drag";
  position:absolute;
  right:10px;
  top:50%;
  transform:translateY(-50%);
  font-size:9px;
  font-weight:800;
  letter-spacing:.4px;
  color:rgba(255,255,255,.45);
  opacity:.85;
  pointer-events:none;
  text-transform:uppercase;
}
.cd-difftl[data-mode="new"] .cd-difftl-overview,
.cd-difftl[data-mode="old"] .cd-difftl-overview{ display:none; }

.cd-ov-track{ position:absolute; inset:0; }
.cd-ov-seg{
  position:absolute;
  top:4px;
  height:12px;
  border-radius:999px;
  background:rgba(255,255,255,.18);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.55);
}
.cd-ov-seg.is-diff-new{ background: color-mix(in srgb, var(--diff-new) 55%, rgba(255,255,255,.08)); }
.cd-ov-seg.is-diff-extended{ background: color-mix(in srgb, var(--diff-extended) 55%, rgba(255,255,255,.08)); }
.cd-ov-seg.is-diff-changed{ background: color-mix(in srgb, var(--diff-changed) 60%, rgba(255,255,255,.08)); }
.cd-ov-seg.is-diff-removed{ background: color-mix(in srgb, var(--diff-removed) 60%, rgba(255,255,255,.08)); }
.cd-ov-seg.is-filtered{ opacity:.20; filter:saturate(.35); }
.cd-ov-seg.is-audio{ top:9px; height:6px; opacity:.78; border-radius:999px; }

.cd-ov-window{
  position:absolute;
  top:1px;
  bottom:1px;
  border-radius:999px;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.20), 0 0 0 1px rgba(0,0,0,.35);
  background:rgba(255,255,255,.06);
  pointer-events:auto;
}
.cd-ov-window::after{
  content:"";
  position:absolute;
  inset:3px;
  border-radius:999px;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.10);
}

.cd-difftl-body{
  position:relative;
  flex:1;
  min-height:0;
  display:flex;
  flex-direction:column;
}

/* Hide legend when viewing original timelines */
.cd-difftl[data-mode="new"] .cd-difftl-legend,
.cd-difftl[data-mode="old"] .cd-difftl-legend{ display:none; }

.cd-difftl-viewport{
  position:relative;
  border-radius:14px;
  border:1px solid rgba(255,255,255,.12);
  background:rgba(0,0,0,.22);
  padding:10px 10px 8px;
  overflow:hidden;
  flex: 1;
  min-height: 80px;
  cursor: grab;
}

/* Cut Diff: red playhead synced to Video Compare timeline */
.cd-difftl-playhead{
  position:absolute;
  left:0;
  will-change:transform;
  top:0;
  bottom:0;
  width:2px;
  background:rgba(255, 59, 48, 0.95);
  box-shadow:0 0 0 1px rgba(0,0,0,0.45), 0 0 12px rgba(255, 59, 48, 0.35);
  pointer-events:none;
  z-index:30;
  transform:translateX(0px);
}
.cd-difftl-playhead::before{
  content:'';
  position:absolute;
  top:2px;
  left:50%;
  transform:translateX(-50%);
  width:0;
  height:0;
  border-left:6px solid transparent;
  border-right:6px solid transparent;
  border-bottom:6px solid rgba(255, 59, 48, 0.95);
  filter:drop-shadow(0 2px 3px rgba(0,0,0,0.55));
}

.cd-difftl-viewport.is-dragging{ cursor: grabbing; }

.cd-difftl-ruler{
  position:relative;
  height:14px;
  opacity:.55;
  margin-bottom:8px;
}
.cd-difftl-ruler .cd-tick{
  position:absolute;
  top:0;
  bottom:0;
  width:1px;
  background:rgba(255,255,255,.14);
}
.cd-difftl-ruler .cd-tick-label{
  position:absolute;
  top:-2px;
  transform: translateX(-50%);
  font-size:10px;
  color:rgba(255,255,255,.72);
  white-space:nowrap;
}

.cd-difftl-tracks{ display:flex; flex-direction:column; gap:8px; }
.cd-track{ display:grid; grid-template-columns:56px 1fr; gap:8px; align-items:center; }
.cd-track-label{
  display:inline-flex;
  align-items:center;
  justify-content:flex-end;
  gap:4px;
  font-size:10px;
  letter-spacing:.8px;
  opacity:.90;
  font-weight:900;
  text-align:right;
  padding:2px 8px;
  border-radius:999px;
  background:rgba(255,255,255,.06);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.12);
}
.cd-track[data-track="old"] .cd-track-label::after,
.cd-track[data-track="new"] .cd-track-label::after{
  content:"CUT";
  margin-left:4px;
  font-size:9px;
  opacity:.55;
  font-weight:900;
  letter-spacing:.9px;
}
.cd-track.is-audio .cd-track-label{
  background:rgba(108,168,255,.10);
  box-shadow: inset 0 0 0 1px rgba(108,168,255,.20);
}
.cd-track[data-track="old-audio"] .cd-track-label::after,
.cd-track[data-track="new-audio"] .cd-track-label::after{
  content:"AUDIO";
  margin-left:4px;
  font-size:9px;
  opacity:.62;
  font-weight:900;
  letter-spacing:.9px;
}
.cd-track-lane{
  position:relative;
  height:18px;
  border-radius:10px;
  background:rgba(255,255,255,.05);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.08);
  overflow:hidden;
}
.cd-seg{
  position:absolute;
  top:3px;
  height:12px;
  border-radius:8px;
  background:rgba(255,255,255,.10);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.55);
}
.cd-seg.is-base{
  opacity:.22;
  background:rgba(255,255,255,.08);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.06);
}
.cd-seg.is-diff-new{ background: color-mix(in srgb, var(--diff-new) 78%, rgba(255,255,255,.10)); }
.cd-seg.is-diff-extended{ background: color-mix(in srgb, var(--diff-extended) 78%, rgba(255,255,255,.10)); }
.cd-seg.is-diff-changed{ background: color-mix(in srgb, var(--diff-changed) 82%, rgba(255,255,255,.10)); }
.cd-seg.is-diff-removed{ background: color-mix(in srgb, var(--diff-removed) 82%, rgba(255,255,255,.10)); }
.cd-seg.is-selected{
  box-shadow:
    inset 0 0 0 1px rgba(0,0,0,.65),
    0 0 0 2px color-mix(in srgb, var(--diff-changed) 45%, transparent);
}
.cd-seg.is-filtered{ opacity:.20; filter:saturate(.35); pointer-events:none; }
.cd-seg.is-filtered.is-selected{ opacity:1; filter:none; pointer-events:auto; }
.cd-seg.is-audio{ box-shadow: inset 0 0 0 1px rgba(255,255,255,.18), inset 0 -1px 0 rgba(0,0,0,.35); }

.cd-difftl.is-collapsed .cd-difftl-body{ display:none; }

/* Original timeline container inside Cut Diff */
.cd-origtl{
  border-radius:14px;
  border:1px solid rgba(255,255,255,.12);
  background:rgba(0,0,0,.18);
  overflow:hidden;
  flex: 1;
  min-height: 140px;
}

.cd-origtl.cd-origtl-pullprep{
  background:
    linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02)),
    rgba(10,12,18,.94);
  display:flex;
}
.cd-origtl .cd-origtl-shell{
  display:flex;
  flex-direction:column;
  width:100%;
  height:100%;
  min-height:0;
}
.cd-origtl .edl-tl-minimap-wrap{
  position:relative;
  flex:0 0 18px;
  height:18px;
  border-bottom:1px solid rgba(255,255,255,.08);
  background:rgba(0,0,0,.34);
  overflow:hidden;
}
.cd-origtl .edl-tl-minimap-canvas{
  display:block;
  width:100%;
  height:100%;
}
.cd-origtl .edl-tl-minimap-window{
  position:absolute;
  top:2px;
  height:calc(100% - 4px);
  border-radius:999px;
  border:1px solid rgba(255,255,255,.34);
  background:rgba(255,255,255,.10);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.26);
  pointer-events:none;
}
.cd-origtl .edl-tl-viewport{
  position:relative;
  flex:1 1 auto;
  min-height:0;
  overflow:auto;
  background:
    linear-gradient(180deg, rgba(18,20,28,.96), rgba(12,14,20,.98));
  cursor:default;
  --edl-tl-label-w: 48px;
  --edl-tl-content-w: 800px;
  scrollbar-width: thin;
  scrollbar-color: rgba(160,120,255,.75) rgba(255,255,255,.08);
}
.cd-origtl .edl-tl-viewport.is-dragging{ cursor:grabbing; }
.cd-origtl .edl-tl-viewport::-webkit-scrollbar{
  width:10px;
  height:10px;
}
.cd-origtl .edl-tl-viewport::-webkit-scrollbar-track{
  background:rgba(255,255,255,.08);
  border-radius:999px;
}
.cd-origtl .edl-tl-viewport::-webkit-scrollbar-thumb{
  background:linear-gradient(180deg, rgba(170,120,255,.88), rgba(110,78,230,.82));
  border-radius:999px;
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.28);
}
.cd-origtl .edl-tl-ruler{
  position:sticky;
  top:0;
  z-index:3;
  height:26px;
  min-width:calc(var(--edl-tl-label-w, 48px) + var(--edl-tl-content-w, 800px));
  background:rgba(0,0,0,.54);
  border-bottom:1px solid rgba(255,255,255,.08);
}
.cd-origtl .edl-tl-ruler .spacer{
  position:sticky;
  left:0;
  width:var(--edl-tl-label-w, 48px);
  height:100%;
  background:rgba(0,0,0,.78);
  border-right:1px solid rgba(255,255,255,.08);
  z-index:2;
}
.cd-origtl .edl-tl-ruler .tick{
  position:absolute;
  top:7px;
  width:1px;
  height:10px;
  background:rgba(255,255,255,.18);
}
.cd-origtl .edl-tl-ruler .label{
  position:absolute;
  top:1px;
  transform:translateX(-50%);
  color:rgba(230,235,245,.78);
  font-size:10px;
  white-space:nowrap;
}
.cd-origtl .edl-tl-tracks{
  position:relative;
  min-width:calc(var(--edl-tl-label-w, 48px) + var(--edl-tl-content-w, 800px));
}
.cd-origtl .edl-tl-track{
  display:flex;
  position:relative;
  min-height:var(--edl-tl-row-h, 24px);
  border-bottom:1px solid rgba(255,255,255,.06);
  background:rgba(255,255,255,.02);
}
.cd-origtl .edl-tl-track:nth-child(even){
  background:rgba(255,255,255,.015);
}
.cd-origtl .edl-tl-track.is-spine{
  background:rgba(255,255,255,.035);
}
.cd-origtl .edl-tl-label{
  width:var(--edl-tl-label-w, 48px);
  flex:0 0 var(--edl-tl-label-w, 48px);
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:11px;
  color:rgba(220,226,236,.78);
  background:rgba(0,0,0,.72);
  border-right:1px solid rgba(255,255,255,.08);
  position:sticky;
  left:0;
  z-index:2;
}
.cd-origtl .edl-tl-label.is-v1{
  color:rgba(255,92,92,.96);
  font-weight:700;
}
.cd-origtl .edl-tl-lane{
  position:relative;
  width:var(--edl-tl-content-w, 800px);
  min-width:var(--edl-tl-content-w, 800px);
  background-image:linear-gradient(to right, rgba(255,255,255,.06), rgba(255,255,255,0));
}
.cd-origtl .edl-tl-item{
  position:absolute;
  top:2px;
  height:calc(var(--edl-tl-row-h, 24px) - 4px);
  border-radius:3px;
  border:1px solid rgba(0,0,0,.55);
  border-left:3px solid rgba(120,195,255,.98);
  background:rgba(56,150,220,.86);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.16),
    inset -1px 0 0 rgba(0,0,0,.35),
    inset 0 -1px 0 rgba(0,0,0,.35);
  color:rgba(255,255,255,.92);
  font-size:10px;
  line-height:calc(var(--edl-tl-row-h, 24px) - 4px);
  padding:0 4px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  cursor:pointer;
  user-select:none;
}
.cd-origtl .edl-tl-item.is-spine-clip{
  background:rgba(86,168,235,.90);
}
.cd-origtl .edl-tl-item.is-connected-clip{
  background:rgba(63,148,226,.82);
}
.cd-origtl .edl-tl-item:hover{
  filter:brightness(1.08);
  border-color:rgba(255,255,255,.32);
}
.cd-origtl .edl-tl-item.is-selected{
  outline:2px solid rgba(255,255,255,.72);
  border-color:rgba(255,255,255,.88);
  filter:brightness(1.10);
}
.cd-origtl .edl-tl-item.is-disabled{
  opacity:.36;
  filter:grayscale(.24) saturate(.38);
  cursor:default;
}
.cd-origtl .edl-tl-item[data-diff="NEW"]{
  border-left-color:var(--diff-new);
}
.cd-origtl .edl-tl-item[data-diff="EXTENDED"]{
  border-left-color:var(--diff-extended);
}
.cd-origtl .edl-tl-item[data-diff="CHANGED"]{
  border-left-color:var(--diff-changed);
}
.cd-origtl .edl-tl-item[data-diff="REMOVED"]{
  border-left-color:var(--diff-removed);
}

/* ตาราง CUT DIFF ให้ตัวหนังสือเล็กลงนิด และอ่านง่าย */
#cutdiffTableWrapper{
  overflow:auto;

  /* Reserve space so overlay scrollbars never cover content */
  padding-right: 18px;
  padding-bottom: 24px;

  /* Hide native scrollbars (overlay scrollbars are always visible) */
  scrollbar-width: none; /* Firefox */
  scrollbar-gutter: auto;
}
#cutdiffTableWrapper::-webkit-scrollbar{
  width:0;
  height:0;
}

/* Cut Diff overlay scrollbars (always visible, like vis-timeline)
   JS: scripts/cutdiff_table_scrollbars.js
*/
.mps-cd-vscroll{
  position:absolute;
  top:0;
  right:0;
  width:12px;
  height:100%;
  background: rgba(0,0,0,0.22);
  border-left: 1px solid rgba(255,255,255,0.08);
  border-top-right-radius: 14px;
  border-bottom-right-radius: 14px;
  pointer-events: auto;
  z-index: 5;
}
.mps-cd-vthumb{
  position:absolute;
  left:2px;
  width:8px;
  top:0;
  height:40px;
  border-radius: 8px;
  background: rgba(255,255,255,0.22);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.55);
}
.mps-cd-hscroll{
  position:absolute;
  left:0;
  bottom:0;
  height:12px;
  width:100%;
  background: rgba(0,0,0,0.22);
  border-top: 1px solid rgba(255,255,255,0.08);
  border-bottom-left-radius: 14px;
  border-bottom-right-radius: 14px;
  pointer-events: auto;
  z-index: 5;
}
.mps-cd-hthumb{
  position:absolute;
  top:2px;
  height:8px;
  left:0;
  width:40px;
  border-radius: 8px;
  background: rgba(255,255,255,0.22);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.55);
}

#cutdiffTable{
  min-width:1300px; /* allow horizontal scroll like the Visual Timeline */
}

