/* ------------------------------------------------------------
   SHOT MARKER (QT marker → VFX Shots List)
------------------------------------------------------------- */
.sm-glass{
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.14);
  backdrop-filter: blur(22px) saturate(1.35);
  -webkit-backdrop-filter: blur(22px) saturate(1.35);
  border-radius: 16px;
}

.sm-wrap{ padding: 10px; }

.sm-toolbar{
  display:flex;
  gap:6px;
  align-items:center;
  padding:10px;
  margin-bottom:10px;
