}

/* EDL Timeline: right-click menu (Enable/Disable/Delete clip) */
.edl-tl-ctx{
  position: fixed;
  left: -9999px;
  top: -9999px;
  min-width: 0;
  padding: 6px;
  display: none; /* single declaration */
  z-index: 99999;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 6px;
  align-items: center;
  background: rgba(18,18,22,.90);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 14px;
  box-shadow: 0 12px 34px rgba(0,0,0,.55);
  backdrop-filter: blur(24px);
}
.edl-tl-ctx.is-open{ display:grid; }
.edl-tl-ctx-item{
  border: none;
  cursor: pointer;
  color: rgba(255,255,255,.94);
}
.edl-tl-ctx-item.pfx-iconbtn{
  min-width: 56px;
  width: 56px;
  height: 42px;
  padding: 0;
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.03));
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.06);
}
.edl-tl-ctx-item.pfx-iconbtn .pfx-ib-ico{
  width: 18px;
  height: 18px;
}
.edl-tl-ctx-item.pfx-iconbtn .pfx-ib-ico svg,
.edl-tl-ctx-item.pfx-iconbtn .pfx-ib-ico svg *{
  width: 18px;
  height: 18px;
  stroke-width: 1.9;
}
.edl-tl-ctx-item.pfx-iconbtn:hover{
  background: linear-gradient(180deg, rgba(255,255,255,.11), rgba(255,255,255,.05));
  border-color: rgba(255,255,255,.18);
}
.edl-tl-ctx-item.pfx-iconbtn:active{
  transform: translateY(1px);
}
.edl-tl-ctx-item.is-enabled{
  color: rgba(120,245,192,.96);
}
.edl-tl-ctx-item.is-danger.pfx-iconbtn{
  color: rgba(255,106,106,.96);
}
.edl-tl-ctx-item.is-danger.pfx-iconbtn:hover{
  background: linear-gradient(180deg, rgba(255,110,110,.16), rgba(255,110,110,.08));
  border-color: rgba(255,120,120,.24);
}

#edlTimelineCard .edl-tl-badge{
  height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(194,103,255,0.35);
  background: rgba(194,103,255,0.12);
  color: rgba(245,247,255,0.92);
  font-size: 12px;
  line-height: 24px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

#edlTimelineCard .edl-tl-viewport{
  /* default is a clamp; can be overridden by dragging the divider */
  height: var(--edl-tl-viewport-h, clamp(60px, 8vh, 90px));
  overflow: auto;
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(0,0,0,0.30);
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,0.03),
    inset 0 2px 0 rgba(255,60,60,0.70);
}

#edlTimelineCard .edl-tl-ruler{
  position: sticky;
  top: 0;
  height: 24px;
  min-width: calc(var(--edl-tl-label-w, 48px) + var(--edl-tl-content-w, 800px));
  background: rgba(0,0,0,0.42);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  z-index: 3;
}

#edlTimelineCard .edl-tl-ruler .spacer{
  position: absolute;
  left: 0;
  top: 0;
  width: var(--edl-tl-label-w, 48px);
  height: 100%;
  background: rgba(0,0,0,0.72);
  border-right: 1px solid rgba(255,255,255,0.06);
}

#edlTimelineCard .edl-tl-ruler .tick{
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: rgba(255,255,255,0.10);
}

#edlTimelineCard .edl-tl-ruler .label{
  position: absolute;
  top: 4px;
  transform: translateX(-50%);
  font-size: 10px;
  opacity: 0.70;
  white-space: nowrap;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

#edlTimelineCard .edl-tl-tracks{
  min-width: calc(var(--edl-tl-label-w, 48px) + var(--edl-tl-content-w, 800px));
}

/* Playhead (position indicator line) */
#edlTimelineCard .edl-tl-tracks{ position: relative; }
#edlTimelineCard .edl-tl-playhead{
  position: absolute;
  top: 0;
  bottom: 0;
  width: 14px;                 /* grab area */
  transform: translateX(-7px); /* center on x */
  pointer-events: none;
  z-index: 20;
}
#edlTimelineCard .edl-tl-playhead::before{
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 2px;
  transform: translateX(-1px);
  border-radius: 1px;
  background: rgba(255, 85, 85, 0.96);
  box-shadow:
    0 0 0 1px rgba(0,0,0,0.45),
    0 0 12px rgba(255, 85, 85, 0.28);
}
#edlTimelineCard .edl-tl-playhead--ruler{
  pointer-events: auto;
  cursor: ew-resize;
  touch-action: none;
}
#edlTimelineCard .edl-tl-playhead--ruler::after{
  content: "";
  position: absolute;
  top: 0px;
  left: 50%;
  transform: translateX(-7px);
  width: 0;
  height: 0;
  border-left: 7px solid transparent;
  border-right: 7px solid transparent;
  border-top: 10px solid rgba(255, 85, 85, 0.96); /* down-facing triangle */
  filter: drop-shadow(0 2px 2px rgba(0,0,0,0.55));
}




#edlTimelineCard .edl-tl-track{
  display: flex;
  align-items: stretch;
  position: relative;
  height: var(--edl-tl-row-h, 18px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  background: rgba(255,255,255,0.02);
}

#edlTimelineCard .edl-tl-track:nth-child(even){
  background: rgba(0,0,0,0.08);
}

/* Track height resize handle (drag like an NLE) */
#edlTimelineCard .edl-tl-resize{
  position: absolute;
  left: 0;
  right: 0;
  bottom: -3px;
  height: 7px;
  cursor: ns-resize;
  z-index: 6;
  opacity: 0;
  transition: opacity 120ms ease;
}

#edlTimelineCard .edl-tl-track:hover .edl-tl-resize,
#edlTimelineCard .edl-tl-resize.is-active{
  opacity: 1;
}

#edlTimelineCard .edl-tl-resize::before{
  content: "";
  position: absolute;
  left: 10px;
  right: 10px;
  top: 3px;
  height: 1px;
  background: rgba(255,255,255,0.14);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.28);
}

#edlTimelineCard .edl-tl-resize::after{
  content: "";
  position: absolute;
  left: 50%;
  top: 2px;
  width: 18px;
  height: 3px;
  transform: translateX(-50%);
  border-radius: 999px;
  background: rgba(170,180,210,0.38);
}

html.edl-tl-resizing, html.edl-tl-resizing *{
  cursor: ns-resize !important;
}

#edlTimelineCard .edl-tl-label{
  width: var(--edl-tl-label-w, 48px);
  flex: 0 0 var(--edl-tl-label-w, 48px);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  opacity: 0.78;
  background: rgba(0,0,0,0.70);
  border-right: 1px solid rgba(255,255,255,0.08);
  position: sticky;
  left: 0;
  z-index: 2;
}

#edlTimelineCard .edl-tl-label.is-v1{
  color: rgba(255,85,85,0.95);
  font-weight: 700;
}

#edlTimelineCard .edl-tl-lane{
  position: relative;
  width: var(--edl-tl-content-w, 800px);
  min-width: var(--edl-tl-content-w, 800px);
  background-image: linear-gradient(to right, rgba(255,255,255,0.06), rgba(255,255,255,0.00));
  overflow: visible;
}

#edlTimelineCard .edl-tl-item{
  position: absolute;
  top: var(--edl-tl-item-top, 2px);
  height: calc(var(--edl-tl-row-h, 18px) - 4px);
  border-radius: 3px;
  border: 1px solid rgba(0,0,0,0.55);
  border-left: 3px solid var(--clip-color, rgba(255,255,255,0.40));
  background: rgba(56, 150, 220, 0.85);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.16),
    inset -1px 0 0 rgba(0,0,0,0.35),
    inset 0 -1px 0 rgba(0,0,0,0.35);
  color: rgba(255,255,255,0.92);
  font-size: 10px;
  line-height: calc(var(--edl-tl-row-h, 18px) - 4px);
  padding: 0 4px;
  overflow: visible;
  cursor: pointer;
  user-select: none;
}

#edlTimelineCard .edl-tl-item-label{
  display: block;
  width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

#edlTimelineCard .edl-tl-item-speed-badge{
  position: absolute;
  left: 50%;
  top: -22px;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 62px;
  max-width: calc(100% + 32px);
  height: 16px;
  padding: 0 7px;
  border-radius: 999px;
  border: 1px solid rgba(255,184,74,0.92);
  background: rgba(14,14,20,0.96);
  box-shadow:
    0 5px 16px rgba(0,0,0,0.36),
    inset 0 1px 0 rgba(255,255,255,0.10);
  color: rgba(255,233,190,0.99);
  font-size: 9px;
  font-weight: 700;
  line-height: 16px;
  letter-spacing: 0.01em;
  white-space: nowrap;
  pointer-events: none;
  z-index: 5;
}

#edlTimelineCard .edl-tl-item-speed-badge::after{
  content: "";
  position: absolute;
  left: 50%;
  top: calc(100% - 1px);
  transform: translateX(-50%);
  width: 2px;
  height: 7px;
  border-radius: 999px;
  background: linear-gradient(to bottom, rgba(255,184,74,0.94), rgba(255,184,74,0.42));
  box-shadow: 0 0 10px rgba(255,184,74,0.28);
}

#edlTimelineCard .edl-tl-item-speed-badge .icon{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  line-height: 1;
  opacity: 0.99;
  flex: 0 0 auto;
}

#edlTimelineCard .edl-tl-item-speed-badge .icon svg{
  display: block;
  width: 100%;
  height: 100%;
  stroke: currentColor;
  fill: none;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#edlTimelineCard .edl-tl-item-speed-badge .val{
  display: inline-block;
  max-width: 100%;
}

#edlTimelineCard .edl-tl-item:hover{
  filter: brightness(1.08);
  border-color: rgba(255,255,255,0.32);
}

#edlTimelineCard .edl-tl-item.is-selected{
  outline: 2px solid rgba(255,255,255,0.70);
  border-color: rgba(255,255,255,0.85);
  filter: brightness(1.10);
}


#edlTimelineCard .edl-tl-item.is-disabled{
  opacity: 0.40;
  background: rgba(120,120,120,0.45);
  border-color: rgba(0,0,0,0.55);
}

#edlTimelineCard .edl-tl-item.is-speed,
#edlTimelineCard .edl-tl-item.is-handles{
  background: rgba(255, 176, 32, 0.92);
  border-color: rgba(0,0,0,0.60);
}
#edlTimelineCard .edl-tl-item.is-adv,
#edlTimelineCard .edl-tl-item.is-transform{
  background: rgba(61, 214, 208, 0.92);
  border-color: rgba(0,0,0,0.60);
}

/* Dynamic speed clips — gradient overlay instead of flat amber */
#edlTimelineCard .edl-tl-item.is-dynamic-speed{
  background: linear-gradient(135deg,
    rgba(255,140,20,0.88) 0%,
    rgba(255,100,10,0.96) 50%,
    rgba(255,140,20,0.88) 100%);
}

/* Speed strip — bottom bar inside clip */
#edlTimelineCard .edl-tl-spd-strip{
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 4px;
  border-radius: 0 0 2px 2px;
  background: rgba(180,100,0,0.55);
  pointer-events: none;
  overflow: hidden;
}
#edlTimelineCard .edl-tl-spd-strip.is-dynamic{
  background: linear-gradient(90deg,
    rgba(255,160,30,0.30) 0%,
    rgba(255,100,10,0.70) 50%,
    rgba(255,160,30,0.30) 100%);
}

/* Keyframe diamond ticks inside the speed strip */
#edlTimelineCard .edl-tl-spd-kf{
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%) rotate(45deg);
  width: 5px;
  height: 5px;
  background: rgba(255,240,160,0.90);
  box-shadow: 0 0 3px rgba(224,179,65,0.70);
  pointer-events: none;
}

/* Resize / Stabilize top strip */
#edlTimelineCard .edl-tl-rs-strip{
  position: absolute;
  left: 0; right: 0; top: 0;
  height: 3px;
  border-radius: 2px 2px 0 0;
  background: rgba(160,90,230,0.72);
  pointer-events: none;
}
#edlTimelineCard .edl-tl-rs-strip.is-stabilize{
  background: rgba(40,200,155,0.68);
}

/* ========================================================================
   Glass Luxe Theme (global) — v2026.02.01-glassluxe
   Goal: ทุกหน้าเป็น frosted-glass เรียบหรู + readable (ไม่กระทบ logic)
   ======================================================================== */

:root{
  --radius: 14px;
  --glass-bg: rgba(20,22,30,0.46);
  --glass-bg-2: rgba(16,18,24,0.32);
  --glass-stroke: rgba(255,255,255,0.14);
  --glass-stroke-2: rgba(255,255,255,0.22);
  --glass-shadow: 0 18px 50px rgba(0,0,0,0.42);
  --glass-shadow-soft: 0 10px 30px rgba(0,0,0,0.28);
  --glass-blur: 26px;
  --glass-sat: 175%;
}

/* Remove dev-only texture (prevents broken url in extension) */
body::before{ display:none !important; }

html,body{
  background:
    radial-gradient(1200px 900px at 12% 8%, rgba(177,124,255,0.26) 0%, rgba(177,124,255,0.08) 22%, rgba(177,124,255,0.00) 55%),
    radial-gradient(1100px 900px at 92% 82%, rgba(114,230,255,0.20) 0%, rgba(114,230,255,0.06) 24%, rgba(114,230,255,0.00) 58%),
    radial-gradient(900px 700px at 70% 14%, rgba(255,223,126,0.10) 0%, rgba(255,223,126,0.03) 26%, rgba(255,223,126,0.00) 60%),
    linear-gradient(180deg, #07070a 0%, #0b0b10 35%, #07070a 100%) fixed;
}

/* Header (glass) */
header{
  background:
    linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0.03)),
    var(--glass-bg);
  border-bottom: 1px solid rgba(255,255,255,0.12);
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
}

/* Cards / panels (global) */
.card{
  background:
    linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0.03)),
    var(--glass-bg);
  border: 1px solid var(--glass-stroke);
  border-radius: 16px;
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  box-shadow: var(--glass-shadow-soft);
}

/* Main tabs (pill glass) */
.tabs{ padding: 10px 10px 0; }
.tab,.inner-tab{
  background:
    linear-gradient(180deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02)),
    rgba(18,19,26,0.36);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 10px;
  backdrop-filter: blur(24px) saturate(175%);
  -webkit-backdrop-filter: blur(24px) saturate(175%);
}
.tab:hover,.inner-tab:hover{
  border-color: rgba(255,255,255,0.20);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0.03)),
    rgba(20,21,30,0.52);
}
.tab.active,.inner-tab.active{
  border-color: rgba(255,255,255,0.26);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.12), rgba(255,255,255,0.03)),
    rgba(20,22,32,0.58);
}

/* Main tabs: align icon nicely (center vertically, left aligned with comfortable spacing) */
.tabs .tab{
  display:flex;
  align-items:center;
  justify-content:flex-start;
  gap:8px;
}
.tabs .tab img{
  display:block;
  flex:0 0 auto;
}

/* Buttons (glass pills) */
.btn,.qs-btn{
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.14);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02)),
    rgba(18,19,26,0.32);
  backdrop-filter: blur(24px) saturate(175%);
  -webkit-backdrop-filter: blur(24px) saturate(175%);
}
.btn:hover,.qs-btn:hover{
  border-color: rgba(255,255,255,0.22);
  box-shadow: 0 10px 26px rgba(0,0,0,0.28);
}
.btn.active,.qs-btn.active{
  border-color: rgba(255,255,255,0.26);
}

/* Inputs / dropdowns */
input[type="text"], input[type="number"], input[type="search"], input[type="email"], textarea, select{
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(0,0,0,0.22);
  color: rgba(255,255,255,0.92);
  outline: none;
}
input[type="text"]:focus, input[type="number"]:focus, input[type="search"]:focus, input[type="email"]:focus, textarea:focus, select:focus{
  border-color: rgba(177,124,255,0.55);
  box-shadow: 0 0 0 3px rgba(177,124,255,0.16);
}

/* Event table outer chrome */
#eventTable{
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,0.10);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.01)),
    rgba(10,10,14,0.30);
  box-shadow: 0 14px 36px rgba(0,0,0,0.35);
}

/* Table rows (subtle zebra) */
#eventTable tbody tr:nth-child(odd) td{ background: rgba(255,255,255,0.02); }
#eventTable tbody tr:hover td{ background: rgba(255,255,255,0.05); }

/* Scrollbars (WebKit) */
*::-webkit-scrollbar{ width: 10px; height: 10px; }
*::-webkit-scrollbar-track{ background: rgba(0,0,0,0.20); border-radius: 999px; }
*::-webkit-scrollbar-thumb{ background: rgba(255,255,255,0.14); border-radius: 999px; border: 2px solid rgba(0,0,0,0.20); }
*::-webkit-scrollbar-thumb:hover{ background: rgba(255,255,255,0.20); }

/* Modal overlay soft */
.mps-qt-modal{ background: rgba(0,0,0,0.42); }
.mps-qt-panel{
  background:
    linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0.03)),
    rgba(12,12,16,0.78);
  border: 1px solid rgba(255,255,255,0.14);
  backdrop-filter: blur(24px) saturate(175%);
  -webkit-backdrop-filter: blur(24px) saturate(175%);
}


/* --- SHOT MARKER: Pro Minimal Viewer + Smart Timeline (EDL-like) --- */
#main-shotmarker .sm-probar{
  display:flex;
  align-items:center;
  gap:8px;
  padding:10px 10px;
}

#main-shotmarker .sm-progroup{
  display:flex;
  align-items:center;
  gap:6px;
  padding:6px 8px;
  border-radius:999px;
  border:1px solid rgba(180,190,210,0.14);
  background: rgba(255,255,255,0.04);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow: 0 10px 28px rgba(0,0,0,0.32);
}

#main-shotmarker .sm-ibtn{
  width:34px;
  height:28px;
  min-width:34px;
  padding:0;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:999px;
  font-size:14px;
  line-height:1;
}


/* Cut-detection edit buttons disabled state (fade + non-interactive) */
#main-shotmarker .sm-ibtn.is-disabled,
#main-shotmarker .sm-ibtn:disabled{
  opacity: .35;
  filter: saturate(.25);
  cursor: not-allowed;
  pointer-events: none;
  box-shadow: none;
}

#main-shotmarker .sm-ibtn.is-on{
  border-color: rgba(180,120,255,0.55);
  box-shadow: 0 0 0 2px rgba(180,120,255,0.18) inset, 0 10px 28px rgba(0,0,0,0.32);
}

/* Shot Marker: clear imported timeline button */
#main-shotmarker #smImportClearBtn{
  border-color: rgba(255, 80, 120, 0.30);
  color: rgba(255, 170, 195, 0.95);
}
#main-shotmarker #smImportClearBtn:hover{
  border-color: rgba(255, 80, 120, 0.48);
  background: rgba(255, 80, 120, 0.10);
}

/* Shot Marker: timeline overlays (cuts + markers) */
#main-shotmarker #smTlTracks{ position: relative; }
#main-shotmarker .sm-tl-overlay{
  position:absolute;
  inset:0;
  pointer-events:none;
  z-index: 12;
}
#main-shotmarker .sm-tl-cutline{
  position:absolute;
  top:0;
  bottom:0;
  width:1px;
  background: rgba(255,255,255,0.18);
}
#main-shotmarker .sm-tl-markerline{
  position:absolute;
  top:0;
  bottom:0;
  width:2px;
  background: rgba(149,255,230,0.85);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55);
  pointer-events:auto;
  cursor:pointer;
}

#main-shotmarker .sm-tl-markerline.is-selected{
  background: rgba(180,120,255,0.95);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55), 0 0 18px rgba(180,120,255,0.22);
}



#main-shotmarker .sm-tl-markerdot{
  position:absolute;
  top: 3px;
  width: 10px;
  height: 10px;
  margin-left: -5px;
  border-radius: 999px;
  background: rgba(149,255,230,0.92);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55), 0 0 12px rgba(149,255,230,0.18);
  pointer-events:auto;
  cursor:pointer;
  z-index: 14;
}
#main-shotmarker .sm-tl-markerdot.is-selected{
  background: rgba(180,120,255,0.95);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55), 0 0 16px rgba(180,120,255,0.22);
}
#main-shotmarker .sm-tl-markerdot.is-active{
  outline: 2px solid rgba(255,255,255,0.70);
  outline-offset: 1px;
}
#main-shotmarker .sm-tl-markerdot.is-timeline{
  top: 2px;
  width: 9px;
  height: 9px;
  margin-left: -4.5px;
  background: rgba(255,220,120,0.92);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55), 0 0 12px rgba(255,220,120,0.18);
}

#main-shotmarker .sm-tl-markerline.is-composite{
  background: rgba(255,220,120,0.78);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55), 0 0 18px rgba(255,220,120,0.16);
}

#main-shotmarker .sm-tl-markerdot.is-composite{
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55), 0 0 0 2px rgba(255,220,120,0.85), 0 0 12px rgba(149,255,230,0.16);
}
#main-shotmarker .sm-tl-markerdot.is-composite.is-selected{
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55), 0 0 0 2px rgba(255,220,120,0.92), 0 0 16px rgba(180,120,255,0.22);
}


/* Shot Marker: batch actions (selection) */
#main-shotmarker .sm-tl-batchbar{
  display:flex;
  align-items:center;
  gap: 6px;
  margin-left: 10px;
  padding: 2px 6px;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 10px;
  background: rgba(10,12,18,0.35);
}
#main-shotmarker .sm-tl-batchcount{
  color: rgba(220,225,240,0.85);
  font-size: 11px;
  padding: 0 6px;
}
#main-shotmarker .sm-tl-batchbtn{
  height: 22px;
  padding: 0 8px;
  border-radius: 9px;
  font-size: 11px;
}
#main-shotmarker .sm-tl-batchbtn:disabled{
  opacity: 0.45;
  cursor: not-allowed;
  filter: saturate(0.85);
}
#main-shotmarker .sm-tl-selectbox{
  position:absolute;
  z-index: 25;
  border: 1px dashed rgba(180,120,255,0.85);
  background: rgba(180,120,255,0.10);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55) inset;
  border-radius: 6px;
  pointer-events:none;
}

/* Shot Marker: imported timeline clip blocks (match EDL Converter look) */
#main-shotmarker .edl-tl-item{
  position: absolute;
  top: var(--edl-tl-item-top, 2px);
  height: calc(var(--edl-tl-row-h, 20px) - 4px);
  border-radius: 3px;
  border: 1px solid rgba(0,0,0,0.55);
  border-left: 3px solid var(--clip-color, rgba(255,255,255,0.40));
  background: rgba(56, 150, 220, 0.85);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.16),
    inset 0 -1px 0 rgba(0,0,0,0.35);
  color: rgba(255,255,255,0.92);
  font-size: 9px;
  line-height: calc(var(--edl-tl-row-h, 20px) - 4px);
  padding: 0 4px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
}
#main-shotmarker .edl-tl-item:hover{
  filter: brightness(1.08);
  border-color: rgba(255,255,255,0.32);
}
#main-shotmarker .edl-tl-item-label{
  display:block;
  overflow:hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events:none;
}

#main-shotmarker .edl-tl-item.is-selected{
  outline: 2px solid rgba(180,120,255,0.75);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55) inset, 0 0 18px rgba(180,120,255,0.18);
}

/* Shot Marker: clips that already have marker(s) */
#main-shotmarker .edl-tl-item.has-marker{
  background: rgba(34, 197, 94, 0.78); /* green tint */
