    inset 0 -1px 0 rgba(0,0,0,0.35),
    0 0 0 1px rgba(34, 197, 94, 0.18);
}
#main-shotmarker .edl-tl-item.has-marker:hover{
  filter: brightness(1.10);
}
#main-shotmarker .edl-tl-item.has-marker.is-selected{
  outline-color: rgba(34, 197, 94, 0.85);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.55) inset, 0 0 18px rgba(34, 197, 94, 0.22);
}

#main-shotmarker .sm-sep{
  width:1px;
  height:18px;
  background: rgba(255,255,255,0.12);
