/* Shot Marker Smart Timeline inherits EDL timeline look */
#smTimelineCard .edl-tl-meta{
  font-size: 12px;
  opacity: 0.72;
  margin-left: auto;
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
#smTimelineCard .edl-tl-viewport{
  height: 132px;
  overflow: auto;
  overflow-x: auto;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable both-edges;
  scrollbar-width: thin;
  border-radius: 16px;
  border: 1px solid rgba(194,103,255,0.28);
  background: rgba(0,0,0,0.20);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.03);
  position: relative;
}
#smTimelineCard .edl-tl-ruler{
  position: sticky;
  top: 0;
  height: 28px;
  min-width: calc(var(--edl-tl-label-w, 56px) + var(--edl-tl-content-w, 800px));
  background: rgba(0,0,0,0.36);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  z-index: 3;
}
#smTimelineCard .edl-tl-ruler .spacer{
  position: absolute;
  left: 0; top: 0;
  width: var(--edl-tl-label-w, 56px);
  height: 100%;
  background: rgba(0,0,0,0.52);
  border-right: 1px solid rgba(255,255,255,0.06);
}
#smTimelineCard .edl-tl-ruler .tick{
  position: absolute;
  top: 0; bottom: 0;
  width: 1px;
  background: rgba(255,255,255,0.12);
}
#smTimelineCard .edl-tl-ruler .label{
  position: absolute;
  top: 6px;
  transform: translateX(-50%);
  font-size: 9px;
  opacity: 0.70;
  white-space: nowrap;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
#smTimelineCard .edl-tl-tracks{
  min-width: calc(var(--edl-tl-label-w, 56px) + var(--edl-tl-content-w, 800px));
  /* tighter stack: reduce extra bottom padding so more layers fit */
  padding-bottom: 2px;
}
#smTimelineCard .edl-tl-track{
  display:flex;
  align-items: stretch;
  /* tighter video layers (match EDL timeline behavior + allow per-track var) */
  height: var(--edl-tl-row-h, 20px);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

/* Track height resize handle (drag like an NLE) */
#smTimelineCard .edl-tl-resize{
  position: absolute;
  left: 0;
  right: 0;
  bottom: -3px;
  height: 7px;
  cursor: ns-resize;
  z-index: 6;
  opacity: 0;
  transition: opacity 120ms ease;
}

#smTimelineCard .edl-tl-track:hover .edl-tl-resize,
#smTimelineCard .edl-tl-resize.is-active{
  opacity: 1;
}

#smTimelineCard .edl-tl-resize::before{
  content: "";
  position: absolute;
  left: 10px;
  right: 10px;
  top: 3px;
  height: 1px;
  background: rgba(255,255,255,0.14);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.28);
}

#smTimelineCard .edl-tl-resize::after{
  content: "";
  position: absolute;
  left: 50%;
  top: 2px;
  width: 18px;
  height: 3px;
  transform: translateX(-50%);
  border-radius: 999px;
  background: rgba(170,180,210,0.38);
}
#smTimelineCard .edl-tl-label{
  width: var(--edl-tl-label-w, 56px);
  flex: 0 0 var(--edl-tl-label-w, 56px);
  display:flex;
  align-items:center;
  justify-content:center;
  /* slightly smaller label for denser layers */
  font-size: 9px;
  opacity: 0.55;
  background: rgba(0,0,0,0.40);
  border-right: 1px solid rgba(255,255,255,0.06);
  position: sticky;
  left: 0;
  z-index: 2;
}
#smTimelineCard .edl-tl-lane{
  position: relative;
  width: var(--edl-tl-content-w, 800px);
  min-width: var(--edl-tl-content-w, 800px);
}

