}

.sm-anno-iconbtn{
  position: relative;
  width: 42px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  border: 1px solid #1e1e32;
  background: rgba(255,255,255,0.04);
  color: rgba(255,255,255,0.82);
  cursor: pointer;
  transition: transform .12s ease, background .12s ease, border-color .12s ease, box-shadow .12s ease;
}

.sm-anno-iconbtn:disabled{
  opacity: 0.35;
  cursor: default;
  transform: none;
}

.sm-anno-iconbtn:disabled:hover{
  background: rgba(16,18,24,0.18);
}

.sm-anno-iconbtn:hover{
  background: rgba(214,163,58,0.07);
  border-color: rgba(214,163,58,0.22);
}

.sm-anno-iconbtn:active{
  transform: translateY(1px);
}

.sm-anno-iconbtn svg{
  width: 18px;
  height: 18px;
  display:block;
  fill: none;
  stroke: rgba(255,255,255,0.82);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

/* Tool indicator dot (top-left) */
.sm-anno-iconbtn .bar{
  position: absolute;
  left: 8px;
  top: 7px;
  width: 2.4px;
  height: 2.4px;
  border-radius: 999px;
  background: rgba(255,255,255,0.32);
  opacity: 0.18;
}

/* Color palette */
.sm-anno-colors{
  gap: 6px;
}

.sm-anno-swatch{
