  border: 1px solid rgba(255,255,255,0.12);
  background: var(--swatch, #ff4c4c);
  padding: 0;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  transition: transform .12s ease, filter .12s ease, box-shadow .12s ease, border-color .12s ease;
}

.sm-anno-swatch:hover{
  filter: brightness(1.08);
}

.sm-anno-swatch:active{
  transform: translateY(1px);
}

.sm-anno-swatch.is-active{
  border-color: rgba(214,163,58,0.65);
