/* ============================
   ABOUT — Retro CRT panel
   ============================ */

/* ABOUT layout: avoid huge empty space on ultra-wide screens */
#main-about .about-grid{
  /* Fill the pane and start under the Project bar (no right-floating panel) */
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-self: flex-start;
}

#main-about .about-cols{
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 10px;
  align-items: start;
}

/* Group columns so the right side does not reflow when the left side expands. */
#main-about .about-left,
#main-about .about-right{
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* Lock the right column (Media Manager + Feedback) while scrolling. */
#main-about .about-right{
  position: sticky;
  top: 92px;
  align-self: start;
  max-height: calc(100vh - 120px);
  overflow: auto;
  padding-bottom: 10px;
}

#main-about .about-head{ position: sticky; top: 10px; z-index: 2; }

/* ABOUT header banner background (channels4_banner.png) */
#main-about .about-head{
  /* Banner background. Use !important to override global .card background (!important). */
  background:
    linear-gradient(180deg, rgba(8,10,14,.18), rgba(8,10,14,.38)),
    url('../assets/channels4_banner.png') center/cover no-repeat !important;
  overflow: hidden;
}

/* ABOUT — compact left column (Media Manager + Settings cards) */
#main-about .about-left{ gap: 8px; }
#main-about .about-left .card{ padding: 8px; }
#main-about .about-left .card-title{ margin-bottom: 4px; font-size: 12px; }
#main-about .about-left .muted{ font-size: 11.5px; line-height: 1.25; }

#main-about .about-left .btn,
#main-about .about-left .qs-btn{
  min-height: 30px;
  padding: 7px 10px;
  border-radius: 10px;
  font-size: 12px;
}
#main-about .about-left .btn.icon-only{
  width: 34px;
  min-width: 34px;
  min-height: 30px;
}

/* ABOUT — add visible color accents to left-column buttons */
#main-about .about-left .btn{
  --qs-bar-w: 6px;
}
#main-about .about-left .btn:not(.icon-only){
  /* keep a clear 1-character gap between the vertical glow bar and button text */
  --qs-bar-left: 10px;
  --qs-bar-gap: 1ch;
  padding-left: calc(var(--qs-bar-left) + var(--qs-bar-w) + var(--qs-bar-gap)) !important;
}
#main-about .about-left .btn .bar{
  left: 10px;
  right: auto;
  top: 50%;
  bottom: auto;
  width: var(--qs-bar-w);
  height: 14px;
  transform: translateY(-50%);
  border-radius: 999px;
  opacity: .85;
  background: var(--c-bar, var(--line-3));
  box-shadow: 0 0 10px var(--c-bar, transparent);
}
#main-about .about-left .btn:hover .bar{
  opacity: 1;
  box-shadow: 0 0 14px var(--c-bar, transparent);
}
/* Don't grey-out the bar in ABOUT — keep theme colors visible */
#main-about .about-left .btn:not(.active){
  opacity: 1;
  filter: none;
}
#main-about .about-left .btn:not(.active) .bar{
  opacity: .75;
  background: var(--c-bar, var(--line-3));
  box-shadow: 0 0 9px var(--c-bar, transparent);
}

/* ABOUT — keep theme-colored bars visible even when buttons aren't "active" */
#main-about .btn:not(.active){
  opacity: 1;
  filter: none;
}
#main-about .btn:not(.active) .bar{
  opacity: .65;
  background: var(--c-bar, var(--line-3));
  box-shadow: 0 0 8px var(--c-bar, transparent);
}

/* Override inline spacings inside cards */
#main-about .about-left .mm-grid{ margin-top: 8px !important; gap: 8px !important; }
#main-about .about-left .mm-row{ margin-top: 6px !important; gap: 6px !important; }
#main-about .about-left .mm-status{ margin-top: 6px !important; gap: 6px !important; }

@media (max-width: 1180px){
  #main-about .about-cols{ grid-template-columns: 1fr; }
  #main-about .about-head{ position: relative; top: auto; }
  #main-about .about-right{
    position: relative;
    top: auto;
    max-height: none;
    overflow: visible;
    padding-bottom: 0;
  }
}

@media (min-width: 2200px){
  #main-about .about-cols{ grid-template-columns: 1.35fr 0.65fr; }
}

.about-retro{
  position: relative;
  overflow: hidden;
  background: radial-gradient(120% 120% at 50% 40%, rgba(20,255,160,.14) 0%, rgba(0,0,0,0) 55%),
              linear-gradient(180deg, rgba(0,0,0,.70) 0%, rgba(0,0,0,.84) 100%),
              #00140d;
  border: 1px solid rgba(120,255,190,.18);
  border-radius: 16px;
  box-shadow:
    0 0 0 1px rgba(0,0,0,.35) inset,
    0 18px 60px rgba(0,0,0,.55),
    0 0 24px rgba(30,255,180,.08);
  color: rgba(170,255,215,.92);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

/* scanlines */
.about-retro::before{
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(
      180deg,
      rgba(0,0,0,.00) 0px,
      rgba(0,0,0,.00) 2px,
      rgba(0,0,0,.16) 3px
    );
  opacity: .55;
  mix-blend-mode: multiply;
}

/* subtle vignette + glow */
.about-retro::after{
  content: "";
  position: absolute;
  inset: -20px;
  pointer-events: none;
  background: radial-gradient(60% 55% at 50% 45%, rgba(40,255,190,.12) 0%, rgba(0,0,0,0) 60%),
              radial-gradient(120% 110% at 50% 50%, rgba(0,0,0,0) 40%, rgba(0,0,0,.55) 100%);
}

.about-retro .card-title,
.about-retro h4,
.about-retro li,
.about-retro .muted,
.about-retro a{
  text-shadow:
    0 0 12px rgba(30,255,180,.18),
    0 0 2px rgba(30,255,180,.22);
