/* -------------------------------------------------------------
   Shot Marker — Fold the two right-side cards (Inspector + VFX Shots List)
   to the RIGHT to give the Viewer more space.
------------------------------------------------------------- */
#main-shotmarker #smTopRow{ position: relative; }

#main-shotmarker #smSidePanelsToggle.pfx-panel-toggle{
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 25;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(0,0,0,0.28);
  color: rgba(255,255,255,0.88);
  backdrop-filter: blur(18px) saturate(1.2);
  -webkit-backdrop-filter: blur(18px) saturate(1.2);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  user-select: none;
  box-shadow: 0 10px 22px rgba(0,0,0,0.22);
}
#main-shotmarker #smSidePanelsToggle.pfx-panel-toggle:hover{
  border-color: rgba(255,255,255,0.28);
  background: rgba(0,0,0,0.34);
}
#main-shotmarker #smSidePanelsToggle.pfx-panel-toggle:active{ transform: translateY(1px); }

#main-shotmarker #smTopRow.is-panels-collapsed{
  /* Collapse ONLY the VFX Shots List (red box). Inspector must remain visible. */
  grid-template-columns: minmax(320px,1fr) 12px var(--smInspectorW, 460px) 0px !important;
  gap: 12px !important;
}
#main-shotmarker #smTopRow.is-panels-collapsed #smShotListCard{
  display: none !important;
}



/* -------------------------------------------------------------
   Shot Marker — Viewer + Inspector side-by-side (Inspector stays with Viewer)
------------------------------------------------------------- */
#main-shotmarker #smTopRow{
  display: grid;
  /* Viewer | handle | Inspector | (optional) VFX Shots List */
  grid-template-columns: minmax(320px,1fr) 12px var(--smInspectorW, 460px);
  gap: 12px;
  height: 100%;
  min-height: 0;
  min-width: 0;
  align-items: stretch;
}
#main-shotmarker #smTopRow > *{
  min-width: 0;
  min-height: 0;
}

/* Split handle (Viewer ↔ Inspector) */
#main-shotmarker #smSplitHandleVI.sm-split-handle{
  width: 12px;
  height: 100%;
  min-height: 120px;
  align-self: stretch;
  cursor: col-resize;
  border-radius: 999px;
  position: relative;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.10);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.06);
  user-select: none;
}
#main-shotmarker #smSplitHandleVI.sm-split-handle::before{
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 4px;
  height: 4px;
  border-radius: 999px;
  transform: translate(-50%, -50%);
  background: rgba(255,255,255,0.55);
  box-shadow:
    0 -7px 0 rgba(255,255,255,0.55),
    0  7px 0 rgba(255,255,255,0.55);
  opacity: .9;
}
#main-shotmarker #smSplitHandleVI.sm-split-handle:hover{
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.18);
}

/* While resizing: show a subtle purple guide line */
#main-shotmarker #smTopRow.is-resizing #smSplitHandleVI{
  border-color: rgba(180,120,255,0.55);
  box-shadow:
    0 0 0 1px rgba(180,120,255,0.35),
    0 0 16px rgba(180,120,255,0.25),
    inset 0 1px 0 rgba(255,255,255,0.08);
}
#main-shotmarker #smTopRow #smPlayerPro{
  height: 100% !important;
  min-height: 0;
}
#main-shotmarker #smTopRow #smInspectorCard{
  /* Match Viewer card height (top/bottom aligned) */
  height: 100% !important;
  max-height: 100% !important;
  min-height: 0;
  align-self: stretch;
  overflow: hidden;
}


/* Right column (VFX Shots List only) should fill the available height */
