  height: 100%;
  min-height: 0;
}
#main-shotmarker #smShotListCard.sm-ref2-shotlist-right{
  height: 100% !important;
  flex: 1 1 auto !important;
}

/* --- Shot Marker: VFX Shots List should NOT stretch to full column height (match red-box request) --- */
