  min-height: unset !important; height: unset !important;
  border-radius: 0 !important; background: none !important;
  border: none !important; gap: 8px;
}


/* =============================================================
   VFX MARKER — Smart / Space-Saving Tune
   Goal: ดูโปรขึ้น + ประหยัดพื้นที่ แต่ยังคง workflow เดิม
   (mainly: Inspector compact + actions icon-first)
============================================================= */

/* Default widths (user can still resize via split handles) */
#main-shotmarker{
  --smInspectorW: 420px;
  --smShotListW: 260px;
}

/* Tighter spacing in top row */
#main-shotmarker #smTopRow{ gap: 10px !important; }

/* Inspector compact */
#main-shotmarker .sm-inspector-top{
  grid-template-columns: 170px 1fr !important;
  gap: 10px !important;
}
#main-shotmarker .sm-inspector-thumb{ height: 92px !important; }

/* Make Jump/Del/Grab/OCR sit as a single compact row (keep DOM) */
#main-shotmarker .sm-inspector-actions-2row{
  display:flex !important;
  align-items:center;
  justify-content:flex-end;
  gap: 8px;
  flex-wrap: nowrap;
}
#main-shotmarker .sm-inspector-actions{ gap: 8px !important; }

/* Icon-first buttons (use tooltip/title for text) */
