/* Plate gen controls */
#main-shotmarker .sm-plategen{ margin-top: 6px !important; }
#main-shotmarker .sm-plategen select{ height: 28px !important; }
#main-shotmarker .sm-plategen .sm-genplate{ height: 28px !important; }

/* Note / Scope of Work area (single combined field, still resizable) */
#main-shotmarker .sm-inspector-sow textarea{ min-height: 96px !important; }
#main-shotmarker .sm-inspector-sow textarea.sm-note-input{
