/* Keyboard focus glow (Bin / Source / Timeline / Notes) */
.pfx-reviews.is-kf-bin .pfx-reviews-bin{box-shadow:0 0 0 1px rgba(152,93,255,.35),0 0 0 3px rgba(152,93,255,.14)}
.pfx-reviews.is-kf-notes .pfx-reviews-notes{box-shadow:0 0 0 1px rgba(152,93,255,.35),0 0 0 3px rgba(152,93,255,.14)}
.pfx-reviews.is-kf-source .pfx-reviews-source{box-shadow:0 0 0 1px rgba(152,93,255,.35),0 0 0 3px rgba(152,93,255,.14);border-radius:14px}
.pfx-reviews.is-kf-timeline .pfx-reviews-timeline{box-shadow:0 0 0 1px rgba(152,93,255,.35),0 0 0 3px rgba(152,93,255,.14);border-radius:14px}
.pfx-reviews-center{min-height:0;overflow:hidden;display:flex;flex-direction:column;gap:10px;min-width:0;height:100%}
.pfx-reviews-viewers{display:grid;grid-template-columns:minmax(0,1.35fr) 16px minmax(0,1fr);gap:10px;min-height:0;flex:1 1 auto;min-width:0}

/* Docked panels (requested): Bin is a dedicated card inside the red box (not overlay). */
.pfx-reviews:not(.is-notes-open) .pfx-reviews-notes{display:none}
.pfx-reviews:not(.is-bin-open) .pfx-reviews-bin{display:none}

/* Fullscreen/Cinema: hide side panels VISUALLY only (do not change Bin/Notes state).
   This prevents the bug where exiting fullscreen leaves Bin/Notes hidden.
*/
.pfx-reviews.is-fs-hide-panels .pfx-reviews-bin,
.pfx-reviews.is-fs-hide-panels .pfx-reviews-notes,
.pfx-reviews.is-fs-hide-panels .pfx-reviews-binSplitter,
.pfx-reviews.is-fs-hide-panels .pfx-reviews-binEdgeHandle{display:none!important}
.pfx-reviews.is-fs-hide-panels .pfx-reviews-layout{grid-template-columns:1fr!important}

/* Layout columns adapt to panel visibility */
.pfx-reviews.is-bin-open:not(.is-notes-open) .pfx-reviews-layout{grid-template-columns:var(--pfx-reviews-binW,420px) 1fr}
.pfx-reviews.is-bin-open.is-notes-open .pfx-reviews-layout{grid-template-columns:var(--pfx-reviews-binW,420px) 1fr 360px}
.pfx-reviews:not(.is-bin-open).is-notes-open .pfx-reviews-layout{grid-template-columns:1fr 360px}
.pfx-reviews:not(.is-bin-open):not(.is-notes-open) .pfx-reviews-layout{grid-template-columns:1fr}

/* Bin resize handle (between Bin and Center)
   - Wider hit area so users can easily grab it (even if they drag on the seam)
   - Center it in the 10px grid gap (gap=10 => +5px)
*/
.pfx-reviews-binSplitter{
  position:absolute;
  top:0;
  bottom:0;
  left:calc(var(--pfx-reviews-binW,420px) + 5px);
  transform:translateX(-50%);
  width:28px;
  z-index:80;
  touch-action:none;
}
.pfx-reviews:not(.is-bin-open) .pfx-reviews-binSplitter{display:none}
.pfx-reviews.is-drawer .pfx-reviews-binSplitter{display:none}

/* Bin edge handle (always grabbable)
   - Lives on the Bin itself, so it can never be covered by viewer overlays.
   - Wide hit area but visually subtle.
*/
.pfx-reviews-binEdgeHandle{
  position:absolute;
  top:0;
  bottom:0;
  right:-10px;
  width:20px;
  cursor:col-resize;
  z-index:80;
  touch-action:none;
}
.pfx-reviews:not(.is-bin-open) .pfx-reviews-binEdgeHandle{display:none}
.pfx-reviews.is-drawer .pfx-reviews-binEdgeHandle{display:none}
.pfx-reviews-binEdgeHandle::before{
  content:"";
  position:absolute;
  left:50%;
  top:10px;
  bottom:10px;
  width:2px;
  transform:translateX(-50%);
  background:rgba(210,210,210,.18);
  border-radius:2px;
  opacity:.65;
  transition:background .12s ease, box-shadow .12s ease, opacity .12s ease;
}
.pfx-reviews-binEdgeHandle:hover::before{
  background:rgba(230,230,230,.28);
  box-shadow:0 0 14px rgba(185,120,255,.55),0 0 4px rgba(185,120,255,.65);
  opacity:.9;
}
body.pfx-is-resizing .pfx-reviews-binEdgeHandle::before{
  background:rgba(235,235,235,.34);
  box-shadow:0 0 18px rgba(185,120,255,.65),0 0 6px rgba(185,120,255,.85);
  opacity:1;
}


/* Bin edge resize affordance (fallback): allow dragging the Bin right edge */
.pfx-reviews-bin{position:relative}
.pfx-reviews-bin.is-resize-hot{cursor:col-resize}
.pfx-reviews-bin.is-resize-hot::after{
  content:"";
  position:absolute;
  top:8px;
  bottom:8px;
  right:-8px;
  width:16px;
  border-radius:10px;
  background:rgba(185,120,255,.08);
  box-shadow:0 0 14px rgba(185,120,255,.45);
  pointer-events:none;
  opacity:.9;
}


/* Resizers (Resolve-style) — thin grey line + lilac glow on hover/drag */
.pfx-reviews-splitter{position:relative;background:transparent;border:none;border-radius:0}
.pfx-reviews-splitter::before{content:"";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);background:rgba(210,210,210,.22);border-radius:2px;opacity:.95;transition:background .12s ease,box-shadow .12s ease,opacity .12s ease}
.pfx-reviews-splitter-x{cursor:col-resize;align-self:stretch}
.pfx-reviews-splitter-x::before{width:2px;height:calc(100% - 14px)}
.pfx-reviews-splitter-y{cursor:row-resize;height:10px;margin:-4px 0}
.pfx-reviews-splitter-y::before{height:2px;width:calc(100% - 14px)}

.pfx-reviews-splitter:hover::before{background:rgba(230,230,230,.32);box-shadow:0 0 14px rgba(185,120,255,.55),0 0 4px rgba(185,120,255,.65)}
body.pfx-is-resizing .pfx-reviews-splitter::before{background:rgba(235,235,235,.38);box-shadow:0 0 18px rgba(185,120,255,.65),0 0 6px rgba(185,120,255,.85)}

/* UI Lock (Reviews): freeze layout drag handles + layout toggles (Fullscreen remains available) */
.pfx-reviews.is-ui-locked .pfx-reviews-splitter,
.pfx-reviews.is-ui-locked .pfx-reviews-binEdgeHandle{pointer-events:none;cursor:default}
.pfx-reviews.is-ui-locked .pfx-reviews-splitter::before,
.pfx-reviews.is-ui-locked .pfx-reviews-binEdgeHandle::before{opacity:.25;box-shadow:none}
.pfx-reviews.is-ui-locked .pfx-btn-bin,
.pfx-reviews.is-ui-locked .pfx-btn-notes,
.pfx-reviews.is-ui-locked .pfx-btn-view,
.pfx-reviews.is-ui-locked .pfx-reviews-binToggle{opacity:.45;filter:grayscale(.25)}

body.pfx-is-resizing{user-select:none}
.pfx-reviews-viewerWrap{display:flex;flex-direction:column;min-height:0;min-width:0}
.pfx-reviews-viewerTitle{font-size:11px;font-weight:800;opacity:.75;padding:2px 6px}
.pfx-reviews-viewerControls{display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:4px 6px;min-height:34px}
.pfx-reviews-ioText{margin-left:auto;font-size:11px;opacity:.75;white-space:nowrap}
.pfx-reviews-timelineWrap{min-height:92px;flex:0 0 auto}
.pfx-reviews-bin .pfx-reviews-card,
.pfx-reviews-notes .pfx-reviews-card{flex:1;min-height:0}

/* V1/V2 split bin: keep V1 (Ref) truly compact so V2 header sits higher */
/*
  Previous: fixed-height (flex-basis 132px + min-height 120px) made V1 reserve
  too much vertical space, pushing the V2 (Shots) header down.
*/
.pfx-reviews-bin .pfx-reviews-card--ref{flex:0 0 auto;min-height:300px;max-height:clamp(320px,52vh,460px)}
.pfx-reviews-bin .pfx-reviews-card--ref .pfx-reviews-cardBody{overflow:auto}
.pfx-reviews-bin .pfx-reviews-card--shots{flex:1 1 auto;min-height:0}
.pfx-reviews-bin .pfx-reviews-card--shots .pfx-reviews-cardBody{overflow:auto}
.pfx-reviews-refBody .pfx-reviews-clipRow{min-height:26px;padding:4px 8px}


/* Drawer mode (Resolve-style): Bin/Notes slide in as drawers, center stays full-width */
.pfx-reviews.is-drawer .pfx-reviews-layout{grid-template-columns:1fr;grid-template-rows:1fr;position:relative;height:100%}
.pfx-reviews.is-drawer .pfx-reviews-center{grid-column:1;grid-row:1}

.pfx-reviews.is-drawer .pfx-reviews-bin,
.pfx-reviews.is-drawer .pfx-reviews-notes{position:absolute;top:0;bottom:0;z-index:50;max-width:86vw;opacity:0;pointer-events:none;transition:transform .18s ease,opacity .18s ease}

.pfx-reviews.is-drawer .pfx-reviews-bin{left:0;width:320px;transform:translateX(-106%)}
.pfx-reviews.is-drawer.is-bin-open .pfx-reviews-bin{transform:translateX(0);opacity:1;pointer-events:auto}

.pfx-reviews.is-drawer .pfx-reviews-notes{right:0;width:380px;transform:translateX(106%)}
.pfx-reviews.is-drawer.is-notes-open .pfx-reviews-notes{transform:translateX(0);opacity:1;pointer-events:auto}

/* "Hide Panels" closes both drawers (handles remain for quick open) */
.pfx-reviews.is-drawer.is-panels-hidden .pfx-reviews-bin{transform:translateX(-106%);opacity:0;pointer-events:none}
.pfx-reviews.is-drawer.is-panels-hidden .pfx-reviews-notes{transform:translateX(106%);opacity:0;pointer-events:none}

/* Edge handles (visible when drawer is closed) */
.pfx-reviews-drawerHandle{position:absolute;top:50%;transform:translateY(-50%);z-index:60;border:none;border-radius:999px;padding:10px 10px;font-size:11px;font-weight:700;letter-spacing:.2px;background:rgba(0,0,0,.18);color:rgba(255,255,255,.9);backdrop-filter:blur(10px);cursor:pointer;opacity:.9}
.pfx-reviews-drawerHandle:hover{opacity:1}
.pfx-reviews-drawerHandle.is-left{left:8px}
.pfx-reviews-drawerHandle.is-right{right:8px}
.pfx-reviews.is-drawer.is-bin-open .pfx-reviews-drawerHandle.is-left{display:none}
.pfx-reviews.is-drawer.is-notes-open .pfx-reviews-drawerHandle.is-right{display:none}

@media (max-width: 1100px){
  .pfx-reviews-layout{grid-template-columns:1fr;grid-template-rows:1fr}
  .pfx-reviews-viewers{grid-template-columns:1fr}
  .pfx-reviews-splitter-x{display:none}
}

/* Viewer */
.pfx-reviews-viewer{position:relative;flex:1;min-height:240px;border-radius:12px;overflow:hidden;background:rgba(0,0,0,.06);border:1px solid rgba(0,0,0,.08)}
.pfx-reviews-video{position:absolute;inset:0;margin:0;width:100%;height:100%;object-fit:contain;border-radius:18px;box-shadow:0 10px 30px rgba(0,0,0,.35);opacity:0;transition:none;background:transparent;will-change:opacity,transform;backface-visibility:hidden;transform:translateZ(0)}
.pfx-reviews-video-overlay{z-index:4;pointer-events:none}

/* QC modes */
/* QC base vars: stack RGB isolate + Gain + Gamma */
.pfx-reviews-viewer-program{--pfx-qc-rgb:;--pfx-qc-gamma:;--pfx-qc-gain:1}
.pfx-reviews-viewer-program .pfx-reviews-video,
.pfx-reviews-viewer-program .pfx-reviews-video-overlay{filter:var(--pfx-qc-rgb) brightness(var(--pfx-qc-gain,1)) var(--pfx-qc-gamma)}

/* Gamma (luma-ish) */
.pfx-reviews-viewer-program.is-gamma{--pfx-qc-gamma:grayscale(1) contrast(1.65) brightness(1.15)}

/* Difference matte between V1 and V2 overlay */
.pfx-reviews-viewer-program.is-diff{background:#000}
.pfx-reviews-viewer-program.is-diff .pfx-reviews-video-overlay{display:block!important;opacity:1!important;mix-blend-mode:difference}
.pfx-reviews-viewer-program.is-diff .pfx-reviews-viewerHint{opacity:.65}

/* Wipe compare (V1 vs V2 overlay) */
.pfx-reviews-viewer-program.is-wipe{background:#000}
.pfx-reviews-viewer-program.is-wipe .pfx-reviews-video-overlay{display:block!important;opacity:1!important;clip-path:inset(0 calc((1 - var(--wipe, .5))*100%) 0 0)}
.pfx-reviews-wipeLine{position:absolute;top:0;bottom:0;width:2px;left:50%;transform:translateX(-1px);background:rgba(255,255,255,.70);box-shadow:0 0 0 1px rgba(0,0,0,.35),0 0 16px rgba(255,255,255,.16);opacity:0;pointer-events:none;z-index:6}
.pfx-reviews-viewer-program.is-wipe .pfx-reviews-wipeLine{opacity:1}

/* Blink compare (V1 <-> V2 overlay) */
.pfx-reviews-viewer-program.is-blink .pfx-reviews-video-overlay{display:block!important;opacity:0!important}
.pfx-reviews-viewer-program.is-blink.is-blink-on .pfx-reviews-video-overlay{opacity:1!important}
.pfx-reviews-viewerHint{position:absolute;inset:auto 12px 12px 12px;font-size:12px;opacity:.85;padding:8px 10px;border-radius:10px;background:rgba(0,0,0,.08)}
.pfx-reviews-viewerFsHint{position:absolute;inset:12px 12px auto auto;font-size:11px;opacity:.7;padding:6px 8px;border-radius:10px;background:rgba(0,0,0,.06);user-select:none;pointer-events:none}


/* QC tools: top overlay bar (Diff / Wipe / Blink / Gamma)
   Move tools to TOP so we dont cover subtitles/burn-ins at the bottom. */
.pfx-reviews-qcTop{position:absolute;left:50%;top:12px;transform:translateX(-50%) translateY(-6px);display:flex;align-items:center;gap:4px;padding:4px 6px;border-radius:14px;border:1px solid rgba(255,255,255,.08);background:rgba(18,19,26,.55);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);z-index:55;opacity:0;pointer-events:none;white-space:nowrap;transition:opacity .14s ease,transform .14s ease}
.pfx-reviews-viewerWrap:hover .pfx-reviews-qcTop,
.pfx-reviews-viewerWrap:focus-within .pfx-reviews-qcTop{opacity:1;transform:translateX(-50%) translateY(0);pointer-events:auto}
.pfx-reviews-viewer:fullscreen .pfx-reviews-qcTop{opacity:1;transform:translateX(-50%) translateY(0);pointer-events:auto}

.pfx-reviews-qcTop{box-shadow:0 14px 34px rgba(0,0,0,.28)}
.pfx-reviews-qcTop .pc-pill{height:24px;padding:0 7px;border-radius:10px;border:1px solid rgba(255,255,255,.10);background:rgba(0,0,0,.18);color:rgba(255,255,255,.92);cursor:pointer;font-weight:800;font-size:10.5px;display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:background .12s ease,border-color .12s ease,transform .12s ease}
.pfx-reviews-qcTop .pc-pill.pc-pill-sm{height:22px;padding:0 7px;border-radius:9px;font-size:10px}
.pfx-reviews-qcTop .pc-pill:hover{transform:translateY(-1px);background:rgba(0,0,0,.26);border-color:rgba(255,255,255,.16)}
.pfx-reviews-qcTop .pc-pill.is-active{background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.22)}

.pfx-reviews-qcTop .pc-wipe{width:120px;min-width:90px;max-width:160px;height:5px;border-radius:999px;appearance:none;-webkit-appearance:none;background:rgba(255,255,255,.12);outline:none}
.pfx-reviews-qcTop .pc-gain{width:110px;min-width:80px;max-width:150px}
.pfx-reviews-qcTop .pc-wipe::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:12px;height:12px;border-radius:999px;background:rgba(255,255,255,.92);border:1px solid rgba(0,0,0,.35)}
.pfx-reviews-qcTop .pc-wipe::-moz-range-thumb{width:12px;height:12px;border-radius:999px;background:rgba(255,255,255,.92);border:1px solid rgba(0,0,0,.35)}

/* Pro player controls (Resolve-like) under each viewer */
.pfx-reviews-proControls{display:flex;align-items:center;gap:8px;padding:4px 6px;border-radius:14px;border:1px solid rgba(255,255,255,.08);background:rgba(18,19,26,.55);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}
.pfx-reviews-proControls .pc-left{display:flex;align-items:center;gap:6px;min-width:0;flex:1}
.pfx-reviews-proControls .pc-qc{display:flex;align-items:center;gap:4px;padding:3px;border-radius:12px;border:1px solid rgba(255,255,255,.06);background:rgba(0,0,0,.12)}
.pfx-reviews-proControls .pc-btnGroup{display:flex;align-items:center;gap:4px;padding:3px;border-radius:12px;border:1px solid rgba(255,255,255,.08);background:rgba(0,0,0,.18)}
.pfx-reviews-proControls .pc-btn{width:24px;height:24px;border-radius:9px;border:1px solid rgba(255,255,255,.08);background:rgba(0,0,0,.20);color:rgba(255,255,255,.92);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-size:11px;line-height:1;transition:transform .12s ease,background .12s ease,border-color .12s ease}
.pfx-reviews-proControls .pc-btn:hover{transform:translateY(-1px);background:rgba(0,0,0,.28);border-color:rgba(255,255,255,.14)}
.pfx-reviews-proControls .pc-btn.pc-play{background:rgba(255,0,0,.14);border-color:rgba(255,0,0,.26)}
.pfx-reviews-proControls .pc-btn.pc-play:hover{background:rgba(255,0,0,.18);border-color:rgba(255,0,0,.34)}
.pfx-reviews-proControls .pc-btn.pfx-iconbtn,
.pfx-reviews-proControls .pc-btn.pfx-playbtn{
  min-width:24px;
  width:24px;
  height:24px;
  padding-left:0;
  padding-right:0;
}
.pfx-reviews-proControls .pc-btn.pfx-iconbtn .pfx-ib-ico,
.pfx-reviews-proControls .pc-btn.pfx-playbtn .pfx-playico{
  width:13px;
  height:13px;
}
.pfx-reviews-proControls .pc-btn.pfx-iconbtn .pfx-ib-ico svg,
.pfx-reviews-proControls .pc-btn.pfx-playbtn .pfx-playico svg{
  width:13px;
  height:13px;
  fill:none;
  stroke:currentColor;
  stroke-width:2;
  stroke-linecap:round;
  stroke-linejoin:round;
}
.pfx-reviews-proControls .pc-pill{height:24px;padding:0 7px;border-radius:10px;border:1px solid rgba(255,255,255,.10);background:rgba(0,0,0,.18);color:rgba(255,255,255,.92);cursor:pointer;font-weight:800;font-size:10.5px;display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:background .12s ease,border-color .12s ease,transform .12s ease}
.pfx-reviews-proControls .pc-pill.pc-pill-sm{height:22px;padding:0 7px;border-radius:9px;font-size:10px}
.pfx-reviews-proControls .pc-pill:hover{transform:translateY(-1px);background:rgba(0,0,0,.26);border-color:rgba(255,255,255,.16)}
.pfx-reviews-proControls .pc-pill.is-active{background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.22)}
.pfx-reviews-proControls .pc-pill.pfx-lblbtn{ gap:6px; }
.pfx-reviews-proControls .pc-pill.pfx-lblbtn .pfx-lbl-ico{ width:13px; height:13px; }
.pfx-reviews-proControls .pc-pill.pfx-lblbtn .pfx-lbl-ico svg{ width:13px; height:13px; fill:none; stroke:currentColor; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }
.pfx-reviews-notesHeaderRight .pfx-lblbtn{ gap:6px; }
.pfx-reviews-notesHeaderRight .pfx-lblbtn .pfx-lbl-ico{ width:13px; height:13px; }
.pfx-reviews-notesHeaderRight .pfx-lblbtn .pfx-lbl-ico svg{ width:13px; height:13px; fill:none; stroke:currentColor; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }
.pfx-reviews-proControls .pc-pill-accent{background:rgba(255,0,0,.10);border-color:rgba(255,0,0,.22)}
.pfx-reviews-proControls .pc-pill-accent:hover{background:rgba(255,0,0,.14);border-color:rgba(255,0,0,.30)}
.pfx-reviews-proControls .pc-io{display:flex;align-items:center;gap:4px}
.pfx-reviews-proControls .pc-scrub{flex:1;min-width:200px;max-width:680px;height:5px;border-radius:999px;appearance:none;-webkit-appearance:none;background:rgba(255,255,255,.14);outline:none}
.pfx-reviews-proControls .pc-scrub::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:12px;height:12px;border-radius:999px;background:rgba(255,255,255,.92);border:1px solid rgba(0,0,0,.35)}
.pfx-reviews-proControls .pc-scrub::-moz-range-thumb{width:12px;height:12px;border-radius:999px;background:rgba(255,255,255,.92);border:1px solid rgba(0,0,0,.35)}

.pfx-reviews-proControls .pc-wipe{width:120px;min-width:90px;max-width:160px;height:5px;border-radius:999px;appearance:none;-webkit-appearance:none;background:rgba(255,255,255,.12);outline:none}
.pfx-reviews-proControls .pc-wipe::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:12px;height:12px;border-radius:999px;background:rgba(255,255,255,.92);border:1px solid rgba(0,0,0,.35)}
.pfx-reviews-proControls .pc-wipe::-moz-range-thumb{width:12px;height:12px;border-radius:999px;background:rgba(255,255,255,.92);border:1px solid rgba(0,0,0,.35)}

/* Timeline scrub bar as an overlay inside the viewer (more pro / less clutter) */
.pfx-reviews-scrubOverlay{position:absolute;left:50%;bottom:12px;transform:translateX(-50%);width:min(720px,72%);padding:10px 14px;border-radius:999px;background:rgba(10,10,14,.42);border:1px solid rgba(255,255,255,.10);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 14px 34px rgba(0,0,0,.35);z-index:5;opacity:0;pointer-events:none;transition:opacity .15s ease,transform .15s ease}
.pfx-reviews-scrubOverlay .pc-scrub{width:100%;min-width:0;max-width:none;flex:none;pointer-events:auto}
.pfx-reviews-viewer:hover .pfx-reviews-scrubOverlay,
.pfx-reviews-viewer.is-scrub-overlay .pfx-reviews-scrubOverlay{opacity:1;pointer-events:auto}
.pfx-reviews-proControls .pc-dots{display:flex;align-items:center;gap:4px;opacity:.55}
.pfx-reviews-proControls .pc-dots span{width:5px;height:5px;border-radius:999px;background:rgba(255,255,255,.55)}
.pfx-reviews-proControls .pc-right{display:flex;align-items:center;gap:6px;min-width:0;justify-content:flex-end}
.pfx-reviews-proControls .pc-count{padding:4px 8px;border-radius:999px;border:1px solid rgba(255,255,255,.10);background:rgba(0,0,0,.18);font-weight:900;font-size:10.5px;color:rgba(255,255,255,.9)}
.pfx-reviews-proControls .pc-rec{padding:4px 8px;border-radius:999px;border:1px solid rgba(255,0,0,.20);background:rgba(255,0,0,.08);font-weight:900;font-size:10.5px;letter-spacing:.2px;color:rgba(255,255,255,.92)}

/* Smart: make pro controls overlay inside viewer (more room for image) */
.pfx-reviews-viewerWrap{position:relative}
.pfx-reviews-proControls{position:absolute;left:50%;bottom:58px;transform:translateX(-50%) translateY(6px);opacity:0;pointer-events:none;z-index:40;max-width:calc(100% - 18px);white-space:nowrap;transition:opacity .14s ease,transform .14s ease}
.pfx-reviews-viewerWrap:hover .pfx-reviews-proControls,
.pfx-reviews-viewerWrap:focus-within .pfx-reviews-proControls{opacity:1;transform:translateX(-50%) translateY(0);pointer-events:auto}

/* When dragging scrub overlay, keep controls visible */
.pfx-reviews-viewer.is-scrub-overlay + .pfx-reviews-proControls{opacity:1;transform:translateX(-50%) translateY(0);pointer-events:auto}


/* Compact Source viewer transport: single bottom capsule like QuickTime */
.pfx-reviews-proControls-sourceCompact{
  left:50%;
  bottom:12px;
  gap:6px;
  padding:5px 8px;
  width:min(calc(100% - 20px), 720px);
  max-width:min(calc(100% - 20px), 720px);
  justify-content:center;
}
.pfx-reviews-proControls-sourceCompact .pc-left{flex:0 0 auto; min-width:auto; gap:4px}
.pfx-reviews-proControls-sourceCompact .pc-btnGroup{
  gap:3px;
  padding:2px;
  border-radius:999px;
}
.pfx-reviews-proControls-sourceCompact .pc-btn,
.pfx-reviews-proControls-sourceCompact .pc-btn.pfx-iconbtn,
.pfx-reviews-proControls-sourceCompact .pc-btn.pfx-playbtn{
  width:22px;
  min-width:22px;
  height:22px;
  border-radius:999px;
}
.pfx-reviews-proControls-sourceCompact .pc-btn.pfx-iconbtn .pfx-ib-ico,
.pfx-reviews-proControls-sourceCompact .pc-btn.pfx-playbtn .pfx-playico{
  width:12px;
  height:12px;
}
.pfx-reviews-proControls-sourceCompact .pc-scrub{
  flex:1 1 180px;
  min-width:160px;
  max-width:none;
}
.pfx-reviews-proControls-sourceCompact .pc-io{
  flex:0 0 auto;
  gap:3px;
  align-items:center;
}
.pfx-reviews-proControls-sourceCompact .pc-pill{
  height:22px;
  padding:0 6px;
  border-radius:999px;
  font-size:10px;
}
.pfx-reviews-proControls-sourceCompact .pc-right{
  flex:0 0 auto;
  gap:4px;
  min-width:auto;
}
.pfx-reviews-proControls-sourceCompact .pc-count,
.pfx-reviews-proControls-sourceCompact .pc-rec{
  padding:3px 6px;
  font-size:10px;
  white-space:nowrap;
}
.pfx-reviews-proControls-sourceCompact .pc-rec{
  max-width:122px;
  overflow:hidden;
  text-overflow:ellipsis;
}
.pfx-reviews-proControls-sourceCompact .pc-dots{display:none}
.pfx-reviews-viewerWrap:hover .pfx-reviews-proControls-sourceCompact,
.pfx-reviews-viewerWrap:focus-within .pfx-reviews-proControls-sourceCompact,
.pfx-reviews-viewer.is-scrub-overlay .pfx-reviews-proControls-sourceCompact,
.pfx-reviews-viewer.is-scrub-overlay + .pfx-reviews-proControls-sourceCompact{
  opacity:1;
  transform:translateX(-50%) translateY(0);
  pointer-events:auto;
}
@media (max-width: 1320px){
  .pfx-reviews-proControls-sourceCompact{
    width:min(calc(100% - 16px), 640px);
    gap:5px;
    padding:4px 7px;
  }
  .pfx-reviews-proControls-sourceCompact .pc-scrub{ min-width:120px; }
  .pfx-reviews-proControls-sourceCompact .pc-pill{ padding:0 5px; font-size:9.5px; }
  .pfx-reviews-proControls-sourceCompact .pc-rec{ max-width:108px; }
}

/* === True QuickTime Full Screen (viewer only) === */
.pfx-reviews-viewer:fullscreen{width:100vw!important;height:100vh!important;min-height:100vh!important;max-height:100vh!important;border-radius:0!important;border:none!important;background:#000!important}
.pfx-reviews-viewer:fullscreen .pfx-reviews-video{border-radius:0;box-shadow:none}
.pfx-reviews-viewer:fullscreen .pfx-reviews-viewerHint,
.pfx-reviews-viewer:fullscreen .pfx-reviews-viewerFsHint{display:none!important}


/* When viewer is in fullscreen, hide control rows to keep it clean */
.pfx-reviews.is-viewer-fs .pfx-reviews-viewerControls{display:none!important}

/* Fallback "cinema" mode when Fullscreen API is blocked */
.pfx-reviews.is-cinema-viewer{position:relative}
.pfx-reviews.is-cinema-viewer .pfx-reviews-toolbar,
.pfx-reviews.is-cinema-viewer .pfx-reviews-status,
.pfx-reviews.is-cinema-viewer .pfx-reviews-timeline,
.pfx-reviews.is-cinema-viewer .pfx-reviews-bin,
.pfx-reviews.is-cinema-viewer .pfx-reviews-notes,
.pfx-reviews.is-cinema-viewer .pfx-reviews-viewerControls{display:none!important}
.pfx-reviews.is-cinema-viewer .pfx-reviews-drawerHandle{display:none!important}
.pfx-reviews.is-cinema-viewer .pfx-reviews-viewer{position:fixed!important;inset:0!important;z-index:999999!important;border-radius:0!important;border:none!important;background:#000!important}
.pfx-reviews.is-cinema-viewer .pfx-reviews-video{border-radius:0;box-shadow:none}
.pfx-reviews.is-cinema-viewer .pfx-reviews-viewerHint,
.pfx-reviews.is-cinema-viewer .pfx-reviews-viewerFsHint{display:none!important}
.pfx-reviews.is-drag .pfx-reviews-viewer{outline:2px dashed rgba(0,0,0,.25)}

/* Fullscreen / Cinema mode for Reviews (maximize viewer for continuity review) */
.pfx-reviews.is-fs{width:100vw;height:100vh;max-width:100vw;max-height:100vh;padding:10px;box-sizing:border-box;background:rgba(0,0,0,.06);border-radius:16px}
.pfx-reviews:fullscreen{width:100vw;height:100vh}

/* CSS fallback if Fullscreen API is blocked */
.pfx-reviews.is-cinema{position:fixed;inset:10px;z-index:999999;border-radius:16px;padding:10px;background:rgba(0,0,0,.10);backdrop-filter:blur(10px)}

/* Timeline (2 video layers: V2 overlay + V1 base) */
.pfx-reviews-timeline{height:118px;border-radius:12px;border:1px solid rgba(0,0,0,.08);background:rgba(0,0,0,.04);overflow:hidden}
.pfx-reviews-timelineScroll{height:100%;overflow:auto;position:relative}
.pfx-reviews-timelineInner{height:100%;position:relative}
.pfx-reviews-segRow{position:absolute;left:0;right:0;height:30px}
.pfx-reviews-segRowV2{top:10px;display:block}
.pfx-reviews-segRowV1{top:46px;display:flex}

.pfx-reviews-seg{--segColor:255,255,255;position:relative;height:30px;border-right:1px solid rgba(255,255,255,.04);background:rgba(var(--segColor),.10);cursor:pointer;border-radius:8px;overflow:hidden}
.pfx-reviews-seg::before{content:"";position:absolute;left:0;right:0;top:0;height:3px;background:rgba(var(--segColor),.65)}
.pfx-reviews-seg.is-v1{position:relative;border-radius:0;background:rgba(var(--segColor),.08)}
.pfx-reviews-seg.is-v2{position:absolute;border:1px solid rgba(var(--segColor),.22);background:rgba(var(--segColor),.12)}

/* Active: keep clip color, add red NLE-style outline */
.pfx-reviews-seg.is-active{box-shadow:0 0 0 2px rgba(255,0,0,.35) inset, 0 6px 14px rgba(0,0,0,.25);filter:brightness(1.08)}
.pfx-reviews-seg.is-disabled{opacity:.45;filter:grayscale(1)}
.pfx-reviews-segLabel{position:absolute;left:8px;right:22px;top:7px;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:rgba(255,255,255,.92);text-shadow:0 1px 1px rgba(0,0,0,.25);opacity:.95}
.pfx-reviews-seg.has-segnum .pfx-reviews-segLabel{right:54px}
.pfx-reviews-seg.has-ver .pfx-reviews-segLabel{right:calc(50% + 36px)}
.pfx-reviews-seg.has-ver.has-segnum .pfx-reviews-segLabel{right:calc(50% + 92px)}
.pfx-reviews-segNum{position:absolute;right:8px;top:5px;height:18px;min-width:34px;padding:0 7px;border-radius:999px;border:1px solid rgba(0,0,0,.18);background:rgba(0,0,0,.28);color:rgba(255,255,255,.92);font-size:10px;line-height:18px;font-weight:800;letter-spacing:.04em;text-align:center;pointer-events:none;opacity:.92}
.pfx-reviews-seg:hover .pfx-reviews-segNum,.pfx-reviews-seg.is-active .pfx-reviews-segNum{background:rgba(0,0,0,.36)}
.pfx-reviews-segX{position:absolute;right:4px;top:4px;width:18px;height:18px;border-radius:6px;border:1px solid rgba(0,0,0,.18);background:rgba(255,255,255,.55);font-size:12px;line-height:16px;padding:0;cursor:pointer;opacity:0;pointer-events:none;transition:opacity .12s ease}
.pfx-reviews-seg:hover .pfx-reviews-segX,.pfx-reviews-seg.is-active .pfx-reviews-segX{opacity:.85;pointer-events:auto}
.pfx-reviews-segX:hover{opacity:1}

/* V2 Version pill (smart swap) */
.pfx-reviews-segVer{position:absolute;left:50%;right:auto;top:4px;height:20px;min-width:70px;max-width:calc(100% - 34px);padding:0 11px;border-radius:999px;border:1px solid rgba(255,255,255,.12);background:rgba(14,16,22,.58);box-shadow:0 1px 0 rgba(255,255,255,.08) inset,0 4px 10px rgba(0,0,0,.18);color:rgba(255,255,255,.96);font-size:11px;font-weight:800;line-height:20px;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer;opacity:.88;z-index:2;transform:translateX(-50%);transition:opacity .12s ease, transform .12s ease;display:inline-flex;align-items:center;justify-content:center;gap:5px}
.pfx-reviews-segVerIcon{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;width:12px;height:12px;opacity:.92}
.pfx-reviews-segVerIcon svg{display:block;width:12px;height:12px;stroke:currentColor;stroke-width:2;fill:none;stroke-linecap:round;stroke-linejoin:round}
.pfx-reviews-segVerText{display:inline-block;min-width:0;overflow:hidden;text-overflow:ellipsis}
.pfx-reviews-seg:hover .pfx-reviews-segVer,.pfx-reviews-seg.is-active .pfx-reviews-segVer{opacity:1}
.pfx-reviews-segVer:active{transform:translateX(-50%) scale(.98)}

.pfx-reviews-verMenu{position:fixed;z-index:99999;min-width:260px;max-width:420px;max-height:300px;overflow:auto;border-radius:14px;padding:8px;background:rgba(20,22,26,.92);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.10);box-shadow:0 12px 30px rgba(0,0,0,.45)}
.pfx-reviews-verMenuHead{padding:6px 10px 8px;color:rgba(255,255,255,.80);font-size:11px;letter-spacing:.02em;text-transform:uppercase}
.pfx-reviews-verMenuItem{display:block;width:100%;text-align:left;border:0;border-radius:10px;padding:8px 10px;margin:2px 0;background:transparent;color:rgba(255,255,255,.92);font-size:12px;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pfx-reviews-verMenuItem:hover{background:rgba(255,255,255,.08)}
.pfx-reviews-verMenuItem.is-active{background:rgba(255,255,255,.12);box-shadow:0 0 0 1px rgba(255,255,255,.10) inset}
.pfx-reviews-markersLayer{position:absolute;left:0;right:0;top:0;bottom:0;pointer-events:none}
.pfx-reviews-marker{position:absolute;top:6px;bottom:6px;width:2px;background:rgba(0,180,0,.8);pointer-events:auto;cursor:pointer}
.pfx-reviews-marker.is-selected{background:rgba(255,0,0,.9)}
.pfx-reviews-playhead{position:absolute;top:0;bottom:0;width:2px;background:rgba(255,0,0,.95);pointer-events:none;will-change:transform}
.pfx-reviews-cutLayer{position:absolute;inset:0;pointer-events:none;z-index:3}
.pfx-reviews-cutLayer--uncertain{z-index:4}
.pfx-reviews-cutLayer--uncertain .pfx-reviews-cutMarker{top:3px;bottom:auto;height:12px;border-left-width:2px;filter:drop-shadow(0 0 4px rgba(255,214,107,.12))}
.pfx-reviews-cutLayer--uncertain .pfx-reviews-cutMarker::after{top:0}
/* Visual QC: scene-cut boundaries should read as subtle guides, not dominant red dividers. */
.pfx-reviews-cutMarker{position:absolute;top:8px;bottom:8px;width:0;border:0;border-left:1px solid rgba(255,96,96,.34);background:transparent;pointer-events:auto;cursor:pointer;transform:translateX(-.5px);opacity:.42}
.pfx-reviews-cutMarker::after{content:'';position:absolute;left:-3px;top:0;width:6px;height:6px;border-radius:999px;background:rgba(255,96,96,.38);box-shadow:0 0 0 1px rgba(0,0,0,.14),0 0 6px rgba(255,96,96,.10)}
.pfx-reviews-cutMarker.is-selected{border-left-width:2px;border-left-color:rgba(255,128,128,.88);opacity:.96;filter:drop-shadow(0 0 6px rgba(255,255,255,.14))}
.pfx-reviews-cutMarker.is-selected::after{transform:scale(1.1);background:rgba(255,128,128,.92);box-shadow:0 0 0 1px rgba(255,255,255,.32),0 0 12px rgba(255,255,255,.12)}
.pfx-reviews-cutMarker.is-uncertain{border-left-color:rgba(255,214,107,.52)}
.pfx-reviews-cutMarker.is-uncertain::after{background:rgba(255,214,107,.58)}
.pfx-reviews-cutMarker.is-fade_like{border-left-color:rgba(186,132,255,.48)}
.pfx-reviews-cutMarker.is-fade_like::after{background:rgba(186,132,255,.54)}
.pfx-reviews-cutMarker.is-motion_break{border-left-color:rgba(96,198,255,.50)}
.pfx-reviews-cutMarker.is-motion_break::after{background:rgba(96,198,255,.56)}
.pfx-reviews-cutMarker.is-flash_cut{border-left-color:rgba(255,160,88,.52)}
.pfx-reviews-cutMarker.is-flash_cut::after{background:rgba(255,160,88,.58)}
.pfx-reviews-timeBadge{position:absolute;top:84px;transform:translateX(-50%);font-size:11px;padding:2px 6px;border-radius:999px;background:rgba(0,0,0,.08);white-space:nowrap;pointer-events:none;will-change:left}

/* Cards */
.pfx-reviews-card{border:1px solid rgba(0,0,0,.08);border-radius:12px;background:rgba(0,0,0,.03);overflow:hidden;display:flex;flex-direction:column;min-height:0}
.pfx-reviews-cardHeader{display:flex;align-items:center;justify-content:space-between;padding:8px 10px;border-bottom:1px solid rgba(0,0,0,.08)}
.pfx-reviews-cardTitle{font-weight:700;font-size:12px;opacity:.9}
.pfx-reviews-cardBody{padding:8px 8px;overflow:auto;min-height:0;display:flex;flex-direction:column;gap:8px}

/* Clips */
.pfx-reviews-clipRow{display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid rgba(0,0,0,.08);border-radius:10px;background:rgba(255,255,255,.4)}
.pfx-reviews-clipRow.is-active{border-color:rgba(255,0,0,.25);background:rgba(255,0,0,.04)}
.pfx-reviews-clipRow.is-selected{border-color:rgba(0,0,0,.22);background:rgba(0,0,0,.03)}
.pfx-reviews-clipRow.is-disabled{opacity:.55}
.pfx-reviews-clipName{font-size:12px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pfx-reviews-clipMeta{display:flex;gap:6px;align-items:center}
.pfx-reviews-clipTC{flex:1;min-width:120px;font-size:12px;padding:6px 8px;border-radius:10px;border:1px solid rgba(0,0,0,.12);background:rgba(255,255,255,.8)}

/* Markers */
.pfx-reviews-markerEditor{display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid rgba(0,0,0,.08);border-radius:10px;background:rgba(255,255,255,.45)}
.pfx-reviews-markerMeta{font-size:12px;font-weight:700;opacity:.9}
.pfx-reviews-markerNote{width:100%;min-height:60px;resize:vertical;font-size:12px;padding:8px;border-radius:10px;border:1px solid rgba(0,0,0,.12);background:rgba(255,255,255,.85)}
.pfx-reviews-markerActions{display:flex;gap:6px;justify-content:flex-end}
.pfx-reviews-markerList{display:flex;flex-direction:column;gap:6px}
.pfx-reviews-markerRow{padding:8px;border:1px solid rgba(0,0,0,.08);border-radius:10px;background:rgba(255,255,255,.4);cursor:pointer}
.pfx-reviews-markerRow.is-active{border-color:rgba(255,0,0,.25);background:rgba(255,0,0,.04)}
.pfx-reviews-markerTime{font-size:12px;font-weight:800}
.pfx-reviews-markerText{font-size:12px;opacity:.9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pfx-reviews-markerSub{font-size:11px;opacity:.7;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.pfx-reviews-markerStatusRow{display:flex;gap:6px;flex-wrap:wrap}
.pfx-reviews-markerTagsRow{display:flex;gap:6px;flex-wrap:wrap}
.pfx-reviews-markerSelect{flex:1;min-width:140px;font-size:12px;padding:8px;border-radius:10px;border:1px solid rgba(0,0,0,.12);background:rgba(255,255,255,.85)}
.pfx-reviews-markerSelect:disabled{opacity:.6;cursor:not-allowed}
.pfx-pill-status{padding:6px 10px;border-radius:999px;border:1px solid var(--line-2);background:#14151b;color:var(--txt);font-size:11px;font-weight:700;cursor:pointer;opacity:.85}
.pfx-pill-status:hover{opacity:1;border-color:var(--line-3)}
.pfx-pill-status.is-active{box-shadow:0 0 0 2px rgba(255,255,255,.06) inset;opacity:1}
.pfx-pill-status[data-status="APPROVED"].is-active{border-color:rgba(0,255,160,.35);box-shadow:0 0 0 2px rgba(0,255,160,.10) inset}
.pfx-pill-status[data-status="NEED_FIX"].is-active{border-color:rgba(255,60,60,.40);box-shadow:0 0 0 2px rgba(255,60,60,.12) inset}
.pfx-pill-status[data-status="HOLD"].is-active{border-color:rgba(255,200,0,.40);box-shadow:0 0 0 2px rgba(255,200,0,.12) inset}

.pfx-reviews-markerThumbWrap{display:flex;flex-direction:column;gap:6px}
.pfx-reviews-markerThumb{width:100%;max-height:180px;object-fit:contain;border-radius:10px;border:1px solid rgba(255,255,255,.08);background:rgba(0,0,0,.18)}
.pfx-reviews-btnAnnotate{align-self:flex-end;padding:6px 10px}

.pfx-reviews-markerRow{display:flex;gap:8px;align-items:stretch}
.pfx-reviews-markerLeft{flex:0 0 auto;display:flex;align-items:center}
.pfx-reviews-markerMiniThumb{width:54px;height:34px;object-fit:cover;border-radius:8px;border:1px solid rgba(255,255,255,.08);background:rgba(0,0,0,.15)}
.pfx-reviews-markerMid{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.pfx-reviews-markerRight{flex:0 0 auto;display:flex;align-items:flex-start}
.pfx-reviews-markerBadge{padding:6px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.10);background:rgba(0,0,0,.18);font-size:11px;font-weight:800;opacity:.9;white-space:nowrap}
.pfx-reviews-markerBadge[data-status="APPROVED"]{border-color:rgba(0,255,160,.22)}
.pfx-reviews-markerBadge[data-status="NEED_FIX"]{border-color:rgba(255,60,60,.26)}
.pfx-reviews-markerBadge[data-status="HOLD"]{border-color:rgba(255,200,0,.26)}

/* Annotate modal */
.pfx-anno-modal{position:fixed;inset:0;z-index:999999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.55);backdrop-filter:blur(6px)}
.pfx-anno-sheet{width:min(980px, calc(100vw - 30px));max-height:calc(100vh - 40px);background:#111217;border:1px solid rgba(255,255,255,.10);border-radius:14px;overflow:hidden;box-shadow:0 22px 70px rgba(0,0,0,.55);display:flex;flex-direction:column}
.pfx-anno-top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.08)}
