.pfx-anno-tools .pfx-pill.is-active{box-shadow:0 0 0 2px rgba(255,255,255,.06) inset}

/* Controls (fallback if your UI doesn't have these) */
.pfx-btn{font-size:12px;padding:6px 10px;border-radius:10px;border:1px solid rgba(0,0,0,.12);background:rgba(255,255,255,.65);cursor:pointer}
.pfx-btn:hover{background:rgba(255,255,255,.85)}

/* Clean Feed toolbar button: icon-only monitor */
