.pfx-btn-clean .pfx-ic-monitor{font-size:14px;line-height:1;display:inline-block;transform:translateY(-.5px)}
.pfx-btn-primary{background:rgba(255,0,0,.14);border-color:rgba(255,0,0,.18)}
.pfx-btn-ghost{background:transparent}
.pfx-select{font-size:12px;padding:6px 8px;border-radius:10px;border:1px solid rgba(0,0,0,.12);background:rgba(255,255,255,.65)}
.pfx-reviews-zoomWrap{display:flex;align-items:center;gap:6px}
.pfx-reviews-zoomLabel{font-size:12px;opacity:.8}
