/* ===== PostFlowX – VFX Reviews: Theme-matched controls (dark) ===== */
.pfx-reviews .pfx-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:6px;
  padding:10px 14px;
  min-height:34px;
  font-size:12px;
  font-weight:600;
  letter-spacing:.15px;
  border-radius:10px;
  border:1px solid var(--line-2);
  background:#16171d;
  color:var(--txt);
  cursor:pointer;
  user-select:none;
  transition:transform .15s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease, color .15s ease;
}

/* Icon-only toolbar buttons (compact square) */
.pfx-reviews .pfx-btn-icon{
  padding:8px 10px;
  min-width:34px;
  gap:0;
}
.pfx-reviews .pfx-btn-icon .pfx-ic-svg{
  width:14px;
  height:14px;
  display:block;
}

.pfx-reviews .pfx-btn-icon.pfx-iconbtn .pfx-ib-ico{
  width:14px;
  height:14px;
}
.pfx-reviews .pfx-btn-icon.pfx-iconbtn .pfx-ib-ico svg,
.pfx-reviews .pfx-btn-icon.pfx-iconbtn .pfx-ib-ico svg *{
  fill:none !important;
  stroke:currentColor !important;
  stroke-width:2 !important;
  stroke-linecap:round !important;
  stroke-linejoin:round !important;
}
.pfx-reviews .pfx-reviews-sceneCutBtn.pfx-iconbtn .pfx-ib-ico{
  width:18px;
  height:18px;
}
.pfx-reviews .pfx-reviews-sceneCutBtn.pfx-iconbtn .pfx-ib-ico svg{
  width:18px;
  height:18px;
}

.pfx-reviews .pfx-btn:hover{
  background:#1a1b22;
  border-color:var(--line-3);
  transform:translateY(-1px);
  box-shadow:0 6px 14px rgba(0,0,0,.25);
}
.pfx-reviews .pfx-btn:active{ transform:translateY(0); box-shadow:none; }
.pfx-reviews .pfx-btn:disabled{ opacity:.5; cursor:not-allowed; transform:none; box-shadow:none; }

/* Primary (Play / main action) */
.pfx-reviews .pfx-btn-primary{
  background:rgba(255,0,0,.10);
  border-color:rgba(255,0,0,.28);
  color:var(--txt);
  box-shadow:0 0 10px rgba(255,0,0,.10);
}
.pfx-reviews .pfx-btn-primary:hover{
  background:rgba(255,0,0,.14);
  border-color:rgba(255,0,0,.36);
  box-shadow:0 0 14px rgba(255,0,0,.16);
}

/* Ghost (secondary text buttons) */
.pfx-reviews .pfx-btn-ghost{
  background:transparent;
  border-color:transparent;
  color:var(--muted);
  box-shadow:none;
}
.pfx-reviews .pfx-btn-ghost:hover{
  background:#16171d;
  border-color:var(--line-2);
  color:var(--txt);
}

/* Danger */
.pfx-reviews .pfx-btn-danger{
  border-color:rgba(255,80,80,.28);
}
.pfx-reviews .pfx-btn-danger:hover{
  border-color:rgba(255,80,80,.40);
  box-shadow:0 0 12px rgba(255,80,80,.10);
}

/* Toggle highlight states */
.pfx-reviews.is-bin-open .pfx-btn-bin,
.pfx-reviews.is-notes-open .pfx-btn-notes,
.pfx-reviews.is-panels-hidden .pfx-btn-panels,
.pfx-reviews.is-viewer-fs .pfx-btn-full,
.pfx-reviews.is-cinema-viewer .pfx-btn-full{
  background:#1b1c23;
  border-color:var(--line-3);
  color:var(--txt);
  box-shadow:0 0 10px rgba(255,255,255,.06);
}

/* Select (FPS) */
.pfx-reviews .pfx-select{
  min-height:34px;
  font-size:12px;
  font-weight:600;
  padding:8px 10px;
  border-radius:10px;
  border:1px solid var(--line-2);
  background:#16171d;
  color:var(--txt);
  outline:none;
}
.pfx-reviews .pfx-select:hover{ border-color:var(--line-3); background:#1a1b22; }
.pfx-reviews .pfx-select:focus{ border-color:color-mix(in srgb, var(--line-3) 70%, #74b0c9 30%); }

/* Range (Zoom) */
.pfx-reviews .pfx-reviews-zoom{
  -webkit-appearance:none;
  appearance:none;
  height:4px;
  border-radius:999px;
  background:var(--line-2);
  outline:none;
}
.pfx-reviews .pfx-reviews-zoom::-webkit-slider-thumb{
  -webkit-appearance:none;
  appearance:none;
  width:12px;
  height:12px;
  border-radius:999px;
  background:rgba(255,255,255,.85);
  border:1px solid rgba(0,0,0,.25);
}
.pfx-reviews .pfx-reviews-zoom::-moz-range-thumb{
  width:12px;
  height:12px;
  border-radius:999px;
  background:rgba(255,255,255,.85);
  border:1px solid rgba(0,0,0,.25);
}

/* Drawer edge handles: match theme */
.pfx-reviews .pfx-reviews-drawerHandle{
  border:1px solid var(--line-2);
  background:rgba(22,23,29,.86);
  color:var(--txt);
  box-shadow:0 10px 22px rgba(0,0,0,.28);
}
.pfx-reviews .pfx-reviews-drawerHandle:hover{ border-color:var(--line-3); background:rgba(26,27,34,.92); }

/* ===== VFX Reviews: 1 View / 2 View toggle ===== */
.pfx-reviews.is-oneview .pfx-reviews-viewers{grid-template-columns:1fr!important}
.pfx-reviews.is-oneview .pfx-reviews-splitter-x{display:none!important}
