.pfx-reviews.is-oneview.oneview-source .pfx-reviews-viewers > .pfx-reviews-viewerWrap:last-child{display:none!important}

/* ===== VFX Reviews: Compact smarter action group (right side) ===== */
.pfx-reviews-toolbarGroup{display:flex;align-items:center;gap:6px;position:relative;padding:3px 6px;border-radius:14px;border:1px solid var(--line-2);background:rgba(0,0,0,.10);backdrop-filter:blur(10px)}
.pfx-reviews-toolbarGroup .pfx-btn{padding:6px 10px;min-height:28px;font-size:11px;border-radius:10px;white-space:nowrap}
.pfx-reviews-toolbarGroup .pfx-btn-ghost{padding:6px 9px}
.pfx-reviews-toolbarGroup .pfx-btn-exportMenu.is-open{background:#1b1c23;border-color:var(--line-3);color:var(--txt)}

/* ===== VFX Reviews: Compact tools dock (Add Clips / FPS / Zoom etc) ===== */
.pfx-reviews-toolsDock .pfx-reviews-toolbar{gap:6px}
.pfx-reviews-toolsDock .pfx-btn{padding:6px 10px;min-height:28px;font-size:11px;border-radius:10px}
.pfx-reviews-toolsDock .pfx-btn-ghost{padding:6px 9px}
.pfx-reviews-toolsDock .pfx-select{min-height:28px;font-size:11px;padding:6px 9px;border-radius:10px}
.pfx-reviews-toolsDock .pfx-reviews-zoom{height:4px}
.pfx-reviews-toolsDock .pfx-reviews-zoom::-webkit-slider-thumb{width:12px;height:12px}
.pfx-reviews-toolsDock .pfx-reviews-zoom::-moz-range-thumb{width:12px;height:12px}

.pfx-reviews-exportWrap{position:relative;display:inline-flex;align-items:center;}
.pfx-reviews-menu{position:fixed;min-width:220px;z-index:2147483647;display:none;
  /* No “glass” effect here (user requested). Keep it solid for readability & reliable clicks. */
  border:1px solid var(--line-2);border-radius:14px;background:#14151a;
  -webkit-backdrop-filter:none;backdrop-filter:none;
  box-shadow:0 18px 40px rgba(0,0,0,.38);padding:6px}
.pfx-reviews-menuItem{display:block;width:100%;text-align:left;cursor:pointer;
  background:transparent;color:var(--txt);border:1px solid transparent;
