  border-radius:12px;padding:8px 10px;font-size:12px;font-weight:600;letter-spacing:.1px}
.pfx-reviews-menuItem:hover{background:#1a1b22;border-color:var(--line-2)}

.pfx-reviews-menuItem.pfx-lblbtn{justify-content:flex-start;gap:10px;min-height:40px;padding:9px 12px}
.pfx-reviews-menuItem.pfx-lblbtn .pfx-lbl-ico{width:18px;height:18px;opacity:1}
.pfx-reviews-menuItem.pfx-lblbtn .pfx-lbl-ico svg,
.pfx-reviews-menuItem.pfx-lblbtn .pfx-lbl-ico img{width:18px;height:18px;stroke-width:2.1}
.pfx-reviews-menuItem.pfx-lblbtn .pfx-lbl-txt{font-size:12px;line-height:1.15}
.pfx-reviews-menuItem--json .pfx-lbl-ico{color:#79d4ff}
.pfx-reviews-menuItem--csv .pfx-lbl-ico{color:#7fe3a1}
.pfx-reviews-menuItem--pdf .pfx-lbl-ico{color:#ffbf6b}

/* Reviews / Visual QC: Note list right‑click menu (Delete) */
.pfx-markerCtxMenu{position:fixed;z-index:100001;display:none;min-width:160px;
  border:1px solid var(--line-2);border-radius:14px;background:#14151a;
  box-shadow:0 18px 40px rgba(0,0,0,.42);padding:6px}
.pfx-markerCtxMenu.is-open{display:block}
.pfx-markerCtxItem{display:block;width:100%;text-align:left;cursor:pointer;
  background:transparent;color:var(--txt);border:1px solid transparent;
  border-radius:12px;padding:8px 10px;font-size:12px;font-weight:650;letter-spacing:.1px}
.pfx-markerCtxItem:hover{background:#1a1b22;border-color:var(--line-2)}
.pfx-markerCtxItem--danger{color:rgba(255,80,80,.96)}
.pfx-markerCtxItem--danger:hover{background:rgba(255,80,80,.12);border-color:rgba(255,80,80,.35)}

/* Reviews: Export button moved into Notes header */
.pfx-reviews-notesHeaderRight{position:relative;display:flex;align-items:center;gap:6px;flex:0 0 auto}
/* Match header sizing (small, clean) */
.pfx-reviews-notesHeaderRight .pfx-btn{padding:6px 9px;min-height:28px;font-size:11px;border-radius:10px;white-space:nowrap}

/* ===== PostFlowX – VFX Reviews: Smart Compact Media Bin ===== */
.pfx-reviews-binTools{display:flex;align-items:center;gap:6px;min-width:0}
/* Two-line V2 bin header (requested) */
.pfx-reviews-cardHeader--twoLine{align-items:flex-start}
.pfx-reviews-binTools--twoLine{flex-direction:column;align-items:stretch;gap:6px}
.pfx-reviews-binToolsRow{display:flex;align-items:center;gap:6px;min-width:0}
.pfx-reviews-binToolsRowRight{display:flex;align-items:center;gap:6px;flex:0 0 auto}
.pfx-reviews-binTools--twoLine .pfx-reviews-binSearch{flex:1 1 auto;width:auto;max-width:none;min-width:0}
.pfx-reviews-binTools--twoLine .pfx-reviews-binSort{flex:1 1 auto;min-width:0}

/* Reviews: tidy V2 (Shots) header (title/actions top, search/sort bottom) */
.pfx-reviews-cardHeader--shotsTools{flex-direction:column;align-items:stretch;justify-content:flex-start;gap:6px}
.pfx-reviews-binHeaderTop{display:flex;align-items:center;justify-content:space-between;gap:10px;min-width:0}
.pfx-reviews-binHeaderActions{display:flex;align-items:center;gap:6px;flex:0 0 auto}
.pfx-reviews-binHeaderBottom{display:flex;align-items:center;gap:6px;min-width:0}
.pfx-reviews-binHeaderBottom .pfx-reviews-binSearch{flex:1 1 auto;width:auto;max-width:none;min-width:0}
.pfx-reviews-binHeaderBottom .pfx-reviews-binSort{flex:0 0 auto;min-width:118px}

.pfx-reviews-binAdd{height:28px;min-width:28px;padding:0 10px;border-radius:999px;border:1px solid var(--line-2);background:#14151a;color:rgba(255,255,255,.85);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-weight:800}
.pfx-reviews-binAdd:hover{border-color:var(--line-3);background:#181922}
.pfx-reviews-binSearch{width:120px;max-width:28vw;min-width:90px;height:28px;padding:0 10px;border-radius:999px;border:1px solid var(--line-2);background:#14151a;color:var(--txt);font-size:12px;outline:none}
.pfx-reviews-binSearch::placeholder{color:rgba(255,255,255,.35)}
.pfx-reviews-binSearch:focus{border-color:var(--line-3)}
.pfx-reviews-binSort{height:28px;padding:0 10px;border-radius:999px;border:1px solid var(--line-2);background:#14151a;color:var(--txt);font-size:12px;outline:none}
.pfx-reviews-binCount{height:28px;display:inline-flex;align-items:center;padding:0 10px;border-radius:999px;border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.04);color:rgba(255,255,255,.75);font-size:12px;white-space:nowrap}
.pfx-reviews-binToggle{height:28px;min-width:28px;padding:0 8px;border-radius:999px;border:1px solid var(--line-2);background:#14151a;color:rgba(255,255,255,.8);cursor:pointer}
.pfx-reviews-binToggle:hover{border-color:var(--line-3);background:#181922}
/* Reviews: danger action in bin header (Remove all clips) */
.pfx-reviews-binDanger{border-color:rgba(255,80,80,.22);background:rgba(255,80,80,.06);color:rgba(255,255,255,.85)}
.pfx-reviews-binDanger:hover{border-color:rgba(255,80,80,.35);background:rgba(255,80,80,.10)}

/* Compact rows */
.pfx-reviews-bin .pfx-reviews-cardBody{gap:6px}
.pfx-reviews-bin .pfx-reviews-clipRow{
  display:flex;flex-direction:row;align-items:center;justify-content:space-between;
  padding:4px 8px;gap:8px;
  background:rgba(0,0,0,.18);border:1px solid rgba(255,255,255,.06);
  border-radius:12px;min-height:28px;
  position:relative;
  overflow:visible
}
.pfx-reviews-bin .pfx-reviews-clipRow:hover{border-color:rgba(255,255,255,.14);background:rgba(0,0,0,.22)}
.pfx-reviews-bin .pfx-reviews-clipLeft{display:flex;align-items:center;gap:8px;min-width:0;flex:1 1 auto}
.pfx-reviews-bin .pfx-reviews-clipRight{display:flex;align-items:center;gap:6px;flex:0 0 auto}
.pfx-reviews-bin .pfx-reviews-clipName{font-size:12px;font-weight:650;line-height:1.1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1 1 auto}

/*
  IMPORTANT: Keep clip names readable.
  Previously, .pfx-reviews-clipMeta was hidden via opacity only, but it still
  reserved layout width (many buttons), shrinking the name area to "L...".
  Make the meta controls an overlay (absolute) so the row stays readable.
*/
.pfx-reviews-bin .pfx-reviews-clipMeta{
  display:flex;align-items:center;gap:4px;
  position:absolute;right:6px;top:50%;transform:translateY(-50%) translateY(2px);
  opacity:0;pointer-events:none;
  transition:opacity .12s ease, transform .12s ease;
  padding:3px 4px;border-radius:999px;
  border:1px solid rgba(255,255,255,.10);
  background:rgba(0,0,0,.34);
  backdrop-filter:blur(10px);
  -webkit-backdrop-filter:blur(10px);
  box-shadow:0 10px 22px rgba(0,0,0,.22)
}
.pfx-reviews-bin .pfx-reviews-clipRow:hover .pfx-reviews-clipMeta,
.pfx-reviews-bin .pfx-reviews-clipRow.is-selected .pfx-reviews-clipMeta{opacity:1;pointer-events:auto}

.pfx-reviews-bin .pfx-reviews-clipRow:hover .pfx-reviews-clipMeta,
.pfx-reviews-bin .pfx-reviews-clipRow.is-selected .pfx-reviews-clipMeta{transform:translateY(-50%) translateY(0)}

.pfx-reviews-bin .pfx-reviews-groupArrow{width:14px;min-width:14px;text-align:center;color:rgba(255,255,255,.65);font-size:12px;user-select:none;cursor:pointer}
.pfx-reviews-bin .pfx-reviews-groupArrow--spacer{cursor:default;opacity:.18}
.pfx-reviews-bin .pfx-reviews-clipRow.is-group .pfx-reviews-clipName{font-weight:750}
.pfx-reviews-bin .pfx-reviews-clipRow.is-version{padding-left:18px;min-height:24px;opacity:.92}
.pfx-reviews-bin .pfx-reviews-groupBadge{height:18px;display:inline-flex;align-items:center;padding:0 6px;border-radius:999px;border:1px solid rgba(255,255,255,.10);background:rgba(255,255,255,.04);color:rgba(255,255,255,.75);font-size:11px;white-space:nowrap}
.pfx-reviews-bin .pfx-reviews-verBadge{height:18px;display:inline-flex;align-items:center;padding:0 6px;border-radius:999px;border:1px solid rgba(255,0,0,.18);background:rgba(255,0,0,.06);color:rgba(255,255,255,.78);font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;font-size:11px;white-space:nowrap}

.pfx-reviews-bin .pfx-reviews-clipTCPill{height:22px;display:inline-flex;align-items:center;padding:0 8px;border-radius:999px;border:1px solid rgba(255,255,255,.10);background:rgba(255,255,255,.04);color:rgba(255,255,255,.8);font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;font-size:11px;cursor:default}
.pfx-reviews-bin .pfx-reviews-clipTCInput{height:22px;min-width:104px;max-width:140px;padding:0 8px;border-radius:999px;border:1px solid rgba(255,255,255,.16);background:#0f1014;color:var(--txt);font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;font-size:11px;outline:none}

.pfx-reviews-bin .pfx-reviews-miniBtn{height:22px;min-width:26px;padding:0 8px;border-radius:999px;border:1px solid rgba(255,255,255,.10);background:rgba(255,255,255,.02);color:rgba(255,255,255,.85);font-size:11px;cursor:pointer}
.pfx-reviews-bin .pfx-reviews-miniBtn:hover{border-color:rgba(255,255,255,.18);background:rgba(255,255,255,.06)}

.pfx-reviews-bin .pfx-reviews-miniBtn--icon{min-width:22px;width:22px;padding:0;border-radius:10px;font-weight:750}
.pfx-reviews-bin .pfx-reviews-miniBtn.is-burninOverride{border-color:rgba(182,156,255,.35);background:rgba(182,156,255,.08);box-shadow:0 0 0 1px rgba(182,156,255,.15) inset}
.pfx-reviews-bin .pfx-reviews-miniBtn.is-qcReady{border-color:rgba(114,230,255,.35);background:rgba(114,230,255,.06);box-shadow:0 0 0 1px rgba(114,230,255,.12) inset}

/* Hide heavy controls in compact mode */
.pfx-reviews-bin.is-compact .pfx-reviews-clipTCPill{display:none}
.pfx-reviews-bin.is-compact .pfx-reviews-clipRow{padding:3px 8px;min-height:26px}
.pfx-reviews-bin.is-compact .pfx-reviews-clipMeta{opacity:0}

/* -------------------------------------------------------------
 * VISUAL QC (Reviews) — Bin list font size (requested)
 * Reduce shot-name font size slightly so more rows are readable.
 * ------------------------------------------------------------- */
.pfx-reviews-bin .pfx-reviews-clipName{font-size:11px;line-height:1.15}
