/* ===============================
   Reviews: Right‑click Floating Tools (radial menu)
   - Triggered by contextmenu on Source/Timeline viewers
   - Inspired by SpotOn style quick tools
   =============================== */
.pfx-rtmenu{
  position: fixed;
  left: 50%;
  top: 50%;
  /* Larger canvas so ring buttons have comfortable breathing room */
  width: 280px;
  height: 280px;
  z-index: 100000;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%,-50%) scale(.92);
  transition: opacity .10s ease, transform .10s ease;
}
.pfx-rtmenu.is-open{
  opacity: 1;
  pointer-events: auto;
  transform: translate(-50%,-50%) scale(1);
}
.pfx-rtmenu-ring{
  /*
    No large circular background behind the radial tools.
    Use display: contents so this wrapper never paints (even if other CSS overrides).
  */
  display: contents !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
.pfx-rtmenu-btn{
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44px;
  height: 44px;
  border-radius: 999px;
  transform: translate(-50%,-50%) translate(var(--dx, 0px), var(--dy, 0px));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  line-height: 1;
  color: rgba(250,250,255,0.92);
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.14);
  box-shadow:
    0 10px 28px rgba(0,0,0,0.45),
    0 0 0 1px rgba(0,0,0,0.30) inset;
  -webkit-backdrop-filter: blur(10px) saturate(1.25);
  backdrop-filter: blur(10px) saturate(1.25);
  cursor: pointer;
  user-select: none;
}

/* Radial menu icons/* Radial menu icons (pro SVG) */
.pfx-rtmenu-btn svg{
  width: 18px;
  height: 18px;
  display: block;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.pfx-rtmenu-btn svg .pfx-rt-ico-fill{ fill: currentColor; stroke: none; }
.pfx-rtmenu-btn:hover{
  color: rgba(255,80,80,0.98);
  border-color: rgba(255,80,80,0.55);
  box-shadow:
    0 0 0 2px rgba(255,80,80,0.14),
    0 12px 34px rgba(0,0,0,0.55),
    0 0 0 1px rgba(0,0,0,0.30) inset;
}
.pfx-rtmenu-btn.is-disabled,
.pfx-rtmenu-btn:disabled{
  opacity: .32;
  filter: grayscale(1);
  cursor: default;
}
.pfx-rtmenu-btn:active{
  transform: translate(-50%,-50%) translate(var(--dx, 0px), var(--dy, 0px)) scale(0.98);
}
.pfx-rtmenu-center{
  position: absolute;
  left: 50%;
  top: 50%;
  width: 46px;
  height: 46px;
  border-radius: 999px;
  transform: translate(-50%,-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  color: rgba(245,245,255,0.90);
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.14);
  box-shadow:
    0 12px 30px rgba(0,0,0,0.45),
    0 0 0 1px rgba(0,0,0,0.30) inset;
  -webkit-backdrop-filter: blur(12px) saturate(1.25);
  backdrop-filter: blur(12px) saturate(1.25);
  cursor: pointer;
  user-select: none;
}
.pfx-rtmenu-center:hover{
  color: rgba(255,80,80,0.95);
  border-color: rgba(255,80,80,0.40);
}

