/* ========================================================================
   Hawkins Design Language (HDL) alignment — HDL-inspired UI tokens + base components
   Notes:
   - This pass focuses on consistency & coherence across shape, depth, color, and layout.
   - The provided HDL PDF is a program overview (principles), not a full token spec.
   ======================================================================== */

:root{
  /* Shape */
  --radius: 14px;
  --radius-sm: 12px;
  --radius-lg: 18px;

  /* Depth / material (frosted but calmer) */
  --glass-bg: rgba(20,22,30,0.52);
  --glass-bg-2: rgba(16,18,24,0.34);
  --glass-stroke: rgba(255,255,255,0.12);
  --glass-stroke-2: rgba(255,255,255,0.20);
  --glass-shadow: 0 18px 50px rgba(0,0,0,0.42);
  --glass-shadow-soft: 0 10px 30px rgba(0,0,0,0.28);
  --glass-blur: 22px;
  --glass-sat: 160%;

  /* Keep existing accent behavior (lilac) — can be swapped to Hawkins brand tokens later */
  --focus-ring: rgba(177,124,255,0.55);
  --focus-ring-soft: rgba(177,124,255,0.16);
}

/* Background: reduce the warm/orange cast → calmer neutral dark with subtle depth */
html,body{
  background:
    radial-gradient(900px 700px at 110% 120%, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.00) 60%) fixed,
    radial-gradient(900px 700px at -10% -20%, rgba(177,124,255,0.10) 0%, rgba(0,0,0,0.00) 58%) fixed,
    linear-gradient(180deg, #0b0b0e 0%, #07070a 100%) fixed;
}

/* Replace the external texture URL (was pointing to /mnt/data) with a lightweight noise pattern */
body::before{
  background:
    radial-gradient(1200px 900px at 50% 0%, rgba(255,255,255,0.05) 0%, rgba(255,255,255,0.00) 60%),
    repeating-linear-gradient(0deg, rgba(255,255,255,0.020) 0 1px, rgba(0,0,0,0.00) 1px 3px),
    repeating-linear-gradient(90deg, rgba(255,255,255,0.014) 0 1px, rgba(0,0,0,0.00) 1px 4px);
  opacity: 0.10;
  filter: none;
}

/* Header: cleaner surface + consistent stroke */
header{
  background:
    linear-gradient(180deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02)),
    rgba(12,12,16,0.78);
  border-bottom: 1px solid var(--glass-stroke);
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
}

/* Cards / panels */
.card{
  border-radius: var(--radius-lg) !important;
  border: 1px solid var(--glass-stroke) !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02)),
    var(--glass-bg) !important;
  box-shadow: var(--glass-shadow) !important;
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
}

/* Buttons: unified geometry + calmer material */
.btn,.qs-btn{
  border-radius: var(--radius-sm) !important;
  border: 1px solid var(--glass-stroke) !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0.03)),
    var(--glass-bg-2) !important;
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  transition: transform .08s ease, box-shadow .16s ease, border-color .16s ease, background .16s ease;
}
.btn:hover,.qs-btn:hover{
  border-color: var(--glass-stroke-2) !important;
  box-shadow: var(--glass-shadow-soft) !important;
  transform: translateY(-1px);
}
.btn:active,.qs-btn:active{ transform: translateY(0px); }

/* Inputs: same radius family + consistent focus ring */
input[type="text"], input[type="number"], input[type="search"], input[type="email"], textarea, select{
  border-radius: var(--radius-sm) !important;
  border: 1px solid var(--glass-stroke) !important;
  background: rgba(0,0,0,0.22) !important;
}
input[type="text"]:focus, input[type="number"]:focus, input[type="search"]:focus, input[type="email"]:focus, textarea:focus, select:focus{
  border-color: var(--focus-ring) !important;
  box-shadow: 0 0 0 3px var(--focus-ring-soft) !important;
}

