/* ========================================================================
   FCPX-like Timeline (PULL PREP + MARKERS)
   - Emphasize Primary Storyline (V1)
   - Show subtle connector lines for connected clips
   Notes: scoped to #edlTimelineCard and #smTimelineCard only
   ======================================================================== */

#edlTimelineCard .edl-tl-tracks,
#smTimelineCard .edl-tl-tracks{
  position: relative;
}

#edlTimelineCard .edl-tl-connectors,
#smTimelineCard .edl-tl-connectors{
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  z-index: 1;
}

#edlTimelineCard .edl-tl-connector,
#smTimelineCard .edl-tl-connector{
  position: absolute;
  width: 1px;
  background: rgba(255,255,255,0.18);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.22);
  opacity: 0.55;
}

#edlTimelineCard .edl-tl-connector::before,
#smTimelineCard .edl-tl-connector::before{
  content: "";
  position: absolute;
  top: -2px;
  left: -2px;
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: rgba(255,255,255,0.26);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.25);
}

#edlTimelineCard .edl-tl-connector::after,
#smTimelineCard .edl-tl-connector::after{
  content: "";
  position: absolute;
  bottom: -2px;
  left: -2px;
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: rgba(255,255,255,0.18);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.22);
}

#edlTimelineCard .edl-tl-track.is-spine,
#smTimelineCard .edl-tl-track.is-spine{
  background: rgba(255,255,255,0.035);
}

#edlTimelineCard .edl-tl-track.is-spine .edl-tl-lane,
#smTimelineCard .edl-tl-track.is-spine .edl-tl-lane{
  background-image: linear-gradient(to right, rgba(255,255,255,0.09), rgba(255,255,255,0.00));
}

/* Clip blocks: use top role/cam bar instead of left stripe */
#edlTimelineCard .edl-tl-item,
#smTimelineCard .edl-tl-item{
  border-radius: 7px;
  border: 1px solid rgba(0,0,0,0.72);
  border-left: none;
  padding: 0 6px;
  z-index: 2;
}

#edlTimelineCard .edl-tl-item::before,
#smTimelineCard .edl-tl-item::before{
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 2px;
  background: var(--clip-color, rgba(255,255,255,0.40));
  opacity: 0.95;
}

#edlTimelineCard .edl-tl-item.is-spine-clip,
#smTimelineCard .edl-tl-item.is-spine-clip{
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.18),
    inset 0 -1px 0 rgba(0,0,0,0.35),
    0 10px 20px rgba(0,0,0,0.22);
}

#edlTimelineCard .edl-tl-item.is-connected-clip,
#smTimelineCard .edl-tl-item.is-connected-clip{
  opacity: 0.92;
}

/* FCPX-like selection (yellow outline) */
#edlTimelineCard .edl-tl-item.is-selected,
#smTimelineCard .edl-tl-item.is-selected{
  outline: 2px solid rgba(255, 208, 64, 0.92);
  outline-offset: -2px;
  border-color: rgba(255, 208, 64, 0.80);
  filter: brightness(1.08);
}

#edlTimelineCard .edl-tl-item:hover,
#smTimelineCard .edl-tl-item:hover{
  filter: brightness(1.06);
}

/* Shot Marker: keep has-marker green but align with top-bar style */
#smTimelineCard .edl-tl-item.has-marker{
  background: rgba(34, 197, 94, 0.78) !important;
}
#smTimelineCard .edl-tl-item.has-marker::before{
  background: rgba(34, 197, 94, 0.95) !important;
}

