/* -------------------------------------------------------------
 * VISUAL QC — Note Inspector Dock (green workspace)
 * ------------------------------------------------------------- */

/* Empty area under the timeline is used for the selected Note inspector */
.pfx-reviews-inspectorDock{
  /* Ultra-compact inspector: keep it small so viewers/timeline stay dominant */
  flex:0 0 auto;
  min-height:104px;
  max-height:170px;
  min-width:0;
  overflow:hidden;
  border-radius:16px;
  border:1px solid var(--glass-stroke, rgba(255,255,255,0.14));
  background:
    linear-gradient(180deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02)),
    var(--glass-bg, rgba(20,22,30,0.46));
  backdrop-filter: blur(var(--glass-blur, 26px)) saturate(var(--glass-sat, 175%));
  -webkit-backdrop-filter: blur(var(--glass-blur, 26px)) saturate(var(--glass-sat, 175%));
  box-shadow: var(--glass-shadow-soft, 0 10px 30px rgba(0,0,0,0.28));
  display:flex;
}

/* Make the editor fill the dock and scroll internally */
.pfx-reviews-inspectorDock .pfx-reviews-markerEditor{
  flex:1 1 auto;
  min-height:0;
  overflow:auto;
  border:0;
  border-radius:0;
  background:transparent;
  padding:8px 10px;
  /* Compact 2-column layout: thumb on the left, fields on the right */
  display:grid;
  grid-template-columns: 112px 1fr;
  grid-template-rows: auto auto auto auto;
  grid-template-areas:
    "meta meta"
    "status status"
    "tags tags"
    "thumb note";
  gap:5px;
  align-content:start;
}

.pfx-reviews-inspectorDock .pfx-reviews-markerMeta{
  grid-area: meta;
  font-size:11px;
  font-weight:800;
  opacity:.9;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.pfx-reviews-inspectorDock .pfx-reviews-markerStatusRow{
  grid-area: status;
  gap:6px;
}

.pfx-reviews-inspectorDock .pfx-pill-status{
  padding:4px 8px;
  font-size:10px;
}

/* Reuse the Notes panel styling for the moved inspector */
.pfx-reviews-inspectorDock .pfx-reviews-markerTagsRow{
  grid-area: tags;
  padding:4px;
  gap:6px;
  background: rgba(0,0,0,0.14);
  border:1px solid rgba(255,255,255,0.08);
  border-radius:12px;
}

.pfx-reviews-inspectorDock .pfx-reviews-markerThumbWrap{
  grid-area: thumb;
  margin:0;
  padding:0;
}

.pfx-reviews-inspectorDock .pfx-reviews-markerSelect{
  flex:1 1 0;
  min-width:0;
  height:28px;
  padding:0 28px 0 10px;
  border-radius:10px;
  border:1px solid rgba(255,255,255,0.12);
  background: rgba(0,0,0,0.22);
  color: rgba(255,255,255,0.92);
  outline:none;
  appearance:none;
  -webkit-appearance:none;
  background-image:
    linear-gradient(45deg, transparent 50%, rgba(255,255,255,0.55) 50%),
    linear-gradient(135deg, rgba(255,255,255,0.55) 50%, transparent 50%);
  background-position: calc(100% - 14px) 52%, calc(100% - 9px) 52%;
  background-size: 5px 5px, 5px 5px;
  background-repeat:no-repeat;
}
.pfx-reviews-inspectorDock .pfx-reviews-markerSelect:focus{
  border-color: rgba(185,120,255,0.40);
  box-shadow: 0 0 0 2px rgba(185,120,255,0.14);
}
.pfx-reviews-inspectorDock .pfx-reviews-markerSelect:disabled{ opacity:.6; cursor:not-allowed; }
.pfx-reviews-inspectorDock .pfx-reviews-markerSelect option{ background:#0f1015; color: rgba(255,255,255,0.92); }

.pfx-reviews-inspectorDock .pfx-reviews-markerNote{
