#appShell > .tabs .tab[data-main="reviews"].active .bar,
#appShell > .tabs .tab[data-main="tconform"].active .bar,
#appShell > .tabs .tab[data-main="trlconf"].active .bar,
#appShell > .tabs .tab[data-main="imf"].active .bar,
#appShell > .tabs .tab[data-main="edl"]:hover .bar,
#appShell > .tabs .tab[data-main="cutdiff"]:hover .bar,
#appShell > .tabs .tab[data-main="shotmarker"]:hover .bar,
