  overflow: auto;
  padding: 4px;
  scrollbar-width: none;
}
.fun-mines-board-wrap::-webkit-scrollbar{
  display: none;
}
.fun-mines-board{
  --fun-mines-cell: 24px;
  grid-template-columns: repeat(16, var(--fun-mines-cell));
}
.fun-mines-cell{
  width: var(--fun-mines-cell);
  height: var(--fun-mines-cell);
  min-width: var(--fun-mines-cell);
  min-height: var(--fun-mines-cell);
  box-sizing: border-box;
}
.fun-mines-classic-bottom{
  display: grid;
  grid-template-columns: 44px 1fr 22px;
  align-items: center;
  gap: 10px;
  margin-top: 0;
  padding: 8px;
  min-height: 54px;
}
.fun-mines-bottom-btn{
  width: 38px;
  height: 38px;
  padding: 0;
  border-radius: 0;
  border-top: 3px solid #ffffff;
  border-left: 3px solid #ffffff;
  border-right: 3px solid #7b7b7b;
  border-bottom: 3px solid #7b7b7b;
  background: #c0c0c0;
  position: relative;
  cursor: pointer;
}
.fun-mines-bottom-btn::before{
  content: "";
  position: absolute;
  left: 13px;
  top: 10px;
  width: 0;
  height: 0;
  border-top: 8px solid transparent;
  border-bottom: 8px solid transparent;
  border-left: 12px solid #f1f1f1;
  filter: drop-shadow(1px 1px 0 #8b8b8b);
}
.fun-mines-bottom-btn:active{
  border-top: 3px solid #7b7b7b;
  border-left: 3px solid #7b7b7b;
  border-right: 3px solid #ffffff;
  border-bottom: 3px solid #ffffff;
}
.fun-mines-bottom-track{
  position: relative;
  height: 24px;
  background: #d7d7d7;
  border-top: 3px solid #7b7b7b;
  border-left: 3px solid #7b7b7b;
  border-right: 3px solid #ffffff;
  border-bottom: 3px solid #ffffff;
  overflow: hidden;
}
.fun-mines-bottom-track-inner{
  position: absolute;
  inset: 5px 8px;
  background: linear-gradient(180deg, #e7e7e7 0%, #d9d9d9 100%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.9), inset 0 -1px 0 rgba(120,120,120,0.55);
}
.fun-mines-bottom-knob{
  width: 18px;
  height: 18px;
  border-top: 2px solid #ffffff;
  border-left: 2px solid #ffffff;
  border-right: 2px solid #7b7b7b;
  border-bottom: 2px solid #7b7b7b;
  background: #cfcfcf;
  justify-self: end;
}
.fun-mines-sr-only{
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.fun-mines-help{
  margin-top: 2px;
  font-size: 10px;
  color: rgba(240,240,240,0.58);
  text-align: center;
}
.fun-mines-face[data-state="lose"]{ color: #111; }
.fun-mines-face[data-state="win"]{ color: #111; }
@media (max-width: 1440px){
  .fun-mines-board-wrap{ min-height: 232px; }
}
@media (max-width: 1280px){
  .fun-mines-classic-bottom{ grid-template-columns: 40px 1fr 18px; gap: 8px; min-height: 46px; }
  .fun-mines-bottom-btn{ width: 34px; height: 34px; }
  .fun-mines-bottom-btn::before{ left: 11px; top: 8px; border-top-width: 7px; border-bottom-width: 7px; border-left-width: 10px; }
  .fun-mines-bottom-track{ height: 20px; }
}


/* -------------------------------------------------------------
   Fun box: Minesweeper classic LED counter digits
------------------------------------------------------------- */
.fun-mines-display{
  min-height: 54px;
  padding: 4px 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  background: #000;
  color: #ff2a2a;
  border-top: 3px solid #7b7b7b;
  border-left: 3px solid #7b7b7b;
  border-right: 3px solid #ffffff;
  border-bottom: 3px solid #ffffff;
  box-sizing: border-box;
}
.fun-mines-led-digit{
  position: relative;
  width: 19px;
  height: 34px;
  display: inline-block;
  flex: 0 0 19px;
}
.fun-mines-led-seg{
  position: absolute;
  display: block;
  background: #2e0000;
  box-shadow: none;
  opacity: 1;
}
.fun-mines-led-seg.is-on{
  background: #ff1c12;
  box-shadow: 0 0 1px rgba(255,100,84,.55);
}
.fun-mines-led-seg-a,
.fun-mines-led-seg-d,
.fun-mines-led-seg-g{
  left: 4px;
  width: 11px;
  height: 3px;
}
.fun-mines-led-seg-a{ top: 1px; }
.fun-mines-led-seg-g{ top: 15px; }
.fun-mines-led-seg-d{ top: 29px; }
.fun-mines-led-seg-b,
.fun-mines-led-seg-c,
.fun-mines-led-seg-e,
.fun-mines-led-seg-f{
  width: 3px;
  height: 12px;
}
.fun-mines-led-seg-f{ left: 1px; top: 3px; }
.fun-mines-led-seg-b{ right: 1px; top: 3px; }
.fun-mines-led-seg-e{ left: 1px; top: 17px; }
.fun-mines-led-seg-c{ right: 1px; top: 17px; }

@media (max-width: 1440px){
