  .fun-mines-led-seg-d,
  .fun-mines-led-seg-g{ left: 3px; width: 9px; height: 2px; }
  .fun-mines-led-seg-g{ top: 12px; }
  .fun-mines-led-seg-d{ top: 23px; }
  .fun-mines-led-seg-b,
  .fun-mines-led-seg-c,
  .fun-mines-led-seg-e,
  .fun-mines-led-seg-f{ width: 2px; height: 9px; }
  .fun-mines-led-seg-f{ left: 1px; top: 2px; }
  .fun-mines-led-seg-b{ right: 1px; top: 2px; }
  .fun-mines-led-seg-e{ left: 1px; top: 13px; }
  .fun-mines-led-seg-c{ right: 1px; top: 13px; }
