/* =====================================================================
   Visual QC — Resolve-style filmstrip docked under Timeline
   Goal: move the old right Notes panel into the green workspace as a
   horizontal filmstrip like DaVinci Resolve.
   ===================================================================== */

/* Notes no longer occupy a dedicated right column in Visual QC. */
.pfx-reviews.is-bin-open.is-notes-open .pfx-reviews-layout,
.pfx-reviews.is-bin-open:not(.is-notes-open) .pfx-reviews-layout{
  grid-template-columns:var(--pfx-reviews-binW,360px) 1fr;
}
.pfx-reviews:not(.is-bin-open).is-notes-open .pfx-reviews-layout,
.pfx-reviews:not(.is-bin-open):not(.is-notes-open) .pfx-reviews-layout{
  grid-template-columns:1fr;
}

/* Dock filmstrip inside the center stack, below the timeline and above the note editor. */
.pfx-reviews-center > .pfx-reviews-notes{
  flex:0 0 auto;
  min-height:142px;
  max-height:208px;
  overflow:hidden;
  display:flex;
  flex-direction:column;
}
.pfx-reviews-center > .pfx-reviews-notes .pfx-reviews-card{
  flex:1 1 auto;
  min-height:0;
  overflow:hidden;
  border-radius:14px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02)),
    rgba(8,10,16,0.54);
  border:1px solid rgba(152,93,255,0.16);
  box-shadow:0 12px 26px rgba(0,0,0,0.22), inset 0 0 0 1px rgba(255,255,255,0.03);
}
.pfx-reviews-center > .pfx-reviews-notes .pfx-reviews-cardHeader{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  min-height:34px;
  padding:6px 10px;
  background:rgba(0,0,0,0.22);
  border-bottom:1px solid rgba(255,255,255,0.08);
}
.pfx-reviews-center > .pfx-reviews-notes .pfx-reviews-cardTitle{
  font-size:11px;
  font-weight:900;
  letter-spacing:.24px;
  text-transform:uppercase;
  opacity:.82;
}
.pfx-reviews-center > .pfx-reviews-notes .pfx-reviews-cardBody{
  padding:10px 12px 12px;
  display:flex;
  overflow:hidden;
  background:transparent;
}
.pfx-reviews-center > .pfx-reviews-notes .pfx-reviews-notesHeaderRight .pfx-btn{
  min-height:26px;
  padding:5px 9px;
  border-radius:9px;
}

/* Filmstrip rows become thumbnail cards in a horizontal scroller. */
.pfx-reviews-notes.is-filmstrip .pfx-reviews-markerList{
  display:flex;
  flex-direction:row;
  gap:10px;
  overflow-x:auto;
  overflow-y:hidden;
  padding:0 2px 4px 0;
  scroll-snap-type:x proximity;
  scrollbar-gutter:stable both-edges;
}
.pfx-reviews-notes.is-filmstrip .pfx-reviews-markerList::-webkit-scrollbar{
