.top-aux-pane[data-pane="toolbox"] .tb-workspace-move[aria-disabled="true"]{
  opacity: 0.22;
  cursor: default;
  pointer-events: none;
}
/* ── Workspace Tab permission states ───────────────────────────────────────── */
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card{
  transition: opacity 160ms ease, filter 160ms ease, background 160ms ease, border-color 160ms ease;
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--allowed{
  opacity: 1;
  filter: none;
  cursor: pointer;
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--active{
  opacity: 1;
  filter: none;
  cursor: pointer;
  border-color: color-mix(in srgb, var(--tb-ws-accent,#7c5cff) 70%, transparent);
  background: color-mix(in srgb, var(--tb-ws-accent,#7c5cff) 22%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--tb-ws-accent,#7c5cff) 70%, transparent),
              0 0 18px color-mix(in srgb, var(--tb-ws-accent,#7c5cff) 26%, transparent);
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--active .tb-workspace-label{
  color: #fff;
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--active:hover{
  background: color-mix(in srgb, var(--tb-ws-accent,#7c5cff) 28%, transparent);
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--locked{
  opacity: 0.38;
  filter: grayscale(1) saturate(0) brightness(0.78);
  cursor: not-allowed;
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--locked .tb-workspace-label{
  color: #9ca3af !important;
  opacity: 0.65;
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--locked .tb-workspace-icon{
  opacity: 0.65;
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--locked .tb-workspace-actions{
  opacity: 0.4;
  pointer-events: none;
}
.top-aux-pane[data-pane="toolbox"] .tb-workspace-card.tb-ws--locked:hover{
  background: rgba(148,163,184,0.08) !important;
  border-color: rgba(148,163,184,0.18) !important;
  box-shadow: none !important;
}
.tabs .tab.is-detached-to-toolbox{
  display: none !important;
}
/* Desktop specificity override: beats html[data-pfx-env="desktop"] #appShell .mac-workspace-toolbar .tab { display:flex !important }
   Specificity (1,4,1) > (1,3,1) — the ID rule above would otherwise win and keep hidden tabs visible. */
html[data-pfx-env="desktop"] #appShell .mac-workspace-toolbar .tab.is-detached-to-toolbox {
  display: none !important;
}
html[data-pfx-env="desktop"] #appShell .mac-workspace-toolbar .tab[hidden] {
