/* ── Vertical bar indicator ─────────────────────────────────────
   The checkbox is invisible — clicking anywhere on the card toggles it.
   The colored left-strip IS the on/off indicator.                    */
.sm-name-modal-pro2 .sm-name-chk{
  -webkit-appearance: none !important;
  appearance: none !important;
  position: absolute !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
  pointer-events: none !important;
  margin: 0 !important;
}
.sm-name-modal-pro2 .sm-name-chk::after{ display: none !important; }

/* Field card: make it the toggle target */
.sm-name-modal-pro2 .sm-name-field{
  position: relative !important;
  cursor: pointer !important;
  user-select: none !important;
  /* replace uniform border with inset shadow bar on left */
  border: 1px solid rgba(255,255,255,0.07) !important;
  border-left: 3px solid rgba(255,255,255,0.10) !important;
  transition: border-left-color .18s, background .18s, box-shadow .18s, opacity .18s !important;
}
/* Active card: vivid solid bar + faint purple wash */
.sm-name-modal-pro2 .sm-name-field:has(.sm-name-chk:checked){
  border-left-color: rgba(185,125,255,1) !important;
  background: rgba(180,120,255,0.06) !important;
  box-shadow: inset 0 0 0 1px rgba(180,120,255,0.10) !important;
}
/* Inactive: dim the whole card slightly */
.sm-name-modal-pro2 .sm-name-field:not(:has(.sm-name-chk:checked)){
  opacity: 0.52 !important;
}
