.sm-name-modal-pro2 .sm-name-field-lbl{
  transition: color .15s !important;
}
.sm-name-modal-pro2 .sm-name-field:has(.sm-name-chk:checked) .sm-name-field-lbl{
  color: rgba(215,185,255,0.90) !important;
