/* ===== Visual QC V1 import rows (Video / Timeline) ===== */
.pfx-reviews-bin .pfx-reviews-card--ref{
  min-height:210px !important;
  max-height:clamp(210px,30vh,272px) !important;
}
.pfx-reviews-refImportDock{
  display:grid;
  grid-template-columns:1fr;
  gap:6px;
  margin:0 0 5px;
}
.pfx-reviews-refImportDock .sm-importdock-row{
  display:grid;
  grid-template-columns:minmax(0,1fr) 32px;
  gap:7px;
  align-items:stretch;
  min-height:0;
}
.pfx-reviews-refImportDock .sm-importdock-btn{
  width:100%;
  min-height:46px;
  display:flex;
  align-items:center;
  gap:9px;
  padding:8px 9px;
  border-radius:11px;
  border:1px solid rgba(255,255,255,.10);
  background:rgba(255,255,255,.04);
  color:rgba(244,247,255,.92);
  cursor:pointer;
  text-align:left;
  transition:border-color .18s ease, background .18s ease, transform .18s ease, box-shadow .18s ease;
}
.pfx-reviews-refImportDock .sm-importdock-btn:hover{
  border-color:rgba(180,120,255,.24);
  background:rgba(255,255,255,.07);
  box-shadow:0 0 0 1px rgba(180,120,255,.10) inset;
}
.pfx-reviews-refImportDock .sm-importdock-btn:active{
  transform:translateY(1px);
}
.pfx-reviews-refImportDock .sm-importdock-row.is-dropover .sm-importdock-btn,
.pfx-reviews-refImportDock .sm-importdock-btn.is-dropover{
  border-color:rgba(120,210,255,.46);
  background:linear-gradient(180deg, rgba(120,210,255,.12), rgba(120,210,255,.05));
  box-shadow:0 0 0 1px rgba(120,210,255,.18) inset, 0 0 16px rgba(120,210,255,.08);
}
.pfx-reviews-refImportDock .sm-importdock-remove{
  min-width:32px;
  width:32px;
  padding:0;
  border-radius:11px;
  border:1px solid rgba(255,255,255,.10);
  background:rgba(255,255,255,.035);
  color:rgba(232,236,246,.86);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  transition:border-color .18s ease, background .18s ease, opacity .18s ease, transform .18s ease, box-shadow .18s ease;
}
.pfx-reviews-refImportDock .sm-importdock-remove:hover:not([disabled]){
  border-color:rgba(255,124,124,.34);
  background:rgba(255,88,88,.08);
  color:rgba(255,232,232,.96);
  box-shadow:0 0 0 1px rgba(255,88,88,.12) inset;
}
.pfx-reviews-refImportDock .sm-importdock-remove[disabled]{
  opacity:.38;
  cursor:default;
  pointer-events:none;
}
.pfx-reviews-refImportDock .sm-importdock-row.is-loaded .sm-importdock-remove{
  opacity:1;
}
.pfx-reviews-refImportDock .sm-importdock-ico{
  width:26px;
  height:26px;
  min-width:26px;
  display:grid;
  place-items:center;
  border-radius:9px;
  background:rgba(255,255,255,.06);
  color:rgba(205,224,255,.94);
}
.pfx-reviews-refImportDock .sm-importdock-row[data-import-kind="video"] .sm-importdock-ico{
  box-shadow: inset 3px 0 0 rgba(83,216,255,.92);
}
.pfx-reviews-refImportDock .sm-importdock-row[data-import-kind="timeline"] .sm-importdock-ico{
  box-shadow: inset 3px 0 0 rgba(186,120,255,.92);
}
.pfx-reviews-refImportDock .sm-importdock-ico svg{
  width:14px;
  height:14px;
}
.pfx-reviews-refImportDock .sm-importdock-copy{
  min-width:0;
