  flex-direction:column;
  gap:2px;
}
.pfx-reviews-refImportDock .sm-importdock-label{
  font-size:11px;
  font-weight:700;
  letter-spacing:.18px;
}
.pfx-reviews-refImportDock .sm-importdock-meta{
  display:block;
