   ======================================================================== */

.theme-tconform { --c-bar: #b97aff; }
.theme-trlconf  { --c-bar: #7fd48e; }


/* Tab icon — inherits tab text color so it's muted when inactive, white when active */
.tab-icon-tcf {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  line-height: 1;
  flex-shrink: 0;
  color: #fff;
  opacity: 0.65;
  filter: grayscale(100%);
  transition: opacity .15s, filter .15s, filter .15s;
}
.tab[data-main="tconform"]:not(.active) .tab-icon-tcf {
  opacity: 0.65;
  filter: grayscale(100%);
}
.tab[data-main="tconform"].active .tab-icon-tcf,
.tab[data-main="tconform"]:hover .tab-icon-tcf {
  opacity: 1;
  filter: drop-shadow(0 0 5px color-mix(in srgb, #b97aff 70%, white 30%)) brightness(1.15);
  color: #fff;
}

