.pfx-tutorial-body::-webkit-scrollbar { width: 6px; }
.pfx-tutorial-body::-webkit-scrollbar-track { background: transparent; }
.pfx-tutorial-body::-webkit-scrollbar-thumb { background: rgba(255,255,255,.14); border-radius: 3px; }

/* Player Transport deep-dive help */
.pfx-player-deep-box {
  width: min(760px, 94vw);
  background: #141414;
  border-color: #2f2f2f;
  border-radius: 16px;
  box-shadow: 0 28px 70px rgba(0,0,0,.82);
}
.pfx-player-deep-body {
  gap: 18px;
  background: #141414;
  color: #8e8e8e;
}
.pfx-player-deep-body h3 {
  margin: 0;
  color: #d8d8d8;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0;
}
.pfx-player-deep-body p,
.pfx-player-deep-body li {
  color: #858585;
  font-size: 12px;
  line-height: 1.55;
}
.pfx-player-deep-body strong,
.pfx-player-deep-body b {
  color: #d4d4d4;
}
.pfx-player-deep-eyebrow {
  color: #626262;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.pfx-player-demo-bar {
  margin-top: 12px;
  padding: 14px 18px 12px;
  border: 1px solid #343434;
  border-radius: 9px;
  background: #202020;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  align-items: center;
}
.pfx-player-demo-time {
  color: #747474;
  font: 700 12px/1 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
.pfx-player-demo-scrub {
  height: 18px;
  position: relative;
}
.pfx-player-demo-scrub::before,
.pfx-player-demo-scrub span {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 8px;
  height: 4px;
  border-radius: 999px;
}
.pfx-player-demo-scrub::before { background: #2c2c2c; }
.pfx-player-demo-scrub span {
  right: auto;
  background: #5e5e5e;
}
.pfx-player-demo-scrub i {
  position: absolute;
  left: calc(33% - 5px);
  top: 3px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #9b9b9b;
}
.pfx-player-demo-scrub--wide i { left: calc(52% - 5px); }
.pfx-player-demo-controls {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 8px;
}
.pfx-player-demo-controls button,
.pfx-player-demo-nav button {
  width: 36px;
  height: 32px;
  border: 1px solid #3a3a3a;
  border-radius: 6px;
  background: #292929;
