  font: 800 15px/1 ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.pfx-player-demo-controls button:hover,
.pfx-player-demo-nav button:hover {
  background: #303030;
  color: #e8e8e8;
}
.pfx-player-demo-controls button.is-demo-active,
.pfx-player-demo-nav button.is-demo-active {
  border-color: rgba(65,139,255,.72);
  color: #6aa5ff;
  box-shadow: 0 0 0 2px rgba(65,139,255,.1);
}
.pfx-player-demo-controls button.is-demo-play {
  border-color: rgba(44,186,68,.72);
  color: #69d86f;
  box-shadow: 0 0 0 2px rgba(44,186,68,.1);
}
.pfx-player-demo-controls button.is-demo-loop {
  border-color: rgba(255,106,0,.78);
  color: #ff6a00;
  box-shadow: 0 0 0 2px rgba(255,106,0,.1);
}
.pfx-player-demo-nav {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px;
  border: 1px solid #343434;
  border-radius: 9px;
  background: #202020;
}
.pfx-player-demo-nav span {
  width: 28px;
  height: 28px;
  border: 1px solid #464646;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #858585;
  background: #252525;
  font-size: 18px;
}
.pfx-player-demo-sep {
  width: 1px;
  height: 28px;
  background: #353535;
  margin: 0 3px;
}
.pfx-player-deep-card {
  border: 1px solid #303030;
  border-radius: 9px;
  background: #1d1d1d;
  padding: 16px;
}
.pfx-player-deep-card--cyan {
  border-color: rgba(0,188,205,.48);
  box-shadow: inset 0 0 0 1px rgba(0,188,205,.05);
}
.pfx-player-deep-card--amber {
  border-color: rgba(255,106,0,.5);
  box-shadow: inset 0 0 0 1px rgba(255,106,0,.05);
}
.pfx-player-deep-card--green { border-color: rgba(44,186,68,.45); }
.pfx-player-deep-card--blue { border-color: rgba(65,139,255,.48); }
.pfx-player-deep-heading {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}
.pfx-player-deep-heading p {
  margin: 3px 0 0;
  color: #626262;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.pfx-player-deep-icon,
.pfx-player-deep-dot {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,106,0,.4);
  border-radius: 7px;
  background: rgba(255,106,0,.08);
  color: #ff6a00;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
}
.pfx-player-deep-dot {
  border-color: #3f3f3f;
  border-radius: 50%;
  background: #252525;
  color: #858585;
  font-size: 20px;
}
.pfx-player-deep-scrub-detail {
  padding: 12px 16px;
  border: 1px solid #292929;
  border-radius: 8px;
  background: #191919;
}
.pfx-player-deep-scale {
  display: flex;
  justify-content: space-between;
  color: #737373;
  font: 700 11px/1.2 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  margin-top: 8px;
}
.pfx-player-deep-card ul {
  margin: 12px 0;
  padding-left: 17px;
}
.pfx-player-deep-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}
.pfx-player-deep-tags span,
.pfx-player-deep-card code {
  border: 1px solid #3c3c3c;
  border-radius: 4px;
  padding: 2px 8px;
  background: #202020;
  color: #bdbdbd;
  font: 800 11px/1.3 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
.pfx-player-deep-tags span:nth-child(1) { border-color: rgba(0,188,205,.55); color: #52d8df; }
.pfx-player-deep-tags span:nth-child(2) { border-color: rgba(44,186,68,.55); color: #6fda74; }
.pfx-player-deep-tags span:nth-child(3) { border-color: rgba(85,99,230,.55); color: #aaa8ff; }
.pfx-player-deep-tags span:nth-child(4) { border-color: rgba(255,106,0,.45); color: #d99a43; }
.pfx-player-deep-nav-strip {
  border: 1px solid #303030;
  border-radius: 8px;
  background: #1a1a1a;
  padding: 9px;
  display: flex;
  justify-content: center;
  margin-bottom: 12px;
}
.pfx-player-deep-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}
.pfx-player-deep-grid--stack {
  grid-template-columns: 1fr;
}
.pfx-player-deep-grid article {
  border: 1px solid #2b2b2b;
  border-radius: 7px;
  background: #191919;
  padding: 11px;
}
.pfx-player-deep-grid article p {
  margin: 6px 0 9px;
}
.pfx-player-deep-warning {
  margin-top: 12px;
  border: 1px solid rgba(255,106,0,.36);
  border-radius: 7px;
  background: rgba(70,45,0,.35);
  color: #b8893b;
  padding: 10px 12px;
  font-size: 12px;
  line-height: 1.45;
}
.pfx-player-deep-note {
  margin: 10px 0 0;
  color: #676767;
}
.pfx-player-deep-two {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.pfx-player-deep-two p {
  margin: 8px 0 0;
}
.pfx-player-deep-footer {
  padding: 12px 16px;
  border-radius: 7px;
  background: #1b1b1b;
  color: #686868;
  font-size: 12px;
  font-weight: 800;
