/* ── ProRes: setup modal ────────────────────────────────────────────────── */
.pfx-prores-overlay {
  position: fixed;
  inset: 0;
  z-index: 2147483640;
  background: rgba(0,0,0,.60);
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.pfx-prores-modal {
  width: 480px;
  max-width: calc(100vw - 32px);
  border-radius: 18px;
  background: rgb(16,14,22);
  border: 1px solid rgba(255,160,40,.35);
  box-shadow: 0 24px 64px rgba(0,0,0,.75);
  color: rgba(255,255,255,.88);
  font-size: 13px;
  overflow: hidden;
}
.pfx-prores-modal-hd {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 16px 20px 14px;
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.pfx-prores-modal-icon { font-size: 20px; line-height: 1; }
.pfx-prores-modal-title {
  flex: 1 1 auto;
  font-size: 15px;
  font-weight: 700;
  color: rgba(255,195,80,.98);
}
.pfx-prores-modal-x {
  width: 26px; height: 26px;
  border-radius: 50%;
  border: none;
  background: rgba(255,255,255,.08);
  color: rgba(255,255,255,.60);
  font-size: 16px;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: background .12s;
}
.pfx-prores-modal-x:hover { background: rgba(255,255,255,.16); color: #fff; }
.pfx-prores-modal-sub {
  padding: 12px 20px;
  font-size: 12px;
  color: rgba(255,255,255,.55);
  border-bottom: 1px solid rgba(255,255,255,.07);
  line-height: 1.5;
}
.pfx-prores-modal-fname {
  display: block;
  margin-top: 4px;
  font-family: ui-monospace, Menlo, monospace;
  font-size: 11px;
  color: rgba(255,255,255,.40);
  word-break: break-all;
}
/* Steps */
.pfx-prores-steps {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 6px 0;
}
.pfx-prores-step {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 14px 20px;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.pfx-prores-step:last-child { border-bottom: none; }
.pfx-prores-step-n {
  flex-shrink: 0;
  width: 26px; height: 26px;
  border-radius: 50%;
  background: rgba(255,160,40,.18);
  border: 1px solid rgba(255,160,40,.35);
  color: rgba(255,195,80,.95);
  font-size: 12px;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  margin-top: 1px;
}
.pfx-prores-step-bd { flex: 1 1 auto; display: flex; flex-direction: column; gap: 8px; }
.pfx-prores-step-title { font-weight: 600; font-size: 13px; color: rgba(255,255,255,.90); }
.pfx-prores-step-desc {
  font-size: 12px;
  color: rgba(255,255,255,.50);
  line-height: 1.55;
}
/* Download button */
.pfx-prores-dl-btn {
  align-self: flex-start;
  padding: 8px 18px;
  border-radius: 999px;
  border: 1px solid rgba(255,160,40,.50);
  background: rgba(255,120,0,.14);
  color: rgba(255,200,80,.95);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: background .12s, border-color .12s;
}
.pfx-prores-dl-btn:hover { background: rgba(255,120,0,.26); border-color: rgba(255,160,40,.75); }
.pfx-prores-dl-btn.is-done {
  border-color: rgba(100,220,100,.45);
  background: rgba(60,180,60,.12);
  color: rgba(140,240,140,.90);
  cursor: default;
}
/* Check button */
.pfx-prores-check-btn {
  align-self: flex-start;
  padding: 8px 18px;
  border-radius: 999px;
  border: 1px solid rgba(100,200,255,.35);
  background: rgba(60,140,255,.12);
  color: rgba(140,210,255,.95);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: background .12s;
}
.pfx-prores-check-btn:hover { background: rgba(60,140,255,.22); }
.pfx-prores-check-btn:disabled { opacity: .55; cursor: default; }
/* Check status line */
.pfx-prores-check-status {
  font-size: 12px;
  line-height: 1.4;
  min-height: 0;
}
.pfx-prores-check-status.is-ok  { color: rgba(100,240,120,.90); }
.pfx-prores-check-status.is-err { color: rgba(255,120,100,.90); }
/* Footer */
.pfx-prores-modal-ft {
  padding: 12px 20px 16px;
  border-top: 1px solid rgba(255,255,255,.07);
  display: flex;
  justify-content: flex-end;
}
.pfx-prores-close-btn {
  padding: 6px 20px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.15);
  background: rgba(255,255,255,.06);
  color: rgba(255,255,255,.65);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background .12s;
}
.pfx-prores-close-btn:hover { background: rgba(255,255,255,.12); color: #fff; }

/* ── ProRes Settings card — status indicator ────────────────────────────── */
.pfx-prs-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 600;
}
.pfx-prs-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
/* States */
.pfx-prs-checking .pfx-prs-dot { background: rgba(180,180,180,.55); }
.pfx-prs-checking              { color: rgba(255,255,255,.45); }

.pfx-prs-ready .pfx-prs-dot    { background: #4de878; box-shadow: 0 0 6px #4de878; }
.pfx-prs-ready                 { color: rgba(100,240,130,.90); }

.pfx-prs-warn .pfx-prs-dot     { background: #ffb930; box-shadow: 0 0 6px #ffb930; }
.pfx-prs-warn                  { color: rgba(255,200,80,.90); }

.pfx-prs-missing .pfx-prs-dot  { background: rgba(255,80,60,.70); }
.pfx-prs-missing               { color: rgba(255,255,255,.50); }

.pfx-prs-unknown .pfx-prs-dot  { background: rgba(140,140,180,.40); }
.pfx-prs-unknown               { color: rgba(255,255,255,.35); }

/* ── Proxy output dir path display ─────────────────────────────────────── */
.proxy-out-dir-path {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  font-family: var(--mono, monospace);
  color: rgba(255,255,255,.85);
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.10);
  border-radius: 5px;
  padding: 4px 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.proxy-out-dir-path.proxy-out-dir-default {
  color: rgba(255,255,255,.38);
  font-family: inherit;
  font-style: italic;
}

/* ── [Image #3] Timeline compare map bar — reduce height ───────────────── */
.cd-difftl                   { padding: 5px 10px 6px !important; }
.cd-difftl-head              { margin-bottom: 4px !important; gap: 4px !important; }
.cd-difftl-title             { font-size: 10px !important; }
.cd-modebtn                  { padding: 2px 8px !important; font-size: 10px !important; }
.cd-difftl-legend            { gap: 4px !important; padding-left: 6px !important; font-size: 10px !important; }
.cd-legend-item              { padding: 2px 6px !important; font-size: 10px !important; gap: 4px !important; }
.cd-legend-dot               { width: 7px !important; height: 7px !important; }

/* ── Smart Timeline Compare Map — super smart features ─────────────────── */

/* Rich hover tooltip */
.cd-tl-tooltip {
  position: fixed;
  z-index: 9999;
  pointer-events: none;
  background: rgba(14,14,24,.97);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 9px;
  padding: 9px 12px;
  font-size: 11px;
  color: rgba(255,255,255,.88);
  box-shadow: 0 6px 24px rgba(0,0,0,.6), 0 0 0 1px rgba(255,255,255,.05);
  display: none;
  max-width: 270px;
  min-width: 190px;
  line-height: 1.65;
}
.cd-tl-tooltip.is-visible { display: block; }
.cd-tl-tooltip-clip {
  font-weight: 700;
  font-size: 11.5px;
  color: rgba(255,255,255,.92);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 230px;
}
.cd-tl-tooltip-row {
  display: flex;
  gap: 10px;
  font-size: 10px;
  color: rgba(255,255,255,.52);
  margin-top: 2px;
}
.cd-tl-tooltip-note {
  margin-top: 5px;
  font-size: 10px;
  font-style: italic;
  color: rgba(255,255,255,.40);
  border-top: 1px solid rgba(255,255,255,.08);
  padding-top: 4px;
}
.cd-tl-tooltip-badges {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 5px;
}
.cd-tt-type {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .6px;
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: uppercase;
}
.cd-tt-type-new      { background: color-mix(in srgb, var(--diff-new) 22%, transparent); color: var(--diff-new); }
.cd-tt-type-extended { background: color-mix(in srgb, var(--diff-extended) 22%, transparent); color: var(--diff-extended); }
.cd-tt-type-changed  { background: color-mix(in srgb, var(--diff-changed) 22%, transparent); color: var(--diff-changed); }
.cd-tt-type-removed  { background: color-mix(in srgb, var(--diff-removed) 22%, transparent); color: var(--diff-removed); }

/* Risk strips on bottom edge of diff segments */
.cd-seg.is-risk-high::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 3px;
  background: rgba(255,60,60,.72);
  border-radius: 0 0 6px 6px;
  pointer-events: none;
}
.cd-seg.is-risk-med::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 3px;
  background: rgba(240,195,55,.62);
  border-radius: 0 0 6px 6px;
  pointer-events: none;
}

/* Density heatmap bar */
.cd-density-bar {
  position: relative;
  height: 22px;
  margin: 3px 0 4px;
  border-radius: 5px;
  overflow: hidden;
  background: rgba(255,255,255,.025);
  border: 1px solid rgba(255,255,255,.07);
  display: none;
}
.cd-difftl[data-mode="compare"] .cd-density-bar { display: block; }
.cd-density-bar::before {
  content: "DENSITY";
  position: absolute;
  left: 6px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .7px;
  color: rgba(255,255,255,.18);
  pointer-events: none;
  z-index: 1;
}
.cd-density-bucket {
  position: absolute;
  bottom: 0;
  border-radius: 2px 2px 0 0;
  opacity: .70;
}
.cd-density-bucket.has-new      { background: color-mix(in srgb, var(--diff-new) 72%, rgba(255,255,255,.1)); }
.cd-density-bucket.has-extended { background: color-mix(in srgb, var(--diff-extended) 72%, rgba(255,255,255,.1)); }
.cd-density-bucket.has-changed  { background: color-mix(in srgb, var(--diff-changed) 72%, rgba(255,255,255,.1)); }
.cd-density-bucket.has-removed  { background: color-mix(in srgb, var(--diff-removed) 72%, rgba(255,255,255,.1)); }

/* Cluster badge in title */
.cd-cluster-info {
  margin-left: 7px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .5px;
  color: rgba(255,255,255,.28);
  text-transform: uppercase;
  vertical-align: middle;
}
.cd-cluster-info.has-clusters { color: rgba(255,200,70,.60); }

/* ── [Image #4] Timeline tracks — more height ──────────────────────────── */
.cd-difftl                   { min-height: 200px !important; }
.cd-difftl-viewport          { min-height: 120px !important; padding: 10px 10px 10px !important; }
.cd-difftl-tracks            { gap: 10px !important; }
