/* ── T-CONFORM In/Out markers on VS Timeline ────────────────────────────── */
.tcf-tl-in-marker, .tcf-tl-out-marker {
  position: absolute; top: 0; bottom: 0; width: 2px;
  pointer-events: none; z-index: 15; transform: translateX(-50%);
}
.tcf-tl-in-marker  { background: #2be6a7; box-shadow: 0 0 4px rgba(43,230,167,.6); }
.tcf-tl-out-marker { background: #2172E3; box-shadow: 0 0 4px rgba(255,215,106,.6); }
.tcf-tl-in-marker::after, .tcf-tl-out-marker::after {
  content: attr(title);
  position: absolute; top: 2px; left: 4px;
  font-size: 8px; font-weight: 700; font-family: ui-monospace,monospace;
  color: inherit; white-space: nowrap; pointer-events: none;
}

/* ── Keyboard shortcut overlay ──────────────────────────────────────────── */
.tcf-kb-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,.65);
  display: flex; align-items: center; justify-content: center;
  z-index: 99999; backdrop-filter: blur(4px);
}
.tcf-kb-overlay-box {
  background: rgb(20,20,28); border: 1px solid rgba(255,255,255,.14);
  border-radius: 12px; padding: 20px 24px; max-width: 540px; width: 90%;
  max-height: 85vh; overflow-y: auto; box-shadow: 0 20px 60px rgba(0,0,0,.7);
}
.tcf-kb-overlay-title {
  font-size: 13px; font-weight: 700; color: #e0e0e0;
  margin-bottom: 16px; display: flex; justify-content: space-between; align-items: center;
}
.tcf-kb-overlay-close { cursor: pointer; color: #888; font-size: 14px; }
.tcf-kb-overlay-close:hover { color: #fff; }
.tcf-kb-overlay-grid {
  display: grid; grid-template-columns: auto 1fr; gap: 5px 12px; align-items: center;
}
.tcf-kb-section {
  grid-column: 1 / -1; font-size: 9px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .08em;
  color: rgba(185,122,255,.7); margin-top: 10px; padding-top: 6px;
  border-top: 1px solid rgba(255,255,255,.07);
}
.tcf-kb-overlay-grid kbd {
  display: inline-flex; align-items: center; gap: 2px;
  background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.15);
  border-radius: 4px; padding: 2px 6px; font-size: 10px;
  font-family: ui-monospace,monospace; color: #ccc; white-space: nowrap;
}
.tcf-kb-overlay-grid span { font-size: 11px; color: rgba(255,255,255,.6); }

/* ── T-CONFORM keyboard hint toast ─────────────────────────────────────── */
.tcf-kb-hint {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  background: rgba(20,20,28,.92);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 8px;
  padding: 5px 14px;
  font-size: 12px;
  font-weight: 600;
  color: #e0e0e0;
  pointer-events: none;
  opacity: 0;
  transition: opacity .15s, transform .15s;
  z-index: 9999;
  white-space: nowrap;
  backdrop-filter: blur(6px);
}
.tcf-kb-hint.tcf-kb-hint-show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* =============================================================
   Global How to Use Button — color follows active tab
============================================================= */
#btnTutorial {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 11px 3px 9px;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: 20px;
  border: 1px solid var(--pfx-tutorial-btn-glow, rgba(255,255,255,.25));
  background: color-mix(in srgb, var(--pfx-tutorial-btn-glow, rgba(255,255,255,.12)) 12%, rgba(0,0,0,.35));
  color: color-mix(in srgb, var(--pfx-tutorial-btn-glow, #fff) 80%, #fff);
  cursor: pointer;
  transition: border-color .2s, background .2s, color .2s, box-shadow .2s, opacity .2s;
  white-space: nowrap;
  opacity: 0.85;
}
#btnTutorial:hover {
  opacity: 1;
  border-color: var(--pfx-tutorial-btn-glow, rgba(255,255,255,.5));
  background: color-mix(in srgb, var(--pfx-tutorial-btn-glow, rgba(255,255,255,.2)) 20%, rgba(0,0,0,.3));
  box-shadow:
    0 0 10px color-mix(in srgb, var(--pfx-tutorial-btn-glow, #fff) 45%, transparent),
    0 0 20px color-mix(in srgb, var(--pfx-tutorial-btn-glow, #fff) 20%, transparent);
}
