/* =============================================================
   Fun Box — Final layout fix v3: perfect Minesweeper
   Row 1 = 430px min  → board-wrap ≥ 260px → 16px cells ✓
   Row 2 = 316px min  → snake 252px + header
   Row 3 = auto       → quote
   Panel raised to top=110px for maximum available height.
============================================================= */

.top-aux.funbox-open .top-aux-panel,
.top-aux-panel.pfx-aux-panel-funbox {
  top: 110px !important;
}

@media (min-width: 1320px) {
  /* Row 1: 430px min gives board-wrap ~260px → 16px Intermediate cells.
     Row 2: 316px min fits snake canvas (252px) + card header.
     Row 3: quote, auto-height. */
  .top-aux.funbox-open .top-aux-pane[data-pane="funbox"] .top-aux-pane-body {
    grid-template-rows: minmax(430px, 1.5fr) minmax(316px, 1fr) auto !important;
    align-items: stretch !important;
  }

  /* Apple card: fill the row height, iframe expands to fill */
  .top-aux.funbox-open .top-aux-pane[data-pane="funbox"] .fun-card.fun-card-apple {
    min-height: 0 !important;
    max-height: none !important;
    flex-basis: auto !important;
    height: 100% !important;
  }

  /* Mines card: fill row height, allow internal flex chain to work */
  .top-aux.funbox-open .top-aux-pane[data-pane="funbox"] .fun-card.fun-card-mines {
    min-height: 0 !important;
    max-height: none !important;
    flex-basis: auto !important;
    height: 100% !important;
