/* ── PostFlowX IMF Folder Confirm Modal ──────────────────────────────────── */
.pfx-confirm-backdrop {
  position: fixed; inset: 0;
  background: rgba(0,0,0,.72);
  backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center;
  z-index: 99999;
  animation: pfxConfirmFadeIn .15s ease;
}
@keyframes pfxConfirmFadeIn { from { opacity:0 } to { opacity:1 } }

.pfx-confirm-modal {
  background: #14141f;
  border: 1px solid var(--pfx-border-default);
  border-radius: 14px;
  padding: 28px 28px 22px;
  width: 380px; max-width: 90vw;
  box-shadow: 0 0 0 1px rgba(255,255,255,.04) inset,
              0 20px 60px rgba(0,0,0,.7), 0 0 40px rgba(0,0,0,.12);
  display: flex; flex-direction: column; gap: 18px;
  animation: pfxConfirmSlideUp .18s cubic-bezier(.2,.8,.4,1);
}
@keyframes pfxConfirmSlideUp { from { transform:translateY(8px); opacity:0 } to { transform:none; opacity:1 } }

.pfx-confirm-icon {
  width: 52px; height: 52px;
  background: var(--pfx-accent-soft);
  border: 1px solid var(--pfx-accent-border);
  border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
}

.pfx-confirm-body { display: flex; flex-direction: column; gap: 6px; }

.pfx-confirm-title {
  font-size: 15px; font-weight: 700; color: #e0e0f0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

.pfx-confirm-desc {
  font-size: 12px; color: #666; line-height: 1.6;
}

.pfx-confirm-pill {
  display: inline-block; padding: 1px 7px;
  background: var(--pfx-accent-soft); border: 1px solid var(--pfx-accent-border);
  border-radius: 999px; color: var(--pfx-accent); font-size: 10px; font-weight: 600;
  margin: 0 2px;
}

.pfx-confirm-hint {
  display: block; margin-top: 6px; font-size: 10px; color: #3a3a58;
}

.pfx-confirm-actions {
  display: flex; justify-content: flex-end; gap: 10px;
}

.pfx-confirm-btn {
  padding: 8px 20px; border-radius: 8px; border: none;
  font-size: 13px; font-weight: 600; cursor: pointer;
  transition: background .12s, transform .08s;
}
.pfx-confirm-btn:active { transform: scale(.97); }

.pfx-confirm-btn-cancel {
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.08);
  color: #555;
}
.pfx-confirm-btn-cancel:hover { background: rgba(255,255,255,.09); color: #888; }

.pfx-confirm-btn-ok {
  background: var(--pfx-accent); color: #fff;
  box-shadow: 0 2px 12px rgba(90,167,255,.28);
}
.pfx-confirm-btn-ok:hover { background: #7bbfff; }

/* ── End IMF Confirm Modal ─────────────────────────────────────────────────── */

.mb-modal-backdrop {
  position: fixed; inset: 0; background: rgba(0,0,0,.65);
  display: flex; align-items: center; justify-content: center; z-index: 9000;
}
.mb-modal {
  background: #1e1e2e; border: 1px solid #444; border-radius: 10px;
  width: 480px; max-width: 94vw; overflow: hidden;
  box-shadow: 0 8px 40px rgba(0,0,0,.6);
}
.mb-modal-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 18px; border-bottom: 1px solid #333;
  font-size: 13px; font-weight: 600; color: #e0e0e0;
}
.mb-close-btn {
  background: none; border: none; color: #888; font-size: 16px;
  cursor: pointer; padding: 2px 6px; border-radius: 4px;
}
.mb-close-btn:hover { color: #fff; background: #333; }
.mb-drop-zone {
  margin: 16px; border: 2px dashed #555; border-radius: 8px;
  padding: 28px 16px; text-align: center; color: #888; font-size: 13px;
  transition: border-color .15s, background .15s;
}
.mb-dz-hover { border-color: var(--pfx-accent) !important; background: var(--pfx-accent-soft) !important; }
.mb-browse-btn {
  margin-top: 10px; padding: 6px 14px; border-radius: 6px;
  border: 1px solid #555; background: #2a2a3e; color: #ccc;
  cursor: pointer; font-size: 12px; display: block; margin-left: auto; margin-right: auto;
}
.mb-browse-btn:hover { background: #333; }
.mb-file-list { padding: 0 18px; max-height: 120px; overflow-y: auto; }
.mb-file-item { font-size: 12px; color: #aaa; padding: 4px 0; }
.mb-file-item span { color: #666; margin-left: 6px; }
.mb-status { padding: 8px 18px 14px; font-size: 12px; color: var(--pfx-accent); min-height: 32px; }
.mb-modal-footer {
  display: flex; justify-content: flex-end; align-items: center; gap: 10px;
  padding: 12px 18px; border-top: 1px solid #333;
}
.mb-action-btn {
  padding: 7px 20px; border-radius: 6px; border: none;
  font-size: 13px; font-weight: 600; cursor: pointer;
}
.mb-btn-apply { background: var(--pfx-accent); color: #fff; }
.mb-btn-apply:hover:not(:disabled) { background: #7bbfff; }
.mb-btn-apply:disabled { opacity: .4; cursor: default; }
.mb-btn-reset { background: #333; color: #ccc; }
.mb-btn-reset:hover { background: #444; }

/* ── Match Back reel badge ────────────────────────────────────────────────── */
.evt-mb-badge {
  display: inline-block; background: #1a3a2a; color: #0AA356;
  border: 1px solid #0AA356; font-size: 9px; font-weight: 700;
  padding: 1px 4px; border-radius: 3px; margin-left: 3px;
  vertical-align: middle; line-height: 1.4;
}

/* ═══════════════════════════════════════════════════════════════════════════
   IMF Validation Tab
   ═══════════════════════════════════════════════════════════════════════════ */
/* ── IMF VALIDATION tab ───────────────────────────────────────────────────── */
.tab.theme-imf { --tab-color: var(--pfx-accent); }
.tab.theme-imf .bar { background: var(--tab-color); }
.tab.theme-imf:hover, .tab.theme-imf.active { color: var(--tab-color); }

/* ── IMF Validation — PostFlowX Pro theme ──────────────────────────────────
   One accent (--pfx-accent). Semantic status only. No neon.
   ────────────────────────────────────────────────────────────────────────── */

/* Shell: fills the pane, flex column */
.imf-shell {
  display: flex; flex-direction: column;
  height: calc(100vh - 86px); overflow: hidden;
  background: #0e0e14;
}

/* Empty / loading state: centered in full area */
.imf-empty-state {
  flex: 1; display: flex; flex-direction: column;
  align-items: center; justify-content: center;
}

/* Drop zone card */
.imf-dz-inner {
  display: flex; flex-direction: column; align-items: center; gap: 10px;
  text-align: center;
  width: 340px;
  background: linear-gradient(160deg, #16161f 0%, #111119 100%);
  border: 1.5px dashed #2a2a3c;
  border-radius: 14px;
  padding: 40px 40px 28px;
  cursor: pointer;
  color: #3d3d55;
  transition: border-color .18s, background .18s, box-shadow .18s;
  box-shadow: 0 4px 24px rgba(0,0,0,.4), inset 0 0 0 1px rgba(255,255,255,.03);
}
.imf-dz-inner:hover,
.imf-dz-hover {
  border-color: var(--pfx-accent-border);
  background: linear-gradient(160deg, #13151e 0%, #0f1018 100%);
  color: var(--pfx-accent);
  box-shadow: 0 4px 32px rgba(90,167,255,.08), inset 0 0 0 1px rgba(90,167,255,.06);
}
.imf-dz-inner svg { opacity: .45; transition: opacity .18s; }
.imf-dz-inner:hover svg, .imf-dz-hover svg { opacity: 1; }

/* Drop zone text */
.imf-dz-text {
  font-size: 13px; font-weight: 700; letter-spacing: .03em;
  color: #9090aa; margin-top: 4px;
  transition: color .18s;
}
.imf-dz-inner:hover .imf-dz-text,
.imf-dz-hover .imf-dz-text { color: var(--pfx-accent); }

.imf-dz-sub {
  font-size: 11px; color: #36364a; letter-spacing: .02em;
  transition: color .18s;
}
.imf-dz-inner:hover .imf-dz-sub,
.imf-dz-hover .imf-dz-sub { color: rgba(90,167,255,.45); }

/* Divider */
.imf-dz-or {
  font-size: 10px; color: #2e2e44; letter-spacing: .08em;
  text-transform: uppercase; margin: 4px 0;
}

/* Browse Folder button */
.imf-browse-btn {
  margin-top: 6px; padding: 7px 22px;
  border-radius: 8px;
  border: 1px solid #2e2e46;
  background: linear-gradient(180deg, #1e1e2e 0%, #18181f 100%);
  color: #8888aa; font-size: 12px; font-weight: 600;
  cursor: pointer; letter-spacing: .03em;
  transition: border-color .15s, color .15s, background .15s, box-shadow .15s;
  /* Ensure button is always clickable — no overlay can block it */
  position: relative; z-index: 10; pointer-events: auto;
}
.imf-browse-btn:hover {
  border-color: var(--pfx-accent-border);
  color: var(--pfx-accent);
  background: linear-gradient(180deg, #141620 0%, #101218 100%);
  box-shadow: none;
}

/* Browser-dialog hint */
.imf-browse-hint {
  font-size: 10px; color: #2d2d40; text-align: center;
  margin-top: 4px; line-height: 1.5;
}

/* Spinner */
.imf-spinner {
  width: 32px; height: 32px;
  border: 2.5px solid #1e1e2c;
  border-top-color: var(--pfx-accent);
  border-radius: 50%;
  animation: imf-spin .7s linear infinite;
}
@keyframes imf-spin { to { transform: rotate(360deg); } }

/* 3-column loaded layout — grid-template-rows:1fr gives the single row a definite height */
.imf-3col {
  flex: 1; min-height: 0;
  display: grid;
  grid-template-columns: 450px 1fr;
  grid-template-rows: 1fr;
  overflow: hidden;
}

/* Individual columns — stretch via grid; pure flex chain, no height:100% */
.imf-col {
  display: flex; flex-direction: column;
  min-height: 0; overflow: hidden;
  border-right: 1px solid #1a1a2e; background: #080810;
}
.imf-col-main { border-right: none; background: #000; }

/* Column header */
.imf-col-hdr { display: flex; align-items: center; justify-content: space-between; padding: 8px 14px; border-bottom: 1px solid #1e1e2e; background: #13131e; flex-shrink: 0; }
.imf-col-title { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: #666; }

/* Status badge */
.imf-status { font-size: 10px; font-weight: 600; padding: 2px 8px; border-radius: 4px; }
.imf-status-idle    { background: #1e1e2e; color: #555; }
.imf-status-ok      { background: #1a3a2a; color: #0AA356; }
.imf-status-warn    { background: #3a341a; color: #f0c36d; }
.imf-status-loading { background: #1a2a3a; color: var(--pfx-info); }
.imf-status-error   { background: #3a1a1a; color: #E5484D; }

/* KPI grid — scrollable, fills column */
.imf-kpi-grid { overflow-y: auto; padding: 2px 0; }
.imf-kpi-row { display: flex; padding: 3px 14px; font-size: 11px; border-bottom: 1px solid #1a1a28; gap: 8px; align-items: baseline; }
.imf-kpi-row:hover { background: #1a1a28; }
.imf-kpi-key { flex: 0 0 96px; color: #555; font-size: 10px; }
.imf-kpi-val { color: #ccc; word-break: break-all; flex: 1; font-size: 11px; }

/* ── Left panel tabs ────────────────────────────────────────────────────── */
.imf-left-tabs {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  flex-shrink: 0;
  border-bottom: 1px solid #1a1a2e;
  background: #0d0d18;
  padding: 0 6px 6px;
  gap: 2px 1px;
}
.imf-left-tab {
  background: none; border: none; border-bottom: 2px solid transparent;
  color: #3a3a58; font-size: 9px; font-weight: 700; text-transform: uppercase;
  letter-spacing: .06em; padding: 6px 8px 5px; cursor: pointer; margin-bottom: -1px;
  white-space: nowrap; transition: color .12s;
  display: inline-flex; align-items: center; gap: 6px;
}
.imf-left-tab:hover { color: #777; }
.imf-left-tab-active { color: var(--pfx-accent) !important; border-bottom-color: var(--pfx-accent); }
.imf-left-tab-badge {
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--pfx-accent-soft);
  color: var(--pfx-text-primary);
  border: 1px solid var(--pfx-accent-border);
  font-size: 8px;
  letter-spacing: .05em;
  line-height: 1.4;
}
.imf-left-tab-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  width: 100%;
  margin-left: 0;
  padding: 6px 0 0;
  border-top: 1px solid rgba(255,255,255,.05);
}
.imf-ltab-panel {
  display: flex;
  flex-direction: column;
  flex: 1 1 0;
  min-height: 0;
  height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}
#imfLtabTranscode { gap: 10px; }
#imfLtabTranscode .imf-proxy-panel { height: auto; }
.imf-proxy-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px;
  height: 100%;
  background: linear-gradient(180deg, rgba(18,18,28,.9), rgba(12,12,20,.94));
}
.imf-proxy-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.imf-proxy-panel-title {
  font-size: 12px;
  font-weight: 800;
  color: #ecebff;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.imf-proxy-panel-state {
  padding: 3px 8px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.08);
  background: rgba(255,255,255,.04);
  color: rgba(255,255,255,.72);
  font-size: 10px;
  font-weight: 700;
}
.imf-proxy-panel-state[data-state="running"] {
  color: var(--pfx-text-primary);
  background: var(--pfx-accent-soft);
  border-color: var(--pfx-accent-border);
}
.imf-proxy-panel-state[data-state="done"] {
  color: #d8ffea;
  background: rgba(10,163,86,.14);
  border-color: rgba(10,163,86,.24);
}
.imf-proxy-panel-state[data-state="error"] {
  color: #ffd8d8;
  background: rgba(224,108,117,.14);
  border-color: rgba(224,108,117,.24);
}
.imf-proxy-panel-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.imf-proxy-meta {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 12px;
  background: rgba(255,255,255,.03);
}
.imf-proxy-meta-row {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.imf-proxy-meta-k {
  font-size: 9px;
  color: rgba(255,255,255,.42);
  text-transform: uppercase;
  letter-spacing: .08em;
}
.imf-proxy-meta-v {
  font-size: 11px;
  color: rgba(255,255,255,.88);
  word-break: break-word;
}
.imf-proxy-progress-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid var(--pfx-accent-border);
  background: linear-gradient(180deg, var(--pfx-accent-soft), rgba(255,255,255,.03));
}
.imf-proxy-progress-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.imf-proxy-progress-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--pfx-text-secondary);
  letter-spacing: .05em;
  text-transform: uppercase;
}
.imf-proxy-progress-pct {
  font-size: 12px;
  font-weight: 800;
  color: #f3f0ff;
}
.imf-proxy-progress-bar-wrap {
  height: 8px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(0,0,0,.26);
  border: 1px solid rgba(255,255,255,.06);
}
.imf-proxy-progress-bar {
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--pfx-accent), rgba(90,167,255,.7));
  transition: width .25s ease;
}
.imf-proxy-panel-note {
  font-size: 10px;
  line-height: 1.45;
  color: rgba(255,255,255,.5);
}
/* IMF Engine / Photon status chips */
.imf-engine-chip {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 10px;
  font-size: 9px;
  font-weight: 600;
  border: 1px solid rgba(255,255,255,.15);
  background: rgba(255,255,255,.06);
  color: rgba(255,255,255,.5);
  line-height: 1.6;
}
.imf-engine-chip-ready    { background: rgba(10,163,86,.18); border-color: rgba(10,163,86,.4); color: #0AA356; }
.imf-engine-chip-partial  { background: rgba(255,183,77,.12); border-color: rgba(255,183,77,.35); color: #ffb74d; }
.imf-engine-chip-missing  { background: rgba(255,85,85,.12);  border-color: rgba(255,85,85,.3);  color: #f55; }
.imf-engine-chip-unknown  { background: rgba(255,255,255,.05); border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.4); }
.imf-proxy-debug-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid var(--pfx-border-default);
  background: rgba(255,255,255,.025);
}
.imf-proxy-debug-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.imf-proxy-debug-title {
  font-size: 10px;
  font-weight: 800;
  color: var(--pfx-text-secondary);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.imf-proxy-debug-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
  color: var(--pfx-text-secondary);
  border: 1px solid var(--pfx-border-default);
  background: rgba(255,255,255,.07);
  white-space: nowrap;
}
.imf-proxy-debug-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 12px;
}
.imf-proxy-debug-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.imf-proxy-debug-k {
  font-size: 9px;
  color: rgba(255,255,255,.42);
  text-transform: uppercase;
  letter-spacing: .08em;
}
.imf-proxy-debug-v {
  font-size: 10px;
  color: rgba(255,255,255,.88);
  word-break: break-word;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
.imf-proxy-debug-log {
  max-height: 112px;
  overflow: auto;
  padding: 8px;
  border-radius: 8px;
  border: 1px solid rgba(255,255,255,.06);
  background: rgba(0,0,0,.22);
  font: 10px/1.45 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  color: rgba(255,255,255,.74);
  white-space: pre-wrap;
}
.imf-decode-panel .imf-proxy-progress-card {
  border-color: var(--pfx-accent-border);
  background: linear-gradient(180deg, var(--pfx-accent-soft), rgba(255,255,255,.03));
}
.imf-decode-progress-bar {
  background: linear-gradient(90deg, var(--pfx-accent), rgba(90,167,255,.7));
}

/* ── Package Info accordion ─────────────────────────────────────────────── */
.imf-pkg-accordion { flex-shrink: 0; border-bottom: 1px solid #1e1e2e; }
.imf-pkg-toggle {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; padding: 7px 14px; background: #13131e;
  border: none; cursor: pointer; text-align: left; gap: 8px;
  transition: background .12s;
}
.imf-pkg-toggle:hover { background: #1a1a2a; }
.imf-pkg-toggle-label { display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0; }
.imf-pkg-chevron { color: #555; font-size: 10px; flex-shrink: 0; transition: transform .15s; }
.imf-pkg-toggle[aria-expanded="true"] .imf-pkg-chevron { transform: rotate(90deg); color: var(--pfx-accent); }
.imf-pkg-body { max-height: 220px; overflow-y: auto; }
.imf-uuid { font-family: monospace; font-size: 10px; color: #777; }

/* Validation column */
.imf-val-actions { display: flex; gap: 5px; }
.imf-action-btn { padding: 3px 10px; border-radius: 5px; border: 1px solid var(--pfx-border-default); font-size: 10px; font-weight: 700; cursor: pointer; background: rgba(255,255,255,.07); color: var(--pfx-text-secondary); letter-spacing: .03em; }
.imf-action-btn:hover:not(:disabled) { background: rgba(255,255,255,.12); color: var(--pfx-text-primary); }
.imf-action-btn:disabled { opacity: .4; cursor: default; }
.imf-btn-iab { background: var(--pfx-warning-soft); border-color: var(--pfx-warning-border); color: #efd28a; }
.imf-btn-iab:hover:not(:disabled) { background: rgba(214,163,58,.22); }
.imf-btn-generate { background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); color: var(--pfx-accent); }
.imf-btn-generate:hover:not(:disabled) { background: rgba(90,167,255,.26); }
.imf-iab-waveform-header { display: flex; align-items: center; gap: 6px; margin-top: 6px; }
.imf-iab-waveform-label { flex: 1; font-size: 9px; color: var(--pfx-text-tertiary); }
.imf-iab-waveform-play-btn { flex-shrink: 0; padding: 2px 7px; border-radius: 4px; border: 1px solid var(--pfx-accent-border); background: var(--pfx-accent-soft); color: var(--pfx-accent); font-size: 10px; cursor: pointer; line-height: 1.4; }
.imf-iab-waveform-play-btn:hover { background: rgba(90,167,255,.26); }
