/* IAB labels QC panel */
.imf-labels-head {
  padding: 6px 8px;
  border-bottom: 1px solid #1a1a2e;
  background: #101018;
}
.imf-labels-toolbar {
  display: flex;
  align-items: center;
  gap: 5px;
}
.imf-labels-title {
  font-size: 10px;
  font-weight: 800;
  color: #c8c4ef;
  letter-spacing: .05em;
  text-transform: uppercase;
  flex-shrink: 0;
  margin-right: 2px;
}
.imf-label-input,
.imf-label-select {
  height: 24px;
  border-radius: 5px;
  border: 1px solid rgba(255,255,255,.08);
