.imf-label-input {
  flex: 1 1 90px;
  min-width: 70px;
}
.imf-label-select {
  min-width: 70px;
}
.imf-label-input::placeholder {
  color: rgba(255,255,255,.25);
}
.imf-label-count {
  flex-shrink: 0;
  padding: 2px 7px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.07);
  background: rgba(255,255,255,.03);
  color: rgba(255,255,255,.35);
  font-size: 8.5px;
  font-weight: 600;
  white-space: nowrap;
}
.imf-label-meta {
  padding: 3px 8px 0;
  color: #48475e;
  font-size: 8.5px;
  line-height: 1.3;
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.imf-label-summary {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  padding: 4px 8px;
  border-bottom: 1px solid #181826;
  background: #0c0c14;
}
.imf-label-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.08);
  background: rgba(255,255,255,.04);
  font-size: 9px;
  font-weight: 700;
  color: #d5d1ef;
}
.imf-label-pill-pass {
  color: #8fe0ae;
  border-color: rgba(10,163,86,.22);
  background: rgba(10,163,86,.10);
}
.imf-label-pill-warn {
  color: #f1cf8a;
  border-color: rgba(224,179,65,.22);
  background: rgba(224,179,65,.10);
}
.imf-label-pill-reject {
  color: #f29aa8;
  border-color: rgba(224,108,117,.22);
  background: rgba(224,108,117,.10);
}
.imf-label-table-wrap {
  flex: 0 0 auto;
  min-height: auto;
  overflow: visible;
  background: #080810;
}
.imf-label-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 10.5px;
}
.imf-label-table thead {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #101018;
}
.imf-label-table th {
  padding: 4px 8px;
  border-bottom: 1px solid #1a1a2e;
