  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  text-align: left;
}
.imf-label-table th:first-child { color: transparent; }
.imf-label-table th:first-child,
.imf-label-table td:first-child {
  width: 22px;
}
.imf-label-table th:nth-child(2),
.imf-label-table td:nth-child(2) {
