  border: 1px solid rgba(255,255,255,.08);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .04em;
}
.imf-label-status-pass {
  color: #8fe0ae;
  border-color: rgba(10,163,86,.24);
  background: rgba(10,163,86,.10);
}
.imf-label-status-warn {
  color: #f1cf8a;
  border-color: rgba(224,179,65,.24);
  background: rgba(224,179,65,.10);
}
.imf-label-status-reject {
  color: #f29aa8;
  border-color: rgba(224,108,117,.24);
  background: rgba(224,108,117,.10);
}
.imf-label-mapped {
  color: #ece9ff;
  font-weight: 700;
}
.imf-label-main {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.imf-label-raw {
  color: #f4f1ff;
  font-weight: 700;
  font-size: 10.5px;
  line-height: 1.3;
  margin-bottom: 2px;
}
/* Inline layout: MAPPED — ·  SOURCE path  ·  FIX message on one line each */
.imf-label-mapped-line,
.imf-label-source-line,
.imf-label-fix-line {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}
.imf-label-mini-k {
  flex-shrink: 0;
  min-width: 42px;
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: .07em;
  color: #4e4c62;
  font-weight: 700;
}
.imf-label-source {
  color: #7a7896;
  font-family: monospace;
  font-size: 9.5px;
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.imf-label-fix {
  color: #b0acd0;
  font-size: 9.5px;
  line-height: 1.35;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  min-width: 0;
