/* ── Smart compact label rows ─────────────────────────────────────────────── */
.imf-lbl-row td { padding: 5px 6px; border-bottom: 1px solid #111120; vertical-align: middle; }
.imf-lbl-row:hover td { background: rgba(255,255,255,.025); }

/* Status-tinted row backgrounds */
.imf-lbl-row-warn td  { background: rgba(224,179,65,.03); }
.imf-lbl-row-reject td { background: rgba(224,108,117,.04); }
.imf-lbl-row-warn:hover td  { background: rgba(224,179,65,.07); }
.imf-lbl-row-reject:hover td { background: rgba(224,108,117,.08); }

/* Dot indicator column */
.imf-lbl-st-cell { width: 22px; text-align: center; padding: 5px 0 5px 6px !important; vertical-align: middle; }
.imf-lbl-dot {
  display: inline-block;
  width: 7px; height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.imf-lbl-dot-pass   { background: #0AA356; }
.imf-lbl-dot-warn   { background: #E0B341; }
.imf-lbl-dot-reject { background: #E5484D; }

/* Body cell */
.imf-lbl-body { padding: 5px 8px 5px 4px !important; }

/* Top row: name + group chip */
.imf-lbl-top {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.imf-lbl-name {
  font-size: 10.5px;
  font-weight: 700;
  color: #edeaff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex-shrink: 1;
  min-width: 0;
}

/* Group chip */
.imf-lbl-chip {
  flex-shrink: 0;
  font-size: 8px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(255,255,255,.05);
  color: rgba(255,255,255,.45);
  letter-spacing: .03em;
  white-space: nowrap;
}
/* Per-group chip colours — muted, info-scale only */
.imf-lbl-chip-dialogue   { background: var(--pfx-info-soft); border-color: var(--pfx-info-border); color: var(--pfx-info); }
.imf-lbl-chip-music      { background: var(--pfx-success-soft); border-color: var(--pfx-success-border); color: #8fe0ae; }
.imf-lbl-chip-effects    { background: var(--pfx-warning-soft); border-color: var(--pfx-warning-border); color: #efd28a; }
.imf-lbl-chip-narration  { background: rgba(255,255,255,.05); border-color: rgba(255,255,255,.12); color: rgba(255,255,255,.5); }
.imf-lbl-chip-none       { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.3); }

/* Detail row: source + fix — only for WARN / REJECT */
.imf-lbl-detail {
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin-top: 3px;
  min-width: 0;
}
.imf-lbl-src {
  font-family: monospace;
  font-size: 9px;
  color: #4e4c68;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.imf-lbl-fix {
  font-size: 9px;
  color: #9d98be;
  line-height: 1.3;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

/* Timeline column */
.imf-tl-body { position: relative; padding: 8px 14px 6px; display: flex; flex-direction: column; gap: 5px; flex-shrink: 0; user-select:none; }
.imf-tl-ruler { position: relative; height: 18px; border-bottom: 1px solid #2a2a3e; overflow:hidden; }
.imf-tl-ruler-inner { position:absolute; inset:0 auto 0 0; height:100%; transform-origin:0 0; will-change:transform; }
.imf-tl-tick { position: absolute; top: 0; font-size: 9px; color: #444; transform: translateX(-50%); white-space: nowrap; }
.imf-tl-row { display: flex; align-items: center; gap: 6px; height: 24px; }
.imf-tl-label { flex: 0 0 40px; font-size: 9px; font-weight: 700; color: #555; text-align: right; padding-right: 6px; }
.imf-tl-track { flex: 1; position: relative; display: block; height: 20px; background: #0d0d14; border-radius: 3px; overflow: hidden; cursor:pointer; }
.imf-tl-track-inner { position:absolute; inset:0 auto 0 0; height:100%; transform-origin:0 0; will-change:transform; }
.imf-tl-seg { position: absolute; top:0; bottom:0; cursor: pointer; opacity: .88; transition: opacity .1s; min-width: 3px; }
.imf-tl-playhead { position:absolute; top:0; bottom:0; width:2px; background: linear-gradient(180deg, rgba(255,255,255,0.95), rgba(90,167,255,0.7)); box-shadow: 0 0 0 1px rgba(0,0,0,0.35); pointer-events:none; z-index:6; }
.imf-tl-ruler .imf-tl-playhead { top:0; bottom:-1px; }
.imf-tl-playhead::before { content:""; position:absolute; left:50%; top:-1px; width:8px; height:8px; border-radius:999px; transform:translate(-50%, -30%); background:var(--pfx-accent); box-shadow:0 0 0 2px rgba(255,255,255,0.7); }
.imf-tl-track:hover { box-shadow: inset 0 0 0 1px rgba(255,255,255,0.06); }
.imf-tl-seg:hover { opacity: 1; outline: 1px solid rgba(255,255,255,.4); }
.imf-tl-seg-audio { background: #1e3040 !important; opacity: 1; }
.imf-tl-reel-label { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 9px; font-weight: 700; color: rgba(255,255,255,.65); pointer-events: none; }

/* Dolby Vision metadata row */
.imf-tl-label-dv   { color: #d4922a; }
.imf-tl-seg-dv        { background: linear-gradient(90deg, #8b5a00, #d4922a) !important; opacity: .85; }
.imf-tl-seg-dv-absent { background: #2a1a00 !important; opacity: .4; cursor: default; }
.imf-tl-seg-dv:hover  { opacity: 1; }

/* Trim Pass row */
.imf-tl-label-trim    { color: #7ec8a0; }
.imf-tl-seg-trim        { background: linear-gradient(90deg, #1a5c3a, #0AA356) !important; opacity: .85; }
.imf-tl-seg-trim-absent { background: #0d2018 !important; opacity: .4; cursor: default; }
.imf-tl-seg-trim:hover  { opacity: 1; }

/* Dolby Vision Cuts row (shot-level from Metafier) */
.imf-tl-label-dv-cuts  { color: #a093e8; }
/* In the dedicated shots row shots are primary content — use higher opacity than overlay */
#imfTLDoviShots .imf-tl-dv-shot-seg { opacity: .82; }
#imfTLDoviShots .imf-tl-dv-shot-seg:hover { opacity: 1; }
/* Gap/cut vertical marker between shots */
.imf-tl-dovi-gap { position: absolute; top: 0; bottom: 0; width: 2px; background: rgba(255,70,70,.80);
  z-index: 4; pointer-events: none; box-shadow: 0 0 4px rgba(255,60,60,.5); }
.imf-tl-info { font-size: 10px; color: #555; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.imf-tl-info strong { color:var(--pfx-text-secondary); font-weight:700; }
.imf-tl-info .imf-tl-hint { color:#666; margin-left:8px; }

/* Reel tabs + table */
.imf-reel-tabs { display: flex; align-items: center; border-bottom: 1px solid #1a1a2e; padding: 0 10px; flex-shrink: 0; background: #0d0d18; gap: 2px; }
.imf-reel-tab { font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: #3a3a58; padding: 4px 8px; cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px; transition: color .12s; }
.imf-reel-tab:hover { color: #666; }
.imf-reel-tab-active { color: var(--pfx-accent); border-bottom-color: var(--pfx-accent); }
.imf-reel-table { overflow: visible; flex: 0 0 auto; min-height: auto; background: #080810; }
.imf-rt { width: 100%; border-collapse: collapse; font-size: 10px; table-layout: fixed; }
.imf-rt thead { position: sticky; top: 0; background: #0d0d18; z-index: 1; }
.imf-rt th { color: #3a3a58; font-weight: 600; text-align: left; padding: 3px 6px; font-size: 9px; white-space: nowrap; border-bottom: 1px solid #1a1a2e; text-transform: uppercase; letter-spacing: .05em; }
.imf-rt td { color: #888; padding: 2px 6px; border-bottom: 1px solid #0f0f1a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; line-height: 1.6; }
.imf-rt-row:hover td { background: #14142a; }
.imf-rt-clickable { cursor: pointer; }
.imf-rt-selected td { background: #0d1520 !important; }
.imf-rt-selected td:first-child { border-left: 2px solid var(--pfx-accent); padding-left: 4px; }
.imf-rt-dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; margin-right: 5px; vertical-align: middle; flex-shrink: 0; }
.imf-rt-uuid { font-family: monospace; color: #444; font-size: 9px; }
.imf-rt-mono { font-family: monospace; color: #666; }
.imf-rt-ok   { color: #0AA356; font-size: 9px; }
.imf-rt-miss { color: #E5484D; font-size: 9px; }
.imf-rt-size   { color: #7a7a96; font-size: 9px; font-family: monospace; }
.imf-rt-frames { color: #8888a8; font-size: 9px; font-family: monospace; }

/* Codec badges in reel table — neutral, no rainbow */
.imf-rt-codec { display: inline-block; font-size: 8px; font-weight: 700; padding: 1px 5px; border-radius: 3px; letter-spacing: .04em; vertical-align: middle; }
.imf-rt-codec-htj2k { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-rt-codec-j2k   { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-rt-codec-rgba  { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-rt-codec-cdci  { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-rt-codec-dv    { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-rt-codec-unk   { background: rgba(255,255,255,.04); color: var(--pfx-text-tertiary); border: 1px solid var(--pfx-border-subtle); }
.imf-rt-codec-pcm   { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-rt-codec-iab   { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }

/* Audio meta label next to codec badge (e.g. 48k·24b) */
.imf-rt-audio-meta { font-size: 8px; color: rgba(255,255,255,.55); font-family: monospace; vertical-align: middle; }

/* Audio resources section header row */
.imf-rt-section-hdr td { background: #08080e; color: rgba(255,255,255,.35); font-size: 8px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .06em; padding: 4px 8px 3px;
  border-top: 1px solid #1a1a2e; border-bottom: 1px solid #101020; }

/* Audio resource rows — subtle blue tint to differentiate from video rows */
.imf-rt-audio-res-row td { background: #060610; }
.imf-rt-audio-res-row:hover td { background: #0e0e22; }
.imf-rt-audio-res-row.imf-rt-selected td { background: #0e0a22 !important; }
.imf-rt-audio-res-row.imf-rt-selected td:first-child { border-left: 2px solid #4a6a8a; padding-left: 4px; }

/* Clickable play cell */
.imf-rt-play-cell { cursor: pointer; font-size: 9px; color: #0AA356; transition: color .15s; }
.imf-rt-play-cell:hover { color: #80df9a; }
.imf-rt-play-cell.imf-rt-play-stop { color: #E5484D; }
.imf-rt-play-cell.imf-rt-play-stop:hover { color: #ff9090; }
.imf-rt-audio-iab-cell { font-size: 9px; color: #3a2a58; }

/* Audio summary row below reel table (kept for legacy uses) */
.imf-rt-audio-row { padding: 4px 8px 3px; font-size: 9px; color: #4a4a68; border-top: 1px solid #1a1a2e; background: #080810; font-family: monospace; }
.imf-rt-audio-row span { color: #666; margin-right: 10px; }
.imf-rt-audio-row span b { color: #5a5a88; font-weight: 600; }

/* Combined reels/assets panel */
.imf-side-section {
  display: flex;
  flex-direction: column;
  min-height: 150px;
  border-top: 1px solid #141428;
  background: #090912;
}
.imf-side-section-hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 10px;
  border-bottom: 1px solid #141428;
  background: #10101a;
  color: #7d7d96;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
}
.imf-side-section-count {
  min-width: 18px;
  padding: 1px 6px;
  border-radius: 999px;
  background: #1a1a28;
  color: #adadc8;
  text-align: center;
  font-size: 9px;
}

/* Asset list */
.imf-asset-list { overflow: visible; flex: 0 0 auto; min-height: auto; padding: 2px 0; background: #080810; }
.imf-asset-empty { padding: 10px 12px; color: #555; font-size: 11px; }
.imf-asset-row { display: flex; align-items: center; gap: 5px; font-size: 10px; padding: 2px 10px; border-bottom: 1px solid #0f0f1a; color: #888; line-height: 1.6; }
.imf-asset-row:hover { background: #14142a; }
.imf-asset-missing { color: #E5484D; }
.imf-asset-dot  { width: 6px; height: 6px; border-radius: 50%; flex-shrink: 0; }
.imf-asset-icon { flex-shrink: 0; font-size: 10px; }
.imf-asset-type { flex: 0 0 38px; font-size: 8px; font-weight: 700; letter-spacing: .04em; }
.imf-asset-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: monospace; font-size: 9px; color: #666; }
.imf-asset-size { color: #3a3a58; flex: 0 0 58px; text-align: right; font-size: 9px; }
.imf-asset-status { flex: 0 0 44px; text-align: right; font-size: 9px; font-weight: 700; }
.imf-asset-row:not(.imf-asset-missing) .imf-asset-status { color: #0AA356; }

/* Asset list enhanced rows */
.imf-asset-row { align-items: flex-start; padding: 3px 10px; }
.imf-asset-info  { display: flex; flex-direction: column; flex: 1; overflow: hidden; min-width: 0; }
.imf-asset-meta  { font-size: 8px; color: #3a3a56; font-family: monospace; margin-top: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Asset type color variants — muted info/neutral */
.imf-asset-type-video { color: var(--pfx-info); }
.imf-asset-type-iab   { color: var(--pfx-info); }
.imf-asset-type-audio { color: var(--pfx-text-secondary); }
.imf-asset-type-cpl   { color: var(--pfx-text-secondary); }
.imf-asset-type-pkl   { color: var(--pfx-text-secondary); }
.imf-asset-type-am    { color: var(--pfx-text-tertiary); }
.imf-asset-type-mxf   { color: var(--pfx-text-tertiary); }

/* Asset status indicators */
.imf-asset-ok      { color: #0AA356; }
.imf-asset-virtual { color: #E0B341; }
.imf-asset-miss    { color: #E5484D; }

/* Track detail panel */
.imf-track-detail { margin: 4px 8px; background: #0e0e1c; border: 1px solid #1e1e32; border-radius: 5px; padding: 5px 10px; font-size: 10px; flex-shrink: 0; }
.imf-detail-row { display: flex; gap: 8px; padding: 1px 0; border-bottom: 1px solid #141428; color: #777; font-size: 9px; line-height: 1.7; }
.imf-detail-row:last-child { border-bottom: none; }
.imf-detail-row b { color: #3a3a58; flex: 0 0 110px; font-weight: 600; font-size: 9px; }
.imf-detail-warn { color: #E0B341 !important; }
.imf-detail-warn b { color: #7a6020 !important; }

/* ── Pro track detail ─────────────────────────────────────────────────────── */

/* Header: pills + UUID */
.imf-pro-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px 6px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.imf-pro-pills { display: flex; gap: 4px; flex-wrap: wrap; flex: 1; min-width: 0; }
.imf-pro-pill {
  font-size: 8px; font-weight: 700; letter-spacing: .05em;
  padding: 2px 7px; border-radius: 4px;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(255,255,255,.06); color: rgba(255,255,255,.7);
  white-space: nowrap;
}
.imf-pro-pill-kind  { color: #c8c4e8; border-color: rgba(255,255,255,.14); }
.imf-pro-pill-codec { color: var(--pfx-text-secondary); border-color: var(--pfx-border-default); background: rgba(255,255,255,.06); }
.imf-pro-pill-res   { color: #61aeef; border-color: rgba(97,175,239,.28); background: rgba(97,175,239,.07); }
.imf-pro-pill-dv    { color: #a0b0ff; border-color: rgba(123,143,255,.4); background: rgba(123,143,255,.12); }
.imf-pro-uuid {
  font-family: monospace; font-size: 8px; color: rgba(255,255,255,.3);
  background: none; border: none; cursor: pointer; padding: 2px 4px;
  border-radius: 3px; white-space: nowrap; flex-shrink: 0;
}
.imf-pro-uuid:hover { color: var(--pfx-accent); background: var(--pfx-accent-soft); }

/* TC hero */
.imf-pro-tc {
  padding: 8px 10px 7px;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.imf-pro-tc-range {
  font-family: monospace; font-size: 14px; font-weight: 600;
  color: #ffffff; letter-spacing: .02em; line-height: 1.2;
}
.imf-pro-tc-sep { color: rgba(255,255,255,.3); margin: 0 6px; font-weight: 300; }
.imf-pro-tc-meta {
  display: flex; align-items: center; gap: 5px; margin-top: 3px;
  font-size: 9px; color: rgba(255,255,255,.45); font-family: monospace;
}
.imf-pro-tc-dot { color: rgba(255,255,255,.2); }
.imf-pro-warn   { font-size: 8px; color: rgba(255,255,255,.4); padding: 1px 5px; border-radius: 3px; background: rgba(255,255,255,.05); }
.imf-pro-warn-red { color: #E0B341; background: rgba(224,179,65,.1); }

/* Section label divider */
.imf-pro-sec-lbl {
  display: block; font-size: 6.5px; font-weight: 800; text-transform: uppercase;
  letter-spacing: .14em; color: rgba(255,255,255,.2); padding: 4px 10px 0;
}

/* Color science inline row */
.imf-pro-color-row {
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
  padding: 5px 10px 6px; border-bottom: 1px solid rgba(255,255,255,.05);
}
.imf-pro-transfer {
  font-size: 9.5px; font-weight: 700; padding: 2px 9px; border-radius: 5px;
}
.imf-td-pq  { color: #f5c06a; background: rgba(245,192,106,.12); border: 1px solid rgba(245,192,106,.28); }
.imf-td-hlg { color: #7d9e66; background: rgba(152,195,121,.10); border: 1px solid rgba(152,195,121,.24); }
.imf-td-sdr { color: #61aeef; background: rgba(97,175,239,.08);  border: 1px solid rgba(97,175,239,.2);  }
.imf-pro-primaries {
  font-size: 9px; color: rgba(255,255,255,.6);
  padding: 2px 8px; border-radius: 5px;
  border: 1px solid rgba(255,255,255,.1); background: rgba(255,255,255,.04);
}

/* Flexible essence grid (auto column count via inline style) */
.imf-pro-row4,
.imf-pro-essence-grid {
  display: grid; grid-template-columns: repeat(4,1fr);
  padding: 6px 10px; gap: 4px 8px;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.imf-pro-cell { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.imf-pro-k {
  font-size: 7px; font-weight: 700; text-transform: uppercase;
  letter-spacing: .1em; color: rgba(255,255,255,.28);
}
.imf-pro-v { font-size: 9.5px; color: rgba(255,255,255,.85); font-weight: 500; }

/* Dolby Vision card */
.imf-pro-dv {
  margin: 0; border-top: 2px solid rgba(100,120,255,.5);
  background: linear-gradient(180deg, rgba(80,100,255,.1) 0%, rgba(60,40,120,.06) 100%);
}
.imf-pro-dv-header {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 7px 10px 6px;
  border-bottom: 1px solid rgba(100,120,255,.15);
}
.imf-pro-dv-logo {
  font-size: 8.5px; font-weight: 900; letter-spacing: .12em;
  color: #fff; background: linear-gradient(135deg,#5060ff,#9060ff);
  padding: 2px 8px; border-radius: 4px;
}
.imf-pro-dv-profile {
  font-size: 11px; font-weight: 700; color: #c8d0ff;
}
.imf-pro-dv-level {
  font-size: 11px; font-weight: 400; color: rgba(180,190,255,.7);
}
.imf-pro-dv-trims {
  margin-left: auto; font-size: 8.5px; font-weight: 600;
  color: #a0b0ff; background: rgba(100,120,255,.15);
  border: 1px solid rgba(100,120,255,.3); padding: 2px 8px; border-radius: 4px;
}
.imf-pro-dv-meta { padding: 6px 10px; display: flex; flex-direction: column; gap: 4px; }
.imf-pro-dv-row  { display: flex; align-items: baseline; gap: 8px; }
.imf-pro-dv-k    { font-size: 7.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: rgba(160,176,255,.5); flex-shrink: 0; min-width: 110px; }
.imf-pro-dv-v    { font-size: 9.5px; color: rgba(255,255,255,.75); }
.imf-pro-dv-nits    { color: #f7c26a; font-weight: 700; }
.imf-pro-dv-nits-lo { color: rgba(200,210,255,.6); }

/* ── Smart track detail (legacy chip classes kept) ──────────────────────── */

/* Chips row — identity at a glance */
.imf-td-chips-row {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  margin-bottom: 6px;
}
.imf-td-chip {
  font-size: 8px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  letter-spacing: .04em;
  white-space: nowrap;
  border: 1px solid rgba(255,255,255,.08);
  background: rgba(255,255,255,.05);
  color: rgba(255,255,255,.45);
}
.imf-td-chip-kind  { color: #a0a0c0; border-color: rgba(255,255,255,.1); }
.imf-td-chip-res   { color: #7c9abf; border-color: rgba(97,175,239,.2); background: rgba(97,175,239,.07); }
.imf-td-chip-codec { color: var(--pfx-text-secondary); border-color: var(--pfx-border-default); background: rgba(255,255,255,.06); }
.imf-td-chip-fps   { color: #6a8a6a; border-color: rgba(152,195,121,.18); background: rgba(152,195,121,.05); }
.imf-td-chip-depth { color: #7a7a9a; border-color: rgba(255,255,255,.09); }
.imf-td-chip-size  { color: #8a96a8; border-color: rgba(255,255,255,.1); }
.imf-td-chip-dv    { color: #7b8fff; border-color: rgba(123,143,255,.3); background: rgba(123,143,255,.1); }

/* UUID — right-aligned, dim, click-to-copy */
.imf-td-uuid {
  font-family: monospace;
  font-size: 8px;
  color: #383850;
  cursor: pointer;
  margin-left: auto;
  white-space: nowrap;
}
.imf-td-uuid:hover { color: var(--pfx-accent); }

/* TC block — the hero row */
.imf-td-tc-block {
  background: rgba(255,255,255,.025);
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 6px;
  padding: 5px 8px;
  margin-bottom: 5px;
}
.imf-td-tc-main {
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.imf-td-tc-label {
  font-size: 7.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: #3e3e5a;
  flex-shrink: 0;
  width: 18px;
}
.imf-td-tc-val {
  font-family: monospace;
  font-size: 11px;
  font-weight: 600;
  color: #c8c4e8;
  letter-spacing: .02em;
}
.imf-td-tc-arrow { color: #444; margin: 0 2px; }
.imf-td-tc-sub {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
  padding-left: 24px;
}
.imf-td-fr  { font-family: monospace; font-size: 8.5px; color: #9a98b8; }
.imf-td-dur { font-family: monospace; font-size: 8.5px; color: #8a88a8; }
.imf-td-dot { color: #5a5870; font-size: 8px; }
.imf-td-extra { font-size: 8px; color: #4a4860; padding: 0 4px; border-radius: 3px; background: rgba(255,255,255,.04); }
.imf-td-extra-warn { color: #a06020; background: rgba(224,179,65,.1); }

/* Color science row */
.imf-td-color-row {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  padding: 3px 0;
}
.imf-td-transfer {
  font-size: 9px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 4px;
}
.imf-td-pq  { color: #e5a84a; background: rgba(229,168,74,.1); border: 1px solid rgba(229,168,74,.22); }
.imf-td-hlg { color: #7d9e66; background: rgba(152,195,121,.1); border: 1px solid rgba(152,195,121,.22); }
.imf-td-sdr { color: #61aeef; background: rgba(97,175,239,.08); border: 1px solid rgba(97,175,239,.18); }
.imf-td-primaries {
  font-size: 8.5px;
  color: #a8a8c8;
  padding: 1px 5px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(255,255,255,.05);
}
.imf-td-scan {
  font-size: 8.5px;
  color: #7878a0;
  margin-left: auto;
}

/* ── Labeled section block ───────────────────────────────────────────────── */
.imf-td-section {
  margin-top: 5px;
  padding: 5px 7px;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,.05);
  background: rgba(255,255,255,.02);
}
.imf-td-section-lbl {
  display: block;
  font-size: 7px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: rgba(255,255,255,.45);
  margin-bottom: 4px;
}

/* Key / value grid — 2 col */
.imf-td-kv-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px 6px;
}
.imf-td-kv {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}
.imf-td-ck {
  font-size: 7.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .07em;
  color: #7a7a9a;
}
.imf-td-cv {
  font-size: 9.5px;
  color: #c8c6e0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Transfer value overrides */
.imf-td-cv.imf-td-pq  { color: #e5a84a; font-weight: 600; }
.imf-td-cv.imf-td-hlg { color: #7d9e66; font-weight: 600; }
.imf-td-cv.imf-td-sdr { color: #61aeef; }

/* ── Dolby Vision card ───────────────────────────────────────────────────── */
.imf-td-dv-card {
  margin-top: 6px;
  border-radius: 7px;
  border: 1px solid rgba(123,143,255,.3);
  background: linear-gradient(135deg, rgba(123,143,255,.1), rgba(80,60,160,.08));
  overflow: hidden;
}
.imf-td-dv-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px 4px;
  border-bottom: 1px solid rgba(123,143,255,.18);
  background: rgba(123,143,255,.07);
}
.imf-td-dv-badge {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .06em;
  color: #fff;
  background: linear-gradient(135deg, #5b6fff, #9b6fff);
  padding: 1px 6px;
  border-radius: 3px;
}
.imf-td-dv-name {
  font-size: 10px;
  font-weight: 700;
  color: #b8c0ff;
  letter-spacing: .02em;
}
.imf-td-dv-pl {
  margin-left: auto;
  font-size: 9px;
  font-weight: 600;
  color: #7b8fff;
  font-family: monospace;
}
.imf-td-dv-grid {
  padding: 5px 8px 6px;
  grid-template-columns: 1fr 1fr;
}
.imf-td-dv-grid .imf-td-ck { color: rgba(160,176,255,.65); }
.imf-td-cv-dv  { color: #a0b0ff !important; }
.imf-td-cv-lum { color: #f7c26a !important; font-weight: 600; }
.imf-td-cv-dim { color: #7888aa !important; }

/* Misc badges */
.imf-badge-dv { display: inline-block; font-size: 9px; font-weight: 700; background: #1a1a3a; color: #7b8fff; border: 1px solid #7b8fff; padding: 1px 5px; border-radius: 3px; margin-right: 4px; vertical-align: middle; }

/* ── Dolby Vision Metafier ───────────────────────────────────────────────── */
.imf-dovi-metafier-panel { border-color: rgba(123,143,255,.2); }
.imf-dovi-shot-list { max-height: 180px; overflow-y: auto; margin: 4px 0; scrollbar-width: thin; scrollbar-color: #2a2a44 transparent; }
.imf-dovi-shot-table { width: 100%; border-collapse: collapse; font-size: 10px; font-family: monospace; }
.imf-dovi-shot-table thead tr { background: #0e0e1e; }
.imf-dovi-shot-table th { padding: 3px 5px; text-align: left; color: #555; font-weight: 600; font-size: 9px; border-bottom: 1px solid #1a1a32; white-space: nowrap; }
.imf-dovi-shot-row { border-bottom: 1px solid #111128; }
.imf-dovi-shot-row:hover { background: rgba(123,143,255,.06); }
.imf-dovi-shot-row td { padding: 2px 5px; color: #aaa; vertical-align: middle; white-space: nowrap; }
.imf-dovi-td-num  { color: #555; width: 24px; }
.imf-dovi-td-range { color: #888; font-size: 9px; }
.imf-dovi-td-dur  { color: #666; font-size: 9px; }
.imf-dovi-td-l    { color: #f7a26a; }
.imf-dovi-td-l1   { color: #f7a26a; }
.imf-dovi-td-canvas { color: #7b8fff; }
.imf-dovi-td-type { white-space: nowrap; }
.imf-dovi-td-trims { white-space: nowrap; min-width: 36px; }
.imf-dovi-td-uuid { max-width: 60px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.imf-dovi-badge { display: inline-block; font-size: 8px; font-weight: 700; padding: 1px 4px; border-radius: 3px; text-transform: uppercase; letter-spacing: .03em; }
.imf-dovi-badge-black   { background: #222; color: #666; border: 1px solid #333; }
.imf-dovi-badge-fade    { background: #2a2000; color: #f7c26a; border: 1px solid rgba(247,194,106,.3); }
.imf-dovi-badge-dissolve { background: rgba(255,255,255,.04); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-dovi-badge-cut     { background: #2a0000; color: #f55; border: 1px solid rgba(255,85,85,.3); }
.imf-dovi-uuid { display: inline-block; font-size: 9px; padding: 0 3px; border-radius: 3px; cursor: default; }
.imf-dovi-uuid-ok      { color: #0AA356; background: rgba(10,163,86,.1); }
.imf-dovi-uuid-bad     { color: #f55;    background: rgba(255,85,85,.12); }
.imf-dovi-uuid-missing { color: #555;    background: transparent; }
.imf-dovi-warnings { margin: 4px 0; display: flex; flex-direction: column; gap: 2px; }
.imf-dovi-warn-row { font-size: 10px; padding: 2px 6px; border-radius: 3px; }
.imf-dovi-warn-error { color: #f55;    background: rgba(255,85,85,.08); border-left: 2px solid #f55; }
.imf-dovi-warn-warn  { color: #f7c26a; background: rgba(247,194,106,.08); border-left: 2px solid #f7c26a; }
.imf-dovi-xml-source { font-size: 9px; font-family: monospace; color: #555; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 140px; cursor: default; }
.imf-dovi-shot-row { cursor: pointer; transition: background .1s; }
.imf-dovi-shot-row:hover { background: rgba(123,143,255,.08); }
.imf-dovi-shot-row-active { background: rgba(123,143,255,.14) !important; }
.imf-dovi-row-warn { font-size: 8px; margin-left: 3px; color: #f7c26a; }
.imf-dovi-row-err  { color: #f55; }
/* Canvas cards */
.imf-dovi-canvas-list { display: flex; flex-direction: column; gap: 5px; flex: 1; }
.imf-dovi-canvas-card {
  background: #08081a; border: 1px solid #1a1a30; border-radius: 5px;
  padding: 6px 8px; font-size: 10px; position: relative; overflow: hidden;
}
.imf-dovi-canvas-card::before {
  content: ''; position: absolute; left: 0; top: 0; bottom: 0;
  width: 3px; border-radius: 3px 0 0 3px;
  background: var(--canvas-accent, #0AA356);
}
.imf-dovi-canvas-card-head {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 4px;
}
.imf-dovi-canvas-card-title { font-weight: 700; color: #c0c8ff; font-size: 10px; }
.imf-dovi-canvas-card-shots { font-size: 9px; color: #555; }
.imf-dovi-canvas-card-lum {
  font-family: monospace; font-size: 11px; font-weight: 700;
  color: #f7c26a; letter-spacing: .01em; margin-bottom: 3px;
}
.imf-dovi-canvas-card-sub {
  display: flex; gap: 10px; font-size: 9px; color: #666; font-family: monospace;
  margin-bottom: 4px;
}
.imf-dovi-canvas-card-uuids { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 3px; }
.imf-dovi-canvas-conflict { border-color: rgba(255,60,60,.4); }
.imf-dovi-canvas-conflict::before { background: #f55; }
.imf-dovi-canvas-ok::before { background: #0AA356; }

.imf-dovi-shot-detail { background: #090913; border: 1px solid #1a1a32; border-radius: 4px; padding: 6px 8px; margin: 4px 0; font-size: 10px; max-height: 220px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: #2a2a44 transparent; }
.imf-dovi-detail-header { font-size: 10px; font-weight: 600; color: #7b8fff; margin-bottom: 6px; padding-bottom: 4px; border-bottom: 1px solid #1a1a32; }
.imf-dovi-det-section { margin-bottom: 6px; }
.imf-dovi-det-label { display: block; font-size: 9px; font-weight: 700; color: #444; text-transform: uppercase; letter-spacing: .05em; margin-bottom: 3px; }
.imf-dovi-det-grid { display: grid; grid-template-columns: 120px 1fr; gap: 1px 8px; }
.imf-dovi-det-grid span:nth-child(odd)  { color: #555; }
.imf-dovi-det-grid span:nth-child(even) { color: #aaa; font-family: monospace; }

/* DoVi Metafier — nav row */
.imf-dovi-nav-row {
  display: flex; align-items: center; gap: 6px;
  margin: 4px 0; padding: 2px 0;
}
.imf-dovi-nav-btn {
  background: #0e0e22; border: 1px solid #1e1e3a; color: #7b8fff;
  font-size: 11px; line-height: 1; padding: 3px 8px; border-radius: 3px;
  cursor: pointer; transition: background .1s, color .1s; user-select: none;
}
.imf-dovi-nav-btn:hover:not(:disabled) { background: rgba(123,143,255,.15); color: #aab4ff; }
.imf-dovi-nav-btn:disabled { opacity: .35; cursor: default; }
.imf-dovi-nav-info {
  flex: 1; text-align: center; font-size: 9px; font-family: monospace; color: #555;
}

/* DoVi Metafier — level presence badges */
.imf-dovi-lvl-badges { display: flex; flex-wrap: wrap; gap: 3px; }
.imf-dovi-lvl-badge {
  font-size: 8px; font-weight: 700; letter-spacing: .04em;
  padding: 1px 5px; border-radius: 3px;
  color: #7b8fff; background: rgba(123,143,255,.1); border: 1px solid rgba(123,143,255,.3);
}

/* DoVi Metafier — timeline shot segments */
.imf-tl-dv-shot-seg {
  position: absolute; height: 100%; top: 0;
  opacity: .55; pointer-events: auto; cursor: pointer;
  transition: opacity .12s, filter .12s, outline-color .12s;
}
.imf-tl-dv-shot-seg:hover { opacity: .92; }
/* UUID-derived color set inline; class just provides fallback + black override */
.imf-tl-seg-dv-shot          { background: rgba(123,143,255,.45); }
.imf-tl-seg-dv-shot-black    { background: rgba( 20, 20, 30,.80); }
.imf-tl-seg-dv-shot-conflict { /* outline + border-top set inline */ }

/* Active DV shot (playhead is inside this shot) */
.imf-tl-dv-shot-active {
  opacity: 1 !important;
  filter: brightness(1.4) saturate(1.3);
  outline: 1px solid rgba(255,200,80,.80) !important;
  outline-offset: -1px;
  z-index: 4;
}

/* Shot meta label — #N · T2 · 840n */
.imf-tl-shot-meta-label {
  position: absolute; left: 3px; top: 2px;
  font-size: 7.5px; line-height: 1; font-family: monospace;
  color: rgba(255,255,255,.95); white-space: nowrap; overflow: hidden;
  pointer-events: none; text-shadow: 0 1px 3px rgba(0,0,0,.95), 0 0 6px rgba(0,0,0,.6);
  letter-spacing: .02em;
}

/* L1 nits bar — right-edge vertical indicator, height ∝ maxNits */
.imf-tl-dv-l1-bar {
  position: absolute; right: 0; bottom: 0; width: 3px;
  border-radius: 2px 2px 0 0;
  pointer-events: none;
  min-height: 2px;
}

/* DV label profile badge e.g. "P5 L8" */
.imf-tl-dv-badge {
  display: block; font-size: 7px; font-weight: 600; letter-spacing: .04em;
  color: rgba(229,160,64,.80); margin-top: 1px; line-height: 1;
}

/* DV CUTS shot count below label */
.imf-tl-dv-shot-count {
  display: block; font-size: 8px; font-weight: 600; color: rgba(153,136,240,.75);
  margin-top: 1px; line-height: 1;
}

/* Per-shot trim overlay on TRIM row */
.imf-tl-shot-trim-overlay {
  position: absolute; top: 0; bottom: 0;
  border-radius: 1px; pointer-events: auto; cursor: pointer;
  opacity: .85;
}
.imf-tl-shot-trim-overlay:hover { opacity: 1; }

/* ── Trim-pass cut marker — vertical line where SDR grade changes ──────────── */
.imf-tl-trim-cut {
  position: absolute;
  top: 0; bottom: 0;
  width: 2px;
  background: rgba(255, 220, 60, 0.85);
  box-shadow: 0 0 4px rgba(255, 220, 60, 0.5);
  pointer-events: auto;
  cursor: default;
  z-index: 4;
}
.imf-tl-trim-cut::before {
  content: '';
  position: absolute;
  top: 0;
  left: -1px;
  width: 4px;
  height: 5px;
  background: rgba(255, 220, 60, 0.95);
  border-radius: 0 0 2px 2px;
}
.imf-tl-trim-cut:hover {
  background: rgba(255, 230, 80, 1);
  box-shadow: 0 0 6px rgba(255, 230, 80, 0.7);
}

/* ── IMF Player — proportional preview, not full-height fill ────────────── */
.imf-player {
  flex-shrink: 0;
  display: flex; flex-direction: column;
  background: #000; border-bottom: 2px solid #1a1a2e;
}

/* Top info bar */
.imf-player-topbar {
  display: flex; align-items: center; gap: 10px;
  padding: 6px 14px; background: #0c0c1a;
  border-bottom: 1px solid #161628; flex-shrink: 0;
}
.imf-player-reel-badge {
  font-size: 9px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
  color: var(--pfx-text-secondary); background: rgba(255,255,255,.06); border: 1px solid var(--pfx-border-default);
  padding: 3px 9px; border-radius: 4px; white-space: nowrap; flex-shrink: 0;
}
.imf-player-meta {
  font-family: monospace; font-size: 10px; color: #444; flex: 1;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.imf-view-switch {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px;
  border-radius: 999px;
  border: 1px solid var(--pfx-border-subtle);
  background: rgba(12,12,20,.86);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.03);
}
.imf-view-switch-btn {
  min-width: 58px;
  padding: 4px 10px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: #7a7894;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .05em;
  cursor: pointer;
  transition: background .12s, color .12s, border-color .12s, opacity .12s;
}
.imf-view-switch-btn:hover:not(:disabled) {
  color: var(--pfx-text-primary);
}
.imf-view-switch-btn:disabled {
  opacity: .42;
  cursor: default;
}
.imf-view-switch-btn-active {
  color: var(--pfx-text-primary);
  background: var(--pfx-accent-soft);
  border-color: var(--pfx-accent-border);
}
.imf-player-close-btn {
  background: none; border: 1px solid #2a2a40; color: #444; font-size: 11px;
  padding: 2px 7px; border-radius: 4px; cursor: pointer; flex-shrink: 0;
  transition: border-color .15s, color .15s;
}
.imf-player-close-btn:hover { border-color: #E5484D; color: #E5484D; }

/* Viewer row: video canvas left, scope panel right */
.imf-viewer-row {
  display: flex; flex-direction: row;
  flex: 0 0 auto;
  /* Viewer height increased about 40% for a larger IMF video preview */
  height: clamp(280px, 53vh, 532px);
  background: #000;
}

/* Canvas — fills all available width in viewer row */
.imf-viewer-stage {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  overflow: hidden;
  background: #080810;
}
.imf-canvas {
  display: block;
  width: 100%;
  height: 100%;
  background: #080810;
}
.imf-proxy-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: none;
  object-fit: contain;
  background: #000;
}
.imf-viewer-stage[data-view-mode="proxy"] .imf-proxy-video { display: block; }
.imf-viewer-stage[data-view-mode="proxy"] .imf-canvas { visibility: hidden; }
.imf-proxy-video::-webkit-media-controls,
.imf-proxy-video::-webkit-media-controls-enclosure,
.imf-proxy-video::-webkit-media-controls-panel {
  display: none !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

/* Scope panel — fixed width, dark bg */
.imf-scope-panel {
  flex: 0 0 220px;
  display: flex; flex-direction: column;
  background: #090912; border-left: 1px solid #1a1a2e;
}
.imf-scope-hdr {
  display: flex; align-items: center; justify-content: space-between;
  padding: 4px 8px; background: #0c0c1a; border-bottom: 1px solid #1a1a2e;
  flex-shrink: 0;
}
.imf-scope-title {
  font-size: 9px; font-weight: 700; text-transform: uppercase;
  letter-spacing: .1em; color: #444;
}
.imf-scope-btns { display: flex; gap: 2px; }
.imf-scope-btn {
  font-size: 9px; font-weight: 600; padding: 2px 6px;
  border: 1px solid #252540; border-radius: 3px;
  background: #12121e; color: #444; cursor: pointer; line-height: 1.4;
  transition: background .1s, color .1s;
}
.imf-scope-btn:hover { background: #1e1e30; color: #888; }
.imf-scope-btn-active {
  background: var(--pfx-accent-soft) !important; color: var(--pfx-accent) !important;
  border-color: var(--pfx-accent-border) !important;
}
.imf-scope-canvas {
  display: block; width: 100%;
  flex: 1; min-height: 0;
  background: #060610;
}

/* Scrubber — full-width track with progress fill */
.imf-scrubber-wrap {
  flex-shrink: 0; padding: 0;
  background: #09090f;
  height: 20px; display: flex; align-items: center;
  border-top: 1px solid #111122;
}
.imf-scrubber {
  width: 100%; height: 4px; appearance: none; background: transparent;
  outline: none; cursor: pointer; margin: 0;
}
.imf-scrubber::-webkit-slider-thumb {
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--pfx-accent); cursor: pointer;
  box-shadow: 0 0 0 2px var(--pfx-accent-soft);
  -webkit-appearance: none;
}
.imf-scrubber::-webkit-slider-runnable-track {
  height: 4px;
  background: linear-gradient(to right, var(--pfx-accent) var(--pct, 0%), #1e1e30 var(--pct, 0%));
  border-radius: 2px;
}

/* Transport controls */
.imf-transport {
  display: flex; align-items: center; gap: 12px;
  padding: 7px 14px; background: #09090f; flex-shrink: 0;
  border-top: 1px solid #111122;
}
.imf-transport-btns { display: flex; gap: 5px; flex-shrink: 0; }
.imf-transport-middle {
  flex: 1;
  display: flex;
  justify-content: flex-end;
  min-width: 0;
}
.imf-transport-sep { width: 1px; height: 14px; background: rgba(255,255,255,.1); flex-shrink: 0; }
.imf-transport-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  border: 1px solid var(--pfx-border-subtle);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(18,18,29,.9), rgba(10,10,16,.94));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.03);
}
.imf-transport-action {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  justify-content: center;
  padding: 3px 9px;
  font-size: 9.5px;
  white-space: nowrap;
}
/* Waveform strip */
.imf-waveform-wrap { display: flex; align-items: stretch; height: 44px;
  border-top: 1px solid rgba(255,255,255,.04); background: #09090f; flex-shrink: 0; overflow: hidden; }
.imf-waveform-label { display: flex; flex-direction: column; justify-content: center;
  gap: 3px; padding: 0 8px; min-width: 56px; flex-shrink: 0;
  border-right: 1px solid rgba(255,255,255,.06); }
.imf-wf-track { font-size: 8px; color: #555; letter-spacing: .05em; text-transform: uppercase; }
.imf-wf-track-sel { display: flex; gap: 3px; }
.imf-wf-chip { font-size: 8px; padding: 1px 5px; border-radius: 3px;
  background: var(--pfx-accent-soft); color: var(--pfx-accent); border: 1px solid var(--pfx-accent-border);
  cursor: pointer; white-space: nowrap; line-height: 1.6; }
.imf-wf-chip:hover { background: rgba(90,167,255,.22); }
.imf-wf-chip-active { background: rgba(90,167,255,.28); color: #c8dfff; border-color: rgba(90,167,255,.65); }
.imf-waveform-canvas { flex: 1; height: 44px; display: block; background: #09090f; }

.imf-tbtn {
  background: #161626; border: 1px solid #252540; color: #777;
  font-size: 11px; padding: 5px 10px; border-radius: 5px; cursor: pointer;
  transition: background .12s, color .12s, border-color .12s; flex-shrink: 0; line-height: 1;
}
.imf-tbtn:hover { background: #252540; color: #ddd; border-color: #3a3a5a; }
.imf-tbtn-play {
  background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); color: var(--pfx-accent);
  font-size: 13px; padding: 5px 14px; min-width: 38px; text-align: center;
}
.imf-tbtn-play:hover { background: var(--pfx-accent); color: #fff; border-color: var(--pfx-accent); }
.imf-tbtn-mode { min-width: 38px; font-weight: 700; letter-spacing: .02em; }
#imfBtnPerf { min-width: 48px; }
.imf-tbtn-mode.imf-tbtn-mode-active { background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); color: var(--pfx-accent); box-shadow: 0 0 0 1px var(--pfx-accent-border) inset; }
.imf-tc {
  font-family: monospace; font-size: 15px; font-weight: 700; color: #d8d8f0;
  letter-spacing: .08em; flex: 0 0 auto;
}
.imf-frame-label {
  font-family: monospace; font-size: 10px; color: #3a3a5a;
  white-space: nowrap; flex: 0 0 auto; text-align: right;
}

/* Timeline section — flex:1 so it fills remaining space below player */
.imf-tl-section { flex: 1; min-height: 0; border-bottom: 1px solid #1a1a2e; overflow: hidden; }
.imf-tl-section-hdr {
  display: flex; align-items: center; justify-content: space-between;
  padding: 5px 14px; background: #0e0e1a; border-bottom: 1px solid #1a1a2e;
}

/* IMF supplemental / CPL compare controls */
.imf-cpl-controls{
  display:inline-flex;
  align-items:center;
  gap:8px;
  margin-right:10px;
  min-width:0;
}
.imf-cpl-label{
  font-size:10px;
  font-weight:700;
  letter-spacing:.08em;
  text-transform:uppercase;
  color:#a9a6c8;
}
.imf-cpl-select{
  min-width:220px;
  max-width:360px;
  height:28px;
  border-radius:8px;
  border:1px solid var(--pfx-border-default);
  background:#11121b;
  color:var(--pfx-text-primary);
  font-size:11px;
  padding:0 10px;
}
.imf-cpl-btn-active{
  background:var(--pfx-accent-soft)!important;
  border-color:var(--pfx-accent-border)!important;
  color:var(--pfx-text-primary)!important;
}
.imf-tl-label-base{
  color:var(--pfx-text-secondary);
}
.imf-tl-track-base{
  opacity:.8;
}
.imf-tl-seg-base{
  filter:saturate(.7);
}

/* ── IMF Validation — professional clean pass ─────────────────────────────── */
#main-imf.imf-shell {
  background: linear-gradient(180deg, #08090f 0%, #05060a 100%);
}

#main-imf .imf-3col {
  grid-template-columns: clamp(360px, 24vw, 420px) minmax(0, 1fr);
  background: #05060a;
}

#main-imf .imf-col {
  background: linear-gradient(180deg, rgba(13,14,22,.98), rgba(7,8,14,.98));
  border-right-color: rgba(255,255,255,.07);
}

#main-imf .imf-col-main {
  background: #030408;
  /* 3-zone QC console that fills the whole workspace — no empty black band:
       row 1  review (viewer + scopes) + transport  → grows
       row 2  timeline                               → natural height, always visible
       row 3  QC details                             → fills the remaining lower space
     Two flexible rows (1fr / 0.55fr) split the slack; the timeline (auto) sits
     between them and can never be pushed out. */
  display: grid;
  /* Two zones: large video review on top, a roomy timeline below. The QC
     details zone is removed; its space goes to the timeline (and viewer).
     The player minimum is min(360px, 100%-150px) so both rows always fit
     within the container — overflow:hidden never clips the timeline away. */
  grid-template-rows: minmax(min(360px, calc(100% - 150px)), 1fr) minmax(150px, 0.34fr);
  overflow: hidden;
}
/* QC details removed — space reclaimed for the timeline */
#main-imf .imf-qc-details { display: none !important; }

/* Upper zone — the player lays out its own rows so the transport stays
   visible and the viewer (1fr) absorbs all remaining height. The reel/meta
   strip is no longer a row here — it's an absolute overlay inside the stage. */
#main-imf .imf-player {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto auto;  /* viewer | scrubber | transport */
  min-height: 0;
  overflow: hidden;
}

