/* ── TC range column ──────────────────────────────────────────────────────── */
.imf-rt-tcrange {
  font-size: 9.5px !important;
  color: #ffffff !important;
  white-space: nowrap;
  letter-spacing: .01em;
  font-weight: 500;
}
.imf-rt-tc-arr {
  margin: 0 4px;
  color: rgba(255,255,255,.4);
  font-weight: 300;
}

/* ── Asset-style list rows ───────────────────────────────────────────────── */
.imf-rt-list { width: 100%; }
.imf-rt-item-cell { padding: 0 !important; border-bottom: 1px solid rgba(255,255,255,.04); }
.imf-rt-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  min-width: 0;
}
.imf-rt-item-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  gap: 1px;
}
.imf-rt-item-name {
  font-size: 9px;
  color: #ffffff;
  font-family: monospace;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.imf-rt-item-tc {
  font-size: 8px;
  color: rgba(255,255,255,.45);
  font-family: monospace;
  white-space: nowrap;
}
.imf-rt-item-num {
  font-size: 8px;
  color: rgba(255,255,255,.25);
  flex-shrink: 0;
  min-width: 14px;
  text-align: right;
}
.imf-rt-row:hover .imf-rt-item-name { color: #ffffff; }
.imf-rt-row:hover .imf-rt-item-tc   { color: rgba(255,255,255,.65); }
.imf-rt-selected .imf-rt-item-name  { color: #ffffff; }

/* Number cell — legacy, kept for non-list rows */
.imf-rt-num-cell { vertical-align: middle; white-space: nowrap; }
.imf-rt-num { font-size: 9px; color: rgba(255,255,255,.75); font-weight: 600; }
.imf-rt-tc-cell { vertical-align: middle; }
.imf-rt-fname {
  font-family: monospace;
  font-size: 8px;
  color: rgba(255,255,255,.55);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
  margin-left: auto;
  text-align: right;
}
.imf-rt-row:hover .imf-rt-fname { color: rgba(255,255,255,.8); }
.imf-rt-row-missing .imf-rt-tcrange { color: #5a3030 !important; }
.imf-rt-row-missing .imf-rt-fname   { color: rgba(224,108,117,.3); }

/* Resolution sub-text in codec cell */
.imf-rt-codec-cell { vertical-align: middle; }
.imf-rt-res {
  font-size: 7.5px;
  color: #333;
  font-family: monospace;
  margin-top: 1px;
  letter-spacing: 0;
  display: inline-block;
  margin-left: 3px;
}

/* ── Asset type badges — neutral, readable ───────────────────────────────── */
.imf-asset-type {
  flex: 0 0 auto;
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: .04em;
  padding: 1px 5px;
  border-radius: 3px;
  white-space: nowrap;
}
.imf-asset-type-video  { background: var(--pfx-info-soft); color: var(--pfx-info); border: 1px solid var(--pfx-info-border); }
.imf-asset-type-iab    { background: var(--pfx-info-soft); color: var(--pfx-info); border: 1px solid var(--pfx-info-border); }
.imf-asset-type-audio  { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-asset-type-cpl    { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-asset-type-pkl    { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); }
.imf-asset-type-am     { background: rgba(255,255,255,.04); color: var(--pfx-text-tertiary);  border: 1px solid var(--pfx-border-subtle);  }
.imf-asset-type-mxf    { background: rgba(255,255,255,.04); color: var(--pfx-text-tertiary);  border: 1px solid var(--pfx-border-subtle);  }

/* Status symbols */
.imf-asset-ok      { color: #0AA356; font-size: 9px; font-weight: 700; flex-shrink: 0; }
.imf-asset-virtual { color: #666;    font-size: 9px; flex-shrink: 0; }
.imf-asset-miss    { color: #E5484D; font-size: 9px; font-weight: 700; flex-shrink: 0; }

#main-imf .imf-proxy-panel {
  margin: 6px 8px;
  padding: 8px 10px;
  gap: 6px;
  height: auto;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.045), rgba(255,255,255,.018)),
    rgba(10,11,18,.86);
}

#main-imf .imf-proxy-panel + .imf-proxy-panel {
  margin-top: 0;
}

#main-imf .imf-proxy-panel-head {
  gap: 6px;
}

#main-imf .imf-proxy-panel-title {
  font-size: 10px;
  letter-spacing: .05em;
}

#main-imf .imf-proxy-panel-state {
  padding: 2px 6px;
  font-size: 9px;
}

#main-imf .imf-proxy-panel-body {
  gap: 6px;
}

#main-imf .imf-proxy-meta {
  gap: 4px;
  padding: 6px 8px;
  border-radius: 8px;
  background: rgba(0,0,0,.18);
}

/* Inline key: value on one row instead of stacked column — saves ~half the height */
#main-imf .imf-proxy-meta-row {
  flex-direction: row;
  align-items: baseline;
  gap: 6px;
  flex-wrap: nowrap;
}

#main-imf .imf-proxy-meta-k {
  flex-shrink: 0;
  font-size: 8px;
  color: rgba(255,255,255,.32);
  min-width: 64px;
}

#main-imf .imf-proxy-meta-v {
  font-size: 10px;
  color: rgba(255,255,255,.82);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

#main-imf .imf-proxy-progress-card {
  gap: 5px;
  padding: 6px 8px;
  border-radius: 8px;
  background: rgba(0,0,0,.18);
}

#main-imf .imf-proxy-progress-label {
  font-size: 8.5px;
}

#main-imf .imf-proxy-progress-pct {
  font-size: 11px;
}

#main-imf .imf-proxy-progress-bar-wrap {
  height: 5px;
}

#main-imf .imf-proxy-panel-note {
  font-size: 9px;
  line-height: 1.35;
  color: rgba(255,255,255,.38);
}

#main-imf .imf-proxy-debug-panel {
  display: none;
}

#main-imf .imf-player {
  margin: 10px 10px 0;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px 16px 10px 10px;
  overflow: hidden;
  background: #020306;
  box-shadow: 0 20px 48px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.04);
}

#main-imf .imf-player-topbar {
  min-height: 34px;
  padding: 6px 12px;
  background: linear-gradient(180deg, rgba(18,20,30,.96), rgba(9,10,16,.96));
  border-bottom-color: rgba(255,255,255,.07);
}

#main-imf .imf-player-reel-badge {
  border-radius: 7px;
  padding: 4px 10px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.07);
}

#main-imf .imf-player-meta {
  color: #697087;
  letter-spacing: .04em;
}

#main-imf .imf-view-switch {
  border-color: rgba(255,255,255,.08);
  background: rgba(0,0,0,.28);
}

#main-imf .imf-view-switch-btn {
  min-width: 54px;
  padding: 4px 11px;
}

#main-imf .imf-view-switch-btn-active {
  background: var(--pfx-accent-soft);
  border-color: var(--pfx-accent-border);
}

/* Trim toggle — amber accent (DV/creative-look) when active */
#main-imf .imf-view-switch-btn-trim.imf-view-switch-btn-active {
  background: rgba(245,197,24,.20);
  border-color: rgba(245,197,24,.5);
  color: #f5d471;
}

#main-imf .imf-viewer-row {
  /* Sits in the player's flexible (1fr) row — fills the space between topbar
     and transport. height:auto overrides the base fixed-height clamp; keeps
     its own internal flex row (viewer-stage | scopes-panel). */
  height: auto;
  min-height: 0;
  min-width: 0;
  background: radial-gradient(circle at 50% 45%, #11131a, #000 72%);
}

#main-imf .imf-viewer-stage {
  background: #000;
  /* Center the scaled preview so the freed margin is even on all sides */
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Reel/meta strip as a compact overlay inside the stage — no layout height,
   so the video preview reclaims the space the old top strip used. Keeps the
   IMF/Proxy switch usable. Dims when the pointer isn't over the viewer. */
#main-imf .imf-viewer-stage .imf-player-topbar {
  position: absolute;
  top: 8px; left: 8px; right: 8px;
  z-index: 20;
  min-height: 0;
  height: 22px;
  padding: 0 8px;
  gap: 8px;
  border-radius: 7px;
  border-bottom: none;
  background: rgba(5, 6, 14, .55);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  box-shadow: 0 1px 6px rgba(0, 0, 0, .35), inset 0 0 0 1px rgba(255, 255, 255, .05);
  opacity: .6;
  transition: opacity .15s ease;
  pointer-events: auto;
}
#main-imf .imf-viewer-stage:hover .imf-player-topbar,
#main-imf .imf-viewer-stage .imf-player-topbar:hover,
#main-imf .imf-viewer-stage .imf-player-topbar:focus-within {
  opacity: 1;
}
/* Compact the chips/text inside the overlay */
#main-imf .imf-viewer-stage .imf-player-reel-badge {
  font-size: 8.5px; padding: 1px 7px; flex-shrink: 0;
}
#main-imf .imf-viewer-stage .imf-player-meta {
  font-size: 9px; line-height: 1;
  color: rgba(220, 225, 255, .82);
}
#main-imf .imf-viewer-stage .imf-view-switch { flex-shrink: 0; }
#main-imf .imf-viewer-stage .imf-player-close-btn { flex-shrink: 0; }

#main-imf .imf-proxy-video,
#main-imf .imf-canvas {
  background: #000;
}

/* Fill ~99% of the (now larger) viewer stage using contain — video is the
   main focus, no crop, no distortion. Burn-in / timecode overlays are painted
   onto the canvas bitmap (which re-sizes to its box via ResizeObserver), so
   they scale with the frame and stay aligned automatically. */
#main-imf .imf-canvas {
  width: 99%;
  height: 99%;
  max-width: 99%;
  max-height: 99%;
  object-fit: contain;
}
#main-imf .imf-proxy-video {
  inset: 0.5%;          /* 0.5% on every side → centered 99% × 99% box */
  width: auto;
  height: auto;
  max-width: 99%;
  max-height: 99%;
  object-fit: contain;
}

#main-imf .imf-scope-panel {
  /* Wider panel = larger scope canvases without sacrificing viewer aspect ratio */
  flex-basis: clamp(360px, 27vw, 430px);
  min-width: 360px;
  max-width: 430px;
  background: #070812;
  border-left-color: rgba(255,255,255,.055);
}

#main-imf .imf-scope-hdr {
  padding: 6px 8px;
  background: rgba(12,13,21,.92);
  border-bottom-color: rgba(255,255,255,.055);
}

#main-imf .imf-scope-title {
  color: #53586f;
}

#main-imf .imf-scope-btn {
  border-radius: 6px;
  background: rgba(255,255,255,.035);
  border-color: rgba(255,255,255,.07);
}

#main-imf .imf-scrubber-wrap {
  height: 16px;
  background: #05060a;
  border-top-color: rgba(255,255,255,.06);
}

#main-imf .imf-scrubber::-webkit-slider-thumb {
  width: 10px;
  height: 10px;
  box-shadow: 0 0 0 3px var(--pfx-accent-soft);
}

#main-imf .imf-waveform-wrap {
  height: 35px;
  background: #05060a;
  border-top-color: rgba(255,255,255,.05);
}

#main-imf .imf-waveform-canvas {
  height: 35px;
}

#main-imf .imf-waveform-label {
  min-width: 48px;
}

/* ── Smart transport additions ───────────────────────────────────────────────── */

/* Reel navigation buttons (⏮ ⏭) — slightly smaller than play */
.imf-tbtn-reel { font-size: 10px; padding: 5px 8px; opacity: .7; }
.imf-tbtn-reel:hover { opacity: 1; }

/* Transport mode group (FULL + AUTO side-by-side, no gap between) */
.imf-transport-modes { display: flex; gap: 4px; flex-shrink: 0; }

/* Timecode group: TC + TL label stacked */
.imf-tc-group {
  display: flex; flex-direction: column; gap: 1px;
  cursor: text; flex-shrink: 0;
  padding: 2px 6px; border-radius: 6px; transition: background .15s;
}
.imf-tc-group:hover { background: rgba(255,255,255,.04); }

/* TL absolute timecode (smaller, below main TC) */
.imf-tc-tl {
  font-family: monospace; font-size: 9px; color: #4a4a7a; letter-spacing: .05em;
  line-height: 1; min-height: 10px;
}

/* Timecode text input (shown when user clicks TC) */
.imf-tc-input {
  font-family: monospace; font-size: 15px; font-weight: 700;
  letter-spacing: .08em; color: #eff0ff;
  background: var(--pfx-accent-soft); border: 1px solid var(--pfx-accent-border);
  border-radius: 4px; outline: none; padding: 1px 4px; width: 108px;
}

/* Reel indicator badge  R5/13 · 44:23 */
.imf-reel-indicator {
  font-family: monospace; font-size: 9.5px; font-weight: 700;
  color: var(--pfx-text-secondary); background: rgba(255,255,255,.06);
  border: 1px solid var(--pfx-border-default); border-radius: 4px;
  padding: 2px 7px; flex-shrink: 0; letter-spacing: .04em;
  min-width: 52px; text-align: center;
}

#main-imf .imf-transport {
  gap: 10px;
  padding: 8px 12px;
  background: linear-gradient(180deg, #090a10, #06070c);
  border-top-color: rgba(255,255,255,.055);
}

#main-imf .imf-tbtn {
  border-radius: 8px;
  padding: 6px 10px;
  background: rgba(255,255,255,.04);
  border-color: rgba(255,255,255,.08);
  color: #7d839a;
}

#main-imf .imf-tbtn:hover {
  color: var(--pfx-text-primary);
  border-color: var(--pfx-accent-border);
