#main-imf .imf-tbtn-play {
  min-width: 42px;
  background: var(--pfx-accent-soft);
  border-color: var(--pfx-accent-border);
  color: var(--pfx-accent);
}

#main-imf .imf-tc {
  color: #eff0ff;
  font-size: 14px;
  letter-spacing: .075em;
}

#main-imf .imf-transport-actions {
  padding: 4px 8px;
  border-radius: 12px;
  background: rgba(0,0,0,.18);
  border-color: rgba(255,255,255,.08);
}

#main-imf .imf-frame-label {
  color: #5c6278;
}

#main-imf .imf-tl-section {
  margin: 6px 10px 5px;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 10px;
  background: rgba(6,7,12,.96);
