/* ═══════════════════════════════════════════════════════════════════════════════
   SMART ANNOTATE — state-aware controls and interruption-free review
   ═══════════════════════════════════════════════════════════════════════════════ */
.sm-anno-modal .sm-anno-metaTrack {
  display: none !important;
}
.sm-anno-modal.has-trackable-selection .sm-anno-metaTrack {
  display: flex !important;
}
.sm-anno-modal .sm-anno-meta {
  justify-content: flex-start !important;
  gap: 6px !important;
}
.sm-anno-modal .sm-anno-done[data-mode="mark"],
.sm-anno-modal .sm-anno-done[data-mode="type"],
.sm-anno-modal .sm-anno-done[data-mode="note"] {
  border-color: rgba(77,159,255,.52) !important;
  background: rgba(77,159,255,.13) !important;
  color: #a8d6ff !important;
}
.sm-anno-modal .sm-anno-done[data-mode="missing"] {
  opacity: .5 !important;
  cursor: not-allowed !important;
}
.sm-anno-modal.is-guiding-type .sm-anno-nt,
.sm-anno-modal.is-guiding-note .sm-anno-note {
  outline: 2px solid rgba(77,159,255,.62) !important;
  outline-offset: 2px !important;
  box-shadow: 0 0 0 5px rgba(77,159,255,.1) !important;
}
.sm-anno-note-presets button.is-active {
  border-color: rgba(77,159,255,.58) !important;
  background: rgba(77,159,255,.14) !important;
  color: #acd8ff !important;
}
.sm-anno-headstack {
  position: relative;
}
.sm-anno-headstack > .sm-anno-draft-banner {
  position: absolute !important;
  z-index: 8 !important;
  top: 58px !important;
  right: 12px !important;
  width: auto !important;
  min-height: 28px !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
  padding: 4px 5px 4px 9px !important;
  border: 1px solid rgba(223,173,85,.38) !important;
  border-radius: 5px !important;
  background: rgba(25,22,17,.96) !important;
  box-shadow: 0 9px 24px rgba(0,0,0,.38) !important;
}
.sm-anno-headstack > .sm-anno-draft-banner .sm-anno-draft-msg {
  color: #d8ba7b !important;
  font: 700 9px/1 system-ui, sans-serif !important;
  white-space: nowrap;
}
.sm-anno-headstack > .sm-anno-draft-banner .btn {
  min-height: 20px !important;
  height: 20px !important;
  padding: 0 7px !important;
  font-size: 8px !important;
}
.sm-anno-modal.sm-anno-refocus {
  animation: smAnnoRefocus .5s ease-out !important;
}
@keyframes smAnnoRefocus {
  0%, 100% { box-shadow: 0 28px 90px rgba(0,0,0,.72), 0 0 0 1px rgba(0,0,0,.8); }
  45% { box-shadow: 0 28px 90px rgba(0,0,0,.72), 0 0 0 2px rgba(77,159,255,.62), 0 0 24px rgba(77,159,255,.16); }
}
@media (max-width: 920px) {
  #main-imf .imf-qc-details { grid-template-columns: 1fr; }
  #main-imf #imfQCMeta { grid-column: auto; }
}

/* Empty-state overlay inside a track when no data exists */
#main-imf .imf-tl-empty-note {
  position: absolute; left: 6px; top: 0; bottom: 0;
  display: flex; align-items: center;
  font-size: 7.5px; font-weight: 500; letter-spacing: .04em;
  color: rgba(255,255,255,.22); pointer-events: none; white-space: nowrap;
}
/* Reel boundary tick for CUTS empty state */
#main-imf .imf-tl-reel-tick-absent {
  position: absolute; top: 0; bottom: 0; width: 1px;
  background: rgba(90,167,255,.15); pointer-events: none;
}

#main-imf .imf-tl-section-hdr {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  background: rgba(10,11,18,.98);
  border-bottom: 1px solid rgba(255,255,255,.055);
  border-radius: 10px 10px 0 0;
}

/* TL label badge */
.imf-tl-hdr-label {
  font-size: 8px; font-weight: 900; letter-spacing: .14em;
  text-transform: uppercase; color: rgba(255,255,255,.3);
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.08);
  padding: 1px 6px; border-radius: 3px; flex-shrink: 0;
}

/* Help button */
.imf-tl-hdr-hint {
  margin-left: auto; flex-shrink: 0;
  width: 16px; height: 16px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 9px; font-weight: 700; color: rgba(255,255,255,.22);
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.08);
  cursor: help;
}
.imf-tl-hdr-hint:hover { color: rgba(255,255,255,.55); background: rgba(255,255,255,.1); }

/* Info chips row */
.imf-tl-info { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; flex: 1; min-width: 0; }
.imf-tl-chip {
  display: inline-flex; align-items: center;
  font-size: 8.5px; font-weight: 600;
  padding: 1px 7px; border-radius: 4px;
  border: 1px solid rgba(255,255,255,.07);
  background: rgba(255,255,255,.04);
  color: rgba(255,255,255,.4);
  white-space: nowrap;
}
.imf-tl-chip-reels  { color: #9090c0; border-color: rgba(150,150,210,.2); }
.imf-tl-chip-frames { color: #7888a8; }
.imf-tl-chip-dur    { color: #c8c4e8; font-weight: 700; }
.imf-tl-chip-fps    { color: #6a9a6a; border-color: rgba(100,180,100,.2); background: rgba(100,180,100,.05); }
.imf-tl-chip-size   { color: #6a8aaa; }
.imf-tl-chip-zoom   { color: #f7c26a; border-color: rgba(247,194,106,.25); background: rgba(247,194,106,.08); font-weight: 700; }

#main-imf .imf-tl-body {
  padding: 9px 12px 10px;
  gap: 6px;
}

#main-imf .imf-tl-ruler {
  height: 20px;
  border-bottom-color: rgba(255,255,255,.07);
  cursor: col-resize;
  /* Align ruler content with track content area.
     .imf-tl-label is flex-basis:44px + row gap:6px = 50px.
     Without this offset the ruler starts 50px to the LEFT of the tracks,
     so the playhead diamond (in ruler) and vertical line (in tracks) appear
     at different screen x-positions even though both have the same 'left' px. */
  margin-left: 50px;
}
#main-imf .imf-tl-track { cursor: col-resize; }

/* ── Smart timeline additions ──────────────────────────────────────────────── */

/* Adaptive ruler tick marks */
#main-imf .imf-tl-tick {
  position: absolute; top: 0; bottom: 0;
  display: flex; align-items: flex-end;
  padding-bottom: 2px; padding-left: 3px;
  font-size: 9px; color: #4a526a;
  border-left: 1px solid rgba(255,255,255,.07);
  pointer-events: none; white-space: nowrap; user-select: none;
  transform: translateX(0); /* prevent sub-pixel drift */
}

/* Reel boundary tick — slightly more prominent */
#main-imf .imf-tl-tick-reel {
  color: rgba(90,167,255,.5);
  border-left-color: rgba(90,167,255,.25);
  font-weight: 700;
}
#main-imf .imf-tl-tick-reel::before {
  content: '';
  position: absolute; top: 0; left: 0;
  width: 1px; height: 100%;
  background: linear-gradient(180deg, rgba(90,167,255,.4), transparent);
  pointer-events: none;
}

/* Hover timecode cursor tooltip */
.imf-tl-hover-cursor {
  position: absolute;
  bottom: 2px; /* sits at the bottom of the tl-body, above the first track */
  pointer-events: none; z-index: 20; user-select: none;
  background: rgba(8, 8, 20, 0.88);
  border: 1px solid var(--pfx-accent-border);
  border-radius: 4px;
  padding: 2px 7px;
  font-family: monospace; font-size: 10px; font-weight: 700;
  color: var(--pfx-text-primary); letter-spacing: .06em;
  white-space: nowrap;
  box-shadow: 0 2px 8px rgba(0,0,0,.5);
  transform: translateY(0);
}

/* Segment double-click cue — slight glow on hover to hint zoom-to-reel */
#main-imf .imf-tl-seg:hover {
  filter: brightness(1.12);
  cursor: pointer;
}
#main-imf .imf-tl-seg:active { filter: brightness(1.25); }

#main-imf .imf-tl-row {
  height: 26px;
}

#main-imf .imf-tl-label {
  flex-basis: 44px;
  color: #666d82;
}

#main-imf .imf-tl-track {
  height: 19px;
  border-radius: 6px;
  background: rgba(255,255,255,.035);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.035);
}

#main-imf .imf-tl-seg {
  border-radius: 5px;
}

#main-imf .imf-tl-seg-audio {
  background: linear-gradient(90deg, rgba(50,78,96,.92), rgba(38,63,80,.92)) !important;
}

/* Dolby Vision metadata track */
#main-imf .imf-tl-label-dv   { color: #e5a040; font-weight: 900; letter-spacing: .12em; }
#main-imf .imf-tl-seg-dv     { background: linear-gradient(90deg, rgba(160,80,0,.9), rgba(220,140,20,.85)) !important; }
#main-imf .imf-tl-seg-dv-absent { background: rgba(80,40,0,.35) !important; }

/* Dolby Vision trim pass track */
#main-imf .imf-tl-label-trim  { color: #5ec898; font-weight: 900; letter-spacing: .12em; }
#main-imf .imf-tl-seg-trim    { background: linear-gradient(90deg, rgba(20,90,55,.92), rgba(70,175,115,.88)) !important; }
#main-imf .imf-tl-seg-trim-absent { background: rgba(10,40,25,.4) !important; }

/* DV cuts/shots track label */
#main-imf .imf-tl-label-dv-cuts { color: #9888f0; font-weight: 900; letter-spacing: .12em; line-height: 1.2; }
#imfTLDoviShots { height: 34px; }
#imfTLDoviShots .imf-tl-track { height: 26px; }

#main-imf .imf-tl-reel-label {
  color: rgba(255,255,255,.72);
}

#main-imf .imf-tl-playhead {
  width: 1px;
  background: linear-gradient(180deg, rgba(255,255,255,.95), rgba(90,167,255,.7));
}

#main-imf .imf-tl-playhead::before {
  width: 9px;
  height: 9px;
}

/* One playhead handle — show the circle only on the ruler, not on every track */
#main-imf .imf-tl-track .imf-tl-playhead::before {
  display: none;
}
/* Ruler playhead extends slightly below the ruler bottom to touch the first track */
#main-imf .imf-tl-ruler .imf-tl-playhead {
  bottom: -2px;
}

/* ═══════════════════════════════════════════════════════════════════════════
   NETFLIX QC STYLE — IMF Validation premium dark theme
   Palette:  bg #0A0A0A · surface #141414 · surface+ #1C1C1C
