#main-imf .imf-view-switch-btn:hover { color: #fff; border-color: rgba(255,255,255,.3); }
#main-imf .imf-view-switch-btn-active {
  background: var(--pfx-accent-soft) !important;
  color: var(--pfx-accent) !important;
  border-color: var(--pfx-accent-border) !important;
}

/* Canvas wrapper */
#main-imf #imfCanvas { background: #000; }

/* ── Scrubber ────────────────────────────────────────────────────────────── */
#main-imf .imf-scrubber-wrap {
  background: #000; height: 14px;
  border-top: 1px solid rgba(255,255,255,.04);
}
#main-imf .imf-scrubber::-webkit-slider-thumb {
  background: var(--pfx-accent); width: 12px; height: 12px;
  box-shadow: 0 0 0 3px var(--pfx-accent-soft);
}
#main-imf .imf-scrubber::-webkit-slider-runnable-track {
  background: linear-gradient(to right, var(--pfx-accent) var(--pct,0%), rgba(255,255,255,.08) var(--pct,0%));
}

/* ── Transport bar ───────────────────────────────────────────────────────── */
#main-imf .imf-transport {
  background: #0D0D0D;
  border-top: 1px solid rgba(255,255,255,.05);
  gap: 10px; padding: 7px 12px;
}
#main-imf .imf-tbtn {
  background: rgba(255,255,255,.05);
  border-color: rgba(255,255,255,.07);
  color: rgba(255,255,255,.5); border-radius: 6px;
}
#main-imf .imf-tbtn:hover { background: rgba(255,255,255,.1); color: #fff; border-color: rgba(255,255,255,.15); }
#main-imf .imf-tbtn-play {
  background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); color: var(--pfx-accent);
  min-width: 40px;
}
#main-imf .imf-tbtn-play:hover { background: var(--pfx-accent); color: #fff; }
#main-imf .imf-tbtn-reel { opacity: .5; color: rgba(255,255,255,.45); }
#main-imf .imf-tbtn-reel:hover { opacity: 1; }

/* Timecode */
#main-imf .imf-tc { color: #FFFFFF; font-size: 15px; letter-spacing: .1em; font-weight: 600; }
#main-imf .imf-tc-tl { color: rgba(255,255,255,.28); font-size: 9px; }
#main-imf .imf-tc-group:hover { background: rgba(255,255,255,.04); }
#main-imf .imf-tc-input { color: #fff; background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); }

/* Reel indicator */
#main-imf .imf-reel-indicator {
  background: rgba(255,255,255,.06); color: rgba(255,255,255,.55);
  border-color: rgba(255,255,255,.1);
}

/* Mode buttons */
#main-imf .imf-tbtn-mode { min-width: 42px; font-size: 9.5px; font-weight: 800; letter-spacing: .06em; }
#main-imf .imf-tbtn-mode.imf-tbtn-mode-active { background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); color: var(--pfx-accent); }
/* HDR/SDR preview toggle — accent when HDR emulation is active */
#main-imf #imfBtnHdrSdr.imf-tbtn-mode-active { background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); color: var(--pfx-accent); }
/* Dimmed state when no direct MXF access — still clickable for companion refresh */
#main-imf .imf-tbtn-mode.imf-tbtn-mode-dim { opacity: .4; cursor: help; }

/* Frame counter bar (Fr N · 24 fps · / total) */
#main-imf .imf-frame-label {
  color: rgba(255,255,255,.35);
  font-size: 9px;
  font-family: monospace;
  letter-spacing: .02em;
}

/* Transport actions pill */
#main-imf .imf-transport-actions {
  background: rgba(255,255,255,.04);
  border-color: rgba(255,255,255,.07);
  border-radius: 6px;
  gap: 6px;
}

/* Export + DV+XML + Clear buttons */
#main-imf .imf-btn-export { background: rgba(255,255,255,.06); border-color: var(--pfx-border-default); color: var(--pfx-text-secondary); }
#main-imf .imf-btn-export:hover { background: rgba(255,255,255,.12); }
#main-imf .imf-btn-dovi-export { background: var(--pfx-warning-soft); border-color: var(--pfx-warning-border); color: #efd28a; }
#main-imf .imf-btn-ghost { color: rgba(255,255,255,.35); border-color: rgba(255,255,255,.08); background: transparent; }
#main-imf .imf-btn-ghost:hover { color: rgba(255,255,255,.7); background: rgba(255,255,255,.07); }

/* Timeline body */
#main-imf .imf-tl-body {
  padding: 5px 10px 6px;
  gap: 3px;
  background: rgba(6,7,12,.96);
}

/* Ruler tighter */
#main-imf .imf-tl-ruler { height: 16px; margin-left: 48px; }

/* Track rows — Resolve-style NLE layout */
#main-imf .imf-tl-row { height: 30px; }
#main-imf .imf-tl-track { height: 22px; border-radius: 4px; }

/* Resolve-style clip block: top highlight band + rounded inset */
#main-imf .imf-tl-seg::after {
  content: '';
  position: absolute;
  inset: 0 0 auto 0;
  height: 6px;
  background: rgba(255,255,255,.13);
  border-radius: 3px 3px 0 0;
  pointer-events: none;
}
#main-imf .imf-tl-seg { border-radius: 4px; border: 1px solid rgba(255,255,255,.10); box-sizing: border-box; }

/* Reel number label — centered, Resolve style */
#main-imf .imf-tl-reel-label {
  font-size: 10px; font-weight: 700; letter-spacing: .04em;
  color: rgba(255,255,255,.82);
  justify-content: flex-start;
  padding-left: 6px;
  gap: 5px;
  overflow: hidden;
}
#main-imf .imf-tl-reel-n   { flex-shrink: 0; }
#main-imf .imf-tl-reel-dur { font-size: 9px; font-weight: 500; color: rgba(255,255,255,.55); white-space: nowrap; overflow: hidden; text-overflow: clip; }
#main-imf .imf-tl-reel-tc  { font-size: 9px; font-weight: 400; color: rgba(255,255,255,.32); white-space: nowrap; overflow: hidden; font-variant-numeric: tabular-nums; }

/* Segments too narrow hide duration/tc labels via overflow hidden on the parent */

/* Active (currently playing) reel glow */
#main-imf .imf-tl-seg-playing {
  filter: brightness(1.35) saturate(1.2) !important;
  outline: 2px solid rgba(255,255,255,.55) !important;
  outline-offset: -2px;
  z-index: 3;
}
#main-imf .imf-tl-seg-playing .imf-tl-reel-dur,
#main-imf .imf-tl-seg-playing .imf-tl-reel-tc { color: rgba(255,255,255,.72); }

/* Playhead TC badge */
.imf-tl-ph-badge {
  position: absolute;
  bottom: calc(100% + 2px);
  left: 50%;
  transform: translateX(-50%);
  background: rgba(10,10,14,.92);
  border: 1px solid var(--pfx-accent-border);
  color: var(--pfx-text-primary);
  font-size: 9px; font-weight: 700; letter-spacing: .04em;
  padding: 2px 5px; border-radius: 3px;
  white-space: nowrap; pointer-events: none;
  font-variant-numeric: tabular-nums;
}

/* ── Timeline row type classes: DV → TRIM → CUTS → VIDEO → IAB ─────────────── */
#main-imf .imf-tl-row-dv   { height: 22px; }
#main-imf .imf-tl-row-trim { height: 18px; }
#main-imf .imf-tl-row-dv  .imf-tl-track { background: rgba(160,80,0,.08); height: 15px; }
#main-imf .imf-tl-row-trim .imf-tl-track { background: rgba(120,90,40,.07); height: 12px; }

/* ── Row filter toggle chips in timeline header ─────────────────────────────── */
#main-imf .imf-tl-row-filters {
  display: flex; gap: 2px; align-items: center; flex-shrink: 0;
}
#main-imf .imf-tl-rf {
  font-size: 7px; font-weight: 800; letter-spacing: .06em;
  padding: 2px 5px; border-radius: 3px; cursor: pointer;
  background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.08);
  color: rgba(255,255,255,.25); text-transform: uppercase;
  transition: background .1s, color .1s, border-color .1s;
}
#main-imf .imf-tl-rf:hover { color: rgba(255,255,255,.6); background: rgba(255,255,255,.08); }
#main-imf .imf-tl-rf-on    { color: rgba(255,255,255,.75) !important; background: rgba(255,255,255,.10) !important; border-color: rgba(255,255,255,.20) !important; }
#main-imf [data-row="dv"].imf-tl-rf-on    { color: #e5a040 !important; border-color: rgba(229,160,64,.35) !important; background: rgba(229,160,64,.08) !important; }
#main-imf [data-row="trim"].imf-tl-rf-on  { color: #c09060 !important; border-color: rgba(190,140,80,.30) !important; background: rgba(190,140,80,.07) !important; }
#main-imf [data-row="cuts"].imf-tl-rf-on  { color: rgba(90,167,255,.75) !important; border-color: rgba(90,167,255,.30) !important; background: rgba(90,167,255,.07) !important; }
#main-imf [data-row="video"].imf-tl-rf-on { color: #6a90ff !important; border-color: rgba(100,140,255,.35) !important; background: rgba(100,140,255,.08) !important; }
#main-imf [data-row="iab"].imf-tl-rf-on   { color: var(--pfx-success) !important; border-color: var(--pfx-success-border) !important; background: var(--pfx-success-soft) !important; }
#main-imf .imf-tl-seg-val-pass { background: linear-gradient(90deg, rgba(70,211,105,.70), rgba(52,168,83,.65)) !important; border-color: rgba(70,211,105,.25) !important; }
#main-imf .imf-tl-seg-val-pass::after { display: none; }
#main-imf .imf-tl-seg-val-warn { background: linear-gradient(90deg, rgba(245,197,24,.75), rgba(220,160,0,.68)) !important; border-color: rgba(245,197,24,.30) !important; }
#main-imf .imf-tl-seg-val-warn::after { display: none; }
#main-imf .imf-tl-seg-val-fail { background: linear-gradient(90deg, rgba(255,90,106,.80), rgba(220,50,70,.72)) !important; border-color: rgba(255,90,106,.35) !important; }
#main-imf .imf-tl-seg-val-fail::after { display: none; }
#main-imf .imf-tl-seg-val-info { background: linear-gradient(90deg, rgba(74,144,217,.65), rgba(52,110,180,.58)) !important; border-color: rgba(74,144,217,.25) !important; }
#main-imf .imf-tl-seg-val-info::after { display: none; }

/* Scrubber bar above transport */
#main-imf .imf-scrubber-wrap {
  height: 14px;
  background: #060709;
  border-top: 1px solid rgba(255,255,255,.05);
  padding-left: 60px;   /* align left with timeline track (section-margin 10 + border 1 + body-pad 10 + label 44 + gap 6 − player-margin 10 − border 1) */
  padding-right: 10px;  /* align right with timeline body right padding */
  box-sizing: border-box;
}
#main-imf .imf-scrubber::-webkit-slider-runnable-track { height: 3px; }
#main-imf .imf-scrubber::-webkit-slider-thumb { width: 8px; height: 8px; }
#main-imf .imf-btn-export {
  background: rgba(255,255,255,.06); color: var(--pfx-text-secondary);
  border-color: var(--pfx-border-default); font-weight: 700;
}
#main-imf .imf-btn-export:hover { background: rgba(255,255,255,.12); }
#main-imf .imf-btn-ghost {
  background: transparent; color: rgba(255,255,255,.35);
  border-color: rgba(255,255,255,.08);
}
#main-imf .imf-btn-ghost:hover { color: rgba(255,255,255,.7); border-color: rgba(255,255,255,.18); }

#main-imf .imf-btn-danger {
  background: var(--pfx-danger-soft);
  border: 1px solid var(--pfx-danger-border);
  color: #ffbac2;
  border-radius: 4px;
  font-weight: 700;
}
#main-imf .imf-btn-danger:hover:not(:disabled) {
  background: rgba(255,90,106,.26);
  border-color: rgba(255,90,106,.55);
  color: #fff;
}

/* ── Scopes Overview panel ───────────────────────────────────────────────── */
#main-imf .imf-scope-panel {
  display: flex; flex-direction: column; overflow: hidden;
}
#main-imf .imf-sov-hdr {
  display: flex; align-items: center; justify-content: space-between;
  padding: 5px 7px; flex-shrink: 0;
  background: rgba(10,11,20,.95);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
#main-imf .imf-scope-title {
  font-size: 8px; font-weight: 800; letter-spacing: .12em;
  color: rgba(255,255,255,.28); text-transform: uppercase;
  flex-shrink: 0;
}
#main-imf .imf-stabs {
  display: flex; gap: 1px; flex-wrap: nowrap;
}
#main-imf .imf-stab {
  font-size: 8px; font-weight: 700; letter-spacing: .04em;
  padding: 3px 5px; border-radius: 3px; cursor: pointer;
  background: transparent; border: none;
  color: rgba(255,255,255,.28);
  transition: color .1s, background .1s;
}
#main-imf .imf-stab:hover { color: rgba(255,255,255,.65); background: rgba(255,255,255,.06); }
#main-imf .imf-stab-active { color: var(--pfx-accent) !important; background: var(--pfx-accent-soft) !important; }

/* Overview grid: vertical stack of compact scope cards */
#main-imf .imf-sov-grid {
  /* Overview = 2×2 grid filling the whole panel body, no wasted space */
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: minmax(140px, 1fr) minmax(140px, 1fr);
  gap: 5px;
  overflow: hidden;
  flex: 1; min-height: 0;
  padding: 5px;
  background: #050508;
}
#main-imf .imf-sov-card {
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 7px; overflow: hidden;
  /* Flex column so the canvas reliably fills the space between header and
     stats (percentage height of a grid track doesn't resolve for <canvas>). */
  min-width: 0; min-height: 0;
  display: flex; flex-direction: column;
}
#main-imf .imf-sov-card-hdr {
  display: flex; align-items: center; gap: 4px; flex-shrink: 0;
  padding: 4px 7px 3px; background: rgba(255,255,255,.05);
  border-bottom: 1px solid rgba(255,255,255,.07);
}
#main-imf .imf-sov-card-name {
  font-size: 10px; font-weight: 700; letter-spacing: .06em;
  color: rgba(255,255,255,.75); flex: 1;
  text-transform: uppercase;
}
#main-imf .imf-sov-warn {
  font-size: 8.5px; font-weight: 800; color: #ffbac2;
  background: var(--pfx-danger-soft);
  border: 1px solid var(--pfx-danger-border);
  border-radius: 3px;
  padding: 1px 5px; letter-spacing: .04em;
}
#main-imf .imf-sov-expand {
  font-size: 12px; background: none; border: none;
  color: rgba(255,255,255,.45); cursor: pointer; padding: 0 3px;
  line-height: 1;
}
#main-imf .imf-sov-expand:hover { color: rgba(255,255,255,.90); }
#main-imf .imf-sov-canvas {
  display: block; width: 100%;
  flex: 1 1 0; min-height: 80px; height: auto;
  background: #0d0d18;
}
#main-imf .imf-sov-canvas-sq { height: auto; }
#main-imf .imf-sov-stats {
  flex-shrink: 0;
  padding: 5px 8px 6px;
  font-size: 11px; color: rgba(255,255,255,.6);
  line-height: 1.6;
}
#main-imf .imf-sov-desc { display: none; }  /* title is self-evident — save the row for values */
#main-imf .imf-sov-row {
  display: flex; gap: 6px; align-items: baseline; flex-wrap: wrap;
}
#main-imf .imf-sov-val {
  color: rgba(255,255,255,.92);
  font-weight: 700;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  letter-spacing: .01em;
}
/* Clip/over-sat warning state on value spans */
#main-imf .imf-sov-val.imf-val-warn { color: #f7a26a; }
#main-imf .imf-sov-val.imf-val-clip { color: #ff5555; }
#main-imf .imf-sov-val.imf-val-ok   { color: #0AA356; }
#main-imf .imf-sov-ch { font-weight: 800; font-size: 9px; margin-right: 1px; }
#main-imf .imf-ch-r { color: rgba(235,65,65,1);   }
#main-imf .imf-ch-g { color: rgba(65,215,90,1);   }
#main-imf .imf-ch-b { color: rgba(65,115,240,1);  }

/* Full scope view */
#main-imf .imf-scope-full {
  display: flex; flex-direction: column; flex: 1; min-height: 0; overflow: hidden;
}
#main-imf .imf-scope-full-hdr {
  display: flex; align-items: center; justify-content: space-between;
  padding: 4px 8px; flex-shrink: 0;
  background: rgba(10,11,20,.95); border-bottom: 1px solid rgba(255,255,255,.06);
}
#main-imf .imf-scope-full-title {
  font-size: 8px; font-weight: 700; letter-spacing: .06em;
  color: var(--pfx-text-secondary); text-transform: uppercase;
}
#main-imf .imf-scope-back {
  font-size: 7.5px; font-weight: 600; background: none; border: none;
  color: rgba(255,255,255,.35); cursor: pointer; padding: 2px 4px;
  border-radius: 3px;
}
#main-imf .imf-scope-back:hover { color: rgba(255,255,255,.75); background: rgba(255,255,255,.06); }
#main-imf .imf-scope-canvas { display: block; width: 100%; flex: 1; min-height: 0; background: #060610; }
#main-imf .imf-scope-full-stats {
  padding: 5px 8px; font-size: 8px; color: rgba(255,255,255,.45);
  border-top: 1px solid rgba(255,255,255,.05); flex-shrink: 0; line-height: 1.6;
  font-variant-numeric: tabular-nums;
}
#main-imf .imf-sfstat { color: rgba(255,255,255,.5); }

/* ── Timeline section ────────────────────────────────────────────────────── */
#main-imf .imf-tl-section { background: #0A0A0A; border-top: 1px solid rgba(255,255,255,.05); }
#main-imf .imf-tl-section-hdr {
  background: #0D0D0D;
  border-bottom: 1px solid rgba(255,255,255,.05);
  padding: 5px 12px;
  font-size: 9px; letter-spacing: .09em; color: rgba(255,255,255,.3);
}
#main-imf .imf-tl-body { background: #0A0A0A; padding: 7px 12px 8px; }
#main-imf .imf-tl-ruler {
  background: transparent; border-bottom-color: rgba(255,255,255,.05);
  margin-left: 50px; cursor: col-resize;
}
#main-imf .imf-tl-track {
  background: rgba(255,255,255,.025);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.03);
  border-radius: 5px; height: 18px;
}
#main-imf .imf-tl-label {
  color: rgba(255,255,255,.3);
  flex-basis: 44px; font-size: 8px; font-weight: 800; letter-spacing: .1em;
  text-transform: uppercase;
}
#main-imf .imf-tl-tick { color: rgba(255,255,255,.22); font-size: 8px; }
#main-imf .imf-tl-tick-reel { color: rgba(90,167,255,.5); border-left-color: rgba(90,167,255,.25); }
#main-imf .imf-tl-playhead {
  background: linear-gradient(180deg, rgba(255,255,255,.95), rgba(90,167,255,.7));
  width: 1px;
}
#main-imf .imf-tl-playhead::before { background: var(--pfx-accent); box-shadow: 0 0 0 2px rgba(255,255,255,.7); }
#main-imf .imf-tl-ruler .imf-tl-playhead { bottom: -2px; }
#main-imf .imf-tl-track .imf-tl-playhead::before { display: none; }
#main-imf .imf-tl-seg:hover { filter: brightness(1.15); }
#main-imf .imf-tl-seg-audio {
  background: linear-gradient(90deg, rgba(70,211,105,.35), rgba(50,180,80,.3)) !important;
}

/* Hover cursor */
#main-imf .imf-tl-hover-cursor {
  background: rgba(0,0,0,.92); border-color: var(--pfx-accent-border); color: var(--pfx-text-primary);
}

/* ══════════════════════════════════════════════════════════════════════
   COMPACT BOTTOM PANEL — target 120-145px total for transport + timeline
   ══════════════════════════════════════════════════════════════════════ */

/* DV info strip — single line, no extra padding */
#main-imf #imfDoviPanel {
  height: 16px !important; line-height: 16px; font-size: 9.5px !important;
  padding: 0 8px !important; white-space: nowrap; overflow: hidden;
  display: none !important; align-items: center; gap: 8px;
}

/* Scrubber — ultra thin */
#main-imf .imf-scrubber-wrap { height: 8px !important; }
#main-imf .imf-scrubber::-webkit-slider-thumb { width: 8px; height: 8px; }
#main-imf .imf-scrubber::-webkit-slider-runnable-track { height: 2px; }

/* Transport bar — tight */
#main-imf .imf-transport { padding: 4px 10px !important; gap: 7px !important; }
#main-imf .imf-tbtn { padding: 3px 7px !important; font-size: 10px !important; border-radius: 5px !important; }
#main-imf .imf-tbtn-play { min-width: 30px !important; }
#main-imf .imf-tc { font-size: 12px !important; letter-spacing: .06em !important; }
#main-imf .imf-tc-tl { font-size: 8px !important; }
#main-imf .imf-transport-actions { padding: 2px 6px !important; gap: 4px !important; border-radius: 6px !important; }
#main-imf .imf-transport-action { padding: 3px 7px !important; font-size: 9px !important; min-width: unset !important; }
#main-imf .imf-tbtn-mode { min-width: 34px !important; font-size: 8.5px !important; padding: 3px 6px !important; }

/* Waveform strip — hide to save space */
#main-imf .imf-waveform-wrap { height: 0 !important; overflow: hidden; }

/* Timeline section — fixed compact height */
#main-imf .imf-tl-section {
  min-height: unset !important;
  flex-shrink: 0;
}

/* Timeline header — single tight line */
#main-imf .imf-tl-section-hdr { padding: 3px 8px !important; }
#main-imf .imf-tl-hdr-label { font-size: 8px; padding: 1px 4px; }
#main-imf .imf-tl-chip { font-size: 7.5px !important; padding: 0 4px !important; height: 14px !important; line-height: 14px !important; }
#main-imf .imf-tl-info { gap: 2px !important; }

/* Row toggle chips — micro size */
#main-imf .imf-tl-row-filters { gap: 1px !important; }
#main-imf .imf-tl-rf {
  font-size: 7px !important; padding: 1px 4px !important;
  height: 14px !important; line-height: 12px !important;
}

/* Timeline body — slightly taller rows + more breathing room (uses freed space).
   min-height keeps the bottom panel a stable, readable band even when the
   DV/TRIM/CUTS rows are hidden (so the area never collapses). */
#main-imf .imf-tl-body { padding: 4px 8px 5px !important; gap: 3px !important; min-height: 52px !important; }

/* Ruler — readable major ticks */
#main-imf .imf-tl-ruler { height: 14px !important; }
#main-imf .imf-tl-tick { font-size: 7.5px !important; }

/* Default row height (fallback for any unlabelled row) */
#main-imf .imf-tl-row          { height: 14px !important; }
#main-imf .imf-tl-track        { height: 11px !important; border-radius: 3px !important; }
#main-imf .imf-tl-label        { font-size: 7.5px !important; flex-basis: 40px !important; letter-spacing: .07em !important; }

/* DV / TRIM / CUTS — visible but quiet when empty */
#main-imf .imf-tl-row-dv       { height: 12px !important; }
#main-imf .imf-tl-row-trim     { height: 12px !important; }
#main-imf .imf-tl-row-cuts     { height: 12px !important; }
#main-imf .imf-tl-row-dv   .imf-tl-track { height: 9px !important; }
#main-imf .imf-tl-row-trim .imf-tl-track { height: 9px !important; }

/* VIDEO / IAB — the rows that matter most, made easier to read */
#main-imf .imf-tl-row-video    { height: 14px !important; }
#main-imf .imf-tl-row-iab      { height: 14px !important; }
#main-imf .imf-tl-row-video .imf-tl-track { height: 12px !important; }
#main-imf .imf-tl-row-iab   .imf-tl-track { height: 12px !important; }

/* ── Roomy timeline: stretch rows to fill the reclaimed (ex-QC) space ───────── */
/* Section fills its grid row; body flexes; rows grow to use the height. */
#main-imf .imf-tl-section { display: flex !important; flex-direction: column; min-height: 0 !important; overflow: hidden; }
#main-imf .imf-tl-body    { flex: 1 1 auto !important; min-height: 52px !important; }
#main-imf .imf-tl-ruler   { flex: 0 0 16px !important; height: 16px !important; }
/* All rows: height driven by flex-grow, track stretches to the row height */
#main-imf .imf-tl-row     { height: auto !important; flex: 1 1 0 !important; min-height: 16px !important; }
#main-imf .imf-tl-track,
#main-imf .imf-tl-row-dv   .imf-tl-track,
#main-imf .imf-tl-row-trim .imf-tl-track,
#main-imf .imf-tl-row-video .imf-tl-track,
#main-imf .imf-tl-row-iab   .imf-tl-track { height: auto !important; align-self: stretch !important; }
/* DV / TRIM / CUTS quieter (thinner); VIDEO / IAB stronger (taller) */
#main-imf .imf-tl-row-dv,
#main-imf .imf-tl-row-trim,
#main-imf .imf-tl-row-cuts { flex: 0.8 1 0 !important; min-height: 16px !important; }
#main-imf .imf-tl-row-video,
#main-imf .imf-tl-row-iab  { flex: 1.7 1 0 !important; min-height: 22px !important; }

/* Suppress the top highlight band on tiny rows */
#main-imf .imf-tl-seg::after { display: none !important; }
#main-imf .imf-tl-seg { border-radius: 2px !important; border-width: 0 !important; }

/* Reel labels — hide on tiny rows, show on VIDEO */
#main-imf .imf-tl-row-dv  .imf-tl-reel-label,
#main-imf .imf-tl-row-trim .imf-tl-reel-label { display: none !important; }
#main-imf .imf-tl-reel-label { font-size: 7.5px !important; }
#main-imf .imf-tl-reel-dur, #main-imf .imf-tl-reel-tc { display: none !important; }

/* Empty-state notes — very subtle */
#main-imf .imf-tl-empty-note {
  font-size: 6.5px !important; color: rgba(255,255,255,.20) !important;
  opacity: 1 !important; letter-spacing: .03em;
}

/* DV shots row compact */
#main-imf #imfTLDoviShots .imf-tl-track { height: 10px !important; }
#imfTLDoviShots { height: 12px !important; }
#main-imf .imf-tl-shot-meta-label { font-size: 6px !important; top: 1px !important; }
#main-imf .imf-tl-dv-l1-bar { width: 2px !important; }

/* Playhead — 1px clean line, no glow on tiny rows */
#main-imf .imf-tl-track .imf-tl-playhead::before { display: none !important; }
#main-imf .imf-tl-playhead::before { width: 6px !important; height: 6px !important; }

/* Ph badge — slightly smaller */
.imf-tl-ph-badge { font-size: 7.5px !important; padding: 1px 4px !important; }

/* ── Proxy Transcode panel ───────────────────────────────────────────────── */
#main-imf .imf-proxy-panel {
  background: linear-gradient(180deg, #141414, #0E0E0E);
}
#main-imf .imf-proxy-panel-title { color: #FFFFFF; letter-spacing: .06em; }
#main-imf .imf-proxy-panel-state[data-state="running"] { background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); color: var(--pfx-accent); }
#main-imf .imf-proxy-panel-state[data-state="done"]    { background: var(--pfx-success-soft); border-color: var(--pfx-success-border); color: var(--pfx-success); }
#main-imf .imf-proxy-panel-state[data-state="error"]   { background: var(--pfx-danger-soft); border-color: var(--pfx-danger-border); color: var(--pfx-danger); animation: none; }
#main-imf .imf-proxy-progress-card {
  background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border);
}
#main-imf .imf-proxy-progress-label { color: rgba(255,255,255,.55); }
#main-imf .imf-proxy-progress-pct { color: #fff; }
#main-imf .imf-proxy-progress-bar { background: linear-gradient(90deg, var(--pfx-accent), rgba(90,167,255,.7)); }
#main-imf .imf-proxy-progress-bar-wrap { background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); }
#main-imf .imf-proxy-meta-k { color: rgba(255,255,255,.28); font-size: 8px; letter-spacing: .09em; }
#main-imf .imf-proxy-meta-v { color: rgba(255,255,255,.82); font-size: 10px; }

/* Result and error cards */
#main-imf .imf-proxy-result-card { background: var(--pfx-success-soft); border-color: var(--pfx-success-border); }
#main-imf .imf-proxy-result-head { color: var(--pfx-success); }
#main-imf .imf-proxy-error-card  { background: var(--pfx-danger-soft); border-color: var(--pfx-danger-border); }
#main-imf .imf-proxy-error-icon  { color: var(--pfx-danger); }
#main-imf .imf-proxy-error-text  { color: rgba(255,186,194,.75); }

/* Capability pills */
#main-imf .imf-proxy-cap-pill { font-size: 9px; font-weight: 700; }
#main-imf .imf-proxy-cap-codec { background: var(--pfx-warning-soft); color: #efd28a; border-color: var(--pfx-warning-border); }
#main-imf .imf-proxy-cap-hdr   { background: var(--pfx-warning-soft); color: var(--pfx-warning); border-color: var(--pfx-warning-border); }
#main-imf .imf-proxy-cap-iab   { background: var(--pfx-success-soft); color: var(--pfx-success); border-color: var(--pfx-success-border); }

/* Stage pipeline */
#main-imf .imf-proxy-stage.active { background: var(--pfx-accent-soft); border-color: var(--pfx-accent-border); color: var(--pfx-accent); }
#main-imf .imf-proxy-stage.done   { color: rgba(70,211,105,.6); }

/* ── Reels + Assets table ─────────────────────────────────────────────────── */
#main-imf .imf-rt { width: 100%; border-collapse: collapse; }
#main-imf .imf-rt thead tr { background: #141414; border-bottom: 1px solid rgba(255,255,255,.08); }
#main-imf .imf-rt thead th { font-size: 8px; font-weight: 800; letter-spacing: .1em; color: rgba(255,255,255,.55); text-transform: uppercase; padding: 5px 7px; }
#main-imf .imf-rt-row:hover { background: rgba(255,255,255,.03); }
#main-imf .imf-rt-selected { background: var(--pfx-accent-soft) !important; }
#main-imf .imf-rt-uuid { color: rgba(255,255,255,.3); }
#main-imf .imf-rt-ok { color: rgba(76,207,122,.8); font-size: 11px; }
#main-imf .imf-rt-miss { color: var(--pfx-danger); font-size: 11px; }
#main-imf .imf-rt-codec.imf-rt-codec-htj2k { background: rgba(255,255,255,.06); color: var(--pfx-text-secondary); border: 1px solid var(--pfx-border-default); border-radius: 3px; padding: 1px 4px; font-size: 8px; font-weight: 800; }
#main-imf .imf-rt-codec.imf-rt-codec-j2k   { background: var(--pfx-info-soft); color: var(--pfx-info); border: 1px solid var(--pfx-info-border); border-radius: 3px; padding: 1px 4px; font-size: 8px; font-weight: 800; }
#main-imf .imf-rt-codec.imf-rt-codec-iab   { background: var(--pfx-success-soft); color: var(--pfx-success); border: 1px solid var(--pfx-success-border); border-radius: 3px; padding: 1px 4px; font-size: 8px; font-weight: 800; }
#main-imf .imf-rt-audio-res-row:hover { background: rgba(255,255,255,.03); }

/* ── Passrate bar (in validation group headers) ──────────────────────────── */
#main-imf .imf-val-passbar { background: rgba(255,255,255,.06); }
#main-imf .imf-val-section.sev-fail .imf-val-passbar-fill { background: var(--pfx-danger); }
#main-imf .imf-val-section.sev-warn .imf-val-passbar-fill { background: var(--pfx-warning); }
#main-imf .imf-val-section.sev-pass .imf-val-passbar-fill { background: var(--pfx-success); }

/* ── Top issues pills ────────────────────────────────────────────────────── */
#main-imf .imf-val-top-issue.sev-fail { background: var(--pfx-danger-soft); color: #ffbac2; border-color: var(--pfx-danger-border); }
#main-imf .imf-val-top-issue.sev-warn { background: var(--pfx-warning-soft); color: #efd28a; border-color: var(--pfx-warning-border); }

/* ── IMF preview / Resolve assist ────────────────────────────────────────── */
#main-imf .imf-resolve-assist-badge--done    { background: var(--pfx-success-soft); color: var(--pfx-success); }
#main-imf .imf-resolve-assist-badge--error   { background: var(--pfx-danger-soft); color: var(--pfx-danger); }
#main-imf .imf-resolve-assist-badge--running { background: var(--pfx-accent-soft); color: var(--pfx-accent); }
#main-imf .imf-resolve-check-val--pass { color: var(--pfx-success); background: var(--pfx-success-soft); }
#main-imf .imf-resolve-check-val--warn { color: var(--pfx-warning); background: var(--pfx-warning-soft); }
#main-imf .imf-resolve-check-val--fail { color: var(--pfx-danger); background: var(--pfx-danger-soft); }

/* ── Scrollbars ──────────────────────────────────────────────────────────── */
#main-imf ::-webkit-scrollbar { width: 3px; height: 3px; }
#main-imf ::-webkit-scrollbar-track { background: transparent; }
#main-imf ::-webkit-scrollbar-thumb { background: rgba(255,255,255,.1); border-radius: 2px; }
#main-imf ::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,.2); }

@media (max-width: 1280px) {
  #main-imf .imf-3col {
    grid-template-columns: 340px minmax(0, 1fr);
  }

  /* Narrower windows: slimmer scopes that fall back to a single column so the
     cards stay readable; viewer keeps filling via flex (no fixed height). */
  #main-imf .imf-scope-panel {
    flex-basis: clamp(300px, 24vw, 360px);
    min-width: 300px;
    max-width: 360px;
  }
  #main-imf .imf-sov-grid {
    grid-template-columns: 1fr;
    grid-template-rows: repeat(4, minmax(100px, 1fr));
    overflow-y: auto;
  }

  #main-imf .imf-canvas {
    width: 98%; height: 98%; max-width: 98%; max-height: 98%;
  }
  #main-imf .imf-proxy-video { inset: 1%; }
}

/* ══════════════════════════════════════════════════════════════════════
   PREP & MARK TAB  (.pm-*)
   ══════════════════════════════════════════════════════════════════════ */

/* Tab theme — amber/gold (Prep & Mark) */
.tab.theme-prepmark .bar { background: #2172E3; }
.tab.theme-prepmark { color: #888; }
.tab.theme-prepmark.active { color: #2172E3; }
.tab.theme-prepmark svg { color: inherit; }

/* Tab theme — amber/gold (Cut Diff, matches Prep & Mark exactly) */
.tab.theme-q1 { color: #888; }
.tab.theme-q1 .bar { background: #2172E3; }
.tab.theme-q1.active { color: #2172E3; }
.tab.theme-q1 svg { color: inherit; }

/* ── Pane shell: grid rows = ctx-bar | qs-row | body | timeline ── */
/* JS sets style.display="grid" when activating this tab (see setMainTab) */
#main-prepmark {
  display: grid;
  grid-template-rows: auto auto auto auto minmax(0, 1fr) 220px;
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #080810;
}

/* ── Context bar ── */
.pm-ctx-bar {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 12px;
  background: #0c0c18;
  border-bottom: 1px solid #191928;
  flex-wrap: wrap;
}
.pm-ctx-title {
  font-size: 11px;
  font-weight: 700;
  color: #c0c0d0;
  letter-spacing: .04em;
  margin-right: 4px;
}
.pm-ctx-chip {
  font-size: 10px;
  color: #8888a8;
  background: transparent;
  border: 1px solid #1c1c2e;
  border-radius: 999px;
  padding: 1px 7px;
  white-space: nowrap;
}
.pm-ctx-chip.pm-ctx-linked { color: #0AA356; border-color: #1a4030; background: #0a1c14; }
.pm-ctx-fps-btn { cursor: pointer; transition: color 0.12s, border-color 0.12s; }
.pm-ctx-fps-btn:hover { color: #b0b0d0; border-color: #3a3a5a; }
.pm-fps-popover {
  position: absolute;
  z-index: 9999;
  background: #14141f;
  border: 1px solid #2e2e48;
  border-radius: 6px;
  padding: 4px 0;
  box-shadow: 0 4px 16px rgba(0,0,0,0.6);
  min-width: 110px;
}
.pm-fps-popover button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 4px 12px;
  font-size: 11px;
  color: #9090b0;
  background: none;
  border: none;
  cursor: pointer;
  white-space: nowrap;
}
.pm-fps-popover button:hover { background: #1e1e30; color: #d0d0e8; }
.pm-fps-popover button.pm-fps-active { color: #7eb8f7; font-weight: 700; }
.pm-ctx-spacer { flex: 1; min-width: 0; }
/* Smart Import button — amber solid pill */
.pm-smart-btn {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 10px; font-weight: 700; letter-spacing: 0.5px;
  padding: 3px 11px; height: 22px; border-radius: 4px; cursor: pointer;
  white-space: nowrap; flex-shrink: 0;
  color: #1a1200; background: #2172E3; border: 1px solid #2172E3;
  box-shadow: 0 0 7px rgba(214,163,58,0.45);
  transition: background 0.15s, box-shadow 0.15s;
}
.pm-smart-btn:hover { background: #e0bd62; box-shadow: 0 0 12px rgba(214,163,58,0.7); }
/* Drag-over state on ctx-bar */
.pm-ctx-bar.pm-smart-dragover {
  outline: 2px dashed #2172E3 !important;
  outline-offset: -2px;
  background: rgba(214,163,58,0.06) !important;
}
.pm-ctx-btn {
  font-size: 10px;
  font-weight: 700;
  background: rgba(255,255,255,.03);
  border: 1px solid #2e2e48;
  color: #8888a8;
  border-radius: 4px;
  padding: 2px 8px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
}
.pm-ctx-btn:hover { background: #1a1a2e; color: #c0c0d8; border-color: #404060; }
.pm-ctx-undo-redo {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #e8a020;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: #fff;
  padding: 0;
  margin: 0 1px;
  transition: background .12s, opacity .12s;
  box-shadow: 0 1px 3px rgba(0,0,0,.35);
}
.pm-ctx-undo-redo:hover:not(:disabled) { background: #f0b030; }
.pm-ctx-undo-redo:disabled { opacity: .35; cursor: default; }
.pm-ctx-reset {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #3a1010;
  border: 1.5px solid #6a2020;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: #d05050;
  padding: 0;
  margin: 0 2px 0 4px;
  transition: background .12s, color .12s, border-color .12s, transform .18s;
  box-shadow: 0 1px 3px rgba(0,0,0,.4);
}
.pm-ctx-reset:hover { background: #5a1818; border-color: #E5484D; color: #ff8080; }
.pm-ctx-reset.is-confirm {
  background: #c0301a;
  border-color: #ff5533;
  color: #fff;
  animation: pm-reset-pulse .5s ease-in-out infinite alternate;
}
@keyframes pm-reset-pulse {
  from { box-shadow: 0 0 0 0 rgba(255,60,30,.5); }
  to   { box-shadow: 0 0 0 5px rgba(255,60,30,0); }
}
.pm-reset-confirm-chip {
  display: flex;
  align-items: center;
  gap: 4px;
  background: #1e0e0e;
  border: 1.5px solid #d04030;
  border-radius: 8px;
  padding: 4px 6px;
  box-shadow: 0 4px 14px rgba(0,0,0,.55);
  font-size: 11px;
  white-space: nowrap;
  animation: pm-chip-in .12s ease-out;
}
@keyframes pm-chip-in {
  from { opacity: 0; transform: translateY(-4px) scale(.96); }
  to   { opacity: 1; transform: translateY(0)   scale(1); }
}
.pm-reset-chip-txt { color: #e08070; font-weight: 500; padding: 0 2px; }
.pm-reset-chip-yes {
  background: #c0301a; border: none; border-radius: 5px;
  color: #fff; font-size: 11px; font-weight: 600;
  padding: 2px 8px; cursor: pointer;
  transition: background .1s;
}
.pm-reset-chip-yes:hover { background: #e03020; }
.pm-reset-chip-no {
  background: none; border: 1px solid #504040; border-radius: 5px;
  color: #a08080; font-size: 11px; padding: 2px 6px; cursor: pointer;
  transition: border-color .1s, color .1s;
}
.pm-reset-chip-no:hover { border-color: #907070; color: #d0b0b0; }
.pm-ctx-btn-export { color: #2172E3 !important; border-color: #5a4a10 !important; background: #1c1808 !important; }
.pm-ctx-btn-diff {
  color: #78dce8 !important;
  border-color: #1f4650 !important;
  background: #08171c !important;
}
.pm-ctx-btn-diff:hover { background: #0d242c !important; color: #a6f0ff !important; }
.pm-ctx-btn-diff-main {
  color: #ffe082 !important;
  border-color: #5a4612 !important;
  background: #1b1408 !important;
}
.pm-ctx-btn-diff-main:hover { background: #2a1d08 !important; color: #ffeab0 !important; }
.pm-smartdiff {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 24px;
  padding: 2px 6px;
  border-radius: 6px;
  border: 1px solid rgba(120, 220, 232, 0.16);
  background: linear-gradient(180deg, rgba(10,21,28,0.96), rgba(10,15,24,0.96));
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.03);
}
.pm-smartdiff-base {
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #78dce8;
}
.pm-smartdiff-chip {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.08);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.04em;
  white-space: nowrap;
}
.pm-smartdiff-chip-new  { color: #74b0c9; background: rgba(114,230,255,0.08); border-color: rgba(114,230,255,0.18); }
.pm-smartdiff-chip-ext  { color: #0AA356; background: rgba(10,163,86,0.08); border-color: rgba(10,163,86,0.18); }
.pm-smartdiff-chip-chg  { color: #E0B341; background: rgba(224,179,65,0.08); border-color: rgba(224,179,65,0.18); }
.pm-smartdiff-chip-trim { color: #a386ba; background: rgba(198,120,221,0.08); border-color: rgba(198,120,221,0.18); }
.pm-smartdiff-chip-risk { color: #ff9f7a; background: rgba(255,159,122,0.08); border-color: rgba(255,159,122,0.18); }
.pm-smartdiff-action,
.pm-smartdiff-clear {
  appearance: none;
  border: 1px solid #31314f;
  background: #141426;
  color: #a8a8c8;
  border-radius: 4px;
  padding: 2px 7px;
  font-size: 9px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}
.pm-smartdiff-action:hover,
.pm-smartdiff-clear:hover { background: #1d1d32; color: #d8d8f0; }
.pm-smartdiff-action.is-active {
  background: rgba(114,230,255,0.12);
  border-color: rgba(114,230,255,0.28);
  color: #b8f4ff;
}
.pm-smartdiff-open {
  color: #ffe082;
  border-color: rgba(214,163,58,0.28);
}
.pm-smartdiff-open:disabled {
  opacity: 0.45;
  cursor: default;
}
.pm-export-menu {
  position: absolute;
  right: 0;
  top: calc(100% + 3px);
  z-index: 9999;
  background: #141420;
  border: 1px solid #2a2a3e;
  border-radius: 5px;
  overflow: hidden;
  min-width: 160px;
  box-shadow: 0 4px 20px rgba(0,0,0,.5);
}
.pm-export-menu button {
  display: flex; align-items: center; gap: 7px;
  width: 100%;
  text-align: left;
  padding: 6px 12px;
  font-size: 10px;
  color: #aaa;
  background: none;
  border: none; border-bottom: 1px solid #1a1a2a;
  cursor: pointer;
  white-space: nowrap;
}
.pm-export-menu button:last-child { border-bottom: none; }
.pm-export-menu button svg { flex-shrink: 0; width: 13px; height: 13px; opacity: 0.65; }
.pm-export-menu button:hover { background: #1e1e32; color: #2172E3; }
.pm-export-menu button:hover svg { opacity: 1; }
.pm-export-menu .pm-fmt-tag {
  margin-left: auto;
  padding: 1px 5px;
  font-size: 9px; font-weight: 600; letter-spacing: .04em;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 3px;
  color: #555;
  flex-shrink: 0;
}
.pm-export-menu button:hover .pm-fmt-tag { background: rgba(214,163,58,.1); border-color: rgba(214,163,58,.2); color: #a88a1a; }
.pm-export-menu .pm-export-section {
  padding: 3px 12px 2px;
  font-size: 9px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: #333; pointer-events: none; user-select: none;
}
.pm-export-wrap { position: relative; }

/* ── Storage KPI (Prep & Mark ctx bar) ── */
.pm-st-kpi {
  display: flex; align-items: center; gap: 5px;
  background: #0d0d1e; border: 1px solid #2a2a4a;
  border-left: 2px solid #b8ff5a;
  border-radius: 4px; padding: 3px 8px;
  font-size: 10px; color: #7a7a9a; flex-shrink: 0;
  box-shadow: 0 0 6px rgba(184,255,90,0.08);
}
.pm-st-lbl { font-weight: 800; color: #b8ff5a; opacity: 0.85; letter-spacing: 0.06em; font-size: 9px; }
.pm-st-pill {
  display: inline-flex; align-items: center; gap: 2px;
  border-radius: 3px; padding: 2px 5px;
  font-size: 11px; font-weight: 800; font-family: monospace;
  white-space: nowrap;
}
.pm-st-exr  { display: none; }
.pm-st-cam  { display: none; }
.pm-st-evts { display: none; }
.pm-st-dur  { display: none; }
.pm-st-pill-k { opacity: 0.7; margin-right: 2px; font-size: 9px; font-weight: 700; }
.pm-st-exr  .pm-st-pill-k { color: #a386ba; }
.pm-st-exr  .pm-st-pill-v { color: #e8d0ff; font-size: 11px; }
.pm-st-cam  .pm-st-pill-k { color: #2172E3; }
.pm-st-cam  .pm-st-pill-v { color: #b8d8ff; font-size: 11px; }
.pm-st-evts .pm-st-pill-k { color: #7d9e66; }
.pm-st-evts .pm-st-pill-v { color: #c8f0a0; font-size: 11px; }
.pm-st-dur  .pm-st-pill-k { color: #E0B341; }
.pm-st-dur  .pm-st-pill-v { color: #fff0b8; font-size: 11px; }

/* ── Smart Storage Popover ── */
.pm-storage-popover {
  position: fixed; z-index: 9999;
  background: #0d0e1a; border: 1px solid #2a2c4a;
  border-radius: 8px; box-shadow: 0 8px 32px rgba(0,0,0,0.7);
  width: 420px; font-size: 11px; color: #c0c4d8;
  overflow: hidden;
}
.pm-sp-header { display: flex; align-items: center; justify-content: space-between;
  padding: 8px 12px; background: #111226; border-bottom: 1px solid #1e2038; }
.pm-sp-title  { font-weight: 700; font-size: 12px; color: #2172E3; letter-spacing: 0.3px; }
.pm-sp-close  { background: none; border: none; color: #666; cursor: pointer; font-size: 13px; padding: 0 2px; }
.pm-sp-close:hover { color: #E5484D; }

/* ── Flat-rate hero ── */
.pm-sp-rate-hero { padding: 10px 12px 8px; background: #0e0f20; border-bottom: 1px solid #1a1c30; }
.pm-sp-rate-label { font-size: 9px; font-weight: 700; color: #6a70a0;
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 6px; }
.pm-sp-rate-row { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.pm-sp-rate-input { width: 60px; background: #141528; border: 1px solid #2a2e58;
  color: #2172E3; font-size: 16px; font-weight: 700; text-align: center;
  border-radius: 5px; padding: 3px 6px; }
.pm-sp-rate-input:focus { outline: none; border-color: #2172E3; }
.pm-sp-rate-unit { font-size: 11px; color: #8898b8; font-weight: 600; }
.pm-sp-rate-apply { background: #2172E3; color: #1a1200; border: none;
  font-size: 10px; font-weight: 700; padding: 4px 10px; border-radius: 4px; cursor: pointer; }
.pm-sp-rate-apply:hover { background: #e0bd62; }
.pm-sp-rate-hint { font-size: 9px; color: #8898b8; flex-basis: 100%; margin-top: 2px; }

/* ── Result blocks ── */
.pm-sp-result-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1px;
  background: #111222; border-bottom: 1px solid #1a1c30; }
.pm-sp-result-block { display: flex; flex-direction: column; align-items: center;
  padding: 10px 8px 8px; background: #0d0e1a; gap: 3px; }
.pm-sp-result-lbl { font-size: 9px; color: #6a70a0; text-transform: uppercase; letter-spacing: 0.4px; font-weight: 700; }
.pm-sp-result-val { font-size: 20px; font-weight: 700; letter-spacing: -0.5px; }
.pm-sp-result-sub { font-size: 8.5px; color: #4a4e70; text-align: center; line-height: 1.3; }
.pm-sp-result-exr .pm-sp-result-val { color: #a386ba; }

.pm-sp-summary { display: flex; gap: 0; border-bottom: 1px solid #1a1c30; }
.pm-sp-sum-row { flex: 1; display: flex; flex-direction: column; align-items: center;
  padding: 6px 4px; gap: 2px; border-right: 1px solid #1a1c30; }
.pm-sp-sum-row:last-child { border-right: none; }
.pm-sp-sum-row span { font-size: 9px; opacity: 0.55; text-transform: uppercase; letter-spacing: 0.4px; }
.pm-sp-sum-row strong { font-size: 11px; color: #e0e4f8; font-weight: 600; }

.pm-sp-section-lbl { padding: 6px 12px 3px; font-size: 9px; font-weight: 700;
  color: #6a70a0; text-transform: uppercase; letter-spacing: 0.5px; background: #0a0b16; }

.pm-sp-num  { color: #8898b8; font-variant-numeric: tabular-nums; text-align: right; }
.pm-sp-sz   { font-weight: 600; color: #d4eaff; text-align: right; }
.pm-sp-total { color: #2172E3 !important; }

.pm-sp-alts { display: grid; grid-template-columns: 1fr 1fr; gap: 1px;
  background: #111222; border-top: 1px solid #1a1c30; border-bottom: 1px solid #1a1c30; }
.pm-sp-alt  { display: flex; justify-content: space-between; align-items: center;
  padding: 5px 10px; background: #0d0e1a; }
.pm-sp-alt span  { font-size: 10px; color: #8898b8; }
.pm-sp-alt strong { font-size: 11px; font-weight: 600; }
.pm-sp-alt-exr strong { color: #a386ba; }
.pm-sp-alt-dpx strong { color: #539c95; }
.pm-sp-alt-pro strong { color: #E0B341; }
.pm-sp-alt-prx strong { color: #7d9e66; }

.pm-sp-footer { padding: 5px 12px; font-size: 9px; color: #4a4e6a;
  text-align: center; background: #0a0b16; border-top: 1px solid #131424; }

/* ── ALE Match ── */
.pm-ctx-btn-ale { color: #539c95 !important; border-color: #1a4a48 !important; background: #06191a !important; }
.pm-ctx-btn-ale:hover { background: #0d2a2a !important; color: #7ae8e2 !important; }

/* ── Marker Match button ── */
.pm-ctx-btn-markerMatch { color: #539c86 !important; border-color: #1a4a38 !important; background: #061a12 !important; }
.pm-ctx-btn-markerMatch:hover { background: #0d2a1e !important; color: #7ae8c8 !important; }

/* ── Clip Match row badges (LINKED / MULTI / ORPHAN / CONFLICT) ── */
.pm-cm-badge {
  display: inline-block;
  margin-left: 4px;
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.06em;
  border-radius: 3px;
  padding: 0 3px;
  vertical-align: middle;
  user-select: none;
  cursor: default;
}
.pm-cm-linked   { color: #4fa877; background: #041a0e; border: 1px solid #1a4a2a; }
.pm-cm-multi    { color: #f0c040; background: #1a1000; border: 1px solid #4a3800; }
.pm-cm-orphan   { color: #e05060; background: #1a0006; border: 1px solid #4a1020; }
.pm-cm-conflict { color: #ff7040; background: #1a0800; border: 1px solid #4a2010; }
.pm-ctx-btn-ico { flex-shrink: 0; }
.pm-ctx-voice-status {
  font-size: 8px; font-weight: 900; letter-spacing: 0.08em;
  color: #d06438; padding: 1px 4px; border-radius: 2px;
  background: rgba(255,80,30,.18); border: 1px solid rgba(255,80,30,.35);
  max-width: 60px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pm-ctx-ai-dot {
  width: 5px; height: 5px; border-radius: 50%; flex-shrink: 0;
  background: #3a3a5a;
  transition: background 0.3s;
}
.pm-ctx-ai-dot.is-claude { background: #a386ba; box-shadow: 0 0 4px #a386ba80; }
.pm-ctx-ai-dot.is-gemini { background: #539c95; box-shadow: 0 0 4px #539c9580; }
.pm-ctx-ai-dot.is-local  { background: #6a6a8a; }
.pm-ctx-ai-badge {
  font-size: 8px; font-weight: 900; line-height: 1;
  padding: 1px 4px; border-radius: 2px;
  background: rgba(255,100,80,.20); border: 1px solid rgba(255,100,80,.40);
  color: #ff8080;
}
.pm-ctx-ai-badge.is-ok {
  background: rgba(10,163,86,.18); border-color: rgba(10,163,86,.35);
  color: #7be3a0;
}
.pm-ctx-btn-voice {
  color: #ffb88a !important;
  border-color: rgba(255,140,80,.35) !important;
  background: linear-gradient(135deg, rgba(255,120,60,.18), rgba(180,60,20,.10)) !important;
  box-shadow: 0 0 8px rgba(255,120,60,.15), inset 0 1px 0 rgba(255,180,120,.08) !important;
  display: inline-flex; align-items: center; gap: 4px;
  letter-spacing: 0.04em;
}
.pm-ctx-btn-voice:hover {
  background: linear-gradient(135deg, rgba(255,140,70,.28), rgba(200,70,20,.18)) !important;
  color: #ffd0aa !important;
  border-color: rgba(255,160,90,.55) !important;
  box-shadow: 0 0 12px rgba(255,120,60,.28), inset 0 1px 0 rgba(255,200,140,.1) !important;
}
.pm-ctx-btn-voice.is-active {
  animation: voice-pulse 1.2s ease-in-out infinite;
  color: #d06438 !important;
  border-color: rgba(255,100,50,.7) !important;
}
@keyframes voice-pulse {
  0%, 100% { box-shadow: 0 0 6px rgba(255,100,50,.3); }
  50%       { box-shadow: 0 0 16px rgba(255,100,50,.7), 0 0 4px rgba(255,100,50,.5); }
}
.pm-ctx-btn-ai {
  color: #b394cc !important;
  border-color: rgba(180,100,255,.35) !important;
  background: linear-gradient(135deg, rgba(160,80,255,.18), rgba(80,20,160,.12)) !important;
  box-shadow: 0 0 8px rgba(160,80,255,.15), inset 0 1px 0 rgba(200,140,255,.08) !important;
  display: inline-flex; align-items: center; gap: 4px;
  letter-spacing: 0.04em;
}
.pm-ctx-btn-ai:hover {
  background: linear-gradient(135deg, rgba(180,100,255,.28), rgba(100,30,200,.18)) !important;
  color: #e8c4ff !important;
  border-color: rgba(200,130,255,.55) !important;
  box-shadow: 0 0 12px rgba(160,80,255,.30), inset 0 1px 0 rgba(220,170,255,.1) !important;
}
.pm-ctx-btn-relink { color: #84d4ff !important; border-color: #1f3d5a !important; background: #061522 !important; }
.pm-ctx-btn-relink:hover { background: #0d2438 !important; color: #aee5ff !important; }
.pm-ctx-btn-relink:disabled { opacity: .45 !important; cursor: wait !important; }
.pm-ctx-btn-proxies { color: #a8e6a0 !important; border-color: #1a3d1a !important; background: #06140a !important; }
.pm-ctx-btn-proxies:hover { background: #0d2414 !important; color: #c8f0c0 !important; }
.pm-ale-dot {
  display: inline-block; width: 4px; height: 4px; border-radius: 50%;
  background: #539c95; margin-left: 3px; vertical-align: middle;
  opacity: 0.85; flex-shrink: 0;
}
.pm-ale-fixed { color: #539c95 !important; }
.pm-ale-toast {
  position: absolute; bottom: 52px; left: 50%;
  transform: translateX(-50%) translateY(6px);
  background: #0a2020; color: #539c95; border: 1px solid #1a5050;
  border-radius: 4px; padding: 5px 14px; font-size: 9px; font-family: monospace;
  white-space: nowrap; pointer-events: none; opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease; z-index: 300;
}
.pm-ale-toast.pm-ale-toast-on { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ── Parse progress toast (global, bottom-right) ── */
.pfx-parse-progress {
  position: fixed; bottom: 20px; right: 20px; z-index: 99999;
  display: flex; align-items: center; gap: 8px;
  background: #12121e; border: 1px solid rgba(255,255,255,0.12); border-radius: 6px;
  padding: 7px 12px; font-size: 11px; color: #9090b0;
  box-shadow: 0 4px 16px rgba(0,0,0,0.55);
  opacity: 0; transform: translateY(6px);
  transition: opacity 0.18s ease, transform 0.18s ease;
  pointer-events: none;
}
.pfx-parse-progress.pfx-pp-on { opacity: 1; transform: translateY(0); }
.pfx-parse-progress[data-state="done"] { color: #0AA356; border-color: rgba(10,163,86,0.3); }
.pfx-pp-spinner {
  display: inline-block; width: 11px; height: 11px; flex-shrink: 0;
  border: 1.5px solid rgba(144,144,176,0.25); border-top-color: #9090b0;
  border-radius: 50%; animation: pfx-spin 0.7s linear infinite;
}
@keyframes pfx-spin { to { transform: rotate(360deg); } }
.pfx-pp-check { font-size: 12px; line-height: 1; flex-shrink: 0; }
.pfx-pp-msg { white-space: nowrap; max-width: 260px; overflow: hidden; text-overflow: ellipsis; }

/* ── Split body — fills the minmax(0,1fr) grid row ── */
.pm-body {
  display: flex;
  overflow: hidden;
  min-height: 0;
  height: 100%;
}

/* Smart NLE divider between Shot List and Program Monitor. */
.pm-panel-divider {
  position: relative;
  flex: 0 0 10px;
  width: 10px;
  min-width: 10px;
  height: 100%;
  cursor: col-resize;
  z-index: 35;
  outline: none;
  background: #090d12;
  border-left: 1px solid #242d36;
  border-right: 1px solid #242d36;
  touch-action: none;
  user-select: none;
  transition: background .15s ease, border-color .15s ease;
}
.pm-panel-divider::before {
  content: '';
  position: absolute;
  inset: 0 3px;
  background: linear-gradient(180deg, transparent 0 42%, #52616f 42% 58%, transparent 58% 100%);
  opacity: .42;
}
.pm-panel-divider-grip {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 4px;
  height: 28px;
  transform: translate(-50%,-50%);
  border-radius: 3px;
  background: repeating-linear-gradient(180deg,#748492 0 2px,transparent 2px 5px);
  opacity: .6;
}
.pm-panel-divider:hover,
.pm-panel-divider:focus-visible,
#main-prepmark.pm-panel-resizing .pm-panel-divider {
  border-color: #3f8fca;
  background: rgba(42,112,163,.2);
}
.pm-panel-divider-value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%,-50%) rotate(-90deg);
  min-width: 66px;
  padding: 3px 6px;
  border: 1px solid #438cc1;
  border-radius: 4px;
  background: #0b1721;
  color: #83c8f2;
  box-shadow: 0 5px 16px rgba(0,0,0,.42);
  font: 800 7px/1 system-ui,sans-serif;
  letter-spacing: .08em;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity .12s ease;
}
.pm-panel-divider:hover .pm-panel-divider-value,
.pm-panel-divider:focus-visible .pm-panel-divider-value,
#main-prepmark.pm-panel-resizing .pm-panel-divider-value { opacity: 1; }
body.pm-panel-resizing-active { cursor: col-resize !important; user-select: none !important; }
#main-prepmark.pm-pro-custom-width .pm-left {
  flex-basis: var(--pm-shot-list-width) !important;
  width: var(--pm-shot-list-width) !important;
}

/* ── LEFT: Event table panel ── */
.pm-left {
  display: flex;
  flex-direction: column;
  flex: 0 0 48%;
  width: 48%;
  min-width: 200px;
  height: 100%;
  border-right: 1px solid #1a1a2e;
  overflow: hidden;
  background: #06060f;
}
.pm-left-hdr {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: #0e0e1a;
  border-bottom: 1px solid #141428;
  flex-shrink: 0;
}
.pm-panel-title {
  font-size: 8px;
  font-weight: 700;
  color: #9090b8;
  letter-spacing: .10em;
  text-transform: uppercase;
  flex: 1;
}
.pm-hdr-btn {
  font-size: 9px;
  background: rgba(255,255,255,.04);
  border: 1px solid #3a3a52;
  color: #9090b0;
  border-radius: 3px;
  padding: 2px 8px;
  cursor: pointer;
}
.pm-hdr-btn:hover { background: #1a1a2a; color: #aaa; }
.pm-hdr-btn--rm-mk {
  border-color: rgba(200,100,240,.28);
  background: rgba(180,80,220,.07);
  color: rgba(190,120,240,.70);
  font-weight: 600;
  letter-spacing: .03em;
  transition: background .12s, border-color .12s, color .12s;
}
.pm-hdr-btn--rm-mk:hover {
  background: rgba(200,80,240,.16) !important;
  border-color: rgba(210,100,255,.50) !important;
  color: #d48cf8 !important;
}
.pm-hdr-btn--rm-mk-confirm {
  background: rgba(220,60,60,.16) !important;
  border-color: rgba(255,80,80,.50) !important;
  color: #ff9999 !important;
  animation: pm-ir-rmall-pulse 0.6s ease infinite alternate;
}
.pm-event-scroll { flex: 1; overflow-y: auto; overflow-x: auto; min-height: 0; position: relative; }
.pm-empty { padding: 24px 16px; color: #5a5a7a; font-size: 9px; text-align: center; line-height: 1.8; }

/* Event table */
.pm-event-table {
  --pm-col-num-w: 20px;
  --pm-col-dot-w: 12px;
  --pm-col-reel-w: 130px;
  --pm-col-tc-w: 84px;
  --pm-col-dur-w: 48px;
  --pm-col-shot-w: 210px;
  --pm-col-rt-w: 18px;
  --pm-col-st-w: 18px;
  --pm-col-rs-w: 18px;
  --pm-col-hdl-w: 40px;
  --pm-col-link-w: 74px;
  --pm-col-mk-add-w: 36px;
  width: max-content;
  min-width: 100%;
  border-collapse: collapse;
  font-size: 10px;
  table-layout: fixed;
}
.pm-event-table th {
  color: #a0a0c0;
  font-weight: 700;
  padding: 5px 5px;
  border-bottom: 1px solid #1e1e34;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: .05em;
  font-size: 9px;
  position: sticky;
  top: 0;
  background: #0c0c18;
  z-index: 1;
}
.pm-event-table td {
  padding: 4px 5px;
  border-bottom: 1px solid #111122;
  color: #bcbcd4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.5;
}
.pm-row { cursor: pointer; transition: background 0.08s; }
.pm-row:nth-child(even) td { background: rgba(255,255,255,0.014); }
.pm-row:hover td { background: #13142a !important; }
.pm-row:hover td:first-child { border-left: 2px solid #5050a0; padding-left: 3px; }
/* Active row: strong amber left bar + background tint — easy to spot even in a long list */
.pm-row-active td { background: #181428 !important; }
.pm-row-active td:first-child {
  border-left: 3px solid #2172E3 !important;
  padding-left: 2px;
  color: #2172E3 !important;
}
.pm-row-active .pm-col-reel { color: #dcdcf0 !important; }
.pm-row-diff-new .pm-col-reel      { box-shadow: inset 2px 0 0 #74b0c9; }
.pm-row-diff-extended .pm-col-reel { box-shadow: inset 2px 0 0 #0AA356; }
.pm-row-diff-changed .pm-col-reel  { box-shadow: inset 2px 0 0 #E0B341; }
.pm-row-diff-trimmed .pm-col-reel  { box-shadow: inset 2px 0 0 #a386ba; }
.pm-row-diff-risk-high td { background: rgba(124, 31, 31, 0.08); }
.pm-row-diff-risk-med td  { background: rgba(124, 92, 31, 0.08); }
.pm-row-diff-risk-high:hover td,
.pm-row-diff-risk-med:hover td { filter: brightness(1.08); }
.pm-vfx-empty-banner-cell {
  text-align: center;
  padding: 7px 12px;
  font-size: 9px;
  color: #E0B341;
  background: #1a1408;
  border-bottom: 1px solid #2a1e08;
  letter-spacing: 0.03em;
}

/* Column resize handle */
.pm-col-resize-handle {
  position: absolute;
  right: 0; top: 0;
  width: 8px; height: 100%;
  cursor: col-resize;
  z-index: 2;
}
.pm-col-resize-handle:hover,
.pm-col-resize-handle:active {
  background: rgba(214, 163, 58, 0.35);
}
body.pm-col-resizing,
body.pm-col-resizing * { cursor: col-resize !important; user-select: none !important; }
.pm-col-resizable { padding-right: 10px !important; }

/* Column widths */
.pm-col-num    { width: var(--pm-col-num-w); color: #8888a8; text-align: right; }
.pm-col-dot    { width: var(--pm-col-dot-w); text-align: center; }
.pm-col-reel   { width: var(--pm-col-reel-w); color: #c0c0e0; }
.pm-col-clip   { display: none; }
.pm-col-tc     { width: var(--pm-col-tc-w); font-family: monospace; color: #a8a8c8; }
.pm-col-dur    { width: var(--pm-col-dur-w); font-family: monospace; color: #9898b8; text-align: right; }
.pm-col-shot   { width: var(--pm-col-shot-w); }
td.pm-col-shot { display: flex; align-items: center; gap: 2px; padding: 0 4px; }
td.pm-col-shot .pm-shot-input { flex: 1; min-width: 0; }
.pm-shot-ai-btn {
  flex: 0 0 auto;
  background: none;
  border: none;
  color: rgba(160,180,255,.35);
  font-size: 9px;
  cursor: pointer;
  padding: 0 2px;
  line-height: 1;
  transition: color .12s;
  vertical-align: middle;
}
.pm-shot-ai-btn:hover { color: #2172E3; }

/* Per-row VFX frame scan button */
.pm-vfx-scan-btn {
  flex: 0 0 auto;
  background: none;
  border: none;
  color: rgba(160,200,255,.45);
  font-size: 10px;
  cursor: pointer;
  padding: 0 3px;
  line-height: 1;
  transition: color .12s, opacity .12s;
  vertical-align: middle;
  opacity: 0.45;
}
tr:hover .pm-vfx-scan-btn { opacity: 1; color: rgba(160,200,255,.75); }
.pm-vfx-scan-btn:hover { color: #7ec8f8 !important; opacity: 1 !important; }
.pm-vfx-scan-btn:disabled { opacity: 0.3; cursor: wait; }

/* Per-row VFX hint badge — click to clear */
.pm-vfx-hint {
  flex: 0 0 auto;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .03em;
  padding: 1px 3px;
  border-radius: 3px;
  cursor: pointer;
  line-height: 1.4;
  vertical-align: middle;
  transition: opacity .12s;
  title: '';
}
.pm-vfx-hint--yes {
  background: rgba(255,80,80,.18);
  border: 1px solid rgba(255,100,100,.40);
  color: #ff9999;
}
.pm-vfx-hint--yes:hover { background: rgba(255,80,80,.28); }


.pm-col-status { display: none; }
.pm-col-rt { width: var(--pm-col-rt-w); text-align: center; padding: 0 1px; }
.pm-col-st { width: var(--pm-col-st-w); text-align: center; padding: 0 1px; }
.pm-col-rs { width: var(--pm-col-rs-w); text-align: center; padding: 0 1px; }
.pm-col-hdl    { width: var(--pm-col-hdl-w); text-align: center; padding: 0 2px; }
.pm-col-link   { width: var(--pm-col-link-w); text-align: left; padding-left: 4px; white-space: nowrap; overflow: hidden; }

/* Flag chips (RT / ST / RS) in pull list */
.pm-flag-chip {
  appearance: none;
  font: inherit;
  display: inline-block; font-size: 7.5px; font-weight: 800; font-family: monospace;
  padding: 1px 4px; border-radius: 3px; letter-spacing: 0.04em;
  border: 1px solid transparent; cursor: pointer; user-select: none;
  color: #3a3a58; background: #111120; border-color: #202038;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
}
.pm-flag-chip:hover  { border-color: #4a4a70; color: #7070b0; }
.pm-flag-chip.pm-flag-rt.active  { background: #2a1e08; color: #E0B341; border-color: #7a5010; }
.pm-flag-chip.pm-flag-st.active  { background: #081618; color: #56b6c2; border-color: #1a5860; }
.pm-flag-chip.pm-flag-rs.active  { background: #160e1c; color: #a386ba; border-color: #6030a0; }
/* Auto-detected flag: small amber/purple dot in top-right corner */
.pm-flag-chip.auto-badge { position: relative; }
.pm-flag-chip.auto-badge::after {
  content: '';
  position: absolute;
  top: -2px; right: -2px;
  width: 4px; height: 4px;
  border-radius: 50%;
  background: #E0B341;
  pointer-events: none;
}
.pm-flag-chip.pm-flag-rs.auto-badge::after { background: #a386ba; }

/* Transition badge in clip cell */
.pm-tr-badge {
  display: inline-block;
  margin-left: 4px;
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.05em;
  padding: 0 2px;
  border-radius: 2px;
  vertical-align: middle;
  color: #56b6c2;
  background: #061418;
  border: 1px solid #1a4a52;
}
.pm-tr-badge.pm-tr-fadein,
.pm-tr-badge.pm-tr-fadeout { color: #7d9e66; background: #061208; border-color: #1a3818; }
.pm-tr-badge.pm-tr-wipe    { color: #E0B341; background: #12100a; border-color: #3a3010; }
.pm-diff-badge {
  display: inline-flex;
  align-items: center;
  margin-left: 5px;
  padding: 1px 6px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.08);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.05em;
  vertical-align: middle;
}
.pm-diff-badge-new {
  color: #74b0c9;
  background: rgba(114,230,255,0.08);
  border-color: rgba(114,230,255,0.18);
}
.pm-diff-badge-extended {
  color: #0AA356;
  background: rgba(10,163,86,0.08);
  border-color: rgba(10,163,86,0.18);
}
.pm-diff-badge-changed {
  color: #E0B341;
  background: rgba(224,179,65,0.08);
  border-color: rgba(224,179,65,0.18);
}
.pm-diff-badge-trimmed {
  color: #a386ba;
  background: rgba(198,120,221,0.08);
  border-color: rgba(198,120,221,0.18);
}
.pm-diff-risk-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 14px;
  height: 14px;
  margin-left: 4px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 900;
  vertical-align: middle;
}
.pm-diff-risk-badge-high {
  color: #ffb4b4;
  background: rgba(224,108,117,0.18);
}
.pm-diff-risk-badge-med {
  color: #ffe3a1;
  background: rgba(224,179,65,0.18);
}

/* Handle input with transition detected */
.pm-hdl-input.pm-hdl-transition { color: #56b6c2; }
.pm-hdl-input.pm-hdl-transition:not(:placeholder-shown) { color: #E0B341; }
.pm-hdl-input.pm-hdl-transition::placeholder { color: #1a5860; font-style: italic; }

/* Handle input with retime active (amber to match RT chip) */
.pm-hdl-input.pm-hdl-retime { color: #a07820; }
.pm-hdl-input.pm-hdl-retime:not(:placeholder-shown) { color: #2172E3; }
.pm-hdl-input.pm-hdl-retime::placeholder { color: #5a4210; font-style: italic; }

/* Handle input */
.pm-hdl-input {
  width: 100%; background: transparent; border: none; color: #7070a0;
  font-size: 8px; font-family: monospace; text-align: center;
  outline: none; -moz-appearance: textfield;
}
.pm-hdl-input::-webkit-outer-spin-button,
.pm-hdl-input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.pm-hdl-input:focus { color: #E0B341; background: #12100a; border-radius: 2px; }
.pm-hdl-input:not(:placeholder-shown) { color: #E0B341; }

/* Camera dot */
.pm-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  vertical-align: middle;
}

/* Shot name input */
.pm-shot-input {
  background: transparent;
  border: none;
  color: #b8b8d0;
  font-family: monospace;
  font-size: 9px;
  width: 100%;
  outline: none;
  padding: 0;
}
.pm-shot-input:focus { background: #1a0e2a; border-radius: 2px; padding: 0 2px; }
.pm-shot-input::placeholder { color: #a8a8c8; font-style: italic; }

/* Status badges */
.pm-status {
  display: inline-block;
  font-size: 8px;
  font-weight: 700;
  padding: 2px 5px;
  border-radius: 3px;
  cursor: pointer;
  user-select: none;
  letter-spacing: .04em;
  white-space: nowrap;
  border: 1px solid transparent;
  transition: filter 0.1s, box-shadow 0.1s;
}
.pm-status:hover {
  filter: brightness(1.35);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.12);
}
.pm-status-none      { color: #5a5a7a; background: #0e0e1a; border-color: #1e1e30; }
.pm-status-pulled    { color: #2172E3; background: #0d1e34; border-color: #1e5080; }
.pm-status-delivered { color: #E0B341; background: #231e10; border-color: #7a6420; }
.pm-status-approved  { color: #0AA356; background: #102218; border-color: #206040; }

/* Link badges (legacy — kept for backward compat) */
.pm-link-badge { display: inline-block; font-size: 8px; font-weight: 700; padding: 1px 4px; border-radius: 999px; border: 1px solid transparent; }
.pm-link-ok   { color: #0AA356; background: #0a1c14; border-color: #1a4030; }
.pm-link-warn { color: #E0B341; background: #1c1808; border-color: #5a4a10; }
.pm-link-none { color: #1e1e2e; }

/* Layer-count pill (new) */
/* VFX flags column in pull list */
.pm-col-vfx { display: none; }

/* ── Next Action column ──────────────────────────────────────────────────── */
.pm-col-nxt { display: none; }
.pm-nxt-badge { display: inline-block; font-size: 7.5px; font-weight: 700; padding: 1px 5px; border-radius: 3px; cursor: default; }
.pm-nxt-color         { background: #1a1040; color: #9090ff; border: 1px solid #4040a0; }
.pm-nxt-build         { background: #0a1a2a; color: #4a9fff; border: 1px solid #1a5090; }
.pm-nxt-rebuild       { background: #1a1808; color: #ffb347; border: 1px solid #804020; }
.pm-nxt-rendering     { background: #0a1a1a; color: #40c0c0; border: 1px solid #1a6060; }
.pm-nxt-failed        { background: #2a0808; color: #ff6060; border: 1px solid #601010; }
.pm-nxt-qc-compare    { background: #0a1a10; color: #40c080; border: 1px solid #1a6040; }
.pm-nxt-qc-hold       { background: #1a1a08; color: #ffff60; border: 1px solid #608010; }
.pm-nxt-export        { background: #0a1a0a; color: #80ff80; border: 1px solid #208020; }

/* ── Smart Run button ────────────────────────────────────────────────────── */
.pm-ctx-btn-smart { background: linear-gradient(135deg, #1a3060, #303070); color: #80aaff; border-color: #3050a0; }
.pm-ctx-btn-smart:hover { background: linear-gradient(135deg, #1e3870, #384080); }

/* ── Smart Preflight modal ───────────────────────────────────────────────── */
.pfx-preflight-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,.65); z-index: 10000; display: flex; align-items: center; justify-content: center; }
.pfx-preflight-modal { background: #1c1c28; border: 1px solid #303050; border-radius: 8px; padding: 20px; min-width: 340px; max-width: 480px; }
.pfx-preflight-title { font-size: 13px; font-weight: 700; color: #c0c8e8; margin-bottom: 14px; }
.pfx-preflight-inner { margin-bottom: 4px; }
.pfx-preflight-row { display: flex; justify-content: space-between; padding: 3px 0; font-size: 11px; border-bottom: 1px solid #242438; }
.pfx-preflight-label { color: #7880a8; }
.pfx-preflight-val { color: #c0c8e8; font-weight: 600; }
.pfx-preflight-val.ok   { color: #0AA356; }
.pfx-preflight-val.warn { color: #E0B341; }
.pfx-preflight-val.err  { color: #f47; }
.pfx-preflight-actions { display: flex; gap: 8px; margin-top: 16px; justify-content: flex-end; }
.pfx-preflight-btn { padding: 6px 14px; border-radius: 4px; font-size: 11px; cursor: pointer; border: 1px solid; }
.pfx-preflight-btn-run { background: #1a3860; color: #80b0ff; border-color: #2a5080; }
.pfx-preflight-btn-run:disabled { opacity: .45; cursor: default; }
.pfx-preflight-btn-sec { background: transparent; color: #7880a8; border-color: #404058; }

/* ── Issue Inbox ─────────────────────────────────────────────────────────── */
.pfx-issue-inbox { background: #161624; border: 1px solid #282840; border-radius: 6px; margin: 4px 8px; overflow: hidden; }
.pfx-issue-inbox-hdr { display: flex; align-items: center; gap: 8px; padding: 6px 12px; cursor: pointer; background: #1c1c2c; user-select: none; }
.pfx-issue-inbox-title { font-size: 11px; font-weight: 700; color: #8888c0; flex: 1; }
.pfx-issue-inbox-toggle { font-size: 9px; color: #5860a0; }
.pfx-issue-group-hdr { display: flex; align-items: center; gap: 6px; padding: 4px 12px; font-size: 10px; font-weight: 700; color: #6870a0; }
.pfx-issue-group-count { font-size: 9px; background: #202030; color: #4850a0; border-radius: 99px; padding: 1px 6px; }
.pfx-issue-row { display: flex; align-items: center; gap: 8px; padding: 3px 16px; font-size: 10px; color: #9098b8; }
.pfx-issue-row-shot { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pfx-issue-fix-btn { font-size: 8.5px; padding: 1px 6px; border-radius: 3px; cursor: pointer; border: 1px solid; background: transparent; }
.pfx-fix-relink  { color: #4a8af8; border-color: #2a5080; }
.pfx-fix-confirm { color: #E0B341; border-color: #7a5010; }
.pfx-fix-build   { color: #4a9fff; border-color: #1a5090; }
.pfx-fix-retry   { color: #ff6060; border-color: #601010; }
.pfx-fix-qc      { color: #40c080; border-color: #1a6040; }
.pfx-fix-export  { color: #80ff80; border-color: #208020; }
.pfx-fix-color   { color: #9090ff; border-color: #4040a0; }
.pm-row-vfx-flags { display: inline-flex; gap: 2px; }
.pm-rvf { font-size: 6.5px; font-weight: 700; padding: 1px 3px; border-radius: 2px; letter-spacing: 0.03em; font-family: monospace; }
.pm-rvf-rt { background: #2a1e08; color: #E0B341; border: 1px solid #7a5010; }
.pm-rvf-st { background: #081618; color: #56b6c2; border: 1px solid #1a5860; }
.pm-rvf-rs { background: #160e1c; color: #a386ba; border: 1px solid #6030a0; }

.pm-link-pill { display: inline-block; font-size: 7.5px; font-weight: 800; padding: 1px 5px; border-radius: 999px; font-family: monospace; letter-spacing: 0.04em; }
.pm-link-pill-ok   { color: #0d1e14; background: #0AA356; }
.pm-link-pill-warn { color: #E0B341; background: transparent; border: 1px solid #5a4a10; }


/* Row that already has VFX layers */
.pm-row-has-mk td:first-child { border-left: 2px solid #0AA356; }
.pm-row-has-mk { background: #090d0c; }
.pm-row-has-mk:hover { background: #0d1410 !important; }

/* ── VFX Rename mode ── */
.pm-mode-vfxrename .pm-col-shot { background: rgba(198,120,221,0.04); }
.pm-mode-vfxrename .pm-shot-input { color: #b8b8d0 !important; border-bottom: 1px solid #6030a0; }
.pm-mode-vfxrename .pm-shot-input:focus { background: #130e1a; border-color: #a386ba; outline: none; }
.pm-mode-vfxrename .pm-left-hdr::after {
  content: 'VFX RENAME';
  font-size: 7px; font-weight: 700; letter-spacing: 0.1em;
  color: #a386ba; background: rgba(198,120,221,0.12); border: 1px solid #6030a0;
  padding: 1px 5px; border-radius: 2px; margin-left: auto;
}
/* Hide un-named rows in VFX Rename mode */
.pm-mode-vfxrename .pm-row:not(.pm-row-named) { display: none; }
/* Filter notice */
.pm-vfxrename-notice {
  display: none;
  font-size: 8px; font-family: monospace; letter-spacing: 0.05em;
  color: #6030a0; padding: 3px 10px; background: rgba(198,120,221,0.06);
  border-bottom: 1px solid #2a1840;
}
.pm-mode-flatten   .pm-vfxrename-notice { display: block; color: #2172E3; background: rgba(97,175,239,0.05); border-bottom-color: #102030; }
.pm-mode-conform   .pm-vfxrename-notice { display: block; color: #5a8040; background: rgba(90,180,60,0.06); border-bottom-color: #1a3010; }
.pm-mode-vfxrename .pm-vfxrename-notice { display: block; }
.pm-mode-vfxmarker .pm-vfxrename-notice { display: block; color: #2a6040; }

/* ── VFX Marker mode ── */
.pm-mode-vfxmarker .pm-row { cursor: crosshair; }
.pm-mode-vfxmarker .pm-row:hover td { background: rgba(10,163,86,0.06) !important; }
.pm-mode-vfxmarker .pm-row:hover td:first-child { border-left: 2px solid #0AA356; }
.pm-mode-vfxmarker .pm-col-shot { background: rgba(10,163,86,0.04); }
.pm-mode-vfxmarker .pm-shot-input { color: #0AA356 !important; border-bottom: 1px solid #1a6040; }
.pm-mode-vfxmarker .pm-shot-input:focus { background: #071410; border-color: #0AA356; outline: none; }
/* Non-linked clips hidden in VFX Marker mode — pull list shows only marked clips */
.pm-mode-vfxmarker .pm-row:not(.pm-row-has-mk) { display: none; }
.pm-mode-vfxmarker .pm-left-hdr::after {
  content: 'VFX MARKER';
  font-size: 7px; font-weight: 700; letter-spacing: 0.1em;
  color: #0AA356; background: rgba(10,163,86,0.12); border: 1px solid #1a6040;
  padding: 1px 5px; border-radius: 2px; margin-left: auto;
}

/* Quick remove button in table */
.pm-mk-rm-btn { font-size: 10px; padding: 0 5px; border: 1px solid #7a3030; background: rgba(180,50,50,.12); color: #d06060; border-radius: 3px; cursor: pointer; margin-right: 2px; font-weight: 700; line-height: 1.5; }
.pm-mk-rm-btn:hover { color: #ff7a7a; border-color: #cc3333; background: #2a0808; }

/* ── RIGHT: Video player + inspector ── */
.pm-right {
  display: flex;
  flex-direction: column;
  flex: 1 1 0;
  min-width: 180px;
  height: 100%;
  overflow: hidden;
  background: #050510;
}
.pm-player-wrap {
  flex: 1 1 0;
  min-height: 0;
  position: relative;
  background: #000;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.pm-vid-qt-tc {
  position: absolute;
  top: 8px;
  left: 10px;
  z-index: 12;
  font-family: "SF Mono", ui-monospace, monospace;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: #f0f0e0;
  background: rgba(0,0,0,0.55);
  padding: 2px 7px;
  border-radius: 3px;
  pointer-events: none;
  user-select: none;
}
.pm-player-wrap video {
  max-width: 100%;
  max-height: 100%;
  display: block;
  transform: translateZ(0);
  backface-visibility: hidden;
  will-change: transform;
}
.pm-player-wrap.pm-preview-suppressed video {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}
.pm-video-hint {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: #7070a0;
  font-size: 10px;
  background: #070718;
  border: 1px dashed #28284a;
  pointer-events: none;
}
.pm-video-hint span {
  color: #8080b8;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.05em;
}
.pm-video-hint svg { opacity: 0.5; }
.pm-video-hint .pm-hdr-btn { pointer-events: all; }
.pm-video-hint.pm-proxying svg,
.pm-video-hint.pm-proxying > span:first-of-type { display: none; }
.pm-video-status-msg { font-size: 11px; color: #c0a0a0; text-align: center; max-width: 90%; line-height: 1.5; }
.pm-proxy-progress {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 60%;
  min-width: 160px;
  max-width: 280px;
}
.pm-proxy-bar-wrap {
  width: 100%;
  height: 4px;
  background: #1e1e3a;
  border-radius: 2px;
  overflow: hidden;
}
.pm-proxy-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #6366f1, #818cf8);
  border-radius: 2px;
  transition: width 0.5s ease;
}
/* Indeterminate shimmer — shown while upload phase has no progress signal */
.pm-proxy-bar.pm-proxy-indeterminate {
  width: 100% !important;
  background: linear-gradient(90deg, #1e1e3a 0%, #6366f1 40%, #818cf8 60%, #1e1e3a 100%);
  background-size: 200% 100%;
  animation: pmProxyShimmer 1.4s ease-in-out infinite;
}
@keyframes pmProxyShimmer {
  0%   { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}
.pm-proxy-label {
  font-size: 10px;
  color: #8080b8;
  letter-spacing: 0.04em;
}
.pm-proxy-eta {
  font-size: 10px;
  font-weight: 700;
  color: #2172E3;
  letter-spacing: 0.02em;
}
.pm-video-restore-btn {
  pointer-events: all;
  background: #12122a;
  border: 1px solid #2172E3;
  color: #2172E3;
  font-size: 10px;
  padding: 5px 14px;
  border-radius: 4px;
  cursor: pointer;
  letter-spacing: 0.04em;
  margin-top: 4px;
}
.pm-video-restore-btn:hover { background: #1e1e3a; }
.pm-video-hint-seq {
  font-size: 9px;
  font-family: monospace;
  color: #5a5a88;
  letter-spacing: 0.04em;
  max-width: 90%;
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* ── Now-playing clip banner ── */
.pm-clip-banner {
  display: none !important;
  align-items: center;
  gap: 7px;
  padding: 5px 10px;
  background: #0d0d1c;
  border-top: 1px solid #1a1a2e;
  font-family: "SF Mono", ui-monospace, monospace;
  font-size: 10px;
  flex-shrink: 0;
  overflow: hidden;
  white-space: nowrap;
  min-height: 0;
}
.pm-banner-dot {
  display: inline-block;
  width: 8px; height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.pm-banner-clip {
  color: #e4e4f8;
  font-weight: 700;
  letter-spacing: 0.02em;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
  flex: 1 1 0;
}
.pm-banner-reel {
  color: #6868a0;
  font-size: 8.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  flex-shrink: 1;
  min-width: 0;
}
.pm-banner-sep { color: #2a2a50; font-size: 9px; flex-shrink: 0; }
.pm-banner-tc  { color: #8888b8; font-size: 8.5px; flex-shrink: 0; letter-spacing: 0.02em; }
.pm-banner-dur { color: #4a4a78; font-size: 8px; flex-shrink: 0; }

/* ── Timeline clip hover tooltip ── */
.pm-tl-tooltip {
  display: none;
  position: fixed;
  z-index: 99999;
  background: #12132a;
  border: 1px solid #32325a;
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 11px;
  font-family: "SF Mono", ui-monospace, monospace;
  color: #d0d0f0;
  box-shadow: 0 8px 28px rgba(0,0,0,0.65);
  pointer-events: none;
  max-width: min(340px, calc(100vw - 24px));
  min-width: min(220px, calc(100vw - 24px));
  line-height: 1.6;
}
/* Header */
.pm-tl-tip-clip { font-size: 13px; color: #ffffff; font-weight: 700; margin-bottom: 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-tl-tip-sub  { color: #7878b0; font-size: 10.5px; margin-bottom: 1px; }
/* Section divider */
.pm-tl-tip-div  { height: 1px; background: #242448; margin: 7px 0; }
/* TC grid: 2-column label / value */
.pm-tl-tip-grid { display: grid; grid-template-columns: max-content 1fr; row-gap: 3px; column-gap: 14px; }
.pm-tl-tip-lbl  { color: #5858a0; font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; align-self: center; white-space: nowrap; }
.pm-tl-tip-val  { color: #c8c8f0; font-size: 11px; }
.pm-tl-tip-dim  { color: #5858a0; font-size: 10px; }
/* Speed / retime */
.pm-tl-tip-speed         { font-size: 11px; font-weight: 700; color: #f5a623; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.pm-tl-tip-speed-freeze  { color: #E5484D !important; }
.pm-tl-tip-speed-rev     { color: #80c0ff !important; }
.pm-tl-tip-speed-retime  { color: #f5a623; }
/* Speed type tag (pill badge inside tooltip speed row) */
.pm-tl-tip-speed-tag {
  display: inline-block; border-radius: 3px; padding: 1px 6px; font-size: 9px; font-weight: 800;
  letter-spacing: 0.07em; flex-shrink: 0;
}
.pm-tl-tip-speed-tag--pm-tl-tip-speed-retime { color: #2172E3; background: rgba(214,163,58,0.14); border: 1px solid rgba(214,163,58,0.28); }
.pm-tl-tip-speed-tag--pm-tl-tip-speed-freeze { color: #f08080; background: rgba(224,108,117,0.14); border: 1px solid rgba(224,108,117,0.30); }
.pm-tl-tip-speed-tag--pm-tl-tip-speed-rev    { color: #90c8ff; background: rgba(80,160,245,0.14); border: 1px solid rgba(80,160,245,0.28); }
.pm-tl-tip-speed-tag--retime { color: #2172E3; background: rgba(214,163,58,0.14); border: 1px solid rgba(214,163,58,0.28); }
/* Speed source→output breakdown row */
.pm-tl-tip-speed-detail {
  font-size: 10px; font-weight: 400; color: #8888b8; margin-top: 3px;
  font-family: "SF Mono", ui-monospace, monospace;
}
.pm-tl-tip-speed-ratio  { color: #a0a0d0; font-size: 9.5px; }
/* Transform */
.pm-tl-tip-transform { font-size: 10.5px; color: #7a9ee0; }
/* Chips row */
.pm-tl-tip-chips { display: flex; gap: 5px; flex-wrap: wrap; }
.pm-tl-tip-chip  { display: inline-block; border-radius: 4px; padding: 2px 7px; font-size: 10px; font-weight: 700; background: rgba(255,255,255,0.05); color: #7a7ab8; border: 1px solid rgba(255,255,255,0.10); }
.pm-tl-tip-chip-track  { color: #539c95; border-color: rgba(86,212,200,0.30); background: rgba(86,212,200,0.10); }
.pm-tl-tip-chip-cam    { color: #b8ff5a; border-color: rgba(184,255,90,0.28); background: rgba(184,255,90,0.08); }
.pm-tl-tip-chip-src    { color: #7878a8; border-color: rgba(120,120,168,0.22); }
.pm-tl-tip-chip-fps    { color: #e5a550; border-color: rgba(229,165,80,0.28); background: rgba(229,165,80,0.08); }
.pm-tl-tip-chip-mk     { color: #a386ba; border-color: rgba(198,120,221,0.28); background: rgba(198,120,221,0.08); }
.pm-tl-tip-chip-linked { color: #539c95; border-color: rgba(86,212,200,0.22); }
.pm-tl-tip-chip-warn   { color: #E5484D; border-color: rgba(224,108,117,0.35); background: rgba(224,108,117,0.12); }
/* ALE comment */
.pm-tl-tip-comment { font-size: 10.5px; color: #9898c8; font-style: italic; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 312px; }
/* Footer hint */
.pm-tl-tip-hint { color: #3e3e72; font-size: 9.5px; font-style: italic; border-top: 1px solid #1e1e42; padding-top: 5px; margin-top: 2px; }

.pm-hud {
  display: flex;
  gap: 8px;
  padding: 3px 10px;
  background: #0a0a14;
  font-family: monospace;
  font-size: 9px;
  flex-shrink: 0;
  border-top: 1px solid #141428;
}
.pm-hud-tc      { color: #9898b8; }
.pm-hud-rec     { color: #b0a0ff; }
.pm-hud-src     { color: #8888a8; }
.pm-hud-burnin  { color: #e09850; }
.pm-hud-tc-offset { color: #c07840; font-size: 8px; letter-spacing: 0.04em; }
.pm-hud-tc-warn { color: #e05040; font-size: 8px; cursor: help; }
.pm-hud-frame   { color: #8080a0; }
.pm-hud-tc-input {
  background: rgba(80,70,160,.25); border: 1px solid #6050c0;
  border-radius: 3px; color: #d0c8ff; font-size: inherit;
  font-family: inherit; width: 82px; padding: 0 3px; height: 16px;
  outline: none; caret-color: #b0a0ff;
}
.pm-hud-sep   { color: #2a2a44; margin: 0 4px; }
/* Sync controls */
.pm-sync-btn   { font-size: 8px; padding: 1px 6px; border-radius: 3px; border: 1px solid #4a4a70; background: rgba(255,255,255,.05); color: #9090c8; cursor: pointer; letter-spacing: 0.06em; margin-left: auto; flex-shrink: 0; }
.pm-vid-start-tc { width: 72px; background: #0a0a18; border: 1px solid #2a2a42; border-radius: 3px; color: #a0a0c8; font-family: monospace; font-size: 8.5px; padding: 1px 4px; outline: none; flex-shrink: 0; }
.pm-vid-start-tc:focus { border-color: #E0B341; color: #E0B341; }
.pm-sync-btn:hover { border-color: #6060a0; color: #a0a0c8; }
.pm-sync-btn.pm-sync-armed { border-color: #E0B341; color: #E0B341; background: #1e1808; animation: pm-sync-pulse 0.8s ease-in-out infinite alternate; }
.pm-sync-btn.pm-sync-locked { border-color: #0AA356; color: #0AA356; background: #071410; animation: none; opacity: 1; }
@keyframes pm-sync-pulse { from { opacity: 0.7; } to { opacity: 1; } }
.pm-sync-offset { font-size: 8px; font-family: monospace; color: #4a4a70; padding: 0 4px; cursor: default; transition: color 0.2s; }
.pm-sync-nudge  { font-size: 10px; padding: 0 3px; background: none; border: 1px solid rgba(100,100,160,0.25); border-radius: 2px; color: #6060a0; cursor: pointer; line-height: 1.4; transition: color 0.1s, border-color 0.1s; }
.pm-sync-nudge:hover { color: #a0a0d0; border-color: rgba(140,140,200,0.5); }
.pm-sync-reset  { font-size: 9px; padding: 0 4px; background: none; border: none; color: #7070a0; cursor: pointer; }
.pm-sync-reset:hover { color: #a0a0c8; }

/* Sync toast */
.pm-sync-toast {
  position: fixed;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  background: #1e1808;
  border: 1px solid #E0B341;
  color: #E0B341;
  font-size: 10px;
  font-family: monospace;
  padding: 5px 14px;
  border-radius: 4px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s, transform 0.15s;
  z-index: 9999;
  white-space: nowrap;
}
.pm-sync-toast.pm-sync-toast-visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.pm-controls {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  background: #0a0a14;
  border-top: 1px solid #141428;
  flex-shrink: 0;
}
.pm-controls button {
  font-size: 9px;
  background: rgba(255,255,255,.05);
  border: 1px solid #3a3a52;
  color: #9090b8;
  border-radius: 3px;
  padding: 2px 7px;
  cursor: pointer;
  flex-shrink: 0;
}
.pm-controls button:hover { background: #1a1a28; color: #ccc; }
.pm-scrub {
  flex: 1;
  height: 6px;
  cursor: pointer;
  accent-color: #3a5a88;
}
.pm-mark-btn { color: #2172E3 !important; border-color: #5a4a10 !important; background: #1c1808 !important; font-weight: 700 !important; }
/* Help affordance in the transport bar — carries the tutorial's own orange so the
   button and the panel it opens read as one thing. */
.pm-help-btn { color: #ff9e6c !important; border-color: #4a3020 !important; background: #16100c !important; font-weight: 600 !important; }
.pm-help-btn:hover { color: #ffb489 !important; border-color: #6a4428 !important; background: #201610 !important; }

/* ── Marker color picker ── */
.pm-marker-color-wrap { position: relative; display: inline-flex; }
.pm-marker-color-btn  { padding: 2px 5px !important; }
.pm-color-swatch      { display: inline-block; width: 10px; height: 10px; border-radius: 50%; border: 1px solid rgba(255,255,255,0.25); vertical-align: middle; pointer-events: none; }
.pm-color-menu {
  position: absolute; bottom: calc(100% + 4px); left: 0;
  background: #18182a; border: 1px solid #2e2e50; border-radius: 6px;
  padding: 5px; z-index: 9999; min-width: 140px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.6);
}
.pm-color-item {
  display: flex; align-items: center; gap: 7px; width: 100%;
  background: none; border: none; border-radius: 3px;
  padding: 4px 6px; cursor: pointer; color: #c0c0d8; font-size: 10px;
  text-align: left;
}
.pm-color-item:hover { background: rgba(255,255,255,0.07); }
.pm-color-dot  { width: 12px; height: 12px; border-radius: 50%; flex-shrink: 0; }
.pm-color-label { flex: 1; }

/* Inspector color row */
.pm-insp-color-row { display: flex; flex-wrap: nowrap; gap: 3px; padding: 2px 0 1px; overflow: hidden; }
.pm-insp-color-row--inline { border-top: 1px solid #14142a; margin-top: 2px; padding-top: 3px; width: 100%; box-sizing: border-box; }
.pm-insp-color-swatch {
  width: 12px; height: 12px; border-radius: 50%; border: 2px solid transparent;
  cursor: pointer; padding: 0; flex-shrink: 0;
  transition: transform 0.1s;
}
.pm-insp-color-swatch:hover { transform: scale(1.25); }
.pm-insp-color-sel  { border-color: #fff !important; transform: scale(1.2); }
.pm-inspector {
  flex-shrink: 0;
  max-height: 380px;
  overflow-y: auto;
  background: #080810;
  border-top: 1px solid #1a1a2e;
  font-size: 9px;
  transition: max-height 0.18s ease, opacity 0.15s ease;
  opacity: 1;
}
/* .pm-inspector-hidden no longer used — inspector always visible */
.pm-inspector.pm-inspector-hidden {
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  border-top-color: transparent;
}
/* Legacy row (event fallback view) */
.pm-insp-row { display:flex; gap:8px; padding:2px 10px; border-bottom:1px solid #0d0d18; color:#555; font-size:9px; line-height:1.7; }
.pm-insp-row b { color:#606088; flex:0 0 88px; font-weight:600; font-size:8px; }
.pm-insp-divider { background:#0a0a14; }
.pm-insp-divider b { color:#5a5a78; }

/* ── Editable marker inspector ─────────────────────────────────────────────── */
.pm-insp-mk { padding: 3px 6px; display: flex; flex-direction: column; gap: 3px; }
.pm-insp-mk-hdr { display: flex; gap: 8px; align-items: flex-start; }
.pm-insp-thumb { width: 80px; height: 45px; object-fit: contain; background: #000; border-radius: 3px; border: 1px solid #1a1a2e; flex-shrink: 0; cursor: pointer; }
.pm-insp-thumb-empty { width: 80px; height: 45px; background: #0a0a18; border: 1px dashed #1a1a2e; border-radius: 3px; flex-shrink: 0; }
.pm-insp-mk-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.pm-insp-clip { font-size: 8px; color: #a8a8cc; font-family: monospace; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pm-insp-tc-row { display: flex; align-items: center; gap: 2px; }
.pm-insp-lbl { font-size: 8px; color: #c8c8e8; flex-shrink: 0; width: 24px; font-weight: 700; text-transform: uppercase; }
.pm-insp-tc { font-family: monospace; font-size: 9px; background: #0e0e1c; border: 1px solid #1e1e34; border-radius: 2px; color: #d4d4f8; padding: 1px 4px; width: 74px; outline: none; }
.pm-insp-tc:focus { border-color: #4040a0; color: #e8e8ff; }
.pm-insp-tc-sep { color: #a0a0c0; font-size: 8px; }
.pm-insp-deretime-btn { font-size: 8px; font-family: monospace; background: #1a1a30; border: 1px solid #4a3a6a; border-radius: 2px; color: #c090f0; padding: 1px 5px; cursor: pointer; flex-shrink: 0; white-space: nowrap; line-height: 1.6; }
.pm-insp-deretime-btn:hover { background: #2a1a4a; border-color: #8060c0; color: #e0b0ff; }
.pm-link-ok   { font-size: 9px; color: #0AA356; margin-left: 4px; flex-shrink: 0; line-height: 1; }
.pm-link-warn { font-size: 10px; color: #2172E3; margin-left: 4px; flex-shrink: 0; line-height: 1; cursor: help; }
.pm-vfy-ok   { font-size: 8px; color: #0AA356; margin-left: 2px; vertical-align: middle; }
.pm-vfy-warn { font-size: 9px; color: #2172E3; margin-left: 2px; vertical-align: middle; cursor: help; }
.pm-insp-dur { font-size: 9px; color: #8080a8; font-family: monospace; margin-top: 1px; }
.pm-insp-shot-row { display: flex; gap: 4px; align-items: center; flex-wrap: nowrap; }
.pm-insp-shot { flex: 1; min-width: 0; background: #0d0d1a; border: 1px solid #1e1e34; border-radius: 3px; color: #a386ba; font-family: monospace; font-size: 9px; padding: 2px 6px; outline: none; }
.pm-insp-shot:focus { border-color: #6a3aaa; }
.pm-insp-template-btn {
  display: flex; align-items: center; gap: 3px;
  font-size: 7.5px; padding: 2px 6px; border-radius: 3px;
  border: 1px solid #3a4a20; background: #141a08; color: #98b840;
  cursor: pointer; flex-shrink: 0; white-space: nowrap;
  font-weight: 600; letter-spacing: 0.04em;
}
.pm-insp-template-btn:hover { background: #1e2a0c; color: #c0e050; border-color: #5a7030; }
.pm-insp-template-btn svg { width: 11px; height: 11px; flex-shrink: 0; }
.pm-insp-status-badge { font-size: 7.5px; padding: 1px 6px; border-radius: 8px; border: 1px solid currentColor; background: transparent; cursor: pointer; text-transform: uppercase; letter-spacing: 0.06em; flex-shrink: 0; }
/* ── Naming tools row ──────────────────────────────────────────────────────── */
.pm-insp-name-tools {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 7px 9px;
  border-radius: 8px;
  border: 1px solid rgba(255,255,255,0.08);
  background:
    radial-gradient(140px 52px at 0% 0%, rgba(214,163,58,0.08), transparent 70%),
    radial-gradient(160px 60px at 100% 0%, rgba(97,175,239,0.08), transparent 70%),
    linear-gradient(180deg, rgba(14,16,28,0.98), rgba(9,10,18,0.98));
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04);
}
.pm-insp-name-preview-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pm-insp-plate-controls {
  display: flex;
  flex-direction: row;
  align-items: flex-end;
  gap: 3px;
}
.pm-insp-plate-field {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.pm-insp-plate-lbl {
  font-size: 6.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #9090b4;
  white-space: nowrap;
  padding-left: 1px;
}
.pm-insp-plate-field:nth-child(1) { flex: 0 0 62px; }
.pm-insp-plate-field:nth-child(2) { flex: 0 0 38px; }
.pm-insp-plate-field:nth-child(3) { flex: 1 1 52px; }
.pm-insp-plate-field:nth-child(4) { flex: 1 1 52px; }
.pm-insp-plate-field:nth-child(5) { flex: 0 0 52px; }
.pm-insp-plate-select {
  width: 100%;
  min-width: 0;
  height: 24px;
  padding: 0 16px 0 7px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,0.10);
  background:
    linear-gradient(180deg, rgba(20,24,36,0.98), rgba(12,14,25,0.98));
  color: #c9d1f5;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  font-family: "SF Mono", ui-monospace, monospace;
  outline: none;
  appearance: none;
  -webkit-appearance: none;
  background-image:
    linear-gradient(45deg, transparent 50%, #7f87aa 50%),
    linear-gradient(135deg, #7f87aa 50%, transparent 50%),
    linear-gradient(180deg, rgba(20,24,36,0.98), rgba(12,14,25,0.98));
  background-position:
    calc(100% - 11px) calc(50% - 1px),
    calc(100% - 7px) calc(50% - 1px),
    0 0;
  background-size: 4px 4px, 4px 4px, 100% 100%;
  background-repeat: no-repeat;
}
.pm-insp-plate-select:focus {
  border-color: rgba(97,175,239,0.34);
  box-shadow: 0 0 0 1px rgba(97,175,239,0.16);
}
.pm-insp-plate-input {
  width: 100%;
  min-width: 0;
  height: 24px;
  padding: 0 7px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,0.10);
  background: linear-gradient(180deg, rgba(20,24,36,0.98), rgba(12,14,25,0.98));
  color: #c9d1f5;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  font-family: "SF Mono", ui-monospace, monospace;
  outline: none;
}
.pm-insp-plate-input:focus {
  border-color: rgba(97,175,239,0.34);
  box-shadow: 0 0 0 1px rgba(97,175,239,0.16);
}
.pm-insp-plate-input::placeholder {
  color: #6f7598;
}
.pm-insp-plate-code { color: #9be2b4; }
.pm-insp-plate-num  { color: #2172E3; }
.pm-insp-plate-task,
.pm-insp-plate-vendor { color: #c7c9ff; }
.pm-insp-plate-ver  { color: #74b0c9; }
.pm-insp-name-preview-head {
  display: flex;
  align-items: baseline;
  justify-content: flex-start;
  gap: 8px;
}
.pm-insp-name-label {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #6f7598;
}
.pm-insp-name-caption {
  font-size: 7px;
  color: #4a4f70;
  white-space: nowrap;
}
.pm-insp-name-token-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.pm-insp-name-token {
  display: inline-flex;
  align-items: center;
  min-height: 18px;
  padding: 1px 7px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.08);
  background: rgba(255,255,255,0.04);
  color: #b3b8d8;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.05em;
  font-family: "SF Mono", ui-monospace, monospace;
}
.pm-insp-name-token.is-shotid {
  color: #2172E3;
  background: rgba(214,163,58,0.12);
  border-color: rgba(214,163,58,0.28);
}
.pm-insp-name-token-ver {
  color: #74b0c9;
  background: rgba(114,230,255,0.10);
  border-color: rgba(114,230,255,0.22);
}
.pm-insp-name-token-plate {
  color: #9be2b4;
  background: rgba(10,163,86,0.10);
  border-color: rgba(10,163,86,0.22);
}
.pm-insp-name-token-platever {
  color: #74b0c9;
  background: rgba(114,230,255,0.10);
  border-color: rgba(114,230,255,0.22);
}
.pm-insp-name-token-muted {
  color: #5e6487;
  background: rgba(255,255,255,0.025);
}
.pm-insp-name-value {
  display: none;
  font-family: "SF Mono", ui-monospace, monospace;
  font-size: 13px;
  font-weight: 700;
  color: #edf0ff;
  line-height: 1.25;
  word-break: break-all;
  letter-spacing: 0.02em;
}
.pm-insp-name-preview-block-ver .pm-insp-name-value {
  color: #9fd7ff;
}
.pm-insp-name-preview-block-ver .pm-insp-name-value:not(.is-muted) {
  color: #9fd7ff;
}
.pm-insp-name-preview-block-plate .pm-insp-name-value {
  color: #a7efbf;
}
.pm-insp-name-value.is-muted {
  color: #5f678a;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.04em;
}
.pm-insp-name-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
}
.pm-insp-generate {
  display: flex; align-items: center; gap: 3px;
  justify-content: center;
  font-size: 7.5px; font-weight: 800; letter-spacing: 0.08em;
  min-height: 22px; padding: 1px 7px; border-radius: 4px;
  border: 1px solid rgba(214,163,58,0.32);
  background: linear-gradient(180deg, rgba(37,29,13,0.98), rgba(23,18,9,0.98));
  color: #2172E3; cursor: pointer; flex-shrink: 0; flex-grow: 1; white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04);
  min-width: 0;
}
.pm-insp-generate:hover { background: #2a1e08; color: #ffd060; border-color: #9a7030; }
.pm-insp-generate svg { width: 10px; height: 10px; flex-shrink: 0; }
.pm-insp-template-open {
  display: flex; align-items: center; gap: 3px;
  justify-content: center;
  font-size: 7.5px; font-weight: 700; letter-spacing: 0.06em;
  min-height: 22px; padding: 1px 8px; border-radius: 4px;
  border: 1px solid rgba(97,175,239,0.30); background: #0c0e1e; color: #2172E3;
  cursor: pointer; flex-shrink: 0; white-space: nowrap; min-width: 0;
}
.pm-insp-template-open:hover { background: #111830; color: #9ec8ff; border-color: #4060a0; }
.pm-insp-template-open.pm-nt-active { background: #0a1428; color: #9ec8ff; border-color: #3a6aaa; box-shadow: inset 0 1px 0 rgba(160,200,255,0.07); }

/* ── Naming Template Inline Chip Bar ───────────────────────────────────────── */
.pm-nt-bar {
  grid-column: 1 / -1;
  display: flex; align-items: center; flex-wrap: wrap; gap: 4px;
  background: #080b18; border: 1px solid #1e2840;
  border-radius: 6px; padding: 5px 8px;
  margin-top: 2px; min-width: 0;
  box-shadow: 0 2px 8px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.03);
}
.pm-nt-ico { display: flex; align-items: center; opacity: 0.45; flex-shrink: 0; }
.pm-nt-chips-row { display: flex; align-items: center; flex-wrap: wrap; gap: 4px; flex: 1 1 auto; min-width: 0; }
.pm-nt-chip {
  display: inline-flex; align-items: center; gap: 0;
  height: 22px; border-radius: 999px;
  border: 1px solid rgba(97,175,239,0.5);
  background: rgba(97,175,239,0.13);
  font-size: 10px; white-space: nowrap; overflow: hidden;
  cursor: default; flex-shrink: 0;
}
.pm-nt-chip-shot {
  border-color: rgba(214,163,58,0.55);
  background: rgba(214,163,58,0.13);
}
.pm-nt-chip-lbl {
  padding: 0 5px 0 7px; font-size: 9px; font-weight: 700;
  color: rgba(180,210,255,1); letter-spacing: 0.03em; text-transform: uppercase;
}
.pm-nt-chip-shot .pm-nt-chip-lbl { color: rgba(245,197,100,0.95); }
.pm-nt-chip-colon { color: rgba(255,255,255,0.6); padding-right: 2px; font-size: 9px; }
.pm-nt-chip-val {
  padding: 0 5px 0 2px; font-size: 10px; font-weight: 600; font-family: monospace;
  color: #e2eeff; cursor: pointer; border-radius: 3px;
  transition: background 0.1s;
}
.pm-nt-chip-val:hover { background: rgba(255,255,255,0.1); color: #ffffff; }
.pm-nt-chip-shot .pm-nt-chip-val { color: #ffd055; }
.pm-nt-chip-rm {
  display: flex; align-items: center; justify-content: center;
  width: 18px; height: 100%; border: none; background: transparent;
  color: rgba(255,255,255,0.45); font-size: 12px; cursor: pointer; padding: 0;
  border-left: 1px solid rgba(255,255,255,0.15); flex-shrink: 0;
  transition: background 0.1s, color 0.1s;
}
.pm-nt-chip-rm:hover { background: rgba(224,108,117,0.22); color: #E5484D; }
.pm-nt-chip-inp {
  background: transparent; border: none; outline: none;
  font-size: 10px; font-family: monospace; color: #e8f0ff;
  padding: 0 4px; height: 20px; min-width: 32px; max-width: 120px;
}
.pm-nt-ghost {
  display: inline-flex; align-items: center; height: 22px; padding: 0 8px;
  border-radius: 999px; border: 1px dashed rgba(255,255,255,0.38);
  background: rgba(255,255,255,0.05); color: rgba(255,255,255,0.55);
  font-size: 9px; font-weight: 600; cursor: pointer; letter-spacing: 0.03em;
  transition: border-color 0.15s, color 0.15s, background 0.15s;
}
.pm-nt-ghost:hover { border-color: rgba(97,175,239,0.7); color: #2172E3; background: rgba(97,175,239,0.12); }
.pm-nt-preview {
  font-size: 9.5px; font-family: monospace; color: #7090b8;
  padding: 0 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 180px; flex-shrink: 1;
}
.pm-nt-apply {
  display: flex; align-items: center; justify-content: center;
  height: 22px; padding: 0 10px; border-radius: 4px; flex-shrink: 0;
  border: 1px solid rgba(97,175,239,0.4); background: #0c1428;
  color: #2172E3; font-size: 9px; font-weight: 700; letter-spacing: 0.06em;
  cursor: pointer; text-transform: uppercase;
  transition: background 0.1s, border-color 0.1s, color 0.1s;
}
.pm-nt-apply:hover { background: #1a2840; border-color: #4a80c0; color: #9ec8ff; }
.pm-nt-close {
  display: flex; align-items: center; justify-content: center;
  width: 20px; height: 20px; border-radius: 50%; border: none;
  background: transparent; color: rgba(255,255,255,0.25);
  font-size: 13px; cursor: pointer; flex-shrink: 0;
  transition: background 0.1s, color 0.1s;
}
.pm-nt-close:hover { background: rgba(224,108,117,0.18); color: #E5484D; }
.pm-nt-mode-btn {
  display: flex; align-items: center; justify-content: center;
  width: 20px; height: 20px; border-radius: 4px; border: 1px solid rgba(255,255,255,0.1);
  background: transparent; color: rgba(255,255,255,0.3);
  font-size: 11px; cursor: pointer; flex-shrink: 0;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
}
.pm-nt-mode-btn:hover { background: rgba(97,175,239,0.1); color: #2172E3; border-color: rgba(97,175,239,0.3); }
.pm-nt-auto-badge {
  flex-shrink: 0; padding: 1px 6px; border-radius: 3px;
  font-size: 9px; font-weight: 700; letter-spacing: 0.06em;
  cursor: pointer; white-space: nowrap;
  transition: background 0.12s, color 0.12s, border-color 0.12s;
}
.pm-nt-auto-badge--on  { background: rgba(80,200,120,0.12); color: #50c878; border: 1px solid rgba(80,200,120,0.35); }
.pm-nt-auto-badge--off { background: rgba(255,255,255,0.04); color: rgba(255,255,255,0.25); border: 1px solid rgba(255,255,255,0.1); }
.pm-nt-auto-badge--on:hover  { background: rgba(80,200,120,0.22); border-color: rgba(80,200,120,0.6); }
.pm-nt-auto-badge--off:hover { background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.5); border-color: rgba(255,255,255,0.2); }
/* Shot# counter mini panel */
.pm-nt-shotnum-panel {
  display: flex; align-items: center; gap: 6px;
  background: #0a0d1c; border: 1px solid #1e2840; border-radius: 5px;
  padding: 5px 8px; margin-top: 2px; flex-basis: 100%;
}
.pm-nt-sn-lbl {
  display: flex; align-items: center; gap: 4px;
  font-size: 9px; color: rgba(255,255,255,0.45); white-space: nowrap;
}
.pm-nt-sn-inp {
  width: 46px; background: #06081a; border: 1px solid #1e2840; border-radius: 3px;
  color: #c8d8f0; font-size: 10px; padding: 1px 4px; text-align: right;
}
.pm-nt-sn-ok {
  margin-left: auto; height: 20px; padding: 0 8px; border-radius: 3px;
  border: 1px solid rgba(97,175,239,0.3); background: transparent;
  color: #2172E3; font-size: 9px; font-weight: 700; cursor: pointer;
}
.pm-nt-sn-ok:hover { background: #0c1428; border-color: #4a80c0; }
/* Plate picker panel */
.pm-nt-plate-panel {
  display: flex; flex-direction: column; gap: 6px;
  background: #0a0d1c; border: 1px solid #1e2840; border-radius: 5px;
  padding: 7px 8px; margin-top: 2px; flex-basis: 100%;
}
.pm-nt-pl-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px;
}
.pm-nt-pl-code {
  height: 22px; border-radius: 3px; border: 1px solid #1e2840;
  background: #0d1020; color: rgba(200,216,240,0.6);
  font-size: 9px; font-weight: 700; letter-spacing: 0.05em; cursor: pointer;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
}
.pm-nt-pl-code:hover { background: #141828; color: #c8d8f0; border-color: #2e3c58; }
.pm-nt-pl-code.active { background: #122040; color: #2172E3; border-color: #4a80c0; }
.pm-nt-pl-custom-row {
  display: flex; align-items: center; gap: 6px;
}
.pm-nt-pl-custom {
  flex: 1; min-width: 0; background: #06081a; border: 1px solid #1e2840; border-radius: 3px;
  color: #c8d8f0; font-size: 10px; padding: 2px 5px;
}
.pm-nt-pl-num {
  width: 42px; background: #06081a; border: 1px solid #1e2840; border-radius: 3px;
  color: #c8d8f0; font-size: 10px; padding: 1px 4px; text-align: right;
}
.pm-nt-chip-plate { border-color: rgba(152,118,210,0.5); }
.pm-nt-chip-plate .pm-nt-chip-lbl { color: #b89be0; }
/* Floating chip value popup with number list (EP / SEQ / SCENE / VER#) */
.pm-nt-chip-popup {
  display: flex; flex-direction: column; gap: 4px;
  background: #1a1e2c; border: 1px solid rgba(97,175,239,0.3);
  border-radius: 6px; padding: 6px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.75); min-width: 110px;
}
.pm-nt-chip-popup-inp {
  width: 100%; box-sizing: border-box; background: #06081a;
  border: 1px solid #2a3a58; border-radius: 3px;
  color: #c8d8f0; font-size: 11px; font-family: monospace; padding: 3px 6px;
}
.pm-nt-popup-list {
  display: flex; flex-direction: column; gap: 1px;
  max-height: 148px; overflow-y: auto; border-radius: 3px;
}
.pm-nt-popup-opt {
  text-align: left; padding: 3px 7px; border-radius: 3px;
  border: none; background: none; color: #a8b8d0;
  font-size: 11px; font-family: monospace; cursor: pointer;
  transition: background 0.08s, color 0.08s; white-space: nowrap;
}
.pm-nt-popup-opt:hover { background: rgba(255,255,255,0.07); color: #c8d8f0; }
.pm-nt-popup-opt-active { color: #2172E3; background: rgba(97,175,239,0.13); font-weight: 700; }
.pm-nt-popup-opt-active:hover { background: rgba(97,175,239,0.22); }
/* Combined bar wrap — the single visual box in pm-layer-detail-right */
.pm-layer-detail-right .pm-nt-bar { grid-column: 1 / -1; }
.pm-layer-detail-right .pm-nt-bar-wrap {
  grid-column: 1 / -1;
  display: flex; flex-direction: column; gap: 2px;
  padding: 4px 6px; border-radius: 6px;
  border: 1px solid #1e2840;
  background: #080b18;
  box-shadow: 0 2px 8px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.03);
}
/* Chip bar: transparent, no extra border — wrap provides the box */
.pm-nt-bar-wrap .pm-nt-bar {
  border: none; background: transparent; box-shadow: none;
  margin: 0; padding: 0; border-radius: 0;
}
/* Static bar — column layout inside wrap */
.pm-nt-bar.pm-nt-bar-static {
  flex-direction: column; align-items: stretch; gap: 2px;
}
.pm-nt-bar-static .pm-nt-chips-row { flex-wrap: wrap; gap: 3px; }
/* Compact chip sizing inside the static inspector bar */
.pm-nt-bar-static .pm-nt-chip { height: 18px; font-size: 9.5px; }
.pm-nt-bar-static .pm-nt-chip-lbl { padding: 0 4px 0 6px; font-size: 8.5px; }
.pm-nt-bar-static .pm-nt-chip-val { padding: 0 4px 0 1px; font-size: 9.5px; }
.pm-nt-bar-static .pm-nt-chip-rm { width: 16px; font-size: 11px; }
.pm-nt-bar-static .pm-nt-ghost { height: 18px; padding: 0 6px; font-size: 8.5px; }

/* ── OCR chip status colors ── */
.pm-nt-chip-ocr { border-color: rgba(100,168,240,0.5); cursor: pointer; }
.pm-nt-chip-ocr .pm-nt-chip-lbl { color: rgba(130,190,255,0.95); }
.pm-nt-chip-ocr .pm-nt-chip-val { color: #90c4ff; }
.pm-nt-chip-ocr--verified { border-color: rgba(55,181,115,0.45); }
.pm-nt-chip-ocr--verified .pm-nt-chip-lbl { color: rgba(55,181,115,0.75); }
.pm-nt-chip-ocr--verified .pm-nt-chip-val { color: #37b573; }
.pm-nt-chip-ocr--review { border-color: rgba(255,185,74,0.45); }
.pm-nt-chip-ocr--review .pm-nt-chip-lbl { color: rgba(255,185,74,0.7); }
.pm-nt-chip-ocr--review .pm-nt-chip-val { color: #ffb94a; }
.pm-nt-chip-ocr--low { border-color: rgba(224,108,117,0.45); }
.pm-nt-chip-ocr--low .pm-nt-chip-lbl { color: rgba(224,108,117,0.7); }
.pm-nt-chip-ocr--low .pm-nt-chip-val { color: #E5484D; }
.pm-nt-chip-ocr--empty { border-color: rgba(255,255,255,0.2); opacity: 0.75; }
/* Dim chips — inactive tokens, click to re-enable */
.pm-nt-chip--dim {
  opacity: 0.65;
  cursor: pointer;
  pointer-events: auto;
  font-size: 9px;
  padding: 1px 6px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,0.28);
  background: rgba(255,255,255,0.04);
  color: rgba(255,255,255,0.7);
  white-space: nowrap;
  user-select: none;
  flex-shrink: 0;
}
.pm-nt-chip--dim:hover { opacity: 0.9; border-color: rgba(255,255,255,0.45); color: rgba(255,255,255,0.9); }
/* Drag-and-drop */
.pm-nt-chip[draggable] { cursor: grab; }
.pm-nt-chip[draggable]:active { cursor: grabbing; }
.pm-nt-chip--dragover { outline: 2px dashed rgba(97,175,239,0.6); outline-offset: 1px; }
/* Display modes */
.pm-nt-bar--mode-compact .pm-nt-chip-lbl,
.pm-nt-bar--mode-compact .pm-nt-chip-colon { display: none; }
.pm-nt-bar--mode-expanded .pm-nt-ghost { display: inline-flex; }
.pm-nt-bar--mode-auto .pm-nt-ghost { display: none; }
/* OCR context menu */
.pm-nt-ocr-ctx-menu {
  background: #1a2035; border: 1px solid rgba(255,255,255,0.12);
  border-radius: 6px; padding: 4px; min-width: 150px; box-shadow: 0 8px 24px rgba(0,0,0,0.5);
}
.pm-nt-ocr-ctx-item {
  display: block; width: 100%; text-align: left; background: none; border: none;
  padding: 5px 10px; font-size: 11px; color: rgba(228,235,255,0.82);
  border-radius: 4px; cursor: pointer;
}
.pm-nt-ocr-ctx-item:hover { background: rgba(97,175,239,0.12); color: #9ec8ff; }
/* Parse OCR dialog */
.pm-ocr-parse-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.55); z-index: 9000;
  display: flex; align-items: center; justify-content: center;
}
.pm-ocr-parse-dialog {
  background: #1a2035; border: 1px solid rgba(255,255,255,0.12);
  border-radius: 10px; padding: 18px 20px; min-width: 340px; max-width: 480px;
  box-shadow: 0 16px 48px rgba(0,0,0,0.6);
}
.pm-ocr-parse-title { font-size: 13px; font-weight: 700; color: rgba(228,235,255,0.9); margin-bottom: 10px; }
.pm-ocr-parse-raw { font-size: 11px; color: rgba(228,235,255,0.55); font-family: 'SF Mono','Fira Mono',monospace; background: rgba(255,255,255,0.04); border-radius: 4px; padding: 4px 8px; margin-bottom: 10px; word-break: break-all; }
.pm-ocr-parse-table { width: 100%; border-collapse: collapse; margin-bottom: 12px; font-size: 11px; }
.pm-ocr-parse-table th { color: rgba(228,235,255,0.45); font-weight: 600; text-align: left; padding: 2px 6px; }
.pm-ocr-parse-table td { padding: 3px 6px; color: rgba(228,235,255,0.8); }
.pm-ocr-parse-table .diff-add { color: #37b573; }
.pm-ocr-parse-table .diff-same { color: rgba(228,235,255,0.45); }
.pm-ocr-parse-table .diff-empty { color: rgba(228,235,255,0.25); font-style: italic; }
.pm-ocr-parse-actions { display: flex; gap: 8px; justify-content: flex-end; }
.pm-ocr-parse-apply { padding: 5px 14px; border-radius: 5px; border: none; background: #3b5fd6; color: #fff; font-size: 11px; font-weight: 600; cursor: pointer; }
.pm-ocr-parse-apply:hover { background: #4a70e6; }
.pm-ocr-parse-apply-empty { padding: 5px 14px; border-radius: 5px; border: 1px solid rgba(255,255,255,0.15); background: none; color: rgba(228,235,255,0.7); font-size: 11px; cursor: pointer; }
.pm-ocr-parse-apply-empty:hover { background: rgba(255,255,255,0.05); }
.pm-ocr-parse-cancel { padding: 5px 14px; border-radius: 5px; border: 1px solid rgba(255,255,255,0.1); background: none; color: rgba(228,235,255,0.5); font-size: 11px; cursor: pointer; }
.pm-ocr-parse-cancel:hover { color: rgba(228,235,255,0.85); }

.pm-nt-preview-row {
  display: flex; align-items: center; gap: 6px; padding-top: 3px;
  border-top: 1px solid rgba(255,255,255,0.05);
}
.pm-nt-preview-row .pm-nt-preview { flex: 1 1 auto; }
.pm-nt-preview-row .pm-nt-apply { margin-left: auto; height: 18px; padding: 0 8px; font-size: 8.5px; }

.pm-insp-vfx-flags { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 3px; flex-wrap: nowrap; margin-bottom: 0; width: 100%; }
.pm-vfx-flag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 22px;
  font-size: 7.5px;
  padding: 1px 6px;
  border-radius: 999px;
  border: 1px solid #3a3a58;
  background: rgba(255,255,255,.04);
  color: #7878a8;
  cursor: pointer;
  letter-spacing: 0.04em;
  transition: all 0.1s;
}
.pm-vfx-flag:hover { border-color: #5050a0; color: #a0a0d0; }
.pm-vfx-flag.active { background: #12112a; border-color: #6060c0; color: #c0c0ff; font-weight: 600; }
.pm-vfx-flag[data-flag="retime"].active    { border-color: #E0B341; color: #E0B341; background: #1e1808; }
.pm-vfx-flag[data-flag="stabilize"].active { border-color: #56b6c2; color: #56b6c2; background: #081618; }
.pm-vfx-flag[data-flag="resize"].active    { border-color: #a386ba; color: #a386ba; background: #160e1c; }
/* ── Color picker dropdown ────────────────────────────────────────────────── */
.pm-color-drop-wrap { position: relative; display: inline-block; }
.pm-color-pick-btn {
  display: inline-flex; align-items: center; gap: 5px;
  height: 22px; padding: 0 8px 0 6px;
  border-radius: 4px;
  border: 1px solid #2a2a48;
  background: #0c0c1e; color: #c0c0d8;
  cursor: pointer; font-size: 8px; font-weight: 700;
  letter-spacing: 0.04em; white-space: nowrap;
}
.pm-color-pick-btn:hover { border-color: #4a4a78; color: #c0c0e0; }
.pm-color-pick-dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; border: 1px solid rgba(255,255,255,0.25); }
.pm-color-pick-chevron { font-size: 9px; color: #9898b8; }
.pm-color-pick-popup {
  position: fixed;
  display: grid; grid-template-columns: repeat(3, 22px);
  gap: 5px; padding: 9px;
  background: #111122; border: 1px solid #2a2a44;
  border-radius: 8px; box-shadow: 0 6px 24px rgba(0,0,0,0.65);
  z-index: 99999;
}
.pm-color-pick-popup.is-hidden { display: none; }
.pm-color-pick-popup .pm-insp-color-swatch { width: 22px; height: 22px; }

.pm-insp-sow, .pm-insp-note { width: 100%; box-sizing: border-box; background: #0a0a16; border: 1px solid #1a1a2e; border-radius: 3px; color: #c0c0dc; font-size: 8.5px; padding: 1px 4px; resize: none; outline: none; min-height: 0; max-height: 38px; font-family: monospace; line-height: 1.35; overflow-y: auto; }
.pm-insp-sow:focus, .pm-insp-note:focus { border-color: #2e2e60; }
.pm-insp-note { color: #d0d0b8; border-color: #2a2a1a; }
.pm-insp-note::placeholder { color: rgba(200,200,180,0.45); }
.pm-insp-ntrow { display: flex; align-items: center; gap: 4px; min-height: 14px; flex-wrap: nowrap; overflow: hidden; }
.pm-insp-ntbadge { font-size: 7px; font-weight: 700; padding: 1px 5px; border-radius: 2px; text-transform: uppercase; letter-spacing: 0.5px; white-space: nowrap; }
.pm-insp-nt-add    { background: rgba(46,204,113,0.15); color: #2ecc71; border: 1px solid rgba(46,204,113,0.35); }
.pm-insp-nt-remove { background: rgba(255,76,76,0.15);  color: #ff4c4c; border: 1px solid rgba(255,76,76,0.35); }
.pm-insp-nt-change { background: rgba(255,209,102,0.15);color: #ffd166; border: 1px solid rgba(255,209,102,0.35); }
.pm-insp-nttype { font-size: 8.5px; color: #a0a0c0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pm-insp-anno-list { display: flex; flex-direction: column; gap: 1px; }
.pm-insp-anno-item { display: flex; align-items: center; gap: 5px; padding: 2px 0; border-bottom: 1px solid rgba(255,255,255,0.03); }
.pm-insp-anno-item:last-child { border-bottom: none; }
.pm-insp-anno-idx  { font-size: 8px; color: #4a4a6a; min-width: 10px; text-align: right; font-variant-numeric: tabular-nums; flex-shrink: 0; }
.pm-insp-anno-kind { font-size: 8px; color: #5a5a7e; flex-shrink: 0; min-width: 52px; }
.pm-insp-anno-t    { font-size: 9px; color: #c8c8e0; font-weight: 500; flex: 1; }
.pm-insp-anno-sow  { font-size: 8px; color: #7878a0; font-style: italic; flex-shrink: 0; }
.pm-insp-actions { display: flex; gap: 5px; }
.pm-insp-btn { font-size: 8px; padding: 2px 8px; border-radius: 3px; border: 1px solid #4a4a68; background: rgba(255,255,255,.05); color: #a0a0cc; cursor: pointer; }
.pm-insp-btn:hover { background: #1a1a2c; color: #c0c0e0; }
.pm-insp-annotate { border-color: #3a3060; color: #a386ba; }
.pm-insp-goto     { border-color: #1a3060; color: #2172E3; }
.pm-insp-delete   { border-color: #3a1a1a; color: #E5484D; margin-left: auto; }

/* ── Event fallback view ───────────────────────────────────────────────────── */
.pm-insp-ev { padding: 6px 8px; display: flex; flex-direction: column; gap: 3px; }
.pm-insp-ev-row { display: flex; gap: 6px; align-items: center; }
.pm-insp-val { color: #8080a8; font-size: 8.5px; }
.pm-insp-val.mono { font-family: monospace; color: #7878a0; }
.pm-insp-add-mk { font-size: 8px; padding: 2px 10px; border: 1px solid #3a4a10; background: #141808; color: #b0c040; border-radius: 3px; cursor: pointer; margin-top: 4px; }
.pm-insp-add-mk:hover { background: #1e2410; color: #d0e060; }
.pm-insp-empty { color: #3a3a58; font-size: 8px; padding: 10px; text-align: center; }

/* ── Multi-layer VFX inspector ───────────────────────────────────────────── */
.pm-insp-layers { display: flex; flex-direction: column; height: 100%; }
.pm-insp-ev-hdr { display: flex; align-items: center; justify-content: space-between; padding: 5px 8px 4px; border-bottom: 1px solid #14142a; flex-shrink: 0; gap: 6px; }
.pm-insp-hdr-info { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1; }
.pm-insp-ev-reel { font-size: 9px; color: #c0c0e0; font-family: monospace; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-weight: 600; }
.pm-insp-ev-dur  { font-size: 7.5px; color: #4a4a6a; font-family: monospace; }
.pm-layer-add-btn { font-size: 7.5px; padding: 2px 7px; border: 1px solid #3a4a10; background: #141808; color: #98c030; border-radius: 3px; cursor: pointer; flex-shrink: 0; white-space: nowrap; }
.pm-layer-add-btn:hover { background: #1e2410; color: #c0e050; border-color: #5a7020; }
.pm-sel-all-btn { font-size: 7.5px; padding: 2px 7px; border: 1px solid #1e2a40; background: #0d1520; color: #2172E3; border-radius: 3px; cursor: pointer; flex-shrink: 0; white-space: nowrap; }
.pm-sel-all-btn:hover { background: #142030; color: #7dc0ff; border-color: #2e4060; }
.pm-layers-list { flex: 1; overflow-y: auto; display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; padding: 4px; align-content: start; }
.pm-layer-empty { color: #484868; font-size: 9px; padding: 8px 10px; text-align: center; line-height: 1.6; grid-column: 1 / -1; }
.pm-layer-empty b { color: #686888; }
.pm-layer-row { border: 1px solid #131328; border-radius: 5px; background: #09091a; overflow: visible; }
.pm-layer-row.pm-layer-expanded   { background: #0c0c1c; border-color: #2172E3; grid-column: 1 / -1; }
.pm-layer-row.pm-layer-multi-sel  { border-color: rgba(97,175,239,0.5); background: rgba(97,175,239,0.04); }

/* --- Batch panel (multi-select markers) --- */
.pm-batch-panel  { padding: 8px 10px; display: flex; flex-direction: column; gap: 8px; }
.pm-batch-title  { font-size: 9px; color: #2172E3; display: flex; align-items: center; justify-content: space-between; }
.pm-batch-clear  { background: none; border: none; color: #3a3a58; cursor: pointer; font-size: 10px; padding: 0 2px; }
.pm-batch-clear:hover { color: #E5484D; }
.pm-batch-row    { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.pm-batch-label  { font-size: 8px; color: #3a3a58; min-width: 36px; }
.pm-batch-status { background: #0e0e1a; border: 1px solid #1a1a2e; border-radius: 3px; color: #8b8ba7;
                   font-size: 8px; padding: 2px 6px; cursor: pointer; }
.pm-batch-status:hover   { border-color: #2172E3; color: #2172E3; }
.pm-batch-color  { width: 14px; height: 14px; border-radius: 50%; border: 1px solid rgba(255,255,255,0.15);
                   cursor: pointer; padding: 0; }
.pm-batch-color:hover { transform: scale(1.25); border-color: rgba(255,255,255,0.6); }
.pm-layer-hdr { display: flex; align-items: center; gap: 4px; padding: 5px 7px 5px 5px; cursor: pointer; user-select: none; flex-wrap: wrap; border-left: 2px solid transparent; box-sizing: border-box; position: relative; border-radius: 4px 4px 0 0; }
.pm-layer-hdr:hover { background: #101026; }
.pm-layer-expanded .pm-layer-hdr { background: #101026; }
.pm-layer-chevron { font-size: 7px; color: #505070; flex-shrink: 0; width: 8px; }
.pm-layer-badge { font-size: 8px; font-weight: 700; background: rgba(0,0,0,0.35); border: 1px solid rgba(255,255,255,0.07); border-radius: 3px; padding: 1px 5px; flex-shrink: 0; font-family: monospace; }
.pm-layer-shot { flex: 1; min-width: 0; background: transparent; border: none; border-bottom: 1px dashed rgba(255,255,255,0.10); color: #a386ba; font-family: monospace; font-size: 12px; font-weight: 700; outline: none; padding: 1px 2px; cursor: text; user-select: text; -webkit-user-select: text; }
.pm-layer-shot:hover { border-bottom-color: rgba(255,255,255,0.28); background: rgba(255,255,255,0.02); }
.pm-layer-shot:focus { background: #0e0e1c; border-radius: 2px; border-bottom-color: currentColor; }
.pm-layer-shot.is-locked { border-bottom-style: solid; border-bottom-color: rgba(240,192,96,.4); color: #f0c060 !important; cursor: default; }
.pm-layer-shot.is-locked:hover,
.pm-layer-shot.is-locked:focus { background: transparent; border-radius: 0; }
.pm-shot-lock-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 22px; height: 22px; padding: 0;
  border-radius: 5px; border: 1px solid rgba(255,255,255,0.08);
  background: rgba(255,255,255,0.03); color: #6f7698;
  font-size: 12px; line-height: 1; cursor: pointer; flex-shrink: 0;
  transition: background .15s, border-color .15s, color .15s, transform .1s;
}
.pm-shot-lock-btn:hover { background: rgba(255,255,255,0.08); border-color: rgba(255,255,255,0.18); color: #cfd5f3; }
.pm-shot-lock-btn:active { transform: scale(0.96); }
.pm-shot-lock-btn.is-locked { background: rgba(180,120,20,.15); border-color: rgba(240,192,96,.3); color: #f0c060; }
.pm-shot-lock-btn.is-locked:hover { background: rgba(180,120,20,.24); border-color: rgba(240,192,96,.5); color: #ffd27a; }
.pm-layer-status { font-size: 7px; padding: 1px 5px; border-radius: 6px; border: 1px solid currentColor; background: transparent; cursor: pointer; text-transform: uppercase; letter-spacing: 0.06em; flex-shrink: 0; }
.pm-layer-del {
  font-size: 11px;
  font-weight: 900;
  color: #ffffff;
  background: linear-gradient(160deg, #ff6b6b 0%, #e52222 40%, #c00000 100%);
  box-shadow: inset 0 1px 2px rgba(255,255,255,0.45), inset 0 -2px 3px rgba(0,0,0,0.3), 0 2px 4px rgba(0,0,0,0.4);
  border: none;
  cursor: pointer;
  width: 20px;
  height: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 6px;
  text-shadow: 0 1px 2px rgba(0,0,0,0.35);
  transition: filter .12s, box-shadow .12s;
}
.pm-layer-del:hover {
  filter: brightness(1.15);
  box-shadow: inset 0 1px 2px rgba(255,255,255,0.5), inset 0 -2px 3px rgba(0,0,0,0.3), 0 3px 6px rgba(0,0,0,0.5);
}
.pm-layer-color-btn {
  width: 11px; height: 11px; border-radius: 50%; border: 1.5px solid rgba(255,255,255,0.25);
  padding: 0; cursor: pointer; flex-shrink: 0; transition: border-color 0.15s, transform 0.1s;
}
.pm-layer-color-btn:hover { border-color: rgba(255,255,255,0.7); transform: scale(1.2); }
.pm-layer-color-popup {
  display: flex; flex-direction: column;
  z-index: 99999;
  background: #1e2028; border: 1px solid rgba(255,255,255,0.1); border-radius: 6px;
  padding: 4px; box-shadow: 0 8px 24px rgba(0,0,0,0.7);
  min-width: 150px;
}
.pm-shot-input.is-locked { border-bottom-style: solid; border-bottom-color: rgba(240,192,96,.35); color: #f0c060 !important; cursor: default; }
.pm-shot-input.is-locked:hover,
.pm-shot-input.is-locked:focus { background: transparent; }
.pm-layer-color-swatch {
  display: flex; align-items: center; gap: 8px;
  width: 100%; background: none; border: none; border-radius: 4px;
  padding: 5px 8px; cursor: pointer; text-align: left;
  transition: background 0.1s;
}
.pm-layer-color-swatch:hover { background: rgba(255,255,255,0.08); }
.pm-layer-color-swatch.active { background: rgba(255,255,255,0.13); }
.pm-lcp-dot {
  width: 12px; height: 12px; border-radius: 50%; flex-shrink: 0;
  border: 1px solid rgba(255,255,255,0.2);
}
.pm-lcp-label { font-size: 11px; color: #c8ccd8; white-space: nowrap; }

/* Marker right-click context menu */
.pm-ctx-menu { position: fixed; z-index: 99998; background: #111120; border: 1px solid rgba(255,255,255,0.12); border-radius: 5px; padding: 3px; min-width: 148px; box-shadow: 0 6px 20px rgba(0,0,0,0.6); }
.pm-ctx-menu-item { display: block; width: 100%; text-align: left; background: none; border: none; color: #b0b0d0; font-size: 11px; padding: 5px 10px; border-radius: 3px; cursor: pointer; white-space: nowrap; }
.pm-ctx-menu-item:hover { background: rgba(255,255,255,0.07); color: #e0e0f0; }
.pm-ctx-menu-item.pm-ctx-menu-danger { color: #8a3a3a; }
.pm-ctx-menu-item.pm-ctx-menu-danger:hover { background: rgba(224,108,117,0.12); color: #E5484D; }
.pm-ctx-menu-sep { height: 1px; background: rgba(255,255,255,0.08); margin: 3px 0; }
.pm-layer-detail { padding: 5px 10px 8px 8px; display: grid; grid-template-columns: 148px minmax(0,0.82fr) minmax(0,1.18fr); gap: 4px 9px; border-top: 1px solid #14142a; align-items: start; min-width: 0; overflow: visible; }
.pm-layer-detail > * { min-width: 0; }
.pm-layer-detail-right { display: grid; grid-template-columns: minmax(0,1fr) 196px; gap: 4px 7px; min-width: 0; width: 100%; align-items: start; }
.pm-anno-inp-wrap { display: flex; flex-direction: column; gap: 1px; }
.pm-anno-inp-lbl { font-size: 7.5px; color: #a8a8c8; text-transform: uppercase; letter-spacing: 0.4px; line-height: 1.2; }
.pm-layer-note-col, .pm-layer-addl-col { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.pm-layer-note-col--tc { border-top: 1px solid #14142a; margin-top: 2px; padding-top: 2px; width: 100%; }
.pm-insp-anno-text { background: #06060e; border: 1px solid #1e1e36; border-radius: 3px; padding: 1px 4px; min-height: 0; max-height: 52px; overflow-y: auto; overflow-x: hidden; }
.pm-insp-anno-line { font-size: 9px; color: #c8d0f0; font-family: monospace; line-height: 1.45; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* ── Per-row + add marker button ──────────────────────────────────────────── */
.pm-col-mk-add { width: var(--pm-col-mk-add-w); text-align: right; white-space: nowrap; }
.pm-mk-add-btn { font-size: 10px; background: rgba(255,255,255,.04); border: 1px solid #4a4a6a; color: #9090c0; border-radius: 3px; cursor: pointer; padding: 0 5px; line-height: 1.5; font-weight: 700; }
.pm-mk-add-btn:hover { border-color: #2172E3; color: #2172E3; background: #1c1808; }

/* ── Row selected (marker inspector active) ──────────────────────────────── */
.pm-row-selected td { background: #10101e !important; }
.pm-row-selected td:first-child { border-left: 2px solid #a386ba; }

/* ── Layer thumbnail — tiny (in collapsed header row) ──────────────────── */
.pm-layer-thumb-xs { width: 34px; height: 20px; object-fit: contain; background: #000; border-radius: 2px; border: 1px solid #1a1a30; flex-shrink: 0; cursor: pointer; }
.pm-layer-thumb-xs-empty { display: inline-block; width: 34px; height: 20px; background: #0c0c1e; border: 1px dashed #1e1e38; border-radius: 2px; flex-shrink: 0; }

/* ── Layer thumbnail — small (in expanded detail, beside TC fields) ────── */
.pm-layer-thumb-wrap { position: relative; display: flex; flex-direction: column; gap: 5px; min-width: 0; overflow: visible; }
.pm-layer-thumb-full { display: block; width: 100%; max-width: 100%; height: auto; min-height: 76px; aspect-ratio: 16 / 9; object-fit: contain; border-radius: 4px; border: 1px solid #1e1e36; cursor: pointer; background: #000; flex-shrink: 0; }
.pm-layer-thumb-full:hover { border-color: #2172E3; }
.pm-layer-thumb-full-empty { display: flex; align-items: center; justify-content: center; width: 100%; max-width: 100%; height: auto; min-height: 76px; aspect-ratio: 16 / 9; background: #080818; border: 1px dashed #2a2a48; border-radius: 4px; }
.pm-layer-capture-btn { display: flex; flex-direction: column; align-items: center; gap: 3px; font-size: 7.5px; padding: 4px 6px; border: 1px solid #2a3a60; background: #0e1626; color: #2172E3; border-radius: 3px; cursor: pointer; text-align: center; }
.pm-layer-capture-btn:hover { background: #1a2a40; border-color: #4070b0; color: #a0d0ff; }
.pm-layer-capture-btn:disabled { opacity: 0.5; cursor: wait; }
.pm-layer-recapture { position: absolute; top: 2px; right: 2px; font-size: 9px; background: rgba(0,0,0,0.65); color: #8080a0; border: 1px solid #2a2a50; border-radius: 2px; padding: 0 4px; cursor: pointer; line-height: 1.6; z-index: 1; }
.pm-layer-recapture:hover { background: rgba(10,10,40,0.85); color: #2172E3; border-color: #2172E3; }
.pm-layer-thumb-status { font-size: 8px; color: #6080a0; text-align: center; padding: 2px 4px; }
.pm-layer-thumb-err { color: #E5484D; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-layer-tc-block { display: flex; flex-direction: column; gap: 3px; min-width: 0; background: linear-gradient(180deg, rgba(14,16,28,0.98), rgba(8,9,18,0.98)); border: 1px solid rgba(255,255,255,0.07); border-radius: 8px; padding: 5px 8px; min-height: 100%; box-sizing: border-box; overflow: hidden; }
.pm-layer-detail-right .pm-layer-addl-col { grid-column: 1 / -1; background: linear-gradient(180deg, rgba(14,16,28,0.98), rgba(8,9,18,0.98)); border: 1px solid rgba(255,255,255,0.07); border-radius: 8px; padding: 6px 8px; overflow: hidden; }

.pm-insp-vfx-flags--thumb { display: flex; flex-direction: row; gap: 4px; flex-wrap: wrap; }
.pm-insp-vfx-flags--thumb .pm-vfx-flag { justify-content: center; flex: 1 1 0; min-height: 20px; padding: 1px 6px; border-radius: 4px; font-size: 7.5px; }

/* Conform mode: skipped rows */
.pm-row-skipped { opacity: 0.32; pointer-events: none; cursor: default; }
.pm-row-skipped td { color: #40405a !important; }
.pm-row-skipped .pm-dot { filter: grayscale(1) brightness(0.4); }

/* Disabled clips (disabled:true from parser — clip is muted/disabled in timeline) */
.pm-row-disabled-clip { opacity: 0.38; pointer-events: none; cursor: default; }
.pm-row-disabled-clip td { color: #55556a !important; }
.pm-row-disabled-clip .pm-dot { filter: grayscale(1) brightness(0.45); }
.pm-dis-badge {
  display: inline-block;
  margin-left: 5px;
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #7a7a9a;
  background: #111120;
  border: 1px solid #2a2a40;
  border-radius: 3px;
  padding: 0 3px;
  vertical-align: middle;
  user-select: none;
}

.pm-skip-badge {
  display: inline-block;
  margin-left: 5px;
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #E5484D;
  background: #1c0a0c;
  border: 1px solid #3a1a1e;
  border-radius: 3px;
  padding: 0 3px;
  vertical-align: middle;
  text-transform: uppercase;
}

/* Needs-OCR: event has a VFX marker but no confirmed shot name. We surface
   this instead of silently showing the raw camera clip name as a real name. */
.pm-needs-ocr-badge {
  display: inline-block;
  margin-left: 6px;
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #E0A215;
  background: #1e1706;
  border: 1px solid #3a2e0e;
  border-radius: 3px;
  padding: 0 3px;
  vertical-align: middle;
  text-transform: uppercase;
  cursor: help;
}
.pm-row-needs-ocr .pm-shot-input::placeholder { color: #b8891e; opacity: 0.85; }

/* CornerCut-style CONFORM_ANALYSIS badge for .prproj events */
.pm-pp-badge {
  display: inline-block;
  margin-left: 4px;
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.15em;
  color: #0a0c14;
  background: #84d4ff;
  border-radius: 2px;
  padding: 0 3px;
  vertical-align: middle;
  text-transform: uppercase;
  cursor: help;
  font-family: 'Courier New', monospace;
}
.pm-pp-badge:hover {
  background: #aae4ff;
}

/* ── Timeline strip — 240px grid row, never collapses ── */
.pm-timeline-strip {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-height: 0;
  align-self: stretch;
  border-top: 2px solid #1e1e3e;
  background: #0a0a1c;
}
.pm-tl-hdr {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 10px;
  border-bottom: 1px solid #141428;
  flex-shrink: 0;
}
.pm-tl-label {
  font-size: 8px;
  font-weight: 800;
  color: #606088;
  letter-spacing: .10em;
  text-transform: uppercase;
}
.pm-cov-stats {
  font-size: 8px;
  color: #2a2a42;
}

/* ── Pro timeline control bar ── */
.pm-tl-ctrl-bar {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  background: #090914;
  border-bottom: 1px solid #141428;
  flex-shrink: 0;
  min-height: 26px;
}
.pm-tl-group {
  display: flex;
  align-items: center;
  gap: 1px;
}
.pm-tl-sep {
  width: 1px;
  height: 14px;
  background: #1e1e36;
  margin: 0 4px;
  flex-shrink: 0;
}
/* Base icon button */
.pm-tl-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 2px 5px;
  min-width: 20px;
  min-height: 20px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #8888b0;
  background: rgba(255,255,255,.04);
  border: 1px solid #3a3a55;
  border-radius: 3px;
  cursor: pointer;
  transition: color 0.1s, background 0.1s, border-color 0.1s;
  white-space: nowrap;
  line-height: 1;
}
.pm-tl-btn:hover {
  color: #d0d0f0;
  background: #131325;
  border-color: #5050a0;
}
.pm-tl-btn:active {
  color: #2172E3;
  background: #1a1828;
}
/* Burn-In button — distinct accent color */
#pmTlBurninBtn {
  color: #f5a623;
  background: rgba(245,166,35,.10);
  border-color: rgba(245,166,35,.35);
}
#pmTlBurninBtn:hover {
  color: #ffc34d;
  background: rgba(245,166,35,.20);
  border-color: rgba(245,166,35,.65);
  box-shadow: 0 0 6px rgba(245,166,35,.25);
}
#pmTlBurninBtn:active {
  color: #ffe0a0;
  background: rgba(245,166,35,.30);
}
/* Small text variant (zoom +/-) */
.pm-tl-btn-sm {
  min-width: 16px;
  padding: 1px 4px;
  font-size: 11px;
  font-weight: 400;
}
/* Toggle button — off state */
.pm-tl-toggle {
  color: #6868a0;
  border-color: #2a2a42;
}
.pm-tl-toggle:hover {
  color: #9898c0;
  border-color: #3a3a58;
  background: #0f0f1e;
}
/* Toggle button — ON state */
.pm-tl-toggle[data-active="true"],
.pm-tl-toggle.pm-tl-toggle-on {
  color: #2172E3;
  background: #1a1710;
  border-color: #3a3010;
}
.pm-tl-toggle[data-active="true"]:hover,
.pm-tl-toggle.pm-tl-toggle-on:hover {
  color: #ffd966;
  background: #201c0e;
  border-color: #4a4014;
}
/* iPACK density badge */
.pm-ipack-density {
  display: inline-block;
  margin-left: 3px;
  font-size: 7px;
  font-family: "SF Mono", ui-monospace, monospace;
  color: #0AA356;
  vertical-align: middle;
  min-width: 0;
}
#pmTlIPackBtn[data-active="true"] { color: #56b6c2; background: #071518; border-color: #56b6c2; }
#pmTlIPackBtn[data-active="true"]:hover { color: #7ed6e8; background: #0a1c1f; border-color: #7ed6e8; }
/* Zoom slider */
.pm-tl-zoom-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 72px;
  height: 3px;
  background: #1e1e36;
  border-radius: 2px;
  outline: none;
  cursor: pointer;
  accent-color: #2172E3;
}
.pm-tl-zoom-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #2172E3;
  cursor: pointer;
}
.pm-tl-zoom-slider::-moz-range-thumb {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #2172E3;
  border: none;
  cursor: pointer;
}
/* Zoom percentage display */
.pm-tl-zoom-pct {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  padding: 1px 4px;
  font-size: 8px;
  font-family: monospace;
  font-weight: 700;
  color: #8080a8;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 3px;
  cursor: pointer;
  transition: color 0.1s, border-color 0.1s;
  white-space: nowrap;
}
.pm-tl-zoom-pct:hover {
  color: #2172E3;
  border-color: #2a2840;
}
/* Far-right label pushed by flex */
.pm-tl-label-inline {
  margin-left: auto;
  font-size: 8px;
  font-weight: 800;
  color: #303050;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  padding-right: 4px;
}
.pm-tl-wrap {
  flex: 1 1 0;
  overflow: hidden;
  min-height: 0;
  position: relative;
}
.pm-tl-canvas {
  position: absolute;
  inset: 0;
  display: block;
  cursor: crosshair;
  background: #0a0a1c;
  user-select: none;
  transform: translateZ(0);
  backface-visibility: hidden;
  will-change: contents;
}

/* Timeline zoom buttons */
.pm-tl-zoom-btn {
  padding: 1px 6px;
  font-size: 9px;
  font-family: monospace;
  font-weight: 700;
  background: rgba(255,255,255,.04);
  border: 1px solid #3a3a55;
  color: #8888b0;
  cursor: pointer;
  border-radius: 3px;
  margin-left: 3px;
  transition: color 0.1s, border-color 0.1s;
}
.pm-tl-zoom-btn:hover {
  color: #2172E3;
  border-color: #2172E3;
}

/* ── Quick Settings row (Prep & Mark) ── */
.pm-qs-row {
  display: flex;
  align-items: stretch;
  gap: 3px;
  padding: 4px 8px;
  background: #0b0b18;
  border-bottom: 1px solid #15152a;
  flex-shrink: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.pm-qs-row::-webkit-scrollbar { display: none; }

.pm-qs-btn {
  appearance: none;
  font: inherit;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 44px;
  padding: 3px 6px;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: #9090b8;
  background: rgba(255,255,255,.05);
  border: 1px solid #3a3a52;
  border-radius: 4px;
  cursor: pointer;
  position: relative;
  white-space: nowrap;
  transition: color 0.12s, border-color 0.12s, background 0.12s;
}
.pm-qs-btn .bar {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  border-radius: 2px 2px 0 0;
  background: currentColor;
  opacity: 0;
  transition: opacity 0.12s;
}
.pm-qs-btn svg { width: 12px; height: 12px; flex-shrink: 0; }
.pm-qs-btn.wide { min-width: 62px; }

/* Active state — inherit theme colours from Pull Prep qs-btn themes */
.pm-qs-btn.active                { background: #111128; }
.pm-qs-btn.active .bar           { opacity: 1; }
.pm-qs-btn.active.theme-edl      { color: #98e0d2; border-color: #98e0d2; }
.pm-qs-btn.active.theme-q1       { color: #a386ba; border-color: #a386ba; }
.pm-qs-btn.active.theme-q2       { color: #2172E3; border-color: #2172E3; }
.pm-qs-btn.active.theme-q3       { color: #E0B341; border-color: #E0B341; }
.pm-qs-btn.active.theme-amf      { color: #56b6c2; border-color: #56b6c2; }
.pm-qs-btn.active.theme-danger   { color: #E5484D; border-color: #E5484D; }

.pm-qs-btn:hover:not(.active)    { color: #b0b0d0; border-color: #3a3a58; }

/* ── Modifier buttons: always hidden until Options toggle is on ── */
.pm-qs-btn[data-modes] { display: none; }
#pmQsRow.pm-qs-expanded .pm-qs-btn[data-modes] { display: inline-flex; }

/* ── Options toggle button ── */
.pm-qs-options-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border: 1px solid #2a2a44;
  border-radius: 5px;
  background: transparent;
  color: #5a5a80;
  cursor: pointer;
  transition: color .14s, border-color .14s, background .14s;
  padding: 0;
}
.pm-qs-options-btn:hover { color: #9090c0; border-color: #4a4a70; background: #1a1a30; }
#pmQsRow.pm-qs-expanded .pm-qs-options-btn {
  color: #c0c0ff;
  border-color: #6060a0;
  background: #1a1a38;
}
#pmQsRow.pm-qs-expanded .pm-qs-options-btn svg {
  transform: rotate(45deg);
}

/* ── QS row separator ── */
.pm-qs-sep {
  width: 1px;
  background: #2a2a44;
  margin: 2px 3px;
  flex-shrink: 0;
  align-self: stretch;
}

/* ── Import mode toggle pill: SCRIPTED / UNSCRIPTED ── */
.pm-im-toggle {
  display: flex;
  align-items: stretch;
  flex-shrink: 0;
  border-radius: 5px;
  overflow: hidden;
  border: 1px solid #2e2e4a;
  background: #0d0d1e;
}
.pm-im-opt {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 9px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  white-space: nowrap;
  cursor: pointer;
  color: #50507a;
  background: transparent;
  border: none;
  transition: color 0.14s, background 0.14s;
}
.pm-im-opt svg { width: 11px; height: 11px; flex-shrink: 0; }
.pm-im-opt:first-child { border-right: 1px solid #2e2e4a; }

/* Active: SCRIPTED → teal pill */
.pm-im-scripted.active {
  color: #539c95;
  background: rgba(86,212,200,0.13);
}
/* Active: UNSCRIPTED → amber pill */
.pm-im-unscripted.active {
  color: #e5a84a;
  background: rgba(229,168,74,0.13);
}
.pm-im-opt:not(.active):hover { color: #9090b8; background: rgba(255,255,255,0.04); }


/* ── Left panel drop-zone empty state ── */
.pm-drop-hint {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: #7070a0;
  font-size: 10px;
  background: #070718;
  border: 1px dashed #28284a;
  pointer-events: none;
  user-select: none;
}
.pm-drop-hint button { pointer-events: all; }
.pm-drop-hint svg { opacity: 0.5; }
.pm-drop-hint-title {
  font-size: 11px;
  font-weight: 500;
  color: #8080b8;
  letter-spacing: 0.05em;
}
.pm-drop-hint-sub {
  font-size: 9px;
  color: #6060a0;
}

/* Drag-over states */
.pm-left.pm-drag-over .pm-event-scroll,
.pm-left.pm-drag-over { outline: 2px dashed #2172E3; outline-offset: -2px; background: rgba(214,163,58,.04); }
.pm-left.pm-drag-over .pm-drop-hint { border-color: #2172E3; color: #2172E3; }
.pm-player-wrap.pm-drag-over { outline: 2px dashed #2172E3; outline-offset: -2px; }
.pm-player-wrap.pm-drag-over::after {
  content: 'Drop to import';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: #2172E3;
  background: rgba(5,5,16,.65);
  pointer-events: none;
}
/* ── Subtitle overlay in video player ──────────────────────────────────── */
.pm-sub-overlay {
  position: absolute;
  bottom: 14px;
  left: 0; right: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 0 20px;
  pointer-events: none;
  z-index: 6;
}
.pm-sub-line {
  max-width: 92%;
  padding: 3px 10px;
  border-radius: 3px;
  background: rgba(0,0,0,0.75);
  font-family: "SF Mono", ui-monospace, monospace;
  font-size: 11px;
  line-height: 1.4;
  text-align: center;
  white-space: pre-wrap;
  word-break: break-word;
}
.pm-sub-line.pm-sub-shot {
  color: #f5e89a;
  font-weight: 700;
  font-size: 11.5px;
  letter-spacing: 0.03em;
}
.pm-sub-line.pm-sub-note { color: #c8c8ff; }
.pm-sub-line.pm-sub-add  { color: #a8c8e8; font-size: 10px; }

.pm-tl-wrap.pm-drag-over { outline: 2px dashed #2172E3; outline-offset: -2px; }
.pm-tl-wrap.pm-drag-over::after {
  content: 'Drop timeline file here';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #2172E3;
  background: rgba(5,5,16,.72);
  pointer-events: none;
  z-index: 10;
  letter-spacing: 0.06em;
}
.pm-vid-import-btn { flex-shrink: 0; }

/* ── Timeline info rail ─────────────────────────────────────────────────────── */
.pm-tl-info-rail {
  display: flex;
  align-items: stretch;
  flex-shrink: 0;
  min-height: 26px;
  background: #06060e;
  border-top: 1px solid #13132a;
  padding: 0 10px;
  font-family: "SF Mono", ui-monospace, monospace;
  font-size: 9.5px;
  overflow: hidden;
}
/* Idle state */
.pm-tl-ir-idle {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  flex-wrap: nowrap;
  min-width: 0;
}
.pm-tl-ir-stat { color: #505070; white-space: nowrap; }
.pm-tl-ir-stat strong { font-weight: 700; color: #9898c0; }
.pm-tl-ir-dot { color: #222238; flex-shrink: 0; }
.pm-tl-ir-skip strong { color: #f08090; }
.pm-tl-ir-skip { color: #904050; }
.pm-tl-ir-mk strong { color: #c888e8; }
.pm-tl-ir-mk { color: #704090; }
.pm-tl-ir-spacer { flex: 1 1 0; min-width: 8px; }
.pm-tl-ir-rm-all-mk {
  flex: 0 0 auto;
  padding: 2px 8px;
  border-radius: 4px;
  border: 1px solid rgba(200,100,240,.25);
  background: rgba(180,80,220,.06);
  color: rgba(190,120,240,.65);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: .03em;
  cursor: pointer;
  white-space: nowrap;
  transition: background .12s, border-color .12s, color .12s;
}
.pm-tl-ir-rm-all-mk:hover {
  background: rgba(200,80,240,.14);
  border-color: rgba(210,100,255,.45);
  color: #d48cf8;
}
.pm-tl-ir-rm-all-mk--confirm {
  background: rgba(220,60,60,.14) !important;
  border-color: rgba(255,80,80,.45) !important;
  color: #ff9999 !important;
  animation: pm-ir-rmall-pulse 0.6s ease infinite alternate;
}
@keyframes pm-ir-rmall-pulse {
  from { box-shadow: 0 0 0 0 rgba(220,60,60,0); }
  to   { box-shadow: 0 0 0 3px rgba(220,60,60,.2); }
}
/* Legend */
.pm-tl-ir-legend {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-shrink: 0;
  padding-left: 10px;
  border-left: 1px solid #13132a;
}
.pm-tl-ir-lgnd-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 8.5px;
  color: #383858;
  white-space: nowrap;
}
.pm-tl-ir-lgnd-sep { width: 1px; height: 10px; background: #13132a; }
.pm-tl-ir-lgnd-sw  { display: inline-block; width: 18px; height: 8px; border-radius: 2px; flex-shrink: 0; }
.pm-tl-ir-sw-noncf { background: #181820; background-image: repeating-linear-gradient(135deg, transparent, transparent 2px, #2d2d3e 2px, #2d2d3e 3px); border: 1px solid #24243a; }
.pm-tl-ir-sw-speed { background: linear-gradient(180deg, #181820 55%, rgba(214,163,58,0.55) 55%); border: 1px solid rgba(214,163,58,0.25); }
.pm-tl-ir-sw-resize { background: linear-gradient(180deg, rgba(180,110,234,0.55) 30%, #181820 30%); border: 1px solid rgba(180,110,234,0.25); }
.pm-tl-ir-sw-mk    { background: #3db83d; border: 1px solid rgba(61,184,61,0.40); }
/* Selected clip detail */
.pm-tl-ir-detail {
  display: flex;
  align-items: center;
  gap: 0;
  width: 100%;
  flex-wrap: nowrap;
  min-width: 0;
  overflow: hidden;
}
.pm-tl-ir-clip-name {
  font-size: 11px;
  font-weight: 700;
  color: #e0e0ff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 220px;
  flex-shrink: 1;
}
.pm-tl-ir-field {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  margin-left: 14px;
  flex-shrink: 0;
}
.pm-tl-ir-field-lbl { font-size: 7.5px; color: #333358; text-transform: uppercase; letter-spacing: 0.09em; }
.pm-tl-ir-field-val { font-size: 9.5px; color: #9898c8; }
.pm-tl-ir-badge {
  display: inline-block;
  border-radius: 3px;
  padding: 1px 6px;
  font-size: 8px;
  font-weight: 700;
  flex-shrink: 0;
  margin-right: 6px;
}
.pm-tl-ir-badge-track { color: #539c95; background: rgba(86,212,200,0.10); border: 1px solid rgba(86,212,200,0.22); }
.pm-tl-ir-badge-skip  { color: #E5484D; background: rgba(224,108,117,0.10); border: 1px solid rgba(224,108,117,0.22); }
/* Speed type badges in info rail */
.pm-tl-ir-badge-speed-slow { color: #ffd050; background: rgba(214,163,58,0.12); border: 1px solid rgba(214,163,58,0.28); }
.pm-tl-ir-badge-speed-fast { color: #ffaa50; background: rgba(245,120,40,0.12); border: 1px solid rgba(245,120,40,0.28); }
.pm-tl-ir-badge-speed-frz  { color: #f08080; background: rgba(224,80,80,0.12);  border: 1px solid rgba(224,80,80,0.28); }
.pm-tl-ir-badge-speed-rev  { color: #90c8ff; background: rgba(80,160,245,0.12); border: 1px solid rgba(80,160,245,0.28); }
.pm-tl-ir-badge-speed-var  { color: #ffcc60; background: rgba(255,180,30,0.12); border: 1px solid rgba(255,180,30,0.28); }
/* Speed value in info rail fields */
.pm-tl-ir-speed-val  { color: #ffc840 !important; font-weight: 700; }
.pm-tl-ir-field-dim  { color: #383858; font-size: 8.5px; }

/* ── Annotation system ─────────────────────────────────────────────────────── */
.pm-annot-btn {
  font-size: 11px !important;
  color: #9898b8 !important;
  border-color: #1e1e2e !important;
  background: #111118 !important;
  transition: color .1s, border-color .1s, background .1s;
}
.pm-annot-btn.active {
  color: #E5484D !important;
  border-color: #7a2030 !important;
  background: #1c0810 !important;
}
.pm-annot-canvas {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  pointer-events: none;
  z-index: 2;
  touch-action: none;
  transform: translateZ(0);
  backface-visibility: hidden;
  will-change: contents;
}
.pm-burnin-canvas {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  pointer-events: none;
  z-index: 5;
}

/* ── Quick Annotate toolbar + draw canvas ───────────────────────────────────── */
.pm-qa-canvas {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  z-index: 8;
  pointer-events: auto;
  cursor: crosshair;
  touch-action: none;
}
.pm-qa-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 22;
  display: flex;
  flex-direction: column;
  background: rgba(6, 7, 16, 0.88);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,.10);
}
.pm-qa-row {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 10px;
  height: 40px;
}
.pm-qa-row--tools {
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.pm-qa-row--meta {
  height: 36px;
}
.pm-qa-spacer {
  flex: 1;
}
.pm-qa-k {
  font-size: 10px;
  color: rgba(255,255,255,.38);
  white-space: nowrap;
  letter-spacing: .03em;
  flex-shrink: 0;
}
.pm-qa-select {
  height: 26px;
  padding: 0 6px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 5px;
  color: rgba(255,255,255,.8);
  font-size: 11px;
  cursor: pointer;
  outline: none;
  flex-shrink: 0;
  max-width: 180px;
}
.pm-qa-select:focus { border-color: rgba(84,213,255,.45); }
.pm-qa-input {
  height: 26px;
  padding: 0 8px;
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 5px;
  color: rgba(255,255,255,.85);
  font-size: 11px;
  outline: none;
  flex-shrink: 0;
  width: 120px;
}
.pm-qa-input--note {
  flex: 1;
  width: auto;
  min-width: 80px;
  max-width: 240px;
}
.pm-qa-input:focus { border-color: rgba(84,213,255,.45); }
.pm-qa-track-btn {
  gap: 4px;
}
.pm-qa-track-btn:disabled {
  opacity: 0.4;
  cursor: default;
}
.pm-qa-track-status {
  font-size: 10px;
  color: rgba(84,213,255,.8);
  flex-shrink: 0;
  padding: 0 6px;
  border-radius: 4px;
  background: rgba(84,213,255,.1);
  border: 1px solid rgba(84,213,255,.2);
  height: 22px;
  display: flex;
  align-items: center;
}
.pm-qa-tools {
  display: flex;
  gap: 2px;
}
.pm-qa-tool {
  width: 28px; height: 28px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 5px;
  color: rgba(255,255,255,.6);
  cursor: pointer;
  padding: 0;
  transition: background .1s, border-color .1s, color .1s;
  flex-shrink: 0;
}
.pm-qa-tool:hover { background: rgba(255,255,255,.13); color: #fff; }
.pm-qa-tool.is-active {
  background: rgba(214,163,58,.18);
  border-color: rgba(214,163,58,.6);
  color: #2172E3;
}
.pm-qa-tool svg {
  width: 13px; height: 13px;
  display: block;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.pm-qa-sep {
  width: 1px;
  height: 20px;
  background: rgba(255,255,255,.12);
  flex-shrink: 0;
  margin: 0 3px;
}
.pm-qa-colors {
  display: flex;
  gap: 4px;
}
.pm-qa-color {
  width: 16px; height: 16px;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,.2);
  cursor: pointer;
  padding: 0;
  flex-shrink: 0;
  transition: transform .1s, border-color .1s;
}
.pm-qa-color:hover { transform: scale(1.2); }
.pm-qa-color.is-active {
  border-color: #fff;
  transform: scale(1.15);
  box-shadow: 0 0 0 1px rgba(0,0,0,.5);
}
.pm-qa-size-wrap {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pm-qa-size-icon {
  width: 12px; height: 12px;
  flex-shrink: 0;
  color: rgba(255,255,255,.4);
}
.pm-qa-size {
  -webkit-appearance: none;
  appearance: none;
  width: 72px;
  height: 3px;
  background: rgba(255,255,255,.2);
  border-radius: 2px;
  outline: none;
  cursor: pointer;
}
.pm-qa-size::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 12px; height: 12px;
  border-radius: 50%;
  background: #2172E3;
  border: none;
  cursor: pointer;
}
.pm-qa-size::-moz-range-thumb {
  width: 12px; height: 12px;
  border-radius: 50%;
  background: #2172E3;
  border: none;
  cursor: pointer;
}
.pm-qa-act {
  height: 28px;
  display: flex; align-items: center; justify-content: center; gap: 4px;
  padding: 0 8px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 5px;
  color: rgba(255,255,255,.65);
  font-size: 10px;
  cursor: pointer;
  white-space: nowrap;
  transition: background .1s, color .1s;
  flex-shrink: 0;
}
.pm-qa-act:hover { background: rgba(255,255,255,.13); color: #fff; }
.pm-qa-act svg {
  width: 12px; height: 12px;
  display: block;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}
.pm-qa-save {
  background: rgba(214,163,58,.15);
  border-color: rgba(214,163,58,.4);
  color: #2172E3;
}
.pm-qa-save:hover { background: rgba(214,163,58,.28); color: #ffe082; }
.pm-qa-cancel { color: rgba(255,100,100,.7); border-color: rgba(255,100,100,.25); }
.pm-qa-cancel:hover { background: rgba(255,80,80,.12); color: #ff8080; }
/* ── Fullscreen inspector overlay ──────────────────────────────────────────── */
.pm-fs-insp-overlay {
  position: absolute;
  left: 10px;
  right: 10px;
  bottom: 58px; /* above playback controls */
  z-index: 25;
  max-height: 52%;
  overflow-y: auto;
  pointer-events: auto;
  /* translucent panel */
  background: rgba(8, 9, 20, 0.72);
  backdrop-filter: blur(12px) saturate(1.4);
  -webkit-backdrop-filter: blur(12px) saturate(1.4);
  border: 1px solid rgba(255,255,255,.10);
  border-radius: 8px;
  box-shadow: 0 8px 32px rgba(0,0,0,.55);
  /* animate in */
  animation: pmFsInspIn .18s ease;
}
@keyframes pmFsInspIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
/* Strip card background since the overlay already has a bg */
.pm-fs-insp-overlay .pm-insp-layers,
.pm-fs-insp-overlay .pm-layers-list {
  background: transparent;
}
.pm-fs-insp-overlay .pm-layer-row {
  background: transparent;
  border-color: rgba(255,255,255,.07);
}
.pm-fs-insp-overlay .pm-layer-hdr {
  background: rgba(255,255,255,.04);
}
.pm-fs-insp-overlay .pm-layer-detail {
  background: transparent;
}
/* Hide non-expanded rows in fullscreen overlay — only show expanded card */
.pm-fs-insp-overlay .pm-layer-row:not(.pm-layer-expanded) {
  display: none;
}
/* Inspector when repositioned into fullscreen overlay */
.pm-inspector--fs {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  max-height: none !important;
  overflow: visible !important;
}
/* ── Video overlay controls (brightness + fullscreen) ───────────────────────── */
.pm-vid-overlay-ctrl {
  position: absolute;
  bottom: 8px;
  right: 8px;
  display: flex;
  align-items: center;
  gap: 4px;
  z-index: 30;
  opacity: 0;
  transition: opacity .18s ease;
}
.pm-player-wrap:hover .pm-vid-overlay-ctrl,
.pm-vid-overlay-ctrl:focus-within {
  opacity: 1;
}
.pm-vid-ctrl-btn {
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,.55);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 5px;
  color: rgba(255,255,255,.8);
  cursor: pointer;
  padding: 0;
  flex-shrink: 0;
  transition: background .12s, border-color .12s, color .12s;
}
.pm-vid-ctrl-btn:hover {
  background: rgba(0,0,0,.75);
  border-color: rgba(255,255,255,.35);
  color: #fff;
}
.pm-vid-ctrl-btn.is-active {
  background: rgba(214,163,58,.18);
  border-color: rgba(214,163,58,.6);
  color: #2172E3;
}
.pm-vid-ctrl-btn svg {
  display: block;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.pm-vid-bright-wrap {
  position: relative;
}
.pm-vid-bright-popup {
  position: absolute;
  bottom: 32px;
  right: 0;
  background: #181c23;
  border: 1px solid rgba(255,255,255,.13);
  border-radius: 7px;
  padding: 10px 11px 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: 0 4px 18px rgba(0,0,0,.5);
  min-width: 170px;
  z-index: 50;
}
.pm-vid-bright-row {
  display: flex;
  align-items: center;
  gap: 6px;
}
.pm-vid-bright-row svg {
  flex-shrink: 0;
  stroke: rgba(255,255,255,.45);
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.pm-vid-bright-slider {
  flex: 1;
  -webkit-appearance: none;
  appearance: none;
  height: 3px;
  background: rgba(255,255,255,.18);
  border-radius: 2px;
  outline: none;
  cursor: pointer;
}
.pm-vid-bright-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #2172E3;
  border: none;
  cursor: pointer;
}
.pm-vid-bright-slider::-moz-range-thumb {
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #2172E3;
  border: none;
  cursor: pointer;
}
.pm-vid-bright-val-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}
.pm-vid-bright-pct {
  font-family: monospace;
  font-size: 11px;
  color: rgba(255,255,255,.65);
  min-width: 36px;
}
.pm-vid-bright-reset {
  font-size: 10px;
  padding: 2px 6px;
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.13);
  border-radius: 4px;
  color: rgba(255,255,255,.5);
  cursor: pointer;
  transition: background .1s, color .1s;
}
.pm-vid-bright-reset:hover {
  background: rgba(255,255,255,.13);
  color: rgba(255,255,255,.85);
}
/* Fullscreen mode adjustments */
#pmPlayerWrap:-webkit-full-screen .pm-vid-overlay-ctrl,
#pmPlayerWrap:fullscreen .pm-vid-overlay-ctrl {
  opacity: 1;
  bottom: 14px;
  right: 14px;
}

/* ── QT Burn-In Setup modal ─────────────────────────────────────────────────── */
.pm-burnin-modal {
  position: fixed;
  inset: 0;
  z-index: 99998;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: pmBurninFadeIn .18s ease;
  background: rgba(0,4,12,0.28);
  backdrop-filter: blur(2px);
}
@keyframes pmBurninFadeIn {
  from { opacity: 0; transform: scale(.97); }
  to   { opacity: 1; transform: scale(1); }
}
.pm-burnin-dialog {
  width: min(1380px, 97vw);
  max-height: 94vh;
  display: flex;
  flex-direction: column;
  background: rgba(12,22,50,0.38);
  backdrop-filter: blur(28px) saturate(1.6);
  -webkit-backdrop-filter: blur(28px) saturate(1.6);
  border: 1px solid rgba(160,200,255,.18);
  border-radius: 18px;
  box-shadow: 0 24px 64px rgba(0,0,0,.55), 0 0 0 1px rgba(255,255,255,.08) inset;
  overflow: hidden;
  font: 12px "SF Mono", ui-monospace, monospace;
  color: #e4eeff;
}

/* ── Header ── */
.pm-burnin-head {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 20px 10px;
  background: linear-gradient(180deg, rgba(255,255,255,.06) 0%, rgba(255,255,255,.03) 100%);
  border-bottom: 1px solid rgba(160,200,255,.12);
  box-shadow: 0 1px 0 rgba(0,0,0,.35);
}
.pm-burnin-title {
  font-size: 14px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: .3px;
  text-shadow: 0 1px 8px rgba(0,30,80,.8);
}
.pm-burnin-sub {
  margin-top: 2px;
  font-size: 10.5px;
  color: rgba(180,210,255,.8);
  line-height: 1.4;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  text-shadow: 0 1px 4px rgba(0,0,0,.6);
}
.pm-burnin-close {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.08);
  color: rgba(180,200,240,.6);
  font-size: 13px;
  cursor: pointer;
  border-radius: 8px;
  transition: background .12s, color .12s, border-color .12s;
  flex-shrink: 0;
}
.pm-burnin-close:hover { background: rgba(255,80,80,.18); border-color: rgba(255,80,80,.35); color: #ff8888; }

/* ── Grid ── */
.pm-burnin-grid {
  flex: 1 1 auto;
  display: flex;
  gap: 0;
  overflow: hidden;
}

/* ── Field list ── */
.pm-burnin-fields {
  flex: 0 0 400px;
  overflow-y: auto;
  padding: 4px 10px 8px;
  background: rgba(0,0,0,.82);
  border-right: 1px solid rgba(160,200,255,.1);
  display: flex;
  flex-direction: column;
  gap: 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(58,130,247,.25) transparent;
}
.pm-burnin-fields::-webkit-scrollbar { width: 4px; }
.pm-burnin-fields::-webkit-scrollbar-thumb { background: rgba(58,130,247,.3); border-radius: 2px; }

/* ── Preset bar ── */
.pm-burnin-presets-bar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  background: rgba(4,10,24,.6);
  border-bottom: 1px solid rgba(58,130,247,.10);
}
.pm-burnin-presets-label {
  flex: 0 0 auto;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: .9px;
  text-transform: uppercase;
  color: rgba(130,165,220,.72);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.pm-burnin-preset-select {
  flex: 1 1 auto;
  min-width: 0;
  background: rgba(10,18,40,.85);
  border: 1px solid rgba(58,130,247,.2);
  border-radius: 6px;
  color: #aaccee;
  font: 500 10.5px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  padding: 3px 6px;
  cursor: pointer;
  transition: border-color .12s;
}
.pm-burnin-preset-select:focus { outline: none; border-color: #3a82f7; }
.pm-burnin-preset-btn {
  flex: 0 0 auto;
  padding: 3px 9px;
  font: 600 10px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: rgba(58,130,247,.10);
  border: 1px solid rgba(58,130,247,.22);
  border-radius: 6px;
  color: #7aaae8;
  cursor: pointer;
  white-space: nowrap;
  transition: background .12s, border-color .12s, color .12s;
}
.pm-burnin-preset-btn:hover { background: rgba(58,130,247,.22); border-color: #3a82f7; color: #b0d4ff; }
.pm-burnin-preset-btn-save { color: #6ada9e; border-color: rgba(80,200,120,.25); background: rgba(80,200,120,.08); }
.pm-burnin-preset-btn-save:hover { background: rgba(80,200,120,.18); border-color: rgba(80,200,120,.5); color: #a0ffcc; }
.pm-burnin-preset-btn-del { color: rgba(255,100,100,.7); border-color: rgba(255,80,80,.2); background: rgba(255,60,60,.06); }
.pm-burnin-preset-btn-del:hover { background: rgba(255,60,60,.16); border-color: rgba(255,80,80,.45); color: #ff9999; }

.pm-burnin-row {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 8px;
  border-radius: 7px;
  cursor: pointer;
  user-select: none;
  border: 1px solid transparent;
  transition: background .1s, border-color .1s;
}
.pm-burnin-row:hover {
  background: rgba(160,200,255,.08);
  border-color: rgba(160,200,255,.16);
}
.pm-burnin-row:has(input:checked) {
  background: rgba(58,130,247,.12);
  border-color: rgba(58,130,247,.24);
}
.pm-burnin-row:has(input:checked):hover {
  background: rgba(58,130,247,.18);
  border-color: rgba(58,130,247,.35);
}

/* Custom checkbox toggle */
.pm-burnin-row-toggle { flex: 0 0 auto; }
.pm-burnin-row-toggle input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 28px;
  height: 16px;
  border-radius: 8px;
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.15);
  cursor: pointer;
  position: relative;
  transition: background .15s, border-color .15s;
  flex-shrink: 0;
}
.pm-burnin-row-toggle input[type="checkbox"]::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,.5);
  transition: transform .15s, background .15s;
}
.pm-burnin-row-toggle input[type="checkbox"]:checked {
  background: #3a82f7;
  border-color: #5a9aff;
}
.pm-burnin-row-toggle input[type="checkbox"]:checked::after {
  transform: translateX(12px);
  background: #fff;
}

.pm-burnin-row-copy {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
}
.pm-burnin-row-label {
  display: block;
  font-weight: 600;
  color: #e8f0ff;
  font-size: 11.5px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  text-shadow: 0 1px 4px rgba(0,0,0,.8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: .01em;
}
.pm-burnin-row:not(:has(input:checked)) .pm-burnin-row-label {
  color: rgba(190,210,255,.62);
  font-weight: 500;
  text-shadow: none;
}
.pm-burnin-row-hint {
  display: block;
  font-size: 10px;
  color: rgba(160,190,230,.68);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: .01em;
}
.pm-burnin-row:not(:has(input:checked)) .pm-burnin-row-hint { color: rgba(140,170,215,.45); }
.pm-burnin-customtext-input {
  display: block;
  width: 100%;
  margin-top: 3px;
  padding: 3px 6px;
  background: rgba(0,0,0,.3);
  border: 1px solid rgba(160,200,255,.2);
  border-radius: 4px;
  color: #c8d8f0;
  font-size: 11px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  outline: none;
  box-sizing: border-box;
}
.pm-burnin-customtext-input:focus {
  border-color: rgba(100,160,255,.6);
  background: rgba(0,0,0,.45);
}
.pm-burnin-customtext-input::placeholder { color: rgba(80,110,160,.5); }

/* Merged rows (annotations / custom text) */
.pm-burnin-row--merged { cursor: default; }
.pm-burnin-row-sublabels { display: flex; align-items: center; gap: 3px; flex-wrap: nowrap; overflow: hidden; }
.pm-burnin-sublabel-chip {
  display: inline-block;
  padding: 1px 6px;
  background: rgba(100,150,255,.12);
  border: 1px solid rgba(100,150,255,.28);
  border-radius: 4px;
  font-size: 9.5px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: rgba(160,200,255,.82);
  letter-spacing: .2px;
  line-height: 15px;
  white-space: nowrap;
  font-weight: 500;
}
.pm-burnin-style-divider { height: 1px; background: rgba(160,200,255,.12); margin: 4px 0; }
.pm-burnin-customtext-inline {
  flex: 1 1 auto;
  height: 22px;
  padding: 0 7px;
  background: rgba(10,18,40,.7);
  border: 1px solid rgba(160,200,255,.2);
  border-radius: 5px;
  color: #c8d8f0;
  font-size: 11px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  outline: none;
}
.pm-burnin-customtext-inline:focus { border-color: rgba(100,160,255,.5); background: rgba(10,18,40,.9); }
.pm-burnin-customtext-inline::placeholder { color: rgba(80,110,160,.5); }
.pm-burnin-ct-add {
  display: block;
  width: calc(100% - 24px);
  margin: 2px 12px 4px;
  padding: 5px 0;
  background: rgba(100,150,255,.07);
  border: 1px dashed rgba(100,150,255,.28);
  border-radius: 6px;
  color: rgba(140,180,255,.75);
  font-size: 10.5px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  text-align: center;
  cursor: pointer;
  transition: background .15s, border-color .15s, color .15s;
}
.pm-burnin-ct-add:hover { background: rgba(100,150,255,.16); border-color: rgba(100,150,255,.5); color: #a8caff; }
.pm-burnin-ct-remove {
  flex: 0 0 auto;
  width: 20px; height: 20px;
  padding: 0;
  background: none;
  border: none;
  color: rgba(200,80,80,.55);
  font-size: 10px;
  cursor: pointer;
  border-radius: 4px;
  line-height: 1;
  transition: color .15s, background .15s;
}
.pm-burnin-ct-remove:hover { color: #ff6b6b; background: rgba(255,80,80,.12); }

/* Merged custom text row (legacy, kept for compat) */
.pm-burnin-row--customtext-merged { align-items: flex-start; padding-top: 7px; padding-bottom: 7px; }
.pm-burnin-row-copy--text { flex-direction: column; align-items: flex-start; gap: 4px; }
.pm-burnin-customtext-inputs { display: flex; flex-direction: column; gap: 3px; width: 100%; }
.pm-burnin-customtext-merged { margin-top: 0; }

.pm-burnin-row-select {
  flex: 0 0 auto;
  background: rgba(0,0,0,.35);
  border: 1px solid rgba(160,200,255,.2);
  border-radius: 6px;
  color: #90b8e8;
  font: 10px "SF Mono", ui-monospace, monospace;
  padding: 3px 5px;
  cursor: pointer;
  max-width: 108px;
  transition: border-color .12s;
}
.pm-burnin-row-select:focus { outline: none; border-color: #3a82f7; }
.pm-burnin-row-select:hover { border-color: rgba(58,130,247,.45); }
.pm-burnin-row-select option[value="custom"] { color: #2172E3; font-style: italic; }

/* ── Group section headers ── */
.pm-burnin-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.pm-burnin-group + .pm-burnin-group { margin-top: 3px; }
.pm-burnin-group-header {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.0px;
  text-transform: uppercase;
  color: rgba(130,165,220,.72);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  padding: 6px 8px 3px;
  border-top: 1px solid rgba(160,200,255,.09);
  display: flex;
  align-items: center;
  gap: 6px;
}
.pm-burnin-group--first .pm-burnin-group-header { border-top: none; padding-top: 4px; }
.pm-burnin-group-count {
  font-size: 8px;
  font-weight: 600;
  letter-spacing: .02em;
  color: rgba(100,140,200,.4);
  font-family: "SF Mono", ui-monospace, monospace;
  text-transform: none;
  transition: color .15s;
  line-height: 1;
}
.pm-burnin-group-count--active { color: rgba(140,190,255,.65); }

/* Group accent colors — header label + row left-border tint */
[data-group-idx="0"] .pm-burnin-group-header { color: #5b9bd5; border-top-color: rgba(91,155,213,.2); }
[data-group-idx="0"] .pm-burnin-row { border-left: 2px solid rgba(91,155,213,.18); }
[data-group-idx="0"] .pm-burnin-row:has(input:checked) { border-left-color: rgba(91,155,213,.65); }

[data-group-idx="1"] .pm-burnin-group-header { color: #4ec994; border-top-color: rgba(78,201,148,.18); }
[data-group-idx="1"] .pm-burnin-row { border-left: 2px solid rgba(78,201,148,.18); }
[data-group-idx="1"] .pm-burnin-row:has(input:checked) { border-left-color: rgba(78,201,148,.65); }

[data-group-idx="2"] .pm-burnin-group-header { color: #e5731a; border-top-color: rgba(229,115,26,.18); }
[data-group-idx="2"] .pm-burnin-row { border-left: 2px solid rgba(229,115,26,.18); }
[data-group-idx="2"] .pm-burnin-row:has(input:checked) { border-left-color: rgba(229,115,26,.65); }

[data-group-idx="3"] .pm-burnin-group-header { color: #b06ce4; border-top-color: rgba(176,108,228,.18); }
[data-group-idx="3"] .pm-burnin-row { border-left: 2px solid rgba(176,108,228,.18); }
[data-group-idx="3"] .pm-burnin-row:has(input:checked) { border-left-color: rgba(176,108,228,.65); }

/* Group count badge per-group accent */
[data-group-idx="0"] .pm-burnin-group-count--active { color: rgba(91,155,213,.75); }
[data-group-idx="1"] .pm-burnin-group-count--active { color: rgba(78,201,148,.75); }
[data-group-idx="2"] .pm-burnin-group-count--active { color: rgba(229,115,26,.75); }
[data-group-idx="3"] .pm-burnin-group-count--active { color: rgba(176,108,228,.75); }

/* ── Visual 3×3 slot grid ── */
.pm-burnin-slot-grid { flex: 0 0 auto; position: relative; }
.pm-burnin-sg-inner {
  display: grid;
  grid-template-columns: repeat(3, 11px);
  gap: 2px;
}
.pm-burnin-sg-cell {
  width: 11px;
  height: 8px;
  padding: 0;
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 2px;
  cursor: pointer;
  transition: background .1s, border-color .1s;
}
.pm-burnin-sg-cell:hover { background: rgba(58,130,247,.35); border-color: rgba(58,130,247,.65); }
.pm-burnin-sg-cell--on  { background: rgba(58,130,247,.80) !important; border-color: #5a9aff !important; box-shadow: 0 0 0 1px rgba(58,130,247,.35), 0 0 4px rgba(58,130,247,.4); }
.pm-burnin-sg-custom {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 8px;
  padding: 0;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 2px;
  cursor: pointer;
  font-size: 7px;
  color: rgba(180,200,240,.4);
  transition: background .1s, color .1s, border-color .1s;
  line-height: 1;
  margin-top: 2px;
}
.pm-burnin-sg-custom:hover { background: rgba(214,163,58,.15); border-color: rgba(214,163,58,.4); color: #2172E3; }
.pm-burnin-sg-custom.pm-burnin-sg-cell--on { background: rgba(214,163,58,.22) !important; border-color: rgba(214,163,58,.65) !important; color: #2172E3 !important; }

/* ── Inline font size badge ── */
.pm-burnin-row-sizebadge {
  flex: 0 0 auto;
  font: 600 9px "SF Mono", ui-monospace, monospace;
  color: rgba(120,165,240,.5);
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 3px;
  padding: 1px 4px;
  min-width: 20px;
  text-align: center;
  line-height: 1.6;
  transition: color .12s, border-color .12s, background .12s;
}
.pm-burnin-row:has(input:checked) .pm-burnin-row-sizebadge {
  color: rgba(140,190,255,.75);
  border-color: rgba(58,130,247,.25);
  background: rgba(58,130,247,.08);
}

/* ── Inline preset save panel ── */
.pm-burnin-preset-delete--confirm {
  background: rgba(220,80,60,.18) !important;
  border-color: rgba(220,80,60,.45) !important;
  color: #ff8878 !important;
  animation: pmBurninFadeIn .12s ease;
}

.pm-burnin-preset-savepanel {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  background: rgba(30,50,90,.35);
  border-bottom: 1px solid rgba(58,130,247,.18);
  animation: pmBurninFadeIn .14s ease;
}
.pm-burnin-preset-nameinp {
  flex: 1 1 auto;
  min-width: 0;
  background: rgba(10,18,40,.9);
  border: 1px solid rgba(58,130,247,.3);
  border-radius: 6px;
  color: #b0d0ff;
  font: 11px "SF Mono", ui-monospace, monospace;
  padding: 4px 8px;
  outline: none;
  transition: border-color .12s, box-shadow .12s;
}
.pm-burnin-preset-nameinp:focus { border-color: #3a82f7; box-shadow: 0 0 0 2px rgba(58,130,247,.18); }
.pm-burnin-preset-nameinp::placeholder { color: rgba(80,120,180,.45); }

.pm-burnin-row-style-btn {
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  padding: 0;
  background: rgba(10,18,40,.8);
  border: 1px solid rgba(58,130,247,.2);
  border-radius: 7px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  color: rgba(100,150,220,.55);
  transition: border-color .12s, box-shadow .12s, color .12s, background .12s;
  position: relative;
}
.pm-burnin-row-style-btn:hover {
  border-color: #3a82f7;
  box-shadow: 0 0 0 2px rgba(58,130,247,.18);
  color: #90b8e8;
  background: rgba(20,40,80,.9);
}
.pm-burnin-row-style-btn.pm-burnin-style-open {
  border-color: #3a82f7;
  background: rgba(30,60,120,.6);
  color: #b0d4ff;
  box-shadow: 0 0 0 2px rgba(58,130,247,.25);
}
.pm-burnin-row:has(input:checked) .pm-burnin-row-style-btn {
  border-color: rgba(58,130,247,.32);
  color: rgba(120,170,240,.7);
}
.pm-burnin-row-style-swatch {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: none;
  pointer-events: none;
  flex-shrink: 0;
  box-shadow: 0 0 0 1.5px rgba(255,255,255,.25);
  position: absolute;
  top: 4px;
  right: 4px;
}
.pm-burnin-row-style-icon {
  width: 13px;
  height: 13px;
  pointer-events: none;
  flex-shrink: 0;
}

/* ── Style panel ── */
.pm-burnin-row-style {
  display: none;
  flex-direction: column;
  gap: 3px;
  padding: 5px 10px 6px 34px;
  background: rgba(0,0,0,.28);
  border-radius: 0 0 8px 8px;
  border: 1px solid rgba(160,200,255,.1);
  border-top: none;
  margin: -2px 0 3px;
}
.pm-burnin-style-row {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pm-burnin-style-label {
  flex: 0 0 58px;
  font-size: 9.5px;
  color: rgba(140,178,230,.72);
  text-align: right;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  letter-spacing: .15px;
  font-weight: 500;
}
.pm-burnin-style-color {
  flex: 0 0 auto;
  width: 26px;
  height: 20px;
  padding: 1px 2px;
  background: rgba(10,18,40,.9);
  border: 1px solid rgba(58,130,247,.2);
  border-radius: 5px;
  cursor: pointer;
  transition: border-color .12s;
}
.pm-burnin-style-color:hover { border-color: #3a82f7; }
.pm-burnin-style-color-placeholder { flex: 0 0 26px; }
.pm-burnin-style-axis-label {
  flex: 0 0 10px;
  font-size: 9px;
  font-weight: 700;
  color: rgba(140,180,240,.55);
  text-align: center;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.pm-burnin-style-row-y { margin-top: -2px; }
.pm-burnin-style-section-start { margin-top: 5px; padding-top: 5px; border-top: 1px solid rgba(160,200,255,.06); }
.pm-burnin-style-slider {
  flex: 1 1 auto;
  height: 4px;
  accent-color: #3a82f7;
  cursor: pointer;
  border-radius: 2px;
}
.pm-burnin-style-num {
  flex: 0 0 42px;
  background: rgba(10,18,40,.9);
  border: 1px solid rgba(58,130,247,.18);
  border-radius: 5px;
  color: #90b8e8;
  font: 10.5px "SF Mono", ui-monospace, monospace;
  padding: 2px 3px;
  text-align: center;
  -moz-appearance: textfield;
  transition: border-color .12s;
}
.pm-burnin-style-num--xs {
  flex: 0 0 34px;
}
.pm-burnin-style-num::-webkit-inner-spin-button,
.pm-burnin-style-num::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
.pm-burnin-style-num:focus { outline: none; border-color: #3a82f7; box-shadow: 0 0 0 2px rgba(58,130,247,.15); }

/* ── Preview panel ── */
.pm-burnin-side {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 10px 14px;
  background: rgba(6,10,22,.6);
  min-width: 0;
}
.pm-burnin-side-label {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 1.0px;
  text-transform: uppercase;
  color: rgba(130,165,220,.72);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.pm-burnin-preview {
  flex: 1 1 auto;
  position: relative;
  background: #000;
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid rgba(58,130,247,.22);
  box-shadow: 0 8px 32px rgba(0,0,0,.6), 0 0 0 1px rgba(255,255,255,.04) inset, 0 0 20px rgba(20,60,160,.15);
}
.pm-burnin-preview-canvas {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
  outline: none;
}
.pm-burnin-preview-canvas:focus-visible {
  box-shadow: 0 0 0 2px rgba(82,178,255,.4);
}
@keyframes pm-burnin-hint-fade {
  0%, 55%  { opacity: 1; }
  100%     { opacity: 0; }
}
.pm-burnin-drag-hint {
  position: absolute;
  bottom: 6px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  font-size: 9.5px;
  color: rgba(160,185,220,.55);
  background: rgba(8,12,20,.55);
  padding: 2px 8px;
  border-radius: 4px;
  pointer-events: none;
  letter-spacing: .01em;
  animation: pm-burnin-hint-fade 5s ease forwards;
}
.pm-burnin-preview:hover .pm-burnin-drag-hint,
.pm-burnin-preview:focus-within .pm-burnin-drag-hint {
  animation: none;
  opacity: 1;
}
.pm-burnin-slot--top-left    { top: 5%; left: 3%; text-align: left; }
.pm-burnin-slot--top-center  { top: 5%; left: 50%; transform: translateX(-50%); text-align: center; }
.pm-burnin-slot--top-right   { top: 5%; right: 3%; text-align: right; }
.pm-burnin-slot--middle-left   { top: 50%; transform: translateY(-50%); left: 3%; text-align: left; }
.pm-burnin-slot--middle-center { top: 50%; left: 50%; transform: translate(-50%,-50%); text-align: center; }
.pm-burnin-slot--middle-right  { top: 50%; right: 3%; transform: translateY(-50%); text-align: right; }
.pm-burnin-slot--bottom-left   { bottom: 5%; left: 3%; text-align: left; }
.pm-burnin-slot--bottom-center { bottom: 5%; left: 50%; transform: translateX(-50%); text-align: center; }
.pm-burnin-slot--bottom-right  { bottom: 5%; right: 3%; text-align: right; }
.pm-burnin-entry {
  display: block;
  font-family: "SF Mono", ui-monospace, monospace;
  font-size: 8px;
  line-height: 1.4;
  padding: 1px 4px;
  background: rgba(0,0,0,0.55);
  border-radius: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 140px;
}
.pm-burnin-entry--shot     { color: #ffffff; font-weight: 700; }
.pm-burnin-entry--noteType { color: #aaddff; font-weight: 600; }
.pm-burnin-entry--note     { color: #ffee99; }
.pm-burnin-entry--annotate { color: #f3c4ff; }
.pm-burnin-entry--tc       { color: #c8e8ff; }
.pm-burnin-entry--meta     { color: #d8d8d8; }
.pm-burnin-preview-empty {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(80,110,160,.6);
  font-size: 11px;
}
.pm-burnin-side-note {
  font-size: 10px;
  color: rgba(80,110,160,.6);
  line-height: 1.5;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

/* ── Video transport ── */
.pm-burnin-vctrl {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 2px;
}
.pm-burnin-vctrl-play {
  flex: 0 0 auto;
  width: 30px;
  height: 28px;
  background: rgba(58,130,247,.12);
  border: 1px solid rgba(58,130,247,.25);
  border-radius: 7px;
  color: #90b8e8;
  font-size: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  line-height: 1;
  transition: background .12s, border-color .12s, color .12s;
}
.pm-burnin-vctrl-play:hover { background: rgba(58,130,247,.25); border-color: #3a82f7; color: #d0e8ff; }
.pm-burnin-vctrl-seek {
  flex: 1 1 auto;
  height: 4px;
  accent-color: #3a82f7;
  cursor: pointer;
}
.pm-burnin-vctrl-tc {
  flex: 0 0 auto;
  font: 11px "SF Mono", ui-monospace, monospace;
  color: rgba(100,140,190,.6);
  min-width: 60px;
  text-align: right;
}

/* ── Footer actions ── */
.pm-burnin-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 18px;
  background: linear-gradient(0deg, rgba(0,0,0,.25) 0%, rgba(255,255,255,.04) 100%);
  border-top: 1px solid rgba(160,200,255,.12);
  box-shadow: 0 -1px 0 rgba(0,0,0,.3);
}
.pm-burnin-actions-spacer { flex: 1 1 auto; }

/* Scope toggle */
.pm-burnin-scope-group {
  display: flex;
  align-items: center;
  gap: 4px;
  background: rgba(0,0,0,.25);
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 8px;
  padding: 3px;
}
.pm-burnin-scope-label {
  font-size: 10.5px;
  color: rgba(160,190,230,.65);
  padding: 0 6px 0 4px;
  white-space: nowrap;
}
.pm-burnin-scope-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: rgba(160,190,230,.55);
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background .12s, color .12s, border-color .12s;
  white-space: nowrap;
}
.pm-burnin-scope-btn:hover {
  background: rgba(255,255,255,.06);
  color: rgba(200,220,255,.85);
}
.pm-burnin-scope-btn.active {
  background: rgba(32,96,220,.30);
  border-color: rgba(80,140,255,.5);
  color: #b8d4ff;
  box-shadow: 0 0 0 1px rgba(80,140,255,.12) inset;
}
.pm-burnin-scope-icon { font-size: 11px; }
.pm-burnin-btn {
  padding: 7px 16px;
  border-radius: 8px;
  font: 600 12px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background .12s, border-color .12s, color .12s, box-shadow .12s;
  letter-spacing: .2px;
}
.pm-burnin-btn-ghost {
  background: rgba(255,255,255,.04);
  border-color: rgba(255,255,255,.1);
  color: rgba(160,190,230,.7);
}
.pm-burnin-btn-ghost:hover { background: rgba(255,255,255,.08); border-color: rgba(255,255,255,.18); color: #c0d8f8; }
.pm-burnin-btn-save {
  background: linear-gradient(135deg, #2060d8 0%, #1a4ab8 100%);
  border-color: rgba(100,160,255,.3);
  color: #e8f2ff;
  box-shadow: 0 2px 12px rgba(58,130,247,.35);
}
.pm-burnin-btn-save:hover {
  background: linear-gradient(135deg, #2a70e8 0%, #2055cc 100%);
  box-shadow: 0 4px 18px rgba(58,130,247,.5);
  border-color: rgba(100,160,255,.5);
}

/* Quick workflow preset pills */
.pm-burnin-quick-presets {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 3px 14px 2px;
  flex-wrap: wrap;
}
.pm-burnin-qp-label {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: rgba(160,190,230,.65);
  margin-right: 2px;
  flex: 0 0 auto;
}
.pm-burnin-qp-btn {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 8px;
  background: rgba(58,130,247,.10);
  border: 1px solid rgba(58,130,247,.25);
  border-radius: 10px;
  color: #7ab4ff;
  font-size: 10.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background .14s, border-color .14s, color .14s;
}
.pm-burnin-qp-btn:hover {
  background: rgba(58,130,247,.22);
  border-color: rgba(58,130,247,.5);
  color: #c0d8ff;
}
.pm-burnin-qp-btn:active {
  background: rgba(58,130,247,.32);
}

/* Font family selector */
.pm-burnin-style-font-sel {
  flex: 1 1 auto;
  min-width: 0;
  height: 22px;
  padding: 0 5px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 4px;
  color: #c8d8f0;
  font-size: 10.5px;
  cursor: pointer;
  outline: none;
}
.pm-burnin-style-font-sel:focus { border-color: #3a82f7; }

/* Typography Bold / Italic toggle buttons */
.pm-burnin-tb-btn {
  flex: 0 0 21px;
  width: 21px;
  height: 21px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 4px;
  color: rgba(180,210,255,.6);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: background .12s, border-color .12s, color .12s;
  line-height: 1;
  user-select: none;
}
.pm-burnin-tb-btn:hover {
  background: rgba(58,130,247,.18);
  border-color: rgba(58,130,247,.4);
  color: #b0ceff;
}
.pm-burnin-tb-btn.pm-burnin-tb-on {
  background: rgba(58,130,247,.28);
  border-color: rgba(58,130,247,.6);
  color: #90c0ff;
}
.pm-burnin-tb-italic { font-style: italic; }

/* Apply style to all button */
.pm-burnin-apply-all-btn {
  display: block;
  width: calc(100% - 0px);
  margin-top: 7px;
  padding: 5px 0;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.10);
  border-radius: 5px;
  color: rgba(160,190,230,.55);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background .12s, border-color .12s, color .12s, box-shadow .12s;
  position: relative;
  overflow: hidden;
}
.pm-burnin-apply-all-btn::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 2px;
  background: rgba(58,130,247,.3);
  border-radius: 5px 0 0 5px;
  transition: background .12s;
}
.pm-burnin-apply-all-btn:hover {
  background: rgba(58,130,247,.12);
  border-color: rgba(58,130,247,.30);
  color: #8ab4f8;
  box-shadow: 0 0 0 1px rgba(58,130,247,.08) inset;
}
.pm-burnin-apply-all-btn:hover::before { background: rgba(58,130,247,.7); }

/* Safe area toggle button */
.pm-burnin-safearea-btn {
  flex: 0 0 auto;
  height: 24px;
  padding: 0 9px;
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.10);
  border-radius: 4px;
  color: rgba(180,210,255,.5);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background .12s, border-color .12s, color .12s;
  white-space: nowrap;
}
.pm-burnin-safearea-btn:hover {
  background: rgba(255,200,50,.10);
  border-color: rgba(255,200,50,.30);
  color: rgba(255,200,50,.80);
}
.pm-burnin-safearea-btn.pm-burnin-safearea-on {
  background: rgba(255,200,50,.14);
  border-color: rgba(255,200,50,.45);
  color: rgba(255,210,80,.90);
}

/* ── Burn-in toolrow: scale slider + preview BG switcher ──────────────────── */
.pm-burnin-toolrow {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 2px;
  flex-shrink: 0;
}
.pm-burnin-toolrow-label {
  font-size: 10px;
  font-weight: 600;
  color: rgba(160,185,220,.7);
  text-transform: uppercase;
  letter-spacing: .05em;
  white-space: nowrap;
}
.pm-burnin-toolrow-sep {
  flex: 1 1 auto;
}
.pm-burnin-scale-slider {
  width: 80px;
  height: 3px;
  accent-color: rgba(82,160,255,.9);
  cursor: pointer;
  flex-shrink: 0;
}
.pm-burnin-scale-val {
