/* ALL CAPS toolbar button */
.pm-burnin-tb-caps {
  font-size: 8px;
  letter-spacing: .04em;
  font-weight: 700;
}
/* Quick color swatches */
.pm-burnin-swatches {
  display: flex;
  gap: 3px;
  padding: 3px 0 4px 0;
  flex-wrap: wrap;
}
.pm-burnin-swatch {
  width: 16px;
  height: 16px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,.18);
