  border-color: rgba(255,255,255,.55);
}
.pm-burnin-swatch:active {
  transform: scale(1.1);
}

.pm-annot-canvas.pm-annot-active           { pointer-events: auto; cursor: crosshair; }
.pm-annot-canvas.pm-annot-tool-eraser      { cursor: cell; }
.pm-annot-canvas.pm-annot-tool-text        { cursor: text; }
.pm-annot-canvas.pm-annot-tool-move        { cursor: default; }
.pm-annot-canvas.pm-annot-tool-highlighter { cursor: crosshair; }
.pm-annot-canvas.pm-annot-tool-circle      { cursor: crosshair; }
.pm-annot-toolbar {
  position: absolute;
  top: 6px; left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px;
  background: rgba(8,8,20,.94);
  border: 1px solid #2a2a44;
  border-radius: 6px;
  backdrop-filter: blur(8px);
  user-select: none;
  white-space: nowrap;
  flex-wrap: nowrap;
}
.pm-annot-group { display: flex; align-items: center; gap: 2px; }
.pm-annot-div {
  width: 1px; height: 18px;
  background: #2a2a44; flex-shrink: 0; margin: 0 2px;
}
/* Tool buttons */
.pm-annot-tool {
  width: 24px; height: 24px; padding: 4px;
  background: transparent; border: 1px solid transparent; border-radius: 3px;
  cursor: pointer; color: #6060888;
  display: flex; align-items: center; justify-content: center;
  transition: color .1s, border-color .1s, background .1s;
}
.pm-annot-tool { color: #606088; }
.pm-annot-tool svg { width: 12px; height: 12px; }
.pm-annot-tool:hover  { color: #ccc; background: #1e1e2e; }
.pm-annot-tool.active { color: #2172E3; border-color: #5a4a10; background: #1c1808; }
/* Color swatches */
.pm-annot-color {
  width: 14px; height: 14px; border-radius: 50%;
  background: var(--sw, #888);
  border: 2px solid transparent; cursor: pointer; padding: 0;
  transition: border-color .1s, transform .1s;
}
.pm-annot-color:hover  { transform: scale(1.2); }
.pm-annot-color.active { border-color: #fff; transform: scale(1.15); }
.pm-annot-colorpick {
  width: 16px; height: 16px;
  border-radius: 50%; border: 2px solid #2a2a44;
  padding: 0; cursor: pointer; background: none;
  -webkit-appearance: none;
}
.pm-annot-colorpick::-webkit-color-swatch-wrapper { padding: 0; border-radius: 50%; }
.pm-annot-colorpick::-webkit-color-swatch { border: none; border-radius: 50%; }
/* Style controls */
.pm-annot-styles { gap: 6px; }
.pm-annot-ctl { display: flex; align-items: center; gap: 3px; cursor: pointer; }
.pm-annot-ctl-ic { font-size: 10px; color: #6060888; }
.pm-annot-ctl-ic { color: #606088; }
.pm-annot-width {
  font-size: 9px; background: #111118; border: 1px solid #1e1e2e;
  color: #9898b8; border-radius: 3px; padding: 1px 2px; cursor: pointer;
}
.pm-annot-opacity {
  width: 52px; height: 3px; cursor: pointer; accent-color: #2172E3;
}
/* Action buttons */
.pm-annot-action {
  font-size: 10px;
  background: transparent; border: 1px solid #1e1e2e;
  color: #7878a0; border-radius: 3px; padding: 2px 5px;
  cursor: pointer; white-space: nowrap;
  transition: color .1s, border-color .1s;
}
.pm-annot-action:hover { color: #ccc; border-color: #3a3a56; }
.pm-annot-export { color: #2172E3 !important; border-color: #1e3a5a !important; background: #0a1420 !important; }
.pm-annot-export:hover { color: #fff !important; }
/* Selection box (move tool) */
.pm-annot-canvas.pm-annot-tool-move { cursor: default; }
/* Text input */
.pm-annot-text-input {
  position: absolute; z-index: 11;
  background: rgba(8,8,20,.92); border: 1px solid #5a4a10;
  color: #2172E3; font-size: 13px; font-family: monospace;
  padding: 2px 6px; border-radius: 3px; outline: none;
  min-width: 80px; max-width: 220px;
}

/* ═══════════════════════════════════════════════════════════════════════════
   CD2 — Redesigned Cut Diff layout (.cd2-* classes)
   ═══════════════════════════════════════════════════════════════════════════ */

/* Shell: full-pane flex-column replaces old grid card */
.cd2-shell {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: #06060f;
}

/* ── Sources bar ─────────────────────────────────────────────────────────── */
.cd2-sources-bar {
  display: flex;
  align-items: stretch;
  gap: 0;
  flex-shrink: 0;
  border-bottom: 1px solid #141428;
  background: #0a0a18;
  min-height: 0;
}
.cd2-src-zone {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  position: relative;
  cursor: default;
  transition: background .15s;
  min-height: 26px;
}
.cd2-src-zone.drag-over { background: rgba(97,175,239,.07); }
.cd2-src-old { border-right: 1px solid #141428; }
.cd2-src-new { border-left: none; }
.cd2-src-badge {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .08em;
  padding: 1px 5px;
  border-radius: 2px;
  flex-shrink: 0;
  color: #fff;
}
.cd2-src-old .cd2-src-badge { background: #2a3a5a; color: #7aaeee; }
.cd2-src-new .cd2-src-badge { background: #0e3020; color: #0AA356; }
.cd2-src-status {
  font-size: 9px;
  color: #5a5a7a;
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cd2-src-zone.has-file .cd2-src-status { color: #c0c0d8; }
.cd2-browse-btn {
  font-size: 8px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 2px;
  border: 1px solid #2a2a44;
  background: #0e0e1e;
  color: #6868a0;
  cursor: pointer;
  flex-shrink: 0;
  text-transform: uppercase;
  letter-spacing: .05em;
  transition: color .12s, border-color .12s;
}
.cd2-browse-btn:hover { color: #b0b0d0; border-color: #4a4a70; }
.cd2-src-vs {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  color: #222238;
  font-size: 10px;
}

/* ── KPI hero strip ──────────────────────────────────────────────────────── */
.cd2-kpi-bar {
  flex-shrink: 0;
  background: #080812;
  border-bottom: 1px solid #141428;
  min-height: 0;
  display: flex;
  align-items: center;
  padding: 0 10px;
  height: 34px;
}
.cd2-kpi-empty {
  font-size: 10px;
  color: #3a3a58;
  font-style: italic;
}
.cd2-kpi-content {
  display: flex;
  align-items: center;
  gap: 0;
  width: 100%;
  height: 34px;
  overflow: hidden;
}
.cd2-kpi-sep {
  width: 1px;
  height: 20px;
  background: #1e1e32;
  flex-shrink: 0;
  margin: 0 7px;
}

/* Type filter chips */
.cd2-kpi-types {
  display: flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
}
.cd2-kpi-type {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 2px 6px;
  border-radius: 3px;
  border: 1px solid #202038;
  background: #0e0e1e;
  cursor: pointer;
  transition: opacity .12s;
  min-width: 0;
}
.cd2-kpi-type:hover { opacity: .8; }
.cd2-kpi-type.is-off { opacity: .35; }
.cd2-kpi-type[disabled] { opacity: .35; cursor: not-allowed; }
.cd2-type-k {
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .06em;
  text-transform: uppercase;
  opacity: .7;
  line-height: 1;
}
.cd2-type-n {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: -.2px;
  line-height: 1;
}
.cd2-kpi-type.chip-new { background: rgba(108,168,255,.10); border-color: rgba(108,168,255,.28); color: #6ca8ff; }
.cd2-kpi-type.chip-ext { background: rgba(60,220,160,.08); border-color: rgba(60,220,160,.25); color: #3cdca0; }
.cd2-kpi-type.chip-chg { background: rgba(255,200,70,.08); border-color: rgba(255,200,70,.25); color: #ffc846; }
.cd2-kpi-type.chip-rem { background: rgba(230,100,100,.08); border-color: rgba(230,100,100,.25); color: #E5484D; }

/* Pull metrics */
.cd2-kpi-metric {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  gap: 3px;
  padding: 0 7px;
  flex-shrink: 0;
}
.cd2-m-val {
  font-size: 12px;
  font-weight: 800;
  color: #d0d0e8;
  letter-spacing: -.2px;
  line-height: 1;
}
.cd2-m-lbl {
  font-size: 8px;
  font-weight: 600;
  color: #4a4a68;
  text-transform: uppercase;
  letter-spacing: .05em;
}
.cd2-kpi-pull .cd2-m-val { color: #2172E3; }
.cd-delta-val[data-sign="+"] { color: #34d464 !important; }
.cd-delta-val[data-sign="-"] { color: #ff6a6a !important; }

/* Storage estimate */
.cd2-kpi-storage {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
  padding: 0 4px;
}
.cd2-st-lbl {
  font-size: 8px;
  font-weight: 700;
  color: #b8ff5a;
  opacity: .6;
  text-transform: uppercase;
  letter-spacing: .05em;
}
.cd2-st-pill {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  border-radius: 3px;
  padding: 1px 5px;
  border: 1px solid transparent;
}
.cd2-st-exr { background: #1a1422; border-color: #2a1a38; }
.cd2-st-k {
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  opacity: .7;
}
.cd2-st-exr .cd2-st-k { color: #a386ba; }
.cd2-st-v {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: -.2px;
  color: #b0b0cc;
}

/* Progress */
.cd2-kpi-progress {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
  padding: 0 6px;
  min-width: 0;
}
.cd2-prog-bar-wrap {
  width: 40px;
  height: 3px;
  background: #1a1a2e;
  border-radius: 2px;
  overflow: hidden;
  flex-shrink: 0;
}
.cd2-prog-bar {
  height: 100%;
  background: linear-gradient(90deg, #0AA356, #34d464);
  border-radius: 2px;
  transition: width .3s ease;
  min-width: 2px;
}
.cd2-prog-nums {
  display: flex;
  align-items: baseline;
  gap: 2px;
  font-size: 9px;
  line-height: 1;
}
.cd2-prog-done   { font-weight: 800; color: rgba(255,255,255,.90); font-size: 10px; }
.cd2-prog-sep    { color: #3a3a58; font-size: 8px; }
.cd2-prog-total  { color: rgba(255,255,255,.40); font-size: 8px; }
.cd2-prog-lbl    { font-size: 7px; color: #4a4a68; text-transform: uppercase; letter-spacing: .04em; margin-left: 2px; }

/* Risk */
.cd2-kpi-risk {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  gap: 3px;
  padding: 0 6px;
  flex-shrink: 0;
}
.cd2-risk-n {
  font-size: 12px;
  font-weight: 800;
  color: rgba(255,90,90,.90);
  letter-spacing: -.2px;
  line-height: 1;
}
.cd2-risk-l {
  font-size: 7px;
  font-weight: 600;
  color: rgba(255,90,90,.45);
  text-transform: uppercase;
  letter-spacing: .05em;
}

/* Audio compact */
.cd2-kpi-audio {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  padding: 0 6px;
  flex-shrink: 0;
  min-width: 0;
}
.cd2-aud-row {
  display: flex;
  align-items: baseline;
  gap: 3px;
  font-size: 8px;
  line-height: 1;
  white-space: nowrap;
}
.cd2-aud-k {
  font-size: 7px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: #4a4a68;
  min-width: 0;
}
.cd2-aud-v { color: #9090b0; font-size: 8px; overflow: hidden; text-overflow: ellipsis; }
.cd2-aud-diff .cd2-aud-k { color: #6868a0; }
.cd2-aud-diff .cd2-aud-v { color: #7a7a98; font-style: italic; }

/* ── Smart insights banner ───────────────────────────────────────────────── */
.cd2-insights {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  background: #0c0c1e;
  border-bottom: 1px solid #1a1a30;
  font-size: 9px;
  color: #6ca8ff;
}
.cd2-insights[hidden] { display: none; }
.cd2-insights.cd2-ins-warn {
  background: rgba(255,90,90,.04);
  border-color: rgba(255,90,90,.18);
  color: #ff9090;
}
.cd2-ins-icon {
  font-size: 9px;
  flex-shrink: 0;
  opacity: .85;
}
.cd2-ins-text {
  flex: 1;
  font-size: 9px;
  letter-spacing: .01em;
}

/* ── Main area (video + timeline + table) ────────────────────────────────── */
.cd2-main-area {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.cd2-tl-card {
  flex-shrink: 0;
}
.cd2-table-card {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

/* Override old grid-area rules that no longer apply */
#main-cutdiff .cd2-shell > .cd2-main-area > .card[style*="grid-area"] {
  grid-area: unset !important;
}

