  border-color: rgba(214,163,58,.80) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.16), 0 0 0 1px rgba(214,163,58,.20), 0 0 22px rgba(214,163,58,.20), 0 16px 26px rgba(0,0,0,.32) !important;
}

/* Icon buttons (Chain / Loop / Audio / Fit / Fullscreen) */
#main-cutdiff .cd-vcmp-iconbtn.is-active {
  background: rgba(214,163,58,.16) !important;
  border-color: rgba(214,163,58,.38) !important;
  color: #2172E3 !important;
}

/* Rate select and TC input focus */
#main-cutdiff .cd-vcmp-rate:focus {
  border-color: rgba(214,163,58,.38) !important;
