}

/* Tool buttons (Wipe / Split / A-B / Diff / Heat) — hover + active */
#main-cutdiff .cd-vcmp-toolbtn:hover {
  border-color: rgba(214,163,58,.42) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.16), 0 14px 22px rgba(0,0,0,.36),
              0 0 0 1px rgba(214,163,58,.14), 0 0 18px rgba(214,163,58,.12) !important;
}
#main-cutdiff .cd-vcmp-toolbtn.is-active {
  background: linear-gradient(180deg, rgba(214,163,58,.40), rgba(160,120,0,.55)) !important;
  border-color: rgba(214,163,58,.88) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.18), 0 0 0 1px rgba(214,163,58,.22),
              0 0 22px rgba(214,163,58,.20), 0 14px 24px rgba(0,0,0,.34) !important;
}

/* Icon buttons hover (Chain / Loop / Audio / Fit / Fullscreen) */
#main-cutdiff .btn.tiny.cd-vcmp-iconbtn:hover {
  border-color: rgba(214,163,58,.42) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.16), 0 16px 26px rgba(0,0,0,.36),
              0 0 0 1px rgba(214,163,58,.14), 0 0 18px rgba(214,163,58,.12) !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   CD2 SMART HEADER — base rules for .cd2-hdr (replaces .cd2-sources-bar)
   ══════════════════════════════════════════════════════════════════════════ */

.cd2-hdr {
  display: flex;
  align-items: stretch;
  height: 38px;
  min-height: 38px;
  flex-shrink: 0;
  background: #09091a;
  border-bottom: 1px solid #181828;
  overflow: hidden;
}
.cd2-hdr-drop {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  min-width: 0;
  padding: 0 10px;
  cursor: pointer;
  border-right: 1px solid #141428;
  transition: background .12s;
}
.cd2-hdr-drop:hover { background: rgba(255,255,255,.02); }
.cd2-hdr-drop.drag-over { background: #0f1030; outline: 1px solid #4040cc; }
.cd2-hdr-badge {
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .08em;
  padding: 1px 5px;
  border-radius: 2px;
  flex-shrink: 0;
  text-transform: uppercase;
}
.cd2-hdr-badge-old { background: rgba(97,175,239,.12); color: #2172E3; }
.cd2-hdr-badge-new { background: rgba(10,163,86,.12); color: #0AA356; }
.cd2-hdr-status {
  flex: 1;
  min-width: 0;
  font-size: 10px;
  font-family: monospace;
  color: #5a5a80;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cd2-hdr-old .cd2-hdr-status { color: #4a7aaf; }
.cd2-hdr-new .cd2-hdr-status { color: #3a8060; }
.cd2-hdr-browse {
  flex-shrink: 0;
  background: rgba(255,255,255,.04);
  border: 1px solid #2a2a44;
  border-radius: 3px;
  color: #6868a0;
  font-size: 8px;
  padding: 2px 8px;
  cursor: pointer;
  transition: background .1s, color .1s;
  line-height: 1.5;
}
.cd2-hdr-browse:hover { background: rgba(255,255,255,.08); color: #9090c0; }
.cd2-hdr-vs {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  flex-shrink: 0;
  color: #252540;
}
.cd2-hdr-divider {
  width: 1px;
  background: #181828;
  flex-shrink: 0;
  align-self: stretch;
}
.cd2-hdr-actions {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 10px;
  flex-shrink: 0;
}
.cd2-hdr-maxsec {
  display: flex;
  align-items: center;
  gap: 3px;
  cursor: default;
}
.cd2-hdr-maxsec-lbl,
.cd2-hdr-maxsec-unit { font-size: 8px; color: #4a4a68; }
.cd2-hdr-maxsec input { width: 32px; }

/* ── Timeline header: compact nav only (no action buttons) ──────────────── */
.cd2-tl-nav { gap: 3px; }

/* ── Video compare panel ─────────────────────────────────────────────────── */
.cd2-vcmp-panel {
  flex-shrink: 0;
  overflow: hidden;
  border-top: 1px solid #181828;
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: #06060f;
}
.cd2-vcmp-hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  height: 30px;
  min-height: 30px;
  flex-shrink: 0;
  background: #06060f;
  border-bottom: 1px solid #141424;
}

/* ══════════════════════════════════════════════════════════════════════════
   CD2 SMART LAYOUT — structural overrides v2 (supersedes earlier block)
   ══════════════════════════════════════════════════════════════════════════ */

/* Smart header: fixed 38px row */
#main-cutdiff .cd2-hdr {
  height: 38px !important;
  min-height: 38px !important;
  max-height: 38px !important;
}

/* Video compare panel: order 1 (top), collapsed by default (JS reveals body) */
#main-cutdiff .cd2-vcmp-panel {
  order: 1 !important;
  flex-shrink: 0 !important;
  overflow: hidden !important;
  padding: 0 !important;
  min-height: 0 !important;
}
/* Override old padding:8px rule on the same element */
#main-cutdiff #cutdiffVideoCompareCard {
  padding: 0 !important;
}
/* Body: 200px tall when visible */
#main-cutdiff #cutdiffVcmpBody {
  height: 200px !important;
  min-height: 0 !important;
  overflow: hidden !important;
  flex-shrink: 0 !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   CUT DIFF 2.0 — cd2x-* component styles
   Accent: #74b0c9 (cyan — distinct from CUT DIFF amber and Prep & Mark gold)
   ══════════════════════════════════════════════════════════════════════════ */

/* Tab theme */
.tab.theme-cd2x { color: #888; }
.tab.theme-cd2x .bar { background: #74b0c9; }
.tab.theme-cd2x.active { color: #74b0c9; }
.tab.theme-cd2x svg { color: inherit; }
.btn.theme-cd2x .bar { background: #74b0c9; }

/* Pane layout */
#main-cutdiff2.cd2x-pane {
  display: flex;
  flex-direction: column;
  height: calc(100vh - 86px);
  overflow: hidden;
  background: #08080f;
}

/* Header bar */
.cd2x-hdr {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  height: 36px;
  min-height: 36px;
  flex-shrink: 0;
  background: #0a0a18;
  border-bottom: 1px solid #181830;
  flex-wrap: nowrap;
  overflow: visible;
}
.cd2x-hdr-divider {
  width: 1px;
  height: 18px;
  background: #1e1e38;
  flex-shrink: 0;
  margin: 0 2px;
}
.cd2x-slot {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  min-width: 0;
  background: #0d0d20;
  border: 1px solid #2a2a50;
  border-radius: 4px;
  padding: 4px 8px;
  transition: border-color .15s, background .15s;
}
.cd2x-slot.cd2x-drop-over { border-color: #74b0c9; background: rgba(114,230,255,.08); }
.cd2x-slot.cd2x-drop-loaded { border-color: rgba(114,230,255,.45); background: rgba(114,230,255,.04); }
.cd2x-slot-old .cd2x-slot-tag { color: #6868a0; }
.cd2x-slot-new .cd2x-slot-tag { color: #0AA356; }
.cd2x-slot-tag { font-size: 8px; font-weight: 700; letter-spacing: .06em; flex-shrink: 0; }
.cd2x-slot-label { font-size: 9px; color: #4a4a68; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cd2x-slot.cd2x-drop-loaded .cd2x-slot-label { color: #8888c0; }
.cd2x-browse-btn { font-size: 8px; flex-shrink: 0; }
.cd2x-hdr-vs { font-size: 8px; color: #252540; flex-shrink: 0; padding: 0 4px; }
.cd2x-hdr-actions { display: flex; align-items: center; gap: 5px; flex-shrink: 0; }

/* KPI bar */
.cd2x-kpi-bar {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  background: #09091a;
  border-bottom: 1px solid #141428;
  flex-shrink: 0;
  overflow: hidden;
}
/* Card-style chip: coloured left border + number + plain label */
.cd2x-kpi-chip {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  padding: 3px 8px 3px 6px;
  border-radius: 3px;
  border-left: 2px solid currentColor;
  background: #0e0e1e;
  white-space: nowrap;
  cursor: default;
}
.cd2x-kpi-count { font-size: 13px; font-weight: 700; font-family: monospace; line-height: 1; color: #d8d8f0; }
.cd2x-kpi-desc  { font-size: 7px; letter-spacing: .03em; line-height: 1; color: #9090b8; }
/* All stat chips — muted neutral */
.cd2x-kpi-new  { color: #4a6898; }
.cd2x-kpi-ext  { color: #4a6898; }
.cd2x-kpi-chg  { color: #4a6898; }
.cd2x-kpi-rem  { color: #4a6898; }
.cd2x-kpi-risk { color: #8a3a42; }
.cd2x-kpi-dur  { color: #4a6898; }

/* Focus chip — % of Cut Changed */
.cd2x-kpi-pct {
  color: #56b6c2;
  background: #071618 !important;
  border-left-width: 3px !important;
}
.cd2x-kpi-pct .cd2x-kpi-count { color: #56b6c2 !important; }
.cd2x-kpi-pct .cd2x-kpi-desc  { color: #2e7880 !important; opacity: 1 !important; }
.cd2x-kpi-dur-vals { display: flex; align-items: baseline; gap: 1px; }
.cd2x-kpi-dur-add  { color: #4a9a72; font-size: 11px; font-weight: 700; font-family: monospace; }
.cd2x-kpi-dur-sep  { color: #404068; font-size: 9px; }
.cd2x-kpi-dur-rem  { color: #b05060; font-size: 11px; font-weight: 700; font-family: monospace; }
.cd2x-kpi-sep  { flex: 1; }
.cd2x-kpi-total   { font-size: 8px; color: #4a4a68; font-family: monospace; white-space: nowrap; padding: 0 6px; }
.cd2x-kpi-divider { width: 1px; height: 14px; background: #1e1e34; flex-shrink: 0; margin: 0 2px; }
/* Progress section */
.cd2x-kpi-progress-wrap { display: flex; align-items: center; gap: 5px; }
.cd2x-kpi-progress-label { font-size: 7px; color: #5858a0; letter-spacing: .04em; text-transform: uppercase; }
.cd2x-kpi-progress-track { width: 80px; height: 5px; background: #1a1a30; border-radius: 3px; overflow: hidden; }
.cd2x-kpi-progress-fill { height: 100%; background: #0AA356; border-radius: 3px; transition: width .3s ease; }
.cd2x-kpi-progress-pct { font-size: 9px; font-weight: 700; color: #0AA356; font-family: monospace; }

/* Filter bar */
.cd2x-filter-bar {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 4px 10px;
  background: #08080f;
  border-bottom: 1px solid #111124;
  flex-shrink: 0;
}
.cd2x-filter-label { font-size: 7px; color: #7070a8; letter-spacing: .06em; margin-right: 2px; }
.cd2x-filter-sep   { width: 1px; background: #1a1a30; height: 12px; margin: 0 4px; }
.cd2x-filter-btn, .cd2x-risk-btn {
  font-size: 8px;
  padding: 2px 7px;
  border: 1px solid #1a1a30;
  border-radius: 2px;
  background: transparent;
  color: #4a4a68;
  cursor: pointer;
  transition: border-color .1s, color .1s, background .1s;
}
.cd2x-filter-btn:hover { border-color: rgba(114,230,255,.2); color: #74b0c9; }
.cd2x-filter-btn.cd2x-filter-active { border-color: rgba(114,230,255,.4); background: rgba(114,230,255,.08); color: #74b0c9; }
.cd2x-risk-btn.cd2x-risk-active { border-color: rgba(114,230,255,.3); background: rgba(114,230,255,.06); color: #aaa; }

/* Canvas timeline */
.cd2x-tl-strip { flex-shrink: 0; background: #08080f; border-bottom: 1px solid #111124; position: relative; }
.cd2x-tl-canvas  { display: block; width: 100%; height: 280px; cursor: crosshair; }
.cd2x-tl-overlay { display: block; width: 100%; height: 280px; position: absolute; top: 0; left: 0; pointer-events: none; }
/* Smart Import button */
.cd2x-smart-btn { flex-shrink: 0; font-size: 9px; font-weight: 700; letter-spacing: 0.04em; padding: 3px 9px; border-radius: 4px; cursor: pointer; border: 1px solid rgba(214,163,58,0.5); background: rgba(214,163,58,0.1); color: #2172E3; transition: background .15s, border-color .15s; white-space: nowrap; }
.cd2x-smart-btn:hover { background: rgba(214,163,58,0.2); border-color: rgba(214,163,58,0.8); }
/* Slot click-to-browse */
.cd2x-slot { cursor: pointer; }
.cd2x-vc-slot-clickable { cursor: pointer; }
.cd2x-vc-slot-clickable:hover { background: rgba(114,230,255,0.04); border-radius: 3px; }
#cd2x-vc-old-slot.cd2x-vc-slot-dragover { border-color: #2172E3 !important; background: rgba(97,175,239,0.22) !important; outline: 1px dashed rgba(97,175,239,0.6); outline-offset: -2px; }
#cd2x-vc-new-slot.cd2x-vc-slot-dragover { border-color: #2172E3 !important; background: rgba(214,163,58,0.22) !important; outline: 1px dashed rgba(214,163,58,0.6); outline-offset: -2px; }
/* Header smart drag-over state */
.cd2x-hdr.cd2x-smart-dragover { background: rgba(214,163,58,0.06) !important; outline: 1px dashed rgba(214,163,58,0.45); outline-offset: -2px; }
/* Auto-routed slot highlight */
@keyframes cd2x-slot-pop { 0%{background:rgba(214,163,58,.18)} 100%{background:transparent} }
.cd2x-slot.cd2x-auto-routed { animation: cd2x-slot-pop .8s ease-out forwards; }
/* Smart import toast */
.cd2x-smart-toast { position: absolute; bottom: 64px; left: 50%; transform: translateX(-50%) translateY(8px); display: flex; align-items: center; gap: 8px; flex-wrap: wrap; background: rgba(10,10,24,0.97); border: 1px solid rgba(214,163,58,0.4); border-radius: 6px; padding: 6px 12px; font-size: 9px; color: #c0c0e0; z-index: 9999; opacity: 0; transition: opacity .2s, transform .2s; pointer-events: none; max-width: 80%; white-space: nowrap; }
.cd2x-smart-toast.cd2x-smart-toast-show { opacity: 1; transform: translateX(-50%) translateY(0); }
.cd2x-smart-toast-icon { color: #2172E3; font-size: 11px; }
.cd2x-smart-toast span { color: #8888c0; }

.cd2x-tl-modebar { position: absolute; top: 4px; right: 8px; z-index: 10; display: flex; align-items: center; gap: 5px; }
.cd2x-tl-fit-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 22px; height: 22px; padding: 0; border-radius: 4px; cursor: pointer;
  font-size: 13px; line-height: 1;
  color: #a0a8c8; background: rgba(30,32,56,0.85);
  border: 1px solid rgba(100,110,180,0.45);
  transition: background 0.12s, color 0.12s;
}
.cd2x-tl-fit-btn:hover { background: rgba(60,70,140,0.7); color: #e0e4ff; border-color: rgba(140,150,230,0.75); }
.cd2x-tl-mode-btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 96px; height: 22px;
  font-size: 10px; font-weight: 700; letter-spacing: 0.5px;
  padding: 0 10px; border-radius: 4px; cursor: pointer;
  white-space: nowrap; gap: 4px;
  transition: background 0.15s, box-shadow 0.15s;
}
/* Smart mode — amber solid pill */
.cd2x-tl-mode-btn.is-smart {
  color: #1a1200;
  background: #2172E3;
  border: 1px solid #2172E3;
  box-shadow: 0 0 7px rgba(214,163,58,0.5);
}
.cd2x-tl-mode-btn.is-smart:hover {
  background: #e0bd62;
  box-shadow: 0 0 12px rgba(214,163,58,0.7);
}
/* Sequence mode — indigo outlined pill, same size */
.cd2x-tl-mode-btn.is-seq {
  color: #d0d8ff;
  background: rgba(70,80,170,0.4);
  border: 1px solid rgba(140,150,230,0.75);
  box-shadow: 0 0 6px rgba(100,120,220,0.35);
}
.cd2x-tl-mode-btn.is-seq:hover {
  background: rgba(90,102,200,0.55);
  box-shadow: 0 0 10px rgba(100,120,220,0.55);
}

/* Body */
.cd2x-body { display: flex; flex: 0 0 110px; min-height: 0; overflow: hidden; width: 100%; }

/* Table wrapper */
.cd2x-table-wrap { flex: 1; overflow-y: auto; overflow-x: auto; min-width: 0; position: relative; }
.cd2x-table { width: 100%; border-collapse: collapse; font-size: 10px; table-layout: fixed; }
.cd2x-table th {
  position: sticky;
  top: 0;
  background: #0c0c1e;
  border-bottom: 2px solid #1e1e38;
  padding: 5px 6px;
  font-size: 9px;
  font-weight: 600;
  color: #7070a8;
  text-align: left;
  letter-spacing: .05em;
  text-transform: uppercase;
  z-index: 2;
  white-space: nowrap;
  overflow: hidden;
  position: sticky;
  user-select: none;
}
.cd2x-th-risk   { width: 6px;  min-width: 6px; }
.cd2x-th-type   { width: 44px; min-width: 36px; }
.cd2x-th-reel   { width: 90px; min-width: 50px; }
.cd2x-th-clip   { width: 160px; min-width: 60px; }
.cd2x-th-src    { width: 88px; min-width: 60px; }
.cd2x-th-dur    { width: 52px; min-width: 36px; }
.cd2x-th-conf   { width: 56px; min-width: 36px; }
.cd2x-th-status { width: 44px; min-width: 36px; }

/* Column resize handle */
.cd2x-th-resizer {
  position: absolute;
  right: 0; top: 0; bottom: 0;
  width: 5px;
  cursor: col-resize;
  background: transparent;
  z-index: 3;
}
.cd2x-th-resizer:hover,
.cd2x-th-resizer:active { background: rgba(114,230,255,0.35); }
.cd2x-table th { position: sticky; top: 0; overflow: visible; }

/* Rows */
.cd2x-row { border-bottom: 1px solid #0f0f1e; cursor: pointer; transition: background .06s; }
.cd2x-row:nth-child(even) { background: rgba(255,255,255,0.015); }
.cd2x-row:hover { background: #0f0f28; }
.cd2x-row.cd2x-row-active { background: #141430 !important; }
.cd2x-row.cd2x-row-active td:first-child { border-left: 2px solid var(--risk-color, #74b0c9); }
.cd2x-row td { padding: 4px 6px; vertical-align: middle; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #9898c8; font-size: 10px; }
.cd2x-td-reel { color: #7070a0 !important; font-size: 9px !important; }
.cd2x-td-src  { color: #5858a0 !important; font-size: 9px !important; font-family: monospace; }
.cd2x-td-clip { color: #b0b0d8 !important; }
.cd2x-td-dur  { color: #6868a0 !important; font-size: 9px !important; }
.cd2x-td-risk { width: 6px; padding: 0 !important; }
.cd2x-risk-pip { display: block; width: 3px; height: 100%; min-height: 20px; background: var(--risk-color, #252540); border-radius: 0 1px 1px 0; }

/* Type badge */
.cd2x-type-badge { display: inline-block; padding: 1px 4px; border-radius: 2px; font-size: 7px; font-weight: 700; letter-spacing: .05em; background: #0e0e22; }
.cd2x-type-new       { color: #74b0c9; background: rgba(114,230,255,.10); }
.cd2x-type-extended  { color: #0AA356; background: rgba(10,163,86,.10); }
.cd2x-type-changed   { color: #E0B341; background: rgba(224,179,65,.10); }
.cd2x-type-trimmed   { color: #6868a0; background: rgba(104,104,160,.10); }
.cd2x-type-unchanged { color: #5050a0; background: transparent; }

/* Confidence bar */
.cd2x-conf { display: flex; align-items: center; height: 10px; width: 100%; background: #111124; border-radius: 1px; overflow: hidden; }
.cd2x-conf-bar { height: 100%; border-radius: 1px; transition: width .2s; }
.cd2x-conf-na { color: #6060a0; font-size: 8px; }

/* Status buttons */
.cd2x-status-btn { font-size: 9px; padding: 1px 6px; border: 1px solid #1a1a30; border-radius: 2px; cursor: pointer; transition: background .1s, color .1s; background: transparent; }
.cd2x-st-none  { color: #6868a8; border-color: #2a2a48; }
.cd2x-st-ok    { color: #0AA356; border-color: rgba(10,163,86,.3);   background: rgba(10,163,86,.08); }
.cd2x-st-skip  { color: #6868a0; border-color: rgba(104,104,160,.3); background: rgba(104,104,160,.08); }
.cd2x-st-query { color: #E0B341; border-color: rgba(224,179,65,.3); background: rgba(224,179,65,.08); }

/* Empty state */
.cd2x-empty-state { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); color: #2a2a48; font-size: 11px; text-align: center; pointer-events: none; white-space: nowrap; }

/* Inspector panel */
.cd2x-inspector {
  position: absolute;
  top: 0; right: 0; bottom: 0;
  width: 0;
  overflow: hidden;
  background: rgba(9, 9, 28, 0.94);
  border-left: 1px solid #1e1e38;
  display: flex;
  flex-direction: column;
  transition: width .18s ease;
  z-index: 10;
  backdrop-filter: blur(2px);
}
.cd2x-inspector.cd2x-insp-open { width: 260px; }
.cd2x-left-col .cd2x-insp-close { display: none; }
.cd2x-insp-hdr { display: flex; align-items: center; justify-content: space-between; padding: 6px 10px; background: #0a0a1e; border-bottom: 1px solid #1a1a30; flex-shrink: 0; min-height: 32px; }
.cd2x-insp-title { display: flex; align-items: center; gap: 6px; min-width: 0; overflow: hidden; }
.cd2x-insp-type-badge { font-size: 9px; font-weight: 700; letter-spacing: .05em; flex-shrink: 0; }
.cd2x-insp-event-num { font-size: 8px; color: #7878b8; }
.cd2x-insp-close { background: none; border: none; color: #7878b8; cursor: pointer; font-size: 10px; padding: 2px 4px; flex-shrink: 0; }
.cd2x-insp-close:hover { color: #aaa; }
.cd2x-insp-body { flex: 1; overflow-y: auto; padding: 0; }
.cd2x-insp-section { padding: 8px 10px 6px; border-bottom: 1px solid #111128; }
.cd2x-insp-divider { padding: 5px 10px 3px; font-size: 7px; letter-spacing: .08em; color: #7070a8; background: #08080f; border-top: 1px solid #111128; border-bottom: 1px solid #111128; text-transform: uppercase; }
.cd2x-insp-row { display: flex; align-items: center; gap: 6px; margin-bottom: 4px; }
.cd2x-insp-lbl { font-size: 8px; color: #6868a8; min-width: 52px; flex-shrink: 0; }
.cd2x-insp-val { font-size: 9px; color: #a8a8d0; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cd2x-insp-val-mono { font-family: monospace; font-size: 8px; color: #9090c0; }
.cd2x-insp-conf-row { display: flex; align-items: center; gap: 6px; margin-bottom: 6px; }
.cd2x-insp-conf-track { flex: 1; height: 6px; background: #111128; border-radius: 2px; overflow: hidden; }
.cd2x-insp-conf-fill { height: 100%; border-radius: 2px; transition: width .2s, background .2s; }
.cd2x-insp-select { flex: 1; background: #0e0e22; border: 1px solid #1e1e38; color: #8888b0; font-size: 8px; padding: 2px 4px; border-radius: 2px; }
.cd2x-insp-select:focus { border-color: rgba(114,230,255,.35); outline: none; }
.cd2x-insp-note-row { display: flex; flex-direction: column; gap: 3px; margin-bottom: 6px; }
.cd2x-insp-note { width: 100%; box-sizing: border-box; background: #0e0e22; border: 1px solid #1e1e38; color: #8888b0; font-size: 8px; font-family: monospace; padding: 4px 6px; border-radius: 2px; resize: none; }
.cd2x-insp-note:focus { border-color: rgba(114,230,255,.35); outline: none; }
.cd2x-insp-save-btn { font-size: 8px; }

/* ── CUT DIFF 2.0 — Video Compare Panel ──────────────────────────────────── */
.cd2x-vc-panel {
  flex: 0 0 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: #06060f;
  border-top: 1px solid #111124;
  border-bottom: 1px solid #111124;
  overflow: hidden;
  position: relative;
}
.cd2x-vc-hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  height: 28px;
  min-height: 28px;
  flex-shrink: 0;
  background: #08080f;
}
.cd2x-vc-title { font-size: 8px; color: #7070a8; letter-spacing: .05em; text-transform: uppercase; }
.cd2x-vc-hdr-actions { display: flex; align-items: center; gap: 4px; }
.cd2x-vc-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
/* Setup row — single merged line (title + OLD slot + NEW slot + toggle) */
.cd2x-vc-setup {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  height: 32px;
  min-height: 32px;
  background: #08080f;
  border-bottom: 1px solid #111124;
  flex-shrink: 0;
  flex-wrap: nowrap;
  overflow: hidden;
}
.cd2x-vc-slot {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1;
  min-width: 0;
  min-width: 120px;
}
.cd2x-vc-slot-tag {
  font-size: 7px;
  font-weight: 700;
  color: #6868a0;
  letter-spacing: .06em;
  flex-shrink: 0;
}
.cd2x-vc-slot-new { color: #0AA356; }
.cd2x-vc-slot-name {
  font-size: 8px;
  color: #4a4a68;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cd2x-vc-tc-input {
  width: 80px;
  font-size: 8px;
  padding: 2px 4px;
  background: #0e0e22;
  border: 1px solid #1e1e38;
  color: #7070a0;
  border-radius: 2px;
  flex-shrink: 0;
}
.cd2x-vc-tc-input:focus { border-color: rgba(114,230,255,.35); outline: none; }
/* Viewer area */
.cd2x-vc-view-wrap {
  position: relative;
  background: #000;
  overflow: hidden;
  aspect-ratio: 32 / 9;   /* two 16:9 panels side by side */
  width: 100%;
}
.cd2x-vc-canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* ── CUT DIFF 2.0 — Proxy preparation overlay ───────────────────────────── */
.cd2x-proxy-ov {
  position: absolute; inset: 0; z-index: 10;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 10px; background: rgba(0,0,0,.82); backdrop-filter: blur(4px);
}
.cd2x-proxy-row {
  display: flex; align-items: flex-start; gap: 10px;
  background: rgba(20,20,36,.85); border: 1px solid rgba(255,255,255,.07);
  border-radius: 8px; padding: 10px 14px; min-width: 260px; max-width: 340px;
}
.cd2x-proxy-tag {
  flex-shrink: 0; margin-top: 2px;
  font-size: 9px; font-weight: 800; letter-spacing: .06em;
  padding: 2px 7px; border-radius: 4px;
}
.cd2x-proxy-tag-old { background: rgba(99,102,241,.22); color: #a0a3f5; border: 1px solid rgba(99,102,241,.35); }
.cd2x-proxy-tag-new { background: rgba(52,211,153,.16); color: #6ddbb0; border: 1px solid rgba(52,211,153,.3); }
.cd2x-proxy-info { display: flex; flex-direction: column; gap: 4px; flex: 1; min-width: 0; }
.cd2x-proxy-fname { font-size: 11px; font-weight: 600; color: #8a8c96; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cd2x-proxy-msg   { font-size: 10px; color: #8a8ca8; }
.cd2x-proxy-eta   { font-size: 10px; font-weight: 700; color: #2172E3; letter-spacing: .01em; display: none; }
.cd2x-proxy-bar-wrap { width: 100%; height: 4px; background: #1a1a2a; border-radius: 2px; overflow: hidden; }
.cd2x-proxy-shimmer  { height: 100%; width: 100%; border-radius: 2px;
  background: linear-gradient(90deg, #1e1e2e 25%, #6366f1 50%, #1e1e2e 75%);
  background-size: 200% 100%; animation: cd2x-shimmer 1.4s infinite linear; }
@keyframes cd2x-shimmer { 0%{background-position:100% 0} 100%{background-position:-100% 0} }
.cd2x-proxy-manual {
  display: none; align-items: center; gap: 5px; margin-top: 2px;
  padding: 4px 10px; border-radius: 5px; cursor: pointer;
  background: rgba(99,102,241,.12); border: 1px solid rgba(99,102,241,.28);
  font-size: 10px; font-weight: 600; color: #8b8ef9;
}
.cd2x-proxy-manual:hover { background: rgba(99,102,241,.22); }

/* ── CUT DIFF 2.0 — Metadata bar (filename · STC · FRAME) ───────────────── */
.cd2x-meta-bar {
  display: flex; align-items: center; gap: 0;
  padding: 4px 12px; flex-shrink: 0;
  background: #080814; border-top: 1px solid #111124;
  font-size: 9px; font-family: 'SF Mono', 'Consolas', monospace;
  color: #4a4a72;
}
.cd2x-meta-side { flex: 1; display: flex; align-items: center; gap: 5px; overflow: hidden; }
.cd2x-meta-side-r { justify-content: flex-end; }
.cd2x-meta-name { color: #7070a8; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cd2x-meta-val { color: #b0b0d8; letter-spacing: 0.02em; }
.cd2x-meta-lbl { color: #36365a; text-transform: uppercase; font-size: 7px; letter-spacing: 0.08em; }
.cd2x-meta-sep { color: #22223a; }
.cd2x-meta-center { flex-shrink: 0; padding: 0 16px; color: #2a2a48; font-size: 7px; text-transform: uppercase; letter-spacing: 0.1em; white-space: nowrap; }

/* CUT DIFF 2.0 — two-column layout: left inspector + right content */
#main-cutdiff2 { flex-direction: row !important; }

.cd2x-left-col {
  flex: 0 0 260px;
  display: flex;
  flex-direction: column;
  border-right: 1px solid #1a1a2e;
