/* Hide: secondary/redundant fields */
.cd2x-main-col .cd2x-insp-row:has(#cd2x-insp-src-out)    { display: none !important; }
.cd2x-main-col .cd2x-insp-row:has(#cd2x-insp-rec-out)    { display: none !important; }
.cd2x-main-col .cd2x-insp-row:has(#cd2x-insp-fps)        { display: none !important; }
