/* Hide: note textarea, dividers, close button */
.cd2x-main-col .cd2x-insp-note-row  { display: none !important; }
.cd2x-main-col .cd2x-inspector .cd2x-insp-divider { display: none !important; }
.cd2x-main-col .cd2x-insp-close { display: none !important; }
/* Status + buttons: compact inline */
