.cd2x-main-col .cd2x-insp-save-btn { font-size: 9px !important; padding: 2px 7px !important; height: 20px !important; }
/* Empty state: show hint, hide hdr + body */
.cd2x-main-col .cd2x-inspector:not(.cd2x-insp-open) .cd2x-insp-hdr  { display: none !important; }
.cd2x-main-col .cd2x-inspector:not(.cd2x-insp-open) .cd2x-insp-body { display: none !important; }
