#main-cutdiff2 .cd2x-risk-btn[data-risk="med"]  { color: #E0B341 !important; border-color: rgba(224,179,65,.2) !important; }
#main-cutdiff2 .cd2x-risk-btn[data-risk="low"]  { color: #0AA356 !important; border-color: rgba(10,163,86,.2) !important; }
#main-cutdiff2 .cd2x-risk-btn[data-risk="high"].cd2x-risk-active { background: rgba(224,108,117,.12) !important; }
#main-cutdiff2 .cd2x-risk-btn[data-risk="med"].cd2x-risk-active  { background: rgba(224,179,65,.12) !important; }
#main-cutdiff2 .cd2x-risk-btn[data-risk="low"].cd2x-risk-active  { background: rgba(10,163,86,.12) !important; }

/* ── CUT DIFF 2.0: event table — readable sizes ── */
#main-cutdiff2 .cd2x-type-unchanged   { color: #6868a8 !important; }
#main-cutdiff2 .cd2x-type-trimmed     { color: #9090c8 !important; }
#main-cutdiff2 .cd2x-st-none          { color: #7070a8 !important; border-color: #2a2a48 !important; }
#main-cutdiff2 .cd2x-empty-state      { color: #6060a0 !important; }

/* ── CUT DIFF 2.0: inspector panel — size + color ── */
#main-cutdiff2 .cd2x-insp-event-num   { font-size: 11px !important; color: #8888b8 !important; }
#main-cutdiff2 .cd2x-insp-close       { font-size: 13px !important; color: #8080b8 !important; }
#main-cutdiff2 .cd2x-insp-divider     { font-size: 10px !important; color: #8080b8 !important; }
#main-cutdiff2 .cd2x-insp-lbl         { font-size: 11px !important; color: #8080b8 !important; }
#main-cutdiff2 .cd2x-insp-val         { font-size: 12px !important; color: #c0c0e0 !important; }
#main-cutdiff2 .cd2x-insp-val-mono    { font-size: 11px !important; color: #a8a8d0 !important; }
#main-cutdiff2 .cd2x-insp-select      { font-size: 11px !important; color: #b8b8d8 !important; }
#main-cutdiff2 .cd2x-insp-note        { font-size: 11px !important; color: #b8b8d8 !important; }
#main-cutdiff2 .cd2x-insp-save-btn    { font-size: 11px !important; }

/* ── CUT DIFF 2.0: video compare panel ── */
#main-cutdiff2 .cd2x-vc-title         { font-size: 11px !important; color: #8080b8 !important; }

/* ── CUT DIFF 2.0: HUD overlay ── */
#main-cutdiff2 .cd-vcmp-hud           { font-size: 13px !important; }
#main-cutdiff2 .cd-vcmp-hud .pill     { font-size: 13px !important; padding: 5px 10px !important; background: rgba(0,0,0,.6) !important; border-radius: 4px !important; border: none !important; }
#main-cutdiff2 .cd2x-vc-slot-tag.cd2x-vc-slot-new { color: #0AA356 !important; }


/* =============================================================
 * PLATE LINK 2.0  (.pl2-*)
 * Accent: #2172E3 (teal)   Background: #07070e
 * ============================================================= */

/* ── Tab theme ── */
.tab.theme-pl2 .bar        { background: #2172E3; }
.tab.theme-pl2.active      { color: #2172E3; }

/* ── Pane shell ── */
/* JS sets style.display="flex" when activating this tab (see setMainTab) */
#main-platelink2 {
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: #07070e;
  position: relative;
}

/* ── Context bar ── */
.pl2-ctx-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  background: #0b0b18;
  border-bottom: 1px solid #181830;
  flex-shrink: 0;
  flex-wrap: nowrap;
  overflow: hidden;
}
.pl2-ctx-brand {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-right: 4px;
  flex-shrink: 0;
}
.pl2-ctx-title {
  font-size: 11px;
  font-weight: 800;
  color: #2172E3;
  letter-spacing: .06em;
  white-space: nowrap;
}
.pl2-ctx-chip {
  font-size: 11px;
  color: #7878a0;
  background: #0e0e20;
  border: 1px solid #1e1e38;
  border-radius: 999px;
  padding: 1px 8px;
  white-space: nowrap;
  flex-shrink: 0;
}
.pl2-chip-accent { color: #2172E3; border-color: #182858; background: #060e20; }
.pl2-chip-ok     { color: #0AA356; border-color: #1a3028; background: #061410; }
.pl2-ctx-spacer  { flex: 1; min-width: 0; }
.pl2-ctx-seqlabel {
  font-size: 9px;
  color: #3a3a58;
  letter-spacing: .05em;
  flex-shrink: 0;
}
.pl2-seq-input {
  width: 56px;
  font-size: 10px;
  font-family: monospace;
  background: #0e0e1c;
  border: 1px solid #1e1e30;
  border-radius: 3px;
  color: #a0a0c8;
  padding: 1px 5px;
  outline: none;
  flex-shrink: 0;
}
.pl2-seq-input:focus { border-color: rgba(110,168,240,.4); color: #c8c8e8; }
.pl2-ctx-btn {
  font-size: 10px;
  font-weight: 700;
  background: #111120;
  border: 1px solid #252540;
  color: #555;
  border-radius: 3px;
  padding: 2px 9px;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
  transition: color .1s, border-color .1s, background .1s;
}
.pl2-ctx-btn:hover { color: #aaa; border-color: #3a3a58; background: #18182a; }
/* Import VFX Folder — primary CTA, cyan-teal glow */
.pl2-ctx-btn-scan {
  display: inline-flex; align-items: center;
  color: #74b0c9 !important; border-color: #1a4060 !important;
  background: linear-gradient(135deg, #05141e 0%, #071e2e 100%) !important;
  box-shadow: 0 0 8px rgba(114,230,255,0.18) !important;
  padding: 3px 11px !important; border-radius: 4px !important;
  font-size: 10.5px !important; letter-spacing: 0.2px;
  transition: background 0.12s, box-shadow 0.12s, color 0.12s !important;
}
.pl2-ctx-btn-scan:hover {
  color: #a0f0ff !important; border-color: #2a6080 !important;
  background: linear-gradient(135deg, #071e2e 0%, #0a2a40 100%) !important;
  box-shadow: 0 0 14px rgba(114,230,255,0.32) !important;
}
.pl2-ctx-btn-build  { color: #2172E3 !important; border-color: #1a3060 !important; background: #060e22 !important; }
.pl2-ctx-btn-build:hover { background: #071428 !important; color: #7ae8e2 !important; }
.pl2-ctx-btn-export { color: #E0B341 !important; border-color: #4a3a10 !important; background: #1a1408 !important; }
.pl2-ctx-btn-export:hover { background: #242010 !important; color: #f0d090 !important; }
.pl2-export-wrap { position: relative; }
.pl2-export-menu {
  position: absolute;
  right: 0; top: calc(100% + 3px);
  z-index: 9999;
  background: #141428;
  border: 1px solid #282848;
  border-radius: 5px;
  overflow: hidden;
  min-width: 200px;
  box-shadow: 0 8px 28px rgba(0,0,0,.6);
}
.pl2-export-menu button {
  display: block; width: 100%; text-align: left;
  padding: 7px 14px; font-size: 10px;
  color: #a0a0c0; background: none; border: none;
  cursor: pointer; white-space: nowrap;
}
.pl2-export-menu button:hover { background: #1e1e38; color: #2172E3; }

/* ── Filter bar ── */
.pl2-filter-bar {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 5px 10px;
  background: #09091a;
  border-bottom: 1px solid #16163a;
  flex-shrink: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.pl2-filter-bar::-webkit-scrollbar { display: none; }
.pl2-filter-label { font-size: 9.5px; color: #5858a0; letter-spacing: .06em; flex-shrink: 0; }
.pl2-filter-sep   { width: 1px; background: #1e1e3a; height: 12px; margin: 0 5px; flex-shrink: 0; }
.pl2-filter-spacer { flex: 1; min-width: 8px; }
.pl2-sel-all-wrap { display: flex; align-items: center; flex-shrink: 0; cursor: pointer; }
.pl2-sel-all-wrap input[type=checkbox] { accent-color: #2172E3; cursor: pointer; margin: 0; }
.pl2-sel-meta { font-size: 10px; color: #5858a0; font-family: monospace; flex-shrink: 0; }
/* New button themes for 2.0 action bar */
.pl2-ctx-btn-ae    { color: #9b59b6 !important; border-color: #3a1a5a !important; background: #120a1e !important; }
.pl2-ctx-btn-ae:hover { background: #1e1030 !important; color: #c278ee !important; }
.pl2-ctx-btn-nuke  { color: #E0B341 !important; border-color: #4a3a10 !important; background: #1a1408 !important; }
.pl2-ctx-btn-nuke:hover { background: #242010 !important; color: #f0d090 !important; }
.pl2-ctx-btn-shots { color: #2172E3 !important; border-color: #1a3060 !important; background: #060e20 !important; }
.pl2-ctx-btn-shots:hover { background: #071428 !important; color: #7ae8e2 !important; }
.pl2-filter-btn {
  font-size: 10px;
  padding: 2px 9px;
  border: 1px solid #1e1e3c;
  border-radius: 3px;
  background: transparent;
  color: #5858a0;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
  transition: color .12s, border-color .12s, background .12s;
}
.pl2-filter-btn:hover        { color: #90c0f8; border-color: rgba(110,168,240,.35); }
.pl2-filter-btn.pl2-filter-active {
  color: #2172E3;
  border-color: rgba(110,168,240,.55);
  background: rgba(110,168,240,.08);
}
.pl2-filter-select {
  font-size: 10px;
  background: #0e0e1e;
  border: 1px solid #1e1e3c;
  border-radius: 3px;
  color: #7878b0;
  padding: 1px 5px;
  outline: none;
  flex-shrink: 0;
}
.pl2-search {
  font-size: 10px;
  background: #0a0a18;
  border: 1px solid #1e1e3c;
  border-radius: 3px;
  color: #b0b0d0;
  padding: 3px 9px;
  outline: none;
  width: 180px;
  flex-shrink: 0;
}
.pl2-search::placeholder { color: #3a3a60; }
.pl2-search:focus { border-color: rgba(110,168,240,.45); background: #0c0c1e; }

/* ── Split body ── */
.pl2-body {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

/* ── Left: text-only shot list ── */
.pl2-left {
  flex: 0 0 34%;
  min-width: 180px;
  max-width: 380px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-right: 1px solid #18183a;
  background: #07070f;
}
.pl2-shotlist {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: #1e1e38 transparent;
  /* GPU-composited scroll layer */
  contain: strict;
  will-change: scroll-position;
}
.pl2-shotlist::-webkit-scrollbar { width: 3px; }
.pl2-shotlist::-webkit-scrollbar-thumb { background: #1e1e38; border-radius: 2px; }
/* Empty state */
.pl2-sl-group { display: block; }
.pl2-sl-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 32px 16px;
  text-align: center;
}
.pl2-sl-empty-title { font-size: 11px; color: #5858a0; font-weight: 600; }
.pl2-sl-empty-hint  { font-size: 9.5px; color: #3a3a68; line-height: 1.5; }

/* ── Group header ── */
.pl2-sl-ghdr {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px 6px 12px;
  background: #0c0c22;
  border-top: 1px solid #1e1e40;
  border-bottom: 1px solid #141430;
  cursor: pointer;
  user-select: none;
  position: sticky;
  top: 0;
  z-index: 2;
  transition: background .12s;
}
.pl2-sl-ghdr:hover { background: #111130; }
.pl2-sl-caret {
  width: 5px;
  height: 5px;
  border-right: 1.5px solid #5858a0;
  border-bottom: 1.5px solid #5858a0;
  transform: rotate(-45deg);
  flex-shrink: 0;
  margin-bottom: -2px;
  transition: transform .15s, border-color .12s;
}
.pl2-sl-ghdr:hover .pl2-sl-caret { border-color: #90c0f8; }
.pl2-sl-open > .pl2-sl-ghdr .pl2-sl-caret {
  transform: rotate(45deg);
  margin-bottom: 0;
}
.pl2-sl-gname {
  font-size: 11px;
  font-weight: 700;
  color: #2172E3;
  letter-spacing: .04em;
  font-family: monospace;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
/* Group info: progress bar + count */
.pl2-sl-ginfo {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.pl2-sl-gprog {
  width: 40px;
  height: 4px;
  background: #1a1a38;
  border-radius: 3px;
  overflow: hidden;
}
.pl2-sl-gprog-fill {
  height: 100%;
  border-radius: 3px;
  transition: width .3s;
}
.pl2-sl-gstat {
  font-size: 9.5px;
  color: #6868a8;
  font-family: monospace;
  white-space: nowrap;
  min-width: 28px;
  text-align: right;
}

/* ── Shot row ── */
.pl2-sl-shot {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px 6px 12px;
  border-bottom: 1px solid #0c0c1c;
  border-left: 3px solid transparent;
  cursor: pointer;
  transition: background .1s;
}
.pl2-sl-shot:hover { background: #0e0e22; }
.pl2-sl-active {
  background: #0f1030 !important;
  border-left-color: #2172E3 !important;
}
.pl2-sl-active:hover { background: #111235 !important; }
/* Checkbox */
.pl2-sl-check {
  accent-color: #2172E3;
  flex-shrink: 0;
  cursor: pointer;
  width: 11px;
  height: 11px;
}
/* Tail name (shot suffix after group key) */
.pl2-sl-tail {
  font-size: 11px;
  color: #a8a8c8;
  font-family: monospace;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  letter-spacing: .01em;
}
.pl2-sl-active .pl2-sl-tail { color: #e0e0f8; font-weight: 600; }
/* SEQ / EDL / CDL chips */
.pl2-sl-chips {
  display: flex;
  gap: 2px;
  flex-shrink: 0;
}
.pl2-sl-chip {
  font-size: 8px;
  font-weight: 700;
  padding: 1px 4px;
  border-radius: 2px;
  letter-spacing: .05em;
  line-height: 1.5;
  border: 1px solid transparent;
}
.pl2-sl-chip.ok   { background: rgba(10,163,86,.12); color: #0AA356; border-color: rgba(10,163,86,.25); }
.pl2-sl-chip.miss { background: rgba(224,108,117,.12); color: #E5484D; border-color: rgba(224,108,117,.28); }
.pl2-sl-chip.none { background: rgba(30,30,60,.6);    color: #4a4a78; border-color: rgba(60,60,100,.3); }
/* Frame count badge */
.pl2-sl-fr {
  font-size: 9px;
  color: #6868a0;
  font-family: monospace;
  flex-shrink: 0;
  background: #0e0e22;
  padding: 1px 5px;
  border-radius: 3px;
  border: 1px solid #1a1a38;
  white-space: nowrap;
}

/* ── Right: QT player + detail ── */
.pl2-right {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #070710;
}
/* QuickTime preview area — fills all remaining right-panel space */
.pl2-qt-wrap {
  flex: 1;
  min-height: 0;
  position: relative;
  background: #000;
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid #111228;
  /* Own compositing layer — video decode stays on GPU, not mixed with page paint */
  isolation: isolate;
  contain: layout style;
}
.pl2-qt-video {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  /* Force hardware-accelerated compositing for video playback */
  transform: translateZ(0);
  backface-visibility: hidden;
  will-change: transform;
}
.pl2-qt-hint,
.pl2-qt-no-ref {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  pointer-events: none;
}
/* Re-link button shown when permission needs user gesture */
.pl2-relink-btn {
  pointer-events: all;
  margin-top: 6px;
  padding: 5px 14px;
  border-radius: 4px;
  border: 1px solid rgba(97,175,239,0.5);
  background: rgba(97,175,239,0.08);
  color: #2172E3;
  font-size: 10px;
  cursor: pointer;
  transition: background 0.15s;
}
.pl2-relink-btn:hover { background: rgba(97,175,239,0.18); }
.pl2-relink-btn:disabled { opacity: 0.5; cursor: default; }
.pl2-qt-hint p,
.pl2-qt-no-ref span {
  margin: 0;
  font-size: 11px;
  color: rgba(255,255,255,0.35);
}
/* Shot detail — compact fixed height below player */
.pl2-detail-area {
  flex: 0 0 160px;
  overflow-y: auto;
  min-height: 0;
  scrollbar-width: thin;
  scrollbar-color: #1e1e38 transparent;
}
.pl2-detail-area::-webkit-scrollbar { width: 4px; }
.pl2-detail-area::-webkit-scrollbar-thumb { background: #1e1e38; border-radius: 2px; }

/* ── Toolbar ── */
.pl2-toolbar {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  background: #0a0a18;
  border-bottom: 1px solid #111128;
  flex-shrink: 0;
}
.pl2-toolbar-label {
  font-size: 9px;
  font-weight: 700;
  color: #3a3a58;
  letter-spacing: .06em;
}
.pl2-toolbar-spacer { flex: 1; }
.pl2-mini-btn {
  font-size: 10px;
  padding: 2px 7px;
  background: #111120;
  border: 1px solid #1e1e38;
  border-radius: 3px;
  color: #555;
  cursor: pointer;
  transition: color .1s, border-color .1s;
}
.pl2-mini-btn:hover { color: #aaa; border-color: #3a3a58; }
.pl2-mini-hdl { color: #2172E3 !important; border-color: #182858 !important; }
.pl2-mini-hdl:hover { background: #060e22 !important; }

/* ── Table ── */
.pl2-thead-wrap {
  flex-shrink: 0;
  overflow: hidden;
  background: #0a0a18;
  border-bottom: 1px solid #181834;
}
.pl2-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 10px;
  table-layout: fixed;
}
.pl2-table th {
  padding: 5px 6px;
  font-size: 9px;
  font-weight: 700;
  color: #3a3a58;
  text-align: left;
  letter-spacing: .04em;
  white-space: nowrap;
  overflow: hidden;
}
.pl2-th-shot   { width: 110px; }
.pl2-th-plate  { width: 90px;  }
.pl2-th-clip   { width: 100px; }
.pl2-th-dur    { width: 52px;  }
.pl2-th-hdl    { width: 40px;  }
.pl2-th-status { width: 80px;  }
.pl2-th-v      { width: 48px; font-size: 8px !important; }
.pl2-th-vendors { }

/* Scroll body */
.pl2-scroll-wrap {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  position: relative;
  scrollbar-width: thin;
  scrollbar-color: #1e1e38 transparent;
}
.pl2-scroll-wrap::-webkit-scrollbar { width: 4px; }
.pl2-scroll-wrap::-webkit-scrollbar-thumb { background: #1e1e38; border-radius: 2px; }
.pl2-tbody-tbl { width: 100%; border-collapse: collapse; }
.pl2-row {
  cursor: pointer;
  transition: background .06s;
}
.pl2-row:hover td { background: #0d0d22; }
.pl2-row.pl2-row-active td { background: #111230 !important; }
.pl2-row.pl2-row-active .pl2-td-pip { border-left: 2px solid #2172E3; }
.pl2-row td {
  padding: 4px 6px;
  vertical-align: middle;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border-bottom: 1px solid #0e0e1e;
  color: #8888b0;
}
.pl2-dot {
  display: block;
  width: 3px;
  height: 22px;
  border-radius: 0 1px 1px 0;
}
.pl2-shot-code { color: #c0c0e0; font-family: monospace; font-size: 10px; }
.pl2-td-dur, .pl2-td-hdl { font-family: monospace; font-size: 9px; color: #5a5a80; }
.pl2-hdl-warn { color: #E0B341 !important; }
.pl2-sbtn {
  font-size: 9px;
  font-weight: 700;
  padding: 1px 5px;
  border: 1px solid;
  border-radius: 2px;
  cursor: pointer;
  letter-spacing: .03em;
  transition: opacity .1s;
  background: transparent;
}
.pl2-sbtn:hover { opacity: .75; }
.pl2-vbtn {
  font-size: 10px;
  background: transparent;
  border: 1px solid #1a1a30;
  border-radius: 2px;
  color: #404060;
  cursor: pointer;
  width: 22px; height: 18px;
  display: inline-flex; align-items: center; justify-content: center;
  transition: color .1s, border-color .1s;
}
.pl2-vbtn:hover          { color: #aaa; border-color: #3a3a58; }
.pl2-vbtn-assigned       { color: #2172E3; border-color: #1a3060; }
.pl2-vbtn-pulling        { color: #2172E3; border-color: #1a3050; }
.pl2-vbtn-pulled         { color: #0AA356; border-color: #1a4030; }
.pl2-vbtn-delivered      { color: #E0B341; border-color: #4a3a10; }

/* ── Inspector (right panel, inside .pl2-detail-area) ── */
.pl2-insp-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 120px;
  gap: 10px;
  color: #3a3a58;
  font-size: 11px;
  text-align: center;
  padding: 24px;
}
.pl2-insp-empty p { margin: 0; }
.pl2-insp-hint { font-size: 11px; color: #5858a0; }
.pl2-insp-hint strong { color: #2172E3; }
.pl2-insp-detail {
  overflow-y: auto;
  overflow-x: hidden;
  padding: 6px 8px;
  scrollbar-width: thin;
  scrollbar-color: #1e1e38 transparent;
  flex: 1;
  min-height: 0;
}

/* 3-column compact inspector */
.pl2-insp-3col {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 0 8px;
  min-height: 0;
}
.pl2-insp-col {
  border-right: 1px solid #111228;
  padding-right: 8px;
  min-width: 0;
}
.pl2-insp-col:last-child { border-right: none; padding-right: 0; }
.pl2-insp-col-title {
  font-size: 9.5px;
  font-weight: 700;
  color: #6060a0;
  letter-spacing: .10em;
  text-transform: uppercase;
  margin-bottom: 4px;
  padding-bottom: 3px;
  border-bottom: 1px solid #1a1a30;
}
.pl2-insp-row {
  display: flex;
  align-items: baseline;
  gap: 4px;
  padding: 1px 0;
  font-size: 11px;
  line-height: 1.5;
  min-width: 0;
}
.pl2-insp-row .k {
  color: #7878a8;
  flex-shrink: 0;
  width: 60px;
  font-size: 10.5px;
}
.pl2-insp-row .v {
  color: #c0c0d8;
  font-family: monospace;
  font-size: 10.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.pl2-insp-row .v.good  { color: #0AA356; }
.pl2-insp-row .v.warn  { color: #E0B341; }
.pl2-insp-row .v.bad   { color: #E5484D; }
.pl2-insp-status-chips {
  display: flex;
  gap: 4px;
  margin-bottom: 5px;
}
.pl2-insp-chip {
  font-size: 10px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 2px;
  letter-spacing: .06em;
}
.pl2-insp-chip.ok   { color: #0AA356; background: #0a180e; border: 1px solid #1a2e22; }
.pl2-insp-chip.miss { color: #E5484D; background: #18080a; border: 1px solid #2e1a1a; }
.pl2-insp-chip.none { color: #6060a0; background: #0a0a14; border: 1px solid #1c1c30; }

/* EDL event block */
.pl2-insp-evt {
  margin-bottom: 5px;
  padding-bottom: 4px;
  border-bottom: 1px solid #131325;
}
.pl2-insp-evt:last-child { border-bottom: none; margin-bottom: 0; }
.pl2-insp-evt-hdr {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 10.5px;
  font-family: monospace;
  color: #9090b8;
  margin-bottom: 2px;
}
.pl2-insp-evt-num  { color: #6060a0; font-size: 10px; }
.pl2-insp-evt-tc   { color: #a0a0c8; }
.pl2-insp-evt-dur  { color: #7878a8; margin-left: auto; }
.pl2-insp-evt-speed { color: #E0B341; font-size: 10px; margin-left: 3px; }
.pl2-insp-cmnt {
  font-size: 10px;
  color: #8888b0;
  font-family: monospace;
  padding: 0 2px;
  white-space: pre-wrap;
  word-break: break-all;
  line-height: 1.4;
}
.pl2-insp-cmnt.cmnt-clip  { color: #2172E3; }
.pl2-insp-cmnt.cmnt-asc   { color: #a386ba; }
.pl2-insp-cmnt.cmnt-cdl   { color: #a386ba; }
.pl2-insp-cmnt.cmnt-speed { color: #E0B341; }
.pl2-insp-cmnt.cmnt-vfx   { color: #2172E3; }
.pl2-insp-shotname {
  font-size: 11px;
  font-weight: 800;
  font-family: monospace;
  color: #c0c0e0;
  letter-spacing: .04em;
  margin-bottom: 5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pl2-insp-hdr {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid #181830;
}
.pl2-insp-code {
  font-size: 13px;
  font-weight: 800;
  font-family: monospace;
  color: #d0d0f0;
  letter-spacing: .04em;
}
.pl2-insp-badge {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .06em;
}
.pl2-insp-sect { margin-bottom: 12px; }
.pl2-insp-sect-title {
  font-size: 8px;
  font-weight: 700;
  color: #3a3a58;
  letter-spacing: .1em;
  margin-bottom: 5px;
  overflow: hidden; /* clearfix for float:right children */
}
.pl2-insp-kv {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
  font-size: 10px;
}
.pl2-insp-kv .k { color: #404060; min-width: 70px; flex-shrink: 0; }
.pl2-insp-kv .v { color: #9898c0; }
.pl2-insp-kv .mono { font-family: monospace; font-size: 10px; }
.pl2-insp-covbar {
  height: 3px;
  background: #181830;
  border-radius: 2px;
  margin: 4px 0;
  overflow: hidden;
}
.pl2-insp-covfill { height: 100%; border-radius: 2px; transition: width .3s; }
.pl2-insp-handles-row .pl2-insp-hdl-input {
  width: 48px;
  font-size: 10px;
  font-family: monospace;
  background: #111120;
  border: 1px solid #1e1e38;
  border-radius: 3px;
  color: #a0a0c8;
  padding: 1px 5px;
  outline: none;
}
.pl2-insp-vrow {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 0;
  border-bottom: 1px solid #0e0e1e;
}
.pl2-insp-vname { font-size: 9px; color: #5a5a80; min-width: 70px; flex-shrink: 0; }
.pl2-insp-vbtns { display: flex; gap: 2px; flex-wrap: wrap; }
.pl2-insp-vst {
  font-size: 8px;
  padding: 1px 5px;
  background: #111120;
  border: 1px solid #1e1e30;
  border-radius: 2px;
  color: #404060;
  cursor: pointer;
  transition: color .1s, border-color .1s, background .1s;
}
.pl2-insp-vst:hover { color: #aaa; border-color: #3a3a58; }
.pl2-insp-vst.active { color: #2172E3; border-color: rgba(110,168,240,.5); background: rgba(110,168,240,.08); }
.pl2-insp-no-vend { font-size: 10px; color: #2a2a48; padding: 6px 0; }
.pl2-insp-notes {
  width: 100%;
  min-height: 56px;
  background: #0e0e1c;
  border: 1px solid #1e1e38;
  border-radius: 3px;
  color: #8888b0;
  font-size: 10px;
  padding: 5px 7px;
  resize: vertical;
  outline: none;
  font-family: inherit;
  box-sizing: border-box;
}
.pl2-insp-notes:focus { border-color: rgba(110,168,240,.35); }

/* ── Inspector: truncate long paths ── */
.pl2-insp-truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 160px;
  display: inline-block;
  vertical-align: middle;
}
/* ── Copy-path button ── */
.pl2-copy-btn {
  background: none;
  border: 1px solid #1e1e38;
  border-radius: 3px;
  color: #3a3a58;
  font-size: 10px;
  padding: 0 4px;
  cursor: pointer;
  margin-left: 4px;
  flex-shrink: 0;
  line-height: 1.4;
  transition: color .1s, border-color .1s;
}
.pl2-copy-btn:hover { color: #2172E3; border-color: rgba(110,168,240,.4); }
/* ── Frame verify bar ── */
.pl2-frame-bar {
  height: 3px;
  background: #181830;
  border-radius: 2px;
  overflow: hidden;
  margin-top: 6px;
  margin-bottom: 4px;
}
.pl2-frame-bar-fill { height: 100%; border-radius: 2px; transition: width .3s; }
/* ── EDL event duration label ── */
.pl2-insp-dur { color: #3a3a58; margin-left: 4px; font-size: 9px; }

/* ── EDL event card ── */
.pl2-edl-card {
  background: #0c0c1c;
  border: 1px solid #1a1a2e;
  border-radius: 4px;
  margin-bottom: 8px;
  overflow: hidden;
}
.pl2-edl-card-hdr {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  background: #0e0e20;
  border-bottom: 1px solid #1a1a2e;
}
.pl2-edl-evnum {
  font-size: 8px;
  font-weight: 700;
  color: #3a3a58;
  letter-spacing: .06em;
}
.pl2-edl-tc {
  font-family: monospace;
  font-size: 10px;
  color: #9898c0;
  flex: 1;
}
.pl2-edl-fr {
  font-family: monospace;
  font-size: 9px;
  color: #404060;
}
.pl2-edl-speed {
  font-size: 9px;
  padding: 1px 5px;
  border-radius: 3px;
  font-family: monospace;
  background: #1a1228;
  color: #a386ba;
  margin-left: 4px;
}
.pl2-edl-speed.warn { background: #1e150a; color: #E0B341; }
.pl2-edl-card-body { padding: 5px 8px; }
.pl2-edl-meta-row {
  display: flex;
  gap: 16px;
  margin-bottom: 4px;
}
.pl2-edl-meta-item { font-size: 9px; }
.pl2-edl-meta-item .k { color: #303050; margin-right: 4px; }
.pl2-edl-meta-item .v { color: #6060a0; font-family: monospace; }
/* Comments block */
.pl2-edl-comments {
  margin-top: 5px;
  border-top: 1px solid #141428;
  padding-top: 4px;
}
.pl2-edl-cmnt-hdr {
  font-size: 8px;
  font-weight: 700;
  color: #2a2a48;
  letter-spacing: .06em;
  margin-bottom: 3px;
}
.pl2-edl-cmnt-line {
  font-family: monospace;
  font-size: 9px;
  color: #505078;
  white-space: pre-wrap;
  word-break: break-all;
  line-height: 1.5;
  padding: 1px 0;
}
/* Comment line type highlights */
.pl2-edl-cmnt-line.cmnt-clip   { color: #2172E3; }
.pl2-edl-cmnt-line.cmnt-cdl   { color: #0AA356; }
.pl2-edl-cmnt-line.cmnt-speed { color: #a386ba; }
.pl2-edl-cmnt-line.cmnt-asc   { color: #0AA356; }
.pl2-edl-cmnt-line.cmnt-vfx   { color: #E0B341; }
/* Inspector 2-col grid for STATUS */
.pl2-insp-status-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 4px;
  margin-bottom: 6px;
}
.pl2-insp-scard {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 5px 4px;
  border-radius: 4px;
  border: 1px solid #181830;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .05em;
  text-align: center;
  gap: 2px;
}
.pl2-insp-scard.ok  { border-color: #1a2e22; color: #0AA356; background: #0a180e; }
.pl2-insp-scard.miss { border-color: #2e1a1a; color: #E5484D; background: #18080a; }
.pl2-insp-scard.none { border-color: #181828; color: #3a3a58; background: #0a0a14; }
.pl2-insp-scard-icon { font-size: 12px; margin-bottom: 1px; }
/* EXR info table-like */
.pl2-exr-grid {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: 2px 8px;
  font-size: 9px;
}
.pl2-exr-grid .k { color: #404060; }
.pl2-exr-grid .v { color: #9898c0; font-family: monospace; }

/* ── Timeline strip ── */
.pl2-timeline-strip {
  flex-shrink: 0;
  background: #08080f;
  border-top: 1px solid #121228;
}
.pl2-tl-hdr {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 10px;
  border-bottom: 1px solid #0e0e1e;
}
.pl2-tl-label { font-size: 8px; font-weight: 700; color: #3a3a58; letter-spacing: .08em; }
.pl2-tl-legend { display: flex; gap: 8px; }
.pl2-tl-leg-item { font-size: 8px; color: #303050; }
.pl2-tl-leg-shot  { color: #2172E355; }
.pl2-tl-leg-plate { color: #E5484D55; }
.pl2-cov-stats { font-size: 9px; color: #505070; margin-left: auto; font-family: monospace; }
.pl2-tl-canvas { display: block; width: 100%; height: 80px; cursor: crosshair; }

/* ── Toast ── */
.pl2-toast {
  position: absolute;
  bottom: 100px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  padding: 6px 16px;
  border-radius: 4px;
  pointer-events: none;
  z-index: 9999;
  white-space: nowrap;
  animation: pl2-fadein .15s ease;
}
.pl2-toast-info { background: #071428; border: 1px solid #1a3868; color: #2172E3; }
.pl2-toast-warn { background: #2a1808; border: 1px solid #5a3010; color: #E0B341; }
@keyframes pl2-fadein { from { opacity:0; transform: translateX(-50%) translateY(6px); } to { opacity:1; transform: translateX(-50%) translateY(0); } }

/* ── PLATE LINK 2.0: Import button + drag-over ── */
.pl2-ctx-btn-import {
  color: #a0c8e0 !important;
  border-color: #1a3050 !important;
  background: #060e18 !important;
}
.pl2-ctx-btn-import:hover {
  background: #0d1e2e !important;
  color: #c8e4f8 !important;
}
#main-platelink2.pl2-drag-over {
  outline: 2px dashed rgba(110,168,240,.5);
  outline-offset: -4px;
}
#main-platelink2.pl2-drag-over::after {
  content: 'Drop VFX delivery folder here';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  color: #2172E3;
  background: rgba(6,20,18,.85);
  letter-spacing: .08em;
  pointer-events: none;
  z-index: 100;
}

/* ── PLATE LINK 2.0: Scan / CSV buttons ── */
/* (scan button styled above near line 40769) */
.pl2-lang-sel { background: #0e0e1a; color: #539c95; border: 1px solid #1a2a38; border-radius: 3px; font-size: 9px; font-family: monospace; padding: 2px 4px; cursor: pointer; outline: none; margin-right: 4px; }
.pl2-lang-sel:hover { border-color: #539c95; }
.pl2-lang-sel option { background: #0e0e1a; color: #c0c0d0; }
.pl2-ctx-btn-csv  { color: #a0c0e0 !important; border-color: #1a3050 !important; background: #060e18 !important; }
.pl2-ctx-btn-csv:hover  { background: #0d1e2e !important; color: #c8e4f8 !important; }
.pl2-chip-warn { color: #E0B341 !important; border-color: #4a3a10 !important; background: #1a1408 !important; }

/* ── Progress bar ── */
.pl2-progress-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  background: #0b0b18;
  border-bottom: 1px solid #1a1a30;
  flex-shrink: 0;
}
.pl2-progress-track {
  flex: 1;
  height: 5px;
  background: #1a1a30;
  border-radius: 3px;
  overflow: hidden;
}
.pl2-progress-bar {
  height: 100%;
  background: linear-gradient(90deg, #2172E3, #0AA356);
  border-radius: 3px;
  transition: width .12s linear;
  min-width: 4px;
}
.pl2-progress-label {
  font-size: 9px;
  color: #9898b8;
  white-space: nowrap;
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  flex-shrink: 1;
}
.pl2-progress-pct {
  font-size: 9px;
  font-family: monospace;
  color: #2172E3;
  min-width: 28px;
  text-align: right;
  flex-shrink: 0;
}

/* ── Table columns (delivery manifest) ── */
.pl2-th-pip   { width: 5px;  }
.pl2-th-shot  { }
.pl2-th-pl    { width: 46px; }
.pl2-th-ver   { width: 38px; }
.pl2-th-clip  { }
.pl2-th-tc    { width: 78px; font-family: monospace; }
.pl2-th-dur   { width: 50px; }
.pl2-th-exr   { width: 38px; }
.pl2-th-qt    { width: 24px; text-align: center; }
.pl2-th-amf   { width: 30px; text-align: center; }
.pl2-th-int   { width: 24px; text-align: center; }
.pl2-th-edl   { width: 24px; text-align: center; }
.pl2-th-stat  { width: 80px; }
.pl2-td-pip   { padding: 0 !important; width: 5px; }
.pl2-pip      { display: block; width: 3px; height: 24px; border-radius: 0 1px 1px 0; }
.pl2-td-shot  .pl2-shot-code { font-family: monospace; font-size: 10px; color: #c0c0e0; }
.pl2-td-pl    { font-family: monospace; font-size: 10px; color: #2172E3; font-weight: 700; }
.pl2-td-ver   { font-family: monospace; font-size: 9px;  color: #505070; }
.pl2-td-clip  { font-family: monospace; font-size: 9px;  color: #7878a0; }
.mono         { font-family: monospace !important; }
.pl2-td-tc    { font-family: monospace; font-size: 9px; color: #606080; }
.pl2-td-dur   { font-family: monospace; font-size: 9px; color: #5a5a80; }
.pl2-td-exr   { font-family: monospace; font-size: 9px; color: #5a5a80; text-align: right; padding-right: 8px !important; }
.pl2-td-qt, .pl2-td-amf, .pl2-td-integ, .pl2-td-edl { text-align: center; font-size: 10px; }
.pl2-ok-icon      { color: #0AA356; }
.pl2-warn-icon    { color: #E0B341; }
.pl2-na-icon      { color: #2a2a48; }
.pl2-linked-icon  { color: #2172E3; font-size: 10px; }
.pl2-unlinked-icon{ color: #2a2a40; font-size: 10px; }
.pl2-stat-badge   { font-size: 8px; font-weight: 700; letter-spacing: .04em; padding: 1px 4px; border: 1px solid; border-radius: 2px; white-space: nowrap; }
.pl2-stat-completed { color: #0AA356 !important; border-color: #0AA35622 !important; }
.pl2-stat-partial   { color: #E0B341 !important; border-color: #E0B34122 !important; }
.pl2-stat-missing   { color: #E5484D !important; border-color: #E5484D22 !important; }
.pl2-stat-pending   { color: #2172E3 !important; border-color: #2172E322 !important; }
.pl2-stat-unknown   { color: #3a3a58 !important; border-color: #1e1e30 !important; }
.pl2-td-shot { min-width: 110px; color: #c0c0e0; font-family: monospace; font-size: 10px; }
.pl2-td-tc   { font-family: monospace; font-size: 9px; color: #606080; }

/* ── Empty state ── */
.pl2-empty-state {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  pointer-events: none;
  padding: 32px;
}
.pl2-empty-title { font-size: 12px; color: #3a3a58; font-weight: 700; }
.pl2-empty-hint  { font-size: 10px; color: #282840; text-align: center; line-height: 1.5; }
.pl2-empty-pattern code { font-family: monospace; color: #404060; }


.pfx-qc2-shell {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 0;
  gap: 0;
}

/* Drop row */
.pfx-qc2-droprow {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  background: #12121e;
  border-bottom: 1px solid #1e1e30;
  flex-shrink: 0;
}
.pfx-qc2-dropzone {
  flex: 1;
  min-height: 36px;
  border: 1.5px dashed #2a2a44;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #6060a0;
  cursor: pointer;
  padding: 6px 12px;
  transition: border-color 0.15s, background 0.15s;
}
.pfx-qc2-dropzone.drag-over {
  border-color: #6060e0;
  background: rgba(80,80,200,0.08);
  color: #a0a0ff;
}
.pfx-qc2-drop-icon { font-size: 14px; margin-right: 6px; opacity: 0.6; }
.pfx-qc2-browse-label { color: #8080c0; cursor: pointer; text-decoration: underline; margin-left: 4px; }
.pfx-qc2-file-input { display: none; }
.pfx-qc2-fileinfo {
  flex: 1;
  font-size: 11px;
  color: #a0a0c0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.pfx-qc2-file-name { font-weight: 600; color: #c0c0e0; font-family: monospace; }
.pfx-qc2-clear-btn {
  background: none;
  border: none;
  color: #E5484D;
  cursor: pointer;
  font-size: 13px;
  padding: 0 4px;
  line-height: 1;
}
.pfx-qc2-clear-btn:hover { color: #ff4040; }

/* Sub-tab bar */
.pfx-qc2-subtabs {
  display: flex;
  gap: 2px;
  padding: 6px 14px 0;
  background: #10101c;
  border-bottom: 1px solid #1e1e30;
  flex-shrink: 0;
}
.pfx-qc2-stab {
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: #50507a;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 6px 14px 5px;
  cursor: pointer;
  transition: color 0.15s, border-color 0.15s;
  text-transform: uppercase;
}
.pfx-qc2-stab:hover { color: #9090c0; }
.pfx-qc2-stab.active {
  color: #c0c0ff;
  border-bottom-color: #6060e0;
}

/* Panel wrapper */
.pfx-qc2-panelwrap {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.pfx-qc2-panel {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* Panel header */
.pfx-qc2-panelhead {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-shrink: 0;
}
.pfx-qc2-paneltitle {
  font-size: 12px;
  font-weight: 700;
  color: #c0c0ff;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.pfx-qc2-muted { font-size: 10px; color: #40405a; }

/* Controls row */
.pfx-qc2-sig-controls,
.pfx-qc2-det-controls,
.pfx-qc2-crew-controls,
.pfx-qc2-meta-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.pfx-qc2-ctrl {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: #50507a;
}
.pfx-qc2-ctrl .k { font-weight: 600; color: #6060a0; }
.pfx-qc2-select {
  background: #1a1a2c;
  border: 1px solid #2a2a44;
  color: #a0a0c8;
  font-size: 11px;
  padding: 3px 6px;
  border-radius: 4px;
}
.pfx-qc2-input {
  background: #1a1a2c;
  border: 1px solid #2a2a44;
  color: #a0a0c8;
  font-size: 11px;
  padding: 3px 6px;
  border-radius: 4px;
  width: 54px;
  text-align: right;
}
.pfx-qc2-unit { font-size: 10px; color: #40405a; }
.pfx-qc2-check {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: #7070a0;
  cursor: pointer;
}
.pfx-qc2-check input[type="checkbox"] { accent-color: #6060e0; }
.pfx-qc2-seeker {
  flex: 1;
  min-width: 120px;
  accent-color: #6060e0;
  cursor: pointer;
}
.pfx-qc2-tc-input {
  background: #1a1a2c;
  border: 1px solid #2a2a44;
  color: #c0c0e0;
  font-family: monospace;
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 4px;
  width: 110px;
}
.pfx-qc2-btn-analyze, .pfx-qc2-btn-brscan,
.pfx-qc2-btn-det-run, .pfx-qc2-btn-crew-run,
.pfx-qc2-btn-probe {
  flex-shrink: 0;
}

/* Stats bar */
.pfx-qc2-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 11px;
  font-family: monospace;
  color: #8080c0;
  background: #12121e;
  border: 1px solid #1e1e30;
  border-radius: 5px;
  padding: 6px 10px;
  flex-shrink: 0;
}
.pfx-qc2-stats b { color: #c0c0ff; }

/* Canvas row */
.pfx-qc2-canvas-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: flex-start;
  flex-shrink: 0;
}
.pfx-qc2-canvas-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.pfx-qc2-wf-block { flex: 1; min-width: 200px; }
.pfx-qc2-canvas-label {
  font-size: 10px;
  color: #40405a;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.pfx-qc2-hist-canvas,
.pfx-qc2-wf-canvas,
.pfx-qc2-vs-canvas,
.pfx-qc2-br-canvas {
  border: 1px solid #1e1e30;
  border-radius: 4px;
  display: block;
  max-width: 100%;
}
.pfx-qc2-wf-canvas { width: 100%; min-width: 200px; max-width: 640px; }
.pfx-qc2-br-sparkline-wrap {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex-shrink: 0;
}
.pfx-qc2-br-legend { font-size: 10px; color: #40405a; }

/* Progress */
.pfx-qc2-progress,
.pfx-qc2-crew-progress {
  flex-shrink: 0;
}
.pfx-qc2-progressBar {
  height: 4px;
  background: #1e1e30;
  border-radius: 2px;
  overflow: hidden;
  margin-bottom: 4px;
}
.pfx-qc2-progressFill {
  height: 100%;
  background: #6060e0;
  border-radius: 2px;
  transition: width 0.15s;
}
.pfx-qc2-progressTxt { font-size: 10px; color: #40405a; }

/* Results */
.pfx-qc2-det-results,
.pfx-qc2-crew-results {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
  min-height: 0;
}
.pfx-qc2-resultshead {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}
.pfx-qc2-resultstitle {
  font-size: 11px;
  font-weight: 700;
  color: #6060a0;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.pfx-qc2-tableWrap {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  border: 1px solid #1e1e30;
  border-radius: 5px;
}
.pfx-qc2-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
  color: #9090b8;
}
.pfx-qc2-table th {
  background: #14141e;
  color: #50507a;
  font-weight: 600;
  text-align: left;
  padding: 5px 8px;
  border-bottom: 1px solid #1e1e30;
  position: sticky;
  top: 0;
  z-index: 1;
  white-space: nowrap;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.pfx-qc2-table td {
  padding: 5px 8px;
  border-bottom: 1px solid #16162a;
}
.pfx-qc2-table tr:hover td { background: rgba(80,80,160,0.08); }
.pfx-qc2-th-thumb { width: 72px; }

/* Tags */
.pfx-qc2-tag {
  display: inline-block;
  padding: 2px 6px;
  border-radius: 3px;
  font-size: 10px;
  font-weight: 600;
  background: #1e1e38;
  color: #8080c0;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.pfx-qc2-tag-black_frame    { background: #1a1a1a; color: #606060; }
.pfx-qc2-tag-freeze_frame   { background: #1a2030; color: #5080b0; }
.pfx-qc2-tag-flash_strobe   { background: #302010; color: #c08030; }
.pfx-qc2-tag-ire_violation  { background: #301010; color: #c04040; }
.pfx-qc2-tag-audio_silence  { background: #101820; color: #406080; }

/* Thumbnails */
.pfx-qc2-thumbcell { width: 72px; padding: 4px; }
.pfx-qc2-thumb {
  width: 64px;
  height: 36px;
  object-fit: cover;
  border-radius: 3px;
  background: #0d0d18;
  border: 1px solid #1e1e30;
  display: block;
  opacity: 0.4;
  transition: opacity 0.2s;
}
.pfx-qc2-thumb.is-ready { opacity: 1; }

/* Metadata panel */
.pfx-qc2-meta-body {
  flex: 1;
  overflow-y: auto;
  min-height: 0;
}
.pfx-qc2-meta-placeholder { padding: 12px; font-size: 11px; }
.pfx-qc2-meta-section {
  margin-bottom: 14px;
  border: 1px solid #1e1e30;
  border-radius: 5px;
  overflow: hidden;
}
.pfx-qc2-meta-sectitle {
  font-size: 10px;
  font-weight: 700;
  color: #50507a;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: #14141e;
  padding: 5px 10px;
  border-bottom: 1px solid #1e1e30;
}
.pfx-qc2-meta-grid { display: flex; flex-direction: column; }
.pfx-qc2-meta-row {
  display: flex;
  align-items: flex-start;
  padding: 4px 10px;
  border-bottom: 1px solid #12121e;
  font-size: 11px;
  gap: 8px;
}
.pfx-qc2-meta-row:last-child { border-bottom: none; }
.pfx-qc2-meta-key {
  width: 140px;
  flex-shrink: 0;
  color: #50507a;
  font-weight: 600;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding-top: 1px;
}
.pfx-qc2-meta-val {
  color: #a0a0c8;
  font-family: monospace;
  font-size: 11px;
  word-break: break-all;
}
.pfx-qc2-meta-note {
  padding: 8px 10px;
  font-size: 10px;
  line-height: 1.5;
  border-top: 1px solid #1e1e30;
}

/* Compliance check rows */
.pfx-qc2-compliance-pass .pfx-qc2-compliance-icon { color: #40c060; }
.pfx-qc2-compliance-fail .pfx-qc2-compliance-icon { color: #e04040; }
.pfx-qc2-compliance-warn .pfx-qc2-compliance-icon { color: #c08030; }
.pfx-qc2-compliance-fail .pfx-qc2-meta-val { color: #e08080; }
.pfx-qc2-compliance-icon {
  width: 14px;
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 700;
}

/* Host status badge */
.pfx-qc2-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.03em;
}
.pfx-qc2-badge-ready    { background: rgba(40,140,40,0.2); color: #60c860; border: 1px solid #306030; }
.pfx-qc2-badge-missing  { background: rgba(160,80,20,0.2); color: #d09050; border: 1px solid #604020; }
.pfx-qc2-badge-checking { background: rgba(60,60,120,0.2); color: #7080c0; border: 1px solid #303060; }

/* AI toggle */
.pfx-qc2-ai-toggle { font-size: 11px; color: #7070a0; }
/* ─── /Visual QC 2.0 ─────────────────────────────────────────────────────── */


/* ═══════════════════════════════════════════════════════════════════════════
   TRAILERS CONFORM v3 (trlconf)
   ═══════════════════════════════════════════════════════════════════════════ */

#main-trlconf { box-sizing: border-box; padding: 0; }
#trlconfMount  { height: 100%; }

/* ── Root shell ── */
.trc-root {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: #0d0d14;
  color: #d0d0e8;
  font-family: var(--font-mono, 'JetBrains Mono', 'Fira Mono', monospace);
  font-size: 12px;
}

/* ── Header bar ── */
.trc-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 14px;
  background: #0b0b12;
  border-bottom: 1px solid #1a1a2c;
  flex-shrink: 0;
}
.trc-header-logo {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #2172E3;
  white-space: nowrap;
  flex-shrink: 0;
}

/* ── Status badge row ── */
.trc-status-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.trc-sbadge {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 10px;
  border: 1px solid #222235;
  background: rgba(255,255,255,0.03);
  color: #44445a;
  white-space: nowrap;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.trc-sbadge--ep    { color: #2172E3; border-color: #1e3555; background: rgba(77,159,255,0.07); }
.trc-sbadge--loaded { color: #c0c0e0; border-color: #333360; background: rgba(255,255,255,0.06); }
.trc-sbadge--ok    { color: #50d090; border-color: #1e5535; background: rgba(40,160,80,0.10); }

/* ── Scroll body ── */
.trc-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  gap: 0;
  padding: 10px 12px 12px;
  gap: 8px;
}

/* ── Panels (steps) ── */
.trc-panel {
  background: #11111c;
  border: 1px solid #1e1e32;
  border-radius: 7px;
  overflow: hidden;
  flex-shrink: 0;
}
.trc-panel-results {
  flex: 1;
  min-height: 160px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.trc-panel-verify {
  flex-shrink: 0;
}

.trc-panel-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  background: #0f0f1b;
  border-bottom: 1px solid #1a1a2c;
  flex-shrink: 0;
  min-height: 26px;
}
.trc-step-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid #2a2a4a;
  background: #18182a;
  color: #6060a0;
  font-size: 9px;
  font-weight: 700;
  flex-shrink: 0;
}
.trc-panel-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: #2172E3;
}

/* ── Step 1: Input cards ── */
.trc-input-cards {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 5px;
  padding: 5px 8px 7px;
}

.trc-icard {
  background: #13131f;
  border: 1px solid #1e1e32;
  border-radius: 4px;
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
}

.trc-icard-header {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px;
  background: #0f0f1c;
  border-bottom: 1px solid #181828;
}
.trc-icard--cut .trc-icard-header    { border-left: 2px solid #2172E3; }
.trc-icard--ref .trc-icard-header    { border-left: 2px solid #7d5fff; }
.trc-icard--source .trc-icard-header { border-left: 2px solid #50d090; }

.trc-icard-icon { color: #445570; flex-shrink: 0; width: 11px; height: 11px; }
.trc-icard-label {
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: #9090c0;
}
.trc-icard-formats {
  font-size: 7.5px;
  color: #303048;
  margin-left: auto;
  white-space: nowrap;
}

.trc-icard-body {
  display: flex;
  flex-direction: column;
  flex: 1;
}
/* Hide subtitle — redundant with card label, saves ~14px per card */
.trc-icard-sub { display: none; }

/* Drop zones */
.trc-drop-zone {
  padding: 5px 7px;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s;
  position: relative;
}
.trc-drop-zone:hover,
.trc-drop-zone--over { background: rgba(77,159,255,0.06); }
/* When loaded, collapse to just fit the info block */
.trc-drop-zone--loaded { background: transparent; min-height: unset; padding: 3px 5px 1px; }

.trc-drop-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  text-align: center;
  pointer-events: none;
}
/* Shrink the idle drop icons */
.trc-drop-icon { color: #2172E3; opacity: 0.35; }
.trc-drop-icon svg { width: 20px !important; height: 20px !important; }
.trc-drop-text { font-size: 8.5px; color: #606080; word-break: break-all; max-width: 180px; }
.trc-drop-hint { font-size: 7.5px; color: #252535; }

/* Info block — dense 2-col grid, zero row gap */
.trc-icard-info {
  width: 100%;
  padding: 1px 6px 2px;
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 6px;
  row-gap: 0;
  pointer-events: none;
}
.trc-info-row { display: contents; }
.trc-info-key {
  color: #30304a;
  white-space: nowrap;
  text-transform: uppercase;
  font-size: 7px;
  letter-spacing: 0.05em;
  line-height: 1.65;
  align-self: center;
}
.trc-info-val {
  color: #8080b0;
  font-size: 8px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.65;
  align-self: center;
}
.trc-info-file { color: #7878aa; font-size: 8px; }
.trc-info-ep   { color: #2172E3; font-weight: 700; font-size: 8px; }

.trc-load-btn {
  display: block;
  width: calc(100% - 12px);
  margin: 3px 6px 5px;
  padding: 2px 5px;
  background: #111120;
  border: 1px solid #202038;
  color: #484868;
  border-radius: 3px;
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  text-align: center;
  transition: border-color 0.12s, color 0.12s;
  font-family: inherit;
}
.trc-load-btn:hover { border-color: #2172E3; color: #2172E3; }

.trc-clear-btn {
  position: absolute;
  top: 2px;
  right: 3px;
  background: none;
  border: none;
  color: #303048;
  cursor: pointer;
  font-size: 11px;
  line-height: 1;
  padding: 2px 3px;
  border-radius: 3px;
  z-index: 2;
}
.trc-clear-btn:hover { color: #ff5566; background: rgba(255,50,60,0.1); }

/* ── Step 2: Match panel ── */
.trc-match-btns {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-left: auto;
}

/* Advanced disclosure — tucks the technical match-step buttons out of the way */
.trc-advanced { position: relative; }
.trc-advanced-summary {
  list-style: none;
  cursor: pointer;
  padding: 4px 9px;
  border-radius: 4px;
  border: 1px solid #2a2a48;
  background: #181828;
  color: #6f6f9a;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  user-select: none;
  transition: border-color 0.12s, color 0.12s, background 0.12s;
}
.trc-advanced-summary::-webkit-details-marker { display: none; }
.trc-advanced-summary:hover { border-color: #2172E3; color: #c0d8ff; }
.trc-advanced[open] .trc-advanced-summary { color: #9dc8ff; border-color: #263550; }
.trc-advanced-body {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-top: 6px;
}
.trc-deep-search-opt {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  padding: 4px 8px;
  border: 1px solid #283248;
  border-radius: 5px;
  color: #c7d2e7;
  background: #101522;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.03em;
  cursor: pointer;
}
.trc-deep-search-opt input { accent-color: #2f7cf4; }
.trc-deep-search-opt small {
  color: #77839b;
  font-size: 9px;
  font-weight: 600;
}

.trc-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border-radius: 4px;
  border: 1px solid #2a2a48;
  background: #181828;
  color: #8080b0;
  cursor: pointer;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-family: inherit;
  transition: border-color 0.12s, color 0.12s, background 0.12s;
}
.trc-btn:disabled { opacity: 0.32; cursor: not-allowed; }
.trc-btn:not(:disabled):hover { border-color: #2172E3; color: #c0d8ff; }

.trc-btn-match-step {
  background: rgba(77,159,255,0.06);
  border-color: #263550;
  color: #6090c0;
}
.trc-btn-match-step:not(:disabled):hover { background: rgba(77,159,255,0.13); border-color: #2172E3; color: #9dc8ff; }

.trc-btn-run-match {
  background: rgba(77,159,255,0.12);
  border-color: #2a4570;
  color: #2172E3;
  font-size: 10px;
  padding: 4px 14px;
}
.trc-btn-run-match:not(:disabled):hover { background: rgba(77,159,255,0.22); border-color: #2172E3; box-shadow: 0 0 10px rgba(77,159,255,0.2); }
.trc-btn-run-match--ready:not(:disabled) {
  border-color: #2172E3;
  background: rgba(77,159,255,0.18);
  animation: trc-run-pulse 2s ease-in-out infinite;
}
@keyframes trc-run-pulse {
  0%, 100% { box-shadow: 0 0 6px rgba(77,159,255,0.25); }
  50%       { box-shadow: 0 0 14px rgba(77,159,255,0.55); }
}

.trc-btn-stop {
  background: rgba(220,50,60,0.10);
  border-color: rgba(220,50,60,0.35);
  color: #e07070;
}
.trc-btn-stop:hover { background: rgba(220,50,60,0.20); }

.trc-btn-reset-match {
  background: rgba(80,80,120,0.10);
  border-color: #2a2a48;
  color: #6060a0;
}
.trc-btn-reset-match:hover { border-color: #5050a0; color: #9090c8; }

/* Progress display */
.trc-progress-wrap {
  padding: 8px 10px 6px;
  border-top: 1px solid #1a1a2c;
  background: #0e0e18;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.trc-progress-phases {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}
.trc-phase-step {
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #333355;
  padding: 2px 6px;
  border-radius: 3px;
  border: 1px solid transparent;
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
.trc-phase-step.trc-phase-active {
  color: #2172E3;
  border-color: #1e3555;
  background: rgba(77,159,255,0.08);
}
.trc-phase-arrow { color: #222235; font-size: 10px; }

.trc-progress-bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.trc-progress-bar {
  flex: 1;
  height: 4px;
  border-radius: 2px;
  accent-color: #2172E3;
  border: none;
  background: #18182a;
}
.trc-progress-pct {
  font-size: 10px;
  font-family: monospace;
  color: #2172E3;
  min-width: 32px;
  text-align: right;
  flex-shrink: 0;
}
.trc-progress-current {
  font-size: 9px;
  color: #44445a;
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.trc-progress-eta {
  font-size: 9px;
  color: #7a7aa0;
  font-style: italic;
  margin-left: 6px;
  flex-shrink: 0;
  white-space: nowrap;
}
.trc-slip-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
  padding: 6px 10px;
  border-top: 1px solid rgba(255,255,255,0.05);
}
.trc-slip-label {
  font-size: 9px;
  color: #555580;
  letter-spacing: 0.04em;
  margin-right: 4px;
}
.trc-slip-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border-radius: 3px;
  font-size: 9px;
  font-family: monospace;
  border: 1px solid rgba(255,255,255,0.08);
}
.trc-slip-chip--zero  { background: rgba(80,200,120,0.1); color: #50c878; }
.trc-slip-chip--good  { background: rgba(77,159,255,0.1); color: #2172E3; }
.trc-slip-chip--ok    { background: rgba(246,181,98,0.1);  color: #f6b562; }
.trc-slip-chip--warn  { background: rgba(255,80,80,0.1);   color: #ff6060; }
.trc-slip-reel   { opacity: 0.7; }
.trc-slip-offset { font-weight: 600; }

/* ── Step 3: Results ── */
.trc-results-stats {
  font-size: 9px;
  color: #555580;
  margin-left: auto;
  letter-spacing: 0.04em;
}

/* Worklist status filter (render-only segmented control) */
.trc-results-filter {
  display: inline-flex;
  align-items: center;
  gap: 0;
  border: 1px solid #2a2a48;
  border-radius: 4px;
  overflow: hidden;
  flex-shrink: 0;
}
.trc-filter-btn {
  padding: 3px 9px;
  border: none;
  border-left: 1px solid #2a2a48;
  background: #181828;
  color: #8080b0;
  cursor: pointer;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-family: inherit;
  transition: color 0.12s, background 0.12s;
}
.trc-filter-btn:first-child { border-left: none; }
.trc-filter-btn:hover { color: #c0d8ff; background: #1f1f34; }
.trc-filter-btn.is-active {
  background: rgba(33,114,227,0.22);
  color: #c0d8ff;
}

.trc-results-guide {
  padding: 8px 12px 6px;
  border-top: 1px solid rgba(255,255,255,0.05);
}
.trc-results-summary {
  font-size: 11px;
  color: #c3ccea;
  line-height: 1.5;
}
.trc-results-unmatched-reels {
  font-size: 10px;
  color: #f6b562;
  line-height: 1.5;
  margin-top: 4px;
}
.trc-row-reason {
  font-size: 9px;
  color: #7a7aa0;
  margin-top: 2px;
  max-width: 220px;
  white-space: normal;
  line-height: 1.35;
}
.trc-fix-reel {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.trc-fix-reel-select {
  font-size: 9px;
  color: #c3ccea;
  background: rgba(255,255,255,0.06);
  border: 1px solid #333360;
  border-radius: 3px;
  padding: 1px 3px;
  max-width: 140px;
}
.trc-verify-confidence-line {
  font-size: 10px;
  color: #f6b562;
  padding: 4px 12px;
  line-height: 1.4;
}
.trc-sbadge--last-matched {
  color: #7a7aa0;
  border-color: #333360;
  background: rgba(255,255,255,0.04);
}
.trc-results-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin-top: 6px;
  font-size: 9px;
  color: #7f8cb4;
  line-height: 1.5;
}
.trc-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.trc-legend-item .trc-badge { font-size: 8px; }
.trc-legend-note {
  color: #555580;
  width: 100%;
}

.trc-empty-state {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.trc-empty-hint {
  font-size: 10px;
  color: #333355;
  text-align: center;
  line-height: 1.7;
  max-width: 420px;
}

.trc-results-wrap {
  flex: 1;
  overflow: auto;
  min-height: 0;
}

.trc-results-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 10px;
}
.trc-results-table thead tr {
  position: sticky;
  top: 0;
  z-index: 2;
  background: #0c0c18;
}
.trc-results-table th {
  padding: 4px 6px;
  text-align: left;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: #44445a;
  border-bottom: 1px solid #1a1a2e;
  white-space: nowrap;
}
.trc-results-table td {
  padding: 4px 6px;
  border-bottom: 1px solid #12122a;
  vertical-align: middle;
  white-space: nowrap;
}
.trc-results-table tr:hover td { background: rgba(77,159,255,0.04); cursor: pointer; }

/* Column widths */
.trc-col-num    { width: 28px; color: #333355; text-align: right; }
.trc-col-event  { width: 44px; }
.trc-col-clip   { max-width: 120px; overflow: hidden; text-overflow: ellipsis; color: #8080b0; }
.trc-col-tc     { font-family: monospace; font-size: 9px; color: #7070a0; width: 80px; }
.trc-col-dur    { width: 44px; color: #606080; font-family: monospace; font-size: 9px; }
.trc-col-source { max-width: 120px; overflow: hidden; text-overflow: ellipsis; color: #a0a0c8; }
.trc-col-offset { width: 54px; font-family: monospace; font-size: 9px; color: #7090b0; }
.trc-col-pct    { width: 40px; text-align: right; font-family: monospace; font-size: 9px; }
.trc-col-status { width: 60px; }
.trc-col-action { width: 52px; text-align: center; }

/* Row status colors */
.trc-row-safe td     { background: rgba(40,160,80,0.04); }
.trc-row-review td   { background: rgba(255,180,40,0.04); }
.trc-row-fail td     { background: rgba(220,50,50,0.05); }
.trc-row-manual td   { background: rgba(160,100,255,0.05); }
.trc-row-unmatch td  { opacity: 0.45; }

/* Status pills in results table */
.trc-badge {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 8px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border: 1px solid transparent;
}
.trc-badge-safe    { background: rgba(40,160,80,0.18);  color: #50d090; border-color: rgba(40,160,80,0.3); }
.trc-badge-review  { background: rgba(255,180,40,0.18); color: #ffb840; border-color: rgba(255,180,40,0.3); }
.trc-badge-fail    { background: rgba(220,50,50,0.18);  color: #e07070; border-color: rgba(220,50,50,0.3); }
.trc-badge-manual  { background: rgba(160,100,255,0.18);color: #b880ff; border-color: rgba(160,100,255,0.3); }
.trc-badge-unmatch { background: rgba(60,60,100,0.15);  color: #555580; border-color: rgba(60,60,100,0.25); }

/* Pct color */
.trc-pct-high { color: #50d090; font-weight: 600; }
.trc-pct-med  { color: #ffb840; }
.trc-pct-low  { color: #e07070; }
.trc-pct-none { color: #333355; }
/* Plain-word confidence label beside the Final % (e.g. "78% · Medium") */
.trc-pct-word { font-weight: 400; opacity: 0.75; }

/* Verify action button per row */
.trc-btn-verify-row {
  font-size: 8px;
  padding: 2px 7px;
  background: rgba(77,159,255,0.08);
  border: 1px solid #263550;
  color: #2172E3;
  border-radius: 3px;
  cursor: pointer;
  font-family: inherit;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.trc-btn-verify-row:hover { background: rgba(77,159,255,0.18); border-color: #2172E3; }

/* ── Step 4: Verify panel ── */
.trc-verify-event-label {
  font-size: 9px;
  color: #6080a0;
  margin-left: 4px;
  font-style: italic;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 200px;
}
.trc-view-modes {
  display: flex;
  gap: 4px;
  margin-left: auto;
}
.trc-view-mode-btn {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 3px;
  border: 1px solid #22223a;
  background: transparent;
  color: #44445a;
  cursor: pointer;
  font-family: inherit;
  transition: border-color 0.12s, color 0.12s, background 0.12s;
}
.trc-view-mode-btn:hover { border-color: #2172E3; color: #7090c8; }
.trc-view-mode-btn.is-active { border-color: #2172E3; background: rgba(77,159,255,0.10); color: #2172E3; }

.trc-close-verify {
  margin-left: 8px;
  background: none;
  border: none;
  color: #44445a;
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
  padding: 0 3px;
  flex-shrink: 0;
}
.trc-close-verify:hover { color: #e07070; }

.trc-verify-body {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.trc-frames-row {
  display: flex;
  align-items: stretch;
  gap: 0;
  background: #080810;
  min-height: 200px;
}
.trc-frame-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  padding: 6px 8px;
}
.trc-frame-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: #44445a;
  margin-bottom: 4px;
}
.trc-frame-canvas {
  width: 100%;
  max-width: 480px;
  height: auto;
  border-radius: 3px;
  background: #0c0c18;
  display: block;
}
.trc-frame-divider {
  width: 1px;
  background: #1a1a2c;
  flex-shrink: 0;
  align-self: stretch;
}

/* Waveform strip */
.trc-wave-strip {
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid #1a1a2c;
  background: #0a0a14;
}
.trc-wave-track {
  display: flex;
  align-items: center;
  gap: 0;
  border-bottom: 1px solid #14142a;
}
.trc-wave-track-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #333355;
  text-transform: uppercase;
  width: 28px;
  text-align: center;
  flex-shrink: 0;
}
.trc-wave-canvas {
  flex: 1;
  height: 36px;
  display: block;
  background: #0c0c18;
}
.trc-wave-offset-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
}
.trc-wave-offset-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: #333355;
}
.trc-wave-offset-val {
  font-size: 10px;
  font-family: monospace;
  color: #7090b0;
}

/* Manual frame controls */
.trc-manual-controls {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  background: #0f0f1b;
  border-top: 1px solid #1a1a2c;
  flex-wrap: wrap;
}
.trc-adj-btn {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
  padding: 3px 9px;
  border-radius: 3px;
  border: 1px solid #222240;
  background: #13132a;
  color: #6060a0;
  cursor: pointer;
  font-family: inherit;
  transition: border-color 0.12s, color 0.12s;
}
.trc-adj-btn:hover { border-color: #5060c0; color: #9090d0; }

.trc-manual-sep {
  flex: 1;
  min-width: 10px;
}

.trc-btn-approve-match {
  background: rgba(40,160,80,0.12);
  border-color: rgba(40,160,80,0.35);
  color: #50d090;
}
.trc-btn-approve-match:not(:disabled):hover {
  background: rgba(40,160,80,0.22);
  border-color: #50d090;
}
.trc-btn-reject-match {
  background: rgba(220,50,50,0.10);
  border-color: rgba(220,50,50,0.35);
  color: #e07070;
}
.trc-btn-reject-match:not(:disabled):hover { background: rgba(220,50,50,0.20); }
.trc-btn-mark-review {
  background: rgba(255,180,40,0.08);
  border-color: rgba(255,180,40,0.30);
  color: #ffb840;
}
.trc-btn-mark-review:not(:disabled):hover { background: rgba(255,180,40,0.18); }

.trc-btn-sync-scrub.is-active { border-color: #2172E3; background: rgba(77,159,255,0.10); color: #2172E3; }

/* ── Step 5: Export ── */
.trc-export-summary {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  font-size: 9px;
}
.trc-sum-item  { color: #555580; }
.trc-sum-sep   { color: #222240; }
.trc-sum-safe  { color: #50d090; font-weight: 700; }
.trc-sum-review{ color: #ffb840; font-weight: 700; }
.trc-sum-fail  { color: #e07070; font-weight: 700; }

.trc-export-body {
  display: flex;
  align-items: flex-start;
  gap: 20px;
  padding: 8px 10px;
}
.trc-export-opts {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}
.trc-opt-check {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 9px;
  color: #8080a8;
  cursor: pointer;
  user-select: none;
  letter-spacing: 0.03em;
}
.trc-opt-check input[type="checkbox"] { accent-color: #2172E3; cursor: pointer; }
.trc-opt-check:hover { color: #b0b0d8; }

.trc-export-btns {
  display: flex;
  flex-direction: column;
  gap: 5px;
  flex-shrink: 0;
}
.trc-btn-export-xml {
  background: rgba(77,159,255,0.10);
  border-color: #263550;
  color: #2172E3;
  font-size: 10px;
  padding: 5px 14px;
  font-weight: 700;
}
.trc-btn-export-xml:not(:disabled):hover { background: rgba(77,159,255,0.22); border-color: #2172E3; box-shadow: 0 0 8px rgba(77,159,255,0.18); }
.trc-btn-export-csv  { color: #7090b0; }
.trc-btn-export-csv:not(:disabled):hover  { border-color: #7090b0; color: #a0b8d8; }
.trc-btn-export-json { color: #9060c0; border-color: #2a1a40; background: rgba(100,60,160,0.07); }
.trc-btn-export-json:not(:disabled):hover { border-color: #9060c0; color: #c090e8; }

/* ── Trailers Conform v3.5 layout refresh ─────────────────────────────── */
.trc-root {
  background:
    radial-gradient(circle at top left, rgba(77, 159, 255, 0.12), transparent 28%),
    radial-gradient(circle at top right, rgba(125, 95, 255, 0.10), transparent 22%),
    linear-gradient(180deg, #090b13 0%, #07080f 100%);
  color: #d8def4;
  font-family: "IBM Plex Sans", "Inter", "Segoe UI", sans-serif;
}

.trc-header {
  padding: 6px 14px;
  background: rgba(8, 10, 18, 0.92);
  border-bottom: 1px solid rgba(115, 138, 208, 0.14);
  backdrop-filter: blur(12px);
  flex-shrink: 0;
}

.trc-header-logo {
  font-size: 12px;
  letter-spacing: 0.18em;
  color: #eef3ff;
}

.trc-engine-badge {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  margin-left: 10px;
  padding: 2px 9px;
  border: 1px solid rgba(86, 210, 198, 0.34);
  border-radius: 999px;
  background: rgba(86, 210, 198, 0.09);
  color: #7ce1d7;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.09em;
  white-space: nowrap;
}

.trc-status-row { gap: 8px; }

.trc-sbadge {
  padding: 5px 10px;
  border-radius: 999px;
  border-color: rgba(103, 120, 176, 0.24);
  background: rgba(255, 255, 255, 0.03);
  color: #97a2c7;
  font-size: 10px;
  letter-spacing: 0.05em;
}

.trc-sbadge--ep {
  color: #8ec7ff;
  border-color: rgba(77, 159, 255, 0.35);
  background: rgba(77, 159, 255, 0.12);
}

.trc-sbadge--loaded {
  color: #dbe5ff;
  border-color: rgba(132, 152, 218, 0.3);
  background: rgba(255, 255, 255, 0.07);
}

.trc-sbadge--ok {
  color: #80e0ad;
  border-color: rgba(80, 208, 144, 0.36);
  background: rgba(80, 208, 144, 0.12);
}

.trc-body {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 5px 8px 6px;
  overflow: hidden;
  flex: 1;
  min-height: 0;
}

.trc-panel {
  background: linear-gradient(180deg, rgba(17, 20, 31, 0.98), rgba(12, 14, 23, 0.98));
  border: 1px solid rgba(102, 120, 186, 0.18);
  border-radius: 10px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.22);
}

/* Verify is now first — gets dominant height. Results compact below. */
.trc-panel-verify {
  flex: 3 1 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.trc-panel-results {
  flex: 1 1 0;
  min-height: 60px;
  overflow: hidden;
}

.trc-panel-head {
  padding: 6px 12px;
  background: linear-gradient(180deg, rgba(15, 18, 29, 0.98), rgba(10, 12, 19, 0.98));
  border-bottom: 1px solid rgba(102, 120, 186, 0.14);
  min-height: 34px;
}

.trc-step-num {
  width: 20px;
  height: 20px;
  font-size: 10px;
  color: #dbe5ff;
  border-color: rgba(120, 146, 228, 0.36);
  background: rgba(77, 159, 255, 0.12);
}

.trc-panel-title {
  font-size: 10px;
  letter-spacing: 0.12em;
  color: #8ec7ff;
}

/* ── Step 1 INPUTS: ultra-compact 3-column single-line strip ─────────────── */
.trc-input-cards {
  display: flex;
  flex-direction: row;
  gap: 5px;
  padding: 4px 6px 5px;
}

/* Each card is a single horizontal row */
.trc-icard {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  height: 26px;
  min-height: 26px;
  border-radius: 6px;
  border-color: rgba(102, 120, 186, 0.16);
  background: linear-gradient(90deg, rgba(21, 24, 38, 0.95), rgba(14, 16, 26, 0.95));
  overflow: visible;
  position: relative;
}

/* Left accent + label block */
.trc-icard-header {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
  padding: 0 7px 0 8px;
  height: 100%;
  background: transparent;
  border-bottom: none;
  border-right: 1px solid rgba(102, 120, 186, 0.10);
  min-width: 0;
}
.trc-icard--cut    .trc-icard-header { border-left: 2px solid rgba(77, 159, 255, 0.7); }
.trc-icard--ref    .trc-icard-header { border-left: 2px solid rgba(125, 95, 255, 0.7); }
.trc-icard--source .trc-icard-header { border-left: 2px solid rgba(80, 208, 144, 0.7); }

.trc-icard-icon { width: 10px; height: 10px; color: #4a6080; flex-shrink: 0; }

.trc-icard-label {
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.07em;
  color: #b0bcd8;
  white-space: nowrap;
}

.trc-icard-formats { display: none; }
.trc-icard-sub     { display: none; }

/* Body: drop zone + load button inline */
.trc-icard-body {
  flex: 1;
  display: flex;
  flex-direction: row;
  align-items: center;
  height: 100%;
  min-width: 0;
  gap: 0;
  padding: 0;
}

/* Drop zone fills the body — droppable, clickable */
.trc-drop-zone {
  flex: 1;
  min-height: 0;
  height: 100%;
  padding: 0 6px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  border-radius: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  transition: background 0.12s;
}
.trc-drop-zone:hover,
.trc-drop-zone--over { background: rgba(77, 159, 255, 0.06); }

.trc-drop-zone--loaded {
  min-height: 0;
  padding: 0 6px;
  background: transparent;
}
.trc-root.trc-simple-mode.trc-review-focus .trc-view-modes {
  display: flex !important;
  flex: 0 0 auto;
  gap: 2px;
  margin-left: 5px;
}
.trc-root.trc-simple-mode.trc-review-focus .trc-view-mode-btn {
  min-height: 24px;
  padding: 3px 6px;
  border-radius: 4px;
  font-size: 7px;
}
.trc-review-undo {
  display: inline-flex;
  min-height: 23px;
  align-items: center;
  padding: 3px 7px;
  border: 1px solid rgba(102,121,154,.28);
  border-radius: 4px;
  background: #11151b;
  color: #9eb1ca;
  font: 750 7px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  cursor: pointer;
}
.trc-review-undo:hover:not(:disabled) { border-color: rgba(104,184,255,.55); color: #d7eaff; }
.trc-review-undo:disabled { opacity: .3; cursor: default; }
.trc-nle-transport .trc-nle-loop {
  width: 40px;
  color: #8a96aa;
  font: 750 6px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: .05em;
}
.trc-nle-transport .trc-nle-loop.is-active {
  border-color: rgba(255,155,72,.6);
  background: rgba(174,82,25,.35);
  color: #ffad68;
  box-shadow: 0 0 8px rgba(255,125,49,.18);
}
@media (max-width: 1050px) {
  .trc-root.trc-simple-mode.trc-review-focus .trc-view-modes { display: none !important; }
}

/* Drop inner: row, no icon */
.trc-drop-inner {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 5px;
  pointer-events: none;
  min-width: 0;
  flex: 1;
}

.trc-drop-icon  { display: none; }
.trc-drop-hint  { display: none; }

.trc-drop-text {
  font-size: 9px;
  color: #4a5575;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  font-style: italic;
}

/* Info block when file loaded — single inline row, show only filename */
.trc-icard-info {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: nowrap;
  gap: 6px;
  padding: 0;
  pointer-events: none;
  min-width: 0;
  flex: 1;
}

.trc-info-row {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
  overflow: hidden;
}

/* Hide all info rows except the first (filename) */
.trc-info-row:not(:first-child) { display: none; }

.trc-info-key { display: none; }

.trc-info-val,
.trc-info-file,
.trc-info-ep {
  font-size: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
  line-height: 1;
}

.trc-info-val  { color: #8090b8; }
.trc-info-file { color: #c0ccee; }
.trc-info-ep   { color: #8ec7ff; font-weight: 700; }

/* Load button: tiny icon-only pill on right edge */
.trc-load-btn {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  margin: 0 4px;
  padding: 0;
  border-radius: 4px;
  font-size: 0;
  overflow: hidden;
  background: rgba(77, 159, 255, 0.08);
  border: 1px solid rgba(77, 159, 255, 0.20);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.12s, border-color 0.12s;
  position: relative;
}
.trc-load-btn::after {
  content: '+';
  font-size: 13px;
  font-weight: 400;
  color: #6a88c8;
  line-height: 1;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.trc-load-btn:hover {
  background: rgba(77, 159, 255, 0.18);
  border-color: rgba(77, 159, 255, 0.50);
}
.trc-load-btn:hover::after { color: #8ec7ff; }

/* Clear button — vertically centred */
.trc-clear-btn {
  top: 50%;
  transform: translateY(-50%);
  right: 26px;
  color: #4a5575;
  font-size: 10px;
  padding: 1px 3px;
}
.trc-clear-btn:hover { color: #ff5566; background: rgba(255, 50, 60, 0.12); }

.trc-match-note {
  padding: 5px 12px 4px;
  color: #6a7498;
  font-size: 9px;
  line-height: 1.4;
}

.trc-match-btns { gap: 6px; }

.trc-btn {
  min-height: 26px;
  padding: 4px 10px;
  border-radius: 7px;
  font-size: 9px;
  letter-spacing: 0.07em;
}

.trc-progress-wrap {
  padding: 7px 12px 9px;
  gap: 6px;
  background: rgba(7, 10, 17, 0.72);
  border-top-color: rgba(102, 120, 186, 0.14);
}

.trc-phase-step {
  font-size: 8px;
  padding: 2px 6px;
  border-radius: 999px;
  color: #7f8cb4;
}

.trc-progress-bar { height: 5px; }
.trc-progress-pct { min-width: 38px; font-size: 10px; }
.trc-progress-current { max-width: 300px; font-size: 9px; }

.trc-results-stats {
  font-size: 8.5px;
  color: #98a3c7;
}

.trc-empty-state { padding: 8px 14px; }

.trc-empty-hint {
  max-width: 440px;
  font-size: 9px;
  color: #9ca8cd;
}

.trc-results-table { font-size: 9px; }

.trc-results-table th {
  padding: 3px 5px;
  font-size: 7.5px;
  color: #8795bd;
  background: rgba(8, 10, 16, 0.98);
}

.trc-results-table td {
  padding: 2px 5px;
  border-bottom-color: rgba(102, 120, 186, 0.08);
}

.trc-results-table tr:hover td { background: rgba(77, 159, 255, 0.08); }

.trc-results-table tr.is-selected td {
  background: rgba(77, 159, 255, 0.16);
  box-shadow: inset 0 1px 0 rgba(142, 199, 255, 0.12), inset 0 -1px 0 rgba(142, 199, 255, 0.12);
}

.trc-col-event {
  width: 52px;
  color: #d8e3ff;
  font-weight: 600;
}

.trc-col-clip,
.trc-col-source { max-width: 140px; }

.trc-col-action { width: 210px; }

.trc-badge {
  padding: 1px 6px;
  border-radius: 999px;
  font-size: 7.5px;
}

.trc-act-stack {
  display: flex;
  flex-wrap: nowrap;
  gap: 2px;
  align-items: center;
}

.trc-act-btn {
  min-height: 16px;
  padding: 1px 6px;
  border-radius: 999px;
  border: 1px solid rgba(102, 120, 186, 0.18);
  background: rgba(255, 255, 255, 0.04);
  color: #d4def7;
  font: inherit;
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color .15s, background .15s, color .15s;
  white-space: nowrap;
}

.trc-act-btn:hover {
  border-color: rgba(142, 199, 255, 0.55);
  background: rgba(77, 159, 255, 0.14);
  color: #fff;
}

.trc-verify-body {
  flex: 1;
  min-height: 0;
  display: grid;
  /* auditable picture evidence, frames, waveform, controls */
  grid-template-rows: auto minmax(0, 1fr) auto auto;
}

.trc-review-nav {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-left: auto;
  padding: 2px;
  border: 1px solid rgba(102, 120, 186, 0.16);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.025);
}

.trc-review-nav-btn {
  min-height: 20px;
  padding: 2px 7px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #8997be;
  font: inherit;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .04em;
  cursor: pointer;
  white-space: nowrap;
}

.trc-review-nav-btn:hover:not(:disabled) { color: #eef3ff; background: rgba(77, 159, 255, .12); }
.trc-review-nav-btn:disabled { opacity: .32; cursor: not-allowed; }
.trc-review-nav-btn--attention { color: #f6b562; background: rgba(246, 181, 98, .08); }
.trc-review-counter { min-width: 42px; color: #c5d1ee; font-size: 8px; font-variant-numeric: tabular-nums; text-align: center; }
.trc-view-modes { margin-left: 6px; }

.trc-verify-confidence-line {
  padding: 7px 10px 6px;
  color: #dbe5ff;
  border-bottom: 1px solid rgba(102, 120, 186, 0.14);
  background: linear-gradient(90deg, rgba(18, 23, 37, .96), rgba(10, 13, 22, .96));
}

.trc-evidence-topline {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.trc-evidence-status {
  display: inline-flex;
  align-items: center;
  min-height: 18px;
  padding: 2px 7px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: .07em;
  white-space: nowrap;
}

.trc-evidence-status--ok { color: #65dca2; border-color: rgba(80, 208, 144, .34); background: rgba(80, 208, 144, .10); }
.trc-evidence-status--review { color: #f6b562; border-color: rgba(246, 181, 98, .34); background: rgba(246, 181, 98, .10); }
.trc-evidence-status--fail { color: #f07f89; border-color: rgba(240, 92, 108, .34); background: rgba(240, 92, 108, .10); }
.trc-evidence-decision { color: #dbe5ff; font-size: 8.5px; font-weight: 700; }
.trc-evidence-method { margin-left: auto; color: #697695; font-size: 8px; white-space: nowrap; }

.trc-evidence-grid {
  display: grid;
  grid-template-columns: minmax(250px, 1.7fr) repeat(4, minmax(78px, .55fr));
  gap: 5px;
  margin-top: 5px;
}

.trc-evidence-metric {
  min-width: 0;
  padding: 5px 7px;
  border: 1px solid rgba(102, 120, 186, .13);
  border-radius: 7px;
  background: rgba(255, 255, 255, .025);
}

.trc-evidence-metric > span { display: block; color: #7280a2; font-size: 7px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.trc-evidence-metric > strong { display: block; margin-top: 1px; color: #eef3ff; font-size: 11px; font-variant-numeric: tabular-nums; }
.trc-evidence-metric > small { display: block; margin-top: 1px; color: #596581; font-size: 7px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.trc-distance-scale {
  position: relative;
  display: grid;
  grid-template-columns: 12.5fr 18.75fr 68.75fr;
  gap: 1px;
  height: 4px;
  margin: 4px 0 3px;
  border-radius: 999px;
  overflow: visible;
  opacity: .9;
}
.trc-distance-scale i { display: block; min-width: 0; }
.trc-distance-ok { background: #50d090; border-radius: 999px 0 0 999px; }
.trc-distance-review { background: #f6b562; }
.trc-distance-fail { background: #d95968; border-radius: 0 999px 999px 0; }
.trc-distance-scale b { position: absolute; top: -3px; width: 2px; height: 10px; border-radius: 2px; background: #fff; box-shadow: 0 0 5px rgba(255,255,255,.65); transform: translateX(-1px); }
.trc-distance-scale.is-empty { opacity: .2; }
.trc-evidence-reason { margin-top: 4px; color: #8190b3; font-size: 8px; line-height: 1.35; }

.trc-review-readiness {
  display: grid;
  grid-template-columns: auto minmax(120px, 1fr) auto;
  align-items: center;
  gap: 9px;
  margin-top: 6px;
  padding: 5px 7px;
  border: 1px solid rgba(102, 120, 186, .13);
  border-radius: 7px;
  background: rgba(255, 255, 255, .025);
}
.trc-review-readiness-copy { display: flex; align-items: baseline; gap: 7px; color: #8390af; font-size: 8px; text-transform: uppercase; letter-spacing: .07em; }
.trc-review-readiness-copy strong { color: #dbe5ff; font-size: 9px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.trc-review-readiness-track { height: 5px; overflow: hidden; border-radius: 999px; background: rgba(255,255,255,.07); }
.trc-review-readiness-track span { display: block; width: 0; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #4d9fff, #56d2c6); transition: width .2s ease; }
.trc-btn-open-attention { min-height: 22px; padding: 3px 9px; color: #f6b562; border-color: rgba(246, 181, 98, .25); background: rgba(246, 181, 98, .07); }

/* Instruction text hidden — event info lives in panel head */
.trc-verify-empty { display: none !important; }

.trc-verify-event-label {
  max-width: 100%;
  font-size: 9px;
  color: #9ab8ff;
}

.trc-view-mode-btn {
  min-height: 22px;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 8.5px;
}

.trc-frames-row {
  min-height: 0;
  background: rgba(4, 6, 12, 0.75);
}

.trc-frame-panel { padding: 0; }

/* Column labels hidden — ref/src identity shown in panel head event label */
.trc-frame-label { display: none; }

.trc-frame-canvas {
  max-width: 100%;
  border-radius: 8px;
  border: 1px solid rgba(102, 120, 186, 0.12);
  background: #090c16;
}

.trc-wave-track { padding: 0 8px; }

.trc-wave-track-label {
  width: 44px;
  text-align: left;
  font-size: 8.5px;
  color: #9aa7cd;
}

.trc-wave-canvas {
  height: 30px;
  border-radius: 6px;
}

.trc-wave-offset-row { display: none; }
.trc-wave-offset-label { font-size: 8.5px; color: #7f8cb4; }
.trc-wave-offset-val { font-size: 10px; color: #dbe5ff; }

.trc-manual-controls {
  gap: 5px;
  padding: 6px 10px;
  background: rgba(12, 14, 21, 0.84);
}

.trc-adj-btn {
  min-height: 24px;
  padding: 3px 9px;
  border-radius: 8px;
}

.trc-adj-btn:disabled,
.trc-btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

/* Export summary — inline pill row in panel head */
.trc-export-summary {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  flex-wrap: wrap;
  width: auto;
}

.trc-sum-card {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(102, 120, 186, 0.12);
}

.trc-sum-card-safe    { border-color: rgba(80, 208, 144, 0.28); }
.trc-sum-card-review  { border-color: rgba(246, 181, 98, 0.28); }
.trc-sum-card-review-soft { border-color: rgba(193, 151, 77, 0.20); }
.trc-sum-card-fail    { border-color: rgba(224, 112, 112, 0.28); }

.trc-sum-label {
  color: #6a788c;
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.trc-sum-value {
  color: #e8eeff;
  font-size: 10px;
  font-weight: 700;
}

/* Export body — all on one line */
.trc-export-body {
  flex-direction: row;
  align-items: center;
  gap: 10px;
  padding: 5px 12px 6px;
}

.trc-export-opts {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 2px 14px;
  flex: 1;
  align-items: center;
}
.trc-opt-check { font-size: 8.5px; color: #b0bcd8; gap: 4px; white-space: nowrap; }

.trc-export-btns {
  display: flex;
  flex-direction: row;
  gap: 5px;
  flex-shrink: 0;
  width: auto;
}

.trc-btn-export-xml {
  justify-content: center;
  width: auto;
  min-height: 24px;
  padding: 4px 14px;
  font-size: 9px;
  white-space: nowrap;
}

@media (max-width: 1380px) {
  .trc-panel-results { min-height: 420px; }
}

@media (max-width: 1100px) {
  .trc-input-cards { flex-direction: column; }
  .trc-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .trc-panel-head { flex-wrap: wrap; }
  .trc-export-summary { flex-wrap: wrap; margin-left: 0; }
  .trc-export-body { flex-wrap: wrap; }
  .trc-export-opts { flex-wrap: wrap; }
  .trc-export-btns { flex-shrink: 0; }
  .trc-frames-row { flex-direction: column; }
  .trc-frame-divider {
    width: 100%;
    height: 1px;
  }
}

/* ===========================================================================
   PULL PREP — VFX NAME REVIEW
   Auto names stay compact in the shot list; only exceptions ask for attention.
   =========================================================================== */
#main-prepmark .pm-name-review-badge {
  flex: 0 0 auto;
  height: 14px;
  display: inline-flex;
  align-items: center;
  padding: 0 4px;
  border: 1px solid rgba(255, 184, 77, .34);
  border-radius: 3px;
  background: rgba(255, 166, 43, .09);
  color: #ffbd66;
  font-size: 6px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .07em;
  cursor: help;
}
#main-prepmark .pm-name-review-badge.is-duplicate {
  border-color: rgba(229, 9, 20, .48);
  background: rgba(229, 9, 20, .12);
  color: #ff747b;
}
#main-prepmark .pm-ve-readiness.is-name-review {
  border-color: rgba(255, 174, 64, .45);
  background: rgba(255, 174, 64, .09);
  color: #ffc066;
}
#main-prepmark .pm-ve-readiness.is-name-duplicate {
  border-color: rgba(229, 9, 20, .58);
  background: rgba(229, 9, 20, .14);
  color: #ff747b;
}
#main-prepmark .pm-ve-next-task[data-ve-next-task] {
  position: relative;
}
#main-prepmark .pm-ve-next-task[data-ve-next-task]:focus-visible {
  outline: 2px solid rgba(255, 184, 77, .56);
  outline-offset: 1px;
}

/* ─── /Trailers Conform v3 ──────────────────────────────────────────────── */

/* ─── Main nav tabs: each tab shows its own unique color even when inactive ─ */
#appShell > .tabs .tab:not(.active) {
  color: var(--pfx-top-tab-glow, var(--txt));
  opacity: 0.72;
  filter: none;
}
#appShell > .tabs .tab:not(.active) .bar {
  background: var(--pfx-top-tab-glow, var(--line-3)) !important;
  opacity: 0.22;
  box-shadow: none;
}
#appShell > .tabs .tab:not(.active):hover {
  opacity: 0.92;
}
/* ─── /Main nav tabs unique colors ──────────────────────────────────────── */

/* ─── PULLS PREP — Timeline canvas import overlay ───────────────────────── */
.edl-tl-import-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(6,6,18,.92);
  z-index: 50;
  pointer-events: all;
  border-radius: inherit;
}
.edl-tl-import-overlay.edl-tl-import-hidden {
  display: none;
}
.edl-tl-import-row {
  display: flex;
  align-items: stretch;
  gap: 0;
  width: 88%;
  max-width: 560px;
}
.edl-tl-import-zone {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 28px 20px;
  border: 1px dashed #2a2a50;
  border-radius: 8px;
  background: rgba(12,12,30,.6);
  transition: border-color .15s, background .15s;
  cursor: default;
}
.edl-tl-import-zone:hover { border-color: #3a3a70; }
.edl-tl-import-zone.edl-drag-over {
  border-color: #ff5f7a;
  background: rgba(255,95,122,.08);
}
