/* ─── PULLS PREP — Quick Import Bar (timeline + video) ──────────────────── */
.edl-qib {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  height: 30px;
  min-height: 30px;
  flex-shrink: 0;
  background: #080812;
  border-bottom: 1px solid #181830;
  margin-bottom: 4px;
}
.edl-qib-slot {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  min-width: 0;
  background: #0d0d22;
  border: 1px solid #252545;
  border-radius: 4px;
  padding: 3px 8px;
  height: 22px;
  cursor: default;
  transition: border-color .15s, background .15s;
}
.edl-qib-slot.edl-drag-over {
  border-color: #ff5f7a;
  background: rgba(255,95,122,.08);
}
.edl-qib-slot.edl-qib-loaded {
  border-color: rgba(255,95,122,.4);
  background: rgba(255,95,122,.04);
}
.edl-qib-slot-video.edl-drag-over {
  border-color: #74b0c9;
  background: rgba(114,230,255,.08);
}
.edl-qib-slot-video.edl-qib-loaded {
  border-color: rgba(114,230,255,.4);
  background: rgba(114,230,255,.04);
}
.edl-qib-ico {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  opacity: .45;
  color: #ff5f7a;
}
.edl-qib-slot-video .edl-qib-ico { color: #74b0c9; }
.edl-qib-slot.edl-qib-loaded .edl-qib-ico,
.edl-qib-slot.edl-drag-over .edl-qib-ico { opacity: .9; }
.edl-qib-tag {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .06em;
  flex-shrink: 0;
  color: #ff5f7a;
  opacity: .65;
}
.edl-qib-tag-video { color: #74b0c9; }
.edl-qib-slot.edl-drag-over .edl-qib-tag,
.edl-qib-slot.edl-qib-loaded .edl-qib-tag { opacity: 1; }
.edl-qib-label {
  font-size: 9px;
  color: #3e3e60;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.edl-qib-slot.edl-qib-loaded .edl-qib-label { color: #8888b8; }
.edl-qib-btn {
  font-size: 9px !important;
  padding: 1px 6px !important;
  min-height: 16px !important;
  height: 16px !important;
  flex-shrink: 0;
  line-height: 1 !important;
}
.edl-qib-divider {
  width: 1px;
  height: 16px;
  background: #1c1c38;
  flex-shrink: 0;
  margin: 0 2px;
}
