/* ═══════════════════════════════════════════════════════════════════════════
   PFX AUTH — User badge, Login modal, Account modal
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Header user badge ────────────────────────────────────────────────────── */
.pfx-user-badge {
  display: flex; align-items: center;
  margin: 0 4px 0 0;
}
.pfx-user-btn {
  display: flex; align-items: center; gap: 5px;
  padding: 3px 6px; border-radius: 20px;
  background: transparent; border: 1px solid transparent;
  cursor: pointer; transition: background 0.15s, border-color 0.15s;
  color: #888;
}
.pfx-user-btn:hover {
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.12);
  color: #c0c0d0;
}
.pfx-user-avatar-wrap { position: relative; width: 22px; height: 22px; flex-shrink: 0; }
.pfx-user-avatar-img {
  width: 22px; height: 22px; border-radius: 50%;
  object-fit: cover; display: none;
  border: 1.5px solid rgba(255,255,255,0.15);
}
.pfx-user-icon-wrap {
  display: flex; align-items: center; justify-content: center;
  width: 22px; height: 22px; border-radius: 50%;
  background: rgba(255,255,255,0.06); color: #666;
}
.pfx-user-plan-chip {
  font-size: 9px; font-weight: 700; letter-spacing: 0.6px;
  padding: 1px 5px; border-radius: 3px; border: 1px solid;
  line-height: 14px;
}

/* ── Shared modal backdrop ───────────────────────────────────────────────── */
.pfx-modal-backdrop {
  position: fixed; inset: 0; z-index: 99999;
  display: flex; align-items: center; justify-content: center;
}
.pfx-modal-backdrop[hidden] { display: none; }
.pfx-modal-scrim {
  position: absolute; inset: 0;
  background: rgba(0,0,4,0.78);
  backdrop-filter: blur(4px);
}
.pfx-modal-close {
  position: absolute; top: 12px; right: 12px; z-index: 2;
  width: 24px; height: 24px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.1);
  color: #666; cursor: pointer; transition: color 0.15s, background 0.15s;
}
.pfx-modal-close:hover { background: rgba(255,255,255,0.12); color: #ccc; }

/* ── Login modal ─────────────────────────────────────────────────────────── */
.pfx-login-box {
  position: relative; z-index: 1;
  width: min(480px, 96vw);
  background: linear-gradient(160deg, #0d0d1f 0%, #080812 100%);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 32px 36px 28px;
  box-shadow: 0 32px 80px rgba(0,0,0,0.7), 0 0 0 1px rgba(255,255,255,0.04);
  overflow-y: auto; max-height: 92vh;
}
.pfx-login-brand {
  text-align: center; margin-bottom: 24px;
}
.pfx-login-logo {
  width: 52px; height: 52px; border-radius: 12px; margin-bottom: 10px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.4);
}
.pfx-login-title {
  font-size: 20px; font-weight: 700; color: #e8e8f0; letter-spacing: 0.3px;
}
.pfx-login-tagline {
  font-size: 11px; color: #555; margin-top: 3px; letter-spacing: 0.3px;
}

/* Google button */
.pfx-google-btn {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  width: 100%; padding: 11px 16px; margin-bottom: 10px;
  border-radius: 8px; border: 1px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.05); color: #d8d8e8;
  font-size: 13px; font-weight: 500; cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}
.pfx-google-btn:hover:not(:disabled) {
  background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.22);
}
.pfx-google-btn:active:not(:disabled) { transform: scale(0.98); }
.pfx-google-btn:disabled { opacity: 0.55; cursor: not-allowed; }

.pfx-login-error {
  font-size: 11px; color: #E5484D; background: rgba(224,108,117,0.1);
  border: 1px solid rgba(224,108,117,0.25); border-radius: 6px;
  padding: 7px 10px; margin-bottom: 10px;
}

/* Divider */
.pfx-login-divider {
  position: relative; text-align: center; margin: 20px 0 16px;
}
.pfx-login-divider::before {
  content: ''; position: absolute; top: 50%; left: 0; right: 0;
  height: 1px; background: rgba(255,255,255,0.07);
}
.pfx-login-divider span {
  position: relative; background: #0d0d1f;
  padding: 0 10px; font-size: 10px; color: #444; letter-spacing: 0.5px;
  text-transform: uppercase;
}

/* Plan cards grid */
/* Access notice block */
.pfx-access-notice {
  display: flex; align-items: flex-start; gap: 12px;
  background: rgba(220, 38, 38, 0.07);
  border: 1px solid rgba(220, 38, 38, 0.2);
  border-radius: 10px;
  padding: 14px 16px;
  margin-bottom: 12px;
  color: #e88;
}
.pfx-access-notice-icon {
  flex-shrink: 0; opacity: 0.7; margin-top: 1px;
}
.pfx-access-notice-title {
  font-size: 12px; font-weight: 700; color: #ffb3b3;
  margin-bottom: 4px; letter-spacing: 0.2px;
}
.pfx-access-notice-desc {
  font-size: 11px; color: #aa7070; line-height: 1.5;
}

/* Contact card */
.pfx-contact-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  padding: 16px 18px 14px;
  margin-bottom: 14px;
  text-align: center;
}
.pfx-contact-card-label {
  font-size: 10px; color: #555; letter-spacing: 0.5px;
  text-transform: uppercase; margin-bottom: 8px;
}
.pfx-contact-card-team {
  font-size: 15px; font-weight: 700; color: #e8e8f0;
  line-height: 1.4; margin-bottom: 10px;
}
.pfx-contact-card-team span {
  color: #e50914;
}
.pfx-contact-card-hint {
  font-size: 10.5px; color: #4a4a5a; line-height: 1.6;
  border-top: 1px solid rgba(255,255,255,0.05);
  padding-top: 10px; margin-top: 2px;
}

.pfx-login-terms {
  font-size: 9px; color: #333; text-align: center; margin-top: 4px;
}

/* ── Account modal ───────────────────────────────────────────────────────── */
.pfx-account-box {
  position: relative; z-index: 1;
  width: min(380px, 94vw);
  background: linear-gradient(160deg, #0d0d1f 0%, #080812 100%);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 14px; padding: 28px 24px 20px;
  box-shadow: 0 24px 60px rgba(0,0,0,0.7);
}
.pfx-account-header {
  display: flex; align-items: center; gap: 14px; margin-bottom: 20px;
}
.pfx-account-avatar-wrap { position: relative; flex-shrink: 0; }
.pfx-account-avatar {
  width: 50px; height: 50px; border-radius: 50%; object-fit: cover;
  border: 2px solid rgba(255,255,255,0.12);
}
.pfx-account-avatar-fallback {
  width: 50px; height: 50px; border-radius: 50%;
  background: linear-gradient(135deg, #1e1e3a, #2a2a50);
  border: 2px solid rgba(255,255,255,0.1);
  display: none; align-items: center; justify-content: center;
  font-size: 18px; font-weight: 700; color: #7070a0; letter-spacing: 1px;
}
.pfx-account-name  { font-size: 14px; font-weight: 600; color: #d8d8e8; }
.pfx-account-email { font-size: 11px; color: #555; margin: 2px 0 6px; }
.pfx-account-plan-badge {
  font-size: 9px; font-weight: 700; letter-spacing: 0.8px;
  padding: 2px 8px; border-radius: 4px; border: 1px solid;
  display: inline-block;
}
.pfx-account-section {
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: 14px 0 0; margin-bottom: 4px;
}
.pfx-account-section-sm { padding-top: 10px; margin-top: 4px; }
.pfx-account-section-title {
  font-size: 9px; font-weight: 600; letter-spacing: 0.8px; text-transform: uppercase;
  color: #404060; margin-bottom: 8px;
}
.pfx-account-feats {
  display: flex; flex-direction: column; gap: 3px; margin-bottom: 10px;
}
.pfx-acc-feat-item {
  font-size: 11px; color: #787898; display: flex; align-items: center; gap: 7px;
}
.pfx-acc-feat-check { color: #0AA356; font-size: 10px; flex-shrink: 0; }
.pfx-acc-feat-full { color: #0AA356; }
.pfx-acc-feats-section-label {
  font-size: 9px; font-weight: 700; letter-spacing: 0.8px;
  text-transform: uppercase; color: #404060;
  margin-bottom: 2px; margin-top: 2px;
}
.pfx-account-session-info { font-size: 10px; color: #404060; }

.pfx-upgrade-btn {
  width: 100%; padding: 9px; border-radius: 8px; margin-top: 4px;
  background: linear-gradient(90deg, #2a1e00, #1e1600);
  border: 1px solid rgba(214,163,58,0.3); color: #2172E3;
  font-size: 12px; font-weight: 600; cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.pfx-upgrade-btn:hover { background: linear-gradient(90deg, #3a2800, #2a1e00); border-color: rgba(214,163,58,0.5); }

.pfx-account-footer {
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 14px; display: flex; justify-content: space-between; align-items: center;
}
.pfx-btn-ghost {
  font-size: 10px; color: #484870; background: none; border: none;
  cursor: pointer; padding: 4px 8px; border-radius: 4px;
  transition: color 0.15s, background 0.15s;
}
.pfx-btn-ghost:hover:not(:disabled) { color: #8080b0; background: rgba(255,255,255,0.04); }
.pfx-btn-ghost:disabled { opacity: 0.4; cursor: not-allowed; }
.pfx-signout-btn {
  font-size: 11px; color: #E5484D; background: rgba(224,108,117,0.08);
  border: 1px solid rgba(224,108,117,0.2); border-radius: 6px;
  padding: 5px 12px; cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.pfx-signout-btn:hover { background: rgba(224,108,117,0.16); border-color: rgba(224,108,117,0.4); }

/* Desktop profile editor ── */
.pfx-desktop-profile-section { margin-top: 4px; }
.pfx-dp-field { margin-bottom: 8px; }
.pfx-dp-label {
  display: block; font-size: 9px; font-weight: 600; letter-spacing: 0.7px;
  text-transform: uppercase; color: #404060; margin-bottom: 4px;
}
.pfx-dp-input {
  width: 100%; box-sizing: border-box;
  background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.10);
  border-radius: 6px; padding: 7px 10px;
  font-size: 12px; color: #c8c8e0; outline: none;
  transition: border-color 0.15s;
}
.pfx-dp-input::placeholder { color: #333350; }
.pfx-dp-input:focus { border-color: rgba(90,167,255,0.40); }
.pfx-dp-row { display: flex; align-items: center; gap: 10px; margin-top: 4px; }
.pfx-dp-save-btn {
  padding: 6px 16px; border-radius: 6px; font-size: 11px; font-weight: 600;
  background: rgba(90,167,255,0.14); border: 1px solid rgba(90,167,255,0.34);
  color: #7bb8ff; cursor: pointer; transition: background 0.15s, border-color 0.15s;
}
.pfx-dp-save-btn:hover { background: rgba(90,167,255,0.22); border-color: rgba(90,167,255,0.50); }
.pfx-dp-status { font-size: 10px; color: #0AA356; }
