.sm-anno-frame-lock{
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: contain !important;
  border-radius: 18px !important;
  pointer-events: none !important;
  z-index: 1 !important;
  /* Start hidden — only revealed after load check to prevent black-frame flash */
  opacity: 0 !important;
  transition: opacity 0.18s ease !important;
}
/* Canvas stays absolute (inset:0) so it overlays correctly; just needs z-index above frame-lock */
.sm-anno-canvas{
  z-index: 2 !important;
  /* translateZ(0) promotes canvas to its own GPU compositing layer so the aurora
     background-position animation on the modal doesn't sweep it into that paint region.
