/* ═══════════════════════════════════════════════════════════════════════════
   ANNOTATE — AI SMART UI LEVEL 2 (v2.5)
   ═══════════════════════════════════════════════════════════════════════════ */

/* Extra keyframes */
@keyframes sm-anno-spin {
  to { transform: rotate(360deg); }
}
@keyframes sm-anno-ai-pulse {
  0%,100% { box-shadow: 0 0 10px rgba(84,213,255,0.06), inset 0 1px 0 rgba(255,255,255,0.04); }
  50%      { box-shadow: 0 0 24px rgba(84,213,255,0.16), inset 0 1px 0 rgba(255,255,255,0.07); }
}

/* Modal — animated aurora border (background set via JS; animation applied here) */
.mps-modal.sm-anno-modal {
  will-change: background-position !important;
  animation: sm-anno-aurora-border 4s ease-in-out infinite !important;
  box-shadow:
    0 28px 70px rgba(0,0,0,0.55),
    0 0 0 1px rgba(255,255,255,0.04) inset,
    0 0 60px rgba(84,213,255,0.05),
    0 0 80px rgba(176,108,255,0.04) !important;
}

/* When AI is scanning — the whole modal glows more intensely */
.mps-modal.sm-anno-modal.is-ai-scanning {
  animation-duration: 1.0s !important;
  box-shadow:
    0 28px 70px rgba(0,0,0,0.55),
    0 0 0 1px rgba(255,255,255,0.06) inset,
    0 0 80px rgba(84,213,255,0.12),
    0 0 120px rgba(176,108,255,0.07) !important;
}

/* Toolbar bottom accent line */
.sm-anno-toolbar {
  position: relative !important;
}
.sm-anno-toolbar::after {
  content: '' !important;
  position: absolute !important;
  bottom: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: 1px !important;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(84,213,255,0.28) 25%,
    rgba(176,108,255,0.22) 55%,
    rgba(84,213,255,0.28) 80%,
    transparent 100%) !important;
  background-size: 200% 100% !important;
  animation: sm-anno-headline 3s ease-in-out infinite !important;
  pointer-events: none !important;
}

/* Headstack line faster during AI scanning */
.sm-anno-modal.is-ai-scanning .sm-anno-head .sm-anno-headstack::before {
  animation-duration: 0.9s !important;
}
.sm-anno-modal.is-ai-scanning .sm-anno-ai-group {
  animation-duration: 0.8s !important;
}

/* Annotate label — glowing sparkle prefix */
.sm-anno-label-spark {
  color: rgba(84,213,255,0.90) !important;
  -webkit-text-fill-color: rgba(84,213,255,0.90) !important;
  font-size: 14px !important;
  line-height: 1 !important;
  filter: drop-shadow(0 0 5px rgba(84,213,255,0.60)) !important;
  display: inline-block !important;
  margin-right: 0px !important;
  animation: sm-anno-ai-pulse 2.8s ease-in-out infinite !important;
}

/* AI button spinner arc when detecting */
.sm-anno-ai-btn.is-detecting::before {
  content: '' !important;
  position: absolute !important;
  inset: -4px !important;
  border-radius: 13px !important;
  border: 1.5px solid transparent !important;
  border-top-color: rgba(84,213,255,0.92) !important;
  border-right-color: rgba(84,213,255,0.28) !important;
  animation: sm-anno-spin 0.60s linear infinite !important;
  pointer-events: none !important;
  z-index: 3 !important;
}

/* AI group — combined aurora + pulse animations */
.sm-anno-ai-group {
  animation: sm-anno-aurora-border 3.2s ease-in-out infinite, sm-anno-ai-pulse 2.8s ease-in-out infinite !important;
}

/* AI chip — more prominent */
.sm-anno-ai-chip {
  font-size: 8px !important;
  font-weight: 900 !important;
  letter-spacing: 1.3px !important;
  padding: 2px 6px !important;
  border: 1px solid rgba(84,213,255,0.55) !important;
  box-shadow: 0 0 8px rgba(84,213,255,0.22), 0 0 2px rgba(84,213,255,0.50) !important;
  color: rgba(155,232,255,0.97) !important;
}

/* Stage — technical grid (lines + node dots) */
.sm-anno-stage {
  background:
    radial-gradient(circle at 50% 0%, rgba(22,34,72,0.32), transparent 44%),
    linear-gradient(rgba(84,213,255,0.030) 1px, transparent 1px),
    linear-gradient(90deg, rgba(84,213,255,0.030) 1px, transparent 1px),
    radial-gradient(circle, rgba(84,213,255,0.11) 1.2px, transparent 1.2px),
    linear-gradient(180deg, rgba(6,8,14,1), rgba(3,4,10,1)) !important;
  background-size: 100% 100%, 32px 32px, 32px 32px, 32px 32px, 100% 100% !important;
}

/* Wrap glows during AI scan */
.sm-anno-stage.is-ai-scanning .sm-anno-wrap {
  box-shadow:
    0 18px 48px rgba(0,0,0,0.50),
    0 0 0 1px rgba(84,213,255,0.32),
    0 0 0 3px rgba(84,213,255,0.08),
    0 0 28px rgba(84,213,255,0.14) !important;
}

/* Tool button hover — scale lift */
.sm-anno-iconbtn {
  transition: transform 0.10s ease, background 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease !important;
}
.sm-anno-group:not(.sm-anno-colors):not(.sm-anno-styles) .sm-anno-iconbtn:not(:disabled):hover {
  transform: scale(1.07) !important;
  background: rgba(255,255,255,0.09) !important;
}

/* Tool indicator bar — moved to bottom-center */
.sm-anno-iconbtn .bar {
  top: auto !important;
  left: 50% !important;
  bottom: 3px !important;
  transform: translateX(-50%) !important;
  width: 10px !important;
  height: 2px !important;
  border-radius: 2px !important;
  opacity: 0.18 !important;
}
.sm-anno-iconbtn.is-active-tool .bar {
  background: rgba(84,213,255,0.92) !important;
  box-shadow: 0 0 6px rgba(84,213,255,0.65) !important;
  width: 18px !important;
  opacity: 1 !important;
}


/* ═══════════════════════════════════════════════════════════════════════════
   ANNOTATE — AI SMART UI LEVEL 3 (v2.5)
   ═══════════════════════════════════════════════════════════════════════════ */

/* Per-AI-button unique color identity via CSS var */
[data-act="aiDetectFaces"]   { --ai-c: rgba(210,80,255,0.90); }
[data-act="aiDetectScreens"] { --ai-c: rgba(84,213,255,0.90); }
[data-act="aiDetectText"]    { --ai-c: rgba(46,204,113,0.90); }
[data-act="aiSmartSuggest"]  { --ai-c: rgba(255,193,7,0.90);  }

.sm-anno-ai-btn {
  color: var(--ai-c) !important;
  border-color: color-mix(in srgb, var(--ai-c) 28%, transparent) !important;
}
.sm-anno-ai-btn svg { stroke: var(--ai-c) !important; }

[data-act="aiDetectFaces"]:not(:disabled):hover   { background: rgba(210,80,255,0.11) !important;  border-color: rgba(210,80,255,0.55) !important;  box-shadow: 0 0 14px rgba(210,80,255,0.18) !important; }
[data-act="aiDetectScreens"]:not(:disabled):hover { background: rgba(84,213,255,0.11) !important;  border-color: rgba(84,213,255,0.55) !important;  box-shadow: 0 0 14px rgba(84,213,255,0.18) !important; }
[data-act="aiDetectText"]:not(:disabled):hover    { background: rgba(46,204,113,0.11) !important;  border-color: rgba(46,204,113,0.55) !important;  box-shadow: 0 0 14px rgba(46,204,113,0.18) !important; }
[data-act="aiSmartSuggest"]:not(:disabled):hover  { background: rgba(255,193,7,0.11) !important;   border-color: rgba(255,193,7,0.55) !important;   box-shadow: 0 0 14px rgba(255,193,7,0.18) !important;  }

/* Spinner arc inherits button color */
[data-act="aiDetectFaces"].is-detecting::before   { border-top-color: rgba(210,80,255,0.92) !important;  border-right-color: rgba(210,80,255,0.22) !important;  }
[data-act="aiDetectScreens"].is-detecting::before { border-top-color: rgba(84,213,255,0.92) !important;  border-right-color: rgba(84,213,255,0.22) !important;  }
[data-act="aiDetectText"].is-detecting::before    { border-top-color: rgba(46,204,113,0.92) !important;  border-right-color: rgba(46,204,113,0.22) !important;  }
[data-act="aiSmartSuggest"].is-detecting::before  { border-top-color: rgba(255,193,7,0.92) !important;   border-right-color: rgba(255,193,7,0.22) !important;   }

/* READY / ANALYZING status badge */
.sm-anno-ai-status {
  font-size: 8px !important;
  font-weight: 900 !important;
  letter-spacing: 1.5px !important;
  color: rgba(84,213,255,0.60) !important;
  padding: 3px 9px !important;
  border-radius: 5px !important;
  border: 1px solid rgba(84,213,255,0.18) !important;
  background: rgba(84,213,255,0.04) !important;
  white-space: nowrap !important;
  flex-shrink: 0 !important;
  transition: color 0.25s, border-color 0.25s, background 0.25s, box-shadow 0.25s !important;
}
.sm-anno-ai-status[data-state="analyzing"] {
  color: rgba(84,213,255,0.98) !important;
  border-color: rgba(84,213,255,0.55) !important;
  background: rgba(84,213,255,0.11) !important;
  box-shadow: 0 0 10px rgba(84,213,255,0.16) !important;
  animation: sm-anno-ai-pulse 0.70s ease-in-out infinite !important;
}

/* Color button — ring tracks active color */
.sm-anno-colorbtn {
  --sm-active-color: #ff4c4c;
  box-shadow: 0 0 0 1.5px color-mix(in srgb, var(--sm-active-color) 38%, transparent) !important;
  transition: box-shadow 0.2s !important;
}
.sm-anno-colorbtn:hover {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--sm-active-color) 65%, transparent),
              0 0 10px color-mix(in srgb, var(--sm-active-color) 20%, transparent) !important;
}

/* Group micro-labels above each pill */
.sm-anno-group:not(.sm-anno-ai-group):not(.sm-anno-colors):not(.sm-anno-styles) {
  position: relative !important;
}
.sm-anno-group[role="group"]:not(.sm-anno-ai-group):not(.sm-anno-colors):not(.sm-anno-styles)::before {
  content: attr(aria-label) !important;
  position: absolute !important;
  top: -9px !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  font-size: 6.5px !important;
  font-weight: 900 !important;
  letter-spacing: 1.1px !important;
  text-transform: uppercase !important;
  color: rgba(174,188,225,0.32) !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* Stage — persistent ambient radial glow behind canvas */
.sm-anno-stage::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  z-index: 0 !important;
  pointer-events: none !important;
  background: radial-gradient(ellipse 52% 32% at 50% 48%, rgba(84,213,255,0.045), transparent 70%) !important;
  animation: sm-anno-ai-pulse 5s ease-in-out infinite !important;
}

/* Canvas wrap — ambient slow pulse + flash on AI detection */
@keyframes sm-anno-wrap-pulse {
  0%,100% { box-shadow: 0 18px 48px rgba(0,0,0,0.50), 0 0 0 1px rgba(255,255,255,0.025) inset; }
  50%      { box-shadow: 0 18px 48px rgba(0,0,0,0.50), 0 0 0 1px rgba(84,213,255,0.09) inset, 0 0 24px rgba(84,213,255,0.07); }
}
.sm-anno-wrap {
  transition: box-shadow 0.35s ease !important;
  animation: sm-anno-wrap-pulse 5s ease-in-out infinite !important;
}
.sm-anno-wrap.sm-anno-ai-flash {
  box-shadow:
    0 0 0 2px rgba(84,213,255,0.78),
    0 0 0 5px rgba(84,213,255,0.14),
    0 0 50px rgba(84,213,255,0.32) !important;
  animation: none !important;
}


/* ═══════════════════════════════════════════════════════════════════════════
   ANNOTATE — AI SMART UI LEVEL 4 (v2.5)
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Color-reactive active tool glow ─────────────────────────────────────── */
/* --sm-draw-color is set by JS in __setColor and at modal init              */
.sm-anno-modal { --sm-draw-color: #ff4c4c; }

.sm-anno-group:not(.sm-anno-colors):not(.sm-anno-styles) .sm-anno-iconbtn.is-active-tool {
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--sm-draw-color) 22%, rgba(8,14,28,0.96)) 0%,
    color-mix(in srgb, var(--sm-draw-color) 10%, rgba(8,14,28,0.96)) 100%) !important;
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--sm-draw-color) 40%, transparent),
    0 0 14px color-mix(in srgb, var(--sm-draw-color) 22%, transparent) !important;
}
.sm-anno-group:not(.sm-anno-colors):not(.sm-anno-styles) .sm-anno-iconbtn.is-active-tool svg {
  stroke: var(--sm-draw-color) !important;
  filter: drop-shadow(0 0 5px color-mix(in srgb, var(--sm-draw-color) 75%, transparent)) !important;
}
.sm-anno-iconbtn.is-active-tool .bar {
  background: var(--sm-draw-color) !important;
  box-shadow: 0 0 8px color-mix(in srgb, var(--sm-draw-color) 85%, transparent) !important;
  width: 20px !important;
}

/* ── All 4 corner reticle brackets ──────────────────────────────────────── */
.sm-anno-corner {
  position: absolute !important;
  width: 20px !important;
  height: 20px !important;
  z-index: 6 !important;
  pointer-events: none !important;
  opacity: 0.38 !important;
  transition: opacity 0.3s !important;
}
.sm-anno-corner-tr {
  top: 8px !important; right: 8px !important;
  border-top: 2px solid rgba(84,213,255,0.72) !important;
  border-right: 2px solid rgba(84,213,255,0.72) !important;
  border-radius: 0 3px 0 0 !important;
}
.sm-anno-corner-bl {
  bottom: 8px !important; left: 8px !important;
  border-bottom: 2px solid rgba(84,213,255,0.72) !important;
  border-left: 2px solid rgba(84,213,255,0.72) !important;
  border-radius: 0 0 0 3px !important;
}
.sm-anno-stage.is-ai-scanning .sm-anno-corner { opacity: 1 !important; }

/* ── Canvas vignette — cinematic dark edge on the image ─────────────────── */
.sm-anno-wrap::before,
.sm-anno-wrap::after {
  z-index: 5 !important;
}
.sm-anno-stage::after {
  /* Vignette over the stage edges — doesn't interfere with scan beam
     because scan beam uses .is-ai-scanning::after which is more specific */
}
/* Use a box-shadow inset vignette on the wrap instead */
.sm-anno-wrap {
  box-shadow:
    0 18px 48px rgba(0,0,0,0.50),
    0 0 0 1px rgba(255,255,255,0.025) inset,
    0 0 40px rgba(0,0,0,0.55) inset !important;
}

/* ── Note textarea — glow on focus in draw color ─────────────────────────── */
.sm-anno-noteRow .sm-anno-note:focus {
  border-color: color-mix(in srgb, var(--sm-draw-color) 42%, rgba(84,213,255,0.25)) !important;
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--sm-draw-color) 14%, rgba(84,213,255,0.08)),
    0 0 14px color-mix(in srgb, var(--sm-draw-color) 10%, rgba(84,213,255,0.05)) !important;
  outline: none !important;
}

/* ── Meta fields focus ───────────────────────────────────────────────────── */
.sm-anno-meta select:focus,
.sm-anno-meta input:focus {
  border-color: rgba(84,213,255,0.38) !important;
  box-shadow: 0 0 0 2px rgba(84,213,255,0.10) !important;
  outline: none !important;
}

/* ── Tool button hover — scale + color hint ──────────────────────────────── */
.sm-anno-group:not(.sm-anno-colors):not(.sm-anno-styles) .sm-anno-iconbtn:not(:disabled):hover {
  transform: scale(1.07) !important;
  background: color-mix(in srgb, var(--sm-draw-color) 10%, rgba(255,255,255,0.06)) !important;
  border-color: color-mix(in srgb, var(--sm-draw-color) 22%, rgba(255,255,255,0.10)) !important;
}

/* ── Colorbtn — larger disc, ring matches draw color ─────────────────────── */
.sm-anno-colordisc {
  width: 18px !important;
  height: 18px !important;
  border-radius: 50% !important;
  border: 2px solid rgba(255,255,255,0.22) !important;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.25) !important;
  transition: box-shadow 0.15s !important;
}
.sm-anno-colorbtn:hover .sm-anno-colordisc {
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--sm-active-color, #ff4c4c) 55%, transparent),
    0 0 10px color-mix(in srgb, var(--sm-active-color, #ff4c4c) 30%, transparent) !important;
}

/* ── Active swatch — draw color glow ─────────────────────────────────────── */
.sm-anno-swatch.is-active {
  border-color: rgba(255,255,255,0.75) !important;
  box-shadow:
    0 0 0 2px var(--swatch),
    0 0 14px color-mix(in srgb, var(--swatch) 55%, transparent) !important;
  transform: scale(1.12) !important;
}

/* ── Done button — draw color accent on hover ────────────────────────────── */
.sm-anno-done:hover {
  background: linear-gradient(135deg,
    color-mix(in srgb, var(--sm-draw-color) 18%, rgba(84,213,255,0.20)) 0%,
    rgba(176,108,255,0.18) 100%) !important;
  border-color: color-mix(in srgb, var(--sm-draw-color) 45%, rgba(120,218,255,0.45)) !important;
  color: color-mix(in srgb, var(--sm-draw-color) 35%, rgba(195,243,255,0.97)) !important;
}

/* ── AI group — draw color bleeds into aurora on hover ───────────────────── */
.sm-anno-ai-group:hover {
  background:
    linear-gradient(color-mix(in srgb, var(--sm-draw-color) 6%, rgba(8,14,28,0.85)),
                    color-mix(in srgb, var(--sm-draw-color) 6%, rgba(8,14,28,0.85))) padding-box,
    linear-gradient(90deg,
      color-mix(in srgb, var(--sm-draw-color) 30%, rgba(84,213,255,0.55)),
      rgba(176,108,255,0.48),
      color-mix(in srgb, var(--sm-draw-color) 30%, rgba(84,213,255,0.55))
    ) border-box !important;
}


/* ═══════════════════════════════════════════════════════════════════════════
   ANNOTATE — AI SMART UI LEVEL 5 — PRO (v2.5)
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Keyframes ─────────────────────────────────────────────────────────── */
@keyframes sm-anno-ripple {
  0%   { transform: scale(0.5); opacity: 0.45; }
  100% { transform: scale(2.8); opacity: 0; }
}
@keyframes sm-anno-ai-shimmer {
  0%   { opacity: 0; left: -60%; }
  18%  { opacity: 0.35; }
  82%  { opacity: 0.35; }
  100% { opacity: 0; left: 160%; }
}
@keyframes sm-anno-count-pop {
  0%   { transform: scale(1); }
  40%  { transform: scale(1.35); }
  100% { transform: scale(1); }
}

/* ── Modal — stronger cinematic glass ────────────────────────────────────── */
.mps-modal.sm-anno-modal {
  backdrop-filter: blur(26px) saturate(185%) brightness(0.82) !important;
  -webkit-backdrop-filter: blur(26px) saturate(185%) brightness(0.82) !important;
}

/* ── Annotate label — aurora gradient text ─────────────────────────────── */
.sm-anno-label {
  background: linear-gradient(125deg,
    rgba(224,246,255,0.97) 0%,
    rgba(175,218,255,0.88) 55%,
    rgba(164,128,255,0.82) 100%) !important;
  -webkit-background-clip: text !important;
  background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
}
.sm-anno-label .muted {
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  -webkit-text-fill-color: rgba(150,167,210,0.76) !important;
}
.sm-anno-label-spark {
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  -webkit-text-fill-color: rgba(84,213,255,0.90) !important;
}

/* ── Cursor glow ring on canvas ─────────────────────────────────────────── */
.sm-anno-cursor-glow {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 72px !important;
  height: 72px !important;
  pointer-events: none !important;
  z-index: 8 !important;
  border-radius: 50% !important;
  background: radial-gradient(circle,
    color-mix(in srgb, var(--sm-draw-color) 22%, transparent) 0%,
    transparent 68%) !important;
  transition: opacity 0.14s ease !important;
  opacity: 0 !important;
  /* Own compositing layer — transform updates are GPU-composited (no paint) */
  will-change: transform !important;
  transform: translate(-50%, -50%) translateZ(0) !important;
}

/* ── Live shape counter pill ─────────────────────────────────────────────── */
.sm-anno-shape-count {
  display: inline-flex !important;
  align-items: center !important;
  gap: 2px !important;
  padding: 3px 8px !important;
  border-radius: 6px !important;
  border: 1px solid rgba(255,255,255,0.09) !important;
  background: rgba(255,255,255,0.03) !important;
  flex-shrink: 0 !important;
  transition: border-color 0.2s, background 0.2s !important;
}
.sm-anno-shape-num {
  font-size: 13px !important;
  font-weight: 900 !important;
  letter-spacing: -0.3px !important;
  color: rgba(174,194,230,0.55) !important;
  transition: color 0.2s !important;
  font-variant-numeric: tabular-nums !important;
}
.sm-anno-shape-k {
  font-size: 8px !important;
  font-weight: 800 !important;
  letter-spacing: 0.7px !important;
  color: rgba(160,178,216,0.42) !important;
  text-transform: uppercase !important;
}
.sm-anno-shape-count.has-shapes {
  border-color: color-mix(in srgb, var(--sm-draw-color) 30%, rgba(84,213,255,0.20)) !important;
  background: color-mix(in srgb, var(--sm-draw-color) 8%, rgba(84,213,255,0.05)) !important;
}
.sm-anno-shape-count.has-shapes .sm-anno-shape-num {
  color: color-mix(in srgb, var(--sm-draw-color) 60%, rgba(84,213,255,0.90)) !important;
  animation: sm-anno-count-pop 0.25s ease-out !important;
}
.sm-anno-shape-count.has-shapes .sm-anno-shape-k {
  color: rgba(180,210,250,0.55) !important;
}

/* ── Ripple effect on tool button press ─────────────────────────────────── */
.sm-anno-iconbtn {
  overflow: visible !important;
}
.sm-anno-iconbtn:active::after {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  border-radius: inherit !important;
  background: rgba(255,255,255,0.22) !important;
  animation: sm-anno-ripple 0.32s ease-out forwards !important;
  pointer-events: none !important;
}

/* ── AI button shimmer — periodic scan across icon ──────────────────────── */
.sm-anno-ai-btn {
  overflow: hidden !important;
}
