}
.sm-anno-ai-side-btn .sm-anno-ai-label,
.sm-anno-ai-3d-btn .sm-anno-ai-label {
  color: rgba(140,175,230,0.70) !important;
}

/* Hover: slight brightening — same for all */
.sm-anno-ai-side-btn:hover,
.sm-anno-ai-3d-btn:hover {
  background: rgba(84,213,255,0.08) !important;
  border-color: rgba(84,213,255,0.28) !important;
}
.sm-anno-ai-side-btn:hover svg,
.sm-anno-ai-3d-btn:hover svg {
  stroke: rgba(185,225,255,0.90) !important;
}
.sm-anno-ai-side-btn:hover .sm-anno-ai-label,
.sm-anno-ai-3d-btn:hover .sm-anno-ai-label {
