/* UNIFIED active state — single cyan glow for ALL toggle buttons */
.sm-anno-ai-side-btn.is-active-tool,
.sm-anno-ai-3d-btn.is-active-tool,
[data-act].is-active-tool.sm-anno-ai-btn {
  background: rgba(84,213,255,0.12) !important;
  border: 1px solid rgba(84,213,255,0.50) !important;
  box-shadow: 0 0 10px rgba(84,213,255,0.18), inset 0 0 0 1px rgba(84,213,255,0.08) !important;
  animation: sm-anno-detect-glow 1.2s ease-in-out infinite !important;
}
.sm-anno-ai-side-btn.is-active-tool svg,
.sm-anno-ai-3d-btn.is-active-tool svg,
[data-act].is-active-tool.sm-anno-ai-btn svg {
