}
.sm-anno-ai-side-btn.is-active-tool .sm-anno-ai-label,
.sm-anno-ai-3d-btn.is-active-tool .sm-anno-ai-label,
[data-act].is-active-tool.sm-anno-ai-btn .sm-anno-ai-label {
  color: rgba(134,233,255,0.92) !important;
}

/* ── IS-RUNNING: the ONE button currently executing ─────────────────────────
   Visually dominant vs. the dimmed is-detecting state on all other buttons.
   Shows: bright white-to-cyan spinning border + glowing background + "RUNNING" label.
   ──────────────────────────────────────────────────────────────────────────── */

@keyframes sm-anno-run-spin {
  0%   { transform: rotate(0deg);   }
  100% { transform: rotate(360deg); }
}
@keyframes sm-anno-run-pulse {
  0%,100% { box-shadow: 0 0 0   rgba(255,255,255,0.0),  inset 0 0 0   rgba(255,255,255,0.0); }
  50%     { box-shadow: 0 0 14px rgba(84,213,255,0.55), inset 0 0 6px rgba(84,213,255,0.10); }
}

/* Base is-running state */
.sm-anno-ai-side-btn.is-running,
.sm-anno-ai-3d-btn.is-running {
  background: rgba(14,24,44,0.92) !important;
  border-color: rgba(84,213,255,0.70) !important;
  color: #fff !important;
  animation: sm-anno-run-pulse 1.0s ease-in-out infinite !important;
  position: relative !important;
  overflow: visible !important;
  z-index: 2 !important;
}

/* Spinning arc — a conic-gradient border that rotates around the button */
.sm-anno-ai-side-btn.is-running::before,
.sm-anno-ai-3d-btn.is-running::before {
  content: '' !important;
  position: absolute !important;
  inset: -3px !important;
  border-radius: 13px !important;
  background: conic-gradient(
    from 0deg,
    rgba(84,213,255,0.0)   0%,
    rgba(84,213,255,0.90) 35%,
    rgba(255,255,255,1.0) 50%,
    rgba(84,213,255,0.90) 65%,
    rgba(84,213,255,0.0) 100%
  ) !important;
  animation: sm-anno-run-spin 0.85s linear infinite !important;
  z-index: -1 !important;
  pointer-events: none !important;
}

/* Inner mask so the spinning arc only shows as a border ring */
.sm-anno-ai-side-btn.is-running::after,
.sm-anno-ai-3d-btn.is-running::after {
  content: '' !important;
  position: absolute !important;
  inset: 0px !important;
  border-radius: 10px !important;
  background: rgba(10,18,36,0.94) !important;
  z-index: -1 !important;
  pointer-events: none !important;
}

/* Icon and label brighter when running */
.sm-anno-ai-side-btn.is-running svg,
.sm-anno-ai-3d-btn.is-running svg {
  stroke: rgba(84,213,255,0.95) !important;
}
.sm-anno-ai-side-btn.is-running .sm-anno-ai-label,
.sm-anno-ai-3d-btn.is-running .sm-anno-ai-label {
  color: rgba(134,233,255,1.0) !important;
  font-weight: 900 !important;
}

/* Non-running buttons during detection: dim them down so the running one stands out */
.is-ai-scanning .sm-anno-ai-side-btn.is-detecting,
.is-ai-scanning .sm-anno-ai-3d-btn.is-detecting {
  opacity: 0.38 !important;
  filter: saturate(0.4) !important;
  animation: none !important;
}
.is-ai-scanning .sm-anno-ai-side-btn.is-detecting::before,
.is-ai-scanning .sm-anno-ai-3d-btn.is-detecting::before {
  display: none !important;
}

/* SCAN ALL — primary action, spans full width with aurora shimmer */
.sm-anno-ai-scan-all {
  width: 100% !important;
  height: 36px !important;
  background:
    linear-gradient(rgba(6,10,22,0.90), rgba(6,10,22,0.90)) padding-box,
    linear-gradient(135deg, rgba(84,213,255,0.65), rgba(176,108,255,0.50), rgba(84,213,255,0.65)) border-box !important;
  border: 1px solid transparent !important;
  background-size: 100% 100%, 200% 100% !important;
  will-change: background-position !important;
  animation: sm-anno-aurora-border 2.4s ease-in-out infinite !important;
}
.sm-anno-ai-scan-all svg { stroke: rgba(160,230,255,0.90) !important; }
.sm-anno-ai-scan-all .sm-anno-ai-label { color: rgba(160,230,255,0.88) !important; }
.sm-anno-ai-scan-all:hover { box-shadow: 0 0 12px rgba(84,213,255,0.24) !important; }

/* Scanning: whole sidebar glows */
.sm-anno-stage.is-ai-scanning .sm-anno-ai-sidebar {
  border-color: rgba(84,213,255,0.55) !important;
  box-shadow:
    0 8px 32px rgba(0,0,0,0.50),
    0 0 28px rgba(84,213,255,0.18) !important;
  animation: sm-anno-detect-glow 0.8s ease-in-out infinite !important;
}

/* Divider */
.sm-anno-ai-divider {
  width: 100% !important;
  height: 1px !important;
  background: linear-gradient(90deg, transparent, rgba(84,213,255,0.18), transparent) !important;
  margin: 1px 0 !important;
  flex-shrink: 0 !important;
}

/* Smooth Path active feedback */
[data-act="aiSmoothPath"]:active { opacity: 0.7 !important; }

/* ═══════════════════════════════════════════════════════════════════════════
   RENDER QUEUE TAB
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Tab chrome ─────────────────────────────────────────────────────────── */
.tab.theme-renderq            { color: #888; }
.tab.theme-renderq .bar       { background: #E0B341; }
.tab.theme-renderq.active     { color: #E0B341; }
.tab.theme-renderq svg        { color: inherit; }

/* Badge on Export button showing queued count */
.rq-export-badge {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 15px; height: 15px; padding: 0 4px;
  background: #E0B341; color: #0a0f1a;
  font: 700 9px/1 ui-monospace,monospace; border-radius: 8px;
  margin-left: 5px; vertical-align: middle;
}

/* ── Pane shell ──────────────────────────────────────────────────────────── */
.rq-pane { box-sizing: border-box; }
.rq-shell {
  display: flex; flex-direction: column;
  height: calc(100vh - 86px);
  padding: 16px 20px; gap: 0;
  box-sizing: border-box; overflow: hidden;
}

/* ── Header ──────────────────────────────────────────────────────────────── */
.rq-header {
  display: flex; align-items: center; justify-content: space-between;
  padding-bottom: 12px; border-bottom: 1px solid #1a2540; flex-shrink: 0;
}
.rq-header-left  { display: flex; align-items: center; gap: 8px; color: #E0B341; }
.rq-header-title {
  font: 600 13px/1 ui-monospace,monospace; letter-spacing: .05em;
  text-transform: uppercase; color: #E0B341;
}
.rq-header-controls { display: flex; gap: 8px; }

/* ── Control buttons ─────────────────────────────────────────────────────── */
.rq-ctrl-btn {
  font: 11px/1.4 ui-monospace,monospace; padding: 5px 11px;
  border-radius: 5px; cursor: pointer; border: 1px solid;
  transition: background .15s, color .15s;
}
.rq-btn-pause        { background: #0d1a2e; border-color: #2a5070; color: #7ab4d8; }
.rq-btn-pause:hover  { background: #142038; color: #9fd0f0; }
.rq-btn-resume       { background: #0d2010; border-color: #2a6030; color: #7ac87a; }
.rq-btn-resume:hover { background: #0f2a14; color: #9de09d; }
.rq-btn-clear        { background: #0d1220; border-color: #1e2e4a; color: #5070a0; }
.rq-btn-clear:hover:not(:disabled) { background: #121830; color: #7090c0; }
.rq-btn-clear:disabled { opacity: .4; cursor: default; }
.rq-btn-stop        { background: rgba(160,40,30,.22); border-color: rgba(220,80,60,.45); color: #e88070; }
.rq-btn-stop:hover:not(:disabled) { background: rgba(160,40,30,.38); border-color: rgba(220,80,60,.75); color: #f4a090; }
.rq-btn-stop:disabled { opacity: .45; cursor: default; }

/* ── Status bar ──────────────────────────────────────────────────────────── */
.rq-status-bar {
  margin: 10px 0 0; padding: 7px 12px;
  font: 11px/1 ui-monospace,monospace; border-radius: 5px;
  border-left: 3px solid; flex-shrink: 0;
}
.rq-sb-idle    { background: #080e1a; border-color: #1e2e4a; color: #4060a0; }
.rq-sb-ready   { background: #0a1520; border-color: #2a5090; color: #6090d0; }
.rq-sb-running { background: #0a1820; border-color: #E0B341; color: #E0B341;
  animation: rq-pulse 2s ease-in-out infinite; }
.rq-sb-paused  { background: #120e08; border-color: #604020; color: #a07040; }
.rq-sb-blocked { background: #0e0c08; border-color: #806030; color: #c0a050;
  animation: rq-pulse 2.5s ease-in-out infinite; }
@keyframes rq-pulse { 0%,100% { opacity: 1; } 50% { opacity: .7; } }

/* ── System info panel (static specs) ───────────────────────────────────── */
.rq-sys-panel {
  display: flex; align-items: center; flex-wrap: wrap;
  gap: 6px; margin: 8px 0 0; padding: 7px 12px;
  border-radius: 8px; background: #060b14;
  border: 1px solid #1a2840; flex-shrink: 0;
}
.rq-sysp-chip {
  display: flex; align-items: baseline; gap: 6px;
  font: 11px/1 ui-monospace,monospace;
  white-space: nowrap; overflow: hidden;
}
.rq-sysp-lbl {
  font: 700 8px/1 ui-monospace,monospace;
  text-transform: uppercase; letter-spacing: .1em;
  color: rgba(255,255,255,.3); flex-shrink: 0;
}
.rq-sysp-chip span:not(.rq-sysp-lbl) {
  color: rgba(255,255,255,.65);
  font-variant-numeric: tabular-nums;
  overflow: hidden; text-overflow: ellipsis;
}
.rq-sysp-dot {
  width: 3px; height: 3px; border-radius: 50%;
  background: rgba(255,255,255,.15); flex-shrink: 0;
}

/* ── Hint row ────────────────────────────────────────────────────────────── */
.rq-hint-row {
  margin: 8px 0 4px;
  font: 10.5px/1.5 -apple-system,sans-serif; color: #7898b8; flex-shrink: 0;
}
.rq-hint-row strong { color: #5a7090; }

/* ── Job list ────────────────────────────────────────────────────────────── */
.rq-job-list {
  flex: 1; overflow-y: auto; margin-top: 8px; padding-right: 4px;
  display: flex; flex-direction: column; gap: 6px;
}
.rq-job-list::-webkit-scrollbar       { width: 4px; }
.rq-job-list::-webkit-scrollbar-track { background: transparent; }
.rq-job-list::-webkit-scrollbar-thumb { background: #1e2e4a; border-radius: 2px; }

/* ── Empty state ─────────────────────────────────────────────────────────── */
.rq-empty {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  flex: 1; gap: 10px; color: #2a4060; text-align: center;
  font: 12px/1.6 -apple-system,sans-serif; padding: 40px 0;
}
.rq-empty p         { margin: 0; }
.rq-empty-hint      { font-size: 11px; color: #223048; }
.rq-empty-hint strong { color: #7898b8; }

/* ── Job card ────────────────────────────────────────────────────────────── */
.rq-job {
  background: #080e1a; border: 1px solid #1a2840;
  border-radius: 8px; padding: 10px 12px;
  transition: border-color .15s, background .15s;
}
.rq-job:hover              { border-color: #2a3a60; }
.rq-job-running            { border-color: #2a5080 !important; background: #060d1c; }
.rq-job-cancelling         { border-color: #604020 !important; background: #0a0c10; }
.rq-job-done               { border-color: #1a3020; }
.rq-job-error              { border-color: #3a1820; background: #0a0810; }
.rq-job-cancelled          { border-color: #2a2010; opacity: .75; }
.rq-job-blocked            { border-color: #504020 !important; background: #0b0e0a; }

/* Flash on dupe detection */
@keyframes rq-flash { 0%,100% { border-color: inherit; } 50% { border-color: #e8c84a; } }
.rq-job-flash { animation: rq-flash .35s ease 2; }

/* ── Card head row ───────────────────────────────────────────────────────── */
.rq-job-head {
  display: flex; align-items: center; gap: 6px; margin-bottom: 6px;
}

/* Status icon */
.rq-job-icon {
  display: flex; align-items: center; justify-content: center;
  width: 15px; flex-shrink: 0;
}
.rq-svg-icon { display: block; }
.rq-icon-pending   { color: #3a5a80; }
.rq-icon-running   { color: #E0B341; }
.rq-icon-cancelling { color: #c07030; }
.rq-icon-done      { color: #5c9e5c; }
.rq-icon-error     { color: #a03838; }
.rq-icon-cancelled { color: #604030; }
.rq-icon-blocked   { color: #c09030; }

/* Spinner animation on SVG circle element */
.rq-spinner { overflow: visible; }
.rq-icon-running   .rq-spinner,
.rq-icon-cancelling .rq-spinner {
  animation: rq-spin 1s linear infinite;
}
@keyframes rq-spin { to { transform: rotate(360deg); transform-origin: 8px 8px; } }

/* Module source badge */
.rq-mod-badge {
  font: 700 8px/1 ui-monospace,monospace; padding: 2px 5px;
  border-radius: 3px; border: 1px solid; text-transform: uppercase;
  letter-spacing: .04em; flex-shrink: 0;
}

/* Job label */
.rq-job-label {
  flex: 1; font: 12px/1 ui-monospace,monospace; color: #b0c8e8;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0;
}
.rq-job-running   .rq-job-label { color: #c8dcf8; }
.rq-job-done      .rq-job-label { color: #608060; }
.rq-job-error     .rq-job-label { color: #906060; }
.rq-job-cancelled .rq-job-label { color: #604040; }
.rq-job-blocked   .rq-job-label { color: #907050; }

/* Resumed tag */
.rq-tag-resumed {
  font: 700 8px/1 ui-monospace,monospace; padding: 2px 5px;
  background: #1a1808; color: #807040; border: 1px solid #403810;
  border-radius: 3px; flex-shrink: 0; white-space: nowrap;
}

/* Status badge */
.rq-badge {
  font: 700 9px/1 ui-monospace,monospace; padding: 2px 6px;
  border-radius: 3px; text-transform: uppercase; flex-shrink: 0;
}
.rq-badge-pending    { background: #0d1a30; color: #4a6a90; border: 1px solid #1e3050; }
.rq-badge-running    { background: #1a2840; color: #E0B341; border: 1px solid #E0B34140; }
.rq-badge-cancelling { background: #1a1208; color: #c07030; border: 1px solid #60301040; }
.rq-badge-done       { background: #0d2010; color: #5c9e5c; border: 1px solid #2a5030; }
.rq-badge-error      { background: #200a0a; color: #a03838; border: 1px solid #4a1a1a; }
.rq-badge-cancelled  { background: #1a1008; color: #604030; border: 1px solid #3a2010; }
.rq-badge-blocked    { background: #1a1408; color: #c09030; border: 1px solid #604020; }

/* ── Action buttons inside card ──────────────────────────────────────────── */
.rq-job-acts { display: flex; gap: 4px; flex-shrink: 0; }
.rq-act {
  font: 10px/1 ui-monospace,monospace; padding: 3px 7px;
  border-radius: 4px; cursor: pointer; border: 1px solid;
  transition: background .12s, color .12s;
}
.rq-act:disabled { opacity: .45; cursor: default; }
.rq-act-remove { background: #0d1220; border-color: #1e2e4a; color: #4060a0; }
.rq-act-remove:hover:not(:disabled) { background: #1a0a0a; border-color: #4a1a1a; color: #a04040; }
.rq-act-stop   { background: #1a0c08; border-color: #503020; color: #c07050; }
.rq-act-stop:hover:not(:disabled)   { background: #200e08; border-color: #703820; color: #e08060; }
.rq-act-retry  { background: #0d1220; border-color: #2a4060; color: #6090b0; }
.rq-act-retry:hover  { background: #0a1a30; color: #90c0e0; }
.rq-act-up     { background: #0d1220; border-color: #1a3050; color: #4a6a90; }
.rq-act-up:hover     { background: #0a1830; color: #7aace0; }
.rq-max-retries {
  font: 10px/1 ui-monospace,monospace; color: #604040;
  padding: 3px 6px; white-space: nowrap;
}

/* ── Progress bar ────────────────────────────────────────────────────────── */
.rq-progress-track {
  height: 3px; background: #0f1a28; border-radius: 2px;
  overflow: hidden; margin: 0 0 6px;
}
.rq-progress-fill {
  height: 100%; background: linear-gradient(90deg, #2a6090, #E0B341);
  border-radius: 2px; transition: width .4s ease;
}
.rq-job-running .rq-progress-fill {
  background: linear-gradient(90deg,
    var(--rq-accent,#4a8ad4) 0%,
    rgba(255,210,140,0.75) 42%,
    var(--rq-accent,#4a8ad4) 80%
  );
  background-size: 220% 100%;
  animation: rq-shimmer 2s ease-in-out infinite;
  transition: width .4s ease;
}
.rq-job-cancelling .rq-progress-fill {
  background: linear-gradient(90deg, #604020, #c07030);
  animation: none;
}
@keyframes rq-shimmer {
  0%   { background-position: 110% 0; }
  100% { background-position: -10% 0; }
}
.rq-prog-cancelling { background: linear-gradient(90deg, #604020, #c07030); }
.rq-job-done .rq-progress-fill { background: #3a7a3a; }

/* ── Rich running stats ──────────────────────────────────────────────────── */
.rq-richstats {
  margin: 2px 0 6px;
  display: flex; flex-direction: column; gap: 5px;
}
.rq-stat-row {
  display: flex; align-items: center; gap: 6px; min-width: 0;
}
.rq-stat-label {
  font: 700 8px/1 ui-monospace,monospace;
  text-transform: uppercase; letter-spacing: .09em;
  color: rgba(255,255,255,.22); flex-shrink: 0; white-space: nowrap;
}
.rq-stat-sep   { color: rgba(255,255,255,.2); }
.rq-stat-unit  { font: 500 9px/1 ui-monospace,monospace; color: rgba(255,255,255,.3); }
.rq-stat-spacer { flex: 1; min-width: 4px; }

/* Primary row: phase lozenge + elapsed */
.rq-stat-row-primary { gap: 7px; }
.rq-elapsed {
  font: 500 10px/1 "SF Pro Text","Segoe UI",sans-serif;
  color: rgba(255,255,255,.38); white-space: nowrap;
  overflow: hidden; text-overflow: ellipsis;
}

/* Phase lozenge */
.rq-phase-lozenge {
  display: inline-flex; align-items: center; gap: 5px; flex-shrink: 0;
  font: 700 9px/1 ui-monospace,monospace;
  text-transform: uppercase; letter-spacing: .07em;
  padding: 3px 7px; border-radius: 4px; border: 1px solid;
}
.rq-phase-dot {
  width: 5px; height: 5px; border-radius: 50%;
  background: currentColor; flex-shrink: 0;
  animation: rq-dot-pulse 1.6s ease-in-out infinite;
}
@keyframes rq-dot-pulse { 0%,100% { opacity:1; transform:scale(1); } 50% { opacity:.45; transform:scale(.75); } }
.rq-phase-lozenge-seeking    { color:#a07ad4; border-color:rgba(160,122,212,.28); background:rgba(160,122,212,.08); }
.rq-phase-lozenge-extracting { color:#d4a47a; border-color:rgba(212,164,122,.28); background:rgba(212,164,122,.08); }
.rq-phase-lozenge-encoding   { color:#E0B341; border-color:rgba(224,179,65,.32);  background:rgba(224,179,65,.10); }
.rq-phase-lozenge-muxing     { color:#4ab4d4; border-color:rgba(74,180,212,.28);  background:rgba(74,180,212,.08); }
.rq-phase-lozenge-saving     { color:#5cc878; border-color:rgba(92,200,120,.28);  background:rgba(92,200,120,.08); }
.rq-phase-lozenge-working    { color:#91baff; border-color:rgba(145,186,255,.28); background:rgba(145,186,255,.08); }

/* Shots counter in primary row */
.rq-richstat-shots {
  font: 500 10px/1 ui-monospace,monospace;
  color: rgba(255,255,255,.35); white-space: nowrap; flex-shrink: 0;
}

.rq-enc-chip {
  display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0;
  min-width: 28px; padding: 3px 7px; border-radius: 999px; border: 1px solid;
  font: 700 8px/1 ui-monospace,monospace; text-transform: uppercase; letter-spacing: .08em;
}
.rq-enc-chip-hw { color: #98def8; border-color: rgba(88, 186, 228, .34); background: rgba(62, 122, 162, .14); }
.rq-enc-chip-sw { color: #ffd28c; border-color: rgba(224,179,65, .30); background: rgba(224,179,65, .10); }

/* Frame counter row */
.rq-stat-row-frames { gap: 6px; }
.rq-stat-frame-num {
  font: 600 12px/1 ui-monospace,monospace;
  color: rgba(255,255,255,.82);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.rq-frame-cur { color: rgba(255,255,255,.92); }
.rq-fps-val {
  font: 700 10px/1 ui-monospace,monospace;
  color: #E0B341; font-variant-numeric: tabular-nums; white-space: nowrap;
}

/* Frame sub-progress bar */
.rq-frame-bar-track {
  height: 2px; background: rgba(255,255,255,.06);
  border-radius: 1px; overflow: hidden;
}
.rq-frame-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #2a5a90, #5a9ad4);
  border-radius: 1px; transition: width .25s ease;
}

/* Phase pipeline */
.rq-phase-pipe {
  display: flex; align-items: center; gap: 0; margin-top: 1px;
}
.rq-phase-step {
  font: 600 8.5px/1 ui-monospace,monospace;
  text-transform: uppercase; letter-spacing: .05em;
  color: rgba(255,255,255,.18); white-space: nowrap; flex-shrink: 0;
}
.rq-phase-step.is-done   { color: rgba(255,255,255,.38); }
.rq-phase-step.is-active { color: #e8c07a; font-weight: 700; }
.rq-phase-line {
  flex: 1; height: 1px; min-width: 6px; margin: 0 5px;
  background: rgba(255,255,255,.08);
}
.rq-phase-line.is-done { background: rgba(255,255,255,.22); }

/* Slim foot for running/cancelling (no status row needed) */
.rq-transfer-foot-slim { margin-top: 4px; }
.rq-transfer-foot-slim .rq-transfer-status { min-height: 0; }

/* ── System stats row (CPU / RAM / GPU) ──────────────────────────────────── */
.rq-sys-stats {
  display: flex; align-items: center; gap: 10px;
  margin-top: 6px; padding: 5px 8px;
  background: rgba(0,0,0,.18);
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 6px;
}
.rq-sys-block {
  display: flex; align-items: center; gap: 5px; min-width: 0; flex: 1;
}
.rq-sys-block-gpu { flex: 1.5; min-width: 0; }
.rq-sys-label {
  font: 700 8px/1 ui-monospace,monospace;
  text-transform: uppercase; letter-spacing: .1em;
  color: rgba(255,255,255,.28); flex-shrink: 0;
}
.rq-sys-mini-track {
  flex: 1; height: 3px; min-width: 28px; max-width: 60px;
  background: rgba(255,255,255,.07); border-radius: 2px; overflow: hidden;
}
.rq-sys-mini-fill {
  height: 100%; border-radius: 2px; transition: width .6s ease;
}
.rq-sys-val {
  font: 600 9px/1 ui-monospace,monospace;
  white-space: nowrap; font-variant-numeric: tabular-nums; flex-shrink: 0;
}
.rq-sys-gpu-name {
  font: 500 9px/1 ui-monospace,monospace;
  color: rgba(255,255,255,.38);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
/* Level colors */
.rq-sys-ok   { color: #5cc878; }
.rq-sys-warn { color: #e8c04a; }
.rq-sys-hot  { color: #e85a5a; }
.rq-sys-mini-fill.rq-sys-ok   { background: #3a7a50; }
.rq-sys-mini-fill.rq-sys-warn { background: #7a6020; }
.rq-sys-mini-fill.rq-sys-hot  { background: #7a2020; }

/* ── Footer row ──────────────────────────────────────────────────────────── */
.rq-job-foot {
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
}
.rq-time    { font: 10px/1 ui-monospace,monospace; color: #2a4060; white-space: nowrap; }
.rq-steps       { font: 10px/1 ui-monospace,monospace; color: #4a6a90; white-space: nowrap; }
.rq-frame-count { font: 500 10px/1 ui-monospace,monospace; color: #5b9bd5; white-space: nowrap; letter-spacing: 0.02em; }
.rq-elapsed {
  font: 10px/1 ui-monospace,monospace; color: #7090a8; white-space: nowrap;
  flex: 1; overflow: hidden; text-overflow: ellipsis;
}
.rq-status-line {
  font: 9px/1.5 ui-monospace,monospace; color: #5a8ab0;
  padding: 2px 8px 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  min-height: 14px;
}
.rq-dir     { margin-left: auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 200px; }
.rq-dir-none  { }
.rq-dir-btn {
  font: 10px/1 ui-monospace,monospace; color: #5a8a5a;
  background: none; border: none; padding: 2px 4px; border-radius: 4px;
  cursor: pointer; transition: background .15s, color .15s; display: block; width: 100%;
  text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.rq-dir-none.rq-dir-btn { color: #7898b8; }
.rq-dir-btn:hover         { background: rgba(255,255,255,.06); color: #88ccaa; }
.rq-dir-none.rq-dir-btn:hover { color: #6090bb; }
.rq-dir-picked   { color: #5a9e6a !important; }
.rq-dir-picked:hover { color: #88ccaa !important; background: rgba(255,255,255,.06) !important; }
.rq-dir-repick   { color: #c09030 !important; }
.rq-dir-repick:hover { color: #e0b840 !important; background: rgba(255,255,255,.06) !important; }
.rq-dir-pick-btn { color: #4a7a9a !important; font-style: italic; }
.rq-dir-pick-btn:hover { color: #6aaccc !important; background: rgba(255,255,255,.06) !important; }

/* ── Blocked strip ───────────────────────────────────────────────────────── */
.rq-blocked-strip {
  margin-top: 6px; padding: 5px 8px;
  background: #100e06; border: 1px solid #503a10; border-radius: 4px;
  font: 10px/1.4 ui-monospace,monospace; display: flex; flex-direction: column; gap: 3px;
}
.rq-blocked-msg    { color: #a08040; }
.rq-blocked-action { color: #6090b0; font-style: italic; }

/* ── Pre-flight badge ────────────────────────────────────────────────────── */
.rq-preflight-ok   { color: #5c9e5c; font-size: 10px; flex-shrink: 0; }
.rq-preflight-warn { color: #c09030; font-size: 10px; flex-shrink: 0; cursor: help; }

/* ── Error message ───────────────────────────────────────────────────────── */
.rq-job-err {
  margin-top: 6px; padding: 5px 8px;
  background: #120808; border: 1px solid #3a1818; border-radius: 4px;
  font: 10px/1.4 ui-monospace,monospace; color: #a06060; word-break: break-all;
}
.rq-recovery {
  margin-top: 4px; color: #6090b0; font: 10px/1.4 ui-monospace,monospace;
  font-style: italic; word-break: break-word;
}

/* ── Priority ────────────────────────────────────────────────────────────── */
.rq-job-high-pri { border-left: 2px solid #d0a030 !important; }
.rq-pri-indicator {
  font: 700 9px/1 ui-monospace,monospace; color: #c09030;
  flex-shrink: 0; padding: 0 1px;
}
.rq-act-pri-high {
  background: #1a1408; border-color: #60401880; color: #c09030;
  font: 700 10px/1 ui-monospace,monospace; padding: 3px 7px;
  border-radius: 4px; cursor: pointer; border: 1px solid;
}
.rq-act-pri-high:hover { background: #201a08; color: #e0b840; }
.rq-act-pri-norm {
  background: #0d1220; border-color: #1a3050; color: #3a5a80;
  font: 10px/1 ui-monospace,monospace; padding: 3px 7px;
  border-radius: 4px; cursor: pointer; border: 1px solid;
}
.rq-act-pri-norm:hover { background: #0a1830; color: #c09030; }

/* ── Drag-and-drop ───────────────────────────────────────────────────────── */
.rq-job-pending[draggable] { cursor: grab; }
.rq-job-pending[draggable]:active { cursor: grabbing; }
.rq-job-dragging { opacity: .45; border-style: dashed !important; }
.rq-drop-above   { border-top: 2px solid #E0B341 !important; }

/* ── Stop button ─────────────────────────────────────────────────────────── */
.rq-act-stop {
  font: 10px/1 ui-monospace,monospace; padding: 3px 7px;
  border-radius: 4px; cursor: pointer; border: 1px solid;
  background: #1a0c08; border-color: #503020; color: #c07050;
  transition: background .12s, color .12s;
}
.rq-act-stop:hover:not(:disabled) { background: #200e08; border-color: #703820; color: #e08060; }
.rq-act-stop:disabled { opacity: .45; cursor: default; }
.rq-act-log {
  font: 10px/1 ui-monospace,monospace; padding: 3px 7px;
  border-radius: 4px; cursor: pointer;
  background: #0d1220; border: 1px solid #1e3050; color: #5070a0;
  transition: background .12s;
}
.rq-act-log:hover { background: #0a1830; color: #7a90c0; }

/* ── Log panel ───────────────────────────────────────────────────────────── */
.rq-log-panel {
  margin-top: 6px; padding: 5px 8px;
  background: #050b15; border: 1px solid #1a2a40; border-radius: 4px;
  font: 10px/1.5 ui-monospace,monospace; color: #5a7a9a;
  max-height: 120px; overflow-y: auto;
}
.rq-log-line   { display: flex; gap: 8px; align-items: baseline; }
.rq-log-ts     { color: #2a4060; flex-shrink: 0; }

/* ── Output files count ──────────────────────────────────────────────────── */
.rq-files-count {
  font: 10px/1 ui-monospace,monospace; color: #4a7a4a; white-space: nowrap;
}

/* ── History section ─────────────────────────────────────────────────────── */
.rq-history-section {
  flex-shrink: 0; border-top: 1px solid #0f1a28; margin-top: 6px;
}
.rq-hist-toggle {
  width: 100%; background: none; border: none; cursor: pointer;
  font: 11px/1 ui-monospace,monospace; color: #2a4060;
  padding: 8px 2px; text-align: left;
  transition: color .15s;
}
.rq-hist-toggle:hover { color: #4a6090; }
.rq-hist-count {
  background: #0d1a30; color: #3a5a80; border: 1px solid #1a3050;
  border-radius: 8px; padding: 1px 5px;
  font: 700 8px/1 ui-monospace,monospace;
}
.rq-hist-list {
  max-height: 180px; overflow-y: auto;
  display: flex; flex-direction: column; gap: 3px; padding-bottom: 4px;
}
.rq-hist-list::-webkit-scrollbar       { width: 3px; }
.rq-hist-list::-webkit-scrollbar-track { background: transparent; }
.rq-hist-list::-webkit-scrollbar-thumb { background: #1e2e4a; border-radius: 2px; }
.rq-hist-card {
  display: flex; align-items: center; gap: 5px;
  padding: 4px 6px; border-radius: 5px;
  background: #050b15; border: 1px solid #0f1820;
}
.rq-hist-card:hover { border-color: #1a2840; }
.rq-hist-label {
  flex: 1; font: 10px/1 ui-monospace,monospace; color: #4a6080;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0;
}
.rq-hist-meta  { font: 9px/1 ui-monospace,monospace; color: #2a3a50; flex-shrink: 0; }
.rq-hist-done  { }
.rq-hist-error .rq-hist-label { color: #604040; }
.rq-hist-cancelled .rq-hist-label { color: #3a3028; }

/* ── Render Queue Refresh ────────────────────────────────────────────────── */
#main-renderq.rq-pane {
  box-sizing: border-box;
  padding: 10px 12px 14px;
  background:
    radial-gradient(circle at 85% 92%, rgba(196, 58, 58, 0.22), transparent 28%),
    radial-gradient(circle at 100% 0%, rgba(109, 42, 128, 0.18), transparent 24%),
    linear-gradient(180deg, #050506 0%, #09050a 100%);
}

#main-renderq .rq-stage {
  height: calc(100vh - 104px);
  display: flex;
}

#main-renderq .rq-shell {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 0;
  padding: 12px 18px 12px;
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,.12);
  background:
    linear-gradient(180deg, rgba(7, 3, 8, .97), rgba(20, 7, 20, .96)),
    linear-gradient(135deg, rgba(128, 34, 68, .08), rgba(36, 19, 56, .08));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.06),
    0 18px 52px rgba(0,0,0,.36);
  overflow: hidden;
}

#main-renderq .rq-shell::before {
  content: "";
  position: absolute;
  inset: auto -8% -20% auto;
  width: 52%;
  height: 48%;
  background: radial-gradient(circle, rgba(212, 56, 56, .28), transparent 64%);
  pointer-events: none;
  filter: blur(10px);
}

#main-renderq .rq-shell::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255,255,255,.015), transparent 14%);
  pointer-events: none;
}

#main-renderq .rq-window-chrome,
#main-renderq .rq-header,
#main-renderq .rq-segment-wrap,
#main-renderq .rq-status-bar,
#main-renderq .rq-hint-row,
#main-renderq .rq-history-section,
#main-renderq .rq-job-list {
  position: relative;
  z-index: 1;
}

#main-renderq .rq-window-chrome {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

#main-renderq .rq-window-dot {
  width: 12px;
  height: 12px;
  border-radius: 999px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.28);
}

#main-renderq .rq-window-dot-red { background: #ff6b57; }
#main-renderq .rq-window-dot-amber { background: #f6bf4f; }
#main-renderq .rq-window-dot-green { background: #28c840; }

#main-renderq .rq-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0;
  border: 0;
}

#main-renderq .rq-header-left {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  color: #f5efe9;
}

#main-renderq .rq-title-eyebrow {
  font: 600 10px/1 "SF Pro Text","Segoe UI",sans-serif;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: rgba(255,255,255,.32);
}

#main-renderq .rq-header-title {
  font: 700 clamp(15px, 1.3vw, 18px)/1.05 "SF Pro Display","Segoe UI",sans-serif;
  letter-spacing: -.02em;
  text-transform: none;
  color: #f8f1ec;
}

#main-renderq .rq-header-controls {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

#main-renderq .rq-connection-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(121, 202, 132, .55);
  font: 600 10px/1 "SF Pro Text","Segoe UI",sans-serif;
  letter-spacing: .01em;
  color: #d6e6d3;
  background: rgba(12, 26, 15, .45);
}

#main-renderq .rq-connection-pill::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(255,255,255,.06);
}

#main-renderq .rq-connection-pill.is-good {
  color: #7fd28b;
  border-color: rgba(121, 202, 132, .55);
  background: rgba(12, 26, 15, .45);
}
#main-renderq .rq-connection-pill.is-live {
  color: #7fd28b;
  border-color: rgba(121, 202, 132, .55);
  background: rgba(12, 26, 15, .45);
}
#main-renderq .rq-connection-pill.is-paused {
  color: #f2c46a;
  border-color: rgba(242, 196, 106, .4);
  background: rgba(53, 36, 9, .34);
}
#main-renderq .rq-connection-pill.is-warn {
  color: #ff8d79;
  border-color: rgba(255, 141, 121, .42);
  background: rgba(54, 22, 20, .34);
}
#main-renderq .rq-connection-pill.is-idle {
  color: #b5bccb;
  border-color: rgba(255,255,255,.15);
  background: rgba(255,255,255,.03);
}

#main-renderq .rq-ctrl-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  justify-content: center;
  height: 26px;
  padding: 0 10px;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,.14);
  background: rgba(255,255,255,.05);
  color: rgba(255,255,255,.75);
  cursor: pointer;
  font: 600 11px/1 "SF Pro Text","Segoe UI",sans-serif;
  letter-spacing: .01em;
  transition: border-color .14s ease, background .14s ease, color .14s ease;
  white-space: nowrap;
}

#main-renderq .rq-ctrl-btn:hover:not(:disabled) {
  background: rgba(255,255,255,.1);
  border-color: rgba(255,255,255,.25);
  color: #fff;
}

#main-renderq .rq-ctrl-btn:disabled {
  opacity: .35;
  cursor: default;
}

#main-renderq .rq-ctrl-btn svg {
  width: 11px;
  height: 11px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}

#main-renderq .rq-btn-pause {
  color: #f2c46a;
  border-color: rgba(242, 196, 106, .4);
  background: rgba(60, 44, 8, .35);
}
#main-renderq .rq-btn-pause:hover:not(:disabled) {
  background: rgba(242, 196, 106, .14);
  border-color: rgba(242, 196, 106, .65);
  color: #f7d580;
}
#main-renderq .rq-btn-resume {
  color: #8ad79a;
  border-color: rgba(138, 215, 154, .45);
  background: rgba(14, 40, 20, .35);
}
#main-renderq .rq-btn-resume:hover:not(:disabled) {
  background: rgba(138, 215, 154, .12);
  border-color: rgba(138, 215, 154, .7);
  color: #a0e8b0;
}
#main-renderq .rq-btn-clear {
  color: #f08080;
  border-color: rgba(240,100,80,.38);
  background: rgba(200,60,40,.12);
}
#main-renderq .rq-btn-clear:hover:not(:disabled) {
  background: rgba(200,60,40,.22);
  border-color: rgba(240,100,80,.65);
  color: #f4a0a0;
}
#main-renderq .rq-btn-stop {
  color: #f08c7c;
  border-color: rgba(240,100,80,.45);
  background: rgba(160,40,30,.28);
}
#main-renderq .rq-btn-stop:hover:not(:disabled) {
  background: rgba(200,60,40,.38);
  border-color: rgba(240,100,80,.75);
  color: #f4a090;
}
#main-renderq .rq-btn-stop:disabled {
  opacity: .45;
  cursor: default;
}

#main-renderq .rq-ctrl-label {
  display: inline;
}

#main-renderq .rq-identity {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-left: 2px;
}

#main-renderq .rq-user-avatar {
  width: 26px;
  height: 26px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(74, 138, 212, .22);
  border: 1px solid rgba(74, 138, 212, .35);
  color: #7ab4f0;
  font: 700 9px/1 "SF Pro Text","Segoe UI",sans-serif;
  letter-spacing: .02em;
}

#main-renderq .rq-identity-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

#main-renderq .rq-user-name {
  max-width: 180px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font: 600 12px/1.1 "SF Pro Display","Segoe UI",sans-serif;
  color: #f8f1ec;
}

#main-renderq .rq-user-team {
  font: 500 10px/1 "SF Pro Text","Segoe UI",sans-serif;
  color: rgba(255,255,255,.38);
}

#main-renderq .rq-identity-caret {
  width: 0;
  height: 0;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-top: 4px solid rgba(255,255,255,.7);
  margin-left: 2px;
}

#main-renderq .rq-segment-wrap {
  display: flex;
  justify-content: center;
  margin: 10px 0 12px;
}

#main-renderq .rq-segmented {
  display: inline-flex;
  padding: 3px;
  border-radius: 9px;
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.03);
}

#main-renderq .rq-segment-btn {
  display: inline-flex;
  align-items: center;
  gap: 0;
  min-width: 98px;
  justify-content: center;
  height: 34px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: rgba(255,255,255,.74);
  font: 600 11px/1 "SF Pro Text","Segoe UI",sans-serif;
  cursor: pointer;
  transition: background .16s ease, color .16s ease, box-shadow .16s ease;
}

#main-renderq .rq-segment-btn.is-active {
  background: linear-gradient(180deg, rgba(73, 87, 184, .76), rgba(58, 70, 150, .76));
  color: #eef1ff;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.14);
}

#main-renderq .rq-segment-count {
  display: none;
}

#main-renderq .rq-status-bar {
  margin: 0 0 4px;
  padding: 0;
  border: 0;
  background: transparent;
  font: 500 11px/1.45 "SF Pro Text","Segoe UI",sans-serif;
  color: rgba(255,255,255,.58);
}

#main-renderq .rq-sb-running { color: #ffd3a0; animation: none; }
#main-renderq .rq-sb-paused { color: #f0c978; }
#main-renderq .rq-sb-blocked { color: #f49b90; animation: none; }
#main-renderq .rq-sb-ready { color: #c9d4ff; }
#main-renderq .rq-sb-idle { color: rgba(255,255,255,.42); }

#main-renderq .rq-hint-row {
  margin: 0 0 10px;
  font: 500 10px/1.45 "SF Pro Text","Segoe UI",sans-serif;
  color: rgba(255,255,255,.34);
}

#main-renderq .rq-hint-row strong { color: rgba(255,255,255,.68); }

#main-renderq .rq-job-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-right: 2px;
}

#main-renderq .rq-job-list::-webkit-scrollbar { width: 6px; }
#main-renderq .rq-job-list::-webkit-scrollbar-track { background: transparent; }
#main-renderq .rq-job-list::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,.12);
  border-radius: 999px;
}

#main-renderq .rq-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: rgba(255,255,255,.42);
  text-align: center;
  font: 500 12px/1.5 "SF Pro Text","Segoe UI",sans-serif;
  padding: 32px 0 40px;
}

#main-renderq .rq-empty svg { opacity: .7; }
#main-renderq .rq-empty-hint {
  max-width: 360px;
  color: rgba(255,255,255,.3);
}

#main-renderq .rq-empty-hint strong { color: rgba(255,255,255,.65); }

#main-renderq .rq-job {
  position: relative;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.08);
  background:
    linear-gradient(90deg, rgba(34, 28, 36, .94) 0%, rgba(44, 28, 43, .94) 56%, rgba(84, 32, 43, .9) 100%);
  padding: 12px 14px 10px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.03),
    0 10px 24px rgba(0,0,0,.16);
  transition: border-color .14s ease, box-shadow .14s ease;
}

#main-renderq .rq-job::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(255,255,255,.015), transparent 24%, rgba(255,255,255,.03) 100%);
  pointer-events: none;
}

#main-renderq .rq-job:hover {
  border-color: rgba(255,255,255,.16);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.045),
    0 12px 28px rgba(0,0,0,.2);
}

#main-renderq .rq-job-running {
  border-color: rgba(106, 140, 255, .24);
  background: linear-gradient(90deg, rgba(28, 33, 46, .95) 0%, rgba(38, 31, 54, .95) 60%, rgba(75, 35, 62, .9) 100%);
}

#main-renderq .rq-job-pending {
  border-color: rgba(148, 129, 209, .16);
  background: linear-gradient(90deg, rgba(30, 24, 38, .95) 0%, rgba(39, 29, 49, .95) 60%, rgba(65, 32, 49, .9) 100%);
}

#main-renderq .rq-job-blocked {
  border-color: rgba(255, 174, 98, .22) !important;
  background: linear-gradient(90deg, rgba(42, 31, 26, .95) 0%, rgba(55, 34, 31, .95) 60%, rgba(88, 45, 33, .9) 100%);
}

#main-renderq .rq-job-error {
  border-color: rgba(255, 112, 112, .26);
  background: linear-gradient(90deg, rgba(43, 30, 34, .95) 0%, rgba(58, 31, 39, .94) 58%, rgba(132, 47, 50, .9) 100%);
}

#main-renderq .rq-job-done {
  border-color: rgba(117, 196, 140, .22);
  background: linear-gradient(90deg, rgba(25, 35, 31, .95) 0%, rgba(28, 39, 35, .95) 58%, rgba(40, 74, 49, .88) 100%);
}

#main-renderq .rq-job-cancelled {
  border-color: rgba(255,255,255,.08);
  opacity: .8;
}

#main-renderq .rq-transfer-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
}

#main-renderq .rq-transfer-copy {
  min-width: 0;
}

#main-renderq .rq-transfer-eyebrow {
  margin-bottom: 5px;
  font: 500 10px/1.2 "SF Pro Text","Segoe UI",sans-serif;
  color: rgba(255,255,255,.48);
}

#main-renderq .rq-transfer-name {
  margin-bottom: 8px;
  font: 700 clamp(12px, 1vw, 14px)/1.3 "SF Pro Display","Segoe UI",sans-serif;
  letter-spacing: -.015em;
  color: #f7efe9;
  word-break: break-word;
}

#main-renderq .rq-progress-track {
  height: 3px;
  margin: 0 0 10px;
  border-radius: 999px;
  background: rgba(255,255,255,.26);
  overflow: hidden;
}

#main-renderq .rq-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(244,244,247,.72), rgba(255,255,255,.95));
  transition: width .35s ease;
}

#main-renderq .rq-job-running .rq-progress-fill {
  background: linear-gradient(90deg, #8eb5ff, #d7e0ff);
}

#main-renderq .rq-job-done .rq-progress-fill {
  background: linear-gradient(90deg, #8be1a0, #e0ffe7);
}

#main-renderq .rq-job-blocked .rq-progress-fill {
  background: linear-gradient(90deg, #f0c178, #ffe0b3);
}

#main-renderq .rq-job-error .rq-progress-fill,
#main-renderq .rq-job-cancelled .rq-progress-fill {
  background: linear-gradient(90deg, rgba(255,255,255,.45), rgba(255,255,255,.72));
}

#main-renderq .rq-transfer-foot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

#main-renderq .rq-transfer-status {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex-wrap: wrap;
  color: rgba(255,255,255,.52);
}

#main-renderq .rq-job-icon {
  width: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

#main-renderq .rq-icon-pending { color: #9ba2bf; }
#main-renderq .rq-icon-running { color: #91baff; }
#main-renderq .rq-icon-cancelling { color: #f0c178; }
#main-renderq .rq-icon-blocked { color: #f4b061; }
#main-renderq .rq-icon-error { color: #ff8b8b; }
#main-renderq .rq-icon-done { color: #7fd79a; }
#main-renderq .rq-icon-cancelled { color: rgba(255,255,255,.52); }

#main-renderq .rq-transfer-status-copy,
#main-renderq .rq-elapsed {
  font: 500 10px/1.35 "SF Pro Text","Segoe UI",sans-serif;
}
#main-renderq .rq-elapsed { color: rgba(255,255,255,.38); }

#main-renderq .rq-transfer-meta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  flex-wrap: wrap;
}

#main-renderq .rq-transfer-chip,
#main-renderq .rq-transfer-tag {
  display: inline-flex;
  align-items: center;
  height: 20px;
