/* ========================================================================
   Auth Overlay (login / denied / expired)
   ======================================================================== */

#pfx-auth-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(6, 8, 16, 0.92);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
}
#pfx-auth-overlay[hidden] { display: none; }

.pfx-auth-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  background: rgba(23, 24, 28, 0.98);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 18px;
  padding: 44px 44px 32px;
  min-width: 340px;
  max-width: 400px;
  box-shadow: 0 28px 70px rgba(0,0,0,.55);
}

.pfx-auth-logo {
  width: 52px;
  height: 52px;
  object-fit: contain;
  border-radius: 12px;
  margin-bottom: 2px;
}

.pfx-auth-spinner {
  width: 24px;
  height: 24px;
  border: 2px solid rgba(255,255,255,.14);
  border-top-color: #e50914;
  border-radius: 50%;
  animation: pfx-auth-spin .8s linear infinite;
}

@keyframes pfx-auth-spin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .pfx-auth-spinner { animation: none; border-top-color: rgba(255,255,255,.55); }
}

.pfx-auth-title {
  font-size: 23px;
  font-weight: 700;
  color: #f2f3f6;
  margin: 0;
  letter-spacing: .01em;
}
.pfx-auth-title--deny { color: #f08080; }

.pfx-auth-sub {
  font-size: 13.5px;
  color: rgba(200,205,220,.6);
  margin: 0;
  text-align: center;
  line-height: 1.5;
}

.pfx-auth-note {
  font-size: 12px;
  border-radius: 6px;
  padding: 8px 12px;
  margin: 0;
  text-align: center;
}
.pfx-auth-note--warn  { background: rgba(240,180,50,.1);  color: #e8c060; border: 1px solid rgba(240,180,50,.22); }
.pfx-auth-note--info  { background: rgba(80,160,240,.1);  color: #80b8f0; border: 1px solid rgba(80,160,240,.22); }
.pfx-auth-note--error { background: rgba(229,72,77,.1);   color: #f09090; border: 1px solid rgba(229,72,77,.22); margin-top: 4px; }

.pfx-auth-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  padding: 11px 20px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background .15s, opacity .15s;
}
.pfx-auth-btn:disabled { opacity: .5; cursor: not-allowed; }

.pfx-auth-btn--google {
  background: #fff;
  color: #1f1f1f;
}
.pfx-auth-btn--google:hover:not(:disabled) { background: #f0f0f0; }

.pfx-auth-btn--primary {
  background: #5b5bd6;
  color: #fff;
}
