  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 6px;
  pointer-events: none;
  user-select: none;
}

/* In read-only mode, dim save/export/edit buttons site-wide */
.pfx-is-read-only [data-pfx-ro] {
  opacity: .4;
  cursor: not-allowed;
}

/* ========================================================================
   Guard Toast
   ======================================================================== */

.pfx-guard-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(16px);
  z-index: 99998;
  background: rgba(20, 22, 36, 0.96);
  border: 1px solid rgba(255,255,255,.12);
  color: #e0e4f0;
  font-size: 13px;
  padding: 10px 20px;
  border-radius: 8px;
  pointer-events: none;
  opacity: 0;
  transition: opacity .2s, transform .2s;
  /* Was `nowrap`, which was safe only while every refusal was three words.
     The wording now says what happened and what to do about it, on two lines
     separated by \n — with nowrap the newline collapsed and the toast grew
     wider than the window, clipped at both ends because it is centred with
     translateX(-50%). pre-line keeps the break; the max-width keeps the
     longer single sentences inside the frame. Same four departures the
     error-banner block below already documents. */
  white-space: pre-line;
  max-width: min(90vw, 460px);
  text-align: center;
  box-shadow: 0 8px 32px rgba(0,0,0,.4);
}
.pfx-guard-toast--on {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
.pfx-guard-toast[data-type="deny"] {
  border-color: rgba(240,100,80,.32);
  color: #f0a090;
}

/* ACES Look tab theme */
.tab.theme-aceslook { --tab-color: #b39ddb; }
.tab.theme-aceslook .bar { background: var(--tab-color); }
.tab.theme-aceslook:hover, .tab.theme-aceslook.active { color: var(--tab-color); }

@keyframes pfx-toast-in { from { opacity:0; transform:translateX(-50%) translateY(8px); } to { opacity:1; transform:translateX(-50%) translateY(0); } }

/* ── Error banner (scripts/core/errorBanner.js) ───────────────────────────── */
/* The same visual language as .pfx-guard-toast, with four deliberate
   departures: it wraps and preserves newlines, because a file-not-found
   message carries a filesystem path on a line of its own and `nowrap` would
   push it off-screen; it takes pointer events so it can be dismissed early;
   it is tinted with the app's error red so a failure is not mistaken for a
   confirmation; and it sits above the guard toast, since a failure outranks a
   permission notice. */
.pfx-error-banner {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(16px);
  z-index: 99999;
  max-width: min(560px, 90vw);
  background: rgba(34, 18, 20, .97);
  border: 1px solid rgba(240, 100, 80, .36);
  color: #f2c9c0;
  font-size: 13px;
  line-height: 1.45;
  padding: 10px 20px;
  border-radius: 8px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  box-shadow: 0 8px 32px rgba(0, 0, 0, .45);
  opacity: 0;
  /* Hidden it must not swallow clicks: with padding it still occupies a small
     box at the bottom of the screen even when empty. */
  pointer-events: none;
  transition: opacity .2s, transform .2s;
}
.pfx-error-banner--on {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
  pointer-events: auto;
  cursor: pointer;
}
@media (prefers-reduced-motion: reduce) {
  .pfx-error-banner { transition: none; }
}

