   ════════════════════════════════════════════════════════════════════════ */

/* Advanced mode toggle (floating button visible in pro mode only) */
/* Smart / Advanced toggle — two distinct visual states */
.pm-adv-toggle {
  display: none; /* JS sets to flex when visible */
  position: absolute; top: 8px; right: 10px;
  align-items: center; gap: 5px;
  padding: 4px 11px 4px 8px; border-radius: 5px;
  font-size: 10px; font-weight: 800; letter-spacing: 0.3px;
  cursor: pointer; z-index: 10; transition: background 0.14s, border-color 0.14s;
  /* Default = Advanced mode button: muted purple */
  background: #181828; border: 1px solid #2e2e55; color: #7880c0;
}
.pm-adv-toggle:hover { background: #20203c; border-color: #4848a0; color: #a8b0e0; }

/* Icons — show one at a time based on mode */
.pm-adv-tog-icon { flex-shrink: 0; transition: opacity 0.1s; }
.pm-adv-tog-adv   { display: block; }     /* gear/crosshair icon for "go to Advanced" */
.pm-adv-tog-smart { display: none;  }     /* hexagon icon for "go to Smart" */
.pm-adv-toggle.is-simple .pm-adv-tog-adv   { display: none; }
.pm-adv-toggle.is-simple .pm-adv-tog-smart { display: block; }

.pm-adv-tog-lbl { line-height: 1; }

/* Layout wrapper */
.pm-sly {
  display: flex; flex-direction: column;
  height: calc(100vh - 86px); /* same as .main-pane height */
  overflow: hidden;
  background: #0b0c17;
}

/* ── TOP BAR ── */
.pm-sly-topbar {
  display: flex; align-items: center; gap: 12px;
  padding: 0 14px; height: 36px; flex-shrink: 0;
  background: #0b0c18; border-bottom: 1px solid #181928;
}
.pm-sly-title {
  font-size: 12px; font-weight: 800; color: #c0c4e8; letter-spacing: 0.3px; white-space: nowrap;
}
.pm-sly-ver { font-size: 9px; color: #2172E3; font-weight: 700; margin-left: 2px; opacity: 0.8; }
.pm-sly-steps { display: flex; align-items: center; gap: 5px; flex: 1; min-width: 0; }
.pm-sly-step {
  font-size: 10px; font-weight: 600; color: #6870a0; white-space: nowrap;
  padding: 2px 7px; border-radius: 3px; cursor: default; user-select: none;
}
