.pm-sly-tb-adv {
  display: inline-flex; align-items: center; gap: 5px;
  background: rgba(214,163,58,0.12); border: 1px solid rgba(214,163,58,0.50);
  color: #2172E3;
  font-size: 10px; font-weight: 800; padding: 4px 11px 4px 8px; border-radius: 5px;
  cursor: pointer; letter-spacing: 0.3px; white-space: nowrap;
  transition: background 0.12s, border-color 0.12s;
  box-shadow: 0 0 8px rgba(214,163,58,0.10);
}
.pm-sly-tb-adv:hover {
  background: rgba(214,163,58,0.22); border-color: #2172E3; color: #e0bd62;
  box-shadow: 0 0 12px rgba(214,163,58,0.22);
}

/* ── 3-COLUMN BODY ── */
.pm-sly-body {
  display: flex; flex: 1; min-height: 0; overflow: hidden;
}

/* ── LEFT SIDEBAR ── */
.pm-sly-left {
  width: 215px; flex-shrink: 0;
  background: #0b0c17; border-right: 1px solid #181928;
  overflow-y: auto; padding: 8px 8px 16px;
  display: flex; flex-direction: column; gap: 6px;
}
.pm-sly-left::-webkit-scrollbar { width: 4px; }
.pm-sly-left::-webkit-scrollbar-track { background: transparent; }
.pm-sly-left::-webkit-scrollbar-thumb { background: #2a2c48; border-radius: 4px; }

/* ── CENTER ── */
.pm-sly-center {
  flex: 1; min-width: 0;
  display: flex; flex-direction: column;
  background: #0a0b16; border-right: 1px solid #181928;
  overflow: hidden;
}

/* ── RIGHT PANEL ── */
.pm-sly-right {
  width: 215px; flex-shrink: 0;
  background: #0b0c17;
  overflow-y: auto; padding: 8px 8px 16px;
  display: flex; flex-direction: column; gap: 6px;
}
.pm-sly-right::-webkit-scrollbar { width: 4px; }
.pm-sly-right::-webkit-scrollbar-track { background: transparent; }
.pm-sly-right::-webkit-scrollbar-thumb { background: #2a2c48; border-radius: 4px; }

/* ── SHARED CARD ── */
.pm-sly-card {
  background: #0d0e1c; border: 1px solid #171828; border-radius: 6px;
  padding: 8px 10px; flex-shrink: 0;
}
.pm-sly-clabel {
  font-size: 8.5px; font-weight: 800; color: #6878a8; letter-spacing: 0.6px;
  text-transform: uppercase; margin-bottom: 6px; display: flex; align-items: center; gap: 6px;
}
.pm-sly-empty-hint { font-size: 11px; color: #8898c8; text-align: center; padding: 8px 0; }

/* ── PROJECT CARD ── */
.pm-sly-card--proj { padding: 6px 8px; }
.pm-sly-proj-row { display: flex; align-items: center; gap: 5px; }
.pm-sly-proj-name { font-size: 12px; font-weight: 700; color: #c8ccf0; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-sly-proj-shot { font-size: 9px; color: #7880a0; min-height: 0; }
.pm-sly-proj-shot:empty { display: none; }
.pm-sly-save-line { font-size: 9px; color: #a0784a; min-height: 0; line-height: 1.4; }
.pm-sly-save-line:empty { display: none; }
.pm-sly-save-line.is-unsaved::before { content: '● '; }
.pm-sly-proj-btns { display: flex; gap: 5px; }

/* ── BUTTONS ── */
.pm-sly-btn-sm {
  background: #141528; border: 1px solid #1e2040; color: #8890c0;
  font-size: 10px; font-weight: 600; padding: 3px 8px; border-radius: 3px; cursor: pointer;
}
.pm-sly-btn-sm:hover { background: #1a1c38; color: #c0c8f0; }
.pm-sly-btn-sm.pm-sly-btn-accent {
  background: #1c1808; border-color: #5a4a10; color: #2172E3;
}
.pm-sly-btn-sm.pm-sly-btn-accent:hover { background: #251e08; color: #e0bd62; }
.pm-sly-btn-sm.pm-sly-btn-danger {
  background: #1e0a0a; border-color: #5a1010; color: #e07070;
}
.pm-sly-btn-sm.pm-sly-btn-danger:hover { background: #2a0e0e; color: #ff9090; }
/* Smart Import card */
#pmSlySmartImportCard {
  transition: border-color 0.12s, background 0.12s;
}
#pmSlySmartImportCard.pm-sly-import-drag {
  border-color: rgba(84,213,255,0.50) !important;
  background: rgba(84,213,255,0.04) !important;
}
/* Drop hint — shown as a small bar below inputs, not covering them */
.pm-sly-import-drop-hint {
  text-align: center; font-size: 9px; color: #384058; padding: 3px 0;
  transition: color 0.12s;
  border: 1px dashed rgba(255,255,255,0.06); border-radius: 3px;
  margin-top: 4px;
}
#pmSlySmartImportCard.pm-sly-import-drag .pm-sly-import-drop-hint {
  color: rgba(84,213,255,0.65);
  border-color: rgba(84,213,255,0.30);
}

/* Combined Sources + Smart Import card */
.pm-src-combined { }
.pm-src-row {
  display: flex; align-items: center; gap: 5px;
  padding: 2px 0; min-height: 20px;
}
.pm-src-row--sm {
  padding: 1px 0; min-height: 17px;
}
.pm-src-lbl {
  font-size: 7.5px; font-weight: 700; color: #8898c8; letter-spacing: 0.4px;
  text-transform: uppercase; width: 28px; flex-shrink: 0;
}
.pm-src-inp {
  flex: 1; min-width: 0; font-size: 9px; padding: 3px 6px;
  background: rgba(0,0,0,0.30); border: 1px solid rgba(255,255,255,0.08);
  color: #c0c8f0; border-radius: 3px;
  font-family: 'SF Mono','Fira Mono','Consolas',monospace;
}
.pm-src-inp::placeholder { color: #2e3450; font-size: 8.5px; }
.pm-src-inp:focus { outline: none; border-color: rgba(84,213,255,0.35); }
.pm-src-inp.pm-sly-import-inp-drag { border-color: rgba(84,213,255,0.50); background: rgba(84,213,255,0.06); }
.pm-src-status {
  font-size: 9px; color: #4a5870; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* Smart Import path inputs */
.pm-sly-import-inp {
  flex: 1; min-width: 0; font-size: 9.5px; padding: 4px 7px;
  background: rgba(0,0,0,0.35); border: 1px solid rgba(255,255,255,0.10);
  color: #c0c8f0; border-radius: 4px; font-family: 'SF Mono','Fira Mono','Consolas',monospace;
}
.pm-sly-import-inp::placeholder { color: #3a4060; }
.pm-sly-import-inp:focus { outline: none; border-color: rgba(84,213,255,0.40); }
.pm-sly-import-footer {
  display: flex; align-items: center; gap: 5px; margin-top: 5px;
}
.pm-sly-import-status {
  font-size: 9px; color: #5a6880; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pm-sly-qa-row {
  display: flex; gap: 5px; margin-top: 5px; padding-top: 5px;
  border-top: 1px solid #181928;
}
.pm-sly-qa-chip {
  flex: 1; font-size: 9px; font-weight: 700; padding: 3px 5px;
  background: none; border: 1px solid #1e2040; border-radius: 3px;
  cursor: pointer; text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.pm-sly-qa-danger { color: #c86060; border-color: #3a1818; }
.pm-sly-qa-danger:hover { color: #e08080; background: rgba(200,60,60,0.08); border-color: #5a2020; }
.pm-sly-qa-export { color: #0AA356; border-color: #183828; }
.pm-sly-qa-export:hover { color: #7de0a8; background: rgba(10,163,86,0.08); border-color: #205840; }
.pm-sly-import-go {
  background: rgba(84,213,255,0.12) !important; border-color: rgba(84,213,255,0.35) !important;
  color: #84d4ff !important; font-weight: 800 !important; white-space: nowrap;
}
.pm-sly-import-go:hover { background: rgba(84,213,255,0.22) !important; }

.pm-sly-btn-xs {
  flex-shrink: 0; background: #141528; border: 1px solid #1e2040; color: #7880a0;
  font-size: 9px; font-weight: 600; padding: 2px 6px; border-radius: 3px; cursor: pointer;
  white-space: nowrap;
}
.pm-sly-btn-xs:hover { background: #1a1c38; color: #c0c8f0; }

/* ── WORKFLOW STATUS ── */
.pm-sly-wf-pct { color: #2172E3; font-size: 9px; font-weight: 700; }

/* Compact 3×2 grid layout */
.pm-sly-wf-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px 3px;
}
.pm-sly-wf-row {
  display: flex; align-items: center; gap: 3px;
  padding: 2px 3px; border-bottom: none;
  background: rgba(255,255,255,0.02); border-radius: 3px;
  min-width: 0;
}
.pm-sly-wf-dot { width: 11px; font-size: 9px; text-align: center; flex-shrink: 0; color: #8898c8; }
.pm-sly-wf-row.is-done .pm-sly-wf-dot { color: #0AA356; }
.pm-sly-wf-row.is-warn .pm-sly-wf-dot { color: #e5a040; }
.pm-sly-wf-name { flex: 1; color: #a0a8d0; font-size: 9px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-sly-wf-row.is-done .pm-sly-wf-name { color: #7880a8; }
.pm-sly-wf-cta {
  display: none !important;
}

/* ── SOURCES ── */
.pm-sly-src-row {
  display: flex; align-items: center; gap: 4px; padding: 3px 0;
  border-bottom: 1px solid #121323; font-size: 10px;
}
.pm-sly-src-row:last-child { border-bottom: none; }
.pm-sly-src-lbl { width: 90px; flex-shrink: 0; font-size: 8.5px; font-weight: 700; color: #8898c8; letter-spacing: 0.3px; }
.pm-sly-src-val { flex: 1; color: #7880a0; font-size: 10px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* ── QUICK ACTIONS — now chips inside SOURCES card (see .pm-sly-qa-chip above) ── */

/* ── VIEWER HEADER ── */
.pm-sly-vhdr {
  display: flex; align-items: center; gap: 8px; padding: 6px 10px;
  background: #0e0f1e; border-bottom: 1px solid #181928; flex-shrink: 0;
}
.pm-sly-vhdr-lbl { font-size: 9px; font-weight: 800; color: #8898c8; letter-spacing: 0.6px; text-transform: uppercase; }
.pm-sly-vhdr-btns { display: flex; gap: 4px; margin-left: auto; }
.pm-sly-vhdr-btn {
  background: #141528; border: 1px solid #1e2040; color: #8890c0;
  font-size: 10px; font-weight: 600; padding: 3px 8px; border-radius: 3px; cursor: pointer;
}
.pm-sly-vhdr-btn:hover { background: #1a1c38; color: #c0c8f0; }
.pm-sly-vhdr-add { color: #2172E3 !important; border-color: #5a4a10 !important; background: #1c1808 !important; }
.pm-sly-vhdr-add:hover { background: #251e08 !important; color: #e0bd62 !important; }

/* ── VIEWER SLOT — houses the DOM-moved .pm-right ── */
.pm-sly-viewer-slot {
  flex: 1; min-height: 0; overflow: hidden; position: relative;
  background: #060710;
}
.pm-sly-viewer-slot .pm-right {
  height: 100% !important; max-height: 100% !important;
  width: 100% !important; max-width: 100% !important;
  border-right: none !important;
  overflow: hidden !important;
}
.pm-sly-viewer-slot .pm-inspector { display: none !important; }

/* ── INSIGHT BAR ── */
.pm-sly-insight {
  display: flex; align-items: center; gap: 6px; padding: 5px 10px;
  background: #0b0d1c; border-top: 1px solid #141626; flex-shrink: 0;
}
.pm-sly-ins-item { font-size: 10px; color: #0AA356; }
.pm-sly-ins-item.is-warn { color: #e5a040; }
.pm-sly-ins-sep { font-size: 10px; color: #2a2e48; }

/* ── MARKER STRIP ── */
.pm-sly-mkstrip {
  height: 26px; flex-shrink: 0; position: relative;
  background: #0a0b18; border-top: 1px solid #141626; overflow: hidden;
}
.pm-sly-mk-chip {
  position: absolute; top: 4px; transform: translateX(-50%);
  height: 18px; min-width: 6px; border-radius: 2px;
  cursor: pointer; overflow: hidden;
  display: flex; align-items: center; padding: 0 3px;
  font-size: 8px; font-weight: 600; color: #fff; white-space: nowrap;
  transition: transform 0.1s, z-index 0s;
}
.pm-sly-mk-chip:hover { z-index: 10; transform: translateX(-50%) scaleY(1.2); }
.pm-sly-mk-chip.is-sel { outline: 1px solid #fff; z-index: 5; }
.pm-sly-mk-chip-pl { background: #3a6ec8; }
.pm-sly-mk-chip-cp { background: #6b3ec8; }
.pm-sly-mk-chip-fg { background: #3ec87a; }
.pm-sly-mk-chip-bg { background: #c86a3e; }
.pm-sly-chip-label { display: none; }
.pm-sly-mk-chip:hover .pm-sly-chip-label { display: block; }

/* ── KPI BAR ── */
.pm-sly-kpi-bar {
  background: #0e0f1e; border: 1px solid #1a1c2e; border-radius: 5px;
  padding: 7px 10px; flex-shrink: 0;
}
.pm-sly-kpi-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 4px; }
.pm-sly-kpi { font-size: 10px; font-weight: 700; white-space: nowrap; }
.pm-sly-kpi-ok      { color: #0AA356; }
.pm-sly-kpi-neutral { color: #7880a0; }
.pm-sly-kpi-warn    { color: #e5a040; }
.pm-sly-kpi-cp      { color: #a060e0; }
.pm-sly-kpi-pl      { color: #6090e0; }
.pm-sly-kpi-ev-row  { font-size: 9.5px; color: #8898b8; display: flex; gap: 6px; align-items: center; margin-bottom: 3px; }
.pm-sly-kpi-sep     { opacity: 0.5; }
.pm-sly-kpi-warn-note { font-size: 9.5px; color: #e0a040; margin: 3px 0; }
.pm-sly-kpi-prog-wrap { margin-top: 5px; }
.pm-sly-kpi-prog-bg {
  height: 3px; background: #1a1c30; border-radius: 2px; overflow: hidden; margin-bottom: 3px;
}
.pm-sly-kpi-prog-fill { height: 100%; background: #2172E3; border-radius: 2px; transition: width 0.3s; }
.pm-sly-kpi-prog-label { font-size: 9px; color: #8898b8; }

/* ── MARK NEXT BUTTON ── */
.pm-sly-mark-next {
  width: 100%; text-align: left; padding: 6px 10px; flex-shrink: 0;
  background: #1c1808; border: 1px solid #5a4a10; border-radius: 4px;
  color: #2172E3; font-size: 10.5px; font-weight: 700; cursor: pointer;
  letter-spacing: 0.2px;
}
.pm-sly-mark-next:hover { background: #251e08; color: #e0bd62; }

/* ── SMART AUTO CARD ── */
.pm-sly-smart-card { padding: 8px 10px; }
.pm-sly-smart-hdr {
  display: flex; align-items: center; gap: 5px;
  font-size: 10px; font-weight: 800; color: #2172E3; letter-spacing: 0.5px;
  margin-bottom: 7px;
}
.pm-sly-sa-unk {
  font-size: 9.5px; color: #0AA356; margin-bottom: 6px; font-weight: 600;
}
.pm-sly-sa-cl-lbl {
  font-size: 8.5px; font-weight: 700; color: #8898c8; letter-spacing: 0.4px;
  text-transform: uppercase; margin-bottom: 5px;
}
.pm-sly-sa-clusters { display: flex; flex-direction: column; gap: 3px; margin-bottom: 8px; }
.pm-sly-sa-cluster {
  display: flex; align-items: center; gap: 4px;
  padding: 4px 6px; border-radius: 3px; cursor: pointer;
  background: #101122; border: 1px solid #1a1c30;
  transition: background 0.1s;
}
.pm-sly-sa-cluster:hover { background: #14162a; border-color: #3a3f70; }
.pm-sly-sa-cluster.is-marked { opacity: 0.55; }
.pm-sly-sa-dot {
  width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0;
  background: #3a6ec8;
}
.pm-sly-sa-cname { font-size: 10px; font-weight: 700; color: #c0c8f0; min-width: 0; flex-shrink: 0; }
.pm-sly-sa-cinfo { font-size: 9.5px; color: #a0a8d0; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-sly-sa-help {
  flex-shrink: 0; background: none; border: 1px solid #2a2c48; color: #9098c0;
  font-size: 9px; width: 16px; height: 16px; border-radius: 50%; cursor: pointer;
  padding: 0; display: flex; align-items: center; justify-content: center;
}
.pm-sly-sa-help:hover { background: #1a1c30; color: #c0c8f0; }
.pm-sly-sa-approve {
  display: block; width: 100%; text-align: left; padding: 5px 0;
  background: none; border: none; color: #0AA356; font-size: 10px; font-weight: 700;
  cursor: pointer;
}
.pm-sly-sa-approve:hover { color: #7de0a8; }
.pm-sly-sa-insight { font-size: 10px; color: #0AA356; padding: 3px 0; }
.pm-sly-sa-ai {
  display: block; width: 100%; text-align: left; padding: 3px 0;
  background: none; border: none; color: #5060a0; font-size: 10px; font-weight: 600;
  cursor: pointer; text-decoration: underline;
}
.pm-sly-sa-ai:hover { color: #7080c0; }

/* ════════════════════════════════════════════════════════════════════════
   SMART AUTO v2 — compact, plain-language panel for non-tech users
   ════════════════════════════════════════════════════════════════════════ */

/* Progress bar */
.pm-sa2-progress { margin-bottom: 7px; }
.pm-sa2-prog-bar {
  height: 3px; border-radius: 2px;
  background: rgba(255,255,255,0.06); overflow: hidden; margin-bottom: 3px;
}
.pm-sa2-prog-fill { height: 100%; border-radius: 2px; transition: width 0.4s ease; }
.pm-sa2-prog-labels { display: flex; justify-content: space-between; align-items: baseline; }
.pm-sa2-prog-pct   { font-size: 10px; font-weight: 800; line-height: 1; }
.pm-sa2-prog-count { font-size: 8.5px; color: #8898c8; }

/* Mark All row — button + next-name hint on one line */
.pm-sa2-mark-row {
  display: flex; align-items: center; gap: 6px; margin-bottom: 7px;
}
.pm-sa2-mark-all {
  flex-shrink: 0; padding: 5px 10px;
  background: linear-gradient(135deg, rgba(58,110,200,0.30), rgba(10,163,86,0.22));
  border: 1px solid rgba(84,213,255,0.40); border-radius: 5px;
  color: #c0e8ff; font-size: 9.5px; font-weight: 800; letter-spacing: 0.3px;
  cursor: pointer; transition: background 0.14s, border-color 0.14s; white-space: nowrap;
}
.pm-sa2-mark-all:hover { background: rgba(84,213,255,0.18); border-color: rgba(84,213,255,0.65); }
.pm-sa2-mark-n {
  display: inline-block; background: rgba(84,213,255,0.18); border-radius: 8px;
  padding: 0 4px; font-size: 8.5px; margin-left: 3px;
}
/* Next name hint — monospace, truncated, secondary */
.pm-sa2-mark-hint {
  font-size: 8.5px; font-weight: 700; color: #7898b8;
  font-family: 'SF Mono','Fira Mono','Consolas',monospace;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1;
}

/* All done state */
.pm-sa2-all-done {
  font-size: 9.5px; font-weight: 700; color: #0AA356; padding: 4px 0; margin-bottom: 5px;
}

/* Status row — unknown pill + approve button inline */
.pm-sa2-status-row {
  display: flex; align-items: center; gap: 6px; margin-bottom: 6px;
}
.pm-sa2-unk-pill {
  font-size: 8.5px; color: #404868; background: rgba(255,255,255,0.04);
  padding: 1px 5px; border-radius: 8px; border: 1px solid #202236;
}

/* Section label (shared for groups + marked shots) */
.pm-sa2-groups-lbl {
  font-size: 8px; font-weight: 700; color: #7080a8; letter-spacing: 0.5px;
  text-transform: uppercase; margin-bottom: 5px; display: flex; align-items: center; gap: 5px;
}
.pm-sa2-mk-count {
  background: rgba(84,213,255,0.15); color: #4890b0; padding: 0 5px;
  border-radius: 8px; font-size: 8px; font-weight: 800; line-height: 14px;
}

/* Marked shots list */
.pm-sa2-mkshots {
  display: flex; flex-direction: column; gap: 2px; margin-bottom: 8px;
  max-height: 240px; overflow-y: auto;
  scrollbar-width: thin; scrollbar-color: #252840 transparent;
}
.pm-sa2-mkshots::-webkit-scrollbar { width: 3px; }
.pm-sa2-mkshots::-webkit-scrollbar-thumb { background: #252840; border-radius: 2px; }

.pm-sa2-mks-row {
  display: flex; align-items: center; gap: 4px;
  padding: 2px 4px; border-radius: 3px; cursor: pointer; transition: background 0.1s;
}
.pm-sa2-mks-row:hover { background: #0e1020; }
.pm-sa2-mks-dot { width: 5px; height: 5px; border-radius: 50%; flex-shrink: 0; }
.pm-sa2-mks-name {
  font-size: 9px; font-weight: 700; color: #808aaa; flex: 1;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-family: 'SF Mono','Fira Mono','Consolas',monospace;
}
.pm-sa2-mks-reel { font-size: 7.5px; color: #6878a8; flex-shrink:0; max-width:50px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.pm-sa2-mks-tc   { font-size: 7.5px; color: #606880; flex-shrink:0; font-variant-numeric:tabular-nums; }

/* Divider between Smart Auto and Marker editor (within the same card) */
.pm-sa2-mk-divider {
  height: 1px; background: rgba(255,255,255,0.05);
  margin: 8px -10px 8px; /* bleed to card edges */
}
.pm-sa2-mk-hdr {
  font-size: 8px; font-weight: 700; color: #7080a8; letter-spacing: 0.5px;
