.pm-sly-mk-rname { flex: 1; font-size: 10px; color: #9098c0; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-sly-mk-rbadge { font-size: 8.5px; font-weight: 700; padding: 1px 4px; border-radius: 3px; flex-shrink: 0; }
.pm-sly-mk-pl  { background: #1a2240; color: #6090e0; }
.pm-sly-mk-cp  { background: #1e1a40; color: #a060e0; }
