/* ── EXPORT SUMMARY ── */
.pm-sly-sum-grid {
  display: grid; grid-template-columns: auto 1fr; gap: 3px 10px; align-items: center;
}
.pm-sly-sum-k { font-size: 9px; font-weight: 700; color: #8898c8; letter-spacing: 0.3px; text-transform: uppercase; }
.pm-sly-sum-v { font-size: 10.5px; color: #9098c0; font-weight: 600; }

/* ── EXPORT BUTTON AREA ── */
.pm-sly-ex-wrap { display: flex; flex-direction: column; gap: 5px; }
.pm-sly-ex-btn {
  width: 100%; padding: 10px 12px; font-size: 12px; font-weight: 800;
  background: #1c1808; border: 1px solid #6a5010; border-radius: 5px;
  color: #2172E3; cursor: pointer; text-align: left; letter-spacing: 0.2px;
  display: flex; align-items: center; gap: 6px;
}
.pm-sly-ex-btn:hover { background: #251e08; border-color: #8a6818; }
.pm-sly-ex-btn:disabled { opacity: 0.4; cursor: default; }
.pm-sly-ex-warn {
  margin-left: auto; font-size: 10px; font-weight: 700; color: #e0a040;
  background: #1e1200; border: 1px solid #5a3800; padding: 1px 5px; border-radius: 3px;
}
.pm-sly-rq-note { font-size: 9.5px; color: #8898c8; text-align: center; }
.pm-sly-sub-row { display: flex; gap: 4px; flex-wrap: wrap; }

.pm-sly-sub-btn {
  background: #0f1020; border: 1px solid #1a1c30; color: #a0a8d0;
  font-size: 9.5px; font-weight: 600; padding: 3px 7px; border-radius: 3px; cursor: pointer;
}
.pm-sly-sub-btn:hover { background: #141528; color: #c0c8f0; border-color: #2a2e58; }
.pm-sly-paste-btn {
  width: 100%; background: #0f1020; border: 1px solid #1e2040; color: #5060a0;
  font-size: 10px; font-weight: 700; padding: 5px 8px; border-radius: 3px; cursor: pointer;
  text-align: center;
}
.pm-sly-paste-btn:hover { background: #141528; color: #8090c0; }


/* Smart Auto additions */
.pm-sly-sa-summary {
  font-size: 10px; color: #0AA356; font-weight: 700; margin-bottom: 5px;
}
.pm-sly-sa-more {
  font-size: 9.5px; color: #8898b8; padding: 3px 6px; cursor: pointer;
}
.pm-sly-sa-more:hover { color: #8890b0; }

/* Topbar — ensure right-side buttons always visible */
.pm-sly-topbar-r {
  display: flex; align-items: center; gap: 5px; flex-shrink: 0; margin-left: auto;
}
.pm-sly-steps {
  flex: 0 1 auto; /* don't force-expand — let topbar-r stay visible */
  min-width: 0; overflow: hidden;
}

/* ── Smart/Advanced mode toggle — ctx bar + floating overlay ── */

/* SMART button (in Smart mode → offers "Advanced") — amber, prominent */
.pm-mode-toggle {
  display: flex; align-items: center; gap: 5px; flex-shrink: 0;
  background: rgba(214,163,58,0.12); border: 1px solid rgba(214,163,58,0.50);
  color: #2172E3;
  font-size: 10px; font-weight: 800; padding: 4px 10px; border-radius: 5px;
  cursor: pointer; letter-spacing: 0.3px; white-space: nowrap;
  transition: background 0.13s, border-color 0.13s;
}
.pm-mode-toggle:hover { background: rgba(214,163,58,0.22); border-color: #2172E3; color: #e0bd62; }
.pm-mode-toggle svg { flex-shrink: 0; }

/* ADVANCED button (in Advanced mode → offers "Smart") — green, inviting */
.pm-mode-toggle.is-smart-active {
  background: rgba(10,163,86,0.12); border-color: rgba(10,163,86,0.45); color: #0AA356;
}
.pm-mode-toggle.is-smart-active:hover { background: rgba(10,163,86,0.22); border-color: #0AA356; color: #7de0a8; }

/* Floating overlay toggle — mirrors pm-mode-toggle visual logic */
.pm-adv-toggle.is-simple {    /* in advanced mode → "← Smart" green */
  background: rgba(10,163,86,0.13); border-color: rgba(10,163,86,0.45); color: #0AA356;
}
.pm-adv-toggle.is-simple:hover { background: rgba(10,163,86,0.24); border-color: #0AA356; color: #7de0a8; }
.pm-adv-toggle:not(.is-simple) {  /* in smart mode → "Advanced" amber */
  background: rgba(214,163,58,0.10); border-color: rgba(214,163,58,0.40); color: #d4a826;
}
.pm-adv-toggle:not(.is-simple):hover { background: rgba(214,163,58,0.20); border-color: #2172E3; color: #2172E3; }

/* ── Smart Auto v2 — smarter layout ── */

/* Coverage bar */
.pm-sly-sa-cov { margin-bottom: 7px; }
.pm-sly-sa-cov-bar {
  height: 4px; background: #1a1c30; border-radius: 2px; overflow: hidden; margin-bottom: 3px;
}
.pm-sly-sa-cov-fill { height: 100%; background: linear-gradient(90deg, #3a6ec8, #0AA356); border-radius: 2px; transition: width 0.4s; }
.pm-sly-sa-cov-lbl { display: flex; justify-content: space-between; font-size: 9.5px; color: #9098c0; }
.pm-sly-sa-cov-pct { color: #2172E3; font-weight: 700; }

/* Camera breakdown chips */
.pm-sly-sa-cams { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 7px; }
.pm-sly-sa-cam-chip {
  display: flex; align-items: center; gap: 4px;
  font-size: 9.5px; color: #7080a0; background: #101122; border: 1px solid #1a1c30;
  padding: 2px 7px; border-radius: 10px; cursor: default;
}
.pm-sly-sa-cam-dot {
  width: 6px; height: 6px; border-radius: 50%; background: #3a6ec8; flex-shrink: 0;
}
.pm-sly-sa-cam-pct { color: #0AA356; font-weight: 700; margin-left: 3px; }

/* Smart warnings */
.pm-sly-sa-warns { margin-bottom: 6px; }
.pm-sly-sa-warn { font-size: 9.5px; color: #e0a040; padding: 1px 0; }

/* Cluster rows — v2 */
.pm-sly-sa-clusters { display: flex; flex-direction: column; margin-bottom: 6px; }
.pm-sly-sa-cluster {
  display: grid;
  grid-template-columns: 14px 1fr auto auto;
  align-items: center; gap: 4px;
  padding: 4px 4px; border-radius: 3px;
  cursor: pointer; transition: background 0.1s;
  border-bottom: 1px solid #101122;
}
.pm-sly-sa-cluster:last-child { border-bottom: none; }
.pm-sly-sa-cluster:hover { background: #13142a; }
.pm-sly-sa-cluster.is-done { opacity: 0.45; }
.pm-sly-sa-cluster.is-next { background: #141830; }

/* Status dot */
.pm-sly-sa-sdot { font-size: 10px; text-align: center; flex-shrink: 0; }
.sa-dot-none    { color: #3a3e60; }
.sa-dot-partial { color: #e0a040; }
.sa-dot-done    { color: #0AA356; }

.pm-sly-sa-cname  { font-size: 10px; font-weight: 700; color: #b0b8e0; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-sly-sa-ccount { font-size: 9px; color: #8898b8; text-align: right; flex-shrink: 0; }

/* Cluster CTA button */
.pm-sly-sa-cta {
  flex-shrink: 0; background: #141830; border: 1px solid #2a2e58; color: #8090c0;
  font-size: 9px; font-weight: 700; padding: 2px 6px; border-radius: 3px; cursor: pointer;
  white-space: nowrap;
}
.pm-sly-sa-cta:hover { background: #1c2040; color: #2172E3; border-color: #5a4a10; }
.pm-sly-sa-cta-all { color: #2172E3 !important; border-color: #5a4a10 !important; background: #1c1808 !important; }
.pm-sly-sa-cta-all:hover { background: #251e08 !important; }
.pm-sly-sa-cta-done { font-size: 9px; color: #0AA356; flex-shrink: 0; padding: 0 4px; }

/* More rolls */
.pm-sly-sa-more { font-size: 9.5px; color: #8898b8; padding: 5px 4px; cursor: pointer; }
.pm-sly-sa-more:hover { color: #8890b0; }
.pm-sly-sa-more-done { color: #0AA356; margin-left: 3px; }

/* Mark next button */
.pm-sly-sa-next {
  width: 100%; text-align: left; padding: 6px 8px; margin-bottom: 5px;
  background: #181a2e; border: 1px solid #3040a0; border-radius: 4px;
  color: #2172E3; font-size: 10px; font-weight: 800; cursor: pointer;
  display: flex; align-items: center; gap: 5px; flex-wrap: wrap;
}
.pm-sly-sa-next:hover { background: #1e2038; border-color: #4050c0; }
.pm-sly-sa-next-name { color: #d0d8f8; font-weight: 600; font-size: 9.5px; overflow: hidden; text-overflow: ellipsis; }

/* All done state */
.pm-sly-sa-all-done { font-size: 10px; color: #0AA356; font-weight: 700; padding: 5px 0; }

/* Insights block */
.pm-sly-sa-insights { margin-top: 5px; border-top: 1px solid #141626; padding-top: 5px; }
.pm-sly-sa-ins { font-size: 10px; padding: 2px 0; }
.pm-sly-sa-ins.is-ok  { color: #0AA356; }
.pm-sly-sa-ins.is-warn { color: #e0a040; }

/* Smart Auto v3 additions */
.pm-sly-sa-autoall {
  width: 100%; padding: 8px 10px; margin-bottom: 7px;
  background: linear-gradient(135deg, #1c1808 0%, #141830 100%);
  border: 1px solid #5a4a10; border-radius: 4px;
  color: #2172E3; font-size: 10.5px; font-weight: 800;
  cursor: pointer; text-align: left; letter-spacing: 0.2px;
  display: flex; align-items: center; gap: 6px;
}
.pm-sly-sa-autoall:hover { border-color: #8a6818; background: linear-gradient(135deg, #251e08 0%, #1c2040 100%); }

/* Plate type badge inside cluster count */
.pm-sly-sa-ctype {
  font-size: 8px; font-weight: 800; color: #8898b8; background: #0f1020;
  border: 1px solid #1a1c30; padding: 0 3px; border-radius: 2px; margin-left: 2px;
}

/* CTA variants */
.pm-sly-sa-cta-cont  { color: #e0a040 !important; border-color: #5a3800 !important; background: #1e1200 !important; }
.pm-sly-sa-cta-start { color: #8090c0; }
.pm-sly-sa-cta-start:hover { color: #2172E3; border-color: #5a4a10; background: #1c1808; }

/* ── Shot Marker + Naming panel (smart mode) ── */
.pm-sly-mk-edit-hdr {
  display: flex; align-items: center; gap: 6px; margin-bottom: 8px;
}
.pm-sly-mk-edit-title { flex: 1; font-size: 10px; font-weight: 800; color: #8890c0; letter-spacing: 0.4px; text-transform: uppercase; }
.pm-sly-mk-template-btn {
  background: #141830; border: 1px solid #2a2e58; color: #8090c0;
