}
.pm-sly-mk-template-btn:hover { color: #2172E3; border-color: #5a4a10; background: #1c1808; }

.pm-sly-mk-field { margin-bottom: 7px; }
.pm-sly-mk-lbl {
  display: block; font-size: 8.5px; font-weight: 800; color: #8898c8;
  letter-spacing: 0.5px; text-transform: uppercase; margin-bottom: 3px;
}
.pm-sly-mk-name-row { display: flex; gap: 4px; }
.pm-sly-mk-name-inp {
  flex: 1; background: #0d0e1c; border: 1px solid #2a2e58; border-radius: 3px;
  color: #e0e4f8; font-size: 11px; font-weight: 700; padding: 4px 7px;
  font-family: monospace; min-width: 0;
}
.pm-sly-mk-name-inp:focus { outline: none; border-color: #2172E3; background: #111220; }
.pm-sly-mk-name-ok {
  flex-shrink: 0; background: #1c1808; border: 1px solid #5a4a10; color: #2172E3;
