}
.pm-sly-mk-name-ok:hover { background: #251e08; }

.pm-sly-mk-type-sel {
  width: 100%; background: #0d0e1c; border: 1px solid #2a2e58; border-radius: 3px;
  color: #9098c0; font-size: 10.5px; padding: 4px 6px; cursor: pointer;
}
