  font-family: inherit; box-sizing: border-box;
}
.pm-sly-mk-note-inp:focus { outline: none; border-color: #2a3468; }

.pm-sly-mk-meta-grid {
  display: grid; grid-template-columns: 28px 1fr; gap: 2px 6px;
  align-items: center; margin-bottom: 7px; font-size: 10px;
}
