.pm-sly-mk-actions { display: flex; gap: 5px; flex-wrap: wrap; }

/* List view */
.pm-sly-mk-list-hdr { font-size: 9px; color: #8898c8; font-weight: 700; letter-spacing: 0.3px; text-transform: uppercase; margin-bottom: 5px; }
.pm-sly-mk-row {
  display: flex; align-items: center; gap: 5px; padding: 4px 3px;
  border-bottom: 1px solid #0f1020; cursor: pointer; border-radius: 2px;
}
.pm-sly-mk-row:last-child { border-bottom: none; }
.pm-sly-mk-row:hover { background: #13142a; }
.pm-sly-mk-row-body { flex: 1; min-width: 0; }
.pm-sly-mk-reel-small { display: block; font-size: 8.5px; color: #8898c8; font-family: monospace; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-sly-mk-warn-dot { font-size: 9px; color: #e07040; font-weight: 800; flex-shrink: 0; }

/* ── Undo / Redo history buttons ── */
.pm-sly-history-btns { display: flex; gap: 3px; align-items: center; margin-right: 5px; }
.pm-sly-hist-btn {
  display: flex; align-items: center; justify-content: center; gap: 4px;
  background: rgba(84,213,255,0.08); border: 1px solid rgba(84,213,255,0.25);
  color: #c8d8f8;
  padding: 4px 10px; height: 26px; border-radius: 5px;
  cursor: pointer; position: relative; font-size: 10px; font-weight: 800;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
  white-space: nowrap; letter-spacing: 0.2px;
}
.pm-sly-hist-btn:not([disabled]):hover {
  background: rgba(84,213,255,0.18); border-color: rgba(84,213,255,0.60);
  color: #ffffff;
}
.pm-sly-hist-btn[disabled] { opacity: 0.28; cursor: default; }
/* Text labels */
#pmSlyUndoBtn::after { content: 'Undo'; }
#pmSlyRedoBtn::after { content: 'Redo'; }
.pm-sly-hist-count {
  position: absolute; top: -5px; right: -5px;
  background: #3a6ec8; color: #fff; font-size: 7.5px; font-weight: 800;
  min-width: 13px; height: 13px; border-radius: 7px; line-height: 13px;
  text-align: center; padding: 0 2px;
}

/* ── Center stats bar ── */
.pm-sly-stats-bar {
  display: flex; align-items: center; flex-wrap: wrap; gap: 0;
  padding: 3px 10px; background: #0d0e1c; border-bottom: 1px solid #141526;
  flex-shrink: 0; min-height: 22px; overflow: hidden;
}
.pm-sly-sb-chip { font-size: 9.5px; color: #9098c0; white-space: nowrap; }
.pm-sly-sb-sep  { font-size: 9.5px; color: #282a40; margin: 0 5px; }

/* ── Smart Auto — reference design ── */
.pm-sly-sa-unk-line {
  font-size: 10px; color: #0AA356; font-weight: 600; margin-bottom: 6px; padding: 0 1px;
}
.pm-sly-sa-cl-lbl {
  font-size: 8.5px; font-weight: 700; color: #3a3e60; letter-spacing: 0.5px;
  text-transform: uppercase; margin-bottom: 5px;
}
.pm-sly-sa-clusters { display: flex; flex-direction: column; gap: 1px; margin-bottom: 8px; }
.pm-sly-sa-cluster {
  display: flex; align-items: center; gap: 5px;
  padding: 5px 4px; border-radius: 3px; cursor: pointer;
  transition: background 0.1s;
}
.pm-sly-sa-cluster:hover { background: #12132a; }
.pm-sly-sa-cluster.is-done { opacity: 0.4; pointer-events: none; }
.pm-sly-sa-cdot {
  width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0;
}
.pm-sly-sa-cname { font-size: 10.5px; font-weight: 700; color: #c0c8f0; flex-shrink: 0; }
.pm-sly-sa-cinfo { font-size: 10px; color: #6070a0; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pm-sly-sa-qbtn {
  flex-shrink: 0; background: none; border: 1px solid #2a2c48; color: #8898b8;
  font-size: 9px; width: 16px; height: 16px; border-radius: 50%;
