.pm-sly-sa-more {
  font-size: 9.5px; color: #4a5070; padding: 4px 4px; cursor: pointer;
}
.pm-sly-sa-more:hover { color: #8890b0; }

/* Approve button — matches reference: green text, full-width */
.pm-sly-sa-approve {
  display: block; width: 100%; text-align: left;
  background: #0e1a12; border: 1px solid #1e4028; border-radius: 3px;
  color: #0AA356; font-size: 10px; font-weight: 700;
  padding: 6px 8px; cursor: pointer; margin-bottom: 6px;
}
.pm-sly-sa-approve:hover { background: #122016; color: #7de0a8; }

/* Insight lines */
.pm-sly-sa-exp-ok {
  font-size: 10px; color: #0AA356; padding: 2px 0; font-weight: 600;
}
.pm-sly-sa-ai-link {
  font-size: 10px; color: #8898b8; padding: 2px 0; cursor: pointer;
}
.pm-sly-sa-ai-link:hover { color: #8090c0; }

/* Divider */
.pm-sly-sa-divider {
  font-size: 10px; color: #2a2c48; padding: 5px 0; text-align: center;
}

/* ════════════════════════════════════════════════════════════════════════════
   MARKER FLAG RAIL — sits above the transport controls scrub bar
   Shows a colored flag at every marker's timecode position
   ════════════════════════════════════════════════════════════════════════ */

.pm-mk-rail {
  position: relative;
  width: 100%;
  height: 28px;
  background: #08090f;
  border-top: 1px solid #141526;
  border-bottom: 1px solid #0d0e1a;
  overflow: visible;
  flex-shrink: 0;
  box-sizing: border-box;
}

/* Individual flag */
.pm-mk-flag {
  position: absolute;
  top: 0;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  z-index: 2;
  /* highlight on hover / select */
}
.pm-mk-flag:hover { z-index: 10; }
.pm-mk-flag.is-sel .pm-mk-flag-tick { box-shadow: 0 0 0 2px #fff; }

/* The vertical tick line — hidden */
.pm-mk-flag-tick { display: none; }

/* Triangle notch — hidden */
.pm-mk-flag-tick::after { display: none; }

/* Tooltip card — hidden by default, shown on hover */
.pm-mk-flag-tip {
  position: absolute;
  bottom: calc(100% + 4px);
  left: 50%;
  transform: translateX(-50%);
  background: #0e1020;
  border: 1px solid var(--flag-color, #2172E3);
  border-radius: 4px;
  padding: 5px 8px;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.12s;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 80px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.6);
}
.pm-mk-flag:hover .pm-mk-flag-tip { opacity: 1; }

.pm-mk-flag-code {
  font-size: 8.5px; font-weight: 800;
  color: var(--flag-color, #2172E3);
  letter-spacing: 0.4px; text-transform: uppercase;
}
.pm-mk-flag-shot {
  font-size: 10px; font-weight: 700; color: #d0d8f0;
  font-family: monospace; max-width: 160px;
  overflow: hidden; text-overflow: ellipsis;
}
.pm-mk-flag-tc {
  font-size: 9px; color: #6070a0;
  font-family: monospace; font-variant-numeric: tabular-nums;
}

/* Small dot at the base of the tick on the rail */
.pm-mk-flag::after {
  content: '';
  display: block;
  position: absolute;
  bottom: 2px;
  left: 50%;
  transform: translateX(-50%);
  width: 5px; height: 5px;
  border-radius: 50%;
  background: var(--flag-color, #2172E3);
  opacity: 0.7;
}
.pm-mk-flag:hover::after { opacity: 1; width: 7px; height: 7px; bottom: 1px; }

/* ── Marker rail alignment — pixel math in JS, no padding trick needed ── */
.pm-mk-rail {
  padding: 0 !important; /* JS computes exact left% per flag using getBoundingClientRect */
}
.pm-mk-flag {
  position: absolute; /* left% computed relative to full rail width via pixel math */
}

/* Tick lines hidden — only dot indicator remains */
.pm-mk-flag-tick { display: none; }
.pm-mk-flag:hover .pm-mk-flag-tick,
.pm-mk-flag.is-sel .pm-mk-flag-tick { display: none; }

/* Tooltip: always appears above the rail, centered on the flag */
.pm-mk-flag-tip {
  bottom: calc(100% + 5px);
  /* Prevent overflow beyond viewport edges */
  max-width: 180px;
}

/* Dot at base of tick — hidden */
.pm-mk-flag::after { display: none; }

/* ── Scrub + marker rail wrapper — shared flex slot ── */
.pm-scrub-wrap {
  flex: 1;            /* takes same space the scrub used to take */
  min-width: 0;
  position: relative; /* rail is absolute inside here */
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Rail sits above the scrub inside the same width container */
.pm-scrub-wrap .pm-mk-rail {
  position: relative;
  width: 100%;        /* exactly == scrub width */
  height: 22px;
  background: #090a14;
  border-top: 1px solid #141526;
  overflow: visible;
  flex-shrink: 0;
  padding: 0 !important;
  box-sizing: border-box;
}

/* Scrub bar fills remaining space below the rail */
.pm-scrub-wrap .pm-scrub {
  width: 100%;
  flex: 1;
}

