/* ═══════════════════════════════════════════════════════════════════════════════
   VISUAL QC — sm-importdock slots inside #main-reviews (V1 REF / Video + Timeline)
   The .sm-importdock-* classes are scoped to #main-shotmarker in the original
   CSS, so they get no styling when rendered inside the Visual QC bin.
   ═══════════════════════════════════════════════════════════════════════════════ */

#main-reviews .sm-importdock-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px;
  gap: 6px;
  align-items: stretch;
}

#main-reviews .sm-importdock-btn {
  width: 100%;
  min-height: 46px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,.09);
  background: #1C1C1C;
  color: rgba(255,255,255,.85);
  cursor: pointer;
  text-align: left;
  transition: border-color .12s, background .12s;
}
#main-reviews .sm-importdock-btn:hover {
  background: #242424;
  border-color: rgba(255,255,255,.16);
}
#main-reviews .sm-importdock-row.is-loaded .sm-importdock-btn {
  border-color: rgba(255,255,255,.13);
}
#main-reviews .sm-importdock-btn.is-dropover {
  border-color: rgba(74,144,217,.45);
  background: rgba(74,144,217,.08);
}

#main-reviews .sm-importdock-remove {
  min-width: 30px;
  width: 30px;
  padding: 0;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,.09);
  background: rgba(255,255,255,.03);
  color: rgba(255,255,255,.55);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background .12s, border-color .12s;
}
#main-reviews .sm-importdock-remove:hover:not([disabled]) {
  background: rgba(229,9,20,.10);
  border-color: rgba(229,9,20,.30);
  color: rgba(255,100,100,.90);
}
#main-reviews .sm-importdock-remove[disabled] { opacity: .35; cursor: default; pointer-events: none; }

#main-reviews .sm-importdock-ico {
  width: 26px; height: 26px; min-width: 26px;
  display: grid; place-items: center;
  border-radius: 4px;
  background: rgba(255,255,255,.05);
  color: rgba(200,220,255,.88);
  flex-shrink: 0;
}
#main-reviews .sm-importdock-row[data-import-kind="video"] .sm-importdock-ico {
  box-shadow: inset 3px 0 0 rgba(74,144,217,.80);
}
#main-reviews .sm-importdock-row[data-import-kind="timeline"] .sm-importdock-ico {
  box-shadow: inset 3px 0 0 rgba(229,9,20,.70);
}
#main-reviews .sm-importdock-ico svg { width: 13px; height: 13px; }

#main-reviews .sm-importdock-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  overflow: hidden;
}
#main-reviews .sm-importdock-label {
  font-size: 11px;
  font-weight: 700;
  color: rgba(255,255,255,.85);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#main-reviews .sm-importdock-meta {
  display: block;
  font-size: 10px;
  color: rgba(255,255,255,.45);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  font-family: ui-monospace, 'SF Mono', Consolas, monospace;
}

/* filmstrip notes card inside reviews also uses glass — flatten */
#main-reviews .pfx-reviews-center > .pfx-reviews-notes .pfx-reviews-card {
  background: #141414 !important;
  border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 5px !important;
  box-shadow: none !important;
}
#main-reviews .pfx-reviews-center > .pfx-reviews-notes .pfx-reviews-cardHeader {
  background: #141414 !important;
  border-bottom: 1px solid rgba(255,255,255,.08) !important;
  min-height: 30px !important;
}


