.sm-anno-lock-badge,
[class*="anno-lock"],
[class*="frameLocked"],
[class*="frame-locked"] {
  background: rgba(229,9,20,.12) !important;
  border: 1px solid rgba(229,9,20,.35) !important;
  color: rgba(229,9,20,.90) !important;
  border-radius: 4px !important;
  font-size: 9.5px !important;
  font-weight: 800 !important;
  letter-spacing: .06em !important;
  animation: none !important;
  box-shadow: none !important;
}

/* ── Annotation count / status badges ───────────────────────────────────────── */
.sm-anno-ai-status {
  background: rgba(255,255,255,.04) !important;
  border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 4px !important;
  color: rgba(255,255,255,.50) !important;
}
.sm-anno-ai-status[data-state="analyzing"] {
  border-color: rgba(229,9,20,.30) !important;
  color: rgba(229,9,20,.80) !important;
  background: rgba(229,9,20,.06) !important;
}

/* ── Group pill wrapper (non-AI) ──────────────────────────────────────────────── */
.sm-anno-group:not(.sm-anno-ai-group):not(.sm-anno-colors):not(.sm-anno-styles) {
  background: rgba(255,255,255,.03) !important;
  border: 1px solid rgba(255,255,255,.07) !important;
  border-radius: 4px !important;
  padding: 2px 4px !important;
}

/* ── Stage canvas area ────────────────────────────────────────────────────────── */
.sm-anno-stage { background: #0A0A0A !important; }
.sm-anno-wrap {
  border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 6px !important;
  box-shadow: none !important;
}

/* ── Note row ─────────────────────────────────────────────────────────────────── */
.sm-anno-noteRow {
  background: #141414 !important;
  border-top: 1px solid rgba(255,255,255,.08) !important;
  padding: 8px 12px 10px !important;
}
.sm-anno-noteRow .sm-anno-noteK {
  color: rgba(255,255,255,.30) !important;
  font-size: 9px !important;
  letter-spacing: .08em !important;
  text-transform: uppercase !important;
}
.sm-anno-noteRow .sm-anno-note {
  background: #0A0A0A !important;
  border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 4px !important;
  color: rgba(255,255,255,.75) !important;
}
.sm-anno-noteRow .sm-anno-note::placeholder { color: rgba(255,255,255,.22) !important; }

/* ── Brief overlay ────────────────────────────────────────────────────────────── */
.sm-anno-brief-overlay {
  background: rgba(0,0,0,.75) !important;
  backdrop-filter: blur(4px) !important;
}
.sm-anno-brief-head {
  background: #141414 !important;
  border-bottom: 1px solid rgba(255,255,255,.08) !important;
  color: rgba(255,255,255,.88) !important;
}

/* ── Scan beam — replace cyan with red ───────────────────────────────────────── */
.sm-anno-stage.is-ai-scanning::after {
  background: linear-gradient(
    180deg,
    transparent 0%,
    rgba(229,9,20,.06) 48%,
    rgba(229,9,20,.14) 50%,
    rgba(229,9,20,.06) 52%,
    transparent 100%
  ) !important;
}

/* ── Netflix Delivery Compliance Panel ──────────────────────────────────────── */
.imf-nx-panel {
  padding: 8px 12px 6px;
  border-bottom: 1px solid #1a1a2e;
  background: rgba(229,9,20,.04);
}
.imf-nx-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}
.imf-nx-label {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: rgba(229,9,20,.65);
}
.imf-nx-overall {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .06em;
  padding: 1px 6px;
  border-radius: 3px;
  margin-left: auto;
}
.imf-nx-overall-pass { background: rgba(10,163,86,.18); color: #0AA356; border: 1px solid rgba(10,163,86,.3); }
.imf-nx-overall-warn { background: rgba(247,162,106,.12); color: #f7a26a; border: 1px solid rgba(247,162,106,.25); }
.imf-nx-overall-fail { background: rgba(229,9,20,.14); color: #e55; border: 1px solid rgba(229,9,20,.3); }

.imf-nx-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.imf-nx-chip {
  font-size: 9px;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 3px;
  cursor: default;
  white-space: nowrap;
  line-height: 1.4;
  letter-spacing: .02em;
}
.imf-nx-chip-pass { background: rgba(10,163,86,.12); color: #0AA356; border: 1px solid rgba(10,163,86,.22); }
.imf-nx-chip-warn { background: rgba(247,162,106,.10); color: #f7a26a; border: 1px solid rgba(247,162,106,.20); }
.imf-nx-chip-fail { background: rgba(229,9,20,.12); color: #f55;    border: 1px solid rgba(229,9,20,.25); }

/* ── ADM Programme Tree Panel ───────────────────────────────────────────────── */
.imf-adm-tree-panel {
  padding: 8px 12px 6px;
  border-bottom: 1px solid #1a1a2e;
}
.imf-adm-tree-inner {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.imf-adm-prog {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 2px;
}
.imf-adm-prog-name {
  font-size: 9px;
  color: rgba(160,176,255,.7);
  background: rgba(124,106,247,.08);
  border: 1px solid rgba(124,106,247,.18);
  padding: 1px 6px;
  border-radius: 3px;
}
.imf-adm-bed {
  display: flex;
  align-items: center;
  gap: 6px;
}
.imf-adm-bed-label {
  font-size: 9px;
  font-weight: 700;
  color: #7c6af7;
  letter-spacing: .04em;
  min-width: 32px;
}
.imf-adm-channels {
  display: flex;
  gap: 3px;
  flex-wrap: wrap;
}
.imf-adm-ch {
  font-size: 9px;
  font-weight: 700;
  font-family: monospace;
  background: rgba(124,106,247,.14);
  color: #a0b0ff;
  border: 1px solid rgba(124,106,247,.25);
  padding: 1px 5px;
  border-radius: 3px;
  letter-spacing: .04em;
}
.imf-adm-objects {
  display: flex;
  align-items: center;
  gap: 6px;
}
.imf-adm-obj-badge {
  font-size: 9px;
  font-weight: 700;
  background: rgba(10,163,86,.12);
  color: #0AA356;
  border: 1px solid rgba(10,163,86,.22);
  padding: 1px 7px;
  border-radius: 3px;
}

/* ── HDR preview mode button — 3-state colors ───────────────────────────────── */
#imfBtnHdrSdr[data-preview-mode="full"] {
  background: rgba(247,162,106,.18) !important;
  color: #f7a26a !important;
  border-color: rgba(247,162,106,.35) !important;
}
/* HDR boost — same as 'full' internally */
#imfBtnHdrSdr[data-preview-mode="hdr"] {
  background: rgba(247,162,106,.18) !important;
  color: #f7a26a !important;
  border-color: rgba(247,162,106,.35) !important;
}
#imfBtnHdrSdr[data-preview-mode="trim"] {
  background: rgba(124,106,247,.18) !important;
  color: #7c6af7 !important;
  border-color: rgba(124,106,247,.35) !important;
}
#imfBtnHdrSdr[data-preview-mode="sdr"] {
  background: rgba(10,163,86,.12) !important;
  color: #0AA356 !important;
  border-color: rgba(10,163,86,.25) !important;
}

/* ── Proxy audio meter ──────────────────────────────────────────────────────── */
#imfProxyAudioMeter {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 44px;
  padding: 2px 4px;
  background: rgba(0,0,0,.3);
  border-radius: 3px;
  min-width: 60px;
}
.imf-meter-ch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  flex: 1;
}
.imf-meter-bar-wrap {
  width: 100%;
  height: 34px;
  background: rgba(255,255,255,.04);
  border-radius: 2px;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
}
.imf-meter-bar {
  width: 100%;
  border-radius: 2px 2px 0 0;
  transition: height .05s linear;
  min-height: 1px;
}
.imf-meter-ok   { background: #0AA356; }
.imf-meter-hot  { background: #f7c26a; }
.imf-meter-clip { background: #e55; }
.imf-meter-label {
  font-size: 6px;
  font-weight: 700;
  font-family: monospace;
  color: rgba(255,255,255,.35);
  letter-spacing: .04em;
}

/* ── Resolve Proxy Button ──────────────────────────────────────────────── */
.imf-btn-resolve {
  background: rgba(229,9,20,.15);
  border: 1px solid rgba(229,9,20,.4);
  color: rgba(229,9,20,.9);
  font-weight: 700;
}
.imf-btn-resolve:hover {
  background: rgba(229,9,20,.25);
  border-color: rgba(229,9,20,.65);
  color: #f55;
}
.imf-resolve-status {
  font-size: 9px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
  display: inline-block;
  margin-left: 4px;
  vertical-align: middle;
  letter-spacing: .04em;
}
.imf-resolve-status[data-state="connected"] {
  background: rgba(10,163,86,.12);
  color: #0AA356;
  border: 1px solid rgba(10,163,86,.25);
}
.imf-resolve-status[data-state="disconnected"] {
  background: rgba(255,255,255,.05);
  color: rgba(255,255,255,.35);
  border: 1px solid rgba(255,255,255,.1);
}
.imf-resolve-status[data-state="rendering"] {
  background: rgba(229,9,20,.12);
  color: rgba(229,9,20,.85);
  border: 1px solid rgba(229,9,20,.25);
  animation: imf-resolve-pulse 1.2s ease-in-out infinite;
}
@keyframes imf-resolve-pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.55; }
}


/* ── IMF Left Panel — compact + smart layout ─────────────────────────────── */
/* Reduces padding throughout the left column so more content fits without
   sacrificing readability. All overrides are scoped to #main-imf. */

/* Narrow the left column slightly */
#main-imf .imf-3col {
  grid-template-columns: clamp(300px, 22vw, 370px) minmax(0, 1fr);
}

/* Package Info toggle row */
#main-imf .imf-pkg-toggle { padding: 4px 10px; }

/* Tab bar — biggest savings: 10px → 5px top/bottom */
#main-imf .imf-left-tab { padding: 5px 10px; font-size: 9px; }
#main-imf .imf-left-tabs { padding: 0; }
#main-imf .imf-left-tab-actions { padding-top: 5px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; gap: 4px; }

/* Action buttons — tighter pill */
#main-imf .imf-action-btn { padding: 3px 9px; font-size: 9.5px; border-radius: 5px; }

/* Action strip wrapper */
#main-imf .imf-action-strip { padding: 5px 10px; gap: 5px; }

/* Netflix Check panel */
#main-imf .imf-nx-panel { padding: 5px 10px 4px; }
#main-imf .imf-nx-header { margin-bottom: 4px; }
#main-imf .imf-nx-chips { gap: 3px; }
#main-imf .imf-nx-chip { font-size: 8.5px; padding: 1px 5px; }
#main-imf .imf-nx-label { font-size: 8px; }
#main-imf .imf-nx-overall { font-size: 8.5px; padding: 1px 5px; }

/* ADM tree panel */
#main-imf .imf-adm-tree-panel { padding: 4px 10px 3px; }
#main-imf .imf-adm-tree-inner { gap: 3px; }
#main-imf .imf-adm-prog { gap: 3px; margin-bottom: 0; }
#main-imf .imf-adm-prog-name { font-size: 8.5px; padding: 1px 5px; }
#main-imf .imf-adm-bed { gap: 4px; }
#main-imf .imf-adm-bed-label { font-size: 8.5px; min-width: 24px; }
#main-imf .imf-adm-channels { gap: 2px; }
#main-imf .imf-adm-ch { font-size: 8px; padding: 1px 4px; }
#main-imf .imf-adm-obj-badge { font-size: 8.5px; padding: 1px 5px; }

/* Track detail: head pills */
#main-imf .imf-pro-head { padding: 4px 8px 3px; }
#main-imf .imf-pro-pill { font-size: 7.5px; padding: 1px 5px; }

/* TC hero — slightly smaller, less vertical breathing room */
#main-imf .imf-pro-tc { padding: 5px 8px 4px; }
#main-imf .imf-pro-tc-range { font-size: 12px; }
#main-imf .imf-pro-tc-meta { font-size: 8.5px; margin-top: 2px; gap: 4px; }

/* Section label dividers */
#main-imf .imf-pro-sec-lbl { padding: 3px 8px 0; font-size: 6px; }

/* Color science chips */
#main-imf .imf-pro-color-row { padding: 3px 8px 3px; gap: 4px; }
#main-imf .imf-pro-transfer { font-size: 9px; padding: 1px 7px; }
#main-imf .imf-pro-primaries { font-size: 8.5px; padding: 1px 6px; }

/* Essence / metadata grid */
#main-imf .imf-pro-row4,
#main-imf .imf-pro-essence-grid { padding: 4px 8px; gap: 2px 6px; }
#main-imf .imf-pro-k { font-size: 6.5px; }
#main-imf .imf-pro-v { font-size: 9px; }
#main-imf .imf-pro-cell { gap: 1px; }

/* DV section */
#main-imf .imf-pro-dv { border-radius: 5px; margin: 3px 8px; }
#main-imf .imf-pro-dv-meta { padding: 4px 8px; gap: 3px; }
#main-imf .imf-pro-dv-k { font-size: 7px; min-width: 90px; }
#main-imf .imf-pro-dv-v { font-size: 9px; }

/* Audio spec row */
#main-imf .imf-pro-row4 { padding: 4px 8px; }

/* Reel / asset list rows */
#main-imf .imf-rt td { padding: 3px 6px; font-size: 9px; }
#main-imf .imf-rt th { padding: 3px 6px; }

/* KPI rows (package info accordion) */
#main-imf .imf-kpi-row { padding: 2px 10px; font-size: 10px; }
#main-imf .imf-kpi-key { font-size: 9px; flex: 0 0 82px; }
#main-imf .imf-kpi-val { font-size: 10px; }

/* Side sections (video file list, asset entries) */
#main-imf .imf-side-section-hdr { padding: 2px 6px; }
#main-imf .imf-asset-row { padding: 3px 8px; font-size: 9px; }

/* Detail rows (IAB/proxy info panels) */
#main-imf .imf-detail-row { padding: 2px 0; font-size: 9px; }
#main-imf .imf-track-detail { padding: 0; }

/* Proxy meta rows */
#main-imf .imf-proxy-meta-row { padding: 2px 0; font-size: 9px; }
#main-imf .imf-proxy-meta { gap: 1px; }
#main-imf .imf-proxy-panel-note { font-size: 8.5px; padding: 4px 0; line-height: 1.4; }

/* ── Action button row — uniform size ────────────────────────────────────── */
/* All action buttons in the TRANSCODE strip must be the same height.
   white-space:nowrap prevents "Resolve Proxy" from wrapping to 2 lines. */
#main-imf .imf-left-tab-actions .imf-action-btn {
  white-space: nowrap;
  height: 26px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 9px;
  font-size: 9.5px;
  box-sizing: border-box;
}

/* ══════════════════════════════════════════════════════════════════════════
   IMF TIMELINE — Smart · Professional · Functional
   Redesigns row hierarchy, label depth, segment detail, and ruler clarity.
   All rules are #main-imf scoped and use !important only where overriding
   prior compact-panel rules that already use !important.
   ══════════════════════════════════════════════════════════════════════════ */

/* ── Section shell ───────────────────────────────────────────────────────── */
#main-imf .imf-tl-section {
  border-top: 1px solid rgba(255,255,255,.06) !important;
  background: #080810 !important;
}

