  padding: 4px 10px !important;
  background: rgba(8,8,16,.98) !important;
  border-bottom: 1px solid rgba(255,255,255,.06) !important;
}
#main-imf .imf-tl-hdr-label {
  font-size: 8px !important; font-weight: 900; letter-spacing: .18em;
  color: rgba(255,255,255,.45) !important;
  background: rgba(255,255,255,.06) !important;
  border: 1px solid rgba(255,255,255,.10) !important;
  padding: 1px 6px !important;
}

/* Row toggle chips — sized to match the header */
#main-imf .imf-tl-row-filters { gap: 2px !important; }
#main-imf .imf-tl-rf {
  font-size: 7.5px !important; font-weight: 800; letter-spacing: .07em;
  padding: 2px 6px !important; height: auto !important; line-height: 1.4 !important;
  border-radius: 3px !important;
}

/* ── Body layout ─────────────────────────────────────────────────────────── */
#main-imf .imf-tl-body {
  padding: 4px 10px 6px !important;
  gap: 2px !important;
  background: #080810 !important;
}

/* ── Ruler ───────────────────────────────────────────────────────────────── */
#main-imf .imf-tl-ruler {
  flex: 0 0 18px !important; height: 18px !important;
  background: rgba(5,5,12,.98) !important;
  border-bottom: 1px solid rgba(124,106,247,.2) !important;
  margin-left: 50px !important;
}
#main-imf .imf-tl-tick        { font-size: 8px !important; color: rgba(160,170,200,.55) !important; }
#main-imf .imf-tl-tick-reel   { color: rgba(229,9,20,.75) !important; border-left-color: rgba(229,9,20,.4) !important; font-weight: 800 !important; }

/* ── Playhead — 2px, high-contrast red head ─────────────────────────────── */
#main-imf .imf-tl-playhead {
