  background: linear-gradient(180deg, rgba(255,255,255,.95) 0%, rgba(229,9,20,.7) 100%) !important;
}
#main-imf .imf-tl-playhead::before {
  background: #E50914 !important;
  box-shadow: 0 0 0 1.5px rgba(255,255,255,.9), 0 0 10px rgba(229,9,20,.6) !important;
