}

/* ── Row label column ────────────────────────────────────────────────────── */
#main-imf .imf-tl-label {
  flex-basis: 50px !important; min-width: 50px !important;
  font-size: 8px !important; font-weight: 900 !important; letter-spacing: .1em !important;
  color: rgba(255,255,255,.28) !important; text-align: right !important;
  padding-right: 8px !important;
  display: flex !important; align-items: center !important; justify-content: flex-end;
  border-right: 2px solid transparent;   /* color-coded per-row below */
