/* Per-row label accent border */
#imfTLVideo  .imf-tl-label  { border-right-color: rgba(100,140,255,.55) !important; color: rgba(100,140,255,.8)  !important; }
#imfTLAudio  .imf-tl-label  { border-right-color: rgba(70,211,105,.45)  !important; color: rgba(70,211,105,.7)   !important; }
#imfTLDV     .imf-tl-label  { border-right-color: rgba(229,160,64,.5)   !important; color: rgba(229,160,64,.75)  !important; }
#imfTLTrim   .imf-tl-label  { border-right-color: rgba(94,200,152,.45)  !important; color: rgba(94,200,152,.70)  !important; }
#imfTLDoviShots .imf-tl-label { border-right-color: rgba(152,136,240,.45) !important; color: rgba(152,136,240,.70) !important; }

/* ── Row heights — VIDEO/IAB dominant, metadata rows thin ────────────────── */
#main-imf .imf-tl-row         { height: auto !important; flex: 1 1 0 !important; min-height: 14px !important; }

/* Metadata rows: thin but still usable */
#main-imf .imf-tl-row-dv,
#main-imf .imf-tl-row-trim    { flex: 0.6 1 0 !important; min-height: 12px !important; }
#imfTLDoviShots                { flex: 0.85 1 0 !important; min-height: 14px !important; }

/* Primary content rows: 3× taller than metadata */
#main-imf .imf-tl-row-video   { flex: 3 1 0 !important; min-height: 26px !important; }
#main-imf .imf-tl-row-iab     { flex: 1.5 1 0 !important; min-height: 18px !important; }

/* ── Track backgrounds — depth + type colour ─────────────────────────────── */
#main-imf .imf-tl-track {
  height: auto !important; align-self: stretch !important;
  border-radius: 4px !important;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.04) !important;
}
#imfTLVideo  .imf-tl-track {
  background: rgba(14,18,42,.9) !important;
  box-shadow: inset 0 0 0 1px rgba(100,140,255,.08) !important;
}
#imfTLAudio  .imf-tl-track {
  background: rgba(8,28,20,.9) !important;
  box-shadow: inset 0 0 0 1px rgba(70,211,105,.07) !important;
}
#imfTLDV     .imf-tl-track,
#imfTLTrim   .imf-tl-track,
#imfTLDoviShots .imf-tl-track {
  background: rgba(10,10,20,.6) !important;
  border-radius: 3px !important;
}

/* ── VIDEO segments — rich gradient with highlight edge ─────────────────── */
#imfTLVideo .imf-tl-seg {
  background: linear-gradient(180deg,
    rgba(90,115,240,.85) 0%,
    rgba(68,92,218,.80) 35%,
    rgba(55,78,200,.72) 100%) !important;
  border-top: 1px solid rgba(140,165,255,.35) !important;
  border-radius: 4px !important;
  box-shadow: inset 0 1px 0 rgba(180,200,255,.12) !important;
}
#imfTLVideo .imf-tl-seg:hover {
  filter: brightness(1.18) !important;
  box-shadow: inset 0 1px 0 rgba(180,200,255,.20), 0 0 0 1px rgba(140,170,255,.4) !important;
}
/* Reel label — larger, bolder number */
#imfTLVideo .imf-tl-reel-label {
  font-size: 11px !important; font-weight: 900 !important;
  color: rgba(255,255,255,.9) !important;
  text-shadow: 0 1px 3px rgba(0,0,0,.7) !important;
  letter-spacing: -.01em !important;
}

/* ── IAB audio segment — translucent teal ────────────────────────────────── */
#imfTLAudio .imf-tl-seg-audio {
  background: linear-gradient(180deg,
    rgba(70,211,105,.55) 0%,
    rgba(50,170,82,.48) 50%,
    rgba(38,140,68,.42) 100%) !important;
  border-top: 1px solid rgba(100,220,130,.3) !important;
  border-radius: 4px !important;
}

/* ── DV / TRIM / CUTS segments — existing colours, slightly refined ──────── */
#imfTLDV .imf-tl-seg-dv {
  background: linear-gradient(90deg, rgba(180,90,0,.92), rgba(230,150,20,.88)) !important;
  border-radius: 3px !important;
}
#imfTLTrim .imf-tl-seg-trim {
  background: linear-gradient(90deg, rgba(20,100,60,.92), rgba(80,185,120,.88)) !important;
  border-radius: 3px !important;
}

/* ── Hover cursor tooltip ────────────────────────────────────────────────── */
#main-imf .imf-tl-hover-cursor {
  background: rgba(6,6,18,.95) !important;
  border-color: rgba(229,9,20,.4) !important;
  color: rgba(255,210,210,.95) !important;
  font-size: 10px !important; font-weight: 700 !important;
  padding: 2px 8px !important; border-radius: 4px !important;
  box-shadow: 0 3px 12px rgba(0,0,0,.6) !important;
}

/* ── Empty state note ────────────────────────────────────────────────────── */
#main-imf .imf-tl-empty-note {
  color: rgba(255,255,255,.15) !important;
  font-size: 8px !important; letter-spacing: .06em;
}

/* ── Trim-pass cut marker (yellow tick) ──────────────────────────────────── */
#imfTLTrim .imf-tl-trim-cut {
  width: 1px !important;
  background: rgba(255,220,60,.8) !important;
  box-shadow: 0 0 3px rgba(255,220,60,.4) !important;
}

/* ── CUTS / DV shots row — taller inner track, visible segments ──────────── */
#imfTLDoviShots .imf-tl-track { border-radius: 4px !important; }
#imfTLDoviShots .imf-tl-dv-shot-seg { border-radius: 2px !important; opacity: .88 !important; }
#imfTLDoviShots .imf-tl-dv-shot-seg:hover { opacity: 1 !important; outline: 1px solid rgba(255,255,255,.5) !important; }

/* ── Base (reference) row ────────────────────────────────────────────────── */
#main-imf .imf-tl-row-base    { flex: 0.8 1 0 !important; min-height: 14px !important; }
#main-imf .imf-tl-label-base  { color: rgba(200,200,255,.5) !important; border-right-color: rgba(200,200,255,.3) !important; }

/* ══════════════════════════════════════════════════════════════════════════
   DVS Clipster-style DV / TRIM timeline visualization
   ══════════════════════════════════════════════════════════════════════════ */

/* ── DV row: L1 luminance waveform container ─────────────────────────────── */
#imfTLDV .imf-tl-track {
  /* overflow visible so bars can fill bottom-up without clipping */
  overflow: hidden;
  position: relative;
  /* Subtle horizontal scan-line grid — evokes a scope graticule */
  background-image:
    repeating-linear-gradient(
      0deg,
      rgba(255,255,255,.025) 0px, rgba(255,255,255,.025) 1px,
      transparent 1px, transparent 25%
    ),
    linear-gradient(180deg, rgba(14,18,42,.8), rgba(8,10,24,.9));
  border: 1px solid rgba(100,140,255,.1) !important;
}

/* L1 nits bar — bottom-anchored luminance columns */
.imf-tl-dv-l1-bar {
  position: absolute;
  bottom: 0;
  min-width: 1px;
  border-radius: 1px 1px 0 0;
  cursor: pointer;
  transition: filter .1s, outline .1s;
  /* Top edge highlight — looks like the peak of the waveform */
  border-top: 1px solid rgba(255,255,255,.25);
}
.imf-tl-dv-l1-bar:hover  {
  filter: brightness(1.4);
  outline: 1px solid rgba(255,255,255,.55);
  z-index: 2;
}
.imf-tl-dv-l1-bar-conflict { outline: 1px solid rgba(255,60,60,.7) !important; }
.imf-tl-dv-l1-bar-fade     { opacity: .65; }

/* Shot boundary separators in DV row */
.imf-tl-dv-shot-sep {
  position: absolute; top: 0; bottom: 0; width: 1px;
  background: rgba(255,255,255,.12);
  pointer-events: none; z-index: 3;
}

/* ── TRIM row: grade deviation bars ──────────────────────────────────────── */
#imfTLTrim .imf-tl-track {
  background-image:
    linear-gradient(180deg, rgba(10,30,20,.9), rgba(6,18,12,.9));
  border: 1px solid rgba(70,200,130,.08) !important;
}
/* SDR target-27 shot highlight */
.imf-tl-trim-t27 {
  border-top: 1px solid rgba(255,220,80,.55) !important;
}

/* ── Trim-grade-change diamond marker (Clipster-style) ───────────────────── */
.imf-tl-trim-cut-pro {
  position: absolute;
  top: 0; bottom: 0;
  width: 2px;
  background: hsla(var(--cut-hue, 40), 90%, 55%, var(--cut-alpha, .8));
  box-shadow: 0 0 5px hsla(var(--cut-hue, 40), 90%, 55%, .45);
  pointer-events: auto;
  cursor: default;
  z-index: 5;
  transform: translateX(-1px);
}
/* Diamond head at the top of the marker */
.imf-tl-trim-cut-pro::before {
  content: '';
  position: absolute;
  top: -4px;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 6px; height: 6px;
  background: hsla(var(--cut-hue, 40), 90%, 65%, var(--cut-alpha, .9));
  box-shadow: 0 0 4px hsla(var(--cut-hue, 40), 90%, 55%, .6);
}
/* Bottom notch */
.imf-tl-trim-cut-pro::after {
  content: '';
  position: absolute;
  bottom: -3px;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 5px; height: 5px;
  background: hsla(var(--cut-hue, 40), 80%, 55%, .6);
}
.imf-tl-trim-cut-pro:hover {
  box-shadow: 0 0 8px hsla(var(--cut-hue, 40), 90%, 60%, .75);
  filter: brightness(1.3);
}

/* ── CUTS row improvements ───────────────────────────────────────────────── */
#imfTLDoviShots .imf-tl-track {
  background-image: linear-gradient(180deg, rgba(10,8,28,.9), rgba(6,5,18,.9));
  border: 1px solid rgba(152,136,240,.08) !important;
}
/* Shot segments in cuts row — refined */
#imfTLDoviShots .imf-tl-seg-dv-shot {
  background: linear-gradient(180deg, rgba(140,120,255,.42) 0%, rgba(100,85,220,.36) 100%) !important;
  border-top: 1px solid rgba(160,145,255,.28) !important;
}
#imfTLDoviShots .imf-tl-seg-dv-shot-black {
  background: rgba(12,10,25,.8) !important;
  border-top: 1px solid rgba(50,45,80,.5) !important;
}
/* L1 nits label overlaid on wider shots */
.imf-tl-dv-nits-label {
  position: absolute; top: 50%; transform: translateY(-50%);
  font-size: 7.5px; font-weight: 800; font-family: monospace;
  color: rgba(200,210,255,.8);
  letter-spacing: .03em;
  pointer-events: none;
  padding: 0 3px;
  white-space: nowrap;
  text-shadow: 0 0 4px rgba(0,0,0,.9);
}

/* ── Scope DV row luminance bars away from CUTS row mini bars ──────────────
   The generic .imf-tl-dv-l1-bar (line ~37932) is the CUTS-row mini bar
   (3px right-edge indicator). Our new bars in #imfTLDV are full-height
   bottom-anchored columns — scope them explicitly. */
#imfTLDV .imf-tl-dv-l1-bar {
  position: absolute !important;
  bottom: 0 !important;
  right: unset !important;
  width: auto !important;   /* width set inline per-shot */
  pointer-events: auto !important;
  min-height: 4% !important;
  border-radius: 1px 1px 0 0 !important;
  border-top: 1px solid rgba(255,255,255,.25) !important;
  cursor: pointer !important;
}
/* Override the compact-panel 2px width rule that would crush the waveform bars */
#imfTLDV .imf-tl-track .imf-tl-dv-l1-bar { width: unset !important; }

/* Keep CUTS row mini bars as-is (right-edge 2-3px indicator) */
#imfTLDoviShots .imf-tl-dv-l1-bar { width: 3px !important; right: 0 !important; pointer-events: none !important; }

/* ══════════════════════════════════════════════════════════════════════════
   DV Trim-Cut Markers v2 — visible, severity-scaled, labeled
   ══════════════════════════════════════════════════════════════════════════ */

/* The TRIM track must NOT clip content so diamonds extend outside track bounds */
#imfTLTrim               { overflow: visible !important; }
#imfTLTrim .imf-tl-track { overflow: visible !important; }

/* ── Base marker ─────────────────────────────────────────────────────────── */
.imf-tl-trim-cut-pro {
  position: absolute;
  /* Extend 8px above and below the track so the diamond is always visible */
  top: -8px; bottom: -8px;
  width: 3px;
  background: hsla(var(--cut-hue,40), 85%, 55%, var(--cut-alpha,.85));
  box-shadow:
    0 0 0 1px hsla(var(--cut-hue,40), 85%, 40%, .25),
    0 0  6px  hsla(var(--cut-hue,40), 90%, 60%, .40);
  pointer-events: auto;
  cursor: default;
  z-index: 10;
  transform: translateX(-1px);
}

/* ── Diamond head — 14×14px, always outside the track ───────────────────── */
.imf-tl-trim-cut-pro::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 10px; height: 10px;
  background: hsla(var(--cut-hue,40), 90%, 65%, var(--cut-alpha,.95));
  box-shadow:
    0 0 0 1px hsla(var(--cut-hue,40), 80%, 80%, .4),
    0 0  8px  hsla(var(--cut-hue,40), 90%, 55%, .7);
}
/* Bottom notch */
.imf-tl-trim-cut-pro::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 8px; height: 8px;
  background: hsla(var(--cut-hue,40), 80%, 58%, .8);
  box-shadow: 0 0 5px hsla(var(--cut-hue,40), 90%, 55%, .5);
}

/* ── Severity tiers ──────────────────────────────────────────────────────── */
.imf-tl-trim-cut-subtle  { width: 2px; }
.imf-tl-trim-cut-notable { width: 3px; }
.imf-tl-trim-cut-major   {
  width: 4px;
  box-shadow:
    0 0 0 1px hsla(var(--cut-hue,12), 85%, 40%, .35),
    0 0 10px  hsla(var(--cut-hue,12), 90%, 55%, .65),
    0 0 20px  hsla(var(--cut-hue,12), 90%, 55%, .25);
}
.imf-tl-trim-cut-subtle::before  { width: 7px; height: 7px; }
.imf-tl-trim-cut-notable::before { width: 10px; height: 10px; }
.imf-tl-trim-cut-major::before   { width: 13px; height: 13px; }
.imf-tl-trim-cut-subtle::after   { width: 5px; height: 5px; }
.imf-tl-trim-cut-notable::after  { width: 7px; height: 7px; }
.imf-tl-trim-cut-major::after    { width: 10px; height: 10px; }

/* ── Delta label badge ───────────────────────────────────────────────────── */
.imf-tl-trim-cut-badge {
  position: absolute;
  top: -19px;           /* floats above the diamond */
  left: 50%;
  transform: translateX(-50%);
  font-size: 7px; font-weight: 900; font-family: monospace;
  letter-spacing: .02em; white-space: nowrap;
  padding: 1px 4px; border-radius: 2px;
  color: hsla(var(--cut-hue,40), 90%, 80%, 1);
  background: hsla(var(--cut-hue,40), 70%, 12%, .92);
  border: 1px solid hsla(var(--cut-hue,40), 80%, 45%, .55);
  box-shadow: 0 1px 4px rgba(0,0,0,.7);
  pointer-events: none;
  /* subtle ones hidden by default, shown on hover */
  opacity: 0; transition: opacity .12s;
}
/* notable and major badges always visible */
.imf-tl-trim-cut-badge-notable,
.imf-tl-trim-cut-badge-major   { opacity: 1 !important; }

/* Show subtle badge on hover */
.imf-tl-trim-cut-pro:hover .imf-tl-trim-cut-badge { opacity: 1; }

/* ── Hover glow ──────────────────────────────────────────────────────────── */
.imf-tl-trim-cut-pro:hover {
  filter: brightness(1.35);
  box-shadow:
    0 0 0 1px hsla(var(--cut-hue,40), 85%, 60%, .5),
    0 0 12px  hsla(var(--cut-hue,40), 90%, 60%, .7);
}

/* ══════════════════════════════════════════════════════════════════════════
   DV / TRIM / CUTS row text — readable at any zoom
   ══════════════════════════════════════════════════════════════════════════ */

/* Row labels: DV · TRIM · CUTS — larger, saturated, always legible */
#imfTLDV       .imf-tl-label,
#imfTLTrim     .imf-tl-label,
#imfTLDoviShots .imf-tl-label {
  font-size: 9px !important;
  font-weight: 900 !important;
  letter-spacing: .10em !important;
  line-height: 1.1 !important;
}
#imfTLDV        .imf-tl-label { color: #f0a84a !important; }
#imfTLTrim      .imf-tl-label { color: #6ed4a8 !important; }
#imfTLDoviShots .imf-tl-label { color: #a89af5 !important; }

/* DV profile badge ("P8 L8") — visible amber */
#main-imf .imf-tl-dv-badge {
  font-size: 8px !important; font-weight: 700 !important;
  color: rgba(240,168,74,.90) !important;
  letter-spacing: .04em !important;
}

/* Shot count under DV label */
#main-imf .imf-tl-dv-shot-count {
  font-size: 9px !important; font-weight: 800 !important;
  color: rgba(168,154,245,.90) !important;
}

/* Empty-state notes: "No DV data" / "No trim metadata" / "No cut metadata"
   These were 6.5px at 20% opacity — completely invisible in practice.       */
#main-imf .imf-tl-empty-note {
  font-size: 9px !important;
  font-weight: 600 !important;
  color: rgba(255,255,255,.38) !important;
  letter-spacing: .05em !important;
}

/* Shot meta label inside CUTS segments: "#1 · T2 · 450n" */
#main-imf .imf-tl-shot-meta-label {
  font-size: 8px !important;
  font-weight: 700 !important;
  color: rgba(255,255,255,.85) !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  text-shadow: 0 1px 2px rgba(0,0,0,.8) !important;
}

/* Trim-cut-pro delta badge ("G+8%") — already positioned, just ensure legible */
.imf-tl-trim-cut-badge {
  font-size: 7.5px !important;
  font-weight: 900 !important;
  letter-spacing: .03em !important;
}

/* ── Extract DoVi button in timeline header ─────────────────────────────── */
.imf-tl-dovi-extract-btn {
  font-size: 8px; font-weight: 800; letter-spacing: .06em;
  padding: 2px 8px; border-radius: 3px; cursor: pointer;
  background: rgba(229,160,64,.14); border: 1px solid rgba(229,160,64,.4);
  color: rgba(229,160,64,.9); white-space: nowrap;
  transition: background .12s, border-color .12s;
}
.imf-tl-dovi-extract-btn:hover:not(:disabled) {
  background: rgba(229,160,64,.25); border-color: rgba(229,160,64,.7);
}
.imf-tl-dovi-extract-btn:disabled { opacity: .45; cursor: default; }

/* Status chip next to extract button */
.imf-tl-dovi-extract-status {
  font-size: 8px; font-weight: 700; padding: 1px 6px; border-radius: 3px;
  white-space: nowrap;
}
.imf-tl-dovi-extract-status[data-state="running"] {
  background: rgba(229,160,64,.12); color: rgba(229,160,64,.9);
  border: 1px solid rgba(229,160,64,.25);
}
.imf-tl-dovi-extract-status[data-state="ok"] {
  background: rgba(10,163,86,.12); color: #0AA356;
  border: 1px solid rgba(10,163,86,.25);
}
.imf-tl-dovi-extract-status[data-state="warn"] {
  background: rgba(247,194,106,.10); color: #f7a26a;
  border: 1px solid rgba(247,194,106,.22);
}
.imf-tl-dovi-extract-status[data-state="error"] {
  background: rgba(229,9,20,.12); color: #f55;
  border: 1px solid rgba(229,9,20,.25);
}

/* ── DoVi extraction debug + Metafier config panel ─────────────────────────── */
.imf-dovi-debug-summary {
  font-size: 8.5px; font-weight: 700; color: rgba(255,255,255,.35);
  cursor: pointer; padding: 3px 6px; letter-spacing: .04em;
  list-style: none;
}
.imf-dovi-debug-summary:hover { color: rgba(255,255,255,.6); }
.imf-dovi-debug-log {
  font-size: 8px; font-family: monospace; color: rgba(255,255,255,.5);
  padding: 4px 8px; white-space: pre-wrap; word-break: break-all;
  max-height: 80px; overflow-y: auto; line-height: 1.5;
  background: rgba(0,0,0,.3); border-radius: 3px; margin: 2px 0;
}
.imf-dovi-config-label {
  font-size: 8px; font-weight: 700; color: rgba(255,255,255,.35);
  text-transform: uppercase; letter-spacing: .08em; padding: 4px 0 2px;
}
.imf-dovi-config-input {
  width: 100%; font-size: 9px; font-family: monospace;
  background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.12);
  color: rgba(255,255,255,.8); padding: 3px 7px; border-radius: 3px;
  box-sizing: border-box;
}
.imf-dovi-config-input:focus {
  outline: none; border-color: rgba(229,160,64,.4);
  background: rgba(229,160,64,.05);
}
.imf-dovi-config-result {
  font-size: 8.5px; font-weight: 600; padding: 2px 0; margin-top: 2px;
  min-height: 14px;
}

/* ══════════════════════════════════════════════════════════════════════════
   VFX PULL WORKSPACE — hard layout branch shown instead of .pm-body
   when _pmLocalQs.vfxmarker is active
   ══════════════════════════════════════════════════════════════════════ */

/* When VFX workspace is active, collapse grid to 3 rows (ctx-bar, qs-row, workspace)
   and hide the normal body + timeline strip */
#main-prepmark.pm-vfx-workspace-on {
  grid-template-rows: auto auto minmax(0, 1fr) !important;
}
#main-prepmark.pm-vfx-workspace-on .pm-body,
#main-prepmark.pm-vfx-workspace-on .pm-timeline-strip,
#main-prepmark.pm-vfx-workspace-on #pmSimpleLayout {
  display: none !important;
}
#main-prepmark.pm-vfx-workspace-on #pmVfxWorkspace {
  display: flex !important;
}

#pmVfxWorkspace {
  display: flex;
  flex-direction: column;
  flex: 1 1 0;
  min-height: 0;
  overflow: hidden;
  background: #0d0d14;
  font-family: inherit;
}

/* ── Top bar ── */
.pfx-vfx-ws-topbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 14px;
  background: #111118;
  border-bottom: 1px solid #1e1e2e;
  flex-shrink: 0;
}
.pfx-vfx-ws-title {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #0AA356;
  text-transform: uppercase;
}

/* PULL READY panel */
.pfx-vfx-pull-ready {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.pfx-vfx-pr-label {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: #a0a0c0;
  text-transform: uppercase;
}
.pfx-vfx-pr-chip {
  font-size: 9px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 3px;
  letter-spacing: 0.06em;
}
.pfx-vfx-pr-chip-ok   { background: rgba(10,163,86,.18); color: #0AA356; border: 1px solid rgba(10,163,86,.3); }
.pfx-vfx-pr-chip-warn { background: rgba(224,179,65,.13);  color: #E0B341; border: 1px solid rgba(224,179,65,.25); }
.pfx-vfx-pr-chip-err  { background: rgba(229,72,77,.13);   color: #E5484D; border: 1px solid rgba(229,72,77,.25); }
.pfx-vfx-pr-export-btn {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  padding: 4px 12px;
