  background: rgba(100,140,255,.25);
  border-color: #8aadff;
  color: #c5d8ff;
}

/* ═══════════════════════════════════════════════════════════════════════════
   Smart VFX Pull Settings Panel
═══════════════════════════════════════════════════════════════════════════ */

.pfx-vfxs-panel {
  position: relative; z-index: 1;
  width: min(780px, 96vw);
  max-height: 88vh;
  background: linear-gradient(160deg, #0d0d20 0%, #08080f 100%);
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 14px;
  box-shadow: 0 32px 80px rgba(0,0,0,0.75), 0 0 0 1px rgba(255,255,255,0.04);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ── Header ── */
.pfx-vfxs-header {
  display: flex;
  align-items: flex-start;
  padding: 20px 22px 0;
  flex-shrink: 0;
}
.pfx-vfxs-title-block { flex: 1; }
.pfx-vfxs-title {
  display: block;
  font-size: 14px;
  font-weight: 700;
  color: #d0d8ff;
  letter-spacing: 0.04em;
}
.pfx-vfxs-subtitle {
  display: block;
  font-size: 10px;
  color: #6070a0;
  margin-top: 2px;
}

/* ── Tabs ── */
.pfx-vfxs-tabs {
  display: flex;
  gap: 2px;
  padding: 14px 22px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
}
.pfx-vfxs-tab {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 5px 16px 8px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: #5060a0;
  cursor: pointer;
  text-transform: uppercase;
  transition: color 0.15s, border-color 0.15s;
  margin-bottom: -1px;
}
.pfx-vfxs-tab:hover { color: #a0b0e0; }
.pfx-vfxs-tab.active {
  color: #8aadff;
  border-bottom-color: #5080e0;
}

/* ── Body ── */
.pfx-vfxs-body {
  /* flex-basis MUST be auto, not 0: the panel has no definite height (only
     max-height:88vh), so a basis-0 body has no free space to grow into and
     collapses to ~one line while its content scrolls away. `auto` sizes the
     body to its content (panel grows to fit, up to 88vh, then this scrolls). */
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 18px 22px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.1) transparent;
}
.pfx-vfxs-body::-webkit-scrollbar { width: 5px; }
.pfx-vfxs-body::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 3px; }

/* ── Sections ── */
.pfx-vfxs-section {
  margin-bottom: 20px;
  padding-bottom: 20px;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.pfx-vfxs-section:last-child { border-bottom: none; margin-bottom: 0; }
.pfx-vfxs-section-title {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: #5060a0;
  text-transform: uppercase;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 7px;
}
.pfx-vfxs-section-sub {
  font-weight: 500;
  text-transform: none;
  letter-spacing: 0;
  font-size: 9px;
  color: #405070;
}

/* ── Layout rows ── */
.pfx-vfxs-row {
  display: flex;
  align-items: flex-end;
  gap: 14px;
}
.pfx-vfxs-row-wrap { flex-wrap: wrap; }
.pfx-vfxs-row-nowrap { flex-wrap: nowrap; }
.pfx-vfxs-field-group {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.pfx-vfxs-field-label {
  font-size: 9px;
  font-weight: 600;
  color: #5a7090;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* ── Preset grid ── */
.pfx-vfxs-preset-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 7px;
}
.pfx-vfxs-preset-btn {
  background: rgba(255,255,255,0.03);
  border: 1.5px solid rgba(255,255,255,0.08);
  border-radius: 7px;
  padding: 10px 13px;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.pfx-vfxs-preset-btn:hover {
  background: rgba(255,255,255,0.07);
  border-color: rgba(255,255,255,0.15);
}
.pfx-vfxs-preset-btn.active {
  background: rgba(100,140,255,0.1);
  border-color: rgba(100,140,255,0.45);
}
.pfx-vfxs-preset-label {
  display: block;
  font-size: 10px;
  font-weight: 700;
  color: #c5d0f0;
}
.pfx-vfxs-preset-desc {
  display: block;
  font-size: 9px;
  color: #5a7090;
  margin-top: 2px;
}
.pfx-vfxs-preset-btn.active .pfx-vfxs-preset-label { color: #a8c4ff; }

/* ── Chip rows (format / framing selectors) ── */
.pfx-vfxs-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
.pfx-vfxs-chip {
  font-size: 9px;
  font-weight: 700;
  padding: 4px 11px;
  border-radius: 4px;
  border: 1.5px solid rgba(255,255,255,0.1);
  background: rgba(255,255,255,0.04);
  color: #7080b0;
  cursor: pointer;
  transition: all 0.12s;
}
.pfx-vfxs-chip:hover { border-color: rgba(255,255,255,0.2); color: #b0c0e0; }
.pfx-vfxs-chip.active {
  background: rgba(100,140,255,0.15);
  border-color: rgba(100,140,255,0.5);
  color: #a0c0ff;
}

/* ── Inputs ── */
.pfx-vfxs-input {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 5px;
  color: #c0d0f0;
  font-size: 11px;
  padding: 5px 9px;
  outline: none;
  transition: border-color 0.15s;
}
.pfx-vfxs-input:focus { border-color: rgba(100,140,255,0.5); }
.pfx-vfxs-input-sm  { width: 80px; }
.pfx-vfxs-input-wide { flex: 1; min-width: 0; }
.pfx-vfxs-select {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 5px;
  color: #c0d0f0;
  font-size: 10px;
  padding: 5px 8px;
  outline: none;
  cursor: pointer;
}
.pfx-vfxs-select-wide { width: 100%; }
.pfx-vfxs-val-static {
  font-size: 10px;
  color: #7080b0;
  padding: 5px 0;
  font-style: italic;
}
.pfx-vfxs-textarea {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 5px;
  color: #b0c0e0;
  font-size: 10px;
  font-family: monospace;
  padding: 6px 8px;
  resize: vertical;
  outline: none;
  width: 100%;
  box-sizing: border-box;
}
.pfx-vfxs-textarea:focus { border-color: rgba(100,140,255,0.4); }

/* ── Naming ── */
.pfx-vfxs-token-hints {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 6px;
}
.pfx-vfxs-token-label {
  font-size: 9px;
  color: #405070;
  margin-right: 2px;
}
.pfx-vfxs-token {
  font-family: monospace;
  font-size: 9px;
  padding: 2px 6px;
  background: rgba(100,140,255,0.1);
  border: 1px solid rgba(100,140,255,0.25);
  border-radius: 3px;
  color: #7090d0;
  cursor: pointer;
  user-select: none;
  transition: background 0.12s;
}
.pfx-vfxs-token:hover { background: rgba(100,140,255,0.22); color: #a0c0ff; }
.pfx-vfxs-name-preview {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: 8px;
}
.pfx-vfxs-name-sample {
  font-family: monospace;
  font-size: 10px;
  color: #7090c0;
  background: rgba(0,0,0,0.2);
  padding: 3px 7px;
  border-radius: 3px;
  border-left: 2px solid rgba(100,140,255,0.3);
}
.pfx-vfxs-name-sample-dim { color: #405060; }

/* ── Inline warnings / info ── */
.pfx-vfxs-warn-inline {
  margin-top: 8px;
  font-size: 9px;
  color: #E0B341;
  background: rgba(224,179,65,0.07);
  border: 1px solid rgba(224,179,65,0.2);
  border-radius: 4px;
  padding: 5px 9px;
}
.pfx-vfxs-info-inline {
  margin-top: 6px;
  font-size: 9px;
  color: #6080a0;
  padding: 4px 0;
}

/* ── Resolve status ── */
.pfx-vfxs-resolve-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.pfx-vfxs-resolve-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.pfx-vfxs-resolve-dot.ok  { background: #0AA356; box-shadow: 0 0 5px rgba(10,163,86,0.6); }
.pfx-vfxs-resolve-dot.err { background: #E5484D; box-shadow: 0 0 5px rgba(229,72,77,0.5); }
.pfx-vfxs-resolve-status {
  font-size: 11px;
  font-weight: 600;
  color: #b0c0e0;
}
.pfx-vfxs-resolve-hint {
  font-size: 9px;
  color: #506080;
  margin-left: 4px;
}

/* ── Gate progress bar ── */
.pfx-vfxs-gate-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
}
.pfx-vfxs-gate-bar-wrap {
  flex: 1;
  height: 6px;
  background: rgba(255,255,255,0.06);
  border-radius: 3px;
  overflow: hidden;
}
.pfx-vfxs-gate-bar {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s;
}
.pfx-vfxs-gate-pct {
  font-size: 12px;
  font-weight: 700;
  min-width: 38px;
  text-align: right;
}
.pfx-vfxs-gate-label {
  font-size: 9px;
  color: #5060a0;
  white-space: nowrap;
}
.pfx-vfxs-gate-stats {
  display: flex;
  gap: 16px;
  margin-top: 4px;
}
.pfx-vfxs-stat {
  font-size: 9px;
  color: #506080;
}
.pfx-vfxs-stat-val {
  font-weight: 700;
  margin-right: 3px;
}

/* ── Warnings list ── */
.pfx-vfxs-warn-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  background: rgba(229,72,77,0.2);
  border: 1px solid rgba(229,72,77,0.35);
  border-radius: 8px;
  font-size: 8px;
  font-weight: 700;
  color: #E5484D;
}
.pfx-vfxs-count-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  background: rgba(100,140,255,0.12);
  border: 1px solid rgba(100,140,255,0.25);
  border-radius: 8px;
  font-size: 8px;
  font-weight: 700;
  color: #8aadff;
}
.pfx-vfxs-warn-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.pfx-vfxs-warn-item {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  font-size: 10px;
  padding: 6px 9px;
  border-radius: 5px;
}
.pfx-vfxs-warn-item.error {
  background: rgba(229,72,77,0.08);
  border: 1px solid rgba(229,72,77,0.2);
  color: #e08080;
}
.pfx-vfxs-warn-item.warn {
  background: rgba(224,179,65,0.07);
  border: 1px solid rgba(224,179,65,0.18);
  color: #d4b040;
}
.pfx-vfxs-warn-icon { flex-shrink: 0; font-size: 10px; }
.pfx-vfxs-ok-banner {
  font-size: 10px;
  font-weight: 600;
  color: #0AA356;
  padding: 8px 10px;
  background: rgba(10,163,86,0.08);
  border: 1px solid rgba(10,163,86,0.2);
  border-radius: 5px;
}

/* ── Verify table ── */
.pfx-vfxs-vt-scroll {
  max-height: 220px;
  overflow-y: auto;
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 6px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.1) transparent;
}
.pfx-vfxs-verify-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 10px;
}
.pfx-vfxs-verify-table thead { position: sticky; top: 0; background: #0d0d20; z-index: 1; }
.pfx-vfxs-verify-table th {
  padding: 5px 9px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #404060;
  text-transform: uppercase;
  text-align: left;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.pfx-vfxs-verify-table td {
  padding: 5px 9px;
  color: #8090b0;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  vertical-align: middle;
}
.pfx-vfxs-verify-table tr:last-child td { border-bottom: none; }
.pfx-vfxs-vt-shot { color: #b0c0e0 !important; font-weight: 600; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pfx-vfxs-vt-score { color: #5060a0 !important; }
.pfx-vfxs-vt-none  { color: #2a3050 !important; }
.pfx-vfxs-empty    { color: #3a4060 !important; text-align: center; padding: 16px !important; }

/* ── Badges ── */
.pfx-vfxs-badge {
  display: inline-block;
  font-size: 8px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 3px;
  letter-spacing: 0.05em;
  margin-right: 3px;
}
.pfx-vfxs-badge-ok      { background: rgba(10,163,86,.15); color: #0AA356; border: 1px solid rgba(10,163,86,.3); }
.pfx-vfxs-badge-err     { background: rgba(229,72,77,.15);  color: #E5484D; border: 1px solid rgba(229,72,77,.3); }
.pfx-vfxs-badge-warn    { background: rgba(224,179,65,.12); color: #E0B341; border: 1px solid rgba(224,179,65,.25); }
.pfx-vfxs-badge-pending { background: rgba(100,100,140,.12); color: #6a7090; border: 1px solid rgba(100,100,140,.2); }

/* ── Export tab ── */
.pfx-vfxs-radio-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.pfx-vfxs-radio-label {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 8px 10px;
  border: 1.5px solid rgba(255,255,255,0.07);
  border-radius: 6px;
  cursor: pointer;
  transition: border-color 0.12s, background 0.12s;
  font-size: 10px;
  color: #8090b0;
}
.pfx-vfxs-radio-label:hover { border-color: rgba(100,140,255,0.3); }
.pfx-vfxs-radio-label.active { border-color: rgba(100,140,255,0.45); background: rgba(100,140,255,0.07); color: #a0b0d0; }
.pfx-vfxs-radio-label input[type="radio"] { margin-top: 1px; flex-shrink: 0; }
.pfx-vfxs-path-hint {
  display: block;
  font-family: monospace;
  font-size: 9px;
  color: #405060;
  margin-top: 2px;
}
.pfx-vfxs-path-preview {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px;
  background: rgba(0,0,0,0.2);
  border-radius: 5px;
  border: 1px solid rgba(255,255,255,0.05);
}
.pfx-vfxs-path-row {
  font-family: monospace;
  font-size: 9px;
  color: #6080a0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pfx-vfxs-path-more {
  font-size: 9px;
  color: #405060;
  padding: 2px 0;
}
.pfx-vfxs-checkbox-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  color: #8090b0;
  padding: 4px 0;
  cursor: pointer;
}
.pfx-vfxs-gate-block {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 10px 12px;
  background: rgba(229,72,77,0.08);
  border: 1.5px solid rgba(229,72,77,0.25);
  border-radius: 6px;
  font-size: 10px;
  color: #e08080;
  margin-top: 8px;
}
.pfx-vfxs-gate-block-icon {
  font-size: 12px;
  flex-shrink: 0;
  margin-top: 1px;
}

/* ── Footer ── */
.pfx-vfxs-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 22px;
  border-top: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
}
.pfx-vfxs-btn {
  font-size: 10px;
  font-weight: 700;
  padding: 6px 16px;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.15s;
  letter-spacing: 0.04em;
  border: 1.5px solid transparent;
}
.pfx-vfxs-btn-ghost {
  background: rgba(255,255,255,0.05);
  border-color: rgba(255,255,255,0.1);
  color: #7080a0;
}
.pfx-vfxs-btn-ghost:hover { background: rgba(255,255,255,0.09); color: #b0c0e0; }
.pfx-vfxs-btn-cancel {
  background: transparent;
  border-color: rgba(255,255,255,0.08);
  color: #5a6880;
}
.pfx-vfxs-btn-cancel:hover { background: rgba(255,255,255,0.05); color: #9090a0; }
.pfx-vfxs-btn-primary {
  background: rgba(100,140,255,0.18);
  border-color: rgba(100,140,255,0.5);
  color: #8aadff;
}
.pfx-vfxs-btn-primary:hover {
  background: rgba(100,140,255,0.3);
  border-color: #8aadff;
  color: #d0e4ff;
}

/* ── 3-panel body ── */
.pfx-vfx-ws-body {
  display: flex;
  flex: 1 1 0;
  min-height: 0;
  overflow: hidden;
}

/* ── LEFT: shot list ── */
.pfx-vfx-ws-left {
  width: 380px;
  min-width: 320px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  border-right: 1px solid #1e1e2e;
  background: #0f0f18;
  overflow: hidden;
}
.pfx-vfx-ws-panel-hdr {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #5a5a7a;
  text-transform: uppercase;
  padding: 7px 10px 5px;
  border-bottom: 1px solid #181828;
  flex-shrink: 0;
}
.pfx-vfx-ocf-drop-zone {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px;
  margin: 6px 8px 4px;
  border: 1.5px dashed rgba(160, 100, 255, 0.4);
  border-radius: 7px;
  background: rgba(100, 40, 200, 0.08);
  color: rgba(200, 160, 255, 0.75);
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  flex-shrink: 0;
  user-select: none;
}
.pfx-vfx-ocf-drop-zone:hover,
.pfx-vfx-ocf-drop-zone.pfx-vfx-ocf-drag-over {
  border-color: rgba(180, 100, 255, 0.85);
  background: rgba(120, 50, 220, 0.18);
  color: #4a8ce8;
}
.pfx-vfx-ocf-drop-zone.pfx-vfx-ocf-drag-over {
  border-style: solid;
  box-shadow: 0 0 10px rgba(160, 80, 255, 0.3);
}
.pfx-vfx-ocf-drop-zone.pfx-vfx-ocf-linked {
  border-color: rgba(80, 220, 130, 0.7);
  background: rgba(40, 180, 90, 0.1);
  color: #7fffb2;
  border-style: solid;
}
.pfx-vfx-ocf-pick-btn {
  display: inline;
  padding: 0;
  margin: 0;
  background: none;
  border: none;
  color: #b47fff;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.pfx-vfx-ocf-pick-btn:hover { color: #4a8ce8; }
.pfx-vfx-ws-shot-scroll {
  flex: 1 1 0;
  overflow-y: auto;
  overflow-x: hidden;
}
.pfx-vfx-shot-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11.5px;
}
.pfx-vfx-shot-table thead th {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #9090b4;
  text-transform: uppercase;
  padding: 6px 8px 5px;
  border-bottom: 1px solid #262638;
  text-align: left;
  position: sticky;
  top: 0;
  background: #0f0f18;
}
.pfx-vfx-shot-table tbody tr {
  border-bottom: 1px solid #1d1d2c;
  cursor: pointer;
}
.pfx-vfx-shot-table tbody tr:hover td {
  background: rgba(10,163,86,.10);
}
.pfx-vfx-shot-table tbody tr.is-selected td {
  background: rgba(10,163,86,.16);
  border-left: 2px solid #0AA356;
}
.pfx-vfx-shot-table td {
  padding: 8px 8px;
  color: #dcdcf0;
  vertical-align: middle;
}
.pfx-vfx-shot-empty td {
  color: #3a3a5a;
  font-style: italic;
  text-align: center;
  padding: 20px 8px;
  cursor: default;
}
.pfx-vfx-shot-name {
  font-weight: 700;
  color: #e8fff0;
  font-size: 12px;
  max-width: 290px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pfx-vfx-shot-score {
  font-family: monospace;
  font-size: 11px;
  color: #a8a8d0;
}
/* Inline badge spans used in shot list Verify / Approved cells */
.pfx-vfx-badge-ok {
  font-size: 10px;
  font-weight: 700;
  color: #0AA356;
}
.pfx-vfx-badge-warn {
  font-size: 10px;
  font-weight: 700;
  color: #e2a332;
}
.pfx-vfx-badge-nil {
  font-size: 10px;
  color: #3a3a5a;
}

/* ── CENTER: compare viewer ── */
.pfx-vfx-ws-center {
  flex: 1 1 0;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  background: #0d0d14;
}

/* Compare toolbar */
.pfx-vfx-compare-toolbar {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 5px 10px;
  background: #111118;
  border-bottom: 1px solid #1e1e2e;
  flex-shrink: 0;
}
.pfx-vfx-cmp-btn {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 3px 10px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.1);
  color: #7070a0;
  border-radius: 4px;
  cursor: pointer;
  text-transform: uppercase;
  transition: background .1s, color .1s;
}
.pfx-vfx-cmp-btn:hover {
  background: rgba(255,255,255,.09);
  color: #a0a0c8;
}
.pfx-vfx-cmp-btn.active {
  background: rgba(10,163,86,.22);
  border-color: rgba(10,163,86,.55);
  color: #0AA356;
}
.pfx-vfx-cmp-sep {
  width: 1px;
  height: 16px;
  background: #2a2a3a;
  margin: 0 4px;
  flex-shrink: 0;
}

/* Compare viewer */
.pfx-vfx-viewer-wrap {
  flex: 1 1 0;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #080810;
  position: relative;
  overflow: hidden;
}
.pfx-vfx-viewer-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: #3a3a5a;
}
.pfx-vfx-viewer-placeholder span {
  font-size: 11px;
  font-weight: 500;
}
.pfx-vfx-vp-sub {
  font-size: 9px !important;
  color: #2a2a42;
}

/* Hero frame strip */
.pfx-vfx-frame-strip {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 8px;
  background: #0e0e18;
  border-top: 1px solid #1e1e2e;
  flex-shrink: 0;
}
.pfx-vfx-strip-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.pfx-vfx-strip-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: #5a5a7a;
  text-transform: uppercase;
  width: 36px;
  flex-shrink: 0;
}
.pfx-vfx-strip-frames {
  display: flex;
  gap: 3px;
  flex: 1 1 0;
}
.pfx-vfx-strip-frame {
  flex: 1 1 0;
  aspect-ratio: 16/9;
  border-radius: 2px;
  overflow: hidden;
  background: #151520;
  border: 1px solid #2a2a3a;
}
.pfx-vfx-strip-frame-empty {
  background: repeating-linear-gradient(
    -45deg,
    #131320,
    #131320 4px,
    #171724 4px,
    #171724 8px
  );
}

/* ── VFX Player Controls ── */
.pfx-vfx-player {
  display: flex;
  flex-direction: column;
  gap: 0;
  background: #0c0c16;
  border-top: 1px solid #1a1a2e;
  border-bottom: 1px solid #1a1a2e;
  flex-shrink: 0;
  user-select: none;
}
.pfx-vfx-plr-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
}
.pfx-vfx-plr-transport-row {
  padding: 5px 8px 3px;
}
.pfx-vfx-plr-scrub-row {
  padding: 0 6px 2px;
}
.pfx-vfx-plr-utils-row {
  padding: 3px 8px 5px;
  justify-content: space-between;
}

/* Transport buttons */
.pfx-vfx-plr-btns {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}
.pfx-vfx-plr-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  height: 24px;
  padding: 0 5px;
  background: #1a1a28;
  border: 1px solid #2a2a40;
  border-radius: 3px;
  color: #9090b0;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
}
.pfx-vfx-plr-btn:hover:not(:disabled) {
  background: #252538;
  border-color: #4040608c;
  color: #c0c0e0;
}
.pfx-vfx-plr-btn:active:not(:disabled) {
  background: #1e1e38;
}
.pfx-vfx-plr-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}
.pfx-vfx-plr-play {
  min-width: 32px;
  background: #18283a;
  border-color: #2a4060;
  color: #50a0e0;
  font-size: 12px;
}
.pfx-vfx-plr-play:hover:not(:disabled) {
  background: #1e3050;
  border-color: #3060a0;
  color: #80c0f0;
}
.pfx-vfx-plr-play.pfx-vfx-plr-playing {
  background: #1a2e1a;
  border-color: #2a6030;
  color: #50d060;
}

/* TC readouts */
.pfx-vfx-plr-tc-block {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1 1 0;
  min-width: 0;
}
.pfx-vfx-plr-tc-lbl {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #505070;
  text-transform: uppercase;
  flex-shrink: 0;
}
.pfx-vfx-plr-tc {
  font-family: 'SF Mono', 'Fira Mono', 'Consolas', monospace;
  font-size: 11px;
  color: #6ec87a;
  letter-spacing: 0.04em;
  flex-shrink: 0;
}
.pfx-vfx-plr-fr {
  color: #8888b0;
  font-size: 10px;
}
.pfx-vfx-plr-tc-sep {
  color: #303050;
  font-size: 10px;
  flex-shrink: 0;
}

/* Mode label + speed cluster */
.pfx-vfx-plr-right-cluster {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.pfx-vfx-plr-mode-lbl {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #404060;
  text-transform: uppercase;
  min-width: 52px;
  text-align: right;
}
.pfx-vfx-plr-speeds {
  display: flex;
  gap: 1px;
}
.pfx-vfx-plr-speed {
  height: 20px;
  padding: 0 7px;
  background: #151520;
  border: 1px solid #252535;
  color: #505070;
  font-size: 9px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.1s, color 0.1s;
}
.pfx-vfx-plr-speed:first-child { border-radius: 3px 0 0 3px; }
.pfx-vfx-plr-speed:last-child  { border-radius: 0 3px 3px 0; }
.pfx-vfx-plr-speed-active {
  background: #1a1a36;
  border-color: #3a3a60;
  color: #9090d0;
}
.pfx-vfx-plr-speed:hover:not(.pfx-vfx-plr-speed-active) {
  background: #1a1a28;
  color: #7070a0;
}

/* Scrub slider */
.pfx-vfx-plr-slider {
  width: 100%;
  height: 16px;
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  cursor: pointer;
  outline: none;
}
.pfx-vfx-plr-slider::-webkit-slider-runnable-track {
  height: 3px;
  background: linear-gradient(to right, #2a6070 0%, #2a6070 var(--pfx-pct, 0%), #1e1e30 var(--pfx-pct, 0%), #1e1e30 100%);
  border-radius: 2px;
}
.pfx-vfx-plr-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #5090c0;
  margin-top: -3.5px;
  border: none;
  transition: background 0.1s;
}
.pfx-vfx-plr-slider:hover::-webkit-slider-thumb {
  background: #70b0e0;
}

/* Utility buttons */
.pfx-vfx-plr-utils-left,
.pfx-vfx-plr-utils-right {
  display: flex;
  align-items: center;
  gap: 4px;
}
.pfx-vfx-plr-util {
  height: 20px;
  padding: 0 8px;
  background: #131320;
  border: 1px solid #202030;
  border-radius: 3px;
  color: #606080;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.03em;
  cursor: pointer;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
  white-space: nowrap;
}
.pfx-vfx-plr-util:hover {
  background: #1a1a2e;
  border-color: #303050;
  color: #8080a8;
}
.pfx-vfx-plr-util-sep {
  width: 1px;
  height: 14px;
  background: #202030;
  flex-shrink: 0;
}
.pfx-vfx-plr-zoom-btn {
  padding: 0 6px;
  color: #505070;
}
.pfx-vfx-plr-ocf-prog {
  font-size: 9px;
  color: #5080a0;
  letter-spacing: 0.04em;
}

/* Loading overlay on OCF thumb inside viewer */
.pfx-vfx-viewer-ocf-wrap.pfx-vfx-plr-loading::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.45);
}

/* Hero strip: clickable frames */
.pfx-vfx-strip-frame {
  cursor: pointer;
  transition: border-color 0.12s;
}
.pfx-vfx-strip-frame:hover {
  border-color: #4060a0;
}
.pfx-vfx-strip-frame-sel {
  border-color: #5090d0 !important;
  box-shadow: 0 0 0 1px #3070b0 inset;
}

/* ── RIGHT: verify panel ── */
.pfx-vfx-ws-right {
  width: 200px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  border-left: 1px solid #1e1e2e;
  background: #0f0f18;
  overflow: hidden;
}
.pfx-vfx-verify-list {
  display: flex;
  flex-direction: column;
  padding: 6px 0;
  overflow-y: auto;
  flex: 1 1 0;
}
.pfx-vfx-vf-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 12px;
  border-bottom: 1px solid #161622;
}
.pfx-vfx-vf-row:hover {
  background: rgba(255,255,255,.025);
}
.pfx-vfx-vf-row-score {
  background: rgba(10,163,86,.04);
}
.pfx-vfx-vf-key {
  font-size: 9px;
  font-weight: 600;
  color: #7a7a9a;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.pfx-vfx-vf-val {
  font-size: 10px;
  font-weight: 700;
  font-family: monospace;
}
.pfx-vfx-vf-pending { color: #3a3a5a; }
.pfx-vfx-vf-ok      { color: #0AA356; }
.pfx-vfx-vf-warn    { color: #E0B341; }
.pfx-vfx-vf-err     { color: #E5484D; }
.pfx-vfx-vf-divider {
  height: 1px;
  background: #1e1e2e;
  margin: 8px 0;
}
.pfx-vfx-approve-btn {
  margin: 4px 12px 8px;
  padding: 8px 0;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border-radius: 5px;
  cursor: pointer;
  border: 1.5px solid rgba(10,163,86,.35);
  background: rgba(10,163,86,.12);
  color: #0AA356;
  transition: background .15s, border-color .15s;
}
.pfx-vfx-approve-btn:disabled {
  opacity: 0.35;
  cursor: default;
}
.pfx-vfx-approve-btn:not(:disabled):hover {
  background: rgba(10,163,86,.28);
  border-color: #0AA356;
  color: #a0ffcf;
}

/* Viewer live image */
.pfx-vfx-viewer-img-wrap {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #060610;
}
.pfx-vfx-viewer-img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  display: block;
}
.pfx-vfx-viewer-side {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
}
/* Equal, aligned side-by-side panes (QT Ref | OCF). Both halves use the same
   pane box so the two frames render at identical size and vertical alignment. */
.pfx-vfx-viewer-pane {
  flex: 1 1 0;
  min-width: 0;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.pfx-vfx-viewer-pane > img,
.pfx-vfx-viewer-pane > .pfx-vfx-viewer-img {
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
  object-fit: contain;
  flex: 0 1 auto;
}
.pfx-vfx-viewer-pane > .pfx-vfx-viewer-no-ocf {
  width: 100%;
  height: 100%;
}
/* legacy fallback for any bare img/no-ocf still rendered directly in -side */
.pfx-vfx-viewer-side > img,
.pfx-vfx-viewer-side > .pfx-vfx-viewer-no-ocf {
  flex: 1 1 0;
  min-width: 0;
  max-height: 100%;
  object-fit: contain;
}
.pfx-vfx-viewer-side-div {
  width: 1px;
  height: 80%;
  background: rgba(255,255,255,.2);
  flex-shrink: 0;
}
.pfx-vfx-viewer-no-ocf {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 700;
  color: #5a3a3a;
  background: #0e0a0a;
  height: 100%;
  text-align: center;
  padding: 0 16px;
}
.pfx-vfx-viewer-no-ocf.pfx-vfx-ocf-loading {
  color: rgba(228,235,255,.35);
  font-weight: 400;
}
.pfx-vfx-viewer-no-ocf.pfx-vfx-ocf-err {
  color: #c0634a;
}
.pfx-vfx-ocf-err-detail {
  font-size: 9px;
  font-weight: 400;
  color: rgba(228,235,255,.35);
  max-width: 260px;
  word-break: break-all;
}
/* Resolve Engine required state */
.pfx-vfx-viewer-no-ocf.pfx-vfx-ocf-engine-required {
  color: rgba(228,235,255,.75);
  gap: 10px;
}
.pfx-vfx-ocf-engine-msg {
  font-size: 10px;
  font-weight: 600;
  max-width: 280px;
  text-align: center;
  line-height: 1.4;
  color: rgba(228,235,255,.75);
}
.pfx-vfx-ocf-engine-msg b { color: #4a8ce8; }
.pfx-vfx-ocf-engine-hint {
  font-size: 9px;
  font-weight: 600;
  color: rgba(228,235,255,.45);
  text-align: center;
  max-width: 280px;
}
.pfx-vfx-ocf-engine-actions {
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-items: center;
}
.pfx-vfx-ocf-btn {
  font-size: 9px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 4px;
  border: 1px solid rgba(228,235,255,.3);
  background: rgba(80,100,160,.35);
  color: rgba(228,235,255,.9);
  cursor: pointer;
  letter-spacing: .03em;
  min-width: 160px;
  text-align: center;
}
.pfx-vfx-ocf-btn:hover {
  background: rgba(80,100,160,.6);
  border-color: rgba(228,235,255,.55);
}
.pfx-vfx-ocf-btn.pfx-vfx-ocf-btn-minor {
  background: transparent;
  border-color: rgba(228,235,255,.15);
  color: rgba(228,235,255,.45);
}
.pfx-vfx-ocf-btn.pfx-vfx-ocf-btn-minor:hover {
  color: rgba(228,235,255,.75);
  border-color: rgba(228,235,255,.35);
}
/* Decoder badge — overlay on OCF image */
.pfx-vfx-viewer-ocf-wrap {
  flex: 1 1 0;
  min-width: 0;
  position: relative;
  overflow: hidden;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.pfx-vfx-viewer-ocf-wrap .pfx-vfx-viewer-img {
  flex: 0 1 auto;
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
  object-fit: contain;
}
.pfx-vfx-ocf-decoder-badge {
  position: absolute;
  bottom: 4px;
  right: 4px;
  background: rgba(0,0,0,.72);
  color: rgba(228,235,255,.72);
  font-size: 8px;
  font-weight: 700;
  padding: 2px 5px;
  border-radius: 3px;
  letter-spacing: .03em;
  pointer-events: none;
}
/* Badge as inline flow element (inside no-ocf / error divs) */
.pfx-vfx-ocf-decoder-badge-inline {
  position: static;
  display: inline-block;
  background: rgba(255,255,255,.08);
  color: rgba(228,235,255,.45);
  font-size: 8px;
  font-weight: 600;
  padding: 1px 5px;
  border-radius: 3px;
}
/* Strip decoder badge */
.pfx-vfx-strip-decoder-badge {
  position: absolute;
  bottom: 14px;
  right: 2px;
  background: rgba(0,0,0,.6);
  color: rgba(228,235,255,.55);
  font-size: 6px;
  font-weight: 700;
  padding: 1px 3px;
  border-radius: 2px;
  pointer-events: none;
}

/* Frame strip: populated cells */
.pfx-vfx-strip-frame {
  position: relative;
}
.pfx-vfx-strip-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.pfx-vfx-strip-lbl {
  position: absolute;
  bottom: 2px;
  left: 0;
  right: 0;
  text-align: center;
  font-size: 7px;
  font-weight: 700;
  color: rgba(255,255,255,.75);
  background: rgba(0,0,0,.45);
  pointer-events: none;
  line-height: 1.4;
}
.pfx-vfx-strip-frame-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
}
.pfx-vfx-strip-spin {
  font-size: 8px;
  color: #4a4a6a;
  animation: pfx-spin-fade 1s infinite alternate;
}
@keyframes pfx-spin-fade {
  from { opacity: 0.2; }
  to   { opacity: 1;   }
}
.pfx-vfx-strip-err {
  font-size: 9px;
  color: #6a3030;
}
.pfx-vfx-strip-frame-nil {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8px;
  font-weight: 700;
  color: #5a3a3a;
  flex: 1 1 100%;
  aspect-ratio: unset;
  height: 32px;
}

/* =============================================================
   macOS Native Titlebar + Workspace Toolbar
   Tier 1 (.mac-titlebar): 38px drag region — app title + global controls
   Tier 2 (.mac-workspace-toolbar): 34px compact tab strip
   ============================================================= */

/* Tier 1: macOS native-style titlebar (desktop only) */
html[data-pfx-env="desktop"] .mac-titlebar {
  display: flex;
  align-items: stretch;
  height: 38px;
  flex: 0 0 38px;
  padding-left: 78px;
  padding-right: 14px;
  -webkit-app-region: drag;
  background: rgba(20, 20, 24, 0.72);
  backdrop-filter: blur(28px) saturate(140%);
  -webkit-backdrop-filter: blur(28px) saturate(140%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  user-select: none;
}

/* 3-column grid: title | status | actions */
html[data-pfx-env="desktop"] .mac-drag-zone {
  display: grid;
  /* Balanced 3-zone bar: title (left) · resolve status (centered) · actions (right).
     Equal 1fr edges center the middle column so the title isn't stranded alone. */
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  width: 100%;
  height: 100%;
  gap: 8px;
}

/* App title — left column */
html[data-pfx-env="desktop"] .app-title {
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.75);
  letter-spacing: 0.02em;
  pointer-events: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Resolve status badge — center column */
html[data-pfx-env="desktop"] .titlebar-status {
  border-radius: 8px;
  font-size: 11px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 0 10px;
  height: 24px;
  display: flex;
  align-items: center;
  gap: 5px;
  color: rgba(255, 255, 255, 0.55);
  white-space: nowrap;
  -webkit-app-region: no-drag;
  cursor: pointer;
}
html[data-pfx-env="desktop"] .titlebar-status:hover {
  background: rgba(255, 255, 255, 0.07);
}
html[data-pfx-env="desktop"] .titlebar-status .pfx-resolve-pill-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}
html[data-pfx-env="desktop"] .titlebar-status .pfx-resolve-pill-text {
  font-size: 11px;
}

/* Action buttons group — right column */
html[data-pfx-env="desktop"] .titlebar-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  justify-self: end;   /* pin the action cluster to the right edge of its 1fr column */
  -webkit-app-region: no-drag;
}

/* All interactive elements inside titlebar must not be draggable */
html[data-pfx-env="desktop"] .mac-titlebar button,
html[data-pfx-env="desktop"] .mac-titlebar select,
html[data-pfx-env="desktop"] .mac-titlebar a,
html[data-pfx-env="desktop"] .mac-titlebar [role="button"],
html[data-pfx-env="desktop"] .mac-titlebar input,
html[data-pfx-env="desktop"] .mac-titlebar .top-aux,
