  align-items: center;
  gap: 4px;
  white-space: nowrap;
  -webkit-app-region: no-drag;
}
html[data-pfx-env="desktop"] .titlebar-actions > button:hover,
html[data-pfx-env="desktop"] .titlebar-actions .pfx-global-tutorial-btn:hover {
  background: rgba(255, 255, 255, 0.07);
  color: rgba(255, 255, 255, 0.9);
}

/* Tool Box / Fun box toggle buttons */
html[data-pfx-env="desktop"] .mac-titlebar .top-aux-tab {
  height: 24px;
  font-size: 11px;
  padding: 0 8px;
  border-radius: 7px;
}

/* Language selector */
html[data-pfx-env="desktop"] .mac-titlebar .lang-select-flags {
  height: 24px;
  font-size: 14px;
  padding: 0 2px;
}

/* Tool Box / Fun box dropdown panel: anchor below the tab buttons.
   top: calc(100% + 4px) = 4px below the bottom edge of .top-aux.
   position: fixed escapes #appViewport overflow:hidden clipping. */
html[data-pfx-env="desktop"] .mac-titlebar .top-aux-panel {
  position: fixed !important;
  top: 42px !important;
  right: 14px !important;
}

/* Ensure Tool Box panel and all its interactive children are never part of the
   Electron drag region — position:fixed keeps the panel visually outside the
   38px titlebar, but explicit no-drag is belt-and-suspenders for Electron. */
.toolbox-popover,
.toolbox-popover *,
#topAuxPanel,
#topAuxPanel *,
.workspace-tabs-panel,
.workspace-tab-row,
.workspace-tab-row button,
.workspace-tab-pin,
.workspace-tab-toggle,
.workspace-tab-handle,
.tb-workspace-section,
.tb-workspace-tabs,
.tb-workspace-card,
.tb-workspace-actions,
.tb-workspace-pin,
.tb-workspace-move,
.tb-workspace-open {
  -webkit-app-region: no-drag;
}

/* Hide mac-titlebar on Chrome extension / non-desktop */
html:not([data-pfx-env="desktop"]) .mac-titlebar {
  display: none !important;
}

/* Desktop: strip outer #appShell padding so titlebar/toolbar are flush with window edges.
   Content panes below the toolbar retain spacing via their own padding/margin. */
html[data-pfx-env="desktop"] #appViewport {
