/* Tier 2: Workspace tab strip — all !important to beat #appShell > .tabs generic rules */
html[data-pfx-env="desktop"] #appShell > .mac-workspace-toolbar {
  height: 34px !important;
  min-height: 34px !important;
  flex: 0 0 34px !important;
  /* Symmetric padding + centered tabs so the strip is balanced rather than
     stranded on the left. Traffic-light clearance lives on the row above. */
  padding: 0 12px !important;
  background: rgba(9, 9, 14, 0.92) !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 2px !important;
}

/* Workspace tab buttons — include #appShell to beat #appShell > .tabs .tab (specificity 120+) */
html[data-pfx-env="desktop"] #appShell .mac-workspace-toolbar .tab {
  height: 26px !important;
  min-height: 26px !important;
  border-radius: 7px !important;
  border: none !important;
  background: transparent !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  color: rgba(255, 255, 255, 0.45) !important;
  padding: 0 10px !important;
  display: flex !important;
  align-items: center !important;
  gap: 5px !important;
  cursor: pointer !important;
  white-space: nowrap !important;
  box-shadow: none !important;
  letter-spacing: 0.02em !important;
}
html[data-pfx-env="desktop"] #appShell .mac-workspace-toolbar .tab:hover {
