}
html[data-pfx-env="desktop"] #appShell .mac-workspace-toolbar .tab.active svg {
  opacity: 1;
}
html[data-pfx-env="desktop"] #appShell .mac-workspace-toolbar .tab .bar { display: none !important; }

/* ── AAF detail panel (Settings > Media Playback, desktop only) ─────────── */
.pfx-nh-aaf-detail {
