.imf-sb-left,
.imf-sb-right { display: flex; align-items: center; gap: 0; }
.imf-sb-item { font-size: 10px; color: #555; white-space: nowrap; }
.imf-sb-sep { font-size: 10px; color: #333; padding: 0 8px; }
.imf-sb-dot { font-size: 8px; margin-right: 4px; }
.imf-sb-dot-green { color: #4a9a5a; }
.imf-sb-dot-red   { color: #9a4a4a; }
.imf-sb-val { color: #888; }
.imf-sb-val-blue  { color: #4a7a9a; }
.imf-sb-val-green { color: #4a9a5a; }

/* ── Shared icon btn ─────────────────────────────────────────────────────── */
.imf-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 3px;
  color: #666;
  font-size: 11px;
  cursor: pointer;
  line-height: 1;
  transition: color .12s, background .12s, border-color .12s;
}
.imf-icon-btn:hover { color: #bbb; background: #2a2a2a; border-color: #383838; }

/* ── Scope panel relocated to right column ───────────────────────────────── */
.imf-col-right .imf-scope-panel,
#main-imf .imf-col-right .imf-scope-panel {
  flex: 1;
  flex-basis: auto !important;
  min-height: 0 !important;
  min-width: 0 !important;
  max-width: none !important;
  border-left: none;
  border-top: none;
  width: 100%;
}


/* ═══════════════════════════════════════════════════════════════════════════
   IMF IAB Center Panel
   ═════════════════════════════════════════════════════════════════════════ */

.imf-iab-main {
  display: none;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  background: #0e0e10;
  overflow: hidden;
}

.imf-iab-summary-bar {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 8px 12px;
  background: #141416;
  border-bottom: 1px solid #2a2a30;
  flex-shrink: 0;
  flex-wrap: nowrap;
  overflow-x: auto;
}
.imf-iab-summary-bar::-webkit-scrollbar { height: 3px; }
.imf-iab-summary-bar::-webkit-scrollbar-thumb { background: #2a2a30; }

.imf-iab-sum-stat {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 0 14px 0 0;
  min-width: 0;
  flex-shrink: 0;
}
.imf-iab-sum-k {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #555;
  line-height: 1.2;
}
.imf-iab-sum-v {
  font-size: 12px;
  font-weight: 600;
  color: #ccc;
  line-height: 1.4;
  white-space: nowrap;
  font-family: 'SF Mono', 'Menlo', 'Fira Code', monospace;
}
.imf-iab-sum-spacer { flex: 1; }
.imf-iab-sum-status {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 12px;
  flex-shrink: 0;
}
.imf-iab-sum-dot { font-size: 10px; line-height: 1; }
.imf-iab-sum-dot-idle    { color: #555; }
.imf-iab-sum-dot-running { color: #e5a020; }
.imf-iab-sum-dot-ok      { color: #3a9a5a; }
.imf-iab-sum-dot-err     { color: #b04040; }
.imf-iab-sum-status-lbl  { font-size: 11px; color: #777; }

.imf-iab-sum-actions {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}
.imf-iab-act-btn {
  padding: 4px 10px;
  font-size: 11px;
  border-radius: 3px;
  border: 1px solid #3a3a3a;
  background: #1e1e22;
  color: #bbb;
  cursor: pointer;
  white-space: nowrap;
  transition: border-color 0.15s, background 0.15s;
}
.imf-iab-act-btn:hover {
  border-color: #5a5a6a;
  background: #28282e;
  color: #ddd;
}
.imf-iab-act-primary {
  border-color: #3a5a7a;
  background: #1a2f42;
  color: #7ab4d8;
}
.imf-iab-act-primary:hover {
  border-color: #5a7a9a;
  background: #1f3852;
  color: #9ac4e8;
}

/* Track table header */
.imf-iab-track-hdr {
  display: grid;
  grid-template-columns: 52px 32px 1fr 76px 32px 54px 96px 32px;
  padding: 4px 10px;
  background: #161618;
  border-bottom: 1px solid #252528;
  flex-shrink: 0;
}
.imf-iab-th {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #555;
  padding: 2px 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Track table body */
.imf-iab-track-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
}
.imf-iab-track-body::-webkit-scrollbar { width: 5px; }
.imf-iab-track-body::-webkit-scrollbar-track { background: #0e0e10; }
.imf-iab-track-body::-webkit-scrollbar-thumb { background: #2e2e34; border-radius: 3px; }

/* Empty state */
.imf-iab-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  gap: 12px;
}
.imf-iab-empty-icon { font-size: 32px; opacity: 0.4; }
.imf-iab-empty-msg {
  font-size: 12px;
  color: #555;
  text-align: center;
  line-height: 1.6;
}

/* Track row */
.imf-iab-track-row {
  display: grid;
  grid-template-columns: 52px 32px 1fr 76px 32px 54px 96px 32px;
  padding: 3px 10px;
  border-bottom: 1px solid #1c1c1e;
  align-items: center;
  transition: background 0.1s;
}
.imf-iab-track-row:hover { background: #1a1a1e; }
.imf-iab-track-row-bed { border-left: 2px solid #3a6a9a; }
.imf-iab-track-row-obj { border-left: 2px solid #3a7a5a; }
.imf-iab-track-row-grp { border-left: 2px solid #7a6a3a; }

/* Type badge */
.imf-iab-badge {
  display: inline-block;
  padding: 1px 5px;
  border-radius: 2px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.imf-iab-badge-bed { background: #1a3555; color: #6aabda; border: 1px solid #2a4d6a; }
.imf-iab-badge-obj { background: #1a3a28; color: #5ac47a; border: 1px solid #2a5040; }
.imf-iab-badge-grp { background: #3a2a18; color: #c49a50; border: 1px solid #5a4428; }

/* Track cells */
.imf-iab-td {
  font-size: 11px;
  color: #aaa;
  padding: 2px 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: 'SF Mono', 'Menlo', 'Fira Code', monospace;
}
.imf-iab-td-name {
  color: #ccc;
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 11px;
}
.imf-iab-td-qc-ok   { color: #3a9a5a; }
.imf-iab-td-qc-warn { color: #c8902a; }
.imf-iab-td-qc-err  { color: #b04040; }

/* Progress row */
.imf-iab-progress-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: #141416;
  border-top: 1px solid #252528;
  flex-shrink: 0;
}
.imf-iab-prog-lbl {
  font-size: 11px;
  color: #888;
  white-space: nowrap;
}
.imf-iab-prog-wrap {
  flex: 1;
  height: 3px;
  background: #252528;
  border-radius: 2px;
  overflow: hidden;
}
.imf-iab-prog-bar {
  height: 100%;
  width: 0%;
  background: #4a7aaa;
  border-radius: 2px;
  transition: width 0.2s;
}
.imf-iab-prog-pct {
  font-size: 11px;
  color: #666;
  font-family: 'SF Mono', 'Menlo', monospace;
  white-space: nowrap;
  min-width: 32px;
  text-align: right;
}

/* Waveform row */
.imf-iab-wave-row {
  flex-shrink: 0;
  background: #111113;
  border-top: 1px solid #252528;
}
.imf-iab-wave-hdr {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px;
  background: #141416;
  border-bottom: 1px solid #1e1e20;
}
.imf-iab-wave-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #555;
}
.imf-iab-wave-lbl { font-size: 10px; color: #888; flex: 1; }
.imf-iab-wave-play {
  padding: 2px 8px;
  font-size: 10px;
  border: 1px solid #3a3a3a;
  background: #1e1e22;
  color: #aaa;
  border-radius: 2px;
  cursor: pointer;
}
.imf-iab-wave-canvas {
  width: 100%;
  height: 80px;
  display: block;
  background: #0a0a0c;
}

/* ═══════════════════════════════════════════════════════════════════════════
   IMF IAB Right Panel
   ═════════════════════════════════════════════════════════════════════════ */

.imf-iab-right-panel {
  display: none;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  background: #0e0e10;
}
.imf-iab-right-panel::-webkit-scrollbar { width: 5px; }
.imf-iab-right-panel::-webkit-scrollbar-track { background: #0e0e10; }
.imf-iab-right-panel::-webkit-scrollbar-thumb { background: #2e2e34; border-radius: 3px; }

.imf-iab-rp-section {
  flex-shrink: 0;
  padding: 8px 10px;
}
.imf-iab-rp-grow { flex: 1; min-height: 60px; overflow: hidden; display: flex; flex-direction: column; }
.imf-iab-rp-grow .imf-iab-rp-hdr { flex-shrink: 0; }
.imf-iab-rp-grow .imf-iab-adm-tree { flex: 1; }

.imf-iab-rp-hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}
.imf-iab-rp-hdr-sep {
  border-top: 1px solid #1e1e22;
  padding-top: 8px;
}
.imf-iab-rp-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #555;
}
.imf-iab-rp-std { font-size: 9px; color: #444; letter-spacing: 0.04em; }

/* Loudness grid */
.imf-iab-ld-grid { display: flex; flex-direction: column; gap: 2px; }
.imf-iab-ld-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 3px 7px;
  border-radius: 2px;
  background: #111113;
  border: 1px solid #1a1a1e;
}
.imf-iab-ld-k { font-size: 10px; color: #666; letter-spacing: 0.02em; }
.imf-iab-ld-v {
  font-size: 11px;
  font-weight: 600;
  color: #9ab8cc;
  font-family: 'SF Mono', 'Menlo', 'Fira Code', monospace;
  letter-spacing: -0.02em;
}
.imf-iab-ld-v-tp { color: #c8906a; }

/* Channel map */
.imf-iab-chmap {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  padding: 2px;
}
.imf-iab-chmap-empty,
.imf-iab-rt-empty,
.imf-iab-adm-empty { font-size: 11px; color: #3a3a40; padding: 2px; }

.imf-iab-ch-chip {
  padding: 2px 6px;
  background: #1a2530;
  border: 1px solid #2a3a48;
  border-radius: 2px;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: #6a9abf;
  font-family: 'SF Mono', 'Menlo', monospace;
}

/* Render targets */
.imf-iab-rt-list { display: flex; flex-direction: column; gap: 2px; }
.imf-iab-rt-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 3px 7px;
  background: #111113;
  border: 1px solid #1a1a1e;
  border-radius: 2px;
}
.imf-iab-rt-name  { font-size: 10px; color: #aaa; }
.imf-iab-rt-layout { font-size: 9px; color: #666; font-family: 'SF Mono', 'Menlo', monospace; }

/* ADM tree */
.imf-iab-adm-tree {
  font-size: 10px;
  color: #777;
  padding: 4px 2px;
  overflow-y: auto;
  line-height: 1.7;
}
.imf-iab-adm-tree::-webkit-scrollbar { width: 4px; }
.imf-iab-adm-tree::-webkit-scrollbar-thumb { background: #2a2a30; border-radius: 2px; }
.imf-iab-adm-node { padding-left: 12px; }
.imf-iab-adm-leaf { color: #888; font-family: 'SF Mono', 'Menlo', monospace; }

/* VFX Pull — wider SHOT LIST panel so shot names aren't truncated (user request).
   Appended last + !important to beat any earlier/competing width rule. */
.pfx-vfx-ws-body > .pfx-vfx-ws-left,
#pmVfxWorkspace .pfx-vfx-ws-left,
.pfx-vfx-ws-left { width: 380px !important; min-width: 320px !important; flex: 0 0 380px !important; }
.pfx-vfx-ws-left .pfx-vfx-shot-name,
.pfx-vfx-shot-name { max-width: 300px !important; }

/* ╔══════════════════════════════════════════════════════════════════════╗
   ║  HAWKINS PROFESSIONAL — OVERRIDE LAYER                                 ║
   ║  Appended last so it wins the cascade over this file's accreted        ║
   ║  restyle passes. Flattens neon/gradients, applies flat #161616         ║
   ║  surfaces + single Blue500 (#2172E3) accent, Hawkins radius/borders/   ║
   ║  focus rings. Semantic green/red kept for status + destructive.        ║
   ║  REVERSIBLE: delete from this banner to EOF to restore prior look.     ║
   ╚══════════════════════════════════════════════════════════════════════╝ */

/* ── App canvas: flat dark, drop the warm orange radial gradient ───────── */
html, body {
  background: var(--hwk-canvas) !important;
}

/* ── Header: flat surface, no top→bottom gradient, hairline divider ────── */
header {
  background: var(--hwk-surface) !important;
  border-bottom: 1px solid var(--hwk-border) !important;
  box-shadow: none !important;
}
.brand .x { color: var(--hwk-blue500) !important; }       /* was lilac #2172E3 */

/* ── Single-accent: collapse every per-tool neon --c-bar to Blue500 ────── */
[class*="theme-"],
.theme-edl, .theme-analyze, .theme-csv, .theme-pdf, .theme-vfxpack,
.theme-q1, .theme-q2, .theme-q3, .theme-amf,
#qsRow .qs-btn[data-key],
#cutdiffOldBrowse, #cutdiffNewBrowse, #cutdiffVcmpOldBrowse, #cutdiffVcmpNewBrowse,
#cutdiffAnalyzeBtn, #cutdiffExportBtn, #cutdiffExportCsvBtn,
#cutdiffExportPdfBtn, #cutdiffExportPackBtn {
  --c-bar: var(--hwk-blue500) !important;
}
/* Keep semantic meaning where the action is destructive / success */
.theme-danger, #cutdiffClearBtn,
#qsRow .qs-btn[data-key="vfxmarker"] { --c-bar: var(--hwk-red) !important; }
#qsRow .qs-btn[data-key="vfxrename"] { --c-bar: var(--hwk-green) !important; }

/* ── Cards / panels: flat surface, Hawkins low shadow, no backdrop blur ── */
.card {
  background: var(--hwk-surface) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 1px solid var(--hwk-border) !important;
  border-radius: var(--hwk-radius-1) !important;
  box-shadow: var(--hwk-shadow-low) !important;
}

/* ── Buttons (shared) ──────────────────────────────────────────────────── */
.btn, .qs-btn {
  background: var(--hwk-surface-2) !important;
  border: 1px solid var(--hwk-border-2) !important;
  border-radius: var(--hwk-radius-1) !important;
  color: var(--hwk-fg) !important;
  box-shadow: none !important;
  text-shadow: none !important;
  transition: background .15s, border-color .15s, color .15s !important;
}
.btn:hover, .qs-btn:hover {
  background: #262626 !important;
  border-color: var(--hwk-border-3) !important;
  transform: none !important;                 /* drop the lift */
  box-shadow: none !important;
}
/* Active = Hawkins primary: solid Blue500 fill, white text, no glow */
.btn.active, .qs-btn.active {
  background: var(--hwk-blue500) !important;
  border-color: var(--hwk-blue500) !important;
  color: var(--hwk-on-accent) !important;
  box-shadow: none !important;
}
.btn.active .bar, .qs-btn.active .bar,
.tab.active .bar, .inner-tab.active .bar {
  box-shadow: none !important;                /* kill underline glow */
}
.btn:focus-visible, .qs-btn:focus-visible {
  outline: none !important;
  box-shadow: var(--hwk-focus-ring) !important;
}

/* Destructive / success buttons stay semantic when active */
.theme-danger.active, #cutdiffClearBtn.active {
  background: var(--hwk-red) !important; border-color: var(--hwk-red) !important;
}
#qsRow .qs-btn[data-key="vfxrename"].active {
  background: var(--hwk-green) !important; border-color: var(--hwk-green) !important;
}

/* ── Tabs (main + inner): flat, Blue500 active underline bar ───────────── */
.tab, .inner-tab {
  background: var(--hwk-surface) !important;
  border: 1px solid var(--hwk-border) !important;
  border-radius: var(--hwk-radius-0) !important;
  color: var(--hwk-fg-muted) !important;
  box-shadow: none !important;
}
.tab.active, .inner-tab.active {
  background: var(--hwk-surface-2) !important;
  border-color: var(--hwk-border-3) !important;
  color: var(--hwk-fg) !important;
}
.tab .bar, .inner-tab .bar, .btn .bar {
  background: var(--c-bar, var(--hwk-blue500)) !important;
  box-shadow: none !important;
}

/* ── Inputs / selects / textareas: flat field + Blue500 focus ring ─────── */
input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
select, textarea {
  background: var(--hwk-surface) !important;
  border: 1px solid var(--hwk-border-2) !important;
  border-radius: var(--hwk-radius-0) !important;
  color: var(--hwk-fg) !important;
  box-shadow: none !important;
}
input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):focus,
select:focus, textarea:focus {
  outline: none !important;
  border-color: var(--hwk-blue500) !important;
  box-shadow: var(--hwk-focus-ring) !important;
}

/* ── Drop zone: dashed Hawkins border, accent on drag ──────────────────── */
#dropZone {
  background: var(--hwk-surface) !important;
  border: 1px dashed var(--hwk-border-3) !important;
  border-radius: var(--hwk-radius-1) !important;
}
#dropZone.drag {
  border-color: var(--hwk-blue500) !important;
  outline: none !important;
  background: rgba(33,114,227,.06) !important;
}

/* ── Badges / status pills: flat, no glow ──────────────────────────────── */
.alpha-badge {
  background: var(--hwk-blue500) !important;
  border-radius: var(--hwk-radius-0) !important;
  box-shadow: none !important;
}
.pfx-resolve-pill { border-radius: var(--hwk-radius-pill) !important; }
.pfx-resolve-pill:focus-visible { box-shadow: var(--hwk-focus-ring) !important; }

/* ── Global de-neon: remove leftover white/colored text-shadow glows ───── */
header .t, .brand .t, .card-title, .kpi, .tab, .inner-tab, .btn, .qs-btn {
  text-shadow: none !important;
}

/* ── Scrollbars: thin Hawkins-grey ─────────────────────────────────────── */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,.16);
  border-radius: var(--hwk-radius-pill);
}
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,.26); }
::-webkit-scrollbar-track { background: transparent; }

/* ── Accent-colored links / focus default ──────────────────────────────── */
a { color: var(--hwk-blue400); }
:focus-visible { outline-color: var(--hwk-blue500); }

/* ── Toolbar buttons: unify per-button --accent onto Blue500 ───────────── */
#tbReloadUI, #tbResetLayout, #tbFramingFDL, #tbExportQCReport, #tbTlConvert,
[id^="tb"] { --accent: var(--hwk-blue500) !important; }

/* ── KPIs / stat tiles: flat surface ───────────────────────────────────── */
.kpi {
  background: var(--hwk-surface-2) !important;
  border: 1px solid var(--hwk-border) !important;
  border-radius: var(--hwk-radius-0) !important;
  box-shadow: none !important;
  text-shadow: none !important;
}

/* ── Tables (event list / inspector): hairline Hawkins borders ─────────── */
#eventTable thead th, #eventTable tbody td,
.ins-table th, .ins-table td {
  border-color: var(--hwk-border) !important;
}
#eventTable tbody tr:hover td { background: rgba(255,255,255,.03) !important; }
#eventTable thead th { background: var(--hwk-surface-2) !important; }

/* ── Generic toggles / range / checkbox accent → Blue500 ───────────────── */
input[type="checkbox"], input[type="radio"], input[type="range"] {
  accent-color: var(--hwk-blue500) !important;
}

/* ── Polish pass (post-screenshot review) ──────────────────────────────── */
/* Render Queue: kill the blurred red/orange ambient glow (Hawkins is flat) */
#main-renderq .rq-shell::before { background: none !important; filter: none !important; }
/* Any remaining decorative warm radial body wash stays overridden by html,body above */

/* ── IMF transport: COMPACT standardized playback controls (Hawkins) ───── */
.imf-transport-v2 { height: 36px !important; gap: 4px !important; padding: 0 8px !important; background: var(--hwk-surface) !important; border-top: 1px solid var(--hwk-border) !important; }
.imf-transport-tc { gap: 4px !important; }
.imf-tc-large { font-size: 13px !important; }
.imf-frame-sub { font-size: 9px !important; }
.imf-transport-btns-v2,
.imf-transport-nudge,
.imf-transport-marks,
.imf-transport-modes,
.imf-transport-vol { gap: 2px !important; }
/* uniform secondary transport buttons — compact */
.imf-tbtn2 {
