.imf-tbtn2-play.is-playing { background: var(--hwk-blue600) !important; border-color: var(--hwk-blue600) !important; }
/* small / nudge / mark buttons — smaller still */
.imf-tbtn2-sm { width: 22px !important; height: 22px !important; font-size: 9px !important; }
/* mode toggles (FULL/AUTO/SDR): flat, Blue500 when active */
.imf-tbtn-mode { min-width: 32px !important; height: 22px !important; font-size: 9px !important; padding: 0 5px !important; border-radius: var(--hwk-radius-0) !important; }
.imf-tbtn-mode.imf-tbtn-mode-active { background: rgba(33,114,227,.16) !important; border-color: var(--hwk-blue500) !important; color: var(--hwk-blue400) !important; box-shadow: none !important; }
.imf-vol-slider { width: 48px !important; accent-color: var(--hwk-blue500) !important; }
/* Pack controls together — kill the big empty middle so the row is compact.
