  inset: 0;
  width: 100%;
  height: 100%;
  display: none;
  object-fit: contain;
  background: #000;
  z-index: 3;
}

/* ════════════════════════════════════════════════════════════════════════
   RESOLVE-STYLE TRANSPORT — unified across ALL PostFlowX players.
   DaVinci Resolve look: flat, borderless, monochrome-grey icon buttons —
   no boxes/fills/shadows; grey glyph → white on hover; Play is NOT a colored
   fill (just a grey ▶/⏸). Overrides the per-player button styling for IMF,
   Cut Diff, Pulls Prep, pm-video and VFX Pull players. Appended last to win.
   ════════════════════════════════════════════════════════════════════════ */
.imf-tbtn2, .imf-tbtn2-sm, .imf-tbtn2-play,
.cd-vcmp-tbtn,
.pm-sly-cmp-tbtn, .pm-sly-cmp-play, .pm-sly-cmp-io, .pm-sly-cmp-sync,
.pm-vid-ctrl-btn,
.pfx-vfx-plr-btn, .pfx-vfx-plr-play,
.pm-vfx-ws-scrub-btn, .pm-vfx-ws-play-btn,
.mps-qt-player-btn {
