  border: 0 !important;
  border-radius: 5px !important;
  box-shadow: none !important;
  text-shadow: none !important;
  color: rgba(255,255,255,.55) !important;
  cursor: pointer !important;
  transition: color .12s ease, background .12s ease !important;
}
.imf-tbtn2:hover, .imf-tbtn2-sm:hover, .imf-tbtn2-play:hover,
.cd-vcmp-tbtn:hover,
.pm-sly-cmp-tbtn:hover, .pm-sly-cmp-play:hover, .pm-sly-cmp-io:hover, .pm-sly-cmp-sync:hover,
.pm-vid-ctrl-btn:hover,
.pfx-vfx-plr-btn:hover, .pfx-vfx-plr-play:hover,
.pm-vfx-ws-scrub-btn:hover, .pm-vfx-ws-play-btn:hover,
.mps-qt-player-btn:hover {
  background: rgba(255,255,255,.10) !important;
  color: #fff !important;
}
/* active / playing / selected → bright white glyph, still flat (no fill) */
.imf-tbtn2.active, .imf-tbtn2-play.is-playing,
.cd-vcmp-tbtn.active, .cd-vcmp-tbtn.is-active,
.pm-sly-cmp-tbtn.is-active, .pm-sly-cmp-play.is-playing,
.pm-vid-ctrl-btn.active,
.pfx-vfx-plr-btn.active, .pfx-vfx-plr-play.is-playing,
.pm-vfx-ws-play-btn.is-playing,
.mps-qt-player-btn.is-playing {
  background: rgba(255,255,255,.06) !important;
  color: #fff !important;
}
.imf-tbtn2:focus-visible, .cd-vcmp-tbtn:focus-visible,
.pm-sly-cmp-tbtn:focus-visible, .pm-vid-ctrl-btn:focus-visible,
.pfx-vfx-plr-btn:focus-visible,
.pm-vfx-ws-scrub-btn:focus-visible, .pm-vfx-ws-play-btn:focus-visible,
.mps-qt-player-btn:focus-visible {
  outline: none !important; box-shadow: var(--hwk-focus-ring) !important;
}
/* Play/Pause: same flat grey as the rest — revert the blue circle */
.imf-tbtn2-play {
  width: 26px !important; height: 26px !important;
  border-radius: 5px !important; font-size: 13px !important; margin: 0 1px !important;
}

/* ── Resolve-style transport bar for native <video> players (RVT) ──────── */
.pfx-rvt {
  --rvt-icon: rgba(158,160,166,.94);
  --rvt-icon-hot: rgba(238,240,245,.96);
  --rvt-red: #ff3b30;
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 6;
  display: none; align-items: center; justify-content: center; gap: 0;
  height: 88px; padding: 0;
  background: #202126;
  border-top: 1px solid rgba(255,255,255,.08);
  box-shadow: 0 -1px 0 rgba(0,0,0,.7) inset;
}
.pfx-rvt-navpod,
.pfx-rvt-core {
  position: absolute;
  top: 40px;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
}
.pfx-rvt-navpod {
  left: max(72px, calc(50% - 330px));
  gap: 12px;
}
.pfx-rvt-core {
  left: 50%;
  transform: translateX(-50%);
  gap: 24px;
}
.pfx-rvt-loop {
  position: absolute;
  top: 40px;
  left: min(calc(100% - 86px), calc(50% + 236px));
}
.pfx-rvt-btn {
  all: unset !important;
  box-sizing: border-box !important;
  flex: 0 0 auto;
  display: inline-flex !important; align-items: center; justify-content: center;
  width: 34px; height: 34px; padding: 0;
  -webkit-appearance: none !important;
  appearance: none !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  text-shadow: none !important;
  color: var(--rvt-icon) !important;
  font-size: 13px; line-height: 1; cursor: pointer;
  transition: color .12s ease, opacity .12s ease;
  user-select: none !important;
  -webkit-user-select: none !important;
  -webkit-tap-highlight-color: transparent !important;
}
.pfx-rvt-btn:focus,
.pfx-rvt-btn:focus-visible,
.pfx-rvt-btn:active,
.pfx-rvt-btn[role="button"],
.pfx-rvt-btn[aria-disabled="true"] {
  background: transparent !important;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  color: var(--rvt-icon) !important;
}
.pfx-rvt-btn:hover { color: var(--rvt-icon-hot) !important; }
.pfx-rvt-btn.active,
.pfx-rvt-btn.rti-active { color: var(--rvt-red) !important; }
.pfx-rvt-btn.pfx-rvt-loop {
  position: absolute !important;
  top: 40px !important;
  left: min(calc(100% - 86px), calc(50% + 236px)) !important;
}
.pfx-rvt-mini { width: 28px; height: 34px; }
.pfx-rvt-current-hit .pfx-rvt-current { color: var(--rvt-icon-hot) !important; }
.pfx-rvt-empty .pfx-rvt-btn:not([data-act="full"]):not([data-act="prevItem"]):not([data-act="currentItem"]):not([data-act="nextItem"]),
.pfx-rvt-empty .pfx-rvt-scrub {
  opacity: 1;
  cursor: default;
}
.pfx-rvt-btn:disabled,
.pfx-rvt-btn[data-disabled="1"] {
  pointer-events: none;
  color: var(--rvt-icon) !important;
}
.pfx-rvt-play { font-size: 14px; }
.pfx-rvt-time,
.pfx-rvt-btn[data-act="mute"],
.pfx-rvt-btn[data-act="full"] {
  display: none !important;
}
.pfx-rvt-scrub {
  position: absolute;
  left: 0; right: 0; top: 20px;
  width: 100%;
  height: 4px;
  margin: 0;
  cursor: pointer;
  -webkit-appearance: none !important;
  appearance: none !important;
  accent-color: var(--rvt-red) !important;
  background: transparent !important;
  outline: 0 !important;
  border: 0 !important;
}
.pfx-rvt-scrub::-webkit-slider-runnable-track {
  height: 4px;
  background: #30323a !important;
  border-top: 1px solid rgba(0,0,0,.65) !important;
  border-bottom: 1px solid rgba(255,255,255,.08) !important;
}
.pfx-rvt-scrub::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 8px !important;
  height: 22px !important;
  margin-top: -9px !important;
  border-radius: 2px !important;
  background: var(--rvt-red) !important;
  border: 1px solid rgba(0,0,0,.75) !important;
  box-shadow: 0 0 0 1px rgba(255,255,255,.25) inset !important;
}

/* ── Force MONOCHROME (text-style) glyphs on all transport buttons ──────── */
/* macOS renders ⏮ ⏭ ⏹ ⏸ ▶ etc. as colored emoji by default; this makes them
   render as flat monochrome icons (DaVinci Resolve look). */
.imf-tbtn2, .imf-tbtn2-sm, .imf-tbtn-mode,
.cd-vcmp-tbtn, .pm-sly-cmp-tbtn, .pm-vid-ctrl-btn,
.pfx-vfx-plr-btn, .pfx-rvt-btn {
  font-variant-emoji: text !important;
  font-family: "Helvetica Neue", Arial, "Apple Symbols", sans-serif !important;
}
.pfx-rvt-btn svg, .pfx-vfx-plr-btn svg, .imf-tbtn2 svg { width: 14px; height: 14px; display: block; fill: currentColor; }
.pfx-rvt-btn svg { width: 30px !important; height: 30px !important; }
.pfx-rvt-mini svg { width: 26px !important; height: 26px !important; }
.pfx-rvt-current svg { width: 20px !important; height: 20px !important; }

/* ── Resolve SVG transport icons: sizing + monochrome (currentColor) ───── */
.imf-tbtn2 svg, .imf-tbtn2-sm svg, .cd-vcmp-tbtn svg,
.pm-sly-cmp-tbtn svg, .pfx-vfx-plr-btn svg, .pfx-rvt-btn svg,
#pmPrevFrameBtn svg, #pmPlayBtn svg, #pmNextFrameBtn svg {
  width: 15px; height: 15px; display: block;
  fill: currentColor; stroke-width: 0;
  pointer-events: none;
}
/* stroke-based icons (loop, markers, fullscreen) keep their stroke */
.imf-tbtn2 svg[fill="none"], .cd-vcmp-tbtn svg[fill="none"],
.pm-sly-cmp-tbtn svg[fill="none"], .pfx-vfx-plr-btn svg[fill="none"],
.pfx-rvt-btn svg[fill="none"],
#pmPrevFrameBtn svg[fill="none"], #pmPlayBtn svg[fill="none"], #pmNextFrameBtn svg[fill="none"] { fill: none; }
.pfx-rvt-btn svg[fill="none"] {
  fill: none !important;
  stroke: currentColor !important;
  stroke-width: 2.2 !important;
}
.pfx-rvt .pfx-rvt-btn,
.pfx-rvt .pfx-rvt-btn[role="button"],
.pfx-rvt .pfx-rvt-btn[aria-disabled="true"],
.pfx-rvt .pfx-rvt-btn[data-disabled="1"] {
  color: var(--rvt-icon) !important;
}
.pfx-rvt .pfx-rvt-btn:hover { color: var(--rvt-icon-hot) !important; }
.pfx-rvt .pfx-rvt-btn.active,
.pfx-rvt .pfx-rvt-btn.rti-active { color: var(--rvt-red) !important; }
.pfx-rvt .pfx-rvt-btn svg {
  color: inherit !important;
}
.pfx-rvt .pfx-rvt-btn svg[fill="currentColor"],
.pfx-rvt .pfx-rvt-btn svg *[fill="currentColor"] {
  fill: currentColor !important;
}
.pfx-rvt .pfx-rvt-btn svg[stroke="currentColor"],
.pfx-rvt .pfx-rvt-btn svg *[stroke="currentColor"] {
  stroke: currentColor !important;
}

/* ── Transport red active accent (handoff §4/§9): loop-on, play-while-playing ── */
.rti-active { color: #FF3B30 !important; }

/* ── Center the core transport group (Resolve redline layout) ──────────── */
.pcb-core-centered { margin-left: auto !important; margin-right: auto !important; }

/* ── Nav pod [ < • > ] — Resolve-style item navigator ─────────────────────── */
.pfx-nav-pod {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  gap: 2px;
  margin-right: 6px;
  height: 100%;
}
.pfx-nav-dot {
  font-size: 7px !important;
  line-height: 1 !important;
  opacity: 0.65;
  background: rgba(255,255,255,0.06) !important;
  border: none !important;
  border-radius: 50% !important;
  min-width: 18px !important;
  width: 18px !important;
  height: 18px !important;
  padding: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
}
.pfx-nav-dot:hover { opacity: 1; background: rgba(255,255,255,0.14) !important; }

/* ── VFX WS jump extras — smaller, lower contrast ─────────────────────────── */
.pm-vfx-ws-scrub-nav [data-pfx-jump-extra] {
  font-size: 0.72em;
  opacity: 0.55;
  margin: 0 1px;
}
.pm-vfx-ws-scrub-nav [data-pfx-jump-extra]:hover { opacity: 0.9; }

/* ── PULLS PREP nav pod buttons in .pm-controls ────────────────────────────── */
.pm-controls .pfx-nav-dot,
.pm-controls #pmPrevEventBtn,
.pm-controls #pmNextEventBtn {
  font-size: 11px;
  padding: 0 4px;
  margin-right: 2px;
  opacity: 0.7;
}
.pm-controls #pmPrevEventBtn:hover,
.pm-controls #pmNextEventBtn:hover { opacity: 1; }

/* ── Scroll/Scrub jog [ ‹ ● › ] — DaVinci Cut-page leftmost control ─────────── */
.pcb-scrub,
.pcb-navpod {
  flex-direction: column !important;   /* override .pfx-nav-pod row layout */
  gap: 1px !important;
  justify-content: center;
  padding: 2px 8px;
  margin-right: 8px;
  background: var(--hwk-surface-2, #2a2a2a) !important;
  border: 1px solid var(--hwk-border-2, #3a3a3a) !important;
  border-radius: var(--hwk-radius-0, 4px) !important;
  color: var(--hwk-fg, #e8e8e8);
  cursor: default;
  user-select: none;
}
.pcb-scrub-row,
.pcb-navpod-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 7px;
}
.pcb-scrub-arr,
.pcb-scrub-dot,
.pcb-navpod-arr,
.pcb-navpod-dot {
  background: transparent !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  color: inherit !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: none !important;
}
.pcb-scrub-arr,
.pcb-navpod-arr { width: 14px; height: 18px; cursor: pointer; }
.pcb-scrub-dot,
.pcb-navpod-dot { width: 16px; height: 18px; cursor: default; touch-action: none; }
.pcb-scrub-arr:hover,
.pcb-scrub-dot:hover,
.pcb-navpod-arr:hover { color: var(--hwk-fg, #fff) !important; }
.pcb-scrub-dot.pcb-scrubbing { color: var(--hwk-blue400, #4a9eff) !important; }
.pcb-scrub-arr svg,
.pcb-navpod-arr svg { width: 15px; height: 15px; display: block; fill: none; stroke: currentColor; }
.pcb-scrub-dot svg,
.pcb-navpod-dot svg { width: 14px; height: 14px; display: block; fill: currentColor; stroke: none; }
.pcb-scrub-cap {
  font-size: 7px;
  line-height: 1;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--hwk-fg-dim, #777);
  text-align: center;
  pointer-events: none;
}

