/* ╔══════════════════════════════════════════════════════════════════════════╗
   ║  pfxTransport — the single shared media transport (scrub row + buttons).    ║
   ║  Self-contained namespace .pfx-tx-*. Matches the PFXplaycontrol reference.  ║
   ╚══════════════════════════════════════════════════════════════════════════╝ */
.pfx-tx {
  --tx-bg: var(--hwk-surface-2, #1f1f1f);
  --tx-fg: var(--hwk-fg-muted, rgba(255,255,255,.6));
  --tx-fg-hot: var(--hwk-fg, rgba(255,255,255,.92));
  --tx-border: var(--hwk-border, rgba(255,255,255,.12));
  --tx-green: var(--hwk-green, #0AA356);
  --tx-blue: var(--hwk-blue500, #2172E3);
  --tx-loop: var(--pfx-cut-accent, #ff6a00);
  --tx-track: rgba(255,255,255,.14);

  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
  box-sizing: border-box;
  padding: 8px 10px;
  background: var(--tx-bg);
  border: 1px solid var(--tx-border);
  border-radius: 8px;
  user-select: none;
}

/* Scrub row */
.pfx-tx-scrub-row {
  display: grid;
  grid-template-columns: auto minmax(80px, 1fr) auto;
  align-items: center;
  gap: 12px;
}
.pfx-tx-tc {
  font: 700 11px/1 ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  letter-spacing: .02em;
  color: var(--tx-fg);
  white-space: nowrap;
  pointer-events: none;
}
.pfx-tx-tc-dur { text-align: right; }

.pfx-tx-scrub {
  position: relative;
  height: 16px;
  cursor: pointer;
  touch-action: none;
  outline: none;
}
.pfx-tx-scrub-track {
  position: absolute;
  left: 0; right: 0; top: 50%;
  height: 5px;
  transform: translateY(-50%);
  background: rgba(255,255,255,.12);     /* dim unplayed region */
  border-radius: 999px;
}
.pfx-tx-scrub-fill {
  position: absolute;
  left: 0; top: 50%;
  height: 5px;
  width: 0;
  transform: translateY(-50%);
  background: rgba(255,255,255,.80);      /* clearly-filled played region */
  border-radius: 999px;
  transition: background .15s ease;
}
.pfx-tx-scrub.is-playing .pfx-tx-scrub-fill { background: var(--tx-blue); }  /* colour shifts while playing */
.pfx-tx-scrub-thumb {
  position: absolute;
  top: 50%;
  left: 0;
  width: 12px; height: 12px;
  margin-left: -6px;
  transform: translateY(-50%);
  background: var(--tx-fg-hot);
  border: 1px solid rgba(0,0,0,.55);
  border-radius: 50%;
  box-shadow: 0 0 0 1px rgba(255,255,255,.12);
  pointer-events: none;
}
.pfx-tx-scrub:hover .pfx-tx-scrub-thumb,
.pfx-tx-scrub:focus-visible .pfx-tx-scrub-thumb { background: #fff; }
.pfx-tx-scrub:focus-visible { box-shadow: 0 0 0 2px rgba(33,114,227,.5); border-radius: 6px; }

/* Button row */
.pfx-tx-btn-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.pfx-tx-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px; height: 30px;
  padding: 0;
  border: 0 !important;
  border-radius: 6px;
  background: transparent !important;
  color: var(--tx-fg);
  cursor: pointer;
  transition: color .12s ease, background .12s ease;
}
.pfx-tx-btn:hover { background: rgba(255,255,255,.10) !important; color: var(--tx-fg-hot); }
.pfx-tx-btn:active { background: rgba(255,255,255,.06) !important; }
/* Subtle resting box on the main transport buttons (the reference shows boxed
   icons); the nav-pod chevrons stay unboxed inside the pod. */
.pfx-tx-btn-row > .pfx-tx-btn { background: rgba(255,255,255,.05) !important; }
.pfx-tx-btn-row > .pfx-tx-btn:hover { background: rgba(255,255,255,.13) !important; }
.pfx-tx-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px rgba(33,114,227,.55); }
.pfx-tx-btn[disabled] { opacity: .38; cursor: default; pointer-events: none; }
.pfx-tx-btn svg { width: 20px; height: 20px; fill: currentColor; }
/* Defeat the global theme rule `svg:not(.fun-launcher-arrow){color:#blue !important}`
   so transport icons follow the BUTTON color (muted grey, or green/blue per state). */
.pfx-tx .pfx-tx-btn svg,
.pfx-tx .pfx-tx-navpod svg,
.pfx-tx .pfx-tx-navpod-dot svg { color: inherit !important; }

/* Loop sits apart on the right, with a thin divider (reference layout). */
.pfx-tx-loop { margin-left: 18px; position: relative; }
.pfx-tx-loop::before {
  content: ""; position: absolute; left: -10px; top: 50%;
  transform: translateY(-50%); width: 1px; height: 18px;
  background: rgba(255,255,255,.12);
}

/* Color states (toggled by the component) */
.pfx-tx-play.pfx-tx-playing { color: var(--tx-green) !important; }
.pfx-tx-back.pfx-tx-active  { color: var(--tx-blue) !important; }
.pfx-tx-loop.pfx-tx-loop-on { color: var(--tx-loop) !important; background: rgba(255,106,0,.16) !important; }
.pfx-tx-btn.pfx-tx-flash { color: #fff !important; background: var(--tx-blue) !important; }

/* Nav pod [ < o > ] */
.pfx-tx-navpod {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 4px;
  margin-right: 6px;
  background: rgba(0,0,0,.18);
  border: 1px solid var(--tx-border);
  border-radius: 8px;
}
.pfx-tx-mini { width: 26px; height: 24px; border-radius: 5px; }
.pfx-tx-mini svg { width: 15px; height: 15px; }
.pfx-tx-navpod-dot {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px; height: 24px;
  color: rgba(214,214,214,.55);
  pointer-events: auto;        /* jog/scrub: draggable + wheel (see pfxTransport.js) */
  cursor: ew-resize;
  touch-action: none;
}
.pfx-tx-navpod { touch-action: none; }   /* allow wheel-scrub without page scroll */
.pfx-tx-navpod-dot svg { width: 13px; height: 13px; fill: currentColor; }

.pfx-tx-no-play .pfx-tx-play,
.pfx-tx-no-play .pfx-tx-back,
.pfx-tx-no-play .pfx-tx-stop { opacity: .38; }

/* IMF's transport row (.imf-transport-v2) is a fixed ~36px flex row built for the
   old single-row transport; the unified 2-row bar (~72px) overflowed it and the
   button row was clipped. When it hosts the bar, let it grow (block, auto height). */
.imf-transport-v2:has(> .pfx-tx-host) {
  display: block !important;
  height: auto !important;
  min-height: 0 !important;
  max-height: none !important;
  overflow: visible !important;
}

/* Cut Diff 2.0 keeps its own full-width scrubber (#cd2x-vc-scrub) as the single
   long scrub bar — hide the unified bar's own (short, centered) scrub row so there
   is exactly ONE scrub. The unified button row still shows. */
.pfx-tx[data-pfx-tx-name="cutdiff2"] .pfx-tx-scrub-row { display: none; }

/* Combine the Cut Diff control strip: the unified bar normally paints itself as a
   raised rounded pill, which makes it float apart from the compare-mode buttons
   (left) and utility icons (right) that share the same `.cd-vcmp-probar` panel.
   Strip the pill so the transport buttons sit flat in one continuous strip. */
.pfx-tx[data-pfx-tx-name="cutdiff2"] {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  justify-content: center;
}
.pfx-tx[data-pfx-tx-name="cutdiff2"] .pfx-tx-btn-row { background: transparent !important; }

/* ============================================================================
   Cut Diff 2.0 — Home-style reskin
   Re-map Cut Diff's bespoke navy/mixed chrome onto the HOME landing page's
   design language: neutral #161616 surfaces, #2a2e3d borders, 6–8px radii,
   uppercase muted (#4e5a72) section labels, and #2172E3 blue accents. Scoped to
   #main-cutdiff2. cutdiff2 injects its own <style> at runtime (loads after this
   sheet), so overrides use !important. Home tokens are literal hex to match
   src/scripts/features/home/homeScreen.js.
   ============================================================================ */

/* -- Panels / chrome: navy → neutral Home surfaces ------------------------- */
#main-cutdiff2 .cd2x-hdr {
  background: #161616 !important;
  border-bottom: 1px solid #2a2e3d !important;
}
#main-cutdiff2 .cd2x-left-col,
#main-cutdiff2 .cd2x-table-wrap { background: #161616 !important; }
#main-cutdiff2 .cd2x-left-col { border-right-color: #2a2e3d !important; }
#main-cutdiff2 .cd2x-vc-panel {
  background: #0e0e0e !important;
  border-right-color: #2a2e3d !important;
}
/* Transport control strip → a clear neutral gray toolbar (one step lighter than
   the #222 buttons that sit on it, so the controls still read as distinct). */
#main-cutdiff2 .cd-vcmp-probar { background: #2b2b2b !important; }
#main-cutdiff2 .cd2x-kpi-bar {
  background: #161616 !important;
  border-bottom-color: #2a2e3d !important;
