}
#main-cutdiff2 .cd2x-smart-btn {
  background: #222 !important;
  border: 1px solid #2e3447 !important;
  border-radius: 6px !important;
  color: #c8d1e8 !important;
  font-weight: 600 !important;
}

/* -- Compare-mode buttons → Home segmented buttons ------------------------- */
#main-cutdiff2 .cd-vcmp-mode {
  background: #222 !important;
  border: 1px solid #2e3447 !important;
  border-radius: 6px !important;
  color: #c8d1e8 !important;
  font-weight: 500 !important;
}
#main-cutdiff2 .cd-vcmp-mode.is-active {
