  border: 1px solid #2e3447 !important;
  border-radius: 6px !important;
}
#main-cutdiff2 .cd2x-filter-btn.cd2x-filter-active,
#main-cutdiff2 .cd2x-risk-btn.cd2x-risk-active {
  background: #16233a !important;
  border-color: #2172E3 !important;
  color: #e4ebff !important;
}

/* -- KPI stat chips → Home card tiles (keep the semantic left accent) ------ */
#main-cutdiff2 .cd2x-kpi-chip {
