.trc-coach-copy { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.trc-coach-kicker { color: #70aef2; font-size: 9px; font-weight: 800; letter-spacing: .13em; }
.trc-coach-copy strong { color: #f2f6ff; font-size: 15px; line-height: 1.25; }
.trc-coach-copy > span:last-child { color: #aebad5; font-size: 11px; line-height: 1.45; }
.trc-coach-action {
  min-height: 38px;
  padding: 8px 16px;
  border: 1px solid rgba(117, 196, 255, .55);
  border-radius: 9px;
  background: linear-gradient(145deg, #327fe6, #506bea);
  color: #fff;
  font: inherit;
  font-size: 11px;
