}
.trc-nle-workspace-strip > .trc-workspace-tab.is-done { color: #65cfa0; }
.trc-nle-workspace-strip > .trc-workspace-tab.is-done > b { font-size: 0; border-color: rgba(80,208,144,.42); }
.trc-nle-workspace-strip > .trc-workspace-tab.is-done > b::after { content: '\2713'; font-size: 7px; }
.trc-nle-workspace-strip > i { flex: 1; height: 1px; }
.trc-workspace-state {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #53637a;
  font: 750 7px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
