  grid-template-areas:
    "media monitors"
    "engine monitors"
    "timeline timeline"
    "output output";
  gap: 4px;
  min-height: 0;
  padding: 4px 6px 6px;
  overflow: hidden;
}
.trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-panel {
  min-width: 0;
