  display: flex !important;
  min-height: 0 !important;
  order: unset;
}
.trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-panel-match {
  grid-area: engine;
  order: unset;
}
.trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-panel-results {
  grid-area: timeline;
  display: flex;
  min-height: 0;
  order: unset;
}
.trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-panel-export {
  grid-area: output;
  order: unset;
}

/* Media pool uses three stacked bins, like an assistant editor's source panel. */
.trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-input-cards {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr);
