}
.trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-panel-export .trc-opt-check { font-size: 8px; }
.trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-btn-export-xml { min-height: 27px; }

@media (max-width: 1180px) {
  .trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-body {
