  box-shadow: inset 0 -1px rgba(255,255,255,.04);
}
.trc-manual-controls .trc-btn kbd { margin-left: 3px; color: currentColor; }

.trc-panel-pulse { animation: trc-panel-focus-pulse .8s ease-out; }
@keyframes trc-panel-focus-pulse {
  0%, 100% { box-shadow: none; }
  30% { border-color: rgba(77,159,255,.72); box-shadow: 0 0 0 2px rgba(77,159,255,.12), 0 0 18px rgba(77,159,255,.16); }
}

.trc-root.trc-nle-workspace:not(.trc-review-focus) .trc-load-btn {
  min-width: 78px;
  font-size: 9px;
}
