  overflow: hidden;
}
.pm-pro-steps { display: grid; grid-template-columns: repeat(4, minmax(82px, 1fr)); min-width: 0; }
.pm-pro-step {
  position: relative;
  min-width: 0;
  height: 39px;
  display: grid;
  grid-template-columns: 25px minmax(0,1fr);
  grid-template-rows: 18px 13px;
  align-items: center;
