:root {
  --pfx-canvas: #000000;
  --pfx-surface-0: #0b0b0b;
  --pfx-surface-1: #141414;
  --pfx-surface-2: #181818;
  --pfx-surface-3: #232323;
  --pfx-border: rgba(255,255,255,.11);
  --pfx-border-strong: rgba(255,255,255,.2);
  --pfx-text: #f5f5f1;
  --pfx-text-2: #b3b3b3;
  --pfx-text-3: #737373;
  --pfx-primary: #e50914;
  --pfx-primary-hover: #f6121d;
  --pfx-primary-soft: rgba(229,9,20,.14);
  --pfx-success: #46d38f;
  --pfx-success-soft: rgba(70,211,143,.12);
  --pfx-warning: #e2b656;
  --pfx-warning-soft: rgba(226,182,86,.12);
  --pfx-danger: #ff5f6d;
  --pfx-danger-soft: rgba(255,95,109,.12);

  /* Compatibility map for older workspaces. */
  --hwk-canvas: var(--pfx-canvas);
  --hwk-surface: var(--pfx-surface-1);
  --hwk-surface-2: var(--pfx-surface-2);
  --hwk-fg: var(--pfx-text);
  --hwk-fg-muted: var(--pfx-text-2);
  --hwk-fg-subtle: var(--pfx-text-3);
  --hwk-border: var(--pfx-border);
  --hwk-border-2: var(--pfx-border-strong);
  --hwk-blue500: var(--pfx-primary);
  --hwk-blue400: var(--pfx-primary-hover);
  --hwk-green: var(--pfx-success);
  --hwk-yellow: var(--pfx-warning);
  --hwk-red: var(--pfx-danger);
  --accent: var(--pfx-primary);
  --focus-ring: var(--pfx-primary);
  --focus-ring-soft: rgba(229,9,20,.2);
  --glass-bg: rgba(20,20,20,.96);
  --glass-bg-2: rgba(24,24,24,.96);
  --glass-stroke: var(--pfx-border);
  --glass-stroke-2: var(--pfx-border-strong);
}

