/* ==========================================================================
   PULL PREP — SMART MARKER TASK CARD 2026.08
   One compact decision row replaces the always-open production form. Detailed
   metadata, QC, handoffs and notes appear only when the editor asks for them.
   ========================================================================== */
#main-prepmark .pm-ve-shot-control {
  max-height: 84px;
  overflow: hidden;
  transition: max-height .16s ease;
}
#main-prepmark .pm-ve-shot-control.is-details-open {
  max-height: 232px;
  overflow: auto;
}
#main-prepmark .pm-ve-shot-head {
  min-height: 30px;
  grid-template-columns: minmax(175px, auto) auto minmax(140px, 1fr);
  padding: 3px 8px;
}
#main-prepmark .pm-ve-smart-row {
  min-height: 39px;
  display: grid;
  grid-template-columns: minmax(118px, .72fr) auto minmax(180px, 1.35fr) auto;
  align-items: center;
  gap: 6px;
  padding: 3px 8px 5px;
  background: linear-gradient(180deg, #111, #0d0d0d);
}
#main-prepmark .pm-ve-stage {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 5px;
}
#main-prepmark .pm-ve-stage > span {
  color: #737373;
  font-size: 6px;
  font-weight: 850;
  letter-spacing: .08em;
  text-transform: uppercase;
}
#main-prepmark .pm-ve-stage select {
  width: 100%;
  min-width: 0;
  height: 27px;
  padding: 2px 6px;
  border: 1px solid #363636;
  border-radius: 4px;
  background: #181818;
  color: #e7e7e4;
  font-size: 7px;
  outline: none;
}
#main-prepmark .pm-ve-stage select:focus { border-color: #e50914; }
#main-prepmark .pm-ve-progress {
  display: flex;
  align-items: center;
  gap: 3px;
}
#main-prepmark .pm-ve-progress > span {
  height: 25px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 7px;
  border: 1px solid #333;
  border-radius: 999px;
  background: #171717;
  color: #858585;
  font-size: 6px;
  font-weight: 800;
  white-space: nowrap;
}
#main-prepmark .pm-ve-progress > span b { color: #d4d4d2; font-size: 7px; }
#main-prepmark .pm-ve-progress > span.is-complete {
  color: #46d38f;
  border-color: rgba(70, 211, 143, .35);
  background: rgba(70, 211, 143, .06);
}
#main-prepmark .pm-ve-next-task {
  min-width: 0;
  height: 29px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 7px;
  padding: 2px 9px;
  border: 1px solid #353535;
  border-radius: 5px;
  background: #191919;
  color: #d7d7d4;
  text-align: left;
  cursor: pointer;
}
#main-prepmark .pm-ve-next-task small {
  color: #737373;
  font-size: 6px;
  font-weight: 850;
  letter-spacing: .08em;
  white-space: nowrap;
}
#main-prepmark .pm-ve-next-task b {
  min-width: 0;
  overflow: hidden;
  color: #f5f5f1;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
#main-prepmark .pm-ve-next-task.needs-attention {
  border-color: rgba(229, 9, 20, .52);
  background: linear-gradient(90deg, rgba(229, 9, 20, .14), #181818 52%);
