#main-prepmark .pm-ve-next-task.needs-attention small { color: #ff747b; }
#main-prepmark .pm-ve-details-toggle {
  height: 29px;
  padding: 0 9px;
  border: 1px solid #353535;
  border-radius: 5px;
  background: #181818;
  color: #a8a8a5;
  font-size: 7px;
  cursor: pointer;
}
#main-prepmark .pm-ve-details { display: none; border-top: 1px solid #282828; }
#main-prepmark .pm-ve-details.is-open { display: block; }
#main-prepmark .pm-ve-fields-secondary {
  grid-template-columns: .66fr .92fr 1fr 1fr;
}

@media (max-width: 1450px) {
  #main-prepmark .pm-ve-smart-row {
    grid-template-columns: minmax(108px, .7fr) auto minmax(150px, 1fr) auto;
  }
