  #main-prepmark .pm-ve-progress > span b { font-size: 7px; }
}

/* ==========================================================================
   DESKTOP TITLEBAR — SMART UTILITY CLUSTER
   One calm command surface for Help, tools, account and language. The controls
   keep their existing DOM and behaviour; this layer only improves hierarchy.
   ========================================================================== */
html[data-pfx-env="desktop"] .titlebar-actions {
  position: relative;
  height: 30px;
  padding: 3px 4px;
  gap: 3px !important;
  border: 1px solid rgba(255, 255, 255, .10);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(31, 31, 34, .98), rgba(17, 17, 19, .98));
  box-shadow:
    0 6px 18px rgba(0, 0, 0, .28),
    inset 0 1px 0 rgba(255, 255, 255, .055);
  isolation: isolate;
}

html[data-pfx-env="desktop"] .titlebar-actions::before {
  content: "";
  position: absolute;
  inset: -1px auto -1px -1px;
  width: 3px;
  border-radius: 10px 0 0 10px;
  background: linear-gradient(180deg, #ff3945, #b20710);
  box-shadow: 2px 0 10px rgba(229, 9, 20, .20);
  pointer-events: none;
}

html[data-pfx-env="desktop"] .titlebar-actions > button,
html[data-pfx-env="desktop"] .titlebar-actions .pfx-global-tutorial-btn,
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab,
html[data-pfx-env="desktop"] .titlebar-actions .pfx-user-btn,
html[data-pfx-env="desktop"] .titlebar-actions .lang-switch {
  height: 24px !important;
  min-height: 24px !important;
  border: 1px solid transparent !important;
  border-radius: 7px !important;
  background: transparent !important;
  box-shadow: none !important;
  color: rgba(245, 245, 241, .72) !important;
  transition:
    color .14s ease,
    background-color .14s ease,
    border-color .14s ease,
    transform .14s ease !important;
}

html[data-pfx-env="desktop"] .titlebar-actions > button:hover,
html[data-pfx-env="desktop"] .titlebar-actions .pfx-global-tutorial-btn:hover,
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab:hover,
html[data-pfx-env="desktop"] .titlebar-actions .pfx-user-btn:hover,
html[data-pfx-env="desktop"] .titlebar-actions .lang-switch:hover {
  color: #fff !important;
  background: rgba(255, 255, 255, .075) !important;
  border-color: rgba(255, 255, 255, .075) !important;
}

html[data-pfx-env="desktop"] .titlebar-actions > button:active,
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab:active,
html[data-pfx-env="desktop"] .titlebar-actions .pfx-user-btn:active {
  transform: translateY(1px) !important;
}

html[data-pfx-env="desktop"] .titlebar-actions button:focus-visible,
html[data-pfx-env="desktop"] .titlebar-actions select:focus-visible {
  outline: 2px solid rgba(71, 164, 255, .82) !important;
  outline-offset: 1px !important;
}

/* Help is a single, friendly entry point rather than another boxed button. */
html[data-pfx-env="desktop"] #btnTutorial {
  padding: 0 9px !important;
  gap: 6px !important;
  font-size: 9px !important;
  letter-spacing: .025em !important;
}
html[data-pfx-env="desktop"] #btnTutorial svg {
  width: 13px;
  height: 13px;
  color: #68a9ff;
  filter: drop-shadow(0 0 5px rgba(67, 143, 255, .28));
}

/* A hairline separates navigation/help from the two workspace drawers. */
html[data-pfx-env="desktop"] .titlebar-actions .top-aux {
  margin-left: 1px;
  padding-left: 5px;
  border-left: 1px solid rgba(255, 255, 255, .09);
}
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tabs {
  gap: 2px;
  overflow: visible;
  border: 0 !important;
  border-radius: 8px !important;
  background: transparent !important;
}
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab {
  padding: 0 8px !important;
  gap: 5px !important;
  font-size: 9px !important;
  letter-spacing: .025em !important;
}
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab + .top-aux-tab {
  border-left-color: transparent !important;
}
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab::before {
  width: 13px !important;
  height: 13px !important;
  flex-basis: 13px !important;
  opacity: .86;
}
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab-toolbox:hover,
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab-toolbox.active {
  color: #8bc8ff !important;
  border-color: rgba(78, 165, 255, .18) !important;
  background: rgba(61, 142, 232, .11) !important;
}
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab-funbox:hover,
html[data-pfx-env="desktop"] .titlebar-actions .top-aux-tab-funbox.active {
  color: #d8a0ff !important;
  border-color: rgba(185, 101, 255, .18) !important;
  background: rgba(155, 73, 222, .11) !important;
}

/* Account + locale form a quiet identity zone at the end of the cluster. */
html[data-pfx-env="desktop"] .titlebar-actions .pfx-user-badge {
  margin-left: 2px !important;
  padding-left: 6px;
  border-left: 1px solid rgba(255, 255, 255, .09);
}
html[data-pfx-env="desktop"] .titlebar-actions .pfx-user-btn {
  padding: 0 7px 0 4px !important;
  gap: 5px !important;
}
html[data-pfx-env="desktop"] .titlebar-actions .pfx-user-avatar-wrap,
